\subsection{Extended analysis}
\label{sec:nesterov-2}
As studied by~\citet{chambolle2015convergence,aujol2024strong} for upper-bounds on the convergence rates for convex functions, we consider the same recursion as in \eq{nesterov-1}, but now with $\tau_k =   2\rho /(k+2\rho-1)$,
leading to for $k \geqslant 1$,
\BEA
\label{eq:nesterov-2}
 \theta_{k+1}  &  = &  ( \idm - \gamma H) \bigg[  \theta_{k} + \Big( 1 - \frac{ 2\rho  }{k+2\rho-1} \Big) ( \theta_{k} - \theta_{k-1}) \bigg] \\
\notag &  = &  ( \idm - \gamma H) \bigg[  2   \frac{ k+\rho-1 }{k+2\rho-1}    \theta_{k} - 
  \frac{ k -1 }{k+2\rho-1}  \theta_{k-1} \bigg] .
\EEA
This exactly extends the case $\rho=1$ treated earlier. We now have for  any $k \geqslant 1$:
\BEAS
(k+2\rho - 1)\theta_{k+1} & = & 
 ( \idm - \gamma H) \big[  2  (  k+\rho-1)     \theta_{k} - 
 (k - 1)   \theta_{k-1} \big]\\
 (k+1)\theta_{k+1} + 2 (\rho-1) \theta_{k+1} & = & 
 ( \idm - \gamma H) \big[  2 k \theta_k  - 
 (k-1)\theta_{k-1} + 2 (\rho-1)  \theta_k   \big].
\EEAS


Multiplying by $z^k$ and summing for $k \geqslant 1$, this leads to the following ODE, since $\Theta'(z) = \sum_{k=1}^{+\infty} k z^{k-1} \theta_k$,
$$
\Theta'(z) - \theta_1
+ 2 (\rho-1) \frac{1}{z} \big[ \Theta(z) - \theta_0 - z \theta_1\big]  = ( \idm - \gamma H) \big[
 (2z - z^2) \Theta'(z) + 2 (\rho-1)( \Theta(z) - \theta_0 )
\big],
$$
that is, since $\theta_1=\theta_0$,
$$
\big[ \idm - (2z -z^2)  ( \idm - \gamma H) \big] \Theta'(z)  + 2 ( \rho-1 ) \big[\Theta(z) - \theta_0 \big]
\Big[ \frac{1}{z} \idm - ( \idm - \gamma H) \Big]
=    (2 \rho-1)  \theta_1.
$$
With  $B(0,\lambda)=1$ and
\BEQ
\label{eq:perf-nesterov-2}
a_k = \frac{1}{2} \theta_k^\top H \theta_k = \int_0^1
b_k(\lambda)^2
d\sigma(\lambda),
\EEQ
we get an ordinary differential equation for $B(z,\lambda)$:
\BEQ
\label{eq:nesterov-22} \big[ 1 - (2z -z^2)  ( 1 - \lambda) \big]  B'(z,\lambda)  + 2 (\rho-1)  [ B(z,\lambda)-1]
\cdot \Big[ \frac{1}{z}   - ( 1-\lambda) \Big]
=    ( 2\rho-1).
\EEQ
It cannot be integrated in closed form, but the following lemma shows that it leads to a simple expression for a specific derivative (see proof in Appendix~\ref{app:lemma:nest-2}).

\begin{lemma}
\label{lemma:nest-2}
If $B$ satisfies \eq{nesterov-22}, then $D(z,\lambda) = z^{2\rho-2} ( B(z,\lambda) - 1 ) $ satisfies
$$
D^{(2\rho-1)}(z,\lambda)  = \frac{ (2\rho-2)!}{ ((1-z)^2(1-\lambda) + \lambda)^\rho}
.$$
\end{lemma}




Our goal is thus to compute an equivalent of
$$
C(z) = \frac{ 1}{ (  (1-z)^2  (1-\lambda)  + {\lambda})^\rho}
* \frac{ 1}{ (  (1-z)^2  (1-\lambda)  + {\lambda})^\rho},
$$
and then multiply the obtained equivalent of the associated sequence $(c_k)_{k \geqslant 0}$ by $[ (2\rho-1)!]^2 k^{2 - 4\rho}$. In order to obtain a formula for $C$, we rely on the following identities:
\BEAS
\frac{ 1}{ (  (1-z)^2 (1-\lambda) + {\lambda})^\rho}
& = &\frac{(-1)^{\rho -1}}{(\rho-1)!}   \frac{\partial^{\rho-1}}{\partial \alpha^{\rho-1}} \Big( \frac{ 1}{      (1-z)^2 (1-\lambda)  + {\lambda + \alpha}} \Big) \Big|_{\alpha =0}
\EEAS
leading to, using the bi-linearity of the derivative operator,
\BEAS
& & \frac{ 1}{ (  (1-z)^2  (1-\lambda) + {\lambda})^\rho}
* \frac{ 1}{ (  (1-z)^2  (1-\lambda) + {\lambda})^\rho} \\
& = & \frac{1}{(\rho-1)!^2} 
\frac{\partial^{2\rho-2}}{\partial \alpha^{\rho-1}\partial \beta^{\rho-1}} \Big( \frac{ 1}{     (1-z)^2  (1-\lambda) + {\lambda} + \alpha} *  \frac{ 1}{      (1-z)^2 (1-\lambda)  + {\lambda} + \beta }\Big) \Big|_{\alpha,\beta =0}.
\EEAS
Moreover, using explicit calculations for rational functions described in Appendix~\ref{app:conv},
this allows us to get a rational function in $z$ and $\lambda$. We can then perform asymptotic calculations of the $z$-transform around $z=1$. This leads to the following conjecture.

\begin{conjecture}[Nesterov acceleration, $\rho \in \mathbb{N}$]
\label{conj:nesterov-2}
Assume \textbf{(A1)} obtained from Lemma~\ref{lemma:GD}. Then for the sequence defined in \eq{nesterov-2} and in \eq{perf-nesterov-2}, we have:
$$
a_k \sim c \frac{\Gamma(2 \rho)^2}{\Gamma(\rho)^2} \cdot \left\{
\begin{array}{ll}
  \ds \frac{\Gamma(\rho-\omega) \Gamma(\omega)}{\Gamma(4\rho-1-2\omega)}  
 \frac{\Gamma(2\rho-1/2-\omega)}{\Gamma(\rho+1/2-\omega)}
 \frac{2^{2\rho-1}}{4^\omega }  \cdot \frac{1}{k^{ 2\omega}} & \mbox{ if } \omega \in (0,\rho)\\[.3cm]
 \ds  \frac{1}{2^{2\rho-1}} \frac{ \log k}{k^{2\rho}} & \mbox{ if } \omega = \rho
\\[.3cm]
\ds   \frac{1}{2^{2\rho-1}}   \Gamma(\omega-\rho) \frac{1}{k^{\omega+\rho}}  & \mbox{ if } \omega > \rho.
\end{array}
\right.
$$
\end{conjecture}
As partial proof, we do not provide a proof of the Tauberian conditions and only focus on the asymptotic expansion of the $z$-transform.
With Mathematica\footnote{See Mathematica notebook {\url{https://www.di.ens.fr/~fbach/ztf/nesterov_rho.nb}}.}, we checked the conjecture with symbolic computations for all integers $\rho$ less than $8$ (where the $z$-transform $C(z)$ already has 45 terms), for $\omega = \rho$ (logarithmic behavior), for $\omega \in (\rho-1,\rho)$, and $\omega \in (\rho,\rho+1)$ to check the three behaviors. We also conjecture (and checked empirically by running simulations) that Conjecture~\ref{conj:nesterov-2} is true for all $\rho>0$ (not necessarily integer). See Figure~\ref{fig:nestrho}.


