\end{center}

\vspace*{-.5cm}

\caption{Nesterov acceleration with multiple $\rho$'s with $\omega=3$: true performance $a_k$ vs. potential asymptotic equivalent  $\bar{a}_k$.
\label{fig:nestrho}}
