\paragraph{Heavy-ball recursion.}
The corresponding heavy ball recursion for general $\rho$ can be taken to be 
\BEAS \theta_{k+1}  &  = &    \Big( \idm - \frac{k}{k+2\rho-1} \gamma H\Big)  \theta_{k} + \Big( 1 - \frac{ 2\rho  }{k+2\rho-1} \Big) ( \theta_{k} - \theta_{k-1}),
 \EEAS
 with a recursion that is asymptotically equivalent to that of~\cite{berthier2020accelerated}, as outlined by~\citet{berthier2022acceleration}, who show, in the context of gossip algorithms, an asymptotic equivalence with a partial differential equation. 
 Using similar derivations as for Nesterov acceleration, we can get an equation for $\Theta$ as 
 $$
 c(z) \Theta'(z) + 2(\rho-1) \Big[ \frac{c(z)}{z}  - \frac{c'(z)}{2} \Big] \cdot \big[ \Theta(z) - \theta_0 \big]
 = (2\rho-1) \theta_0,
 $$
 with $c(z) = \idm - (2\idm - \gamma H)z + z^2 \idm$, instead of $c(z) = \idm - (2z - z^2)(\idm - \gamma H)$.
Similar developments could then be carried out, with a similar potential lack of Tauberian conditions (and not full equivalence).


\section{Additive noise}
\label{sec:additivenoise}
 The $z$-transform method can also be used efficiently in the presence of additive noise in the recursion. We consider in this section two examples: gradient descent and Nesterov acceleration from \mysec{nesterov-1}.


 \subsection{Gradient descent}
 \label{sec:sgd-noise}
 The recursion in \eq{GDrec} now becomes
 $$
 \theta_k = ( \idm - \gamma H) \theta_{k-1} + \varepsilon_{k},
 $$
 with $\varepsilon_k$ a random vector with zero mean and covariance matrix $\Sigma$. For simplicity, we assume that all noise vectors are independent with the same covariance matrix, but the same technique could be applied with a time-varying covariance matrix, leading to ordinary differential equations (if the time variation is rational).

 Unrolling the recursion leads to 
 $$
\theta_k = ( \idm - \gamma H)^k \theta_0 + \sum_{i=1}^k ( \idm - \gamma H)^{k-i} \varepsilon_i,
$$
with the performance being in expectation equal to
$$
\frac{1}{2}\E \big[ \langle \theta_k,  H \theta_k \rangle \big]
=  \frac{1}{2}\langle \theta_0, ( \idm - \gamma H)^{2k} H \theta_0 \rangle + \frac{1}{2}
\sum_{i=1}^k \tr \big( H( \idm - \gamma H)^{2k-2i} \E [ \varepsilon_i\varepsilon_i^\top] \big).
$$
With a constant covariance matrix $\Sigma$, we get 
\BEQ
\label{eq:GDnoise}
a_k = \E \big[ \langle \theta_k,  H \theta_k \rangle \big]
=  \frac{1}{2}\langle \theta_0, ( \idm - \gamma H)^{2k} H \theta_0 \rangle +  \frac{1}{2}
\sum_{i=0}^{k-1}  \tr \big( \Sigma H( \idm - \gamma H)^{2i}  \big).
\EEQ
We can compute the $z$-transform of $(a_k)_{k \geqslant 0}$ as follows:
\BEAS
\sum_{k=0}^{+\infty}
a_k z^k & = & \frac{1}{2}\sum_{k=0}^{+\infty} \langle \theta_0, ( \idm - \gamma H)^{2k} H  \theta_0 \rangle z^k
+  \frac{1}{2}\sum_{k=1}^{+\infty}
\sum_{i=0}^{k-1} z^k  \tr \big( \Sigma H( \idm - \gamma H)^{2i}  \big)\\
& = &  \frac{1}{2}\sum_{k=0}^{+\infty} \langle \theta_0, ( \idm - \gamma H)^{2k} H \theta_0\rangle z^k
+ \frac{1}{2}\sum_{i=0}^{+\infty}   \sum_{k=i+1}^{+\infty}
z^k  \tr \big( \Sigma H( \idm - \gamma H)^{2i}  \big)
\\
& = & \frac{1}{2} \sum_{k=0}^{+\infty}\langle \theta_0, ( \idm - \gamma H)^{2k} H  \theta_0 \rangle z^k
+  \frac{1}{2}\frac{z  }{1-z}
 \sum_{i=0}^{+\infty}  z^i  \tr \big( \Sigma H( \idm - \gamma H)^{2i}  \big).
\EEAS
This can decomposed into the eigenvectors $u_i \in \H$ of $H$, that is,
\BEAS
A(z)  & = & \frac{1}{2} \sum_{i=0}^{+\infty} \sum_{k=0}^{+\infty} ( 1 - \gamma \lambda_i )^{2k} \lambda_i   z^k
\big[ \langle \theta_0, u_i \rangle^2   + \frac{z  }{1-z} \langle u_i, \Sigma u_i \rangle \big].
\EEAS
Classically in stochastic quadratic optimization, the performance decomposes into two terms, one that corresponds to the deterministic recursion, which we will call the ``bias'' term, and one that corresponds to the noise, which we will call the ``variance'' term.

\paragraph{Bias term.} This is exactly the term from \mysec{GD} with an equivalent obtained in Proposition~\ref{prop:gd}, and is proportional to $1/k^{\omega}$ where $\omega > 0$, with constants obtained from Lemma~\ref{lemma:GD}.


\paragraph{Variance term.} For this term, we make an assumption on the noise covariance matrix $\Sigma$ of a similar form as in Lemma~\ref{lemma:GD}, to obtain the variance term (together with assumptions on $H$).

\begin{proposition}[Variance term for noisy gradient descent]
Assume $\lambda_i = \frac{\gamma L}{i^\alpha}$ for $\alpha>1$, and $\langle u_i, \Sigma u_i \rangle = \frac{\sigma^2}{i^{\beta'}}$ 
where $(\lambda_i,u_i)_{i \geqslant 1}$ are eigenvalues and eigenvectors of $H$. When $\theta_0=0$, the sequence $(a_k)_{k \geqslant 0}$ defined in \eq{GDnoise}, satisfies, with $\omega' = \frac{\beta'-1}{\alpha} + 1$ and $c' = \frac{L \sigma^2}{2 \alpha (\gamma L)^{\omega'}}$:
$$
a_k \sim  \left\{
\begin{array}{ll}
  \ds \frac{c'}{2^{\omega'}}  \frac{ \Gamma(\omega')  \Gamma(1-\omega')}{ \Gamma(2-\omega')}  {k^{1-\omega'}} & \mbox{ if } \omega' \in (0,1), \\[.3cm]
  \ds \frac{1}{\gamma}\tr  \big( \Sigma   ( 2   - \gamma H )^{-1} \big)  = \frac{\sigma^2}{\gamma} \sum_{i\geqslant 1} 
  \frac{1}{2  - \gamma \lambda_i}
  & \mbox{ if } \omega'>1 .
 \end{array}
\right.
$$
\end{proposition}
\begin{proof}
We can apply Lemma~\ref{lemma:discrete}, and get the constants $\omega'$ and $c'$, and then the desired equivalents by using Assumption \textbf{(A1)}. When $\omega' \in (0,1)$, we obtain a $z$-transform proportional to $(1-z)^{\omega'-2}$ and thus the equivalent proportional to $ \frac{1}{k^{\omega'-1}}$. When $\omega' >1$, then we obtain a $z$-transform proportional to $1/(1-z)$, and a limit for $a_k$.
\end{proof}

Two possible values of $\beta'$ correspond to two classical cases in optimization:
\BIT
\item Isotropic noise ($\beta'=0$): this leads to  and equivalent proportional to $k^{1/\alpha}$. We thus see that isotropic noise will lead to a blow-up of the performance in infinite dimensions; note that this is not contradicting non-asymptotic bounds~\citep[Lemma 2]{bach2013non}, which typically have the term $\tr(\Sigma)$.
 \item Least-squares regression ($\beta'=1)$: this corresponds to the noise covariance matrix $\Sigma$ being proportional to $H$ \citep[see][for an in-depth discussion]{dieuleveut2017harder}. Then $\omega' =  2 - 1/\alpha \in (1,2)$ if $\alpha > 1$ (which is standard to have $H$ with finite trace). Then, the variance term tends to a constant. 
\EIT


\subsection{Nesterov acceleration}
We consider the Nesterov-type iteration, as done by \citet{flammarion2015averaging}, with extra additive noise, leading to the following recursion instead of \eq{nesterov-1}:
\BEA
\label{eq:nesterov-noisy} \theta_{k+1}  &  = &  ( \idm - \gamma H) \Big[  \theta_{k} + \Big( 1 - \frac{ 2  }{k+1} \Big) ( \theta_{k} - \theta_{k-1}) \Big]  + \varepsilon_{k+1} ,
\EEA
initialized with $\theta_1 = \theta_0$, with i.i.d.~noise with zero mean and covariance matrix $\Sigma$.

Following \citet{flammarion2015averaging}, we extend the computations from \mysec{nesterov-1}: the equivalent iteration for  $\xi_k = k \theta_{k}$ is 
$$
\xi_{k+1} = ( \idm - \gamma H) ( 2\xi_k - \xi_{k-1}) + (k+1) \varepsilon_{k+1},
$$ 
with $\xi_0 = 0$, $\xi_1 = \theta_0$, and now a noise variable which is amplified by the factor $k+1$. Using the same reasoning as in \mysec{nesterov-1}, we get
$$
\Xi(z) - z\theta_0 =  (2z - z^2) ( \idm - \gamma H) 
\Xi(z) + \sum_{k=1}^{+\infty} z^{k+1} (k+1) \varepsilon_{k+1},$$
leading to
$$
  \Xi(z) = z \big[ \idm - (2z - z^2) ( \idm - \gamma H) \big]^{-1} \Big[
 \theta_0 + \sum_{k=1}^{+\infty} z^{k} (k+1) \varepsilon_{k+1}
\Big]
= z c(z)^{-1} \Big[
\theta_0 + \sum_{k=1}^{+\infty} z^{k} (k+1) \varepsilon_{k+1}
\Big]
,
$$
with $c(z) =  \idm - (2z - z^2) ( \idm - \gamma H) $.
We thus get, for any eigenvector $u_i$ of $H$, and $c_i(z) = 1 - (2z - z^2)(1 - \gamma h_i)$,
\BEAS
&& \E \Big[
  \langle  \Xi(z), u_i\rangle  *   \langle \Xi(z), u_i \rangle
\Big] \\
& = & \langle u_i ,\theta_0 \rangle^2  \big( \frac{z}{c_i(z)} *  \frac{z}{c_i(z)}  \big)
+ z \sum_{k=1}^{+\infty}  (k+1) ^2 \E[ \langle \varepsilon_{k+1}, u_i \rangle^2\big] \big(  \frac{z^k}{c_i(z)}  *  \frac{z^k}{c_i(z)}  \big)
\\
& = & \langle u_i ,\theta_0 \rangle^2   \big(  \frac{z}{c_i(z)}  *   \frac{z}{c_i(z)}  \big)
+ \sum_{k=1}^{+\infty}  (k+1) ^2 z^k \E[ \langle \varepsilon_{k+1}, u_i \rangle^2\big]   \big(  \frac{z}{c_i(z)}  *   \frac{z}{c_i(z)} \big) \\
& = & \Big[
 \langle u_i ,\theta_0 \rangle^2 + \langle u_i, \Sigma u_i \rangle 
 \sum_{k=1}^{+\infty}  (k+1) ^2 z^k 
\Big] \big( \frac{z}{c_i(z)}  *   \frac{z}{c_i(z)}  \big).
\EEAS
Here have used that
$ ( z^k A(z)) * ( z^k B(z)) =   z^k \cdot (A*B)(z)$. The final $z$-transform of the performance of $\xi_{k+1}$ can then be derived with two terms. As for gradient descent, we have a bias term (which corresponds to the absence of noise, that is, Proposition~\ref{prop:nesterov-1}) and a variance term corresponding to the $z$-transform  
$$
 \Big[\langle u_i, \Sigma u_i \rangle 
 \sum_{k=1}^{+\infty}  (k+1) ^2 z^k 
\Big] \big(  \frac{z}{c_i(z)}  *   \frac{z}{c_i(z)} ) \sim   
 \frac{2}{(1-z)^3} \langle u_i, \Sigma u_i \rangle 
 \big( \frac{z}{c_i(z)}  *   \frac{z}{c_i(z)}  \big).
$$
This leads to the following proposition.
\begin{proposition}[Variance term for noisy Nesterov acceleration]
Assume $\lambda_i = \frac{\gamma L}{i^\alpha}$ for $\alpha>$, and $\langle u_i, \Sigma u_i \rangle = \frac{\sigma^2}{i^{\beta'}}$ 
where $(\lambda_i,u_i)_{i \geqslant 1}$ are eigenvalues and eigenvectors of $H$. When $\theta_0=0$, for the sequence $(\theta_k)_{k \geqslant 0}$ defined in \eq{nesterov-noisy}, we have, with $\omega' = \frac{\beta'-1}{\alpha} + 1$ and $c' = \frac{L \sigma^2}{2 \alpha (\gamma L)^{\omega'}}$:
$$
\frac{1}{2} \langle \theta_k, H \theta_k \rangle \sim c' \cdot  \left\{
\begin{array}{ll}
  \ds \frac{\Gamma(1-\omega') \Gamma(\omega')}{\Gamma(6-2\omega')} {4^{1-\omega'}}    k^{ 3-2\omega'} 
 & \mbox{ if } \omega' \in (0,1), \\[.3cm]
  \ds \frac{\Gamma(2-\omega')}{\Gamma(5-\omega')}\frac{\Gamma(\omega')}{\omega'-1} k^{ 2-\omega'} 
  & \mbox{ if } \omega' \in (1,2) .
 \end{array}
\right.
$$
\end{proposition}
\begin{proof}
 When $\omega' \in (0,1)$, we obtain from  \eq{proof-nest1} in the proof of Proposition~\ref{prop:nesterov-1}, that $\sum_{i \geqslant 1} \langle u_i, \Sigma u_i \rangle 
 \big( \frac{z}{c_i(z)} *   \frac{z}{c_i(z)} \big)$ has an equivalent proportional to $(1-z)^{2\omega'-3}$, leading to the impact on the noise of $\frac{1}{k^2} \times k^3 \times k^{ 3-2\omega'- 1} \sim  k^{ 3-2\omega'} $. 

 When $\omega' >1 $, we obtain from  \eq{proof-nest2} in  the proof of Proposition~\ref{prop:nesterov-1}, that $\sum_{i=1}^{+\infty} \langle u_i, \Sigma u_i \rangle 
 \big( \frac{z}{c_i(z)}  *  \frac{z}{c_i(z)}  \big)$ has an equivalent proportional to  $(1-z)^{\omega'-2} $, leading to the impact on the noise of $\frac{1}{k^2} \times k^3 \times k^{2- \omega' -1 } \sim k^{ 2-\omega'}$.
\end{proof}

Using the same cases as in \mysec{sgd-noise}, we get asymptotic versions of results from~\citet{flammarion2015averaging}; see experiments in Fig.~\ref{fig:nesterovnoise}:
\BIT
\item Isotropic noise ($\beta'=0$): this corresponds to $\omega' = 1-1/\alpha \in (0,1)$. We then obtained an impact on the noise proportional to $k^{ 1 + 2/\alpha}$ (so diverging even more than gradient descent).

\item Noise corresponding to least-squares regression ($\beta'=1$): this corresponds to $\omega' = 2-1/\alpha \in (1,2)$. We then obtained the equivalent $k^{ 1/\alpha}$, which is still exploding, but more slowly. \EIT

