\section{Convolutions of rational functions}
\label{app:conv}

In this section, we compute convolutions $A \ast B(z)$ for rational functions $A$ and $B$, starting from $$
\frac{1}{a- uz} * \frac{1}{b- vz} = \frac{1}{ab- uvz},
$$
which is a direct consequence of the $z$-transform of the sequence $( a^{-1} ( u a^{-1})^k)_{k \geqslant 0}$ being $z \mapsto \frac{1}{a- uz}$.

\paragraph{Unique multiple roots.} Since convolutions are bilinear operations, we can differentiate with respect to $a$ $k$ times and to $b$ $\ell$ times to get, using the Leibniz formula:\footnote{See \url{https://en.wikipedia.org/wiki/General_Leibniz_rule}.}
\BEAS
\frac{(-1)^k k! }{(a- uz)^{k+1}} * \frac{(-1)^\ell \ell! }{(b- vz)^{\ell+1}} 
& \!\!\!= \!\!\!& \frac{d^{k+\ell}}{d a^k db^\ell} \Big( \frac{1}{ab- uvz} \Big)
=  \frac{d^{k}}{d a^k} \Big( \frac{(-1)^\ell \ell! a^\ell}{(ab- uvz)^{\ell+1}} \Big)
\\
&\!\!\! = \!\!\!&(-1)^\ell \ell!  \sum_{i=0}^{\min\{k,\ell\}} \frac{k!}{i! (k-i)!} \Big[  \frac{\ell!}{(\ell-i)!} a^{\ell-i} \Big]
\cdot \Big[ \frac{(k+\ell-i)! b^{k-i}}{\ell!} \frac{(-1)^{k-i} }{(ab- uvz)^{\ell+k+1-i}} \Big],
\EEAS
leading to
$\displaystyle
\frac{1}{(a- uz)^{k+1}} * \frac{1 }{(b- vz)^{\ell+1}} 
= \sum_{i=0}^{\min\{k,\ell\}} (-1)^{i}\frac{(k+\ell-i)! }{i! (k-i)! (\ell-i)!}   \frac{  a^{\ell-i}   b^{k-i} }{(ab- uvz)^{\ell+k+1-i}}.
$

\paragraph{Quadratic denominators.}
We will also need convolutions of rational functions with quadratic denominators, that is, by using complex conjugate roots and bi-linearity,
\BEA
\notag \frac{1}{ (1-z)^2 + \lambda }
* \frac{1}{ (1-z)^2 + \mu } 
& \!\!\!= \!\!\!& \frac{-1}{4 \sqrt{\lambda\mu}}\Big(
\frac{1}{1-z -i \sqrt{\lambda}}
-\frac{1}{1-z +i \sqrt{\lambda}}
\Big) \ast \Big(
\frac{1}{1-z -i \sqrt{\mu}}
-\frac{1}{1-z +i \sqrt{\mu}}
\Big) \\
\notag&\!\!\! = \!\!\!&\frac{1}{4 \sqrt{\lambda\mu}}\Big(
\frac{1}{(1-i \sqrt{\lambda})(1+i \sqrt{\mu}) - z}
+
\frac{1}{(1+i \sqrt{\lambda})(1-i \sqrt{\mu}) - z}
\Big) 
\\
\notag& & -  \frac{1}{4 \sqrt{\lambda\mu}}\Big(
\frac{1}{(1-i \sqrt{\lambda})(1-i \sqrt{\mu}) - z}
+
\frac{1}{(1+i \sqrt{\lambda})(1+i \sqrt{\mu}) - z}
\Big) \\
\notag& \!\!\!= \!\!\!&  \frac{1}{2\sqrt{\lambda \mu}} \bigg(
\frac{1+ \sqrt{\lambda\mu} - z}{( 1+ \sqrt{\lambda \mu} - z)^2 + ( \sqrt{\lambda} - \sqrt{\mu})^2}
-\frac{1- \sqrt{\lambda\mu} - z}{( 1- \sqrt{\lambda \mu} - z)^2 + ( \sqrt{\lambda} + \sqrt{\mu})^2}
\bigg)\\
\label{eq:quadden}& \!\!\!= \!\!\!& 
\frac{ (\lambda+1)(\mu+1) - z^2}{( ( 1-z)^2 + \lambda \mu +\lambda + \mu)^2 - 4\lambda \mu z^2}.
\EEA




  \section{Proof of Proposition~\ref{prop:nesterov-1}}
  \label{app:nesterov-1}
We use convolution formulas obtained from \eq{quadden} in Appendix~\ref{app:conv}, with $B(z,\lambda)
=  \frac{1}{(1-\lambda) (1-z)^2 + \lambda }
$ defined in \eq{Bnest}. We obtain several expressions depending on the choice of partial function decomposition for the convolution $A(z) = B(z,\lambda) 
* B(z,\lambda)$:\footnote{See Mathematica notebook {\url{https://www.di.ens.fr/~fbach/ztf/nesterov.nb}}.}



\BEA
\notag A(z) &\!\!\! =\!\!\!&   \frac{1}{ (1-\lambda) (1-z)^2 + \lambda }
* \frac{1}{ (1-\lambda) (1-z)^2 + \lambda } \\
\notag &\!\!\! = \!\!\!& \frac{-\lambda  z+z+1}{((\lambda -1) z+1) \left((\lambda -1)^2 z^2+\left(-4 \lambda ^2+6 \lambda -2\right) z+1\right)} \mbox{ (no expansion)}\\
  \label{eq:nestzroot}&\!\!\! = \!\!\!& \frac{1}{2 (-1+\lambda ) \lambda  \big(-1+z-\frac{\lambda }{1-\lambda }\big)}+\frac{1}{4 (1-\lambda ) \lambda  \big(-1+z+\frac{\lambda
}{1-\lambda }-2 i \sqrt{\frac{\lambda }{1-\lambda }}\big)} \\
\notag & & \hspace*{3cm} +\frac{1}{4 (1-\lambda ) \lambda  \big(-1+z+\frac{\lambda }{1-\lambda }+2 i \sqrt{\frac{\lambda
}{1-\lambda }}\big)}  \mbox{ (expansion in $z$)}. 
\\
 \label{eq:nestlambdaroot}&\!\!\! = \!\!\!&\frac{z}{2 \left(\sqrt{z}-1\right) \left(\sqrt{z}+1\right) (\lambda  z-z+1)}+\frac{-\sqrt{z}-2}{4 \left(\sqrt{z}+1\right) \left(\lambda  \left(z+2 \sqrt{z}\right)-z-2 \sqrt{z}-1\right)} \\
 \notag & & \hspace*{3cm} +\frac{2-\sqrt{z}}{4 \left(\sqrt{z}-1\right) \left(\lambda  \left(z-2 \sqrt{z}\right)-z+2 \sqrt{z}-1\right)}
 \mbox{ (expansion in $\lambda$)}. 
\EEA

Starting with \eq{nestlambdaroot} (partial function expansion in $\lambda$), we obtain directly an expression in terms of the \sti transform, as
\BEA
\label{eq:Alo} A(z) & =  &\frac{S\left(\frac{1}{z}-1\right)}{2 (z-1)}-\frac{S\Big(-\frac{\left(\sqrt{z}-1\right)^2}{z-2 \sqrt{z}}\Big)}{4 \left(z-\sqrt{z}\right)}-\frac{S\Big(-\frac{\left(\sqrt{z}+1\right)^2}{z+2 \sqrt{z}}\Big)}{4 \left(z+\sqrt{z}\right)},
\EEA
with the following equivalent when $z \to 1$:
\BEA
\label{eq:Aloc} A(z)
&\sim & \frac{S(1-z)}{2 (z-1)}-\frac{S\left(\frac{1}{4} (z-1)^2\right)}{2 (z-1)}-\frac{1}{8} S\Big(-\frac{4}{3}\Big).
\EEA
\eq{Aloc} will lead to expansions of the $z$-transform $A(z)$ and its derivatives, thus characterizing the asymptotic equivalent if it exists.

In order to show the Tauberian condition in Theorem~\ref{theorem:gamma}, we consider instead the expression in \eq{nestzroot} (partial function expansion in $z$), and find the corresponding sequences from the $z$-transform, which is the sum of three terms that decompose $a_k$ as the sum of
$$
-\int_0^1 \frac{1}{2\lambda} ( 1 - \lambda)^k d\sigma(\lambda)
\mbox{ and } \int_0^1 \frac{1}{\lambda} b(\lambda) r(\lambda)^k d\sigma(\lambda)
$$
with $r(\lambda) \in \mathbb{C}$ with $|r(\lambda)| = 1-\lambda$, and $|b(\lambda)| = \frac{1}{4}$  (with two occurences). The first term will always lead to a Tauberian condition because it is decreasing. In order to bound $|a_k - a_{k-1}|$ for the other terms, we need to bound
\BEQ
\label{eq:akk}
|a_k - a_{k-1} | \leqslant \int_0^1 |b(\lambda)|  |r(\lambda)|^k d\sigma(\lambda)
= \frac{1}{4} \int_0^1 (1-\lambda)^k d\sigma(\lambda) ,
\EEQ 
and check that it is small enough. Since the right hand side is a decreasing sequence, we can apply Abel's theorem and we compute from \eq{sti} the $(j-1)!$-th order derivative of its $z$-transform for $j>\omega$, which is of order $(1-z)^{\omega - j}$, this leads to an upper bound of order $O(\frac{1}{k^{\omega+1}})$.

 We now divide into several cases, where we provide the desired equivalent of $A$ and show the Tauberian condition.


\paragraph{Case $\omega \in (0,1)$.} We have the equivalent for the \sti transform from \eq{sti}
$$
S(u) \sim    c \Gamma(1-\omega) \Gamma(\omega) u^{\omega -1}
$$
and thus
we get the equivalent from \eq{Aloc}
$$A(z) \sim
 c \Gamma(1-\omega) \Gamma(\omega)  \Big[
 - \frac{1}{2} (1-z)^{\omega-2} 
 + \frac{1}{2} \frac{1}{4^{\omega-1}} (1-z)^{2\omega - 3}
 \Big],
$$
which is equivalent to (since the second term dominates)
\BEQ
\label{eq:proof-nest1}
A(z) \sim
 c \Gamma(1-\omega) \Gamma(\omega)   
 \frac{1}{2} \frac{1}{4^{\omega-1}} (1-z)^{2\omega - 3}.
\EEQ
From Theorem~\ref{theorem:gamma} (applied with $\alpha=3 - 2 \omega$), this leads to the potential equivalent for $a_k$, equal to
$\ds 
a_k \sim  c \Gamma(1-\omega) \Gamma(\omega)   
 \frac{1}{2} \frac{1}{4^{\omega-1}} \cdot \frac{k^{2-2\omega}}{\Gamma(3-2\omega)},
 $
 (which then leads to the desired result). We only need to show that we can upper bound \eq{akk} by $k^{\alpha-2} = k^{1-2 \omega}$, which is true since it is $O(k^{-1-\omega})$. 

\paragraph{Case $\omega \in (1,2)$.} We have from \eq{sti} an equivalent for the derivative of the \sti transform:
 $$
S'(u) \sim - c  \Gamma(2-\omega) \Gamma(\omega)  u^{\omega - 2 },
$$
leading by integration to
$$
S(u) = S(0) - c  \Gamma(2-\omega) \Gamma(\omega) \frac{u^{\omega - 1 }}{\omega - 1} + o(u^{\omega - 1 }) 
.$$
Thus, only the first two terms in \eq{Aloc} dominate, with the value $S(0)$ cancelling out, leading to
\BEQ
\label{eq:proof-nest2}
A(z) \sim
 -c \frac{\Gamma(2-\omega) \Gamma(\omega) }{\omega-1} \Big[
 - \frac{1}{2} (1-z)^{\omega-2} 
 + \frac{1}{2} \frac{1}{4^{\omega-1}} (1-z)^{2\omega - 3}
 \Big] \sim  c \frac{\Gamma(2-\omega) \Gamma(\omega) }{\omega-1}  
  \frac{1}{2} (1-z)^{\omega-2} .
\EEQ
 This leads to the equivalent $\ds a_k \sim  c \frac{\Gamma(2-\omega) \Gamma(\omega) }{\omega-1}  
  \frac{1}{2} \cdot \frac{k^{1-\omega}}{\Gamma(2-\omega)}
  =  \frac{c}{2}  \Gamma(\omega-1)
   k^{1-\omega},$ which leads to the desired result. We then apply Theorem~\ref{theorem:gamma} with $\alpha=2 -  \omega$.


\paragraph{Case $\omega >  2$.} We simply have to obtain the same equivalent as above, and take derivatives with respect to $z$ of \eq{Alo}. It can be easily checked that the dominant term still corresponds to the term
$\frac{S\left(\frac{1}{z}-1\right)}{2 (z-1)}$, and that it leads to the same equivalent.

\paragraph{Case $\omega = 1$.} We have from \eq{sti} $S'(u) \sim - c u^{-1}$, leading to by integration $S(u) \sim c \log \frac{1}{u}$ around $u=0$. The first two terms of \eq{Aloc} then both contribute and lead to $A(z) \sim \frac{c}{2(1-z)}\log \frac{1}{1-z}$, and \eq{log} allows to conclude. 



\section{Proof of Lemma~\ref{lemma:nest-2}}

\label{app:lemma:nest-2}
  Multiplying by $z^{2\rho-2}$, \eq{nesterov-2} is equivalent to
$$ z^{2\rho-2} \big[ 1 - (2z -z^2)  ( 1 - \lambda) \big]  B'(z,\lambda)  + 2 (\rho-1) z^{2\rho-3} [ B(z,\lambda)-1]
\cdot  [ 1   - z ( 1-\lambda) ]
=    ( 2\rho-1) z^{2\rho-2}.
$$
Denoting $D(z,\lambda) = z^{2\rho-2} ( B(z,\lambda) - 1 ) $, and $c(z) =  1 - (2z -z^2)  ( 1 - \lambda) $, we get
$c'(z) = -2(1-z) (1-\lambda)$ and:
$$ c(z) D'(z,\lambda) - (\rho-1) c'(z) D(z,\lambda) =    ( 2\rho-1) z^{2\rho-2}.
$$
Taking $2\rho-1$ derivatives, and using Leibniz formula, we get:
\BEAS
   c(z) D^{(2\rho)}(z,\lambda) + (2\rho-1 ) c'(z)D^{(2\rho-1)}(z,\lambda) 
+  (2\rho-1)(\rho-1) c''(z)D^{(2\rho-2)}(z,\lambda) 
\\
 - (\rho-1) c'(z) D^{(2\rho-1)}(z,\lambda)  - (\rho-1) (2\rho -1) c''(z) D^{(2\rho-2)}(z,\lambda) & = & 0.
\EEAS
Thus
$$   c(z) D^{(2\rho)}(z,\lambda) + \rho c'(z)D^{(2\rho-1)}(z,\lambda) 
=0,
$$
leading to $\ds  c(z)^\rho D^{(2\rho-1)}(z,\lambda)  = \alpha(\lambda),$
for some function $\alpha$. Looking at $z=0$, we have $c(0) = 1$, and
$D^{(2\rho-1)}(0,\lambda)=(2\rho-2)!$, leading to
the desired result.

