\section{Preliminaries}
\subsection{Control barrier functions}



%%
We assume that the dynamics of the systems we consider in this paper are control-affine. 
\begin{definition}[Control-affine systems]
    A nonlinear control-affine system can be modeled  using an ordinary differential equation (ODE) of the form:
    \begin{equation}\label{eq:system}
        \dot{x} = f(x) + g(x)u,
    \end{equation}
    where \( x(t) \in \mathcal{X} \subseteq \mathbb{R}^n \) represents the state, and \( u(t) \in \mathcal{U} \subseteq \mathbb{R}^m \) denotes the control input at time \( t \). The functions \( f: \mathcal{X} \to \mathbb{R}^n \) and \( g: \mathcal{X} \to \mathbb{R}^{n \times m} \) are assumed to be locally Lipschitz continuous.
\end{definition}

\begin{definition}[Control barrier functions~\citep{cbf_overview_2018}]
    A function \( B: \mathcal{X} \to \mathbb{R} \) is a \emph{control barrier function} for system \eqref{eq:system} if it is continuously differentiable and satisfies:
    \begin{align}
        \exists u \in \mathcal{U} \text{ such that } \dot{B}(x,u) + \gamma (B(x)) \geq 0,  \quad \forall x \in \mathcal{D} \subseteq \mathcal{X}, \label{eq:cbf-def-cond-ascent}
    \end{align}
   where the super-level set \( B_{\geq 0} := \{x \ |\ B(x) \geq 0\} \) satisfies \( B_{\geq 0} \subseteq \mathcal{D} \), and \( \gamma: \mathbb{R} \to \mathbb{R} \) is a locally Lipschitz extended class-\( \mathcal{K}_{\infty} \) function, meaning it is strictly increasing and satisfies \( \gamma(0) = 0 \).
\end{definition}
%%
A CBF $B$ for system~(\ref{eq:system}) specifies the controls  that guarantee the {\em forward invariance} of $B_{\geq 0}$. That means that all the trajectories that start in $B_{\geq 0}$ and follow control signals that satisfy (\ref{eq:cbf-def-cond-ascent}) at all time instants, remain 
within it 
at all times, as stated in the following theorem. If the set of unsafe states is disjoint from $B_{\geq 0}$ and the system starts from states in $B_{\geq 0}$, then the system can be kept safe by following such controls. 


\begin{theorem}[\citep{cbf_overview_2018}]
Any Lipschitz continuous control policy  
\( \pi: \mathcal{D} \to \mathcal{U} \) satisfying  
\[
\forall x \in \mathcal{D},\ \pi(x) \in K_{\cbf} := \{u \in \mathcal{U} \mid \nabla B(x)(f(x) + g(x)u) + \gamma(B(x)) \geq 0\}
\]
makes the set \( B_{\geq 0} \) forward invariant.  
\end{theorem}

Given a reference controller \( \pi_{\text{ref}}: \mathcal{X} \to \mathcal{U} \) that does not necessarily satisfy safety constraints, a safety filter using the CBF \( B \) can be employed to modify its unsafe control choices. Specifically, a quadratic program (QP) can be formulated to determine the closest safe control to \( \pi_{\text{ref}}(x) \) \cite{ames2016control}, resulting in what is usually denoted by a CBF-QP policy $\pi_{\text{safe}}$, as shown below:  
%%
\begin{equation}\label{eq:qp}
    \begin{aligned}
    \pi_{\text{safe}}(x) &:= \arg\min_{u \in \mathcal{U}} \lVert u - \pi_{\text{ref}}(x) \rVert^2\quad %\\
        s.t. \quad \nabla B(x)(f(x) + g(x)u) + \gamma(B(x)) \geq 0. 
    \end{aligned}
\end{equation}
