\section{Introduction}

This paper focuses on a multi-dimensional  backward stochastic differential equation (BSDE)
	\begin{equation}\label{eq1}
	Y_{t} = \xi + \int_{t}^{T}H(s,\,Y_{u},\,Z_{u}) \ du - \int_{t}^{T}Z_{u} \ dW_{u}, \quad t \in [0,\, T],
	\end{equation}
where $W = (W^{1},\,\dots,\,W^{d})$ denotes a standard $ d $-dimensional Brownian motion defined on a filtered probability space
$(\Omega,\, \mathcal{F},\, (\mathcal{F}_{s})_{s \in [0, \, T]}, \mathbb{P})$. Here, $(\mathcal{F}_{s})_{s \in [0, \, T]}$ is the $\mathbb{P}$-completion of the filtration generated by $W$. The terminal condition $ \xi $ is an $ \mathcal{F}_{T}$-measurable $ \mathbb{R}^{n} $-valued random variable and the generator $H: [0, T] \times \Omega \times \mathbb{R}^{n} \times \mathbb{R}^{n\times d} \mapsto \mathbb{R}^{n} $ is a progressively measurable process. When $ n = 1 $, nonlinear BSDEs are pioneered under the Lipschitz condition by \citep{Peng1990}.  
BSDEs with generators that exhibit quadratic growth in regards to the variable $ z $ have been extensively researched by articles \citep{BriandHu2006, BriandHu2008, Tevzadze2008, 2013Monotone, BriandRichou2017} and others since \citep{Kobylanski2000} first investigated the situation of  bounded terminal conditions. This paper characterizes a specific category of BSDEs with the form of generators being $f(y)|z|^{2}$, which first appeared in \citep{DuffieEpstein1992} to our knowledge. 
 This paper characterizes a specific category of BSDEs with the form of generators given by $g(y)\lvert z \rvert^{2}$, which to our knowledge first appeared in \citep{DuffieEpstein1992}. 
By employing It\^o-Krylov's formula as well as a ``domination method''derived from the existence result for reflected BSDEs obtained in \citep{Essaky2011}, 
\citep{Bahlali2017} demonstrated existence and uniqueness results when $g$ is globally integrable on $\mathbb{R}$. Another intriguing case is $f(y,\, z)=|z|^{2}/y$, meaning that the generator $ f $ is singular at $ y=0 $. In this instance, \citep{Bahlali2018} assumed that the generator $ f $ satisfies
	\begin{equation}
	0 \leq f(s,\,\omega,\,y,\, z) \leq a_{s}+b_{s} y+\gamma_{s} z+\frac{\delta}{2y}\lvert z \rvert^{2},\, (s,\,\omega,\,y,\, z) \in [0,\, T]\times \Omega \times (0,\, +\infty) \times  \mathbb{R}^{1 \times d},
	\end{equation}
for some processes $ a,\, b,\, \gamma $, and a constant $ \delta $. By utilizing the domination method, they established the existence of solutions in $ \mathcal{S}^{p} \times \mathcal{L}^{2} $. Furthermore, they proved a uniqueness result for bounded solutions using techniques from convex duality.  Subsequently, many researchers has extended this work, such as \citep{Yang2017, Zheng2017, Tian2023, Zheng2024}.
This paper extends the result in \citep{Bahlali2018} to multi-dimensional BSDEs with diagonally quadratic generators and unbounded terminal conditions following the method in \citep{Fan2023}.


\section{Notations and Existence Results}\label{sec2}

This section establishes the existence results. Firstly, we need to introduce the notations used in this paper. We say a process or random variable satisfies some property if this holds except on the empty subset. Thus we sometimes omit \as. $ \mathbb{E}_{t} \left[  \cdot \right] := \mathbb{E}\left[  \cdot \mid \mathcal{F}_{t} \right] $ denotes the conditional mathematical expectation with respect to $ \mathcal{F}_{t} $. The set composed of stopping times $ \tau $ satisfying $ 0\le \tau \le T $ is represented by  $ \mathcal{T}_{0,T}  $. If $ N $ is an adapted and c\`adl\`ag process, define $ N^{\ast} := \sup_{t \in [0,T]} \lvert N_{t} \rvert $. For a matrix $ z=(z_{ij}) $, $z^{i}$ denotes the $i$-th row of $z$, and $ z' $ denotes the transpose of $ z $. We denote its norm by $\lvert z \rvert =\sqrt{\sum_{ij}\lvert z_{ij} \rvert^{2}}.$ The sign function is defined to be $ sgn(y) = \mathds{1}_{ \{y>0\} } - \mathds{1}_{ \{y \le 0\} }$. Let $ \mathbf{0}_{n \times d} $ represent the $ n \times d $ zero matrix and $\mathbf{1}_{n}$ denote the $ n $-dimensional all-ones vector. We recall that class $ (D) $ comprises progressively measurable processes $ X $ satisfying that $\{ X_{\tau}\mid \tau \in \mathcal{T}_{0,\,T} \}$ is uniformly integrable. Sometimes we denote by $ \mathscr{E}(X) $ the stochastic exponential of a one-dimensional local martingale $ X $ and denote by $ Z \cdot W $ the process $ (\int_{0}^{t} Z_{s} dW_{s})_{t \in [0,T]}.$ Given $p\geq 1$ and open sets $ U \subset \mathbb{R},\,V \subset \mathbb{R}^{n} $, let us define the following spaces and notations.

$\mathcal{C}^{p}(U)$: the space of functions from $U $ to $ \mathbb{R}$ having continuous p-th derivative.

$\mathcal{S}:=\mathcal{S}(\mathbb{R}^{n}) $, the space of adapted and continuous processes valued in $ \mathbb{R} $.


$ \mathbb{L}^{p}:= \mathbb{L}^{p}(\Omega, \mathcal{F}_{T}, \mathbb{P}; \mathbb{R}) $, the space of $ \mathcal{F}_{T}$-measurable random variables $\eta$ valued in $ \mathbb{R}$ such that $\mathbb{E}\left[\lvert \eta\rvert ^{p}\right] < \infty.$
%

$\mathcal{S}^{\infty}:= \mathcal{S}^{\infty}(\mathbb{R}^{n}) $, the space of all $ Y \in \mathcal{S}$ such that $\lVert Y \rVert_{\mathcal{S}^{\infty}} := \esssup\limits_{(\omega,t)}\lvert Y_{t}(\omega) \rvert < \infty.  $

$\mathcal{S}^{p}:= \mathcal{S}^{p}(\mathbb{R}^{n}) $, the space of all processes $Y\in \mathcal{S}$ such that $\lVert Y \rVert_{\mathcal{S}^{p}}:=\left(  \mathbb{E}[\sup\limits_{0 \le t \le T}\lvert Y_{t}\rvert ^{p}]\right)^{\frac{1}{p}} < \infty $. 

$\mathcal{L}^{2}:=\mathcal{L}^{2}(\mathbb{R}^{n\times d})$, the space of $\mathbb{R}^{n\times d}$-valued processes $N$ satisfying $N$ is progressively measurable and a.s. $ \int^{T}_{0}|N_{s}|^{2}ds < \infty. $

$\mathcal{M}^{p}:= \mathcal{M}^{p}(\mathbb{R}^{n\times d})$, the space of progressively measurable processes $G$ fulfilling that $G$ is valued in $\mathbb{R}^{n\times d}$ and $\lVert G \rVert_{\mathcal{M}^{p}}:=\left(  \mathbb{E}\left[\left(\int^{T}_{0}\lvert G_{s}\rvert ^{2}ds\right)^{p/2}\right]\right)^{1/p} < + \infty $. $Z \in \mathcal{M}(\mathbb{R}^{n\times d}) $ means that $Z \in \bigcap\limits_{p\ge1} \mathcal{M}^{p}(\mathbb{R}^{n\times d}).$

$BMO(\mathbb{R}^{n\times d})$: the space of all $ N \in \mathcal{M}^{2}$ satisfying \[ \lVert N \rVert_{BMO}: = \sup\limits_{\tau \in \mathcal{T}_{0,T }}\big\lVert \mathbb{E}\Big[ \int_{\tau}^{T}\lvert  N_{s}\rvert^{2} ds   \big| \mathcal{F}_{\tau} \Big]\big\rVert^{\frac{1}{2}}_{\infty} \! < \infty .\]
We note that for $ N \in BMO(\mathbb{R}^{n\times d}) $, the process $ N\cdot W $ is an $ n $-dimensional $ BMO $ martingale.

We sometimes describe the BSDE with generator $ H $ and terminal $ \xi $ as BSDE$ (\xi, H) $ rather than \myeqref{eq1} for notational simplicity.
A solution of BSDE$ (\xi, H) $ is defined as a pair of processes $(Y,\,Z):=\{(Y_{t},\,Z_{t})\}_{t \in [0,T]}  \in \mathcal{S} \times \mathcal{L}^{2} $ fulfilling that \as, \myeqref{eq1} holds and $ \int_{0}^{T} \lvert  g(u,\,Y_{u},\,Z_{u})\rvert  du < \infty $. Furthermore, we designate $ (Y,\,Z) := \{(Y_{t},\,Z_{t})\}_{t \in [0,T]}$ as a $ L^{p} $ solution provided that $ (Y,\,Z) \in \mathcal{S}^{p}\times  \mathcal{M}^{q}$ for some $ p>1,\,q>1 $. A solution $ (Y,\,Z) $ to BSDE$ (\xi, H) $  is said to be positive if each component of $ Y= (Y^{1},\,\dots,\,Y^{n}) $ satisfies $ Y^{i} > 0,\,i = 1\,\dots,\,n. $

Now we establish the existence theorem for BSDE \myeqref{eq1} under the following assumption:

\noindent {\textbf (H1)} There exist nonnegative and progressive measurable processes $\alpha,\,\beta$, nonnegative constants $A,\,\delta $ with $\delta \neq 1$, and scalar generators
$H^{i}_{1} : [0,\,T] \times \Omega \times \mathbb{R}^{n} \to \mathbb{R}$, and $H^{i}_{2} : [0,\,T] \times \Omega \times \mathbb{R} \times \mathbb{R}^{1\times d} \to \mathbb{R}$, $i =1,\,2,\,\dots,\,n,$ such that 
\begin{itemize}
	\item 
$ H=(H^{1},\,H^{2},\,\dots,\,H^{n}).$ For any $(s,\,\omega,\,y,\,z) \in [0,\,T] \times \Omega \times \mathbb{R}^{n} \times \mathbb{R}^{1\times d}$, and $i =1,\,2,\,\dots,\,n$, $H^{i}(s,\,\omega,\,y,\,z) = H_{1}^{i}(s,\,\omega,\,y) + H_{2}^{i}(s,\,\omega,\,y^{i},\,z^{i})$;
	\item for each $i,\,H^{i}_{1} $ is nonnegative, of linear growth in $y$, and uniformly Lipschitz continuous in $y$,  that is, \as, for all $s \in [0,\,T],\,y,\,y^{1},\,y^{2} \in \mathbb{R}^{n} $,
	\[0 \le H_{1}^{i}(s,\,y)  \le A \left( 1 + \lvert y\rvert \right),\text{ and }\lvert H_{1}^{i}(s,\,y^{1}) - H_{1}^{i}(s,\,y^{2}) \vert \le A \lvert y^{1} - y^{2} \rvert;\]
	\item \as, for each $ i $ and any $ s\in [0,\,T], $ $(y,\,z) \to H_{2}^{i}(s,\,\omega,\,y,\,z) $ is continuous and convex on $ \mathbb{R} \times \mathbb{R}^{1\times d}$;
	\item \as, for each $ i $ and any $(s,\,y,\,z) \in [0,\,T] \times (0,\,+\infty) \times \mathbb{R}^{1\times d}$,	\[0 \le  H_{2}^{i}(s,\,\omega,\,y,\,z) \le \alpha_{s} + \beta_{s} y + \frac{\delta}{2y}\lvert z \rvert^{2}.\]
\end{itemize}

\noindent {\textbf(H2)} $ \xi = (\xi^{1},\,\xi^{2},\,\dots,\,\xi^{n})$ satisfies that $ \xi^{i} > 0,\,i =1,\,2,\,\dots,\,n $. For some constants $ p \ge 2 $ and $ q > 1 $, \[\mathbb{E}\left[ \left(\frac{1}{ \xi^{i} } \right)^{q}\right]<+\infty,\,i =1,\,2,\,\dots,\,n,\,\mathbb{E}\left[ \left(1+\lvert \xi \rvert^{2+\delta}+\int_{0}^{T} \alpha^{2+\delta}_{s} ds\right)^{p}e^{p(2+\delta)\int_{0}^{T}\beta_{s}  d s } \right]<+\infty. \]


\begin{theorem}\label{mainresult}
	Assume (H1) and (H2) hold. Then BSDE \myeqref{eq1} admits a unique solution $ (Y,\,Z) $ such that $ (Y,\,Z) \in \mathcal{S}^{p(2+\delta)}(\mathbb{R}^{n}) \times \mathcal{M}^{p}(\mathbb{R}^{n\times d})$. Moreover, $ (Y,\,Z) $ is a positive solution.	
\end{theorem}

\begin{Corollary}\label{corollary}
Assume (H1) holds with processes $ \alpha $ and $ \beta $ are bounded. Assume also that $ \xi = (\xi^{1},\,\xi^{2},\,\dots,\,\xi^{n})$ is bounded and $ \xi^{i} > 0,\,i =1,\,2,\,\dots,\,n.$ For some constant $ q > 1 $, $\mathbb{E}\left[ \left(\frac{1}{ \xi^{i} } \right)^{q}\right]<\infty.$ Then BSDE \myeqref{eq1} admits a unique solution $ (Y,\,Z) $ such that $ Y\in \mathcal{S}^{\infty}(\mathbb{R}^{n})$ and $Z \in BMO(\mathbb{R}^{n \times d}).$
\end{Corollary}

The corollary follows immediately by applying It\^o's formula to $ e^{Mt}\lvert Y_{t}\rvert^{2} $ for some appropriate constant $ M $, so we omit its proof. To prove \sref{Theorem}{mainresult}, we introduce the follwing lemma, and more general cases can be found in  \citep{Yang2017}.
	\begin{lemma} \label{lemma1}
Consider the following one dimensional BSDE
		\begin{equation} \label{eq2}
		Y_{t}=\zeta  + \int_{t}^{T} g(s,\,\omega,\,	Y_{s},\,Z_{s})    d s-\int_{t}^{T} Z_{s} d W_{s},\,1 \le t \le T.
		\end{equation}
		Assume that $ \zeta >0 $, $ g $ is continuous in $ (y, z) $ for each fixed $ (s,\,\omega),$ and there exist nonnegative and progressively measurable processes $ a,\,b$, and a nonnegative constant $ \delta$, such that for any $(s,\,\omega,\,y,\,z) \in [0,\,T] \times \Omega \times (0,\,+\infty) \times \mathbb{R}^{1\times d}$,
	\[0 \le g(s,\,\omega,\,y,\,z) \le a_{s} + b_{s} y  + \frac{\delta}{2y}\lvert z \rvert^{2}.\]


	\begin{enumerate}
	\item If $ (Y,\,Z) $ is a positive solution of \myeqref{eq2} such that \[ \mathbb{E}\left[\left( \sup\limits_{0 \le t \le T}  Y_{t}^{2+\delta}  + \int_{0}^{T}a^{2+\delta}_{r}\ d r\right) e^{(2+\delta)\int_{0}^{T} b_{u} d u}  \right]< +\infty,\] then
	\[ e^{(1+\delta)t+(2+\delta)\int_{0}^{t} b_{u} d u}Y_{t}^{2+\delta} \le  \mathbb{E}\left[ e^{(1+\delta)T+(2+\delta)\int_{0}^{T} b_{u} d u}\zeta^{2+\delta} + \int_{t}^{T} e^{(1+\delta)s+(2+\delta)\int_{0}^{s} b_{u} d u}a^{2+\delta}_{s} \ d s\mid \mathcal{F}_{t}\right]. \]
	\item If $\delta \neq 1,\, (Y,\,Z) $ is a positive solution of \myeqref{eq2} such that \[\mathbb{E}\left[ \sup\limits_{0 \le s \le T}  Y_{s} ^{p(2+\delta)} +  \left(\int_{0}^{T}a_{s}  d s \right)^{p} +  \left(\int_{0}^{T}b_{s}  d s \right)^{p} \right] <+\infty \text{ for some }p > 1, \]  then
	\[
	\mathbb{E}\left[\left(\int_{0}^{T} \lvert Z_{u}\rvert ^{2} d u\right)^{\tfrac{p}{2}}\right] \leq  C+C\mathbb{E}\left[ \sup_{0 \le s \le T}  Y_{s} ^{p(2+\delta)} +  \left(\int_{0}^{T}a_{s}  d s \right)^{p}+ \left(\int_{0}^{T}b_{s}  d s \right)^{p} \right],
	\]	 where $ C $ is a constant depends on $ p,\,\delta,$ and $T. $
	\item If $\delta \neq 1,\,g(s,\,\omega,\,\cdot,\,\cdot) $ is convex in $(y,\,z)$ for each $s,$ \as, and for some $ p > 1 $, 
	\[\mathbb{E}\left[ \left(1 + \zeta^{2+\delta} + \int_{0}^{T} a^{2+\delta}_{r}\ d r\right)^{p}e^{p(2+\delta)\int_{0}^{T} b_{s}d s}\right] < +\infty,\]
	then the BSDE \myeqref{eq2} admits a unique solution $\left(Y,\, Z\right) \in \mathcal{S}^{p(2+\delta)}(\mathbb{R}) \times \mathcal{M}^{p}(\mathbb{R}^{1\times d}).$ Moreover,
	\[\mathbb{E}\left[ \sup\limits_{0 \le t \le T}  Y_{t} ^{p(2+\delta)}e^{p(2+\delta)\int_{0}^{t} b_{s}d s}\right] \le C \mathbb{E}\left[ \left(\zeta^{2+\delta} + \int_{0}^{T} a^{2+\delta}_{r}\ d r\right)^{p}e^{p(2+\delta)\int_{0}^{T} b_{s}d s}\right], \]
	where $ C > 0 $ is a contant depending on $ \delta,\,T,$ and $ p. $
\end{enumerate}
	\end{lemma}
\begin{proof}[Proof of \sref{Theorem}{mainresult}.]

	For any given $ (V,\,N) \in \mathcal{S}^{p(2+\delta)}(\mathbb{R}^{n}) \times \mathcal{M}^{p}(\mathbb{R}^{n\times d}) $ such that \[\mathbb{E}\left[ \left( \int_{0}^{T} \lvert V_{r} \rvert^{2+\delta}\ d r\right)^{p}e^{p(2+\delta)\int_{0}^{T} \beta_{s}d s}\right] < +\infty, \]  consider the following system of BSDEs:
	\begin{equation} \label{eq3}
y_{t}^{i} = \xi^{i} + \int_{t}^{T} H_{1}^{i}(r,\,V_{r}) + H_{2}^{i}(r,\,y^{i}_{r},\,z^{i}_{r})\ d r - \int_{t}^{T} z_{r}^{i}\ d W_{r},\,0 \le t \le T.
 	\end{equation}
	For each $ i =1,\,2,\,\dots,\,n, $ it is clear from (H1) that for any $ (r,\,\omega,\,y,\,z)\in [0,\,T] \times \Omega \times (0,\,+\infty) \times \mathbb{R}^{1\times d},$
\[ 0\le  g(r,\,\omega,\,y,\,z) := H_{1}^{i}(r,\,V_{r}) + H_{2}^{i}(r,\,\omega,\,y,\,z) \le A\left(1 + \lvert V_{r} \rvert\right) + \alpha_{r} +\beta_{r} y +\frac{\delta}{2y}\lvert z \rvert^{2}, \] and $ g $ is convex in $ (y,\,z) $.
	In view of (H2), we have that 
	\[\mathbb{E}\left[ \left(1+(\xi^{i})^{2+\delta} + \int_{0}^{T} \left( \alpha_{r} + A + A\lvert V_{r} \rvert\right) ^{2+\delta}\ d r\right)^{p}e^{p(2+\delta)\int_{0}^{T} \beta_{s}d s}\right] < +\infty,\]
	thus \sref{Lemma}{lemma1} shows that the system \myeqref{eq3} admits a unique solution $ (y,\,z) \in \mathcal{S}^{p(2+\delta)}(\mathbb{R}^{n}) \times \mathcal{M}^{p}(\mathbb{R}^{n\times d}). $ Moreover, for each $ i =1,\,2,\,\dots,\,n, $
		\begin{align*}
		&e^{(1+\delta)t+(2+\delta)\int_{0}^{t}\beta_{s}ds}(y^{i}_{t})^{2+\delta} \nonumber \\ \le & \mathbb{E}_{t}\left[ e^{(1+\delta)T+(2+\delta)\int_{0}^{T}\beta_{s}ds}\lvert \xi \rvert^{2+\delta} + \int_{t}^{T} e^{(1+\delta)s+(2+\delta)\int_{0}^{s}\beta_{u}du}\left(\alpha_{s}+ A + A\lvert V_{s} \rvert \right)^{2+\delta}d s\right]. 	\end{align*}
	Doob's $ L^{p} $ inequality gives that for any $t \in [0,\,T], $
	\begin{align}\label{eq4}
	&\mathbb{E}\left[\sup_{t \le s \le T}e^{(1+\delta)sp+(2+\delta)p\int_{0}^{s}\beta_{u}du}(y^{i}_{s})^{(2+\delta)p}  \right] \nonumber \\ 
\le &\left(\frac{p}{p-1}\right)^{p}3^{p-1}\mathbb{E}\left[ e^{(1+\delta)pT+(2+\delta)p\int_{0}^{T}\beta_{s}ds}\left( \lvert \xi \rvert^{(2+\delta)p} + 2^{(1+\delta)p}\left( \int_{t}^{T} \left( \alpha_{s}+ A\right)^{2+\delta} \ d s\right)^{p}\right)\right]\nonumber \\
+ & \left(\frac{p}{p-1}\right)^{p}3^{p-1}2^{(1+\delta)p}(T-t)^{p}A^{(2+\delta)p}\mathbb{E}\left[ \sup\limits_{t \le s \le T} \left(  e^{(1+\delta)sp+(2+\delta)p\int_{0}^{s}\beta_{u}du} \lvert V_{s} \rvert ^{(2+\delta)p}\right)\right].  	
	\end{align}

	Based on the above argument, we initialize $ (y^{0},\,z^{0}) = (\mathbf{1}_{n},\,\mathbf{0}_{n\times d}) $ and recursively define the sequence of processes $\{(y^{(m+1)},\,z^{(m+1)})\}_{m=0}^{\infty} \in \mathcal{S}^{p(2+\delta)}(\mathbb{R}^{n}) \times \mathcal{M}^{p}(\mathbb{R}^{n\times d})$ as the
	unique adapted solution to the system of BSDEs:
	\begin{equation} \label{eq5}
	y_{t}^{(m+1);i} = \xi^{i} + \int_{t}^{T} H_{1}^{i}(r,\,y_{r}^{(m)}) + H_{2}^{i}(r,\,y_{r}^{(m+1);i},\,z^{(m+1);i}_{r})\ d r - \int_{t}^{T} z_{r}^{(m+1);i}\ d W_{r},\,0 \le t \le T,
	\end{equation}
	where $i = 1,\,\dots,\, n,\,	y^{(m+1);i}   $ denotes the $ i $-th component of $ y^{(m+1)} $.
	Now we prove $\{(y^{(m+1)},\,z^{(m+1)})\}_{m=0}^{\infty}  $ is a Cauchy sequence in $ \mathcal{S}^{p(2+\delta)} \times \mathcal{M}^{p}$. 
	In view of \myeqref{eq4}, we have that for any $t \in [0,\,T], $
	\begin{align} \label{eq6}
	&\mathbb{E}\left[\sup_{t \le s \le T}e^{(1+\delta)sp+(2+\delta)p\int_{0}^{s}\beta_{u}du}\lvert y^{(m+1)} _{s} \rvert^{(2+\delta)p} \right] \nonumber \\ 
	\le &\left(\frac{p}{p-1}\right)^{p}n^{\frac{(2+\delta)p}{2}}3^{p-1}\mathbb{E}\left[ e^{(1+\delta)pT+(2+\delta)p \int_{0}^{T}\beta_{u}du}\left( \lvert \xi \rvert^{(2+\delta)p} + 2^{(1+\delta)p}\left( \int_{0}^{T} \left( \alpha_{s}+ A\right)^{2+\delta} \ d s\right)^{p}\right)\right]\nonumber \\
	+ & \left(\frac{p}{p-1}\right)^{p}n^{\frac{(2+\delta)p}{2}}3^{p-1}2^{(1+\delta)p}(T-t)^{p}A^{(2+\delta)p}\mathbb{E}\left[ \sup\limits_{t \le s \le T} \left(  e^{(1+\delta)sp+(2+\delta)p\int_{0}^{s}\beta_{u}du} \lvert y^{(m)}_{s} \rvert ^{(2+\delta)p}\right)\right]\nonumber\\
	 \le	&D(p) + B(t,p)\mathbb{E}\left[ \sup\limits_{t \le s \le T} \left(  e^{(1+\delta)sp+(2+\delta)p\beta s} \lvert y^{(m)}_{s} \rvert ^{(2+\delta)p}\right)\right], 	
		\end{align}
where \[ D(p) := \left(\tfrac{p}{p-1}\right)^{p}n^{\tfrac{(2+\delta)p}{2}}3^{p-1}\mathbb{E}\left[ e^{(1+\delta)pT+(2+\delta)p \int_{0}^{T}\beta_{u}du}\left( \lvert \xi \rvert^{(2+\delta)p} + 2^{(1+\delta)p}\left( \int_{0}^{T} \left( \alpha_{s}+ A\right)^{2+\delta} \ d s\right)^{p}\right)\right],\] $B(t,p):=\left(\frac{p}{p-1}\right)^{p}n^{\frac{(2+\delta)p}{2}}3^{p-1}2^{(1+\delta)p}(T-t)^{p}A^{(2+\delta)p} $.
If $ A = 0 , $	it is evident that for any $ t \in [0,\,T], $
\[\sup_{m \ge 0}\mathbb{E}\left[\sup_{t \le s \le T}e^{(1+\delta)sp+(2+\delta)p\int_{0}^{s}\beta_{u}du}\lvert y^{(m+1)} _{s} \rvert^{(2+\delta)p} \right] \le
D(p). \]
If 	$ A > 0 , $ set $ \varepsilon = \frac{1}{\frac{p}{p-1}3^{\frac{p-1}{p}}2^{1+\delta+\frac{1}{p}}	A^{2+\delta}n^{\frac{2+\delta}{2}} } $. Then $ \varepsilon > 0. $ Let $ m_{0} $ be the unique integer such that
\begin{equation}\label{eq8}
	\frac{T}{\varepsilon} \le  m_{0} < \frac{T}{\varepsilon}  +1 .
\end{equation} 
If $ m_{0} = 1, $ that is, $ 2B(t,p)\le 2\left(\frac{p}{p-1}\right)^{p}n^{\frac{(2+\delta)p}{2}}3^{p-1}2^{(1+\delta)p}A^{(2+\delta)p}T^{p} = \left(\frac{T}{\varepsilon} \right) ^{p}\le 1. $ Therefore, it follows from \myeqref{eq6} that for any $m \ge 0,\, t \in [0,\,T], $
\begin{align}\label{eq7}
   &\mathbb{E}\left[\sup_{t \le s \le T}e^{(1+\delta)sp+(2+\delta)p\int_{0}^{s}\beta_{u}du}\lvert y^{(m+1)} _{s} \rvert^{(2+\delta)p} \right]  \nonumber \\ \le
&D(p) + \frac{1}{2}\mathbb{E}\left[ \sup\limits_{t \le s \le T} \left(  e^{(1+\delta)sp+(2+\delta)p\int_{0}^{s}\beta_{u}du} \lvert y^{(m)}_{s} \rvert ^{(2+\delta)p}\right)\right] \nonumber\\
    \le
&	D(p)+\frac{1}{2}D(p)+\frac{1}{4}\mathbb{E}\left[ \sup\limits_{t \le s \le T} \left(  e^{(1+\delta)sp+(2+\delta)p\int_{0}^{s}\beta_{u}du} \lvert y^{(m-1)}_{s} \rvert ^{(2+\delta)p}\right)\right] \nonumber \\
    \le &
D(p)\left(1+\frac{1}{2}+...+\frac{1}{2^{m}}\right)+\frac{1}{2^{m+1}}\mathbb{E}\left[ \sup\limits_{t \le s \le T} \left(  e^{(1+\delta)sp+(2+\delta)p\int_{0}^{s}\beta_{u}du} \lvert y^{(0)}_{s} \rvert ^{(2+\delta)p}\right)\right]\nonumber \\
\le&  2D(p)+\frac{1}{2}\mathbb{E}\left[ \sup\limits_{t \le s \le T} \left(  e^{(1+\delta)sp+(2+\delta)p\int_{0}^{s}\beta_{u}du} \lvert y^{(0)}_{s} \rvert ^{(2+\delta)p}\right)\right].
\end{align} 
Therefore,
\begin{align*}
&\sup_{m \ge 1}\mathbb{E}\left[\sup_{0 \le s \le T}e^{(1+\delta)sp+(2+\delta)p\int_{0}^{s}\beta_{u}du}\lvert y^{(m)} _{s} \rvert^{(2+\delta)p}\right] \nonumber\\ \le &2D(p)+\frac{1}{2}\mathbb{E}\left[ \sup\limits_{0 \le s \le T} \left(  e^{(1+\delta)sp+(2+\delta)p\int_{0}^{s}\beta_{u}du} \lvert y^{(0)}_{s} \rvert ^{(2+\delta)p}\right)\right]< +\infty.\end{align*} 


If $ m_{0} = 2$, then $ \varepsilon < T \le 2\varepsilon. $
Thus for all $ t \in \left[T-\varepsilon,\,T\right],\, 2B(t,p)  = \left(\frac{T-t}{\varepsilon} \right) ^{p}  \le 1. $ Similarly, we have that %= 2\left(\frac{p}{p-1}\right)^{p}n^{\frac{(2+\delta)p}{2}}3^{p-1}2^{(1+\delta)p}A^{(2+\delta)p}(T-t)^{p} for any $ t \in [T-\varepsilon,\,T], $
\begin{align}\label{eq9}
&\sup_{m \ge 1}\mathbb{E}\left[\sup_{T-\varepsilon \le s \le T}e^{(1+\delta)sp+(2+\delta)p\int_{0}^{s}\beta_{u}du}\lvert y^{(m)} _{s} \rvert^{(2+\delta)p} \right] \nonumber\\ \le &2D(p)+\frac{1}{2}\mathbb{E}\left[ \sup\limits_{0 \le s \le T} \left(  e^{(1+\delta)sp+(2+\delta)p\int_{0}^{s}\beta_{u}du} \lvert y^{(0)}_{s} \rvert ^{(2+\delta)p}\right)\right] < +\infty.\end{align} 
In particular,
\begin{align}\label{eq10}
&\sup_{m \ge 1} \mathbb{E}\left[e^{(1+\delta)(T-\varepsilon)p+(2+\delta)p\int_{0}^{T-\varepsilon}\beta_{u}du}\lvert y^{(m)} _{T-\varepsilon} \rvert^{(2+\delta)p} \right] \nonumber\\ \le &2D(p)+\frac{1}{2}\mathbb{E}\left[ \sup\limits_{0\le s \le T} \left(  e^{(1+\delta)sp+(2+\delta)p\int_{0}^{s}\beta_{u}du} \lvert y^{(0)}_{s} \rvert ^{(2+\delta)p}\right)\right] < +\infty. \end{align} 
Consider the following system of BSDEs for any $m \ge 0,\,0 \le t \le T-\varepsilon,$
\begin{equation} \label{eq11}
y_{t}^{(m+1);i} = y^{(m+1);i}_{T-\varepsilon} + \int_{t}^{T-\varepsilon} H_{1}^{i}(r,\,y_{r}^{(m)}) + H_{2}^{i}(r,\,y_{r}^{(m+1);i},\,z^{(m+1);i}_{r})\ d r - \int_{t}^{T-\varepsilon} z_{r}^{(m+1);i}\ d W_{r},
\end{equation}
where $i = 1,\,\dots,\, n$. Noting the fact that $ T-\varepsilon < \varepsilon $, we obtain an inequality similar to \myeqref{eq7} for any $ m \ge 0,\,t \in [0,\,T-\varepsilon], $
	\begin{align} \label{eq12}
&\mathbb{E}\left[\sup_{t \le s \le T-\varepsilon}e^{(1+\delta)sp+(2+\delta)p\int_{0}^{s}\beta_{u}du}\lvert y^{(m+1)} _{s} \rvert^{(2+\delta)p}\right]  \nonumber\\
\le	 &\left(\frac{p}{p-1}\right)^{p}n^{\frac{(2+\delta)p}{2}}3^{p-1}\mathbb{E}\left[ e^{(1+\delta)p(T-\varepsilon)+(2+\delta)p \int_{0}^{T-\varepsilon}\beta_{u}du}\lvert y^{(m+1)}_{T-\varepsilon} \rvert^{(2+\delta)p} \right]
\nonumber \\
+ & \left(\frac{p}{p-1}\right)^{p}n^{\frac{(2+\delta)p}{2}}3^{p-1}\mathbb{E}\left[ e^{(1+\delta)p(T-\varepsilon)+(2+\delta)p \int_{0}^{T-\varepsilon}\beta_{u}du}2^{(1+\delta)p}\left( \int_{0}^{T-\varepsilon} \left( \alpha_{s}+ A\right)^{2+\delta} \ d s\right)^{p}\right]
\nonumber \\
+ & \left(\frac{p}{p-1}\right)^{p}n^{\frac{(2+\delta)p}{2}}3^{p-1}2^{(1+\delta)p}(T-\varepsilon-t)^{p}A^{(2+\delta)p}\mathbb{E}\left[ \sup\limits_{t \le s \le T-\varepsilon} \left(  e^{(1+\delta)sp+(2+\delta)p\int_{0}^{s}\beta_{u}du} \lvert y^{(m)}_{s} \rvert ^{(2+\delta)p}\right)\right]\nonumber\\
\le	&
\left(\frac{p}{p-1}\right)^{p}n^{\frac{(2+\delta)p}{2}}3^{p-1}\left(2D(p)+\frac{1}{2}\mathbb{E}\left[ \sup\limits_{0\le s \le T} \left(  e^{(1+\delta)sp+(2+\delta)p\int_{0}^{s}\beta_{u}du} \lvert y^{(0)}_{s} \rvert ^{(2+\delta)p}\right)\right]\right)
\nonumber\\
+	&D(p)+\frac{1}{2}\mathbb{E}\left[ \sup\limits_{t \le s \le T-\varepsilon} \left(  e^{(1+\delta)sp+(2+\delta)p\int_{0}^{s}\beta_{u}du} \lvert y^{(m)}_{s} \rvert ^{(2+\delta)p}\right)\right]\nonumber\\
=	&
\bar{D}(p)+\frac{1}{2}\mathbb{E}\left[ \sup\limits_{t \le s \le T-\varepsilon} \left(  e^{(1+\delta)sp+(2+\delta)p\int_{0}^{s}\beta_{u}du} \lvert y^{(m)}_{s} \rvert ^{(2+\delta)p}\right)\right]\nonumber\\
%\le	&
%\bar{D}(p)+\frac{1}{2}\bar{D}(p)+\frac{1}{4}\mathbb{E}\left[ \sup\limits_{t \le s \le T-\varepsilon} \left(  e^{(1+\delta)sp+(2+\delta)p\int_{0}^{s}\beta_{u}du} \lvert y^{(m-1)}_{s} \rvert ^{(2+\delta)p}\right)\right] \nonumber \\
\le &
\bar{D}(p)\left(1+\frac{1}{2}+...+\frac{1}{2^{m}}\right)+\frac{1}{2^{m+1}}\mathbb{E}\left[ \sup\limits_{t \le s \le T-\varepsilon} \left(  e^{(1+\delta)sp+(2+\delta)p\int_{0}^{s}\beta_{u}du} \lvert y^{(0)}_{s} \rvert ^{(2+\delta)p}\right)\right]\nonumber \\
\le&  2\bar{D}(p)+\frac{1}{2}\mathbb{E}\left[ \sup\limits_{0 \le s \le T} \left(  e^{(1+\delta)sp+(2+\delta)p\int_{0}^{s}\beta_{u}du} \lvert y^{(0)}_{s} \rvert ^{(2+\delta)p}\right)\right],
\end{align}
where \begin{align*}
	\bar{D}(p) := &\left( 1+2\left(\frac{p}{p-1}\right)^{p}n^{\frac{(2+\delta)p}{2}}3^{p-1}\right)D(p)\nonumber \\+&\left(\frac{p}{p-1}\right)^{p}n^{\frac{(2+\delta)p}{2}}3^{p-1}\frac{1}{2}\mathbb{E}\left[ \sup\limits_{0\le s \le T} \left(  e^{(1+\delta)sp+(2+\delta)p\int_{0}^{s}\beta_{u}du} \lvert y^{(0)}_{s} \rvert ^{(2+\delta)p}\right)\right].
\end{align*}  
Therefore,
	\begin{align} \label{eq13}
&\sup_{m \ge 1}\mathbb{E}\left[\sup_{0 \le s \le T-\varepsilon}e^{(1+\delta)sp+(2+\delta)p\int_{0}^{s}\beta_{u}du}\lvert y^{(m)} _{s} \rvert^{(2+\delta)p}\right]  \nonumber\\
\le	 &\left( 1+2\left(\frac{p}{p-1}\right)^{p}n^{\frac{(2+\delta)p}{2}}3^{p-1}\right)2D(p)\nonumber \\+&\left( 1+2\left(\frac{p}{p-1}\right)^{p}n^{\frac{(2+\delta)p}{2}}3^{p-1}\right)\frac{1}{2}\mathbb{E}\left[ \sup\limits_{0\le s \le T} \left(  e^{(1+\delta)sp+(2+\delta)p\int_{0}^{s}\beta_{u}du} \lvert y^{(0)}_{s} \rvert ^{(2+\delta)p}\right)\right].
\end{align}
Combining \myeqref{eq9} and \myeqref{eq13} gives that
\begin{align}\label{eq14}
&\sup_{m \ge 1}\mathbb{E}\left[\sup_{0 \le s \le T}e^{(1+\delta)sp+(2+\delta)p\int_{0}^{s}\beta_{u}du}\lvert y^{(m)} _{s} \rvert^{(2+\delta)p} \right] \nonumber\\
\le &\left( 1+2\left(\frac{p}{p-1}\right)^{p}n^{\frac{(2+\delta)p}{2}}3^{p-1}\right)2D(p)\nonumber \\+&\left( 1+2\left(\frac{p}{p-1}\right)^{p}n^{\frac{(2+\delta)p}{2}}3^{p-1}\right)\frac{1}{2}\mathbb{E}\left[ \sup\limits_{0\le s \le T} \left(  e^{(1+\delta)sp+(2+\delta)p\int_{0}^{s}\beta_{u}du} \lvert y^{(0)}_{s} \rvert ^{(2+\delta)p}\right)\right]<\infty.
\end{align} 
If $ m_{0} = 3, $ then a similar induction gives
\begin{align}\label{eq15}
&\sup_{m \ge 1}\mathbb{E}\left[\sup_{0 \le s \le T}e^{(1+\delta)sp+(2+\delta)p\int_{0}^{s}\beta_{u}du}\lvert y^{(m)} _{s} \rvert^{(2+\delta)p} \right] \nonumber\\
\le &\left( 1+2\left(\frac{p}{p-1}\right)^{p}n^{\frac{(2+\delta)p}{2}}3^{p-1}+\left(2\left(\frac{p}{p-1}\right)^{p}n^{\frac{(2+\delta)p}{2}}3^{p-1}\right)^{2}\right)\nonumber \\\cdot&\left(2D(p)+ \frac{1}{2}\mathbb{E}\left[ \sup\limits_{0\le s \le T} \left(  e^{(1+\delta)sp+(2+\delta)p\int_{0}^{s}\beta_{u}du} \lvert y^{(0)}_{s} \rvert ^{(2+\delta)p}\right)\right]\right)<\infty.
\end{align} 

Therefore, 
\begin{align}\label{eq16}
&\sup_{m \ge 1}\mathbb{E}\left[\sup_{0 \le s \le T}e^{(1+\delta)sp+(2+\delta)p\int_{0}^{s}\beta_{u}du}\lvert y^{(m)} _{s} \rvert^{(2+\delta)p} \right] \nonumber\\
\le &\left( 1+2\left(\frac{p}{p-1}\right)^{p}n^{\frac{(2+\delta)p}{2}}3^{p-1}+\dots+\left(2\left(\frac{p}{p-1}\right)^{p}n^{\frac{(2+\delta)p}{2}}3^{p-1}\right)^{m_{0}-1}\right)\nonumber \\\cdot&\left(2D(p)+ \frac{1}{2}\mathbb{E}\left[ \sup\limits_{0\le s \le T} \left(  e^{(1+\delta)sp+(2+\delta)p\int_{0}^{s}\beta_{u}du} \lvert y^{(0)}_{s} \rvert ^{(2+\delta)p}\right)\right]\right)<\infty.
\end{align} 

Now we prove that
\begin{align}\label{eq17}
	\sup_{m \ge 1}\mathbb{E}\left[\left( \int_{0}^{T} \lvert z^{(m)}_{r}\rvert^{2}\ d r\right)^{\frac{p}{2}} \right]<\infty.
\end{align}
	 	From \sref{Lemma}{lemma1}, we have for any $ m \ge 0, $
	 \[
	 \mathbb{E}\left[\left(\int_{0}^{T} \lvert z^{(m+1);i}_{u}\rvert ^{2} d u\right)^{\tfrac{p}{2}}\right] \leq  C\left\{1+ \sup_{m \ge 0}\mathbb{E}\left[ \sup_{0 \le s \le T}  \lvert y^{(m)}_{s} \rvert^{p(2+\delta)} \right]+ \mathbb{E}\left[ \left(\int_{0}^{T}\alpha_{s} d s \right)^{p}+\left(\int_{0}^{T}\beta_{s} d s \right)^{p} \right]\right\},
	 \]
	 where $ C $ is a contant independent on $ m. $ Consequently, in view of (H2), we have
	 \[\sup_{m \ge 0}\mathbb{E}\left[\left(\int_{0}^{T} \lvert z^{(m)}_{u}\rvert ^{2} d u\right)^{\tfrac{p}{2}}\right] <\infty.  \]
	Now we prove that $\{(y^{(m)},\,z^{(m)})\}_{m=1}^{\infty}  $ is a Cauchy sequence in $ \mathcal{S}^{p(2+\delta)} \times \mathcal{M}^{p} $.
	For any given $m,\,q \ge 1,\,\theta \in (0,\, 1) $, set
\[
\Delta_{\theta}y^{(m,q)}_{t}:=\frac{y^{(m+q)}_{t}-\theta y_{t}^{(m)}}{1-\theta}, \  \Delta_{\theta} z^{(m,q)}_{t} := \frac{z^{(m+q)}_{t}-\theta z^{(m)}_{t}}{1-\theta}.
\] 
	Therfore, $(\Delta_{\theta}y^{(m,q)},\,\Delta_{\theta} z^{(m,q)})  $ is a solution to the following system of BSDEs
	\begin{align*}
		\Delta_{\theta}y^{(m,q);i}_{t} = \xi^{i} &+ \int_{t}^{T} \frac{1}{1-\theta}\Big[H_{1}^{i}\left(u,\, y^{(m+q-1)}_{u}\right)-\theta H_{1}^{i}\left(u,\, y^{(m-1)}_{u}\right)\nonumber\\&+H_{2}^{i}\left(u,\, y_{u}^{(m+q);i},\, z_{u}^{(m+q);i}\right)-\theta H_{2}^{i}\left(u,\, y_{u}^{(m);i},\, z_{u}^{(m);i}\right)\Big]du - \int_{t}^{T} \Delta_{\theta} z^{(m,q);i}_{u}d W_{u}.
	\end{align*}	
It follows from (H1) that
\begin{align}\label{eq18}
	&\frac{\mathds{1}_{\Delta_{\theta}y^{(m,q);i}_{u}>0}}{1-\theta}\left[H_{1}^{i}\left(u,\, y^{(m+q-1)}_{u}\right)-\theta H_{1}^{i}\left(u,\, y^{(m-1)}_{u}\right)+H_{2}^{i}\left(u,\, y_{u}^{(m+q);i},\, z_{u}^{(m+q);i}\right)-\theta H_{2}^{i}\left(u,\, y_{u}^{(m);i},\, z_{u}^{(m);i}\right)\right] \nonumber \\
	\le &\frac{A}{1-\theta}\lvert y^{(m+q-1)}_{u}- y^{(m-1)}_{u}\rvert+H^{i}_{1}\left(u,\, y^{(m-1)}_{u}\right)+ \mathds{1}_{\Delta_{\theta}y^{(m,q);i}_{u}>0}H_{2}^{i}\left(u,\, 	\Delta_{\theta}y^{(m,q);i}_{u},\, 	\Delta_{\theta}z^{(m,q);i}_{u}\right)\nonumber \\
	\le &A\left[\lvert \Delta_{\theta}y^{(m-1,q)}_{u}\rvert +1+2\lvert  y^{(m-1)}_{u}\rvert\right]+\alpha_{u}+\beta_{u}(\Delta_{\theta}y^{(m,q);i}_{u})^{+}+\frac{\delta\mathds{1}_{\Delta_{\theta}y^{(m,q);i}_{u}>0}}{2\Delta_{\theta}y^{(m,q);i}_{u}}\lvert\Delta_{\theta}z^{(m,q);i}_{u}\rvert^{2}.
\end{align}	
	Applying Tanaka’s formula and It\^o's formula to $ ((\Delta_{\theta}y^{(m,q);i}_{t})^{+})^{2+\delta}e^{(1+\delta)t+(2+\delta)\int_{0}^{t}\beta_{u}du} $ and using \myeqref{eq16}, we have for $ t \in [0,\,T], $
\begin{align*}
	&((\Delta_{\theta}y^{(m,q);i}_{t})^{+})^{2+\delta}e^{(1+\delta)t+(2+\delta)\int_{0}^{t}\beta_{u}du} \nonumber \\ \le & \mathbb{E}_{t}\!\left[ \left(\xi^{i}\right)^{2+\delta}e^{(1+\delta)T+(2+\delta)\int_{0}^{T}\beta_{u}du}+\!\! \int_{t}^{T}\!e^{(1+\delta)s+(2+\delta)\int_{0}^{s}\beta_{u}du}\left(A+\alpha_{s}+2A\lvert  y^{(m-1)}_{s}\rvert+A\lvert \Delta_{\theta}y^{(m-1,q)}_{s}\rvert\right)^{2+\delta}d s\right]. 
\end{align*} 
	Analogously, define
	\[
	\Delta_{\theta}\tilde{y}^{(m,q)}_{t}:=\frac{y^{(m)}_{t}-\theta y_{t}^{(m+q)
	}}{1-\theta}, \  \Delta_{\theta} \tilde{z}^{(m,q)}_{t} := \frac{z^{(m)}_{t}-\theta z^{(m+q)}_{t}}{1-\theta}.
	\] 
	Then we have
\begin{align*}
&((\Delta_{\theta}\tilde{y}^{(m,q);i}_{t})^{+})^{2+\delta}e^{(1+\delta)t+(2+\delta)\int_{0}^{t}\beta_{u}du} \nonumber \\ \le & \mathbb{E}_{t}\!\left[ \left(\xi^{i}\right)^{2+\delta}e^{(1+\delta)T+(2+\delta)\int_{0}^{T}\beta_{u}du}+\!\! \int_{t}^{T}\!e^{(1+\delta)s+(2+\delta)\int_{0}^{s}\beta_{u}du}\left(A+\alpha_{s}+2A\lvert  y^{(m+q-1)}_{s}\rvert+A\lvert \Delta_{\theta}\tilde{y}^{(m-1,q)}_{s}\rvert\right)^{2+\delta}d s\right]. 
\end{align*} 
	Note the facts that
