    \le& \eta^{-\frac{1}{k}}\!\!\left\{\mathbb{E}\left[\sup\limits_{0 \le r \le T}\frac{1}{y_{r}^{(m+1);i} \wedge y_{r}^{i}} \right] \right\}^{\frac{1}{k}}\!\! \left\{\mathbb{E}\left[\left( \int_{0}^{T} 2\alpha_{r} +\beta_{r}\left(\lvert y_{r}^{(m+1)}\rvert +\lvert y_{r}\rvert\right)+\frac{\delta\lvert z^{(m+1);i}_{r}\rvert^{2}}{2y_{r}^{(m+1);i}}+\frac{\delta\lvert z^{i}_{r}\rvert^{2}}{2y_{r}^{i}}\ d r\right)^{l}     \right] \right\}^{\frac{1}{l}}\nonumber \\
    \le& C\eta^{-\frac{1}{k}}\left\{\mathbb{E}\left[\sup\limits_{0 \le r \le T}  \frac{1}{\mathbb{E}_{r}\left[ \xi^{i} \right]} \right] \right\}^{\frac{1}{k}} \nonumber \\
       \le&   C\eta^{-\frac{1}{k}}\left\{\mathbb{E}\left[\sup\limits_{0 \le r \le T} \left[ \mathbb{E}_{r}\left[ \frac{1}{ \xi^{i} } \right]\right]^{q}\right]+1 \right\}^{\frac{1}{k}} \nonumber \\
       \le&   C\eta^{-\frac{1}{k}}\left\{\mathbb{E}\left[ \left(\frac{1}{ \xi^{i} } \right)^{q}\right]+1 \right\}^{\frac{1}{k}}   ,
	\end{align}
	where $q > 1$ is defined in (H2), and $ C>0 $ is indepedent on $ m $. Therefore, by taking a large enough $ \eta $, we can obtain that
	\[\lim\limits_{m\to +\infty}\mathbb{E}\left[\int_{0}^{T}\lvert  H_{2}^{i}(r,\,y_{r}^{(m+1);i},\,z^{(m+1);i}_{r}) - H_{2}^{i}(r,\,y_{r}^{i},\,z^{i}_{r}) \rvert \ d r\right] = 0.\]

  Taking limit in \myeqref{eq5}, we get $ (y,\,z) \in \mathcal{S}^{p(2+\delta)}(\mathbb{R}^{n}) \times \mathcal{M}^{p}(\mathbb{R}^{n\times d}) $ is a solution to \myeqref{eq1}. Now it remains to prove the uniqueness.

  Assume that $ (\hat{y},\,\hat{z}) \in  \mathcal{S}^{p(2+\delta)}(\mathbb{R}^{n}) \times \mathcal{M}^{p}(\mathbb{R}^{n\times d})$ is another solution to \myeqref{eq1}.	For any given $\theta \in (0,\, 1) $, set
	\[
	\Delta_{\theta}U_{t}:=\frac{y_{t}-\theta \hat y_{t}}{1-\theta}, \  \Delta_{\theta} V_{t} := \frac{z_{t}-\theta \hat z_{t}}{1-\theta},  
	\] 
	and
	\[
	\Delta_{\theta}\tilde U_{t}:=\frac{\hat y_{t}-\theta  y_{t}}{1-\theta}, \  \Delta_{\theta} \tilde V_{t} := \frac{\hat z_{t}-\theta  z_{t}}{1-\theta}.
	\] 


		Therfore, $(\Delta_{\theta}U,\,\Delta_{\theta} V)  $ is a solution to the following system of BSDEs
	\begin{align*}
	\Delta_{\theta}U^{i}_{t} = \xi^{i} &+ \int_{t}^{T} \frac{1}{1-\theta}\Big[H_{1}^{i}\left(u,\, y_{u}\right)-\theta H_{1}^{i}\left(u,\,\hat y_{u}\right)\nonumber\\&+H_{2}^{i}\left(u,\, y_{u}^{i},\, z_{u}^{i}\right)-\theta H_{2}^{i}\left(u,\, \hat y_{u}^{i},\, \hat z_{u}^{i}\right)\Big]du - \int_{t}^{T} \Delta_{\theta} V^{i}_{u}d W_{u}.
	\end{align*}	
	It follows from (H1) that
	\begin{align}\label{eq33}
	&\frac{\mathds{1}_{\Delta_{\theta}U^{i}_{u}>0}}{1-\theta}\left[H_{1}^{i}\left(u,\, y_{u}\right)-\theta H_{1}^{i}\left(u,\, \hat y_{u}\right)+H_{2}^{i}\left(u,\, y_{u}^{i},\, z_{u}^{i}\right)-\theta H_{2}^{i}\left(u,\, \hat y_{u}^{i},\, \hat z_{u}^{i}\right)\right] \nonumber \\
	\le &\frac{A}{1-\theta}\lvert y_{u}- \hat y_{u}\rvert+H^{i}_{1}\left(u,\, \hat y_{u}\right)+ \mathds{1}_{\Delta_{\theta}U^{i}_{u}>0}H_{2}^{i}\left(u,\, 	\Delta_{\theta}U^{i}_{u},\, 	\Delta_{\theta}V^{i}_{u}\right)\nonumber \\
	\le &A\left[\lvert \Delta_{\theta}U_{u}\rvert +1+2\lvert  \hat y_{u}\rvert\right]+\alpha_{u}+\beta_{u}(\Delta_{\theta}U^{i}_{u})^{+}+\frac{\delta\mathds{1}_{\Delta_{\theta}U^{i}_{u}>0}}{2\Delta_{\theta}U^{i}_{u}}\lvert\Delta_{\theta}V^{i}_{u}\rvert^{2}.
	\end{align}	
	Applying Tanaka’s formula and It\^o's formula to $ ((\Delta_{\theta}U^{i}_{t})^{+})^{2+\delta}e^{(1+\delta)t+(2+\delta)\int_{0}^{t}\beta_{u}du} $ and using \myeqref{eq33}, we have for $ t \in [0,\,T], $
	\begin{align*}
	&((\Delta_{\theta}U^{i}_{t})^{+})^{2+\delta}e^{(1+\delta)t+(2+\delta)\int_{0}^{t}\beta_{u}du} \nonumber \\ \le & \mathbb{E}_{t}\!\left[ \left(\xi^{i}\right)^{2+\delta}e^{(1+\delta)T+(2+\delta)\int_{0}^{T}\beta_{u}du}+\!\! \int_{t}^{T}\!e^{(1+\delta)s+(2+\delta)\int_{0}^{s}\beta_{u}du}\left(A+\alpha_{s}+2A\lvert \hat y_{s}\rvert+A\lvert \Delta_{\theta}U_{s}\rvert\right)^{2+\delta}d s\right]. 
	\end{align*} 
	Analogously, 
	\begin{align*}
	&((\Delta_{\theta}\tilde{U}^{i}_{t})^{+})^{2+\delta}e^{(1+\delta)t+(2+\delta)\int_{0}^{t}\beta_{u}du} \nonumber \\ \le & \mathbb{E}_{t}\!\left[ \left(\xi^{i}\right)^{2+\delta}e^{(1+\delta)T+(2+\delta)\int_{0}^{T}\beta_{u}du}+\!\! \int_{t}^{T}\!e^{(1+\delta)s+(2+\delta)\int_{0}^{s}\beta_{u}du}\left(A+\alpha_{s}+2A\lvert  y_{s}\rvert+A\lvert \Delta_{\theta}\tilde{U}_{s}\rvert\right)^{2+\delta}d s\right]. 
	\end{align*} 
	Note the facts that
	\[\left(\Delta_{\theta}U^{i}_{t} \right)^{-}  = \frac{\left(\theta \hat y_{t}^{i} -  y^{i}_{t}\right)^{+}}{1-\theta} \le \left(\Delta_{\theta}\tilde{U}^{i}_{t} \right)^{+},\]
	and \[\left(\Delta_{\theta}\tilde{U}^{i}_{t} \right)^{-}  \le \left(\Delta_{\theta}U^{i}_{t} \right)^{+}. \]
	Thus,
	\[\lvert\Delta_{\theta}U_{t} \rvert^{2+\delta},\,\lvert\Delta_{\theta}\tilde{U}_{t} \rvert^{2+\delta} \nonumber \le n^{\frac{2+\delta}{2}}2^{1+\delta}\left(\max_{i}((\Delta_{\theta}U^{i}_{t} )^{+})^{2+\delta}+\max_{i}((\Delta_{\theta}\tilde{U}^{i}_{t} )^{+})^{2+\delta}\right).\]
	%	and
	%		\[\lvert\Delta_{\theta}\tilde{y}^{(m,p)}_{t} \rvert \nonumber \le \left(\Delta_{\theta}y^{(m,q);i}_{t} \right)^{+}+\left(\Delta_{\theta}\tilde{y}^{(m,q);i}_{t} \right)^{+}.\]
	Consequently, we have
	\begin{align}\label{eq34}
	&\left( \lvert\Delta_{\theta}U_{t} \rvert ^{2+\delta}+ \lvert\Delta_{\theta}\tilde{U}_{t} \rvert ^{2+\delta} \right)e^{(1+\delta)t+(2+\delta)\int_{0}^{t}\beta_{u}du} \nonumber \\ \le &
	n^{\frac{2+\delta}{2}}2^{3+\delta}\mathbb{E}_{t}\left[ \lvert\xi\rvert^{2+\delta}e^{(1+\delta)T+(2+\delta)\int_{0}^{T}\beta_{u}du}\right]\nonumber \\ + &
	n^{\frac{2+\delta}{2}}2^{5+3\delta}\mathbb{E}_{t}\left[\int_{t}^{T}e^{(1+\delta)s+(2+\delta)\int_{0}^{s}\beta_{u}du}\left(A+\alpha_{s}\right)^{2+\delta}d s\right]\nonumber \\ + &
	n^{\frac{2+\delta}{2}}2^{6+4\delta}A^{2+\delta}\mathbb{E}_{t}\left[\int_{t}^{T}e^{(1+\delta)s+(2+\delta)\int_{0}^{s}\beta_{u}du}\left(\lvert  y_{s}\rvert^{2+\delta}+\lvert \hat y_{s}\rvert^{2+\delta}\right)d s\right]\nonumber \\ + &
	n^{\frac{2+\delta}{2}}2^{3+2\delta}A^{2+\delta}\mathbb{E}_{t}\left[\int_{t}^{T}e^{(1+\delta)s+(2+\delta)\int_{0}^{s}\beta_{u}du}\left(\lvert \Delta_{\theta}\tilde{U}_{s}\rvert^{2+\delta}+\lvert \Delta_{\theta}U_{s}\rvert^{2+\delta}\right)d s\right].
	\end{align}
	Therefore, Doob's $ L^{p} $ inequality gives for any $ t \in [0,\,T], $
	\begin{align}\label{eq35}
	&\mathbb{E}\left[\sup_{t \le s \le T}  \left( \lvert\Delta_{\theta}U_{s} \rvert ^{2+\delta}+ \lvert\Delta_{\theta}\tilde{U}_{s} \rvert ^{2+\delta} \right)^{p}e^{(1+\delta)sp+(2+\delta)p\int_{0}^{s}\beta_{u}du}  \right]\nonumber \\ \le & (\frac{p}{p-1})^{p}4^{p-1}	n^{\frac{(2+\delta)p}{2}}2^{(5+3\delta)p}\mathbb{E}\left[\left( \lvert\xi\rvert^{(2+\delta)p}+\left( \int_{0}^{T}\left(A+\alpha_{s}\right)^{2+\delta}d s\right)^{p}\right)e^{(1+\delta)pT+(2+\delta)p\int_{0}^{T}\beta_{u}du}\right]\nonumber \\ + &
	(\frac{p}{p-1})^{p}4^{p-1}n^{\frac{(2+\delta)p}{2}}2^{(6+4\delta)p}A^{(2+\delta)p}T^{p}\mathbb{E}\left[\sup_{0 \le s \le T}e^{(1+\delta)sp+(2+\delta)p\int_{0}^{s}\beta_{u}du}\left( \lvert y_{s} \rvert^{(2+\delta)p}+\lvert \hat y_{s} \rvert^{(2+\delta)p}\right) \right]\nonumber \\ + &
	(\frac{p}{p-1})^{p}4^{p-1}n^{\frac{(2+\delta)p}{2}}2^{(3+2\delta)p}A^{(2+\delta)p}(T-t)^{p}\nonumber \\ \cdot &\mathbb{E}\left[\sup_{t \le s \le T}e^{(1+\delta)ps+(2+\delta)p\int_{0}^{s}\beta_{u}du}\left(\lvert \Delta_{\theta}\tilde{U}_{s}\rvert^{2+\delta}+\lvert \Delta_{\theta}U_{s}\rvert^{2+\delta}\right)^{p}\right]\nonumber \\ = &
K(p) + \tilde B(t,\,p)\mathbb{E}\left[\sup_{t \le s \le T}e^{(1+\delta)ps+(2+\delta)p\int_{0}^{s}\beta_{u}du}\left(\lvert \Delta_{\theta}\tilde{U}_{s}\rvert^{2+\delta}+\lvert \Delta_{\theta}U_{s}\rvert^{2+\delta}\right)^{p}\right],
	\end{align}
	where $ K(p) $ is a constant independent on $\theta,\,  \tilde B(t,\,p) $ is defined in \myeqref{eq20}. %$=	(\frac{p}{p-1})^{p}4^{p-1}n^{\frac{(2+\delta)p}{2}}2^{(3+2\delta)p}A^{(2+\delta)p}(T-t)^{p}.$

	If $ A = 0 , $	it is evident that for any $ t \in [0,\,T], $
	\[\mathbb{E}\left[\sup_{t \le s \le T}\left( \lvert\Delta_{\theta}U_{s} \rvert ^{2+\delta}+ \lvert\Delta_{\theta}\tilde{U}_{s} \rvert ^{2+\delta} \right)^{p}e^{(1+\delta)sp+(2+\delta)p\int_{0}^{s}\beta_{u}du}  \right] \le
K(p). \]
Therefore, \[\mathbb{E}\left[ \sup\limits_{0 \le t \le T}\lvert y_{t}- \hat y_{t} \rvert^{(2+\delta)p}  \right]  \le
(1-\theta)^{(2+\delta)p}2^{(2+\delta)p-1} \left[K(p)+\mathbb{E}\left[ \sup\limits_{0 \le t \le T}\lvert \hat y_{t}\rvert^{(2+\delta)p}\right] \right]. \]
	Sending $ \theta \to 1$, we get $ y = \hat y $ and $ z= \hat z $ on $[0,\,T].  $ 
	If 	$ A > 0 , $ set $ \tilde \varepsilon = \frac{1}{\frac{p}{p-1}4^{\frac{p-1}{p}}2^{3+2\delta+\frac{1}{p}}	A^{2+\delta}n^{\frac{2+\delta}{2}} } $. Then $\tilde \varepsilon > 0. $ Let $ \tilde m_{0} $ be the unique integer such that
	\begin{equation}\label{eq36}
	\frac{T}{\tilde \varepsilon} \le \tilde m_{0} < \frac{T}{\tilde \varepsilon}  +1 .
	\end{equation} 

	If $ m_{0} = 1, $ that is, $ 2\tilde B(t,p)\le 2\left(\frac{p}{p-1}\right)^{p}n^{\frac{(2+\delta)p}{2}}4^{p-1}2^{(3+2\delta)p}A^{(2+\delta)p}T^{p} = \left(\frac{T}{\tilde \varepsilon} \right) ^{p}\le 1. $ Therefore, it follows from \myeqref{eq35} that 
	\begin{equation}\label{eq37}
	\mathbb{E}\left[\sup_{0 \le s \le T}\lvert\Delta_{\theta}U_{s} \rvert^{(2+\delta)p} \right]  \le 2K(p) .
	\end{equation} 
		Then we have \[\mathbb{E}\left[ \sup\limits_{0 \le t \le T}\lvert y_{t}- \hat y_{t} \rvert^{(2+\delta)p}  \right]  \le
	(1-\theta)^{(2+\delta)p}2^{(2+\delta)p-1} \left[2K(p)+\mathbb{E}\left[ \sup\limits_{0 \le t \le T}\lvert \hat y_{t}\rvert^{(2+\delta)p}\right] \right]. \]
	Sending $ \theta \to 1$, we get $ y = \hat y $ and $ z= \hat z $ on $[0,\,T]$. 


	If $ m_{0} = 2$, then $ \tilde \varepsilon < T \le 2\tilde \varepsilon. $
	Thus for all $ t \in \left[T-\tilde\varepsilon,\,T\right],\, 2\tilde B(t,p)  = \left(\frac{T-t}{\tilde\varepsilon} \right) ^{p}  \le 1. $ Similarly, we have that %= 2\left(\frac{p}{p-1}\right)^{p}n^{\frac{(2+\delta)p}{2}}3^{p-1}2^{(1+\delta)p}A^{(2+\delta)p}(T-t)^{p} for any $ t \in [T-\varepsilon,\,T], $
	\begin{equation}\label{eq38}
	\mathbb{E}\left[\sup_{T-\tilde\varepsilon \le s \le T} \left( \lvert\Delta_{\theta}U_{s} \rvert ^{2+\delta}+ \lvert\Delta_{\theta}\tilde{U}_{s} \rvert ^{2+\delta} \right)^{p}e^{(1+\delta)sp+(2+\delta)p\int_{0}^{s}\beta_{u}du}  \right]  \le 2K(p).\end{equation} 
	In particular,
	\begin{equation}\label{eq39}
	\mathbb{E}\left[e^{(1+\delta)(T-\tilde\varepsilon)p+(2+\delta)p\int_{0}^{T-\tilde\varepsilon}\beta_{u}du}\left( \lvert\Delta_{\theta}U_{T-\tilde\varepsilon} \rvert ^{2+\delta}+ \lvert\Delta_{\theta}\tilde{U}_{T-\tilde\varepsilon} \rvert ^{2+\delta} \right)^{p} \right] \le 2K(p). \end{equation} 
	Consider the following system of BSDEs for any $0 \le t \le T-\tilde\varepsilon,$
	\begin{align*}
	\Delta_{\theta}U^{i}_{t} = \Delta_{\theta}U_{T-\tilde\varepsilon}^{i} &+ \int_{t}^{T-\tilde\varepsilon} \frac{1}{1-\theta}\Big[H_{1}^{i}\left(u,\, y_{u}\right)-\theta H_{1}^{i}\left(u,\,\hat y_{u}\right)\nonumber\\
	&+H_{2}^{i}\left(u,\, y_{u}^{i},\, z_{u}^{i}\right)-\theta H_{2}^{i}\left(u,\, \hat y_{u}^{i},\, \hat z_{u}^{i}\right)\Big]du - \int_{t}^{T-\tilde\varepsilon} \Delta_{\theta} V^{i}_{u}d W_{u},
	\end{align*}
	where $i = 1,\,\dots,\, n$. Noting the fact that $ T-\tilde\varepsilon < \tilde\varepsilon $, we obtain an inequality similar to \myeqref{eq7} for any $t \in [0,\,T-\tilde\varepsilon], $
	\begin{align} \label{eq40}
&\mathbb{E}\left[\sup_{t \le s \le T-\tilde\varepsilon}  \left( \lvert\Delta_{\theta}U_{s} \rvert ^{2+\delta}+ \lvert\Delta_{\theta}\tilde{U}_{s} \rvert ^{2+\delta} \right)^{p}e^{(1+\delta)sp+(2+\delta)p\int_{0}^{s}\beta_{u}du}  \right]\nonumber \\ \le & (\frac{p}{p-1})^{p}4^{p-1}	n^{\frac{(2+\delta)p}{2}}2^{(2+\delta)p}\mathbb{E}\left[\left(  \lvert\Delta_{\theta}U_{T-\tilde\varepsilon} \rvert ^{2+\delta}+ \lvert\Delta_{\theta}\tilde{U}_{T-\tilde\varepsilon} \rvert ^{2+\delta} \right)^{p}e^{(1+\delta)pT+(2+\delta)p\int_{0}^{T}\beta_{u}du}\right]\nonumber \\
 + &(\frac{p}{p-1})^{p}4^{p-1}	n^{\frac{(2+\delta)p}{2}}2^{(5+3\delta)p}\mathbb{E}\left[\left( \int_{0}^{T}\left(A+\alpha_{s}\right)^{2+\delta}d s\right)^{p}e^{(1+\delta)pT+(2+\delta)p\int_{0}^{T}\beta_{u}du}\right]\nonumber \\ + &
(\frac{p}{p-1})^{p}4^{p-1}n^{\frac{(2+\delta)p}{2}}2^{(6+4\delta)p}A^{(2+\delta)p}T^{p}\mathbb{E}\left[\sup_{0 \le s \le T}e^{(1+\delta)sp+(2+\delta)p\int_{0}^{s}\beta_{u}du}\left( \lvert y_{s} \rvert^{(2+\delta)p}+\lvert \hat y_{s} \rvert^{(2+\delta)p}\right) \right]\nonumber \\ + &
(\frac{p}{p-1})^{p}4^{p-1}n^{\frac{(2+\delta)p}{2}}2^{(3+2\delta)p}A^{(2+\delta)p}(T-\tilde\varepsilon-t)^{p}\nonumber \\ \cdot &\mathbb{E}\left[\sup_{t \le s \le T-\tilde\varepsilon}e^{(1+\delta)ps+(2+\delta)p\int_{0}^{s}\beta_{u}du}\left(\lvert \Delta_{\theta}\tilde{U}_{s}\rvert^{2+\delta}+\lvert \Delta_{\theta}U_{s}\rvert^{2+\delta}\right)^{p}\right]\nonumber \\ = &
\bar K(p) + \frac{1}{2}\mathbb{E}\left[\sup_{0 \le s \le T-\tilde\varepsilon}e^{(1+\delta)ps+(2+\delta)p\int_{0}^{s}\beta_{u}du}\left(\lvert \Delta_{\theta}\tilde{U}_{s}\rvert^{2+\delta}+\lvert \Delta_{\theta}U_{s}\rvert^{2+\delta}\right)^{p}\right],
	\end{align}
	where \[
	\bar{K}(p) := \left( 1+(\frac{p}{p-1})^{p}4^{p-1}	n^{\frac{(2+\delta)p}{2}}2^{(2+\delta)p+1}\right)K(p).
\]
	Therefore,
	\begin{equation}\label{eq41}
		\mathbb{E}\left[\sup_{0 \le s \le T-\tilde\varepsilon}  \left( \lvert\Delta_{\theta}U_{s} \rvert ^{2+\delta}+ \lvert\Delta_{\theta}\tilde{U}_{s} \rvert ^{2+\delta} \right)^{p}e^{(1+\delta)sp+(2+\delta)p\int_{0}^{s}\beta_{u}du} \right]  
	\le	2\bar{K}(p). 	\end{equation}
	Combining \myeqref{eq38} and \myeqref{eq41} gives that
	\begin{equation}\label{eq42}
\mathbb{E}\left[\sup_{0 \le s \le T}  \left( \lvert\Delta_{\theta}U_{s} \rvert ^{2+\delta}+ \lvert\Delta_{\theta}\tilde{U}_{s} \rvert ^{2+\delta} \right)^{p}e^{(1+\delta)sp+(2+\delta)p\int_{0}^{s}\beta_{u}du} \right]  
\le	2\bar{K}(p). 	\end{equation}

 	Then we have  \[\mathbb{E}\left[ \sup\limits_{0 \le t \le T}\lvert y_{t}- \hat y_{t} \rvert^{(2+\delta)p}  \right]  \le
 	(1-\theta)^{(2+\delta)p}2^{(2+\delta)p-1} \left[2\bar K(p)+\mathbb{E}\left[ \sup\limits_{0 \le t \le T}\lvert \hat y_{t}\rvert^{(2+\delta)p}\right] \right]. \]

	Sending $ \theta \to 1$, we get $ y = \hat y $ and $ z= \hat z $ on $[0,\,T].  $ 
	  Repeating this process, we have
	  	\begin{equation}\label{eq44}
	 \mathbb{E}\left[\sup_{0 \le s \le T}\left( \lvert\Delta_{\theta}U_{s} \rvert ^{2+\delta}+ \lvert\Delta_{\theta}\tilde{U}_{s} \rvert ^{2+\delta} \right)^{p}e^{(1+\delta)sp+(2+\delta)p\int_{0}^{s}\beta_{u}du} \right] 
	 \le 2C(p)K(p),
	 \end{equation}	
	 where $ C(p) = 1+2^{(2+\delta)p+1}\left(\frac{p}{p-1}\right)^{p}n^{\frac{(2+\delta)p}{2}}4^{p-1}+\dots+\left(2^{(2+\delta)p+1}\left(\frac{p}{p-1}\right)^{p}n^{\frac{(2+\delta)p}{2}}4^{p-1}\right)^{\tilde m_{0}-1}.$
	 Then we have  \[\mathbb{E}\left[ \sup\limits_{0 \le t \le T}\lvert y_{t}- \hat y_{t} \rvert^{(2+\delta)p}  \right]  \le
	 (1-\theta)^{(2+\delta)p}2^{(2+\delta)p-1} \left[2C(p)K(p)+\mathbb{E}\left[ \sup\limits_{0 \le t \le T}\lvert \hat y_{t}\rvert^{(2+\delta)p}\right] \right]. \]

	 Sending $ \theta \to 1$, we get $ y = \hat y $ and $ z= \hat z $ on $[0,\,T].  $ 
	 This completes the proof.
\end{proof}

\section{Applications in Regime-Switching Investment Decision-Making}
In a regime-switching market, a Markov chain is used to reflect the status of the market, such as bull or bear markets. There has been extensive research on optimal consumption-investment problems and mean-variance portfolio selection problems in regime-switching markets, see, e.g. \citep{Bauerle2004, Yin2004, Hu2022}.  Recently, \citep{Hu2025} studied optimal consumption–investment problems in a regime switching market with parameters depending on both a Markov chain and a Brownian motion. Following this framework, this paper generalizes the investment model of \citep{Bahlali2018} to a regime switching market with random coefficients. In this chapter, we demonstrate that the solution to the singular system of equations established in the previous chapter represents the value function of a class of optimal investment decision problems.


We first introduce some notations. Let $\alpha_{t} $ denote a continuous-time stationary Markov chain defined on the probability space $(\Omega,\, \mathcal{F},\,\mathbb{P})$. Recall that $(\mathcal{F}_{s})_{s \in [0, \, T]}$ is the $\mathbb{P}$-completion of the filtration generated by $W$. Define the filtrations $ \tilde{\mathcal{F}}_{t}= \sigma\{W_{s},\,\alpha_{s}: 0 \le s \le t \}\vee \mathcal{N}, $ where $\mathcal N$ is the totality of all the $ \mathbb{P}$-null sets of $ \mathcal{F} $. We assume $ W_{t}$ and $\alpha_{t} $ are independent processes, and $\alpha_{t} $ takes values in a finite state space $ G = {1, 2,\,\dots,\,k} $ with $ k > 1.$ The generator of $ \alpha_{t} $ is given by $ Q = (q^{lj})_{k \times k} $ with $ q^{lj} \ge 0 $ for $ l \neq j $ and $ \sum_{j=1}^{k} q^{lj}  = 0$ for each $ l \in G. $

Consider a market with $ m $ stocks following the synamics
\[dS_{i}(t) = S_{i}(t)\left(b_{i}(t, \alpha_{t}) dt + \sum\limits_{j=1}^{d}\sigma_{ij}(t, \alpha_{t})dW^{j}_{t}\right),\,S_{i}(0) = s_{i}(0)\in \mathbb{R}_{+},\]
 where $  b_{i}(t,l) $ is the appreciation rate process and $ \sigma_{i}(t,l)=(\sigma_{i1}(t,l),\,\dots,\,\sigma_{id}(t,l)) $ is the volatility or the dispersion rate process of the $ i $th stock, corresponding to $ \alpha_{t} = l,$ for each $ i=1,\,\dots,\,m,$ and $ l \in G. $

 For each $ l \in G,$ define the appreciate vector $ b(t,l)=(b_{1}(t,l),\,\dots,\,b_{m}(t,l))'$, and volatility matrix
 \[
\sigma(t,l) = \begin{pmatrix}
 \sigma_{1}(t,l) \\ \sigma_{2}(t,l) \\ \sigma_{m}(t,l)
 \end{pmatrix} \equiv (\sigma_{ij}(t,l))_{m\times d}.
 \]
 We assume throughout this section that for each $ l \in G,$
 $ b(t,l) $ and $ \sigma(t,l) $ are $ \{\mathcal{F}_{t}\}_{t\ge 0} $-predictable and uniformly bounded in $ t $. We also assume the following non-degeneracy condition
 \[\sigma(t,l)\sigma(t,l)' \ge \mu I,\,\text{ for all } t \in [0,\,T]\text{ and } l \in G,\]
 holds for some constant $ \mu>0. $

 Suppose that the initial market mode $ \alpha_{0} = l_{0}. $ Consider an agent with an initial
wealth $ x > 0 $. These initial conditions are fixed throughout this section. Let us denote by $\pi_{i}(t) $  the proportion  of the agent's wealth to invest in the $ i $th stock at time $ t $. $ \pi(\cdot) = (\pi_{1}(\cdot),\,\dots,\,\pi_{m}(\cdot))'$ is called a portfolio of the agent.
 Denote by $ X(t) $ the total wealth of the agent at time $ t $. Assuming that the trading of shares takes place continuously and that transaction cost and consumption are not considered, then one has that
 \begin{align*}
 X(t) = & x+\int_{0}^{t} X(s)\pi'(s)b(s,l)d s + \int_{0}^{t} X(s)\pi'(s)\sigma(s,l)d W_{s}\nonumber \\
       =&x+\int_{0}^{t} X(s)p(s,l)\lambda(s,l) d s + \int_{0}^{t} X(s)p(s,l)d W_{s},
 \end{align*}
 where $  p(s,l) := \pi'(s)\sigma(s,l),\,\lambda(s,l) := \sigma(s,l)'(\sigma(s,l)\sigma(s,l)')^{-1}b(s,l).$
%\[X(t) = x+\int_{0}^{t} X(s)\pi'(s)b(s,l)d s + \int_{0}^{t} X(s)\pi'(s)\sigma(s,l)d W_{s}\]
 Then $ p(s,l) $ and $\lambda(s,l)$ are valued in $ \mathbb{R}^{1\times d} $ and $ \mathbb{R}^{ d\times 1},$ respectively. Let $p(s) = (p(s,1),\,\dots,\,p(s,k))$ denote the strategy vector. The set of admissible trading strategies is defined by
 \begin{align*}
 \mathcal{A} = \{p:\Omega \times [0,\,T] \to \mathbb{R}^{1\times d}\mid 	& p \text{ is } \{\tilde{\mathcal{F}}_{t}\}_{t\in[0,T]} \text{-predictable, }\int_{0}^{T}\lvert p_{s}\rvert^{2}ds<+\infty \text{ \as},\\ &\text{ and } (X(t))_{t\in[0,T]} \in \text{class} (D).\}
 \end{align*}


 In this section, the agent's problem is to maximize his expected utility as in \citep{Bahlali2018}
 \begin{equation}\label{eq3.1}
 V(x,l) = \sup\limits_{p\in\mathcal{A}} \mathbb{E}\left[\frac{(X(T)\zeta(l))^{\gamma}}{\gamma}\right],\end{equation}
 where $\gamma \in (0,\, 1)$, and for each $l \in G,\,\zeta(l)$ is an $\mathcal{F}_{T}$-measurable random variable representing the proportion of wealth that the investor receives or pays at time $ T.$% when $ \alpha_{t}=l.$
 \begin{proposition}
 Assume $ \gamma \in (0,\,\frac{1}{3})\bigcup(\frac{1}{3},\,1).$ Further assume that there exists a constant $D>0 $ such that $ \xi = (\xi^{1},\dots,\xi^{k})' = ((\zeta(1))^{\gamma},\,\dots,\,(\zeta(k))^{\gamma})' $ satisfies $ \frac{1}{D}\le \zeta(l) \le D,\,l=1,\dots,k$. Then the value function in \myeqref{eq3.1} is given by \[V(x,l)=\frac{x^{\gamma}}{\gamma}Y^{l}_{0},\]
  where $ (Y^{l}_{t},\,Z^{l}_{t})_{l=1,\dots,k}$ is the unique solution of the multi-dimensional BSDE $ (\xi,H), $ with $H= (H^{1},\dots,H^{k})'$ is defined for $t\in [0,\,T], y=(y^{1},\dots,y^{k})'\in \mathbb{R}^{k},\,z=(z^{1},\dots,z^{k})' \in \mathbb{R}^{k\times d}$ by ($ l=1,\dots,k $)
 \[H^{l}(t,y,z) = 
 \begin{cases}
 \frac{\gamma y^{l}}{2(1-\gamma)} \lvert \lambda(t,l)' + \frac{1}{y^{l}}z^{l} \rvert^{2} + \sum_{j=1}^{k}q^{lj}y^{j}, \text{ if } y^{l} > 0,\\
 +\infty, \text{else.}                                                         %for all } l=1,\dots,k,\, 
 \end{cases}\]
 Moreover, the optimal admissible strategy is given by
  \begin{equation} \label{eq3.2}
   p^{\ast}(s,l) = \frac{1}{1-\gamma}\left(\lambda(s,l)'+\frac{1}{Y(s,l)}Z(s,l)\right),\,s \in [0,\,T],\,l=1,\dots,k.
   \end{equation}
 \end{proposition}
 \begin{proof}
 	First, we prove the BSDE $ (\xi,H)$ has a unique solution in $ \mathcal{S}^{\infty}(\mathbb{R}^{k}) \times BMO(\mathbb{R}^{k\times d}).$ Let $f(x):=\max(x,\,0),\,x\in \mathbb{R}$ denote the positive part function.
We introduce a multi-dimensional BSDE: 
 	\begin{equation}\label{eq3.4}
 	y_{t}^{l}= \xi^{l}e^{q^{ll}T}+\int_{t}^{T} g^{l}(s,y_{s},z_{s}) ds - \int_{t}^{T} z_{s}^{l} d W_{s},\,t\in[0,T],\,l=1,\dots,k,
 	\end{equation}
 	where $ (g^{1},\,\dots,\,g^{k}) $ is defined for $ t\in[0,\,T],\,y \in \mathbb{R}^{k},\,z\in\mathbb{R}^{k \times d} $ by
  \[g^{l}(t,y,z) = 
 \begin{cases} 
 \frac{\gamma y^{l}}{2(1-\gamma)} \lvert \lambda(t,l)' + \frac{1}{y^{l}}z^{l} \rvert^{2} +\sum_{j=1,j\neq l}^{k}q^{lj}e^{(q^{ll}-q^{jj})t}f(y^{j}), \text{ if } y^{l} > 0,\\
 +\infty, \text{else.}                                                         %for all } l=1,\dots,k,\, 
 \end{cases}\]
 Note the facts that
 \begin{itemize}
 	\item[$ \cdot $] for any $t\in[0,\,T],\,(y,\,z)\in (0, \,+\infty)\times \mathbb{R}^{1\times d},$ $ \frac{\gamma y}{2(1-\gamma)}\lvert\lambda(t,l)' + \frac{1}{y}z \rvert^{2} \le \frac{\gamma\lvert\lambda(t,l)\rvert^{2}}{1-\gamma} y + \frac{\gamma\lvert z \rvert^{2}}{(1-\gamma)y};$
 	\item[$ \cdot $] for any $t\in[0,\,T],\, \frac{\gamma y}{2(1-\gamma)}\lvert\lambda(t,l)' + \frac{1}{y}z \rvert^{2} $ is convex in $ (y,\,z)\in (0, \,+\infty)\times \mathbb{R}^{1\times d};$
    \item[$ \cdot $] for each $j= 1,\dots,k,\,j\neq l,$
    $0 \le \sum_{j=1,j\neq l}^{k}q^{lj}e^{(q^{ll}-q^{jj})t}f(y^{j}) $ is Lipschitz in $ y \in \mathbb{R}^{k} $ uniformly in $ t\in[0,T].$
 \end{itemize}
 	According to \sref{Corolary}{corollary}, \myeqref{eq3.4} admits a unique solution $ (y,\,z) \in \mathcal{S}^{\infty}(\mathbb{R}^{k}) \times BMO(\mathbb{R}^{k\times d})$ with $\delta$ defined in (H1) is given by $\delta = \frac{2\gamma}{1-\gamma}.$ Moreover, $ (y,\,z) $ is a positive solution. Applying It\^o's formula to $Y_{t}^{l} := y_{t}^{l}e^{-q^{ll}t},\,Z_{t}^{l} := z_{t}^{l}e^{-q^{ll}t},\,l = 1,\,\dots,\,k, $ we obtain that $ (Y,\,Z) \in \mathcal{S}^{\infty}(\mathbb{R}^{k}) \times BMO(\mathbb{R}^{k\times d})$  is the unique solution to the BSDE ($ \xi,\,H $).
 %	Now, we prove the value function in \myeqref{eq3.1} is given by $ V(x,l)=\frac{x^{\gamma}}{\gamma}Y^{l}_{0}.$ 

 	We obtain remaining arguments by combining Theorem 3.7 in \citep{Hu2025} and Proposition 5.1 in \citep{Bahlali2018}.  Denote $ Y(t,\alpha_{t}),\,Z(t,\alpha_{t}),\,p(t,\alpha_{t}),\,\lambda(t,\alpha_{t}) $ by $Y_{t},\,Z_{t},\,p_{t},\,\lambda_{t},$ respectively. For all $ p \in \mathcal{A},$ applying It\^o's formula to $ \frac{(X(t)^{\gamma}}{\gamma}Y^{\alpha_{t}}_{t}$ and using Lemma 4.3 in \citep{Hu2020}, we have that
 	\begin{align}
 	&\frac{(X(t))^{\gamma}}{\gamma}Y^{\alpha_{t}}_{t}=\frac{x^{\gamma}}{\gamma}Y^{l_{0}}+\int_{0}^{t} (Y_{s}p_{s}+\frac{1}{\gamma}Z_{s}) dW_{s}  \nonumber \\+& \int_{0}^{t} (X(s))^{\gamma} \left(Y_{s}p_{s}\lambda_{s}+p_{s}Z_{s}'+\frac{\gamma-1}{2}Y_{s}\lvert p_{s}\rvert^{2}- \frac{Y_{s}}{2(1-\gamma)} \lvert \lambda(t,l)' + \frac{1}{Y_{s}}Z_{s}\rvert^{2}\right)  ds   
 	  \nonumber \\+&\int_{0}^{t} \frac{(X(s))^{\gamma}}{\gamma}\sum_{j,j'=1}^{k}(Y^{j}_{s}-Y^{j'}_{s}) \mathds{1}_{\{\alpha_{s-}=j'\}}d\tilde N^{j'j}_{s},
 	\end{align}
 	where $\tilde N^{j'j}_{t} = N^{j'j}_{t} - q^{j'j}t $ is the compensated Poisson martingales under the filtration $ \{\tilde{\mathcal{F}}_{t}\}_{t\in[0,T]}. $

 Since $ \sup_{p \in \mathcal{A}}\left(Y_{s}p_{s}\lambda_{s}+p_{s}Z_{s}'+\frac{\gamma-1}{2}\lvert p_{s} \rvert^{2}\right)$ is obtained at $p^{\ast}_{s}= \frac{1}{1-\gamma}\left(\lambda_{s}'+\frac{1}{Y_{s}}Z_{s}\right),$ that is, $ Y_{s}p_{s}\lambda_{s}+p_{s}Z_{s}'+\frac{\gamma-1}{2}\lvert p_{s} \rvert^{2}\le \frac{Y_{s}}{2(1-\gamma)} \lvert \lambda(t,l)' + \frac{1}{Y_{s}}Z_{s}\rvert^{2},$ there exists a sequence of stopping times $\{\tau_{n}\}_{n \ge 1}$ with $ \tau_{n} \to T $ as $ n \to \infty $ such that
 	\[\mathbb{E}\left[\frac{(X(\tau_{n}))^{\gamma}}{\gamma}Y_{\tau_{n}}\right] \le \frac{x^{\gamma}}{\gamma}Y_{0}^{l_{0}}. \]
 	Applying Fatou's lemma yields that
 	\[\mathbb{E}\left[\frac{(X(T))^{\gamma}}{\gamma}\xi\right] \le \frac{x^{\gamma}}{\gamma}Y_{0}^{l_{0}}. \]  
 	If $ p^{\ast} \in \mathcal{A}, $ then the dominated convergence theorem shows that the equality holds if and only if $ p = p^{\ast}. $ It remains to prove  $ p^{\ast} \in \mathcal{A}.$ Specifically, we will show that for each fixed $l = 1,\,\dots,\,k,\, (X(t))_{t\in[0,T]} \in \text{class} (D)$ if $ p = p^{\ast}. $

 Since $ \lambda(t,l) $ is uniformly bounded in $ t,$ for all $t \in [0,\,T],\,Y^{l}_{t} \ge \mathbb{E}_{t}\left[\xi^{l}\right]\ge \frac{1}{D^{\gamma}},$ and $ Z^{l}\cdot W \in BMO(\mathbb{R}^{1\times d}),$ we obtain $ p^{\ast}\cdot W\in BMO(\mathbb{R}^{1\times d}),$ and for any $ q>1, $ \[ \mathbb{E}\left[ q\int_{0}^{T}\lambda(t,l)dW_{t}-\frac{q}{2} \int_{0}^{T}\lvert \lambda(t,l) \rvert^{2} dt\right]<\infty.\]
 Therefore, $ dW^{\lambda}_{t}= dW_{t}+ \lambda(t,l)' dt$ is a new Brownnian motion under the probability measure defined by $ \frac{dQ}{dP} \mid_{ \mathcal{F}_{T}} = \mathscr{E}(-\int_{0}^{\cdot}\lambda(t,l)dW_{t})_{T},$ and
$ \int_{0}^{t} p^{\ast}(s,l) \lambda(s,l) ds+\int_{0}^{t} p^{\ast}(s,l) dW_{s} $ is a $ BMO$ martingale under $ Q. $

 Thus, $ X(t) = x e^{\int_{0}^{t} p^{\ast}(s,l) \lambda(s,l)  - \frac{1}{2}\lvert p^{\ast}(s,l) \rvert^{2} ds+ \int_{0}^{t} p^{\ast}(s,l) dW_{s} } = x\mathscr{E}(\int_{0}^{\cdot} p^{\ast}(s,l) \lambda(s,l) ds+\int_{0}^{\cdot} p^{\ast}(s,l) dW_{s})_{t}$ is a uniformly integrable martingale under $ Q,$ and for some $ q>1,\,\mathbb{E}^{Q}[(X(T))^{q}]<\infty$ by Theorem 3.4 in \citep{Kazamaki2006}. From Corollary 3.4 in \citep{Kazamaki2006}, we have for $ \theta >1 $ such that $ \frac{1}{\theta}+\frac{1}{q}=1$ and any stopping time $\tau \in \mathcal{T}_{0,T},$ there exists a constant $ C>0 $ such that
 $X(\tau) \le C\left( \mathbb{E}^{Q}[(X(T))^{\frac{1}{\theta}}\mid_{ \mathcal{F}_{\tau}}] \right)^{\theta}.$ Then we have 
 \begin{align*}
 	&\mathbb{E}\left[\sup\limits_{\tau \in \mathcal{T}_{0,T}}X(\tau) \right] \nonumber \\ 
 	\le & C\mathbb{E}\left[\sup\limits_{\tau \in \mathcal{T}_{0,T}}X(\tau) e^{-\frac{1}{q}\int_{0}^{T} \frac{1}{2}\lvert\lambda(s,l) \rvert^{2} ds+ \frac{1}{q}\int_{0}^{T} \lambda(s,l)  dW_{s} }   e^{-\frac{1}{q}\int_{0}^{T} \frac{1}{2}\lvert\lambda(s,l) \rvert^{2} ds- \frac{1}{q}\int_{0}^{T} \lambda(s,l)  dW_{s} }       \right] \nonumber \\
 	\le & C\left(\mathbb{E}^{Q}\left[  \sup\limits_{\tau \in \mathcal{T}_{0,T}}(X(\tau))^{q}\right]  \right)^{\frac{1}{q}}\left(\mathbb{E}\left[e^{-\frac{\theta}{q}\int_{0}^{T} \frac{1}{2}\lvert\lambda(s,l) \rvert^{2} ds+ \frac{\theta}{q}\int_{0}^{T} \lambda(s,l)  dW_{s} } \right] \right)^{\frac{1}{\theta}} \nonumber \\
 	\le & C\left( \mathbb{E}^{Q}\left[  \sup\limits_{\tau \in \mathcal{T}_{0,T}}\left( \mathbb{E}^{Q}[(X(T))^{\frac{1}{\theta}}\mid_{ \mathcal{F}_{\tau}}] \right)^{q\theta}  \right]\right)^{\frac{1}{q}} \le  C\left( \mathbb{E}^{Q}\left[(X(T))^{q}\right]\right)^{\frac{1}{q}} < \infty.
 \end{align*}
 Therefore, $ (X(t))_{t\in[0,T]} \in \text{class} (D),$ which completes the proof.
 \end{proof}
