\section{Notation and assumptions}\label{sec:nap}
Throughout this paper, we use $\R^n$ to denote the $n$-dimensional Euclidean space and $\langle\cdot,\cdot\rangle$ to represent the standard inner product. We use $\|\cdot\|$ to denote the Euclidean norm for vectors and the spectral norm for matrices. For any positive integer $p$ and a $p$th-order continuously differentiable function $\varphi$, we denote by $\Dp\varphi(x)[h_1,\ldots,h_p]$ the $p$th-order directional derivative of $\varphi$ at $x$ along $h_i\in\R^n$, $1\le i\le p$, and 
by $\Dp \varphi(x)[\cdot]$ the associated symmetric $p$-linear form. For any symmetric $p$-linear form $\mathcal{T}[\cdot]$, we define its norm as
\begin{align}\label{def:pnorm}
\|\mathcal{T}\|:=\max_{h_1,\ldots,h_p}\{\mathcal{T}[h_1,\ldots,h_p]:\|h_i\|\le1,1\le i\le p\}. 
\end{align}
For any $x\in\R^n$ and $h_i\in\R^n$ with $1\le i\le p-1$, we define $\nabla^p\varphi(x)(h_1,\ldots,h_{p-1})\in\R^n$ by
\[
\langle \nabla^p\varphi(x)(h_1,\ldots,h_{p-1}), h_p\rangle := \Dp\varphi(x)[h_1,\ldots,h_p]\qquad \forall h_p\in\R^n.
\]
For any $x,h\in\R^n$, we denote $\Dp \varphi(x)[h]^{p}:= \Dp \varphi(x)[h,\ldots,h]$ and $\nabla^p \varphi(x)(h)^{p-1}:=\nabla^p \varphi(x)(h,\ldots,h)$. For any $s\in\R$, we let $\mathrm{sgn}(s)$ be $1$ if $s\ge0$ and $-1$ otherwise. For any positive integer $p$, we define the residual of the $p$th-order Taylor expansion of $\nabla f$ as:
\begin{align}\label{def:taylor-res}
\Rp(y,x) := \nabla f(y) - \sum_{r=1}^p\frac{1}{(r-1)!}\nabla^r f(x)(y-x)^{r-1}\qquad\forall x,y\in\R^n.
\end{align}
In addition, we use $\widetilde{\mathcal{O}}(\cdot)$ to denote $\mathcal{O}(\cdot)$ with logarithmic terms omitted.

We now make the following assumption throughout this paper.
\begin{assumption}\label{asp:basic}
\begin{enumerate}[{\rm (a)}]
\item There exists a finite $f_{\mathrm{low}}$ such that $f(x)\ge f_{\mathrm{low}}$ for all $x\in\R^n$.
\item There exists $L_1>0$ such that $\|\nabla f(x) - \nabla f(y)\|\le L_1\|x-y\|$ for all $x,y\in\R^n$.
\item The stochastic gradient estimator $G:\mathbb{R}^n\times\Xi\to\R^n$ satisfies 
\begin{align*}
\mathbb{E}[G(x;\xi)] = \nabla f(x),\quad\mathbb{E}[\|G(x;\xi) - \nabla f(x)\|^\alpha]\le \sigma^\alpha\qquad\forall x\in\mathbb{R}^n    
\end{align*}
for some $\sigma>0$ and $\alpha\in(1,2]$.
\end{enumerate}    
\end{assumption}

We next make some remarks on Assumption \ref{asp:basic}.

\begin{remark} 
Assumptions \ref{asp:basic}(a) and \ref{asp:basic}(b) are standard. In particular, Assumption \ref{asp:basic}(b) implies that
\begin{align}\label{ineq:1st-desc}
f(y) \le f(x) + \nabla f(x)^T(y-x) + \frac{L_1}{2}\|y-x\|^2\qquad \forall x,y\in\R^n.    
\end{align}
Assumption \ref{asp:basic}(c) states that $G(\cdot;\xi)$ is an unbiased estimator of $\nabla f(\cdot)$, and its $\alpha$th central moment is uniformly bounded. This is weaker than the commonly used variance bounded assumption corresponding to the case $\alpha = 2$. When $\alpha \in (1,2)$, the stochastic gradient noise is said to be heavy-tailed (see, e.g., \cite{zhang2020adaptive}), a phenomenon frequently observed in modern machine learning applications.
% In addition, Assumption \ref{asp:basic}(c) implies that $G(\cdot;\xi)$ is an unbiased estimator for $\nabla f(\cdot)$, and its $\alpha$th central moment is bounded, which is a weaker assumption than the commonly used assumption in \eqref{asp:ub-bd}. When $\alpha \in (1,2)$, the gradient estimator $G(\cdot;\xi)$ is commonly said to exhibit heavy-tailed noise (see, e.g., \cite{zhang2020adaptive}), which has been widely observed in modern machine learning applications.
\end{remark}

\section{Normalized stochastic first-order methods with
momentum}\label{sec:nsgm}

In this section, we propose practical normalized SFOMs with Polyak momentum, multi-extrapolated momentum, and recursive momentum for solving problem \eqref{ucpb}. We also establish their first-order oracle complexities for finding an $\epsilon$-SSP of \eqref{ucpb} under heavy-tailed noise.

\subsection{A normalized SFOM with Polyak momentum}\label{subsec:nsgd-pm}

In this subsection, we propose a practical normalized SFOM with Polyak momentum for solving problem \eqref{ucpb} and establish its first-order oracle complexity for finding an $\epsilon$-SSP of \eqref{ucpb} under heavy-tailed noise.

% A normalized SFOM with Polyak momentum \cite{cutkosky2020momentum}, when applied to problem \eqref{ucpb}, generates two sequences: $\{m^k\}$ and $\{x^k\}$. Specifically, for each $k\geq 0$, the direction $m^{k}$ is a weighted average of stochastic gradients of $f$ evaluated at $x^0, \ldots, x^{k}$, and $x^{k+1}$ is an approximate solution obtained by performing a line search update at $x^{k}$ using a suitable step size and the normalized direction $-m^{k}/\|m^{k}\|$. The detailed steps of the method are presented in  Algorithm \ref{alg:unf-sfom-pm}. 

Our proposed method follows the same general framework as that in \cite{cutkosky2020momentum}, but differs in the choice of algorithmic parameters---particularly the momentum weights and step sizes. Unlike \cite{cutkosky2020momentum}, which requires explicit knowledge of the Lipschitz constant and the noise bound, our method uses dynamically updated parameters that do not depend on such problem-specific quantities. This feature enhances its practical applicability, especially in scenarios where these constants are unavailable or hard to estimate.

Specifically, our practical normalized SFOM with Polyak momentum generates two sequences, $\{m^k\}$ and $\{x^k\}$. At each iteration $k \geq 0$, the direction $m^k$ is computed as a weighted average of stochastic gradients of $f$ evaluated at the iterates $x^0, \ldots, x^k$. The next iterate $x^{k+1}$ is obtained by performing a line search update from $x^k$ along the normalized direction $-m^k/\|m^k\|$, using a suitable step size. The detailed procedure is presented in Algorithm \ref{alg:unf-sfom-pm}, with the specific momentum weights and step sizes defined in Theorems \ref{thm:s-rate-pm} and \ref{thm:un-s-rate-pm}.

\begin{algorithm}[!htbp]
\caption{A normalized SFOM with Polyak momentum}
\label{alg:unf-sfom-pm}
\begin{algorithmic}[0]
\State \textbf{Input:} starting point $x^0\in\R^n$, step sizes $\{\eta_k\}\subset(0,+\infty)$, weighting parameters $\{\theta_k\}\subset(0,1]$.
\State \textbf{Initialize:} $m^{-1}=0$ and $\theta_{-1}=1$.
\For{$k=0,1,2,\ldots$}
\State Compute the search direction:
\begin{align}\label{update-mk-pm}
m^k = (1 - \theta_{k-1}) m^{k-1} + \theta_{k-1} G(x^k;\xi^{k}).\footnotemark{}
\end{align}
\State Update the next iterate:
\begin{align*}%\label{update-xk-pm}
x^{k+1} = x^k - \eta_k\frac{m^k}{\|m^k\|}. 
\end{align*}
\EndFor
\end{algorithmic}
\end{algorithm}
\footnotetext{$\{\xi^k\}$ is a sequence of independently drawn samples.}
The following theorem establishes a complexity bound for Algorithm \ref{alg:unf-sfom-pm} to compute an $\epsilon$-SSP of problem \eqref{ucpb} under the assumption that the tail exponent $\alpha$ is known. Its proof is deferred to Section \ref{subsec:pf-pm}.

\begin{theorem}[{{\bf complexity with known $\alpha$}}]\label{thm:s-rate-pm}
Suppose that Assumption \ref{asp:basic} holds. Let $f_{\mathrm{low}}$, $L_1$, $\sigma$, and $\alpha$ be given in Assumption \ref{asp:basic}, and define
\begin{align}\label{M1a}
M_{1,\alpha} := 2(f(x^0) - f_{\mathrm{low}} + \sigma^\alpha + L_1 + (\alpha-1)(2/\alpha)^{\alpha/(\alpha-1)} + 3L_1^\alpha+2\sigma^\alpha).  
\end{align}
Let $\{x^k\}$ be generated by Algorithm \ref{alg:unf-sfom-pm} with input parameters $\{(\eta_k,\theta_k)\}$ given by
\begin{align}\label{pm-eta-theta}
\eta_k=\frac{1}{(k+1)^{(2\alpha-1)/(3\alpha-2)}},\quad \theta_k=\frac{1}{(k+1)^{\alpha/(3\alpha-2)}}\qquad\forall k\ge0.
\end{align}
Then, for any $\epsilon \in (0,1)$, it holds that $\mathbb{E}[\|\nabla f(x^{\iota_K})\|]\le \epsilon$ for all $K$ satisfying
\begin{align*}%\label{final-stat-upbd-pm}
%\mathbb{E}[\|\nabla f(x^{\iota_K})\|]\le \epsilon\qquad\forall 
K\ge\max\Big\{\Big(\frac{2(3\alpha-2)M_{1,\alpha}}{(\alpha-1)\epsilon}\ln\Big(\frac{2(3\alpha-2)M_{1,\alpha}}{(\alpha-1)\epsilon}\Big)\Big)^{(3\alpha-2)/(\alpha-1)},3\Big\},     
\end{align*}
where $\iota_K$ is uniformly drawn from $\{0,\ldots,K-1\}$.
\end{theorem}

The next theorem establishes a complexity bound for Algorithm \ref{alg:unf-sfom-pm} to compute an $\epsilon$-SSP of problem \eqref{ucpb} without requiring prior knowledge of the tail exponent $\alpha$. Its proof is deferred to Section \ref{subsec:pf-pm}.

\begin{theorem}[{{\bf complexity with unknown $\alpha$}}]\label{thm:un-s-rate-pm}
Suppose that Assumption \ref{asp:basic} holds. Let $f_{\mathrm{low}}$, $L_1$, $\sigma$, and $\alpha$ be given in Assumption \ref{asp:basic}, and define
\begin{align}\label{M1a-o}
\widetilde{M}_{1,\alpha}:= 2(f(x^0) - f_{\mathrm{low}} + \sigma^\alpha + L_1/2 + 3L_1^\alpha),\quad\widehat{M}_{1,\alpha} := 2((\alpha-1)(2/\alpha)^{\alpha/(\alpha-1)} + 2\sigma^\alpha).
\end{align}
Let $\{x^k\}$ be generated by Algorithm \ref{alg:unf-sfom-pm} with input parameters $\{(\eta_k,\theta_k)\}$ given by
\begin{align}\label{pm-eta-theta-o}
\eta_k=\frac{1}{(k+1)^{3/4}},\quad \theta_k=\frac{1}{(k+1)^{1/2}}\qquad\forall k\ge0. 
\end{align}
Then, for any $\epsilon \in (0,1)$, it holds that $\mathbb{E}[\|\nabla f(x^{\iota_K})\|]\le \epsilon$ for all $K$ satisfying
\[
K\ge \max\Big\{\Big(\frac{16\widetilde{M}_{1,\alpha}}{\epsilon}\ln\Big(\frac{16\widetilde{M}_{1,\alpha}}{\epsilon}\Big)\Big)^{4},\Big(\frac{8\alpha\widehat{M}_{1,\alpha}}{(\alpha-1)\epsilon}\ln\Big(\frac{8\alpha\widehat{M}_{1,\alpha}}{(\alpha-1)\epsilon}\Big)\Big)^{2\alpha/(\alpha-1)},3\Big\},
\]
where $\iota_K$ is uniformly drawn from $\{0,\ldots,K-1\}$.
\end{theorem}

\begin{remark}
% From Theorems \ref{thm:s-rate-pm} and \ref{thm:un-s-rate-pm}, we see that under Assumption \ref{asp:basic}, Algorithm \ref{alg:unf-sfom-pm} achieves a sample and first-order operation complexity of $\widetilde{\mathcal{O}}(\epsilon^{-(3\alpha-2)/(\alpha-1)})$ for finding an $\epsilon$-SSP of \eqref{ucpb} when the tail exponent $\alpha$ is known, and $\widetilde{\mathcal{O}}(\epsilon^{-2\alpha/(\alpha-1)})$ when $\alpha$ is unknown. Our complexity results match, up to a logarithmic factor, the best-known ones for SFOMs with gradient clipping \cite{cutkosky2021high,NEURIPS2023_4c454d34,zhang2020adaptive} and normalized SFOMs without gradient clipping \cite{hubler2024gradient,liu2025nonconvex,sun2024gradient}. Moreover, our analysis allows the deployment of time-varying algorithm parameters $\{(\eta_k,\theta_k)\}$ without prior knowledge of the problem-specific quantities, which is more practical than normalized SFOMs that use problem-specific quantities (e.g., Lipschitz constants and noise bounds) as studied in \cite{hubler2024gradient,liu2025nonconvex,sun2024gradient}.
