(ii) When the tail exponent $\alpha$ is unknown, Algorithm~\ref{alg:unf-sfom-pm} with $\{(\eta_k,\theta_k)\}$ specified by \eqref{pm-eta-theta-o} resembles the parameter-free SFOM with momentum proposed in \cite[Appendix D]{hubler2024gradient}. Nevertheless, our complexity analysis is fundamentally  different from that of \cite{hubler2024gradient} and other existing works, as it is based on descent properties of a novel potential sequence defined in \eqref{def:pot-pm}.
\end{remark} 

\subsection{A normalized SFOM with multi-extrapolated momentum}\label{subsec:nsgd-mem}

% In this subsection, we present a normalized SFOM with extrapolated momentum for solving problem \eqref{ucpb} and establish its  first-order oracle complexity for finding an approximate solution of \eqref{ucpb}.

% A normalized SFOM with extrapolated momentum \cite{cutkosky2020momentum}, when applied to problem \eqref{ucpb}, generates three sequences: $\{z^{k,t}\}$, $\{m^k\}$, and $\{x^k\}$. Specifically, for each $k \geq 0$, the points $z^{k,1}, \ldots, z^{k,q}$ are computed by extrapo dlating $x^{k-1}$ and $x^k$ using a set of extrapolation parameters. The direction $m^k$ is then formed as a weighted average of stochastic gradients of $f$ evaluated at the extrapolated points $\{z^{i,t}\}_{0 \leq i \leq k, 1 \leq t \leq q}$. Finally, $x^{k+1}$ is obtained by performing a line search update at $x^k$ using a suitable step size and the normalized direction $-m^k/\|m^k\|$. The detailed steps of the method are presented in Algorithm~\ref{alg:unf-sfom}.

% The detailed steps of the method are presented in Algorithm~\ref{alg:unf-sfom}.

In this subsection, we propose a practical normalized SFOM with multi-extrapolated momentum for solving problem \eqref{ucpb} and establish its first-order oracle complexity for finding an $\epsilon$-SSP of \eqref{ucpb} under heavy-tailed noise.

% Our method follows the general framework of~\cite{he2024stochastic}, {\color{blue}but does not require simultaneous stochastic gradient queries. Unlike~\cite{he2024stochastic}, which requires evaluating $G(\cdot;\xi)$ at multiple points using a shared sample $\xi$, our method uses each random sample $\xi$ only once when evaluating $G$. This approach is less restrictive and more suitable for modern machine learning applications; see~\cite{arjevani2023lower,cutkosky2020momentum} for further discussions.}

%but does not require simultaneous stochastic gradient queries. In contrast to~\cite{he2024stochastic}, which evaluates $G(\cdot;\xi)$ at multiple points using the same sample $\xi$, our method uses each random sample $\xi$ only once when evaluating $G$. This makes our approach less restrictive and more applicable to modern machine learning settings; see~\cite{arjevani2023lower,cutkosky2020momentum} for related discussions.

%Our method follows the general framework of~\cite{he2024stochastic}, but differs in the choice of algorithmic parameters—particularly the extrapolation weights, momentum weights, and step sizes. %Unlike~\cite{he2024stochastic}, which requires explicit knowledge of the Lipschitz constant and the noise bound, our method uses dynamically updated parameters that do not rely on such problem-specific quantities. This feature enhances its practical applicability, especially when these constants are unknown or hard to estimate.

%Our method follows the general framework of~\cite{he2024stochastic}.

Specifically, our practical normalized SFOM with multi-extrapolated momentum generates three sequences: $\{z^{k,t}\}$, $\{m^k\}$, and $\{x^k\}$. At each iteration $k \geq 0$, the points $z^{k,1}, \ldots, z^{k,q}$ are computed by extrapolating $x^{k-1}$ and $x^k$ using a set of extrapolation weights. The direction $m^k$ is then formed as a weighted average of stochastic gradients of $f$ evaluated at the extrapolated points $\{z^{i,t}\}_{0 \leq i \leq k, 1 \leq t \leq q}$. Finally, $x^{k+1}$ is computed via a line search update at $x^k$ using a suitable step size and the normalized direction $-m^k/\|m^k\|$. The detailed procedure is described in Algorithm~\ref{alg:unf-sfom}, with the extrapolation weights, momentum weights, and step sizes specified in Theorems~\ref{thm:known-rate-mem} and~\ref{thm:unknown-rate-mem}.

\begin{algorithm}[!htbp]
\caption{A normalized SFOM with multi-extrapolated momentum}
\label{alg:unf-sfom}
\begin{algorithmic}[0]
\State \textbf{Input:} starting point $x^0\in\R^n$, step sizes $\{\eta_k\}\subset(0,+\infty)$, extrapolation count $q\ge1$, extrapolation parameters $\{\gamma_{k,t}\}\subset(0,1)$, weighting parameters $\{\theta_{k,t}\}$ with $\sum_{t=1}^{q}\theta_{k,t}\in(0,1)$ for all $k\ge0$.
\State \textbf{Initialize:} $x^{-1}=x^0$, $m^{-1}=0$, and $(\gamma_{-1,t},\theta_{-1,t})=(1,1/q)$ for all $1\le t\le q$.
\For{$k=0,1,2,\ldots$}
\State Perform $q$ separate extrapolations: 
\begin{align}\label{update-zk}
z^{k,t} = x^k + \frac{1-\gamma_{k-1,t}}{\gamma_{k-1,t}}(x^k - x^{k-1})\qquad \forall 1\le t\le q.
\end{align}
\State Compute the search direction:
\begin{align}\label{update-mk}
m^k = \Big(1 - \sum_{t=1}^{q}\theta_{k-1,t}\Big) m^{k-1} + \sum_{t=1}^{q}\theta_{k-1,t}G(z^{k,t};\xi^k).\footnotemark{}
\end{align}
\State Update the next iterate:
\begin{align*}%\label{update-xk}
x^{k+1} = x^k - \eta_k\frac{m^k}{\|m^k\|}. 
\end{align*}
\EndFor
\end{algorithmic}
\end{algorithm}
\footnotetext{$\{\xi^k\}$ is a sequence of independently drawn samples. Alternatively, one may draw $q$ independent samples $\xi^{k,t}$, $1\le t\le q$, at every $k$th iteration for computing $G(z^{k,t};\xi^{k,t})$, $1\le t\le q$.
% {\color{blue}At each $k$th iteration, one can also draw $q$ independent samples $\xi^{k,t}$, $1\le t\le q$, for computing $G(z^{k,t};\xi^{k,t})$, $1\le t\le q$. This approach requires only a single stochastic oracle query, that is, using each sample only once to compute $G$, which is less restrictive than methods with simultaneous queries and can be more suitable for modern machine learning settings (see \cite{arjevani2023lower, cutkosky2020momentum} for further discussion).}
}

Before analyzing the complexity of Algorithm~\ref{alg:unf-sfom} for computing an approximate solution to problem~\eqref{ucpb}, we introduce an additional assumption regarding the high-order smoothness of the objective function~$f$.

\begin{assumption}\label{asp:high-smooth}
The function $f$ is $p$th-order continuously differentiable in $\R^n$ for some $p\ge2$, and moreover, there exists some $L_p>0$ such that $\|\Dp f(x) - \Dp f(y)\| \le L_p\|x-y\|$ for all $x,y\in\R^n$.    
\end{assumption}

The following theorem establishes a complexity bound for Algorithm \ref{alg:unf-sfom} to compute an $\epsilon$-SSP of problem \eqref{ucpb} under the assumption that the tail exponent $\alpha$ is known. Its proof is deferred to Section \ref{subsec:pf-mem}.

\begin{theorem}[{{\bf complexity with known $\alpha$}}]\label{thm:known-rate-mem}
Suppose that Assumptions \ref{asp:basic} and \ref{asp:high-smooth} hold. Let $f_{\mathrm{low}}$, $L_1$, $\sigma$, $\alpha$, $p$ and $L_p$ be given in Assumptions \ref{asp:basic} and \ref{asp:high-smooth}, and define
\begin{align}
M_{p,\alpha} &:= 4\Big(f(x^0) - f_{\mathrm{low}} + 4^{1/3}\sigma^\alpha + L_1/2 + 30^{1/(\alpha-1)}(\alpha-1)(2/\alpha)^{\alpha/(\alpha-1)} + 306 p^{2\alpha p} L_p^\alpha/(p!)^\alpha \nonumber\\ 
&\quad \ +64(p-1)^\alpha\sigma^\alpha\Big).   \label{def:Mpa-known}
\end{align}
Let $\{x^k\}$ be  generated by Algorithm \ref{alg:unf-sfom} with input parameters $q=p-1$, and $\{\eta_k\}$ and $\{(\gamma_{k,t},\theta_{k,t})\}$ given by
\begin{align}
&\eta_k=\frac{1}{(k+4)^{(p\alpha+\alpha-1)/(p(2\alpha-1)+\alpha-1)}}\qquad\forall k\ge0,\label{def:eta-known-rate-mem}\\
&\gamma_{k,t}=\frac{\gamma_k}{t^2},\quad \theta_{k,t}=\frac{\prod_{1\le s\le p-1,s\neq t}(1-s^2/\gamma_k)}{(t^2/\gamma_k)\prod_{1\le s\le p-1,s\neq t}((t^2-s^2)/\gamma_k)}\qquad\forall 1\le t\le p-1,k\ge0,\label{def:theta-known-rate-mem}
\end{align}
where
\begin{align}\label{def:gmak-mem-know}
\gamma_k=\frac{1}{(k+4)^{p\alpha/(p(2\alpha-1)+\alpha-1)}}\qquad\forall k\ge0.
\end{align}
Then, for any $\epsilon \in (0,1)$, it holds that $\mathbb{E}[\|\nabla f(x^{\iota_K})\|]\le \epsilon$ for all $K$ satisfying
\[
K\ge  \max\Big\{\Big(\frac{2(p(2\alpha-1) + \alpha -1)M_{p,\alpha}}{p(\alpha-1)\epsilon}\ln\Big(\frac{2(p(2\alpha-1) + \alpha -1)M_{p,\alpha}}{p(\alpha-1)\epsilon}\Big)\Big)^{(p(2\alpha-1)+\alpha-1)/(p(\alpha-1))},5\Big\},
\]
where $\iota_K$ is uniformly drawn from $\{0,\ldots,K-1\}$.
\end{theorem}

The next theorem establishes a complexity bound for Algorithm \ref{alg:unf-sfom} to compute an $\epsilon$-SSP of problem \eqref{ucpb} without requiring prior knowledge of the tail exponent $\alpha$. Its proof is deferred to Section~\ref{subsec:pf-mem}.

\begin{theorem}[{{\bf complexity with unknown $\alpha$}}]\label{thm:unknown-rate-mem}
Suppose that Assumptions \ref{asp:basic} and \ref{asp:high-smooth} hold. Let $f_{\mathrm{low}}$, $L_1$, $\sigma$, $\alpha$, $p$ and $L_p$ be given in Assumptions \ref{asp:basic} and \ref{asp:high-smooth}, and define
\begin{align}
&\widetilde{M}_{p,\alpha}:= 4(f(x^0) - f_{\mathrm{low}} + 4^{1/3}\sigma^\alpha + L_1/2 + 306 p^{2p\alpha} L_p^\alpha/(p!)^\alpha),\label{def:t-Mpa-unk}\\
&\widehat{M}_{p,\alpha}:= 8(30^{1/(\alpha-1)}(\alpha-1)(2/\alpha)^{\alpha/(\alpha-1)}+ 64(p-1)^\alpha\sigma^\alpha).\label{def:h-Mpa-unk}
\end{align}
 Let $\{x^k\}$ be generated by Algorithm \ref{alg:unf-sfom} with input parameters $q=p-1$, $\{\eta_k\}$, and $\{(\gamma_{k,t},\theta_{k,t})\}$ given by 
\begin{align}
&\eta_k=\frac{1}{(k+4)^{(2p+1)/(3p+1)}}\qquad\forall k\ge0,\label{def:eta-unknown-rate-mem}\\
&\gamma_{k,t}=\frac{\gamma_k}{t^2},\quad \theta_{k,t}=\frac{\prod_{1\le s\le p-1,s\neq t}(1-s^2/\gamma_k)}{(t^2/\gamma_k)\prod_{1\le s\le p-1,s\neq t}((t^2-s^2)/\gamma_k)}\qquad\forall 1\le t\le p-1,k\ge0,\label{def:theta-unknown-rate-mem}
\end{align}
where
\begin{align}\label{def:gmak-mem-unknow}
\gamma_k=\frac{1}{(k+4)^{2p/(3p+1)}}\qquad\forall k\ge0.    
\end{align}
Then, for any $\epsilon \in (0,1)$, it holds that $\mathbb{E}[\|\nabla f(x^{\iota_K})\|]\le \epsilon$ for all $K$ satisfying
\begin{align*}
&K\ge \max\Bigg\{\Big(\frac{4(3p+1)\widetilde{M}_{p,\alpha}}{p\epsilon}\ln\Big(\frac{4(3p+1)\widetilde{M}_{p,\alpha}}{p\epsilon}\Big)\Big)^{(3p+1)/p},\\
&\qquad\qquad\quad \Big(\frac{2(3p\alpha+\alpha)\widehat{M}_{p,\alpha}}{p(\alpha-1)\epsilon}\ln\Big(\frac{2(3p\alpha+\alpha)\widehat{M}_{p,\alpha}}{p(\alpha-1)\epsilon}\Big)\Big)^{(3p\alpha+\alpha)/(2p(\alpha-1))},5\Bigg\},
\end{align*}
where $\iota_K$ is uniformly drawn from $\{0,\ldots,K-1\}$. 
\end{theorem}

