\begin{align}
\min_{x_I\in\R^{n_I},x_T\in\R^{n_T}}  -\sum_{k=1}^m\sum_{i=1}^N\bigg(\ln\bigg(\frac{\exp(f_{x_I}(a_{ik})^Tf_{x_T}(b_{ik})/\tau)}{\sum_{j=1}^N\exp(f_{x_I}(a_{ik})^Tf_{x_T}(b_{jk})/\tau)}\bigg) + \ln\bigg(\frac{\exp(f_{x_I}(a_{ik})^Tf_{x_T}(b_{ik})/\tau)}{\sum_{j=1}^N\exp(f_{x_I}(a_{jk})^Tf_{x_T}(b_{ik})/\tau)}\bigg)\bigg),\label{multi-modal} 
