%We first present the following auxiliary lemma adapted from \cite[Theorem 6.3]{rodomanov2020smoothness}.
%\begin{lemma}\label{lem:holder-alpha}
%For any $\alpha\in(1,2]$, $\psi(w):=\|w\|^\alpha$ has a $(\alpha-1)$-Hölder continuous gradient on $\mathbb{R}^n$ with the H\"older constant $2^{2-\alpha}\alpha$. That is, $\|\nabla\psi(w_1) - \nabla\psi(w_2)\|\le 2^{2-\alpha}\alpha\|w_1-w_2\|^{\alpha-1}$ for all $w_1,w_2\in\mathbb{R}^n$.
%\end{lemma}
The following lemma provides an expansion for the $\alpha$-power of the Euclidean norm, generalizing the well-known identity $\|u + v\|^2 = \|u\|^2 + 2u^T v + \|v\|^2$ and inequality $\|u + v\|^2\le (1+c)\|u\|^2+(1+1/c)\|v\|^2$ for all $u,v\in\mathbb{R}^n$ and $c>0$. 

\begin{lemma}%\label{lem:expand-nonsquare}
For any $\alpha\in(1,2]$, it holds that
\begin{align}
&\|u+v\|^\alpha \le \|u\|^\alpha + \alpha\|u\|^{\alpha-2} u^Tv + 2\|v\|^\alpha\qquad\forall u,v\in\mathbb{R}^n,\label{open-alpha}\\
&\|u+v\|^\alpha\le (1+c)\|u\|^\alpha + (2 + (\alpha-1)^{\alpha-1}c^{1-\alpha})\|v\|^\alpha\qquad\forall u,v\in\mathbb{R}^n, c>0. \label{open-alpha-2}   
\end{align}
\end{lemma}

\begin{proof}
Let $\alpha\in(1,2]$ be arbitrarily chosen, and $\psi(w)=\|w\|^\alpha$ for all $w\in\R^n$. It follows from \cite[Theorem 6.3]{rodomanov2020smoothness} that 
\[
\|\nabla\psi(w^1) - \nabla\psi(w^2)\|\le 2^{2-\alpha}\alpha\|w^1-w^2\|^{\alpha-1} \quad \forall w^1, w^2\in\mathbb{R}^n.
\]
By this, one has that for any $u,v\in\R^n$, 
\begin{align*}
&|\psi(u+v) - \psi(u) - \nabla\psi(u)^Tv|=\Big|\int^1_0(\nabla \psi(u+tv) - \nabla \psi(u))^Tv\mathrm{d}t\Big|\\
&\le  \int^1_0\|\nabla \psi(u+tv) - \nabla \psi(u)\|\mathrm{d}t\cdot \|v\|\le 2^{2-\alpha}\alpha \int^1_0\|tv\|^{\alpha-1}\mathrm{d}t\cdot \|v\| = 2^{2-\alpha}\|v\|^\alpha,
\end{align*}
 This along with $\alpha\in(1,2]$ and the fact that $\psi(w)=\|w\|^\alpha$ and $\nabla\psi(w)=\alpha\|w\|^{\alpha-2}w$ implies that \eqref{open-alpha} holds. We next prove \eqref{open-alpha-2}. Let $\alpha^\prime=\alpha/(\alpha-1)$. By the Young's inequality, one has that for all $c>0$,
\[
\alpha\|u\|^{\alpha-2} u^Tv \le \frac{\big((c\alpha^\prime)^{1/\alpha^\prime}\big\|\|u\|^{\alpha-2} u\big\|\big)^{\alpha^\prime}}{\alpha^\prime} + \frac{\big(\alpha\|v\|/(c\alpha^\prime)^{1/\alpha^\prime}\big )^\alpha}{\alpha} =c\|u\|^\alpha + \frac{(\alpha-1)^{\alpha-1}\|v\|^\alpha}{c^{\alpha-1}},
\]
which together with \eqref{open-alpha} implies that \eqref{open-alpha-2} holds.
\end{proof}

