\begin{lemma}%\label{lem:series}
Let $\zeta(\cdot)$ be a convex univariate function. Then it holds that $\sum_{r=a}^b\zeta(r)\le \int^{b+1/2}_{a-1/2}\zeta(\tau)\mathrm{d}\tau$ for any integers $a,b$ satisfying $[a-1/2,b+1/2]\subset\mathrm{dom}\,\zeta$. Consequently,  one has 
\begin{align}
\sum_{r=a}^b \frac{1}{r^\beta} \le \left\{\begin{array}{ll}
\ln\big(b+\frac{1}{2}\big) - \ln\big(a-\frac{1}{2}\big)&\text{if }\beta=1,  \\[4pt]
\frac{1}{1-\beta}\big(\big(b+\frac{1}{2}\big)^{1-\beta} - \big(a-\frac{1}{2}\big)^{1-\beta}\big)&\text{if }\beta\in(0,1)\cup(1,+\infty).
\end{array}\right.
\label{upbd:series-ka} 
\end{align}
\end{lemma}

\begin{proof}
Let $a,b$ be integers satisfying $[a-1/2,b+1/2]\subset\mathrm{dom}\,\zeta$. Since $\zeta$ is convex, one has 
$\zeta(\tau) \geq \zeta(r)+s^T (\tau-r)$ for all $s\in\partial \zeta(r)$ and $r\in[a,b]$. It then follows that 
\[
 \int_{r-1/2}^{r+1/2}\zeta(\tau)\mathrm{d}\tau \geq  \int_{r-1/2}^{r+1/2} \big(\zeta(r)+s^T (\tau-r)\big) \mathrm{d}\tau = \zeta(r),
\]
which implies that $\sum_{r=a}^b\zeta(r)\le \sum^b_{r=a}\int_{r-1/2}^{r+1/2}\zeta(\tau)\mathrm{d}\tau=\int_{a-1/2}^{b+1/2}\zeta(\tau)\mathrm{d}\tau$.  By this and  $\zeta(\tau)=1/\tau^\beta$, one can see that \eqref{upbd:series-ka} holds. 
\end{proof}

We next provide a lemma that will be used to derive complexity bounds subsequently.

\begin{lemma}\label{lem:rate-complexity}
Let $\beta\in(0,1)$ and $u\in(0,1/e)$ be given. Then $v^{-\beta}\ln v\le 2u/\beta$ holds for all $v\ge(u^{-1}\ln(1/u))^{1/\beta}$.
\end{lemma}

\begin{proof}
Fix any $v$ satisfying $v\ge(u^{-1}\ln(1/u))^{1/\beta}$. It then follows from $u\in(0,1/e)$ that
\begin{align}\label{aux-uv-ln}
v\ge(u^{-1}\ln(1/u))^{1/\beta}> e^{1/\beta}.    
\end{align}
Let $\phi(\tau)= \tau^{-\beta}\ln \tau$. It can be verified that $\phi$ is decreasing on $(e^{1/\beta},\infty)$. By this and  \eqref{aux-uv-ln}, one has that 
\begin{align*}
v^{-\beta}\ln v = \phi(v) \le  \phi((u^{-1}\ln(1/u))^{1/\beta}) = \frac{u}{\beta} \Big(1+\frac{\ln\ln(1/u)}{\ln(1/u)}\Big)\le \frac{2u}{\beta},
\end{align*}
where the last inequality follows from $\ln\ln(1/u)\le\ln(1/u)$ due to $u\in(0,1/e)$. Hence, the conclusion of this lemma holds.
\end{proof}

