\begin{proof}
Fix any $u\in\R^n$. Let $\phi(x)=\langle \nabla f(x),u\rangle$. By this and the definition of $\nabla^{r+1} f(x)(h)^{r}$, one has
\begin{align}\label{pth-der-phi-f}
\mathcal{D}^r\phi(x)[v]^r = \langle \nabla^{r+1} f(x)(v)^r, u\rangle\qquad\forall 1\le r\le p-1, v\in\R^n.    
\end{align}
Using this and \eqref{def:pnorm}, we have
\begin{align}\label{p-p-1th-der-phi-f}
\|\mathcal{D}^{p-1}\phi(y)-\mathcal{D}^{p-1}\phi(x)\| \leq \|u\|\|\mathcal{D}^p f(y)-\mathcal{D}^p f(x)\|\qquad \forall x,y\in\R^n.
\end{align}
Fix any $x,y\in\R^n$. By Taylor's expansion, one has
\begin{align*}
&\phi(y) = \phi(x) + \sum_{r=1}^{p-2}\frac{1}{r!} \mathcal{D}^r\phi(x)[y-x]^r  + \frac{1}{(p-2)!} \int_0^1(1-t)^{p-2}\mathcal{D}^{p-1} \phi(x+t(y-x))[y-x]^{p-1}\mathrm{d}t \\
& = \phi(x) + \sum_{r=1}^{p-1}\frac{1}{r!} D^r\phi(x)[y-x]^r + \frac{1}{(p-2)!} \int_0^1(1-t)^{p-2}(\mathcal{D}^{p-1} \phi(x+t(y-x)) - \mathcal{D}^{p-1} \phi(x))[y-x]^{p-1}\mathrm{d}t.
\end{align*}
Using this, \eqref{def:pnorm}, \eqref{pth-der-phi-f}, and \eqref{p-p-1th-der-phi-f}, we obtain that 
\begin{align*}
&\Big|\Big\langle \nabla f(y) - \nabla f(x) - \sum_{r=1}^{p-1}\frac{1}{r!} \nabla^{r+1}f(x)(y-x)^r, u\Big\rangle \Big| \overset{\eqref{pth-der-phi-f}}{=} \Big|\phi(y) - \phi(x) - \sum_{r=1}^{p-1}\frac{1}{r!} \mathcal{D}^r\phi(x)[y-x]^r \Big|\\
&=\Big|\frac{1}{(p-2)!} \int_0^1(1-t)^{p-2}(\mathcal{D}^{p-1} \phi(x+t(y-x)) - \mathcal{D}^{p-1} \phi(x))[y-x]^{p-1}\mathrm{d}t\Big|\\
&\overset{\eqref{def:pnorm}}{\le} \frac{1}{(p-2)!}\|y-x\|^{p-1}\int^1_0(1-t)^{p-2}\|\mathcal{D}^{p-1} \phi(x+t(y-x)) - \mathcal{D}^{p-1} \phi(x)\|\mathrm{d}t\\
&\overset{\eqref{p-p-1th-der-phi-f}}{\leq} \frac{1}{(p-2)!}\|y-x\|^{p-1}\|u\|\int^1_0(1-t)^{p-2}\|\mathcal{D}^p f(x+t(y-x)) - \mathcal{D}^pf(x)\|\mathrm{d}t\\
&{\le} \frac{1}{(p-2)!}L_p\|y-x\|^p\|u\|\int^1_0(1-t)^{p-2}t\mathrm{d}t = \frac{1}{p!}L_p\|y-x\|^p\|u\|,
\end{align*}
where the last inequality follows from Assumption \ref{asp:high-smooth}, and the last equality is due to $\int^1_0(1-t)^{p-2}t\mathrm{d}t=1/(p(p-1))$. Taking the maximum of this inequality over all $u$ with $\|u\|\le 1$, we conclude that this lemma holds.    
\end{proof}


