\begin{proof}
Fix any $k\ge0$. It follows from \eqref{update-mk-pm} that
\begin{align}
&m^{k+1} - \nabla f(x^{k+1}) \overset{\eqref{update-mk-pm}}{=} (1- \theta_k)m^k + \theta_k G(x^{k+1};\xi^{k+1}) - \nabla f(x^{k+1}) \nonumber\\
&= (1- \theta_k) (m^k-\nabla f(x^k)) + (1-\theta_k)(\nabla f(x^k)-\nabla f(x^{k+1})) + \theta_k (G(x^{k+1};\xi^{k+1}) - \nabla f(x^{k+1})). \label{rela-mk+1-pm}
\end{align}
Observe from Algorithm \ref{alg:unf-sfom-pm} and Assumption \ref{asp:basic} that $\|x^{k+1}-x^k\|=\eta_k$, $\E_{\xi^{k+1}}[G(x^{k+1};\xi^{k+1})-\nabla f(x^{k+1})]=0$, $\E_{\xi^{k+1}}[\|G(x^{k+1};\xi^{k+1})-\nabla f(x^{k+1})\|^\alpha]\le\sigma^\alpha$, and $\|\nabla f(x^k)-\nabla f(x^{k+1})\|\leq L_1 \eta_k$.
Using these, \eqref{open-alpha}, \eqref{open-alpha-2}, and \eqref{rela-mk+1-pm}, we obtain that for all $c>0$,
\begin{align}
&\mathbb{E}_{\xi^{k+1}}[\|m^{k+1}-\nabla f(x^{k+1})\|^\alpha]\nonumber \\
&\overset{\eqref{rela-mk+1-pm}}{=}\mathbb{E}_{\xi^{k+1}}[\|(1- \theta_k) (m^k-\nabla f(x^k)) + (1-\theta_k)(\nabla f(x^k)-\nabla f(x^{k+1})) + \theta_k (G(x^{k+1};\xi^{k+1}) - \nabla f(x^{k+1}))\|^\alpha]\nonumber\\
&\overset{ \eqref{open-alpha}}{\le} \|(1- \theta_k) (m^k-\nabla f(x^k))+ (1-\theta_k)(\nabla f(x^k)-\nabla f(x^{k+1}))\|^\alpha + 2\mathbb{E}_{\xi^{k+1}}[\|\theta_k (G(x^{k+1};\xi^{k+1}) - \nabla f(x^{k+1}))\|^\alpha]\nonumber\\
&\overset{\eqref{open-alpha-2}}{\le} (1+c)(1-\theta_k)^\alpha\|m^k-\nabla f(x^k)\|^\alpha  + (2+(\alpha-1)^{\alpha-1}c^{1-\alpha})(1-\theta_k)^\alpha \|\nabla f(x^k)-\nabla f(x^{k+1})\|^\alpha + 2\sigma^\alpha\theta_k^\alpha\nonumber\\
&\le (1+c)(1-\theta_k)^\alpha\|m^k-\nabla f(x^k)\|^\alpha + L_1^\alpha(2+(\alpha-1)^{\alpha-1}c^{1-\alpha})(1-\theta_k)^\alpha\eta_k^\alpha + 2\sigma^\alpha\theta_k^\alpha,\label{vr-inter}
\end{align}
where the first inequality is due to \eqref{open-alpha} and $\E_{\xi^{k+1}}[G(x^{k+1};\xi^{k+1})-\nabla f(x^{k+1})]=0$, the second inequality is due to \eqref{open-alpha-2} and $\E_{\xi^{k+1}}[\|G(x^{k+1};\xi^{k+1})-\nabla f(x^{k+1})\|^\alpha]\le\sigma^\alpha$, and the last inequality follows from  $\|x^{k+1}-x^k\|=\eta_k$ and $\|\nabla f(x^k)-\nabla f(x^{k+1})\|\leq L_1 \eta_k$.

When $\theta_k = 1$, \eqref{ineq:vr-pm} clearly holds. For $\theta_k \in (0, 1)$, letting $c = (1 - \theta_k)^{1 - \alpha} - 1$ in \eqref{vr-inter}, and using the fact that $\alpha \in (1, 2]$, we have
\begin{align*}
c^{1-\alpha} & = ((1-\theta_k)^{1-\alpha} - 1)^{1-\alpha} = \Big(\frac{1}{(1-\theta_k)^{\alpha-1}} - 1\Big)^{1-\alpha} \le \Big(\frac{1}{1-(\alpha-1)\theta_k} - 1\Big)^{1-\alpha}\\
& =\Big(\frac{1-(\alpha-1)\theta_k}{(\alpha-1)\theta_k} \Big)^{\alpha-1} \le ((\alpha-1)\theta_k)^{1-\alpha},
\end{align*}
where the first inequality follows from $(1-\tau)^\beta\le 1-\beta\tau$ for all $\tau\in(-\infty,1)$ and $\beta\in[0,1]$. Combining this inequality with \eqref{vr-inter}, one has 
\begin{align*}
\mathbb{E}_{\xi^{k+1}}[\|m^{k+1}-\nabla f(x^{k+1})\|^\alpha]\le (1-\theta_k)\|m^k-\nabla f(x^k)\|^\alpha + L_1^\alpha(2+\theta_k^{1-\alpha})(1-\theta_k)^\alpha\eta_k^\alpha + 2\sigma^\alpha\theta_k^\alpha,
\end{align*}
which together with $\theta_k\in(0,1]$ and $\alpha\in(1,2]$ implies that \eqref{ineq:vr-pm} holds.
\end{proof}

The following lemma establishes a descent property for the potential sequence $\{\mathcal{P}_k\}$ defined below.

\begin{lemma}\label{lem:rate-pm}
Suppose that Assumption \ref{asp:basic} holds. Let $\{(x^k,m^k)\}$ be the sequence generated by Algorithm \ref{alg:unf-sfom-pm} with input parameters $\{(\eta_k,\theta_k)\}$, and $L_1$, $\sigma$, and $\alpha$ be given in Assumption \ref{asp:basic}, and let $\{{\mathcal P}_k\}$ be defined in \eqref{def:pot-pm} for $\{(x^k,m^k)\}$ and any nonincreasing positive sequence $\{p_k\}$. Then it holds that for all $k\ge0$, 
\begin{align}\label{stat-bd-pm}
\mathbb{E}_{\xi^{k+1}}[{\mathcal P}_{k+1}] \le {\mathcal P}_k- \eta_k\|\nabla f(x^k)\| + \frac{L_1}{2}\eta_k^2
+ \frac{(\alpha-1)(2\eta_k/\alpha)^{\alpha/(\alpha-1)}}{(\theta_kp_k)^{1/(\alpha-1)}}  
+  3L_1^\alpha \theta_k^{1-\alpha}\eta_k^\alpha p_k + 2\sigma^\alpha\theta_k^\alpha p_k.
\end{align}
\end{lemma}

\begin{proof}
Fix any $k\ge0$. By Lemma \ref{lem:ppt-desc} with $(x^+,x,m,\eta)=(x^{k+1},x^k,m^k,\eta_k)$, one has
\begin{align}\label{upbd-fxk+1-pm}
f(x^{k+1}) \le f(x^k) - \eta_k\|\nabla f(x^k)\| + 2\eta_k\|\nabla f(x^k) - m^k\| + \frac{L_1}{2}\eta_k^2.    
\end{align}
Combining this with \eqref{def:pot-pm} and \eqref{ineq:vr-pm}, we obtain that
\begin{align}
&\mathbb{E}_{\xi^{k+1}}[{\mathcal P}_{k+1}] \overset{\eqref{def:pot-pm}}{=} \mathbb{E}_{\xi^{k+1}}[f(x^{k+1}) + p_{k+1}\|m^{k+1} - \nabla f(x^{k+1})\|^\alpha]\nonumber\\
&\overset{\eqref{ineq:vr-pm}\eqref{upbd-fxk+1-pm}}{\le} f(x^k) - \eta_k\|\nabla f(x^k)\| + 2\eta_k\|\nabla f(x^k) - m^k\| + \frac{L_1}{2}\eta_k^2\nonumber \\
&\qquad + (1-\theta_k)p_{k+1}\|m^k-\nabla f(x^k)\|^\alpha + 3L_1^\alpha \theta_k^{1-\alpha}\eta_k^\alpha p_{k+1} + 2\sigma^\alpha\theta_k^\alpha p_{k+1}\nonumber\\
&\le f(x^k) - \eta_k\|\nabla f(x^k)\| + 2\eta_k\|\nabla f(x^k) - m^k\| + \frac{L_1}{2}\eta_k^2\nonumber\\
&\quad + (1-\theta_k)p_k\|m^k-\nabla f(x^k)\|^\alpha + 3L_1^\alpha \theta_k^{1-\alpha}\eta_k^\alpha p_k + 2\sigma^\alpha\theta_k^\alpha p_k,\label{pot-desc-ineq-pm}
\end{align}
where the last inequality follows from the fact that $\{p_k\}$ is nonincreasing. In addition, letting $\alpha^\prime=\alpha/(\alpha-1)$ and using the Young's inequality, we have
\begin{align*}
2\eta_k\|\nabla f(x^k) - m^k\| & \le \frac{\big((\alpha\theta_k p_k)^{1/\alpha} \|\nabla f(x^k) - m^k\|\big)^\alpha}{\alpha} + \frac{\big(2\eta_k/(\alpha\theta_k p_k)^{1/\alpha}\big)^{\alpha^\prime}}{\alpha^\prime}\\
&% = \theta_k p_k \|\nabla f(x^k) - m^k\|^\alpha + \frac{(2\eta_k/(\alpha\theta_k p_k)^{1/\alpha})^{\alpha^\prime}}{\alpha^\prime} 
= \theta_k p_k \|\nabla f(x^k) - m^k\|^\alpha + \frac{(\alpha-1)(2\eta_k)^{\alpha/(\alpha-1)}}{\alpha^{\alpha/(\alpha-1)}(\theta_kp_k)^{1/(\alpha-1)}}.
\end{align*}
This together with \eqref{pot-desc-ineq-pm} implies that
\begin{align*}
&\mathbb{E}_{\xi^{k+1}}[{\mathcal P}_{k+1}]  \le f(x^k) + p_k\|m^k-\nabla f(x^k)\|^\alpha - \eta_k\|\nabla f(x^k)\| + \frac{L_1}{2}\eta_k^2 \\
&\qquad\qquad\qquad + \frac{(\alpha-1)(2\eta_k)^{\alpha/(\alpha-1)}}{\alpha^{\alpha/(\alpha-1)}(\theta_kp_k)^{1/(\alpha-1)}} + 3L_1^\alpha \theta_k^{1-\alpha}\eta_k^\alpha p_k + 2\sigma^\alpha\theta_k^\alpha p_k.
\end{align*}
The conclusion  \eqref{stat-bd-pm} then follows from this and  \eqref{def:pot-pm}.
\end{proof}

We are now ready to prove Theorem \ref{thm:s-rate-pm}.

\begin{proof}[\textbf{Proof of Theorem \ref{thm:s-rate-pm}}]
Let $\{(x^k,m^k)\}$ be generated by Algorithm \ref{alg:unf-sfom-pm} with $\{(\eta_k,\theta_k)\}$ given in \eqref{pm-eta-theta}, and 
