\begin{align}\label{def:pk-pm}
p_k= (k+1)^{(\alpha^2-3\alpha+2)/(3\alpha-2)} \qquad\forall k\ge0.  
\end{align}
Since $\alpha\in(1,2]$, one can see that $\{p_k\}$ is nonincreasing. Also, observe from \eqref{pm-eta-theta} that $\{\eta_k\}\subset(0,+\infty)$ and $\{\theta_k\}\subset(0,1]$. Hence, $\{(\eta_k,\theta_k,p_k)\}$ satisfies the assumptions in Lemma \ref{lem:rate-pm} and Algorithm \ref{alg:unf-sfom-pm}. In addition, by \eqref{def:pot-pm} and \eqref{def:pk-pm}, one has that
%\begin{align}
%&\mathbb{E}_{\xi^0}[{\mathcal P}_0]= f(x^0)+p_0\mathbb{E}_{\xi^0}[\|m^0-\nabla f(x^0)\|^\alpha]= f(x^0) + \mathbb{E}_{\xi^0}[\|G(x^0;\xi^0)-\nabla f(x^0)\|^\alpha]\le f(x^0)+\sigma^\alpha,\label{upbd-exp-P0-pm}\\    
%&\mathbb{E}_{\{\xi^k\}_{k=0}^K}[{\mathcal P}_K]= \mathbb{E}_{\{\xi^k\}_{k=0}^K}[f(x^K)+p_K\|m^K-\nabla f(x^K)\|^\alpha]\ge \mathbb{E}_{\{\xi^k\}_{k=0}^K}[f(x^K)] \ge f_{\mathrm{low}}.\label{lwbd-exp-Pk-pm}
%\end{align}
\begin{align}
&\mathbb{E}[{\mathcal P}_0]= f(x^0)+p_0\mathbb{E}[\|m^0-\nabla f(x^0)\|^\alpha]= f(x^0) + \mathbb{E}[\|G(x^0;\xi^0)-\nabla f(x^0)\|^\alpha]\le f(x^0)+\sigma^\alpha,\label{upbd-exp-P0-pm}\\    
&\mathbb{E}[{\mathcal P}_K]= \mathbb{E}[f(x^K)+p_K\|m^K-\nabla f(x^K)\|^\alpha]\ge \mathbb{E}[f(x^K)] \ge f_{\mathrm{low}}.\label{lwbd-exp-Pk-pm}
\end{align}
Taking expectation on both sides of \eqref{stat-bd-pm} with respect to $\{\xi^i\}_{i=0}^{k+1}$, we have
\begin{align*}
\mathbb{E}[{\mathcal P}_{k+1}] \le \mathbb{E}[{\mathcal P}_k]- \eta_k\mathbb{E}[\|\nabla f(x^k)\|] + \frac{L_1}{2}\eta_k^2
+ \frac{(\alpha-1)(2\eta_k/\alpha)^{\alpha/(\alpha-1)}}{(\theta_kp_k)^{1/(\alpha-1)}}  
+  3L_1^\alpha \theta_k^{1-\alpha}\eta_k^\alpha p_k + 2\sigma^\alpha\theta_k^\alpha p_k\quad\forall k\ge0.
\end{align*}
Summing up this inequality over $k=0,\ldots,K-1$, and using \eqref{upbd-exp-P0-pm} and \eqref{lwbd-exp-Pk-pm}, we obtain that for all $K\ge1$,
\begin{align}
&f_{\mathrm{low}}\overset{\eqref{lwbd-exp-Pk-pm}}{\le} \mathbb{E}[{\mathcal P}_K]\nonumber \\
&\le \E[{\mathcal P}_0] - \sum_{k=0}^{K-1}\eta_k\mathbb{E}[\|\nabla f(x^k)\|] + \sum_{k=0}^{K-1}\Big(\frac{L_1}{2}\eta_k^2 + \frac{(\alpha-1)(2\eta_k)^{\alpha/(\alpha-1)}}{\alpha^{\alpha/(\alpha-1)}(\theta_kp_k)^{1/(\alpha-1)}} + 3L_1^\alpha \theta_k^{1-\alpha}\eta_k^\alpha p_k + 2\sigma^\alpha\theta_k^\alpha p_k\Big)\nonumber\\
&\overset{\eqref{upbd-exp-P0-pm}}{\le} f(x^0) + \sigma^\alpha - \eta_{K-1}\sum_{k=0}^{K-1}\mathbb{E}[\|\nabla f(x^k)\|] + \sum_{k=0}^{K-1}\Big(\frac{L_1}{2}\eta_k^2 + \frac{(\alpha-1)(2\eta_k)^{\alpha/(\alpha-1)}}{\alpha^{\alpha/(\alpha-1)}(\theta_kp_k)^{1/(\alpha-1)}} + 3L_1^\alpha \theta_k^{1-\alpha}\eta_k^\alpha p_k + 2\sigma^\alpha\theta_k^\alpha p_k\Big),\label{rear-pot-desc-pm}
\end{align}
where the last inequality follows from \eqref{upbd-exp-P0-pm} and the fact that $\{\eta_k\}$ is nonincreasing. Rearranging the terms in 
\eqref{rear-pot-desc-pm}, and using \eqref{M1a}, \eqref{pm-eta-theta}, and \eqref{def:pk-pm}, we obtain that for all $K\ge3$, 
\begin{align*}
&\frac{1}{K}\sum_{k=0}^{K-1}\mathbb{E}[\|\nabla f(x^k)\|]\\
&\overset{\eqref{rear-pot-desc-pm}}{\le}\frac{f(x^0) - f_{\mathrm{low}} + \sigma^\alpha}{K\eta_{K-1}} + \frac{1}{K\eta_{K-1}}\sum_{k=0}^{K-1}\Big(\frac{L_1}{2}\eta_k^2+\frac{(\alpha-1)(2\eta_k)^{\alpha/(\alpha-1)}}{\alpha^{\alpha/(\alpha-1)}(\theta_kp_k)^{1/(\alpha-1)}} + 3L_1^\alpha \theta_k^{1-\alpha}\eta_k^\alpha p_k + 2\sigma^\alpha\theta_k^\alpha p_k\Big)  \\
&\overset{\eqref{pm-eta-theta}\eqref{def:pk-pm}}{=} \frac{f(x^0) - f_{\mathrm{low}} + \sigma^\alpha}{K^{(\alpha-1)/(3\alpha-2)}} +\frac{1}{K^{(\alpha-1)/(3\alpha-2)}}\sum_{k=0}^{K-1}\Big(\frac{L_1}{2(k+1)^{2(2\alpha-1)/(3\alpha-2)}} + \frac{(\alpha-1)(2/\alpha)^{\alpha/(\alpha-1)} + 3L_1^\alpha+2\sigma^\alpha}{k+1}\Big) \\
% &\le \frac{f(x^0) - f_{\mathrm{low}} + \sigma^\alpha + 2L_1}{K^{(\alpha-1)/(3\alpha-2)}} + \frac{((\alpha-1)(2/\alpha)^{\alpha/(\alpha-1)} + 3L_1^\alpha+2\sigma^\alpha)\ln(2K+1)}{K^{(\alpha-1)/(3\alpha-2)}}\\
&\le\frac{2(f(x^0) - f_{\mathrm{low}} + \sigma^\alpha + L_1 + (\alpha-1)(2/\alpha)^{\alpha/(\alpha-1)} + 3L_1^\alpha+2\sigma^\alpha)\ln K}{K^{(\alpha-1)/(3\alpha-2)}}\overset{\eqref{M1a}}{=}\frac{M_{1,\alpha}\ln K}{K^{(\alpha-1)/(3\alpha-2)}},
\end{align*}
% where the third inequality follows from $\sum_{k=0}^{K-1}1/(k+1)\le \ln(2K+1)$ and $\sum_{k=0}^{K-1}1/(k+1)^{2(2\alpha-1)/(3\alpha-2)}\le(3\alpha-2) 2^{\alpha/(3\alpha-2)}/\alpha < 4$
% due to \eqref{upbd:series-ka} with $(a,b)=(1,K)$, $\beta=1$ or $2(2\alpha-1)/(3\alpha-2)$, and  $(3\alpha-2)/\alpha \in (1,2]$, and the last inequality is due to $\ln(2K+1)\le 2\ln K$ for all $K\ge 3$. 
where the second inequality follows from $\sum_{k=0}^{K-1}1/(k+1)\le 2\ln K$ due to \eqref{upbd:series-ka} and $K\ge 3$, and $\sum_{k=0}^{K-1}1/(k+1)^{2(2\alpha-1)/(3\alpha-2)}\le(3\alpha-2) 2^{\alpha/(3\alpha-2)}/\alpha < 4$ due to \eqref{upbd:series-ka} and $(3\alpha-2)/\alpha \in (1,2]$. Recall that $\iota_K$ is uniformly selected from $\{0,\ldots,K-1\}$. It then follows from this and the above inequality that
\begin{align}\label{pre-upbd-pm}
\E[\|\nabla f(x^{\iota_K})\|] = \frac{1}{K}\sum_{k=0}^{K-1}\mathbb{E}[\|\nabla f(x^k)\|] \le \frac{M_{1,\alpha}\ln K}{K^{(\alpha-1)/(3\alpha-2)}}\qquad\forall K\ge 3.
\end{align}
In addition, by Lemma \ref{lem:rate-complexity} with $(\beta,u,v)=((\alpha-1)/(3\alpha-2),(\alpha-1)\epsilon/(2(3\alpha-2)M_{1,\alpha}),K)$, one can see that 
\begin{align*}
K^{-(\alpha-1)/(3\alpha-2)}\ln K\le \frac{\epsilon}{M_{1,\alpha}}\qquad\forall K\ge\Big(\frac{2(3\alpha-2)M_{1,\alpha}}{(\alpha-1)\epsilon}\ln\Big(\frac{2(3\alpha-2)M_{1,\alpha}}{(\alpha-1)\epsilon}\Big)\Big)^{(3\alpha-2)/(\alpha-1)},    
\end{align*}
which together with \eqref{pre-upbd-pm} implies that Theorem \ref{thm:s-rate-pm} holds.
\end{proof}

We next prove Theorem \ref{thm:un-s-rate-pm}.

\begin{proof}[\textbf{Proof of Theorem \ref{thm:un-s-rate-pm}}]
Let $\{(x^k,m^k)\}$ be generated by Algorithm \ref{alg:unf-sfom-pm} with $\{(\eta_k,\theta_k)\}$ given in \eqref{pm-eta-theta-o}, and 
$\{{\mathcal P}_k\}$ be defined in \eqref{def:pot-pm} with such $\{(x^k,m^k)\}$ and the following $\{p_k\}$:
\begin{align}\label{pk-pm-unk}
p_k= (k+1)^{(2\alpha^2-5\alpha+2)/(4\alpha)}\qquad\forall k\ge0.    
\end{align}
Since $\alpha\in(1,2]$, one can see that $\{p_k\}$ is nonincreasing. Also, observe from \eqref{pm-eta-theta-o} that $\{\eta_k\}\subset(0,+\infty)$ and $\{\theta_k\}\subset(0,1]$. Hence, $\{(\eta_k,\theta_k,p_k)\}$ defined in \eqref{pm-eta-theta-o} and \eqref{pk-pm-unk} satisfies the assumptions in Lemma \ref{lem:rate-pm} and Algorithm \ref{alg:unf-sfom-pm}. By \eqref{pm-eta-theta-o}, \eqref{pk-pm-unk}, and similar arguments as those for deriving \eqref{rear-pot-desc-pm}, one has that for all $K\ge1$, 
\begin{align*}
f_{\mathrm{low}}\le f(x^0) + \sigma^\alpha - \eta_{K-1}\sum_{k=0}^{K-1}\mathbb{E}[\|\nabla f(x^k)\|]+ \sum_{k=0}^{K-1}\Big(\frac{L_1}{2}\eta_k^2 + \frac{(\alpha-1)(2\eta_k)^{\alpha/(\alpha-1)}}{\alpha^{\alpha/(\alpha-1)}(\theta_kp_k)^{1/(\alpha-1)}} + 3L_1^\alpha \theta_k^{1-\alpha}\eta_k^\alpha p_k + 2\sigma^\alpha\theta_k^\alpha p_k\Big).
\end{align*}
Rearranging the terms of this inequality, and using \eqref{M1a-o}, \eqref{pm-eta-theta-o}, and \eqref{pk-pm-unk}, we obtain that for all $K\ge3$,
\begin{align*}
&\frac{1}{K}\sum_{k=0}^{K-1}\mathbb{E}[\|\nabla f(x^k)\|]\\
&\le \frac{f(x^0) - f_{\mathrm{low}} + \sigma^\alpha}{K\eta_{K-1}} + \frac{1}{K\eta_{K-1}}\sum_{k=0}^{K-1}\Big(\frac{L_1}{2}\eta_k^2+\frac{(\alpha-1)(2\eta_k)^{\alpha/(\alpha-1)}}{\alpha^{\alpha/(\alpha-1)}(\theta_kp_k)^{1/(\alpha-1)}} + 3L_1^\alpha \theta_k^{1-\alpha}\eta_k^\alpha p_k + 2\sigma^\alpha\theta_k^\alpha p_k\Big)\\
&\overset{\eqref{pm-eta-theta-o}\eqref{pk-pm-unk}}{=}\frac{f(x^0) - f_{\mathrm{low}} + \sigma^\alpha}{K^{1/4}} + \frac{1}{K^{1/4}}\sum_{k=0}^{K-1}\Big(\frac{L_1}{2(k+1)^{3/2}} + \frac{(\alpha-1)(2/\alpha)^{\alpha/(\alpha-1)} + 2\sigma^\alpha}{(k+1)^{(5\alpha-2)/(4\alpha)}}  + \frac{3L_1^\alpha}{(k+1)^{(7\alpha - \alpha^2 - 2)/(4\alpha)}}\Big)\\
&\le\frac{f(x^0) - f_{\mathrm{low}} + \sigma^\alpha}{K^{1/4}} + \frac{1}{K^{1/4}}\sum_{k=0}^{K-1}\Big(\frac{L_1/2 + 3L_1^\alpha + ((\alpha-1)(2/\alpha)^{\alpha/(\alpha-1)} + 2\sigma^\alpha)K^{(2-\alpha)/(4\alpha)}}{k+1} \Big) \\
% &\le \frac{f(x^0) - f_{\mathrm{low}} + \sigma^\alpha + (L_1/2 + 3L_1^\alpha + ((\alpha-1)(2/\alpha)^{\alpha/(\alpha-1)} + 2\sigma^\alpha)K^{(2-\alpha)/(4\alpha)})\ln(2K+1)}{K^{1/4}}\\
&\le \frac{2(f(x^0) - f_{\mathrm{low}} + \sigma^\alpha + L_1/2 + 3L_1^\alpha)\ln K}{K^{1/4}} + \frac{2((\alpha-1)(2/\alpha)^{\alpha/(\alpha-1)} + 2\sigma^\alpha)\ln K}{K^{(\alpha-1)/(2\alpha)}} \\
&\overset{\eqref{M1a-o}}{=}\frac{\widetilde{M}_{1,\alpha}\ln K}{K^{1/4}} + \frac{\widehat{M}_{1,\alpha}\ln K}{K^{(\alpha-1)/(2\alpha)}},
\end{align*}
where the second inequality follows from $(5\alpha-2)/(4\alpha)\le1$ and $(7\alpha - \alpha^2 - 2)/(4\alpha)\ge1$ due to $\alpha\in(1,2]$, and the last inequality follows from $\sum_{k=0}^{K-1}1/(k+1)\le 2\ln K$ due to \eqref{upbd:series-ka} and $K\ge 3$. Recall that $\iota_K$ is uniformly selected from $\{0,\ldots,K-1\}$. It follows from this and the above inequality that
\begin{align}\label{ave-bd-unknow-pm}
\E[\|\nabla f(x^{\iota_K})\|] = \frac{1}{K}\sum_{k=0}^{K-1}\mathbb{E}[\|\nabla f(x^k)\|] \le \frac{\widetilde{M}_{1,\alpha}\ln K}{K^{1/4}} + \frac{\widehat{M}_{1,\alpha}\ln K}{K^{(\alpha-1)/(2\alpha)}}\qquad\forall K\ge 3.
\end{align}
In addition, by Lemma \ref{lem:rate-complexity} with $(\beta,u,v)=(1/4,\epsilon/(16\widetilde{M}_{1,\alpha}),K)$ and $(\beta,u,v)=((\alpha-1)/(2\alpha),(\alpha-1)\epsilon/(8\alpha\widehat{M}_{1,\alpha}),K)$, one can see that
\begin{align*}
&K^{-1/4}\ln K\le \frac{\epsilon}{2\widetilde{M}_{1,\alpha}}\qquad\forall K\ge\Big(\frac{16\widetilde{M}_{1,\alpha}}{\epsilon}\ln\Big(\frac{16\widetilde{M}_{1,\alpha}}{\epsilon}\Big)\Big)^{4},\\
&K^{-(\alpha-1)/(2\alpha)}\ln K\le \frac{\epsilon}{2\widehat{M}_{1,\alpha}}\qquad\forall K\ge\Big(\frac{8\alpha\widehat{M}_{1,\alpha}}{(\alpha-1)\epsilon}\ln\Big(\frac{8\alpha\widehat{M}_{1,\alpha}}{(\alpha-1)\epsilon}\Big)\Big)^{2\alpha/(\alpha-1)},
\end{align*}
which together with \eqref{ave-bd-unknow-pm} imply that Theorem \ref{thm:un-s-rate-pm} holds.
\end{proof}


\subsection{Proof of the main results in Section \ref{subsec:nsgd-mem}}\label{subsec:pf-mem}

In this subsection, we first establish several technical lemmas and then use them to prove Theorems \ref{thm:known-rate-mem} and \ref{thm:unknown-rate-mem}.  

Before proceeding, we present the well-known Weierstrass product inequalities (see, e.g., \cite{klamkin1970extensions}). For any given $\{a_t\}_{t=1}^m\subset(0,1)$, it holds that 
\begin{align}\label{W-ineq}
1 - \sum_{t=1}^m a_t  \le \prod_{t=1}^m(1-a_t) \le \frac{1}{1 + \sum_{t=1}^m a_t}.
\end{align}

We next present an auxiliary lemma that will be used subsequently.

\begin{lemma}\label{lem:inf-prod-tool}
$\prod_{s\ge1,s\neq t}(1- t^2/s^2)=(-1)^{t-1}/2$ holds for any positive integer $t$.
\end{lemma}

\begin{proof}
Fix any positive integer $t$. Let $\phi(a)=\prod_{s\ge1,s\neq t}(1- a^2/s^2)$ for any $a\geq 0$. Observe that the sequence $\{u_r\}$ is decreasing and $u_r\geq 0$ when $r\ge a+1$, where $u_r=\prod_{a+1\le s\le r,s\neq t}(1-a^2/s^2)$. This implies that $\phi(a)$ is well-defined for all $a\geq 0$. In addition, it is well-known that the normalized sinc function 
$\sin(\pi y)/(\pi y)$ can be represented as the infinite product $\prod_{s=1}^\infty(1-y^2/s^2)$ for all $y\in\R$. By this, one can see that
\begin{align*}%\label{func-express}
\phi(a) = \frac{\prod_{s=1}^{\infty}(1-a^2/s^2)}{1-a^2/t^2} = \frac{\sin(\pi a)}{\pi a(1-a^2/t^2)}\qquad\forall a\neq t.  
\end{align*}
It then follows that
\begin{align}\label{lpt-rule}
\lim_{a\to t}\phi(a) = \lim_{a\to t}\frac{\sin(\pi a)}{\pi a(1-a^2/t^2)} = \lim_{a\to t}\frac{\cos(\pi a)}{ 1 - 3a^2/t^2} = \frac{(-1)^{t-1}}{2},
\end{align}
where the second equality is due to L'H\^opital's rule. Thus, to prove this lemma, it suffices to show that $\phi(a)$ is continuous at $a=t$. To this end, we define a sequence of functions $\{\phi_r\}$ as follows: 
\begin{align*}
\phi_r(a)=\prod_{1\le s\le r, s\neq t}(1- a^2/s^2)\qquad\forall a \geq 0 
\end{align*}
for each $r\ge1$.  We next show that $\phi_r$ converges uniformly to $\phi$ on $[0,2t]$. Indeed, let $R \in [4t, \infty)$ be arbitrarily chosen, and fix any $r_1, r_2$ satisfying $r_2>r_1>R$. Observe that
\begin{align}\label{cauchy-seq}
|\phi_{r_1}(a) - \phi_{r_2}(a)| = \Big(1 - \prod_{r_1+1\le s\le r_2} (1-a^2/s^2)\Big)\Big|\prod_{1\le s\le r_1, s\neq t} (1-a^2/s^2)\Big|\qquad\forall a\in[0,2t].   
\end{align}
In addition, one has
\begin{align*}
\prod_{r_1+1\le s\le r_2} (1-a^2/s^2)\overset{\eqref{W-ineq}}{\ge} 1 - \sum_{s = r_1+1}^\infty (a^2/s^2) \ge 1 -  \sum_{s = r_1+1}^\infty \frac{a^2}{s(s-1)} = 1 - \frac{a^2}{r_1} \ge 1 - \frac{a^2}{R}\qquad\forall a\in[0,2t],
\end{align*}
which, together with \eqref{cauchy-seq} and $r_2>r_1>R$, implies that 
\begin{align*}
&|\phi_{r_1}(a) - \phi_{r_2}(a)| \le \frac{a^2|\prod_{1\le s\le r_1, s\neq t} (1-a^2/s^2)|}{R} \\
&\le  \frac{a^2\prod_{1\le s\le\lceil a\rceil-1, s\neq t} (a^2/s^2-1)}{R} \le \frac{4t^2\prod_{1\le s\le 2t-1}(4t^2/s^2 - 1)}{R} \qquad\forall a\in[0,2t],\footnotemark
\end{align*}
\footnotetext{$\prod_{1\le s\le\lceil a\rceil-1, s\neq t} (a^2/s^2-1)$ is set to $1$ if $a\in[0,1]$.}

\noindent where the second inequality follows from $(1-a^2/s^2)\in[0,1]$ for all $s\ge\lceil a\rceil$, and the last inequality is due to $a\le 2t$. By this and the choice of $r_1$, $r_2$, and $R$, one can conclude that $\{\phi_r\}$ converges uniformly to $\phi$ on $[0,2t]$, which together with the continuity of $\phi_r$ for each $r\geq 1$ implies that $\phi$ is continuous on $[0,2t]$. Hence, one has $\phi(t)=
\lim_{a\to t}\phi(a)$, which along with \eqref{lpt-rule} and the definition of $\phi$ implies that this lemma holds.
\end{proof}

