Fix any $k\ge0$. We first prove that $\{(\gamma_{k,t},\theta_{k,t})\}$ satisfies \eqref{pth-lss}. For convenience, we denote the coefficient matrix in \eqref{pth-lss} as
\begin{align*}
\Gamma = \begin{bmatrix}
1/\gamma_{k,1} & 1/\gamma_{k,2} & \cdots & 1/\gamma_{k,q}\\ 
1/\gamma_{k,1}^2 & 1/\gamma_{k,2}^2 & \cdots & 1/\gamma_{k,q}^2\\ 
\vdots&\vdots&\vdots & \vdots\\
1/\gamma_{k,1}^q & 1/\gamma_{k,2}^q & \cdots & 1/\gamma_{k,q}^q
\end{bmatrix}\in\R^{q\times q}.
\end{align*} 
In addition, we define a matrix $V\in\R^{q\times q}$, whose $t$-th row $[v_{t1}\ \cdots\ v_{tq}]$ consists of the coefficients of the polynomial
\begin{align*}%\label{def:ht-alpha}
h_t(\alpha) = \frac{\alpha\prod_{1\le s\le q, s\neq t}(\alpha-1/\gamma_{k,s})}{(1/\gamma_{k,t})\prod_{1\le s\le q, s\neq t}(1/\gamma_{k,t}-1/\gamma_{k,s})}=v_{t1}\alpha + v_{t2}\alpha^2 + \cdots + v_{tq}\alpha^q\qquad \forall 1\le t\le q,    
\end{align*}
which satisfies $h_t(1/\gamma_{k,t})=1$ and $h_t(1/\gamma_{k,s})=0$ for all $s\neq t$. By the definitions of $h_t$, $\Gamma$, and $V$, one has 
\begin{align*}
V\Gamma & = \begin{bmatrix}
\sum_{s=1}^q v_{1s}/\gamma_{k,1}^s& \sum_{s=1}^q v_{1s}/\gamma_{k,2}^s&\cdots& \sum_{s=1}^q v_{1s}/\gamma_{k,q}^s\\
\sum_{s=1}^q v_{2s}/\gamma_{k,1}^s& \sum_{s=1}^q v_{2s}/\gamma_{k,2}^s&\cdots& \sum_{s=1}^q v_{2s}/\gamma_{k,q}^s\\
\vdots&\vdots&\vdots&\vdots\\
\sum_{s=1}^q v_{qs}/\gamma_{k,1}^s& \sum_{s=1}^q v_{qs}/\gamma_{k,2}^s&\cdots& \sum_{s=1}^q v_{qs}/\gamma_{k,q}^s
\end{bmatrix}\\
& =     \begin{bmatrix}
h_1(1/\gamma_{k,1})& h_1(1/\gamma_{k,2}) &\cdots& h_1(1/\gamma_{k,q})\\
h_2(1/\gamma_{k,1})& h_2(1/\gamma_{k,2}) &\cdots& h_2(1/\gamma_{k,q})\\
\vdots&\vdots&\vdots&\vdots\\
h_q(1/\gamma_{k,1})& h_q(1/\gamma_{k,2}) &\cdots& h_q(1/\gamma_{k,q})
\end{bmatrix} = I,
\end{align*}
where $I$ is the $q\times q$ identity matrix. Hence, we have  $V=\Gamma^{-1}$. In view of this and the definition of $V$, one can see that the solution to \eqref{pth-lss} is unique and can be written as
\begin{align}\label{pf-exp-thetakt-ht}
\begin{bmatrix}
\theta_{k,1}\\
\theta_{k,2}\\
\vdots\\
\theta_{k,q}
\end{bmatrix} = V\begin{bmatrix}
1\\
1\\
\vdots\\
1
\end{bmatrix}  = \begin{bmatrix}
h_1(1)\\
h_2(1)\\
\vdots\\
h_q(1)
\end{bmatrix},
\end{align}
which together with the definition of $h_t$ implies that $\{(\gamma_{k,t},\theta_{k,t})\}$ satisfies \eqref{pth-lss}.

To prove the first relation in \eqref{two-ipt-ppt-theta-2}, we first establish the following equality:
\begin{align}\label{claim:sum-theta}
\sum_{t=1}^q\theta_{k,t} =1- \frac{\prod_{t=1}^q(1/\gamma_{k,t} - 1)}{\prod_{t=1}^q1/\gamma_{k,t}}.
\end{align}
Notice from \eqref{pf-exp-thetakt-ht} that $\theta_{k,t}=h_t(1)$ for each $1\le t\le q$.
%where $\{c_{st}\}_{1\le s\le q}$ are coefficients of the polynomial $h_t(\alpha)$. 
Let $h(\alpha)=\sum_{t=1}^qh_t(\alpha)$. It then follows that 
\begin{align}\label{sum-theta-kt}
\sum_{t=1}^q\theta_{k,t} = \sum_{t=1}^q h_t(1) = h(1).    
\end{align}
Also, observe that $h_t(0)=0$ for $1\leq t \leq q$. By this,  $h_t(1/\gamma_{k,t})=1$ and $h_t(1/\gamma_{k,s})=0$ for all $1\le s\le q$ and $s\neq t$, one can see that $h$ satisfies $h(0)=0$ and $h(1/\gamma_{k,t})=1$ for all $1\le t\le q$. 
% Note that the interpolation of an $n$th-degree polynomial at $n+1$ distinct points is always unique. 
Using these and the fact that $1/\gamma_{k,t}$, $1\le t\le q$, are distinct, we conclude that $h$ is uniquely given by 
\begin{align*}
h(\alpha) = 1- \frac{\prod_{t=1}^q(1/\gamma_{k,t}-\alpha)}{\prod_{t=1}^q1/\gamma_{k,t}},
\end{align*}
which along with \eqref{sum-theta-kt} implies that \eqref{claim:sum-theta} holds as desired.

We are now ready to prove the first relation in \eqref{two-ipt-ppt-theta-2}. Substituting the definition of $\{\gamma_{k,t}\}$ given in \eqref{unk-theatkt} into \eqref{claim:sum-theta}, we obtain
\begin{align}\label{sum-theatkt}
\sum_{t=1}^q\theta_{k,t} %=1- \frac{\prod_{t=1}^q(1/\gamma_{k,t} - 1)}{\prod_{t=1}^q1/\gamma_{k,t}} 
\overset{\eqref{unk-theatkt}}{=} 1 - \frac{\prod_{1\le t\le q}(t^2/\gamma_k - 1)}{\prod_{1\le t\le q}(t^2/\gamma_k)} = 1 - \prod_{1\le t\le q}\Big(1-\frac{\gamma_k}{t^2}\Big).    
\end{align}
%We next show that \eqref{two-ipt-ppt-theta-2} holds. To this end,
It follows from \eqref{W-ineq} that
\begin{align*}
1 - \gamma_k\sum_{t=1}^q\frac{1}{t^2} \le \prod_{1\le t\le q}\Big(1 - \frac{\gamma_k}{t^2}\Big) \le \frac{1}{1 + \gamma_k\sum_{t=1}^{q}(1/t^2)}.   
\end{align*}
Using these, \eqref{sum-theatkt}, and the identity $\sum_{t=1}^\infty(1/t^2)=\pi^2/6$, we obtain that
\begin{align*}
\frac{\gamma_k}{1 + \pi^2/6}< \frac{\gamma_k\sum_{t=1}^q(1/t^2) }{1 + \gamma_k\sum_{t=1}^q(1/t^2) }\le \sum_{t=1}^q\theta_{k,t}\le \gamma_k\sum_{t=1}^q\frac{1}{t^2}\le \frac{\pi^2\gamma_k}{6} < 2\gamma_k,
\end{align*}
where the first inequality is due to $\gamma_k\sum_{t=1}^q(1/t^2) < \pi^2/6$ and $\sum_{t=1}^q(1/t^2)\geq 1$. The above inequalities along with $\gamma_k\in(0,1/2]$ implies that the first relation in \eqref{two-ipt-ppt-theta-2} holds. In addition, by \eqref{unk-theatkt}, $\gamma_k\in(0,1/2]$, and Lemma \ref{lem:inf-prod-tool}, one can see that for all $1\le t\le q$,
\begin{align*}
|\theta_{k,t}| & = \frac{\prod_{1\le s\le q}(s^2/\gamma_k - 1)}{\prod_{1\le s\le q}(s^2/\gamma_k)} \cdot \frac{\prod_{1\le s\le q, s\neq t}(s^2/\gamma_k)}{|\prod_{1\le s\le q, s\neq t}((t^2-s^2)/\gamma_k)|}\cdot \frac{1}{t^2/\gamma_k - 1}\\
&= \frac{\prod_{1\le s\le q}(1 -\gamma_k/s^2)}{|\prod_{1\le s\le q, s\neq t}(t^2/s^2-1)|} \cdot \frac{1}{t^2/\gamma_k - 1}\le \frac{\prod_{1\le s\le q}(1 -\gamma_k/s^2)}{|\prod_{s\ge1, s\neq t}(t^2/s^2-1)|} \cdot \frac{1}{t^2/\gamma_k - 1} \\
&= \frac{2\prod_{1\le s\le q}(1 -\gamma_k/s^2)}{t^2/\gamma_k - 1} \le \frac{2}{t^2/\gamma_k - 1} \le \frac{4\gamma_k}{t^2},
\end{align*}
where the first inequality is due to $|\prod_{s\ge q+1}(t^2/s^2-1)|\le1$, the third equality follows from Lemma \ref{lem:inf-prod-tool}, the second inequality is due to $\prod_{1\le s\le q}(1 -\gamma_k/s^2)\in(0,1)$, and the last inequality is due to $\gamma_k\in(0,1/2]$ and $t\ge1$. Hence, the second relation in \eqref{two-ipt-ppt-theta-2} also holds, which completes the proof of this lemma.
\end{proof}

The next lemma shows that $\{(\gamma_{k,t},\theta_{k,t})\}$ satisfying \eqref{pth-lss} can lead to the following important identity that will be used for the subsequent analysis.

\begin{lemma}%\label{lem:apx-ipt}
Suppose that Assumptions \ref{asp:basic} and \ref{asp:high-smooth} hold. Let $\Rp(\cdot,\cdot)$ be defined in \eqref{def:taylor-res}, and $\{x^k\}$ and $\{z^{k,t}\}$ be generated by Algorithm \ref{alg:unf-sfom} with input parameters $q=p-1$ and $\{(\gamma_{k,t},\theta_{k,t})\}$ satisfying \eqref{pth-lss}, where $p$ is given in Assumption \ref{asp:high-smooth}. Then it holds that for all $k\geq 0$, 
\begin{align}
\nabla f(x^{k+1})= \Big(1 - \sum_{t=1}^{p-1}\theta_{k,t}\Big)\nabla f(x^k) + \sum_{t=1}^{p-1}\theta_{k,t}\nabla f(z^{k+1,t}) + \Rp(x^{k+1},x^k) - \sum_{t=1}^{p-1}\theta_{k,t}\Rp(z^{k+1,t},x^k).\label{idtt-from-high-smth}
\end{align}
\end{lemma}

\begin{proof}
Fix any $k\ge0$. It follows from \eqref{update-zk} with $q=p-1$ that
\begin{align}\label{extra-rela}
z^{k+1,t}-x^k = \frac{1}{\gamma_{k,t}}(x^{k+1}-x^k)\qquad\forall 1\le t\le p-1.   
\end{align}
By this and \eqref{pth-lss}, one has that 
\begin{align*}
&\nabla f(x^{k+1}) \overset{\eqref{pth-lss}}{=} \nabla f(x^{k+1}) - \sum_{r=2}^p\Big(\Big(1-\sum_{t=1}^{p-1}\frac{\theta_{k,t}}{\gamma_{k,t}^{r-1}}\Big)\frac{1}{(r-1)!}\nabla^r f(x^k)(x^{k+1}-x^k)^{r-1}\Big)\\
&=\nabla f(x^{k+1}) - \sum_{r=2}^p\frac{1}{(r-1)!}\nabla^r f(x^k)(x^{k+1}-x^k)^{r-1} + \sum_{t=1}^{p-1} \sum_{r=2}^p\frac{\theta_{k,t}}{(r-1)!\gamma_{k,t}^{r-1}}\nabla^r f(x^k)(x^{k+1}-x^k)^{r-1}\\
&\overset{\eqref{extra-rela}}{=}\nabla f(x^{k+1}) - \sum_{r=2}^p\frac{1}{(r-1)!}\nabla^r f(x^k)(x^{k+1}-x^k)^{r-1} + \sum_{t=1}^{p-1} \sum_{r=2}^p\frac{\theta_{k,t}}{(r-1)!}\nabla^r f(x^k)(z^{k+1,t}-x^k)^{r-1}\\
&= \Big(1-\sum_{t=1}^{p-1}\theta_{k,t}\Big)\nabla f(x^k) + \sum_{t=1}^{p-1}\theta_{k,t}\nabla f(z^{k+1,t}) + \Big(\nabla f(x^{k+1}) - \sum_{r=1}^p\frac{1}{(r-1)!}\nabla^r f(x^k)(x^{k+1}-x^k)^{r-1}\Big)\\
&\qquad -\sum_{t=1}^{p-1}\theta_{k,t}\Big(\nabla f(z^{k+1,t}) - \sum_{r=1}^p\frac{1}{(r-1)!}\nabla^r f(x^k)(z^{k+1,t}-x^k)^{r-1}\Big),
\end{align*}
which along with the definition of $\Rp$ in \eqref{def:taylor-res} implies that \eqref{idtt-from-high-smth} holds.
\end{proof}

The following lemma presents a recurrence relation for the estimation error of the gradient estimators $\{m^k\}$ generated by Algorithm \ref{alg:unf-sfom}.

\begin{lemma}%\label{lem:vr-mem}
Suppose that Assumptions \ref{asp:basic} and \ref{asp:high-smooth} hold. Let $\{(x^k,m^k)\}$ be the sequence generated by Algorithm \ref{alg:unf-sfom} with input parameters $q=p-1$, $\{\eta_k\}$, and $\{(\gamma_{k,t},\theta_{k,t})\}$ satisfying \eqref{pth-lss} and \eqref{sum-tht-bd}. Then we have
\begin{align}
&\mathbb{E}_{{\xi^{k+1}}}[\|m^{k+1}-\nabla f(x^{k+1})\|^\alpha] \le \Big(1 - \sum_{t=1}^{p-1}\theta_{k,t}\Big)\|m^k-\nabla f(x^k)\|^\alpha  \nonumber \\ 
& \qquad \qquad\quad + \frac{3p^{\alpha-1} L_p^\alpha}{(p!)^\alpha}\Big(\sum_{t=1}^{p-1}\theta_{k,t}\Big)^{1-\alpha}\eta_k^{\alpha p}\Big(1 + \sum_{t=1}^{p-1}\frac{|\theta_{k,t}|^\alpha}{\gamma_{k,t}^{\alpha p}}\Big) + 2(p-1)^{\alpha-1}\sigma^\alpha\sum_{t=1}^{p-1}|\theta_{k,t}|^\alpha\qquad\forall k\ge0,\label{ineq:vr-mem}
\end{align}
where $L_1$, $\sigma$, $\alpha$, $p$, and $L_p$ are given in Assumptions \ref{asp:basic} and \ref{asp:high-smooth}, respectively.
\end{lemma}

\begin{proof}
Fix any $k\ge0$. It follows from \eqref{update-mk}, \eqref{idtt-from-high-smth}, and  $q=p-1$ that 
\begin{align}
\nabla f(x^{k+1}) - m^{k+1} & = \Big(1 - \sum_{t=1}^{p-1}\theta_{k,t}\Big)(\nabla f(x^k)-m^k) + \sum_{t=1}^{p-1}\theta_{k,t}(\nabla f(z^{k+1,t}) - G(z^{k+1,t};\xi^{k+1}))\nonumber  \\
&\quad \  + \Rp(x^{k+1},x^k) - \sum_{t=1}^{p-1}\theta_{k,t}\Rp(z^{k+1,t},x^k).\label{ipt-idt-hsmth-mem}
\end{align}
Observe from Algorithm \ref{alg:unf-sfom} and Assumption \ref{asp:basic} that $\|x^{k+1}-x^k\|=\eta_k$, $\|z^{k+1,t}-x^k\|=\eta_k/\gamma_{k,t}$, $\E_{\xi^{k+1}}[G(z^{k+1,t};\xi^{k+1})-\nabla f(z^{k+1,t})]=0$, and $\mathbb{E}_{\xi^{k+1}}[\|\nabla f(z^{k+1,t}) - G(z^{k+1,t};\xi^{k+1})\|^\alpha]\le\sigma^\alpha$ for all $1\le t\le p-1$. Using these, \eqref{open-alpha}, \eqref{open-alpha-2}, \eqref{rela-mk+1-pm}, \eqref{ipt-idt-hsmth-mem}, and Lemma \ref{lem:grad-desc-near-high}, we obtain that for all $c>0$, 
\begin{align}
&\mathbb{E}_{{\xi^{k+1}}}[\|\nabla f(x^{k+1})-m^{k+1}\|^\alpha]\nonumber\\
&\overset{\eqref{ipt-idt-hsmth-mem}}{=}\mathbb{E}_{{\xi^{k+1}}}\Big[\Big\|\Big(1 - \sum_{t=1}^{p-1}\theta_{k,t}\Big)(\nabla f(x^k)-m^k) + \sum_{t=1}^{p-1}\theta_{k,t}(\nabla f(z^{k+1,t}) - G(z^{k+1,t};\xi^{k+1}))\nonumber\\
&\qquad + \Rp(x^{k+1},x^k) - \sum_{t=1}^{p-1}\theta_{k,t}\Rp(z^{k+1,t},x^k)\Big\|^\alpha\Big]\nonumber\\
&\overset{\eqref{open-alpha}}{\le} \Big\|\Big(1 - \sum_{t=1}^{p-1}\theta_{k,t}\Big)(\nabla f(x^k)-m^k)+\Rp(x^{k+1},x^k) - \sum_{t=1}^{p-1}\theta_{k,t}\Rp(z^{k+1,t},x^k)\Big\|^\alpha\nonumber\\
&\quad + 2\mathbb{E}_{{\xi^{k+1}}}\Big[\Big\|\sum_{t=1}^{p-1}\theta_{k,t}(\nabla f(z^{k+1,t}) - G(z^{k+1,t};\xi^{k+1}))\Big\|^\alpha\Big]\nonumber\\
&\overset{\eqref{open-alpha-2}}{\le} (1+c)\Big(1 - \sum_{t=1}^{p-1}\theta_{k,t}\Big)^\alpha\|\nabla f(x^k)-m^k\|^\alpha+ (2+(\alpha-1)^{\alpha-1}c^{1-\alpha})\Big\|\Rp(x^{k+1},x^k) - \sum_{t=1}^{p-1}\theta_{k,t}\Rp(z^{k+1,t},x^k)\Big\|^\alpha\nonumber\\
&\quad + 2\mathbb{E}_{{\xi^{k+1}}}\Big[\Big\|\sum_{t=1}^{p-1}\theta_{k,t}(\nabla f(z^{k+1,t}) - G(z^{k+1,t};\xi^{k+1}))\Big\|^\alpha\Big]\nonumber\\
&\le (1+c)\Big(1 - \sum_{t=1}^{p-1}\theta_{k,t}\Big)^\alpha\|\nabla f(x^k)-m^k\|^\alpha\nonumber\\
&\quad + p^{\alpha-1}(2+(\alpha-1)^{\alpha-1}c^{1-\alpha}) \Big(\|\Rp(x^{k+1},x^k)\|^\alpha + \sum_{t=1}^{p-1}|\theta_{k,t}|^\alpha\|\Rp(z^{k+1,t},x^k)\|^\alpha\Big)\nonumber\\
&\quad + 2(p-1)^{\alpha-1}\sum_{t=1}^{p-1}|\theta_{k,t}|^\alpha\mathbb{E}_{\xi^{k+1}}[\|\nabla f(z^{k+1,t}) - G(z^{k+1,t};\xi^{k+1})\|^\alpha]\nonumber\\
&\le (1+c)\Big(1 - \sum_{t=1}^{p-1}\theta_{k,t}\Big)^\alpha\|\nabla f(x^k)-m^k\|^\alpha\nonumber\\
&\quad + \frac{p^{\alpha-1} L_p^\alpha}{(p!)^\alpha}(2+(\alpha-1)^{\alpha-1}c^{1-\alpha})\eta_k^{\alpha p}\Big(1 + \sum_{t=1}^{p-1}\frac{|\theta_{k,t}|^\alpha}{\gamma_{k,t}^{\alpha p}}\Big) + 2(p-1)^{\alpha-1}\sigma^\alpha\sum_{t=1}^{p-1}|\theta_{k,t}|^\alpha,\label{vr-inter-mem}
\end{align}
where the first inequality is due to \eqref{open-alpha}, and the fact that $\E_{\xi^{k+1}}[G(z^{k+1,t};\xi^{k+1})-\nabla f(z^{k+1,t})]=0$ for all $1\le t\le p-1$, the third inequality follows from $\|\sum_{t=1}^{m}w_t\|^\alpha \le m^{\alpha-1}\sum_{t=1}^{m}\|w_t\|^\alpha$ because of the convexity of $\|\cdot\|^\alpha$, and the last inequality follows from Lemma \ref{lem:grad-desc-near-high}, $\|x^{k+1}-x^k\|=\eta_k$, $\|z^{k+1,t}-x^k\|=\eta_k/\gamma_{k,t}$, and 
$\mathbb{E}_{\xi^{k+1}}[\|\nabla f(z^{k+1,t}) - G(z^{k+1,t};\xi^{k+1})\|^\alpha]\le\sigma^\alpha$ for all $1\le t\le p-1$. 

Letting $c=(1-\sum_{t=1}^{p-1}\theta_{k,t})^{1-\alpha}-1$ in \eqref{vr-inter-mem}, and using $\sum_{t=1}^{p-1}\theta_{k,t}\in(0,1)$ (see \eqref{sum-tht-bd}) and $\alpha\in(1,2]$, we obtain that
\begin{align*}
c^{1-\alpha} & = \Big(\frac{1}{(1-\sum_{t=1}^{p-1}\theta_{k,t})^{\alpha-1}} - 1\Big)^{1-\alpha} \le \Big(\frac{1}{1-(\alpha-1)\sum_{t=1}^{p-1}\theta_{k,t}} - 1\Big)^{1-\alpha}\\
& =\Big(\frac{1-(\alpha-1)\sum_{t=1}^{p-1}\theta_{k,t}}{(\alpha-1)\sum_{t=1}^{p-1}\theta_{k,t}} \Big)^{\alpha-1} \le \Big((\alpha-1)\sum_{t=1}^{p-1}\theta_{k,t}\Big)^{1-\alpha},
\end{align*}
where the first inequality follows from $(1-\tau)^\beta\le 1-\beta\tau$ for all $\tau\in(-\infty,1)$ and $\beta\in[0,1]$. Combining the above inequality with \eqref{vr-inter-mem}, one can obtain that
\begin{align*}
&\mathbb{E}_{{\xi^{k+1}}}[\|\nabla f(x^{k+1})-m^{k+1}\|^\alpha] \le \Big(1 - \sum_{t=1}^{p-1}\theta_{k,t}\Big)\|\nabla f(x^k)-m^k\|^\alpha \\
&\qquad\qquad\qquad\qquad + \frac{p^{\alpha-1} L_p^\alpha}{(p!)^\alpha}\Big(2+\Big(\sum_{t=1}^{p-1}\theta_{k,t}\Big)^{1-\alpha}\Big)\eta_k^{\alpha p}\Big(1 + \sum_{t=1}^{p-1}\frac{|\theta_{k,t}|^\alpha}{\gamma_{k,t}^{\alpha p}}\Big) + 2(p-1)^{\alpha-1}\sigma^\alpha\sum_{t=1}^{p-1}|\theta_{k,t}|^\alpha,
\end{align*}
which together with $\sum_{t=1}^{p-1}\theta_{k,t}\in(0,1)$ and $\alpha\in(1,2]$ implies that \eqref{ineq:vr-mem} holds.
\end{proof}

The following lemma establishes a descent property for the potential sequence $\{{\mathcal P}_k\}$ defined below.

\begin{lemma}\label{thm:rate-mem}
Suppose that Assumptions \ref{asp:basic} and \ref{asp:high-smooth} hold. Let $\{(x^k,m^k)\}$ be generated by Algorithm \ref{alg:unf-sfom} with input parameters $q=p-1$, $\{\eta_k\}$, and  $\{(\gamma_{k,t},\theta_{k,t})\}$ satisfying \eqref{pth-lss} and \eqref{sum-tht-bd}. Let $L_1$, $\sigma$, and $\alpha$ be given in Assumption \ref{asp:basic}, $p$ and $L_p$ be given in Assumption \ref{asp:high-smooth}, and $\{\mathcal{P}_k\}$ be defined in \eqref{def:pot-pm} for $\{(x^k,m^k)\}$ and any positive sequence $\{p_k\}$ that satisfies $(1-\sum_{t=1}^{p-1}\theta_{k,t})p_{k+1} \le (1-\sum_{t=1}^{p-1}\theta_{k,t}/10)p_k$ for all $k\ge0$. Then it holds that for all $k\geq 0$,
\begin{align}
\mathbb{E}_{{\xi^{k+1}}}[{\mathcal P}_{k+1}] & \le  {\mathcal P}_k- \eta_k\|\nabla f(x^k)\| + \frac{L_1}{2}\eta_k^2 + \frac{(\alpha-1)(2\eta_k)^{\alpha/(\alpha-1)}}{\alpha^{\alpha/(\alpha-1)}(p_k\sum_{t=1}^{p-1}\theta_{k,t}/10)^{1/(\alpha-1)}}\nonumber\\
&\quad + \frac{3p^{\alpha-1} L_p^\alpha}{(p!)^\alpha} p_{k+1}\Big(\sum_{t=1}^{p-1}\theta_{k,t}\Big)^{1-\alpha}\eta_k^{\alpha p}\Big(1 + \sum_{t=1}^{p-1}\frac{|\theta_{k,t}|^\alpha}{\gamma_{k,t}^{\alpha p}}\Big) + 2(p-1)^{\alpha-1}\sigma^\alpha p_{k+1}\sum_{t=1}^{p-1}|\theta_{k,t}|^\alpha.
\label{stat-bd-mem}
\end{align}
\end{lemma}

\begin{proof}
Fix any $k\ge0$. By Lemma \ref{lem:ppt-desc} with $(x^+,x,m,\eta)=(x^{k+1},x^k,m^k,\eta_k)$, one has
\begin{align}\label{upbd-fxk+1-mem}
f(x^{k+1}) \le f(x^k) - \eta_k\|\nabla f(x^k)\| + 2\eta_k\|\nabla f(x^k) - m^k\| + \frac{L_1}{2}\eta_k^2.    
\end{align}
Combining this with \eqref{def:pot-pm} and \eqref{ineq:vr-mem}, we obtain that 
\begin{align}
&\mathbb{E}_{{\xi^{k+1}}}[{\mathcal P}_{k+1}] \overset{\eqref{def:pot-pm}}{=} \mathbb{E}_{{\xi^{k+1}}}[f(x^{k+1}) + p_{k+1}\|\nabla f(x^{k+1})-m^{k+1}\|^\alpha]\nonumber\\
&\overset{\eqref{ineq:vr-mem}\eqref{upbd-fxk+1-mem}}{\le} f(x^k) - \eta_k\|\nabla f(x^k)\| + 2\eta_k\|\nabla f(x^k) - m^k\| + \frac{L_1}{2}\eta_k^2 + \Big(1-\sum_{t=1}^{p-1}\theta_{k,t}\Big)p_{k+1}\|\nabla f(x^k)-m^k\|^\alpha\nonumber \\
&\qquad + \frac{3p^{\alpha-1} L_p^\alpha}{(p!)^\alpha} p_{k+1}\Big(\sum_{t=1}^{p-1}\theta_{k,t}\Big)^{1-\alpha}\eta_k^{\alpha p}\Big(1 + \sum_{t=1}^{p-1}\frac{|\theta_{k,t}|^\alpha}{\gamma_{k,t}^{\alpha p}}\Big) + 2(p-1)^{\alpha-1}\sigma^\alpha p_{k+1}\sum_{t=1}^{p-1}|\theta_{k,t}|^\alpha \nonumber\\
&\le f(x^k) - \eta_k\|\nabla f(x^k)\| + 2\eta_k\|\nabla f(x^k) - m^k\| + \frac{L_1}{2}\eta_k^2 + \Big(1-\sum_{t=1}^{p-1}\theta_{k,t}/10\Big)p_k\|\nabla f(x^k)-m^k\|^\alpha\nonumber\\
&\quad + \frac{3p^{\alpha-1} L_p^\alpha}{(p!)^\alpha} p_{k+1}\Big(\sum_{t=1}^{p-1}\theta_{k,t}\Big)^{1-\alpha}\eta_k^{\alpha p}\Big(1 + \sum_{t=1}^{p-1}\frac{|\theta_{k,t}|^\alpha}{\gamma_{k,t}^{\alpha p}}\Big) + 2(p-1)^{\alpha-1}\sigma^\alpha p_{k+1}\sum_{t=1}^{p-1}|\theta_{k,t}|^\alpha,\label{pot-desc-ineq-mem}
\end{align}
where the last inequality is due to $(1-\sum_{t=1}^{p-1}\theta_{k,t})p_{k+1}\le(1-\sum_{t=1}^{p-1}\theta_{k,t}/10)p_k$. In addition, letting $\alpha^\prime=\alpha/(\alpha-1)$ and using the Young's inequality, we have that
\begin{align*}
2\eta_k\|\nabla f(x^k) - m^k\| & \le \frac{((\alpha p_k\sum_{t=1}^{p-1}\theta_{k,t}/10)^{1/\alpha} \|\nabla f(x^k) - m^k\|)^\alpha}{\alpha} + \frac{(2\eta_k/(\alpha p_k\sum_{t=1}^{p-1}\theta_{k,t}/10)^{1/\alpha})^{\alpha^\prime}}{\alpha^\prime} \\
&% = \theta_k p_k \|\nabla f(x^k) - m^k\|^\alpha + \frac{(2\eta_k/(\alpha\theta_k p_k)^{1/\alpha})^{\alpha^\prime}}{\alpha^\prime} 
= \frac{p_k\sum_{t=1}^{p-1}\theta_{k,t}}{10}\|\nabla f(x^k) - m^k\|^\alpha + \frac{(\alpha-1)(2\eta_k)^{\alpha/(\alpha-1)}}{\alpha^{\alpha/(\alpha-1)}(p_k\sum_{t=1}^{p-1}\theta_{k,t}/10)^{1/(\alpha-1)}}.
\end{align*}
This together with \eqref{pot-desc-ineq-mem} implies that
\begin{align*}
\mathbb{E}_{{\xi^{k+1}}}[{\mathcal P}_{k+1}] &\le f(x^k) + p_k\|m^k-\nabla f(x^k)\|^\alpha - \eta_k\|\nabla f(x^k)\| + \frac{L_1}{2}\eta_k^2 + \frac{(\alpha-1)(2\eta_k)^{\alpha/(\alpha-1)}}{\alpha^{\alpha/(\alpha-1)}(p_k\sum_{t=1}^{p-1}\theta_{k,t}/10)^{1/(\alpha-1)}}\\
&\quad + \frac{3p^{\alpha-1} L_p^\alpha}{(p!)^\alpha} p_{k+1}\Big(\sum_{t=1}^{p-1}\theta_{k,t}\Big)^{1-\alpha}\eta_k^{\alpha p}\Big(1 + \sum_{t=1}^{p-1}\frac{|\theta_{k,t}|^\alpha}{\gamma_{k,t}^{\alpha p}}\Big) + 2(p-1)^{\alpha-1}\sigma^\alpha p_{k+1}\sum_{t=1}^{p-1}|\theta_{k,t}|^\alpha.
\end{align*}
The conclusion \eqref{stat-bd-mem} then follows from this relation and \eqref{def:pot-pm}.
\end{proof}

We next establish some properties for a specific choice of $\{(\gamma_{k,t},\theta_{k,t})\}$ and $\{p_k\}$, which will be used to prove  Theorem \ref{thm:known-rate-mem} subsequently.

\begin{lemma}\label{lem:pk-mem}
Let $\{(\gamma_{k,t},\theta_{k,t})\}$ be defined in \eqref{def:theta-known-rate-mem} and \eqref{def:gmak-mem-know}, and let $\{p_k\}$ be defined as     
\begin{align}\label{def:pk-known-mem}
p_k=(k+4)^{(p(\alpha-1)^2-\alpha+1)/(p(2\alpha-1)+\alpha-1)} \qquad\forall k\ge0.
\end{align}
Then \eqref{pth-lss} and \eqref{sum-tht-bd} hold for such $\{(\gamma_{k,t},\theta_{k,t})\}$, and moreover, $(1-\sum_{t=1}^{p-1}\theta_{k,t})p_{k+1} \le (1-\sum_{t=1}^{p-1}\theta_{k,t}/10)p_k$ holds for all $k\ge0$.
\end{lemma}

\begin{proof}
Fix any $k\ge0$. Notice that $p\alpha/(p(2\alpha-1)+\alpha-1)\in(1/2,1)$ for all $p\ge2$ and $\alpha\in(1,2]$. It then follows from \eqref{def:gmak-mem-know} that $\gamma_k=1/(k+4)^{p\alpha/(p(2\alpha-1)+\alpha-1)}\in(0,1/2)$. By this,  \eqref{def:theta-known-rate-mem}, and Lemma \ref{lem:ppt-thetakt}, one can see that \eqref{pth-lss} and \eqref{sum-tht-bd} hold for $\{(\gamma_{k,t},\theta_{k,t})\}$ that is defined in \eqref{def:theta-known-rate-mem} and \eqref{def:gmak-mem-know}. In addition, observe that
\begin{align}
&\frac{1-\sum_{t=1}^{p-1}\theta_{k,t}/10}{1-\sum_{t=1}^{p-1}\theta_{k,t}} =  1 + \frac{9\sum_{t=1}^{p-1}\theta_{k,t}}{10(1-\sum_{t=1}^{p-1}\theta_{k,t})} \ge 1 + \frac{9\sum_{t=1}^{p-1}\theta_{k,t}}{10} \overset{\eqref{two-ipt-ppt-theta-2}}{\ge} 1 + \frac{9\gamma_k}{10(1 + \pi^2/6)}\nonumber\\
&\overset{\eqref{def:gmak-mem-know}}{=} 1+\frac{9}{10(1 + \pi^2/6)(k+4)^{p\alpha/(p(2\alpha-1)+\alpha-1)}} >1+ \frac{9}{10(1 + \pi^2/6)(k+4)}> 1+\frac{1}{3(k+4)},\label{lwbd-frac-sum-thetak}
\end{align}
where the first inequality follows from $\sum_{t=1}^{p-1}\theta_{k,t}\in(0,1)$, and the third inequality is due to $p\alpha/(p(2\alpha-1)+\alpha-1)<1$ for all $p\ge1$ and $\alpha\in(1,2]$. Also, note that 
\begin{align*}
\frac{p_{k+1}}{p_k} = \Big(1+\frac{1}{k+4}\Big)^{(p(\alpha-1)^2-\alpha+1)/(p(2\alpha-1)+\alpha-1)} \le \Big(1+\frac{1}{k+4}\Big)^{1/3}\le 1+\frac{1}{3(k+4)}, 
\end{align*}
where the first inequality follows from $(p(\alpha-1)^2-\alpha+1)/(p(2\alpha-1)+\alpha-1)\le1/3$ for all $p\ge1$ and $\alpha\in(1,2]$, and the last inequality is due to $(1+\tau)^\beta\le 1+\tau \beta$ for all $\tau>-1$ and $\beta\in[0,1]$. The above relation together with \eqref{lwbd-frac-sum-thetak} implies that $(1-\sum_{t=1}^{p-1}\theta_{k,t})p_{k+1} \le (1-\sum_{t=1}^{p-1}\theta_{k,t}/10)p_k$ holds.
\end{proof}


We are now ready to prove Theorem \ref{thm:known-rate-mem}.

\begin{proof}[\textbf{Proof of Theorem \ref{thm:known-rate-mem}}]
Let $\{(x^k,m^k)\}$ be generated by Algorithm \ref{alg:unf-sfom} with $\{(\eta_k,\gamma_{k,t},\theta_{k,t})\}$ defined in \eqref{def:eta-known-rate-mem} and \eqref{def:theta-known-rate-mem}, and let 
$\{{\mathcal P}_k\}$ be defined in \eqref{def:pot-pm} with such $\{(x^k,m^k)\}$ and $\{p_k\}$ given in \eqref{def:pk-known-mem}. By Lemma \ref{lem:pk-mem}, one can see that such $\{(\eta_k,\gamma_{k,t},\theta_{k,t},p_k)\}$ satisfies the assumptions in Lemma \ref{thm:rate-mem} and Algorithm \ref{alg:unf-sfom}. In addition, by \eqref{def:pot-pm} and \eqref{def:pk-known-mem}, one has that
\begin{align}
\mathbb{E}[{\mathcal P}_0] & = f(x^0)+p_0\mathbb{E}[\|m^0-\nabla f(x^0)\|^\alpha]\nonumber\\   
&\le f(x^0) + 4^{(p(\alpha-1)^2-\alpha+1)/(p(2\alpha-1)+\alpha-1)}\mathbb{E}[\|G(x^0;\xi^0)-\nabla f(x^0)\|^\alpha] \le f(x^0)+ 4^{1/3}\sigma^\alpha,\label{upbd-exp-P0-mem}\\
\mathbb{E}[{\mathcal P}_K] & = \mathbb{E}[f(x^K)+p_K\|m^K-\nabla f(x^K)\|^\alpha]\ge \mathbb{E}[f(x^K)] \ge f_{\mathrm{low}},\label{lwbd-exp-Pk-mem}
\end{align}
where the inequality in \eqref{upbd-exp-P0-mem} is due to $(p(\alpha-1)^2-\alpha+1)/(p(2\alpha-1)+\alpha-1)\le1/3$ for all $p\ge1$ and $\alpha\in(1,2]$, and $\mathbb{E}[\|G(x^0;\xi^{0})-\nabla f(x^0)\|^\alpha]\le\sigma^\alpha$ {for all $1\le t\le p-1$}. Taking expectation on both sides of \eqref{stat-bd-mem} with respect to {$\{\xi^{i}\}_{0\le i\le k+1}$}, we have
\begin{align*}
\mathbb{E}[{\mathcal P}_{k+1}] &\le  \mathbb{E}[{\mathcal P}_k]- \eta_k\mathbb{E}[\|\nabla f(x^k)\|] + \frac{L_1}{2}\eta_k^2 + \frac{(\alpha-1)(2\eta_k)^{\alpha/(\alpha-1)}}{\alpha^{\alpha/(\alpha-1)}(p_k\sum_{t=1}^{p-1}\theta_{k,t}/10)^{1/(\alpha-1)}}\\
&\quad + \frac{3p^{\alpha-1} L_p^\alpha}{(p!)^\alpha} p_{k+1}\Big(\sum_{t=1}^{p-1}\theta_{k,t}\Big)^{1-\alpha}\eta_k^{\alpha p}\Big(1 + \sum_{t=1}^{p-1}\frac{|\theta_{k,t}|^\alpha}{\gamma_{k,t}^{\alpha p}}\Big) + 2(p-1)^{\alpha-1}\sigma^\alpha p_{k+1}\sum_{t=1}^{p-1}|\theta_{k,t}|^\alpha{\quad\forall k\ge0.}
\end{align*}
Summing up this inequality over $k=0,\ldots,K-1$, and using \eqref{upbd-exp-P0-mem} and \eqref{lwbd-exp-Pk-mem}, we obtain that for all $K\ge1$,
\begin{align}
&f_{\mathrm{low}}\overset{\eqref{lwbd-exp-Pk-mem}}{\le} \mathbb{E}[{\mathcal P}_K] \le \E[{\mathcal P}_0] - \sum_{k=0}^{K-1}\eta_k\mathbb{E}[\|\nabla f(x^k)\|]+ \sum_{k=0}^{K-1}\Big(\frac{L_1}{2}\eta_k^2 + \frac{(\alpha-1)(2\eta_k)^{\alpha/(\alpha-1)}}{\alpha^{\alpha/(\alpha-1)}(p_k\sum_{t=1}^{p-1}\theta_{k,t}/10)^{1/(\alpha-1)}}\nonumber\\
&\quad + \frac{3p^{\alpha-1} L_p^\alpha}{(p!)^\alpha} p_{k+1}\Big(\sum_{t=1}^{p-1}\theta_{k,t}\Big)^{1-\alpha}\eta_k^{\alpha p}\Big(1 + \sum_{t=1}^{p-1}\frac{|\theta_{k,t}|^\alpha}{\gamma_{k,t}^{\alpha p}}\Big) + 2(p-1)^{\alpha-1}\sigma^\alpha p_{k+1}\sum_{t=1}^{p-1}|\theta_{k,t}|^\alpha\Big)\nonumber\\
&\overset{\eqref{upbd-exp-P0-mem}}{\le} f(x^0) + 4^{1/3}\sigma^\alpha - \eta_{K-1}\sum_{k=0}^{K-1}\mathbb{E}[\|\nabla f(x^k)\|] + \sum_{k=0}^{K-1}\Big(\frac{L_1}{2}\eta_k^2 + \frac{(\alpha-1)(2\eta_k)^{\alpha/(\alpha-1)}}{\alpha^{\alpha/(\alpha-1)}(p_k\sum_{t=1}^{p-1}\theta_{k,t}/10)^{1/(\alpha-1)}}\nonumber\\
&\quad + \frac{6p^{\alpha-1} L_p^\alpha}{(p!)^\alpha} p_k\Big(\sum_{t=1}^{p-1}\theta_{k,t}\Big)^{1-\alpha}\eta_k^{\alpha p}\Big(1 + \sum_{t=1}^{p-1}\frac{|\theta_{k,t}|^\alpha}{\gamma_{k,t}^{\alpha p}}\Big) + 4(p-1)^{\alpha-1}\sigma^\alpha p_k\sum_{t=1}^{p-1}|\theta_{k,t}|^\alpha\Big)\nonumber\\ 
&\le f(x^0) + 4^{1/3}\sigma^\alpha - \eta_{K-1}\sum_{k=0}^{K-1} \mathbb{E}[\|\nabla f(x^k)\|] + \sum_{k=0}^{K-1}\Big(\frac{L_1}{2}\eta_k^2 + \frac{30^{1/(\alpha-1)}(\alpha-1)(2/\alpha)^{\alpha/(\alpha-1)}\eta_k^{\alpha/(\alpha-1)}}{(p_k\gamma_k)^{1/(\alpha-1)}}\nonumber\\
&\quad + \frac{18 p^{\alpha-1} L_p^\alpha}{(p!)^\alpha} p_k \gamma_k^{1-\alpha}\eta_k^{\alpha p}\Big(1 + \sum_{t=1}^{p-1}\frac{|\theta_{k,t}|^\alpha}{\gamma_{k,t}^{\alpha p}}\Big) + 64(p-1)^\alpha\sigma^\alpha p_k\gamma_k^\alpha\Big)\nonumber\\
&\le f(x^0) + 4^{1/3}\sigma^\alpha - \eta_{K-1}\sum_{k=0}^{K-1} \mathbb{E}[\|\nabla f(x^k)\|] + \sum_{k=0}^{K-1}\Big(\frac{L_1}{2}\eta_k^2 + \frac{30^{1/(\alpha-1)}(\alpha-1)(2/\alpha)^{\alpha/(\alpha-1)}\eta_k^{\alpha/(\alpha-1)}}{(p_k\gamma_k)^{1/(\alpha-1)}}\nonumber\\
&\quad + \frac{18p^{\alpha-1} L_p^\alpha}{(p!)^\alpha} p_k\gamma_k^{1-\alpha}\eta_k^{\alpha p} \Big(1+16\gamma_k^{\alpha-\alpha p}\sum_{t=1}^{p-1}t^{2\alpha(p-1)}\Big) + 64(p-1)^\alpha\sigma^\alpha p_k\gamma_k^\alpha\Big)\nonumber\\
&\le f(x^0) + 4^{1/3}\sigma^\alpha - \eta_{K-1}\sum_{k=0}^{K-1} \mathbb{E}[\|\nabla f(x^k)\|] + \sum_{k=0}^{K-1}\Big(\frac{L_1}{2}\eta_k^2 + \frac{30^{1/(\alpha-1)}(\alpha-1)(2/\alpha)^{\alpha/(\alpha-1)}\eta_k^{\alpha/(\alpha-1)}}{(p_k\gamma_k)^{1/(\alpha-1)}}\nonumber\\
&\quad + \frac{306p^{2\alpha p} L_p^\alpha}{(p!)^\alpha} p_k\gamma_k^{1-\alpha p}\eta_k^{\alpha p} + 64(p-1)^\alpha\sigma^\alpha p_k\gamma_k^\alpha\Big),
\label{rear-pot-desc-rm}
\end{align}
where the third inequality follows from \eqref{upbd-exp-P0-mem}, $p_{k+1}\le 2p_k$ for all $k\ge0$ due to \eqref{def:pk-known-mem}, and the fact that $\{\eta_k\}$ is nonincreasing, the fourth inequality is due to $\sum_{t=1}^{p-1}\theta_{k,t}\in(\gamma_k/3,2\gamma_k)$ and $|\theta_{k,t}|\le 4\gamma_k/t^2\le 4\gamma_k$ for all $1\le t\le p-1$ because of \eqref{two-ipt-ppt-theta-2}, the fifth inequality follows from $|\theta_{k,t}|^\alpha/\gamma_{k,t}^{\alpha p} \le 4^\alpha\gamma_k^{\alpha-\alpha p}t^{2\alpha(p-1)}\le 16\gamma_k^{\alpha-\alpha p}t^{2\alpha(p-1)}$ because of \eqref{two-ipt-ppt-theta-2} and \eqref{def:theta-known-rate-mem}, and the last inequality is due to $1+16\gamma_k^{\alpha-\alpha p}\sum_{t=1}^{p-1}t^{2\alpha(p-1)}\le 17\gamma_k^{\alpha-\alpha p}\sum_{t=1}^{p-1}t^{2\alpha(p-1)}\le17p^{2\alpha p-2\alpha+1}\gamma_k^{\alpha-\alpha p}$. Rearranging the terms in \eqref{rear-pot-desc-rm}, and using \eqref{def:Mpa-known}, \eqref{def:eta-known-rate-mem}, \eqref{def:gmak-mem-know}, and \eqref{def:pk-known-mem}, we obtain that for all $K\ge5$,
\begin{align*}
&\frac{1}{K}\sum_{k=0}^{K-1}\mathbb{E}[\|\nabla f(x^k)\|]\\
&\overset{\eqref{rear-pot-desc-rm}}{\le} \frac{f(x^0) - f_{\mathrm{low}} + 4^{1/3}\sigma^\alpha}{K\eta_{K-1}} + \frac{1}{K\eta_{K-1}}\sum_{k=0}^{K-1}\Big(\frac{L_1}{2}\eta_k^2 + \frac{30^{1/(\alpha-1)}(\alpha-1)(2/\alpha)^{\alpha/(\alpha-1)}\eta_k^{\alpha/(\alpha-1)}}{(p_k\gamma_k)^{1/(\alpha-1)}}\\
&\qquad + \frac{306p^{2\alpha p} L_p^\alpha}{(p!)^\alpha} p_k\gamma_k^{1-\alpha p}\eta_k^{\alpha p} + 64(p-1)^\alpha\sigma^\alpha p_k\gamma_k^\alpha\Big)\\
&\overset{\eqref{def:eta-known-rate-mem}\eqref{def:gmak-mem-know}\eqref{def:pk-known-mem}}{=} \frac{(f(x^0) - f_{\mathrm{low}} + 4^{1/3}\sigma^\alpha)(K+3)^{(p\alpha+\alpha-1)/(p(2\alpha-1)+\alpha-1)}}{K} \\
&\qquad + \frac{(K+3)^{(p\alpha+\alpha-1)/(p(2\alpha-1)+\alpha-1)}}{K}\sum_{k=0}^{K-1}\Big(\frac{L_1}{2(k+4)^{2(p\alpha+\alpha-1)/(p(2\alpha-1)+\alpha-1)}}\\
&\qquad + \frac{30^{1/(\alpha-1)}(\alpha-1)(2/\alpha)^{\alpha/(\alpha-1)} + 306 p^{2\alpha p} L_p^\alpha/(p!)^\alpha +64(p-1)^\alpha\sigma^\alpha}{k+4}\Big)\\
&\le\frac{2(f(x^0) - f_{\mathrm{low}} + 4^{1/3}\sigma^\alpha)}{K^{p(\alpha-1)/(p(2\alpha-1)+\alpha-1)}}  + \frac{2}{K^{p(\alpha-1)/(p(2\alpha-1)+\alpha-1)}}\sum_{k=0}^{K-1}\Big(\frac{L_1}{2(k+4)^{2(p\alpha+\alpha-1)/(p(2\alpha-1)+\alpha-1)}}\\
&\qquad + \frac{30^{1/(\alpha-1)}(\alpha-1)(2/\alpha)^{\alpha/(\alpha-1)} + 306 p^{2\alpha p} L_p^\alpha/(p!)^\alpha +64(p-1)^\alpha\sigma^\alpha}{k+4}\Big)\\
&\le \frac{2(f(x^0) - f_{\mathrm{low}} + 4^{1/3}\sigma^\alpha)}{K^{p(\alpha-1)/(p(2\alpha-1)+\alpha-1)}} + \frac{2}{K^{p(\alpha-1)/(p(2\alpha-1)+\alpha-1)}} \\
&\qquad \times \sum_{k=0}^{K-1}\Big(\frac{L_1/2 + 30^{1/(\alpha-1)}(\alpha-1)(2/\alpha)^{\alpha/(\alpha-1)} + 306 p^{2\alpha p} L_p^\alpha/(p!)^\alpha +64(p-1)^\alpha\sigma^\alpha}{k+4}\Big)\\
% &\le \frac{2(f(x^0) - f_{\mathrm{low}} + 4^{1/3}\sigma^\alpha)}{K^{p(\alpha-1)/(p(2\alpha-1)+\alpha-1)}}\\
% &\qquad + \frac{2(L_1/2 + 30^{1/(\alpha-1)}(\alpha-1)(2/\alpha)^{\alpha/(\alpha-1)} + 306 p^{2\alpha p} L_p^\alpha/(p!)^\alpha +64(p-1)^\alpha\sigma^\alpha)\ln(2K/5+1)}{K^{p(\alpha-1)/(p(2\alpha-1)+\alpha-1)}}\\
&\le \frac{4(f(x^0) - f_{\mathrm{low}} + 4^{1/3}\sigma^\alpha + L_1/2 + 30^{1/(\alpha-1)}(\alpha-1)(2/\alpha)^{\alpha/(\alpha-1)} + 306 p^{2\alpha p} L_p^\alpha/(p!)^\alpha +64(p-1)^\alpha\sigma^\alpha)\ln K}{K^{p(\alpha-1)/(p(2\alpha-1)+\alpha-1)}}\\
&\overset{\eqref{def:Mpa-known}}{=} \frac{M_{p,\alpha} \ln K}{K^{p(\alpha-1)/(p(2\alpha-1)+\alpha-1)}},
\end{align*}
where the second inequality follows from $(K+3)^{(p\alpha+\alpha-1)/(p(2\alpha-1)+\alpha-1)}\le 2K^{(p\alpha+\alpha-1)/(p(2\alpha-1)+\alpha-1)}$ for all $K\ge5$, the third inequality is due to $2(p\alpha+\alpha-1)/(p(2\alpha-1)+\alpha-1)\ge1$ for all $p\ge1$ and $\alpha\in(1,2]$, and the last inequality follows from $\sum_{k=0}^{K-1}1/(k+4)\le \ln(2K/5+1) \le 2\ln K$ for all $K\ge 5$ due to \eqref{upbd:series-ka}. Recall that $\iota_K$ is uniformly selected from $\{0,\ldots,K-1\}$. It then follows from this and the above inequality that 
\begin{align}\label{pre-upbd-mem}
\E[\|\nabla f(x^{\iota_K})\|] = \frac{1}{K}\sum_{k=0}^{K-1}\mathbb{E}[\|\nabla f(x^k)\|] \le \frac{M_{p,\alpha}\ln K}{K^{p(\alpha-1)/(p(2\alpha-1)+\alpha-1)}}\qquad\forall K\ge 5.
\end{align}
By Lemma \ref{lem:rate-complexity} with $(\beta,u,v)=(p(\alpha-1)/(p(2\alpha-1)+\alpha-1),p(\alpha-1)\epsilon/(2(p(2\alpha-1)+\alpha-1)M_{p,\alpha}),K)$, one can see that $K^{-p(\alpha-1)/(p(2\alpha-1)+\alpha-1)}\ln K\le \epsilon/M_{p,\alpha}$ for all $K$ satisfying 
\[
 K\ge\Big(\frac{2(p(2\alpha-1)+\alpha-1)M_{p,\alpha}}{p(\alpha-1)\epsilon}\ln\Big(\frac{2(p(2\alpha-1)+\alpha-1)M_{p,\alpha}}{p(\alpha-1)\epsilon}\Big)\Big)^{(p(2\alpha-1)+\alpha-1)/(p(\alpha-1))},    
\]
which together with \eqref{pre-upbd-mem} implies that Theorem \ref{thm:known-rate-mem}.
\end{proof}

The following lemma establishes some properties for a specific choice of $\{(\gamma_{k,t},\theta_{k,t})\}$ and $\{p_k\}$, which will be used to prove Theorem \ref{thm:unknown-rate-mem} subsequently.

\begin{lemma}\label{lem:pk-mem-unk}
Let $\{(\gamma_{k,t},\theta_{k,t})\}$ be defined in \eqref{def:theta-unknown-rate-mem} and \eqref{def:gmak-mem-unknow}, and let $\{p_k\}$ be defined as     
\begin{align}\label{def:pk-unknown}
p_k=(k+4)^{(2p(\alpha-1)^2-\alpha)/(3p\alpha+\alpha)} \qquad\forall k\ge0.  
\end{align}
Then \eqref{pth-lss} and \eqref{sum-tht-bd} hold for such $\{(\gamma_{k,t},\theta_{k,t})\}$, and moreover, $(1-\sum_{t=1}^{p-1}\theta_{k,t})p_{k+1} \le (1-\sum_{t=1}^{p-1}\theta_{k,t}/10)p_k$ holds for all $k\ge0$.
\end{lemma}

\begin{proof}
Fix any $k\ge0$. Notice that $2p/(3p+1)> 1/2$ for all $p\ge2$. It then follows from \eqref{def:gmak-mem-unknow} that $\gamma_k=1/(k+4)^{2p/(3p+1)}\in(0,1/2)$. By this, \eqref{def:theta-unknown-rate-mem} and Lemma \ref{lem:ppt-thetakt}, one can see that \eqref{pth-lss} and \eqref{sum-tht-bd} hold for $\{(\gamma_{k,t},\theta_{k,t})\}$ that is defined in \eqref{def:theta-unknown-rate-mem} and \eqref{def:gmak-mem-unknow}. In addition, observe that
\begin{align}
&\frac{1-\sum_{t=1}^{p-1}\theta_{k,t}/10}{1-\sum_{t=1}^{p-1}\theta_{k,t}} =1 + \frac{9\sum_{t=1}^{p-1}\theta_{k,t}}{10(1-\sum_{t=1}^{p-1}\theta_{k,t})}  \ge 1 + \frac{9\sum_{t=1}^{p-1}\theta_{k,t}}{10}\overset{\eqref{two-ipt-ppt-theta-2}}{\ge} 1 + \frac{9\gamma_k}{10(1 + \pi^2/6)}\nonumber\\
&\overset{\eqref{def:gmak-mem-unknow}}{=}1+ \frac{9}{10(1 + \pi^2/6)(k+4)^{2p/(3p+1)}} >1+ \frac{9}{10(1 + \pi^2/6)(k+4)}> 1+\frac{1}{3(k+4)},\label{lwbd-frac-sum-thetak-unk}
\end{align}
where the first inequality follows from $\sum_{t=1}^{p-1}\theta_{k,t}\in(0,1)$,  the third inequality follows from $2p/(3p+1)< 1$ for all $p\ge2$. Also, note that 
\begin{align*}
\frac{p_{k+1}}{p_k} = \Big(1+\frac{1}{k+4}\Big)^{(2p(\alpha-1)^2-\alpha)/(3p\alpha+\alpha)} \le \Big(1+\frac{1}{k+4}\Big)^{1/3} \le 1+\frac{1}{3(k+4)}, 
\end{align*}
where the first inequality follows from $(2p(\alpha-1)^2-\alpha)/(3p\alpha+\alpha)\le 1/3$ for all $p\ge2$ and $\alpha\in(1,2]$, and the last inequality is due to $(1+\tau)^\beta\le 1+\tau \beta$ for all $\tau>-1$ and $\beta\in[0,1]$. The above relation along with \eqref{lwbd-frac-sum-thetak-unk} implies that $(1-\sum_{t=1}^{p-1}\theta_{k,t})p_{k+1} \le (1-\sum_{t=1}^{p-1}\theta_{k,t}/10)p_k$ holds.
\end{proof}


We are now ready to prove Theorem \ref{thm:unknown-rate-mem}.

\begin{proof}[\textbf{Proof of Theorem \ref{thm:unknown-rate-mem}}]

Let $\{(x^k,m^k)\}$ be generated by Algorithm \ref{alg:unf-sfom} with $\{(\eta_k,\gamma_{k,t},\theta_{k,t})\}$ defined in \eqref{def:eta-unknown-rate-mem}, \eqref{def:theta-unknown-rate-mem}, and \eqref{def:gmak-mem-unknow}, and let 
$\{{\mathcal P}_k\}$ be defined in \eqref{def:pot-pm} with such $\{(x^k,m^k)\}$ and $\{p_k\}$ given in \eqref{def:pk-unknown}. By Lemma \ref{lem:pk-mem-unk}, one can see that such $\{(\eta_k,\gamma_{k,t},\theta_{k,t},p_k)\}$ satisfies the assumptions in Lemma \ref{thm:rate-mem} and Algorithm \ref{alg:unf-sfom}.  Using this and similar arguments as those for deriving \eqref{rear-pot-desc-rm}, we obtain that for all $K\ge1$,
\begin{align*}
&f_{\mathrm{low}}\le f(x^0) + 4^{1/3}\sigma^\alpha - \eta_{K-1}\sum_{k=0}^{K-1} \mathbb{E}[\|\nabla f(x^k)\|] + \sum_{k=0}^{K-1}\Big(\frac{L_1}{2}\eta_k^2 + \frac{30^{1/(\alpha-1)}(\alpha-1)(2/\alpha)^{\alpha/(\alpha-1)}\eta_k^{\alpha/(\alpha-1)}}{(p_k\gamma_k)^{1/(\alpha-1)}}\nonumber\\
&\qquad \ + \frac{306p^{2\alpha p} L_p^\alpha}{(p!)^\alpha} p_k\gamma_k^{1-\alpha p}\eta_k^{\alpha p} + 64(p-1)^\alpha\sigma^\alpha p_k\gamma_k^\alpha\Big).%\label{upbd-sum-mem-unk}
\end{align*}
Rearranging the terms in this inequality, and using \eqref{def:t-Mpa-unk}, \eqref{def:h-Mpa-unk}, \eqref{def:eta-unknown-rate-mem}, \eqref{def:gmak-mem-unknow}, and \eqref{def:pk-unknown}, we obtain that for all $K\ge5$, 
\begin{align*}
&\frac{1}{K}\sum_{k=0}^{K-1}\mathbb{E}[\|\nabla f(x^k)\|] \le \frac{f(x^0) - f_{\mathrm{low}} + 4^{1/3}\sigma^\alpha}{K\eta_{K-1}} + \frac{1}{K\eta_{K-1}}\sum_{k=0}^{K-1}\Big(\frac{L_1}{2}\eta_k^2\nonumber\\
&\qquad  + \frac{30^{1/(\alpha-1)}(\alpha-1)(2/\alpha)^{\alpha/(\alpha-1)}\eta_k^{\alpha/(\alpha-1)}}{(p_k\gamma_k)^{1/(\alpha-1)}}+ \frac{306p^{2\alpha p} L_p^\alpha}{(p!)^\alpha} p_k\gamma_k^{1-\alpha p}\eta_k^{\alpha p} + 64(p-1)^\alpha\sigma^\alpha p_k\gamma_k^\alpha\Big)\\
&\overset{\eqref{def:eta-unknown-rate-mem}\eqref{def:gmak-mem-unknow}\eqref{def:pk-unknown}}{=} \frac{(f(x^0) - f_{\mathrm{low}} + 4^{1/3}\sigma^\alpha)(K+3)^{(2p+1)/(3p+1)}}{K} + \frac{(K+3)^{(2p+1)/(3p+1)}}{K}\sum_{k=0}^{K-1}\Big(\frac{L_1}{2(k+4)^{2(2p+1)/(3p+1)}}\nonumber\\
&\qquad  + \frac{30^{1/(\alpha-1)}(\alpha-1)(2/\alpha)^{\alpha/(\alpha-1)}+ 64(p-1)^\alpha\sigma^\alpha}{(k+4)^{(2p(2\alpha-1)+\alpha)/(3p\alpha+\alpha)}}+ \frac{306p^{2p\alpha} L_p^\alpha/(p!)^\alpha}{(k+4)^{(p(6\alpha-\alpha^2-2)+\alpha)/(3p\alpha+\alpha)}}\Big)\\
&\le \frac{2(f(x^0) - f_{\mathrm{low}} + 4^{1/3}\sigma^\alpha)}{K^{p/(3p+1)}} + \frac{2}{K^{p/(3p+1)}}\sum_{k=0}^{K-1}\Big(\frac{L_1}{2(k+4)^{2(2p+1)/(3p+1)}}\nonumber\\
&\qquad  + \frac{30^{1/(\alpha-1)}(\alpha-1)(2/\alpha)^{\alpha/(\alpha-1)}+ 64(p-1)^\alpha\sigma^\alpha}{(k+4)^{(2p(2\alpha-1)+\alpha)/(3p\alpha+\alpha)}}+ \frac{306p^{2p\alpha} L_p^\alpha/(p!)^\alpha}{(k+4)^{(p(6\alpha-\alpha^2-2)+\alpha)/(3p\alpha+\alpha)}}\Big)\\
&\le \frac{2(f(x^0) - f_{\mathrm{low}} + 4^{1/3}\sigma^\alpha)}{K^{p/(3p+1)}} + \frac{2}{K^{p/(3p+1)}}\sum_{k=0}^{K-1}\frac{L_1/2 + 306 p^{2p\alpha} L_p^\alpha/(p!)^\alpha}{k+4}\\
&\qquad + \frac{2}{K^{p/(3p+1)}}\sum_{k=0}^{K-1}\frac{(30^{1/(\alpha-1)}(\alpha-1)(2/\alpha)^{\alpha/(\alpha-1)}+ 64(p-1)^\alpha\sigma^\alpha)(K+3)^{p(2-\alpha)/(3p\alpha+\alpha)}}{k+4}\\
&\le \frac{2(f(x^0) - f_{\mathrm{low}} + 4^{1/3}\sigma^\alpha)}{K^{p/(3p+1)}} + \frac{2}{K^{p/(3p+1)}}\sum_{k=0}^{K-1}\frac{L_1/2 + 306 p^{2p\alpha} L_p^\alpha/(p!)^\alpha}{k+4}\\
&\qquad + \frac{4}{K^{p/(3p+1)}}\sum_{k=0}^{K-1}\frac{(30^{1/(\alpha-1)}(\alpha-1)(2/\alpha)^{\alpha/(\alpha-1)}+ 64(p-1)^\alpha\sigma^\alpha)K^{p(2-\alpha)/(3p\alpha+\alpha)}}{k+4}\\
% &\le \frac{2(f(x^0) - f_{\mathrm{low}} + 4^{1/3}\sigma^\alpha) + 2(L_1/2 + 306 p^{2p\alpha} L_p^\alpha/(p!)^\alpha)\ln(2K/5+1)}{K^{p/(3p+1)}}\\
% &\qquad\qquad +\frac{4(30^{1/(\alpha-1)}(\alpha-1)(2/\alpha)^{\alpha/(\alpha-1)}+ 64(p-1)^\alpha\sigma^\alpha)\ln(2K/5+1)}{K^{2p(\alpha-1)/(3p\alpha+\alpha)}}\\
&\le \frac{4(f(x^0) - f_{\mathrm{low}} + 4^{1/3}\sigma^\alpha + L_1/2 + 306 p^{2p\alpha} L_p^\alpha/(p!)^\alpha)\ln K}{K^{p/(3p+1)}}\\
&\qquad +\frac{8(30^{1/(\alpha-1)}(\alpha-1)(2/\alpha)^{\alpha/(\alpha-1)}+ 64(p-1)^\alpha\sigma^\alpha)\ln K}{K^{2p(\alpha-1)/(3p\alpha+\alpha)}} \overset{\eqref{def:t-Mpa-unk}\eqref{def:h-Mpa-unk}}{=} \frac{\widetilde{M}_{p,\alpha}\ln K}{K^{p/(3p+1)}} + \frac{\widehat{M}_{p,\alpha}\ln K}{K^{2p(\alpha-1)/(3p\alpha+\alpha)}},
\end{align*}
where the second inequality is due to $(K+3)^{(2p+1)/(3p+1)}\le 2K^{(2p+1)/(3p+1)}$ for all $K\ge5$, the third inequality follows from $2(2p+1)/(3p+1)\ge1$, $(p(6\alpha-\alpha^2-2)+\alpha)/(3p\alpha+\alpha)\ge1$, and $(2p(2\alpha-1)+\alpha)/(3p\alpha+\alpha)\le1$ for all $p\ge1$ and $\alpha\in(1,2]$, the fourth inequality is due to $(K+3)^{p(2-\alpha)/(3p\alpha+\alpha)}\le 2K^{p(2-\alpha)/(3p\alpha+\alpha)}$ for all $K\ge5$, and the last inequality follows from $\sum_{k=0}^{K-1}1/(k+4)\le \ln(2K/5+1) \leq 2\ln K$ for all $K\ge 5$ due to \eqref{upbd:series-ka}. Recall that $\iota_K$ is uniformly selected from $\{0,\ldots,K-1\}$. It then follows from this and the above relation that
\begin{align}\label{pre-upbd-mem-unk}
\E[\|\nabla f(x^{\iota_K})\|] = \frac{1}{K}\sum_{k=0}^{K-1}\mathbb{E}[\|\nabla f(x^k)\|] \le \frac{\widetilde{M}_{p,\alpha}\ln K}{K^{p/(3p+1)}} + \frac{\widehat{M}_{p,\alpha}\ln K}{K^{2p(\alpha-1)/(3p\alpha+\alpha)}}\qquad\forall K\ge 5.
\end{align}
By Lemma \ref{lem:rate-complexity} with $(\beta,u,v)=(p/(3p+1),p\epsilon/(4(3p+1)\widetilde{M}_{p,\alpha}),K)$ and $(\beta,u,v)=(2p(\alpha-1)/(3p\alpha+\alpha),p(\alpha-1)\epsilon/(2(3p\alpha+\alpha)\widehat{M}_{p,\alpha}),K)$, one can see that 
\begin{align*}
&K^{-p/(3p+1)}\ln K\le \frac{\epsilon}{2\widetilde{M}_{p,\alpha}}\qquad\forall K\ge\Big(\frac{4(3p+1)\widetilde{M}_{p,\alpha}}{p\epsilon}\ln\Big(\frac{4(3p+1)\widetilde{M}_{p,\alpha}}{p\epsilon}\Big)\Big)^{(3p+1)/p},\\
&K^{-2p(\alpha-1)/(3p\alpha+\alpha)}\ln K\le \frac{\epsilon}{2\widehat{M}_{p,\alpha}}\qquad\forall K\ge\Big(\frac{2(3p\alpha+\alpha)\widehat{M}_{p,\alpha}}{p(\alpha-1)\epsilon}\ln\Big(\frac{2(3p\alpha+\alpha)\widehat{M}_{p,\alpha}}{p(\alpha-1)\epsilon}\Big)\Big)^{(3p\alpha+\alpha)/(2p(\alpha-1))},
\end{align*}
which together with \eqref{pre-upbd-mem-unk} implies that Theorem \ref{thm:unknown-rate-mem} holds.
\end{proof}

\subsection{Proof of the main results in Section \ref{subsec:nsgd-rm}}\label{subsec:pf-rm}

In this subsection, we first establish several technical lemmas and then use them to prove Theorems \ref{thm:known-rate-rm} and \ref{thm:unknown-rate-rm}.  

The next lemma presents a recurrence relation for the estimation error of the gradient estimators $\{m^k\}$ generated by Algorithm \ref{alg:unf-sfom-rm}. 

\begin{lemma}%\label{lem:vr-rm}
Suppose that Assumptions \ref{asp:basic} and \ref{asp:gen-ave-smth} hold. Let $\{(x^k,m^k)\}$ be the sequence generated by Algorithm \ref{alg:unf-sfom-rm} with input parameters $\{(\eta_k,\theta_k)\}$. Then we have
\begin{align}
\mathbb{E}_{\xi^{k+1}}[\|m^{k+1}-\nabla f(x^{k+1})\|^\alpha] \le (1-\theta_k)\|m^k-\nabla f(x^k)\|^\alpha + 6(L_1^\alpha+L^\alpha)\eta_k^\alpha + 6\sigma^\alpha\theta_k^\alpha \qquad \forall k\ge0,\label{ineq:vr-rm}
\end{align}
where $L_1$, $\sigma$, $\alpha$, and $L$ are given in Assumptions \ref{asp:basic} and \ref{asp:gen-ave-smth}, respectively.
\end{lemma}

\begin{proof}
Fix any $k\ge0$. It follows from \eqref{update-mk-rm} that 
\begin{align}
m^{k+1} - \nabla f(x^{k+1}) &= (1-\theta_k)(m^k - \nabla f(x^k)) + G(x^{k+1};\xi^{k+1}) - \nabla f(x^{k+1}) \nonumber\\ 
&\quad + (1-\theta_k)(\nabla f(x^k) - G(x^k;\xi^{k+1})).\label{rm-idt-vr}
\end{align}
Observe from Algorithm \ref{alg:unf-sfom-rm} and Assumptions \ref{asp:basic} and \ref{asp:gen-ave-smth} that $\|x^{k+1}-x^k\|=\eta_k$, $\E_{\xi^{k+1}}[G(x^{k+1};\xi^{k+1})-\nabla f(x^{k+1})]=0$, $\E_{\xi^{k+1}}[G(x^k;\xi^{k+1})-\nabla f(x^k)]=0$, $\mathbb{E}_{\xi^{k+1}}[\|\nabla f(x^k) - G(x^k;\xi^{k+1}))\|^\alpha]\le\sigma^\alpha$, $\|\nabla f(x^k)-\nabla f(x^{k+1})\|\leq L_1 \eta_k$, and $\mathbb{E}_{\xi^{k+1}}[\|G(x^{k+1};\xi^{k+1}) - G(x^k;\xi^{k+1})\|^\alpha] \leq L^\alpha \eta_k^\alpha$. Using these, \eqref{open-alpha}, and \eqref{rm-idt-vr}, we obtain that 
\begin{align*}
&\mathbb{E}_{\xi^{k+1}}[\|m^{k+1} - \nabla f(x^{k+1})\|^\alpha] \\
&\overset{\eqref{rm-idt-vr}}{=}\mathbb{E}_{\xi^{k+1}}[\|(1-\theta_k)(m^k - \nabla f(x^k)) + G(x^{k+1};\xi^{k+1}) - \nabla f(x^{k+1}) + (1-\theta_k)(\nabla f(x^k) - G(x^k;\xi^{k+1}))\|^\alpha] \\
&\le(1-\theta_k)^\alpha\|m^k-\nabla f(x^k)\|^\alpha+ 2\mathbb{E}_{\xi^{k+1}}[\|G(x^{k+1};\xi^{k+1}) - \nabla f(x^{k+1}) + (1-\theta_k)(\nabla f(x^k) - G(x^k;\xi^{k+1}))\|^\alpha]\\
&=(1-\theta_k)^\alpha\|m^k-\nabla f(x^k)\|^\alpha +  2\mathbb{E}_{\xi^{k+1}}\big[\|G(x^{k+1};\xi^{k+1}) - G(x^k;\xi^{k+1}) + \nabla f(x^k) - \nabla f(x^{k+1}) \\ 
& \quad - \theta_k(\nabla f(x^k) - G(x^k;\xi^{k+1}))\|^\alpha\big]\\
&\le(1-\theta_k)^\alpha\|m^k-\nabla f(x^k)\|^\alpha + 6\mathbb{E}_{\xi^{k+1}}\big[\|G(x^{k+1};\xi^{k+1}) - G(x^k;\xi^{k+1})\|^\alpha]+ 6\|\nabla f(x^{k+1})-\nabla f(x^k)\|^\alpha \\
&\quad+ 6\theta_k^\alpha \mathbb{E}_{\xi^{k+1}}[\|\nabla f(x^k) - G(x^k;\xi^{k+1}))\|^\alpha\big]\\
&\le (1-\theta_k)^\alpha\|m^k-\nabla f(x^k)\|^\alpha + 6(L_1^\alpha+L^\alpha)\eta_k^\alpha + 6\sigma^\alpha\theta_k^\alpha,
\end{align*}
where the first inequality is due to \eqref{open-alpha}, $\E_{\xi^{k+1}}[G(x^{k+1};\xi^{k+1})-\nabla f(x^{k+1})]=0$, and $\E_{\xi^{k+1}}[G(x^k;\xi^{k+1})-\nabla f(x^k)]=0$, the second inequality follows from $\|a+b+c\|^\alpha\le3(\|a\|^\alpha+\|b\|^\alpha+\|c\|^\alpha)$ for all $a,b,c\in\mathbb{R}^n$ due to $\alpha\in(1,2]$ and the convexity of $\|\cdot\|^{\alpha}$, and the last inequality is due to $\mathbb{E}_{\xi^{k+1}}[\|\nabla f(x^k) - G(x^k;\xi^{k+1}))\|^\alpha]\le\sigma^\alpha$, $\|\nabla f(x^k)-\nabla f(x^{k+1})\|\leq L_1 \eta_k$, and $\mathbb{E}_{\xi^{k+1}}[\|G(x^{k+1};\xi^{k+1}) - G(x^k;\xi^{k+1})\|^\alpha] \leq L^\alpha \eta_k^\alpha$. The above relation together with $\theta_k\in(0,1]$ and $\alpha\in(1,2]$ implies that this lemma holds.
\end{proof}


The following lemma establishes a descent property for the potential sequence $\{{\mathcal P}_k\}$ defined below.

\begin{lemma}\label{thm:stat-bd-rm}
Suppose that Assumptions \ref{asp:basic} and \ref{asp:gen-ave-smth} hold. Let $\{(x^k,m^k)\}$ be the sequence generated by Algorithm \ref{alg:unf-sfom-rm} with input parameters $\{(\eta_k,\theta_k)\}$. Let $L_1$, $\alpha$, and $\sigma$ be given in Assumption \ref{asp:basic}, $L$ be given in Assumption \ref{asp:gen-ave-smth}, and $\{{\mathcal P}_k\}$ be defined in \eqref{def:pot-pm} for $\{(x^k,m^k)\}$ and any positive sequence $\{p_k\}$ that satisfies $(1-\theta_k)p_{k+1} \le (1-\theta_k/2)p_k$ for all $k\ge0$. Then it holds that for all $k\geq 0$,
\begin{align}
&\mathbb{E}_{\xi^{k+1}}[{\mathcal P}_{k+1}]  \le {\mathcal P}_k- \eta_k\|\nabla f(x^k)\| + \frac{L_1}{2}\eta_k^2+ \frac{(\alpha-1)(2\eta_k)^{\alpha/(\alpha-1)}}{\alpha^{\alpha/(\alpha-1)}(\theta_kp_k/2)^{1/(\alpha-1)}} + 6(L_1^\alpha+L^\alpha)\eta_k^\alpha  p_{k+1} + 6\sigma^\alpha\theta_k^\alpha p_{k+1}.\label{stat-bd-rm}
\end{align}
\end{lemma}

\begin{proof}
Fix any $k\ge0$. By Lemma \ref{lem:ppt-desc} with $(x^+,x,m,\eta)=(x^{k+1},x^k,m^k,\eta_k)$, one has 
\begin{align}\label{upbd-fxk+1-rm}
f(x^{k+1}) \le f(x^k) - \eta_k\|\nabla f(x^k)\| + 2\eta_k\|\nabla f(x^k) - m^k\| + \frac{L_1}{2}\eta_k^2.    
\end{align}
Combining this with \eqref{def:pot-pm} and \eqref{ineq:vr-rm}, we obtain that 
\begin{align}
&\mathbb{E}_{\xi^{k+1}}[{\mathcal P}_{k+1}] \overset{\eqref{def:pot-pm}}{=} \mathbb{E}_{\xi^{k+1}}[f(x^{k+1}) + p_{k+1}\|m^{k+1} - \nabla f(x^{k+1})\|^\alpha] \nonumber\\
&\overset{\eqref{ineq:vr-rm}\eqref{upbd-fxk+1-rm}}{\le} f(x^k) - \eta_k\|\nabla f(x^k)\| + 2\eta_k\|\nabla f(x^k) - m^k\| + \frac{L_1}{2}\eta_k^2  \nonumber\\
&\qquad \ + (1-\theta_k)p_{k+1}\|m^k-\nabla f(x^k)\|^\alpha + 6(L_1^\alpha+L^\alpha)\eta_k^\alpha  p_{k+1} + 6\sigma^\alpha\theta_k^\alpha p_{k+1}\nonumber\\
&\le f(x^k) - \eta_k\|\nabla f(x^k)\| + 2\eta_k\|\nabla f(x^k) - m^k\| + \frac{L_1}{2}\eta_k^2 \nonumber\\
&\quad + (1-\theta_k/2)p_k\|m^k-\nabla f(x^k)\|^\alpha + 6(L_1^\alpha+L^\alpha)\eta_k^\alpha  p_{k+1} + 6\sigma^\alpha\theta_k^\alpha p_{k+1},\label{pf-pot-desc-rm}
\end{align}
where the last inequality follows from $(1-\theta_k)p_{k+1}\le(1-\theta_k/2)p_k$. In addition, letting $\alpha^\prime=\alpha/(\alpha-1)$, and using the Young's inequality, one has that
\begin{align*}
2\eta_k\|\nabla f(x^k) - m^k\| & \le \frac{((\alpha\theta_k p_k/2)^{1/\alpha} \|\nabla f(x^k) - m^k\|)^\alpha}{\alpha} + \frac{(2\eta_k/(\alpha\theta_k p_k/2)^{1/\alpha})^{\alpha^\prime}}{\alpha^\prime}\\
&= \frac{\theta_k p_k}{2} \|\nabla f(x^k) - m^k\|^\alpha + \frac{(\alpha-1)(2\eta_k)^{\alpha/(\alpha-1)}}{\alpha^{\alpha/(\alpha-1)}(\theta_kp_k/2)^{1/(\alpha-1)}}.
\end{align*}
This together with \eqref{pf-pot-desc-rm} implies that
\begin{align*}
&\mathbb{E}_{\xi^{k+1}}[{\mathcal P}_{k+1}]  \le f(x^k) + p_k\|\nabla f(x^k) - m^k\|^\alpha -\eta_k\|\nabla f(x^k)\| + \frac{L_1}{2}\eta_k^2+\frac{(\alpha-1)(2\eta_k)^{\alpha/(\alpha-1)}}{\alpha^{\alpha/(\alpha-1)}(\theta_kp_k/2)^{1/(\alpha-1)}} \\
&\qquad\qquad\qquad+ 6(L_1^\alpha+L^\alpha)\eta_k^\alpha  p_{k+1} + 6\sigma^\alpha\theta_k^\alpha p_{k+1} \\
&\le {\mathcal P}_k- \eta_k\|\nabla f(x^k)\| + \frac{L_1}{2}\eta_k^2  + \frac{(\alpha-1)(2\eta_k)^{\alpha/(\alpha-1)}}{\alpha^{\alpha/(\alpha-1)}(\theta_kp_k/2)^{1/(\alpha-1)}} + 6(L_1^\alpha+L^\alpha)\eta_k^\alpha  p_{k+1} + 6\sigma^\alpha\theta_k^\alpha p_{k+1}.   
\end{align*}    
By this and \eqref{def:pot-pm}, one can see that \eqref{stat-bd-rm} holds.
\end{proof}

The following lemma establishes some property for a specific choice of $\{(\theta_k, p_k)\}$, which will be used to prove Theorem \ref{thm:known-rate-rm} subsequently.

\begin{lemma}\label{lem:pk-know-rm}
Let $\{\theta_k\}$ be given in \eqref{rm-eta-theta}, and $\{p_k\}$ be defined as 
\begin{align}\label{def:pot-known-rm}
p_k= (k+1)^{(\alpha-1)^2/(2\alpha-1)}\qquad\forall k\ge0.    
\end{align}
Then $(1-\theta_k)p_{k+1}\le (1-\theta_k/2)p_k$ holds for all $k\ge0$.
\end{lemma}

\begin{proof}
Fix any $k\ge0$. It follows from \eqref{rm-eta-theta} that
\begin{align}\label{frac-pktk-rm}
\frac{1-\theta_k/2}{1-\theta_k} =1 + \frac{\theta_k}{2(1-\theta_k)} \ge 1 + \frac{\theta_k}{2} \overset{\eqref{rm-eta-theta}}{=} 1 + \frac{1}{2(k+1)^{\alpha/(2\alpha-1)}} \ge 1 + \frac{1}{2(k+1)},
\end{align}
where the last inequality is due to $\alpha/(2\alpha-1)<1$ for all $\alpha\in(1,2]$. In addition, notice from \eqref{def:pot-known-rm} that
\begin{align*}
\frac{p_{k+1}}{p_k} = \Big(1+\frac{1}{k+1} \Big)^{(\alpha-1)^2/(2\alpha-1)} \le \Big(1+\frac{1}{k+1} \Big)^{1/3} \le 1+\frac{1}{3(k+1)},   
\end{align*}
where the first inequality is due to $(\alpha-1)^2/(2\alpha-1)\le1/3$ for all $\alpha\in(1,2]$, and the last inequality is due to $(1+\tau)^\beta\le 1+\tau \beta$ for all $\tau>-1$ and $\beta\in[0,1]$. The above relation along with \eqref{frac-pktk-rm} implies that $(1-\theta_k)p_{k+1}\le (1-\theta_k/2)p_k$ holds.
\end{proof}

We are now ready to prove Theorem \ref{thm:known-rate-rm}.

\begin{proof}[\textbf{Proof of Theorem \ref{thm:known-rate-rm}}]
Let $\{(x^k,m^k)\}$ be generated by Algorithm \ref{alg:unf-sfom-rm} with $\{(\eta_k,\theta_k)\}$ defined in \eqref{rm-eta-theta}, and let 
$\{{\mathcal P}_k\}$ be defined in \eqref{def:pot-pm} with such $\{(x^k,m^k)\}$ and $\{p_k\}$ given in \eqref{def:pot-known-rm}. By Lemma \ref{lem:pk-know-rm}, one can see that such $\{(\eta_k,\theta_k,p_k)\}$ satisfies the assumptions in Lemma \ref{thm:stat-bd-rm} and Algorithm \ref{alg:unf-sfom-rm}. In addition, by \eqref{def:pot-pm} and \eqref{def:pot-known-rm}, one has that
\begin{align}
&\mathbb{E}[{\mathcal P}_0]= f(x^0)+p_0\mathbb{E}[\|m^0-\nabla f(x^0)\|^\alpha]= f(x^0) + \mathbb{E}[\|G(x^0;\xi^0)-\nabla f(x^0)\|^\alpha]\le f(x^0)+\sigma^\alpha,\label{upbd-exp-P0-rm}\\ 
&\mathbb{E}[{\mathcal P}_K]= \mathbb{E}[f(x^K)+p_K\|m^K-\nabla f(x^K)\|^\alpha]\ge \mathbb{E}[f(x^K)] \ge f_{\mathrm{low}}.\label{lwbd-exp-Pk-rm}
\end{align}
Taking expectation on both sides of \eqref{stat-bd-rm} with respect to $\{\xi^i\}_{i=0}^{k+1}$, we have {that for all $k\ge0$,}
\[
\mathbb{E}[{\mathcal P}_{k+1}]  \le \mathbb{E}[{\mathcal P}_k]- \eta_k\mathbb{E}[\|\nabla f(x^k)\|] + \frac{L_1}{2}\eta_k^2+ \frac{(\alpha-1)(2\eta_k)^{\alpha/(\alpha-1)}}{\alpha^{\alpha/(\alpha-1)}(\theta_kp_k/2)^{1/(\alpha-1)}} + 6(L_1^\alpha+L^\alpha)\eta_k^\alpha  p_{k+1} + 6\sigma^\alpha\theta_k^\alpha p_{k+1}.
\]
Summing up this inequality over $k=0,\ldots,K-1$, and using \eqref{upbd-exp-P0-rm} and \eqref{lwbd-exp-Pk-rm}, we {obtain that for all $K\ge1$,}
\begin{align}
f_{\mathrm{low}} & \overset{\eqref{lwbd-exp-Pk-rm}}{\le} \mathbb{E}[{\mathcal P}_K]\le \E[{\mathcal P}_0] - \sum_{k=0}^{K-1}\eta_k\mathbb{E}[\|\nabla f(x^k)\|] + \sum_{k=0}^{K-1}\Big(\frac{L_1}{2}\eta_k^2 + \frac{(\alpha-1)(2\eta_k)^{\alpha/(\alpha-1)}}{\alpha^{\alpha/(\alpha-1)}(\theta_kp_k/2)^{1/(\alpha-1)}} \nonumber \\ 
&\qquad+ 6(L_1^\alpha+L^\alpha)\eta_k^\alpha  p_{k+1} + 6\sigma^\alpha\theta_k^\alpha p_{k+1}\Big)\nonumber\\
&\overset{\eqref{upbd-exp-P0-rm}}{\le} f(x^0) + \sigma^\alpha - \eta_{K-1}\sum_{k=0}^{K-1}\mathbb{E}[\|\nabla f(x^k)\|]  + \sum_{k=0}^{K-1}\Big(\frac{L_1}{2}\eta_k^2 + \frac{(\alpha-1)(2\eta_k)^{\alpha/(\alpha-1)}}{\alpha^{\alpha/(\alpha-1)}(\theta_kp_k/2)^{1/(\alpha-1)}} \nonumber \\
&\qquad + 12(L_1^\alpha+L^\alpha)\eta_k^\alpha p_k + 12\sigma^\alpha\theta_k^\alpha p_k\Big),\label{rear-pot-desc-rm-known}
\end{align}
where the last inequality follows from \eqref{upbd-exp-P0-rm} and the fact that $\{\eta_k\}$ is nonincreasing and $p_{k+1}\le 2p_k$ for all $k\ge0$. Rearranging the terms in \eqref{rear-pot-desc-rm-known}, and using \eqref{Ma-rm}, \eqref{rm-eta-theta}, and \eqref{def:pot-known-rm}, we obtain that for all $K\ge3$,
\begin{align*}
&\frac{1}{K}\sum_{k=0}^{K-1}\mathbb{E}[\|\nabla f(x^k)\|] \overset{\eqref{rear-pot-desc-rm-known}}{\le} \frac{f(x^0) - f_{\mathrm{low}}+\sigma^\alpha}{K\eta_{K-1}}\\
&\qquad + \frac{1}{K\eta_{K-1}}\sum_{k=0}^{K-1}\Big(\frac{L_1}{2}\eta_k^2 + \frac{(\alpha-1)(2\eta_k)^{\alpha/(\alpha-1)}}{\alpha^{\alpha/(\alpha-1)}(\theta_kp_k/2)^{1/(\alpha-1)}} + 12(L_1^\alpha+L^\alpha)\eta_k^\alpha p_k + 12\sigma^\alpha\theta_k^\alpha p_k\Big)\\
&\overset{\eqref{rm-eta-theta}\eqref{def:pot-known-rm}}{=} \frac{f(x^0) - f_{\mathrm{low}}+\sigma^\alpha}{K^{(\alpha-1)/(2\alpha-1)}} \\
&\qquad + \frac{1}{K^{(\alpha-1)/(2\alpha-1)}}\sum_{k=0}^{K-1}\Big(\frac{L_1}{2(k+1)^{2\alpha/(2\alpha-1)}} + \frac{2^{1/(\alpha-1)}(\alpha-1)(2/\alpha)^{\alpha/(\alpha-1)} + 12(L_1^\alpha+L^\alpha) + 12\sigma^\alpha}{k+1}\Big)\\
& \le \frac{f(x^0) - f_{\mathrm{low}}+\sigma^\alpha}{K^{(\alpha-1)/(2\alpha-1)}} + \frac{L_1/2 + 2^{1/(\alpha-1)}(\alpha-1)(2/\alpha)^{\alpha/(\alpha-1)} + 12(L_1^\alpha+L^\alpha) + 12\sigma^\alpha}{K^{(\alpha-1)/(2\alpha-1)}}\sum_{k=0}^{K-1}\frac{1}{k+1}\\
% &\le \frac{f(x^0) - f_{\mathrm{low}}+\sigma^\alpha+ (L_1/2 + 2^{1/(\alpha-1)}(\alpha-1)(2/\alpha)^{\alpha/(\alpha-1)} + 12(L_1^\alpha+L^\alpha) + 12\sigma^\alpha)\ln(2K+1)}{K^{(\alpha-1)/(2\alpha-1)}}\\
&\le \frac{2(f(x^0) - f_{\mathrm{low}}+\sigma^\alpha+ L_1/2 + 2^{1/(\alpha-1)}(\alpha-1)(2/\alpha)^{\alpha/(\alpha-1)} + 12(L_1^\alpha+L^\alpha) + 12\sigma^\alpha)\ln K}{K^{(\alpha-1)/(2\alpha-1)}}\\
&\overset{\eqref{Ma-rm}}{=} \frac{M_\alpha\ln K}{K^{(\alpha-1)/(2\alpha-1)}},
\end{align*}
where the second inequality follows from $2\alpha/(2\alpha-1)>1$, the third inequality follows from $\sum_{k=0}^{K-1}1/(k+1)\le \ln(2K+1)\le 2\ln K$ due to \eqref{upbd:series-ka} and $K\ge 3$. Recall that $\iota_K$ is uniformly selected from $\{0,\ldots,K-1\}$. It follows from this and the above relation that
\begin{align}\label{pre-upbd-rm}
\E[\|\nabla f(x^{\iota_K})\|] = \frac{1}{K}\sum_{k=0}^{K-1}\mathbb{E}[\|\nabla f(x^k)\|] \le \frac{M_{\alpha}\ln K}{K^{(\alpha-1)/(2\alpha-1)}}\qquad\forall K\ge 3.
\end{align}
By Lemma \ref{lem:rate-complexity} with $(\beta,u,v)=((\alpha-1)/(2\alpha-1),(\alpha-1)\epsilon/(2(2\alpha-1)M_{\alpha}),K)$, one can see that 
\begin{align*}
K^{-(\alpha-1)/(2\alpha-1)}\ln K\le \frac{\epsilon}{M_{\alpha}}\qquad\forall K\ge\Big(\frac{2(2\alpha-1)M_{\alpha}}{(\alpha-1)\epsilon}\ln\Big(\frac{2(2\alpha-1)M_{\alpha}}{(\alpha-1)\epsilon}\Big)\Big)^{(2\alpha-1)/(\alpha-1)},    
\end{align*}
which together with \eqref{pre-upbd-rm} implies that Theorem \ref{thm:known-rate-rm} holds.
\end{proof}

The next lemma establishes some property for a specific choice of $\{(\theta_k, p_k)\}$, which will be used to prove Theorem \ref{thm:unknown-rate-rm} subsequently.

\begin{lemma}\label{lem:pk-unknow-rm}
Let $\{\theta_k\}$ be given in \eqref{rm-eta-theta-un}, and $\{p_k\}$ be defined as  
\begin{align}\label{def:pk-unknown-rm}
p_k= (k+1)^{2(\alpha-1)^2/(3\alpha)}\qquad\forall k\ge0.   
\end{align}
Then $(1-\theta_k)p_{k+1}\le (1-\theta_k/2)p_k$ holds for all $k\ge0$.
\end{lemma}

\begin{proof}
Fix any $k\ge0$. Observe that
\begin{align}\label{frac-pktk-rm-u}
\frac{1-\theta_k/2}{1-\theta_k} = 1 + \frac{\theta_k}{2(1-\theta_k)} \ge 1 + \frac{\theta_k}{2} \overset{\eqref{rm-eta-theta-un}}{=} 1 + \frac{1}{2(k+1)^{2/3}} \ge 1 + \frac{1}{2(k+1)},
\end{align}
In addition, notice from \eqref{def:pk-unknown-rm} that
\begin{align*}
\frac{p_{k+1}}{p_k} = \Big(1+\frac{1}{k+1} \Big)^{2(\alpha-1)^2/(3\alpha)} \le \Big(1+\frac{1}{k+1} \Big)^{1/3} \le 1+\frac{1}{3(k+1)},   
\end{align*}
where the first inequality is due to $2(\alpha-1)^2/(3\alpha)\le1/3$ for all $\alpha\in(1,2]$, and the last inequality is due to $(1+\tau)^\beta\le 1+\tau \beta$ for all $\tau>-1$ and $\beta\in[0,1]$. The above relation together with \eqref{frac-pktk-rm-u} implies that $(1-\theta_k)p_{k+1}\le (1-\theta_k/2)p_k$ holds.
\end{proof}

We are now ready to prove Theorem \ref{thm:unknown-rate-rm}.
\begin{proof}[\textbf{Proof of Theorem \ref{thm:unknown-rate-rm}}]
Let $\{(x^k,m^k)\}$ be generated by Algorithm \ref{alg:unf-sfom-rm} with $\{(\eta_k,\theta_k)\}$ defined in \eqref{rm-eta-theta-un}, and let 
$\{{\mathcal P}_k\}$ be defined in \eqref{def:pot-pm} with such $\{(x^k,m^k)\}$ and $\{p_k\}$ given in \eqref{def:pk-unknown-rm}. By Lemma \ref{lem:pk-unknow-rm}, one can see that such $\{(\eta_k,\theta_k,p_k)\}$ satisfies the assumptions in Lemma \ref{thm:stat-bd-rm} and Algorithm \ref{alg:unf-sfom-rm}. Using this and similar arguments as those for deriving \eqref{rear-pot-desc-rm-known}, we have {that for all $K\ge1$,}
\begin{align}
&f_{\mathrm{low}}\le f(x^0) + \sigma^\alpha - \eta_{K-1}\sum_{k=0}^{K-1}\mathbb{E}[\|\nabla f(x^k)\|] \nonumber\\
&\qquad\ \ + \sum_{k=0}^{K-1}\Big(\frac{L_1}{2}\eta_k^2 + \frac{(\alpha-1)(2\eta_k)^{\alpha/(\alpha-1)}}{\alpha^{\alpha/(\alpha-1)}(\theta_kp_k/2)^{1/(\alpha-1)}} + 12(L_1^\alpha+L^\alpha)\eta_k^\alpha p_k + 12\sigma^\alpha\theta_k^\alpha p_k\Big). \label{bd-unk-rm}
\end{align}
Rearranging the terms in \eqref{bd-unk-rm},  and using \eqref{Ma-tilde-rm}, \eqref{Ma-hat-rm}, \eqref{rm-eta-theta-un}, and \eqref{def:pk-unknown-rm}, we obtain that for all $K\ge3$,
\begin{align*}
&\frac{1}{K}\sum_{k=0}^{K-1}\mathbb{E}[\|\nabla f(x^k)\|] \overset{\eqref{bd-unk-rm}}{\le} \frac{f(x^0) - f_{\mathrm{low}} + \sigma^\alpha}{K\eta_{K-1}}\\
&\qquad\qquad + \frac{1}{K\eta_{K-1}} \sum_{k=0}^{K-1}\Big(\frac{L_1}{2}\eta_k^2 + \frac{(\alpha-1)(2\eta_k)^{\alpha/(\alpha-1)}}{\alpha^{\alpha/(\alpha-1)}(\theta_kp_k/2)^{1/(\alpha-1)}} + 12(L_1^\alpha+L^\alpha)\eta_k^\alpha p_k + 12\sigma^\alpha\theta_k^\alpha p_k\Big)\\
&\overset{\eqref{rm-eta-theta-un}\eqref{def:pk-unknown-rm}}{=}\frac{f(x^0) - f_{\mathrm{low}} + \sigma^\alpha}{K^{1/3}} + \frac{1}{K^{1/3}}\sum_{k=0}^{K-1}\Big(\frac{L_1}{2(k+1)^{4/3}} + \frac{2^{1/(\alpha-1)}(\alpha-1)(2/\alpha)^{\alpha/(\alpha-1)}+ 12(L_1^\alpha+L^\alpha) + 12\sigma^\alpha}{(k+1)^{2(2\alpha-1)/(3\alpha)}}\Big)\\
&\le \frac{f(x^0) - f_{\mathrm{low}} + \sigma^\alpha}{K^{1/3}} + \frac{1}{K^{1/3}}\sum_{k=0}^{K-1}\Big(\frac{L_1}{2(k+1)} + \frac{(2^{1/(\alpha-1)}(\alpha-1)(2/\alpha)^{\alpha/(\alpha-1)}+ 12(L_1^\alpha+L^\alpha) + 12\sigma^\alpha)K^{(2-\alpha)/(3\alpha)}}{k+1}\Big)\\
% &\le \frac{f(x^0) - f_{\mathrm{low}} + \sigma^\alpha}{K^{1/3}} + \frac{(L_1/2+(2^{1/(\alpha-1)}(\alpha-1)(2/\alpha)^{\alpha/(\alpha-1)}+ 12(L_1^\alpha+L^\alpha) + 12\sigma^\alpha)K^{(2-\alpha)/(3\alpha)})\ln(2K+1)}{K^{1/3}}\\
&\le \frac{2(f(x^0) - f_{\mathrm{low}} + \sigma^\alpha + L_1/2)\ln K}{K^{1/3}} + \frac{2(2^{1/(\alpha-1)}(\alpha-1)(2/\alpha)^{\alpha/(\alpha-1)}+ 12(L_1^\alpha+L^\alpha) + 12\sigma^\alpha)\ln K}{K^{2(\alpha-1)/(3\alpha)}}\\
&\overset{\eqref{Ma-tilde-rm}\eqref{Ma-hat-rm}}{=}\frac{\widetilde{M}_\alpha \ln K}{K^{1/3}} + \frac{\widehat{M}_\alpha \ln K}{K^{2(\alpha-1)/(3\alpha)}},
\end{align*}
where the second inequality follows from $2(2\alpha-1)/(3\alpha)\le 1$ for all $\alpha\in(1,2]$, and the last inequality follows from $\sum_{k=0}^{K-1}1/(k+1)\le 2\ln K$ due to \eqref{upbd:series-ka} and $K\ge 3$. Recall that $\iota_K$ is uniformly selected from $\{0,\ldots,K-1\}$. It follows from this and the above relation that
\begin{align}\label{pre-upbd-rm-unk}
\E[\|\nabla f(x^{\iota_K})\|] = \frac{1}{K}\sum_{k=0}^{K-1}\mathbb{E}[\|\nabla f(x^k)\|] \le \frac{\widetilde{M}_{\alpha}\ln K}{K^{1/3}} + \frac{\widehat{M}_{\alpha}\ln K}{K^{2(\alpha-1)/(3\alpha)}}\qquad\forall K\ge 3.
\end{align}
By Lemma \ref{lem:rate-complexity} with $(\beta,u,v)=(1/3,\epsilon/(12\widetilde{M}_{\alpha}),K)$ and $(\beta,u,v)=(2(\alpha-1)/(3\alpha),(\alpha-1)\epsilon/(6\alpha\widehat{M}_{\alpha}),K)$, one can see that 
\begin{align*}
&K^{-1/3}\ln K\le \frac{\epsilon}{2\widetilde{M}_{\alpha}}\qquad\forall K\ge\Big(\frac{12\widetilde{M}_{\alpha}}{\epsilon}\ln\Big(\frac{12\widetilde{M}_{\alpha}}{\epsilon}\Big)\Big)^{3},\\
&K^{-2(\alpha-1)/(3\alpha)}\ln K\le \frac{\epsilon}{2\widehat{M}_{\alpha}}\qquad\forall K\ge\Big(\frac{6\alpha\widehat{M}_{\alpha}}{(\alpha-1)\epsilon}\ln\Big(\frac{6\alpha\widehat{M}_{\alpha}}{(\alpha-1)\epsilon}\Big)\Big)^{3\alpha/(2(\alpha-1))},
\end{align*}
which together with \eqref{pre-upbd-rm-unk} implies that Theorem \ref{thm:unknown-rate-rm} holds.
\end{proof}


