\begin{document}



\title{Class field theory for function fields and finite abelian torsors}


\author[B. Cais]{Bryden Cais}
\address{Department of Mathematics, The University of Arizona,
Tucson, Arizona, USA}


\email{cais@math.arizona.edu}

\author[S. Otabe]{Shusuke Otabe}
\address{Graduate School of Engineering, Nagoya Institute of Technology, Nagoya, Aichi, Japan
}
\email{shusuke.otabe@nitech.ac.jp}


\thanks{The first named author was supported by NSF DMS-2302072.
The second named author was supported by JSPS KAKENHI Grant Numbers JP21K20334, JP24K16894.}


\date{\today}

\keywords{geometric class field theory, fundamental group schemes, curves, positive characteristic}
\subjclass{14H30, 14H40, 14L15}



\thispagestyle{empty}

\begin{abstract}
Let $U$ be a smooth and connected curve over an algebraically
closed field of positive characteristic, with smooth compactification $X$.
We generalize classical Geometric Class Field theory
to provide a classification of fppf $G$-torsors 
over $U$ in terms of isogenies of generalized Jacobians, for any finite
abelian group scheme $G$.  
We then apply this classification to give a novel description 
of
the abelianized Nori fundmental group scheme 
of $U$ in terms of the Serre--Oort fundamental groups
of generalized Jacobians of $X$; when $U=X$ is projective, 
we recover a well known description of the abelianized fundamental group scheme of $X$ as the projective limit of all torsion subgroup schemes of
its Jacobian.
\end{abstract}


\maketitle





\thispagestyle{empty}





\section{Introduction}\label{sec:intro}


Pioneered by Lang \cite{Lang} and Rosenlicht \cite{Rosenlicht54,Rosenlicht57} in the 1950's,
and 
expounded in Serre's book \cite{Serre59},
Geometric Class Field theory provides a beautiful description of the 
abelian covers of 
a smooth, projective 
and connected curve $X$ over an algebraically closed field $k$ 
in terms of \'etale isogenies onto its generalized Jacobians.
In the case of unramified coverings, this description is encapsulated
by an identification of profinite abelian groups
\begin{equation}
    \pi_1^{\et}(X)^{\ab} \simeq \varprojlim_n J_X[n](k),
    \label{eq:Lang}
\end{equation}
with $J_X$ the Jacobian of $X$.  Via Nori's theory of the fundamental group scheme \cite{Nori82},
\eqref{eq:Lang} admits a striking enrichment to an isomorphism
of profinite group {\em schemes}
\begin{equation}
    \pi^{\Nori}(X)^{\ab} \simeq \varprojlim_n J_X[n]
    \label{eq:Nori}
\end{equation}
recovering \eqref{eq:Lang} on $k$-points; see
\cite[Remark 2]{Nori83} and cf.~\cite[Corollary 3.8]{Antei}\cite[Corollary 7.2]{Langer}.  The isomorphism \eqref{eq:Nori} is likewise equivalent to
an enrichment of unramified Geometric Class Field theory
to a classification of {fppf} $G$-torsors over $X$
for an arbitrary finite abelian $k$-group scheme $G$
in terms of (not necessarily separable) isogenies onto $J_X$.

It is natural to ask for analogues of \eqref{eq:Lang}--\eqref{eq:Nori}
in the case of {\em ramified} coverings, or equivalently, 
for analogous descriptions of the abelianized fundamental group
(scheme) of a smooth {\em affine} curve.  
In the case of
\eqref{eq:Lang}, such a description essentially goes back to Serre \cite[\S5.2]{Serre61},
whose work gives an identification of profinite abelian groups
\begin{equation}
        \pi_1^{\et}(X\setminus S)^{\ab} \simeq \varprojlim_{\frkm} \varpi_1(J_{X,\frkm})(k)
        \label{eq:serre-affine}
\end{equation}
for any finite set $S\subset X(k)$, 
in which $\varpi_1(\cdot)$ is the {\em Serre--Oort fundamental group}, as defined by
Oort \cite[II,\S7]{Oort} (cf.~\cite{Brion}), $J_{X,\frkm}$
is the generalized Jacobian of $X$ with modulus $\frkm$,
and
the inverse limit is taken over all $\frkm$ supported on $S$.


In this paper, we establish the natural analogue of \eqref{eq:Nori}
for arbitrary smooth affine curves by enriching \eqref{eq:serre-affine} 
to an isomorphism of profinite group schemes:

\begin{thm}\label{thm:main-intro}
    Let $X$ be a smooth projective and connected curve over $k$
    and $S\subset X(k)$ any finite set of points.  There is an isomorphism
    of profinite group schemes
    \begin{equation}
        \pi^{\Nori}(X\setminus S)^{\ab} \simeq \varprojlim_{\frkm} \varpi_1(J_{X,\frkm})
        \label{eq:nori-affine}
\end{equation}
    recovering \eqref{eq:serre-affine} on $k$-points.
\end{thm}

\begin{rem}
    A precursor to the Serre--Oort fundamental group $\varpi_1(\cdot)$
    was defined by Serre \cite[\S5.3]{Serre_GP}, who constructed
    a functor from 
    the category of
    pro-algebraic $k$-groups (in the sense of \cite[\S2.1 Definition I]{Serre_GP}) to the category of profinite abelian groups.  At the time, Grothendieck's theory of group {\em schemes} was in its infancy, so Serre's category of proalgebraic groups may look strange
    to a modern reader: it is the pro-category of the category of {\em quasi-algebraic groups},
    the latter being the localization of the category of commutative, smooth algebraic $k$-groups
    at the class of morphisms inducing an isomorphism on $k$-points. 
    Oort \cite[II.7]{Oort} generalized Serre's construction
    to define $\varpi_1(\cdot)$ as a functor from the pro-category of commutative algebraic $k$-groups
    to the category of profinite commutative $k$-group {\em schemes}.  We review Oort's construction 
    in \S\ref{sec:ab Nori}, noting here that for a commutative and connected algebraic $k$-group $H$, one has the ``concrete'' description
    \begin{equation}
            \varpi_1(H) = \varprojlim_{\varphi: H'\twoheadrightarrow H} \ker(\varphi)
            \label{eqn:varpi-concrete}
    \end{equation}
    with the limit taken over all isogenies  $\varphi:H'\twoheadrightarrow H$
    of commutative algebraic $k$-groups.  Thus, \eqref{eq:nori-affine} provides a description of the abelianized
    Nori fundamental group of $X\setminus S$ in terms of isogenies onto the generalized Jacobians of 
    $X$ with moduli supported on $S$.
    More or less by definition, the associated profinite abelian
    group of $k$-points $\varpi_1(\cdot)(k)$ recovers Serre's original construction. 

    Note that when $S=\emptyset$,
    \eqref{eq:serre-affine} and \eqref{eq:nori-affine} recover
    \eqref{eq:Lang} and \eqref{eq:Nori}, respectively, 
    as every isogeny with target $J_X$ factors multiplication
    by $n$ for some $n$, by duality for (isogenies of) 
    abelian varieties.
\end{rem}

Let us briefly describe the proof of Theorem \ref{thm:main-intro}.
Writing $U:=X\setminus S$, Nori's work provides a profinite commutative $k$-group scheme 
$\pi^{\Nori}(U)^{\ab}$ with a functorial identification
\begin{equation}
    \Hom(\pi^{\Nori}(U)^{\ab},G) = H^1_{\fppf}(U,G)
\end{equation}
for variable finite commutative $k$-group schemes $G$.  On the other hand, 
it follows from the concrete description of $\varpi_1(\cdot)$ given by \eqref{eqn:varpi-concrete}
that, for any commutative, connected and reduced $k$-group $H$,
pushout of the tautological extension 
arising from an isogeny $\varphi:H'\rightarrow H$
along a homomorphism of finite $k$-group schemes $\ker(\varphi)\rightarrow G$
induces a functorial identification (see Lemma \ref{lem:univ cov B})
\begin{equation}
    \Hom(\varpi_1(H),G) = \Ext^1(H,G). 
\end{equation}
As such, the identification \eqref{eq:nori-affine} is equivalent to a functorial identification
\begin{equation}
    H^1_{\fppf}(U,G) \simeq \varinjlim_{\frkm} \Ext^1(J_{X,\frkm},G).
    \label{eqn:fppf-ext}
\end{equation}
In the case $S=\emptyset$, so $U=X$ is projective, \eqref{eqn:fppf-ext}
follows from the well known identifications
\begin{equation}\label{eq:Raynaud}
H^1_{\fppf}(X,G)\simeq\Hom(G^D,J_X)\simeq\Ext^1(J_X,G),
\end{equation}
where $G^D$ is the Cartier dual of $G$; see \cite[Proposition 6.2.1]{Raynaud}
for the first isomorphism and \cite[III.19, Theorem (19.1)]{Oort} for the second.

Thus, the main contribution of this paper is to establish \eqref{eqn:fppf-ext}
for general $S\subset X(k)$.  We will prove a more precise result: fixing 
$x_0\in U(k)$ and, for any modulus $\frkm$ supported on $S$, writing $\varphi_{\frkm}:U\rightarrow J_{X,\frkm}$
for the corresponding Albanese map, we establish the following generalization of Geometric Class Field theory:

\begin{thm}(cf.\ Theorem \ref{thm:CFT})\label{thm-intro:CFT}
    For any finite, abelian $k$-group scheme $G$ and any {fppf} $G$-torsor
    $P\rightarrow U$, there exists a modulus $\frkm$ supported on $S$ 
    and a unique isogeny of algebraic groups $J'\rightarrow J_{X,\frkm}$ with kernel $G$ such that $P=\varphi_{\frkm}^* J'$ is the pullback
    of $J'$ along $\varphi_{\frkm}$.
\end{thm}

When $G$ is reduced, Theorem \ref{thm-intro:CFT} recovers the classical Geometric Class Field theory
of Lang, Rosenlicht, and Serre; see \cite{Serre}.  In fact, the identification 
\eqref{eqn:fppf-ext} is stated by Deligne for arbitrary commutative $k$-groups $G$
in a 1974 letter to Serre (reproduced in the Appendix of \cite{BE}).
Deligne sketches a proof, which proceeds by devissage to the case of smooth $G$.
He then interprets each side of \eqref{eqn:fppf-ext} as the $i=1$
degree of a cohomological $\delta$-functor in {\em two} variables, and argues that each $\delta$-functor
is effaceable and therefore universal by (a generalization of) Grothendieck's theorem \cite[II, Proposition 2.2.1]{Grothendieck}.  In this way, Deligne's approach reduces \eqref{eqn:fppf-ext} to 
the identification $\Maps(U,G)\simeq \varinjlim_{\frkm} \Hom(J_{X,\frkm},G)$
for smooth commutative $k$-groups $G$, which follows from Rosenlicht's work
(see \cite[Chapter V, \S2, Theorem 2]{Serre}).  While beautiful, Deligne's sketch 
is missing some details (e.g.~we are unaware of any reference for the
generalization of Grothendieck's theorem to the case of cohomological $\delta$-functors in
two variables that the argument relies on).  Rather than fill in these details, we provide
a different---and in some ways more elementary---approach, establishing Theorem \ref{thm-intro:CFT}
in \S\ref{sec:abelian torsors}.



Among all moduli $\frkm$
guaranteed by Theorem \ref{thm-intro:CFT}, there is a unique {\em minimal} one (see Corollary  \ref{cor:minmod}). 
In the classical case of \'etale (i.e.~constant) $G$,
this minimal modulus coincides with the ramification
divisor of the associated branched covering of curves.  
In the general case, it yields a natural notion
of $G$-torsor over $U$ {\em with ramification no worse than $\frkm$}.
Such a notion has recently been proposed by R\"ulling and Saito 
\cite[\S9]{RS} for smooth schemes over a perfect field as an application of their general theory of ramification for reciprocity sheaves; see also see Remark \ref{rem:RS}. We will give a description of the minimal modulus purely in terms of local fields. To that end, we introduce a conductor $\cond^G_{L}(-)$ (see Definition \ref{def:cond}) for finite local-local torsors over a complete, discretely valued field $L$
over $k$ having residue field $k$.
In \S\ref{sec:torsors with modulus}, we provide the following description of the minimal modulus $\frkm$ for finite local-local torsors:



\begin{thm}(cf.\,Theorem \ref{thm:m vs c})\label{thm-intro:m vs c}
Let $G$ be a finite local-local $k$-group and $P\in H^1_{\fppf}(U,G)$. Let  $\frkm(P)=\sum_{x\in S}n_x(P) x$ be the minimum modulus of $P$. Then for any $x\in S$, we have
\[
n_x(P)=\cond^G_{\Frac\widehat{\scrO}_{X,x}}(P|_{\Frac\widehat{\scrO}_{X,x}}).
\]
\end{thm}




We also study the particular case of $G=\alpha_p$, providing an alternative description
of $\frkm(P)$ in terms of meromorphic differentials on $X$ with poles ``no worse than $\frkm(P)$''; see Proposition \ref{prop:alphap-diff}.

As another application of our work, we deduce from Theorem \ref{thm:main-intro}
a description of the connected component of the identity of $\pi^{\Nori}(U)^{\ab}$ in terms of the Frobenius-power torsion subgroup
schemes of generalized Jacobians, which is a perhaps more satisfyingly direct analogue of \eqref{eq:Nori}
than the description of the full $\pi^{\Nori}(U)^{\ab}$ afforded by \eqref{eq:nori-affine}; see Corollary \ref{cor:conn part}.

In the final \S\ref{sec:singular curve}, as a related topic, we study the abelian unipotent fundamental group scheme of the singular curve $X_{\frkm}$ associated to a modulus $\frkm$ \cite[IV, \S1, No.~4]{Serre},  and deduce a version of Das's description of the \'etale fundamental group of singular curves \cite[Theorem 3.3]{Das}; see Theorem \ref{thm:uni ab}.  


\begin{rem}
\begin{enumerate}
\item In \cite{CH}, Campbell and Hayash reformulate and reprove Geometric Class Field theory with arbitrary ramification by using the theory of {\it commutative group stacks}. Although they do not consider non-reduced finite abelian $k$-group schemes, it seems that our Theorem \ref{thm-intro:CFT} might also be deducible from their work. 

\item In \cite{Brion}, Brion has extended the theory of the Serre--Oort fundamental group to allow for arbitrary base fields (not necessarily algebraically closed).  
Relying on Brion's work, it would be interesting to generalize the present work to general base fields as well. 
\end{enumerate}
\end{rem}



