\end{ack}



\section*{Notation and conventions}


\begin{itemize}[leftmargin=*]

\item Throughout, we work over a fixed algebraically closed field $k=\overline{k}$ of characteristic $p>0$. A {\it $k$-group} always means an abelian group scheme of finite type over $k$. A \textit{proalgebraic} $k$-group is a projective limit $\varprojlim G_i$ of $k$-groups $G_i$. A {\it profinite} $k$-group is a projective limit of finite $k$-groups. 


\item For any proalgebraic $k$-group $G$, we denote by $G^0$ the connected component of the identity of $G$, and write $G^{\et}$ for the quotient $G/G^0$ and call it the {\it \'etale part} of $G$. 
As $k$ is algebraically closed, $G^{\et}$ is canonically isomorphic to the constant $k$-group scheme associated with the profinite group of $k$-valued points $G^{\et}(k)$. 



\item A finite $k$-group is said to be \textit{\'etale} if $G=G^{\et}$. A finite $k$-group $G$ is said to be of \textit{multiplicative type} if it is isomorphic to $\prod_{i=1}^m\mu_{n_i}$ for some integers $n_1,\dots,n_m>0$. 
A finite $k$-group $G$ is \textit{unipotent} if it is obtained by successive extensions of $\Z/p\Z$ or $\alpha_p$. 
For any finite $k$-group $G$,  
there exists a canonical decomposition $G=G^{\uni}\times G^{\MT}$ into the product of a unipotent $k$-group $G^{\uni}$ and a multiplicative type $k$-group $G^{\MT}$ (cf.\ \cite[9.5 Theorem]{Wat}). 
We call $G^{\uni}$ (respectively $G^{\MT}$) the unipotent part (respectively the multiplicative part) of $G$. 
A finite $k$-group $G$ is said to be \textit{local-local} if it is connected and unipotent. For any finite $k$-group $G$, we put $G^{\LL}\Def (G^0)^{\uni}$ and call it the \textit{local-local} part of $G$. For any finite $k$-group $G$, there exists a functorial decomposition $G = G^0\times G^{\et}= G^{0,\rm m}\times G^{\rm ll} \times G^{\et}$, and the terminology introduced in this paragraph can be extended to any profinite $k$-group in an obvious manner. 
\end{itemize}






\section{Finite abelian torsors}\label{sec:abelian torsors}

We maintain the notation of \S\ref{sec:intro},
so $X$ is a smooth, connected and projective 
curve over $k$ and $U= X\setminus S$
is the complement in $X$ of a finite (possibly empty) set of points 
$S\subset X(k)$.  We fix a base point $x_0\in U(k)$,
and for any modulus $\frkm$ supported on $S$,
we write $J_{X,\frkm}$ for the generalized Jacobian
of $X$ with modulus $\frkm$, and 
$\varphi_{\frkm} : U \rightarrow J_{X,\frkm}$
for the Albanese map corresponding to $x_0$
\cite[V, \S2, Theorem 1]{Serre}.
Due to \cite[V, \S2, Theorem 2]{Serre},
this
satisfies the following universal property:
for any smooth and connected $k$-group $H$
and any morphism of pointed $k$-schemes
$f:(U,x_0)\rightarrow (H,0)$ admitting $\frkm$
as a modulus in the sense of 
\cite[III, \S1, Definition 1]{Serre},
there exists a unique homomorphism of
$k$-groups $\theta: J_{X,\frkm}\rightarrow H$
with $f = \theta \circ \varphi_{\frkm}$.





Let $G$ be a finite $k$-group.
For any modulus $\frkm$ with support contained in $S$,
pullback along $\varphi_{\frkm}$ yields
a homomorphism
\begin{equation}\label{eq:phim}
\varphi_{\frkm}^*\colon \Ext^1(J_{X,\frkm},G)\to H^1_{\fppf}(U,G).
\end{equation}
These are compatible with change in $\frkm$,
so they induce a homomorphism of abelian groups
\begin{equation}\label{eq:CFT}
\varinjlim_{\frkm}\Ext^1(J_{X,\frkm},G)\to H^1_{\fppf}(U,G),
\end{equation}
with $\frkm$ ranging over all moduli supported on $S$.

\begin{thm}\label{thm:CFT}
The map (\ref{eq:CFT}) is an isomorphism.
\end{thm}

We first prove:




\begin{lem}\label{lem:CFT inj}
The map
\eqref{eq:phim} is injective.
\end{lem}

\begin{proof}
Suppose that $0\to G\to P\xrightarrow{f} J_{X,\frkm}\to 0$ is an extension of $J_{X,\frkm}$ by $G$ whose pullback 
$\varphi_{\frkm}^*P\to U$ to a $G$-torsor over $U$ is trivial, and let 
$s\colon U\to\varphi_{\frkm}^*P$ be a corresponding section.
Composing $s$ with the canonical projection $\varphi_{\frkm}^*P\rightarrow P$ gives a lift $\varphi:U\rightarrow P$ of $\varphi_{\frkm}$. 
Let $P_{\rm red}$ be the reduction (cf.\ \cite[Definition 01J4]{SP}) of $P$; it is a closed subgroup scheme of $P$ by \cite[Lemma 047R]{SP},
and hence a smooth $k$-group.  
As $U$ is reduced, the map $\varphi\colon U\to P$ factors as $\varphi\colon U\to P_{\rm red}\subset P$. 
\[
\xymatrix{
P_{\rm red}\ar@{^{(}->}[r]&P\ar[d]^f\\
U\ar@{-->}[u]\ar[r]_{\varphi_{\frkm}}\ar[ur]^{\varphi}&J_{X,\frkm}
}
\]
By applying \cite[III, \S2, Proposition 14]{Serre} to the composition map $\varphi_{\frkm}=f\circ\varphi\colon U\to P_{\rm red}\to J_{X,\frkm}$, we find that $\frkm$ is a modulus for $\varphi\colon U\to P_{\red}$, hence there exists a homomorphism $\theta\colon J_{X,\frkm}\to P_{\red}$ such that $\varphi=\theta\circ\varphi_{\frkm}+\varphi(x_0)$. As $f\circ\varphi(x_0)=\varphi_{\frkm}(x_0)=0$, we have  $\varphi_{\frkm}=f\circ\theta\circ\varphi_{\frkm}$, hence by the universal property of $\varphi_{\frkm}$, we can conclude that  $f\circ\theta={\rm id}_{J_{X,\frkm}}$. 
Thus, $\theta$ is a splitting of the given extension $P$, whose
class in $\Ext^1(J_{X,\frkm},G)$ is therefore trivial. 
\end{proof}



\begin{rem}\label{rem:CFT inj}
Let $f\colon H\to G$ be a finite surjective $k$-homomorphism of $k$-groups. If $G$ is reduced and connected, then we have the commutative diagram of short exact sequences
\[
\xymatrix{
1\ar[r]&\Ker(f|_{H^0_{\red}})\ar@{^{(}->}[d]\ar[r]&H^0_{\red}\ar[r]^{f|_{H^0_{\red}}}\ar@{^{(}->}[d]&G\ar[r]\ar@{=}[d]&1\\
1\ar[r]&\Ker(f)\ar[r]&H\ar[r]^f&G\ar[r]&1.
}
\]
Clearly, the map $H^0_{\red}\hookrightarrow H$ is equivariant with respect to the actions of $\Ker(f|_{H^0_{\red}})$ and $\Ker(f)$. Thus, the diagram tells us that $H=\Ind_{\Ker(f|_{H^0_{\red}})}^{\Ker(f)}(H^0_{\red})$ as a $\Ker(f)$-torsor over $G$. 
\end{rem}


\begin{proof}[Proof of Theorem \ref{thm:CFT}]
Thanks to 
Lemma \ref{lem:CFT inj},
it remains to prove that \eqref{eq:CFT} is surjective.
Via the canonical decomposition 
$G=G^{0,\MT} \times G^{\rm ll} \times G^{\et}$,
the surjectivity of \eqref{eq:CFT} is reduced to the three cases
$G=G^{\star}$ for each value of $\star$ in the decomposition above. The case $\star={\et}$ is classical \cite[VI,\S2]{Serre}.



Assume now that $G=G^{0,\rm m}$. If $S=\emptyset$, then the surjectivity of
\eqref{eq:CFT} is again classical; see \S\ref{sec:intro}.
 Supposing that $S\neq\emptyset$, let $\frkm_{\red}\Def\sum_{x\in S}x$. As $\frkm_{\red}$ is reduced, $J_{X,\frkm_{\red}}$ is a semi-abelian variety over $k$. More precisely, there exists an exact sequence of smooth $k$-groups
\begin{equation*}
0\to L_{\frkm_{\red}}\to J_{X,\frkm_{\red}}\to J_X\to 0,
\end{equation*}
where $L_{\frkm_{\red}}$ is a smooth $k$-group, which is non-canonically isomorphic to $\G_{m,k}^{\oplus \#S-1}$; see Remark \ref{rem:L_m}. We will show that the injective homomorphism 
\[
\varphi_{\frkm_{\red}}^*\colon\Ext^1(J_{X,\frkm_{\red}},G^{0,\MT})\to H^1_{\fppf}(U,G^{0,\MT})
\]
is bijective. As the source and target are finite groups, it suffices to prove that
\[
\#\Ext^1(J_{X,\frkm_{\red}},G^{0,\MT})=\#H^1_{\fppf}(U,G^{0,\MT}).
\]
Since $G^{0,\MT}=\prod_{i=1}^m\mu_{p^{n_i}}$ for some $n_1,\dots,n_m$, we are reduced to the case where $G^{0,\MT}=\mu_{p^n}$. 
By \cite[Proposition 3.2]{Otabe}, we have 
$H^1_{\fppf}(U,\mu_{p^n})\simeq(\Z/p^n\Z)^{\oplus f_X+\#S-1}$, where $f_X$ denotes the $p$-rank of $X$. 
Therefore, it suffices to show that $\Ext^1(J_{X,\frkm_{\red}},\mu_{p^n})\simeq(\Z/p^n\Z)^{\oplus f_X+\#S-1}$.   
By \cite[II, \S12, Lemma (12.2)]{Oort}, 
we have $\Ext^2(J_X,\mu_{p^n})=0$, and hence a short exact sequence
\[
0\to \Ext^1(J_X,\mu_{p^n})\to \Ext^1(J_{X,\frkm_{\red}},\mu_{p^n})\to\Ext^1(L_{\frkm_{\red}},\mu_{p^n})\to 0.
\]
As $\Ext^1(J_X,\mu_{p^n})\simeq
J_X[p^n](k)\simeq(\Z/p^n\Z)^{\oplus f_X}$ (cf.\ \cite[Remark 2]{Nori83}\cite[\S6, p.61]{Mumford}), 
it suffices to show that $\Ext^1(L_{\frkm_{\red}},\mu_{p^n})\simeq(\Z/p^n\Z)^{\oplus \#S-1}$. Since $L_{\frkm_{\red}}\simeq\G_{m,k}^{\oplus \#S-1}$, this follows from the exactness of the sequence
\[
0\to \End(\G_{m,k})\xrightarrow{p^n}\End(\G_{m,k})\to\Ext^1(\G_{m,k},\mu_{p^n})\to 0.
\]
This proves the surjectivity of the map (\ref{eq:CFT}) when $G=G^{0,\MT}$. 


It remains to show the surjectivity of (\ref{eq:CFT}) when $G=G^{\rm ll}$. If $S=\emptyset$, this is classical; see \S\ref{sec:intro}. Thus, we may assume that $U$ is affine. Thanks to \cite[V, \S1, Proposition 2.5]{DG},
we may embed $G$ as a subgroup scheme of a smooth and unipotent $k$-group $W$ with quotient $W/G$ that is necessarily smooth as $G$ acts 
freely on $W$ \cite[Lemma 05B5]{SP}.  On the other hand, 
$H^1_{\fppf}(U,W)=0$ as $W$ is a successive extension of
copies of $\G_a$ and $H^1_{\fppf}(U,\G_a)=H^1(U,\calO_U)=0$ 
by \cite[III, \S3, Proposition 3.7]{Milne} and the fact that $U$ is affine.
We thereby obtain
the exact sequence
\begin{equation*}
    \xymatrix{
        0 \ar[r] & {H^0(U,W)} \ar[r] & {H^0(U,W/G)} \ar[r] & {H^1_{\fppf}(U,G)} \ar[r] & 0
    }.
\end{equation*}
It follows that
for any $G=G^{\rm ll}$-torsor $P\to U$, there exists a $k$-morphism $f\colon U\to W/G$ such that $P\simeq f^*W$ as $G$-torsors over $U$. As $W/G$ is a smooth $k$-group, there exists a modulus $\frkm$ supported on $S$ such that $f\colon U\to W/G$ factors through $\varphi_{\frkm}\colon U\to J_{X,\frkm}$. 
This proves that the class of $P$ in $H^1_{\fppf}(U,G)$ lies in the image of $\varphi_{\frkm}^*\colon\Ext^1(J_{X,\frkm},G)\to H^1_{\fppf}(U,G)$, as desired.
\end{proof}

In particular, the proof of Theorem \ref{thm:CFT} together with \cite[VI, \S2, Examples.\,(1)]{Serre} shows:

\begin{cor}\label{cor:CFT MT}
Let $\frkm_{\red}\Def\sum_{x\in S}x$. 
If $G$ is of multiplicative type, we have an isomorphism
\[
\Ext^1(J_{X,\frkm_{\red}},G)\xrightarrow{\simeq} H^1_{\fppf}(U,G).
\]
\end{cor}



For an arbitrary finite $k$-group $G$, Theorem \ref{thm:CFT} yields an evident filtration on $H^1_{\fppf}(U,G)$:

\begin{definition}\label{def:F_m H^1}
For any modulus $\frkm$ supported on $S$, we define
\[
F_{\frkm}H^1_{\fppf}(U,G)\Def\im\left(\varphi_{\frkm}^*\colon\Ext^1(J_{X,\frkm},G)\to H^1_{\fppf}(U,G)\right).
\]
\end{definition}


\begin{rem}
The definition of $F_{\frkm}H^1_{\fppf}(U,G)$ does not depend on the choice of the base point $x_0\in U(k)$. Indeed, let $x_1\in U(k)$ be another $k$-point and $\varphi'_{\frkm}\colon U\to J_{X,\frkm}$ the Albanese map associated with $x_1$. According to \cite[V, \S2, Corollary 1]{Serre}, there exists a translation map $T\colon J_{X,\frkm}\to J_{X,\frkm}$ such that $\varphi'_{\frkm}=T\circ\varphi_{\frkm}$, and it follows
at once that $\varphi_{\frkm}^*$ and $(\varphi_{\frkm}')^*$
have the same image.
\end{rem}


\begin{prop}\label{pr:minmod}
Let $G$ be a finite $k$-group and $\frkm$, $\frkm'$ moduli supported on $S$. Then
\[
F_{\frkm}H^1_{\fppf}(U,G)\cap F_{\frkm'}H^1_{\fppf}(U,G)=F_{{\rm Inf}(\frkm,\frkm')}H^1_{\fppf}(U,G).
\]
\end{prop}

\begin{proof}
Using Lemma \ref{lem:CFT inj}, the proof of \cite[VI, \S2, Lemma 1]{Serre} works for any finite $k$-group $G$. 
\end{proof}

As a consequence, we obtain our version of \cite[VI, \S2, Proposition 11]{Serre}.

\begin{cor}\label{cor:minmod}
Let $P\to U$ be a torsor for a finite $k$-group $G$.
There exists
a least modulus $\frkm$ such that $P$ is the pullback
of an isogeny $J'\rightarrow J_{X,\frkm}$ with kernel $G$
along $\varphi_{\frkm}:U\rightarrow J_{X,\frkm}$.  Moreover,
$\frkm$ has support contained in $S$.
\end{cor}



\begin{rem}\label{rem:L_m}
As in \cite[V,\S3]{Serre}, the structure
of generalized Jacobians can be made somewhat explicit.
Let $\frkm=\sum_{x\in S} n_x x$ be a modulus
supported on $S$.  Then there is
an exact sequence $k$-groups
\begin{equation}\label{eq:genjac-str}
    \xymatrix{
        1 \ar[r] & {\G_{\rm m}} \ar[r]^-{\Delta} & { \displaystyle\prod_{x\in S} \left(\G_{\rm m}\times V_{(n_x)}\right)} \ar[r] & {J_{X,\frkm}} \ar[r] & J_{X} \ar[r] & 0 
    }
\end{equation}
in which $\Delta$ is the diagonal embedding of 
$\G_{\rm m}$ into $\prod_{x\in S} \G_{\rm m}$ and $V_{(n)}$ is the smooth and unipotent
$k$-group determined by 
$$
    V_{(n)}(k)=(1+uk[\![u]\!])^{\times} / (1+u^n k[\![u]\!])^{\times}.
$$
Note that $L_{\frkm}\Def\ker(J_{X,\frkm}\twoheadrightarrow J_X)$
is a linear algebraic group.  
Moreover, as $k$ has characteristic $p$, the unipotent group $V_{(n)}$ is a product of Witt groups.  More precisely, 
let $F(u)\Def\exp(-\sum_{s\ge 0} u^{p^s}/p^s)\in\Q[\![u]\!]$;
as is well-known, $F(u)$
has coefficients in $\Z_{(p)}$ so may be considered as
a formal power series over $\F_p$ by reduction modulo $p$.
For any Witt vector ${\bm a}=(a_0,a_1,a_2,\ldots)\in W(k)$,
set
$$
    E(\bm{a}\cdot u)\Def F(a_0u)F(a_1u^p)F(a_2u^{p^2})\cdots,
$$
which is an element of $1+uk[\![u]\!]$.
For each integer $i$ with $1\le i < n$ and $(i,p)=1$,
let $r_i$ be the least integer $r$ satisfying $p^r \ge n/i$.  Then
the map
\begin{equation}\label{eq:local grp}
\prod_{1\le i< n,~p\nmid i}W_{r_i}\to V_{(n)}
\quad\text{determined on $k$-points by}\quad (\bm{a}_i)_i\mapsto \prod_iE(\bm{a}_i\cdot u^i)
\end{equation}
is an isomorphism of $k$-groups \cite[V, \S3, Proposition 9]{Serre}.
\end{rem}


\begin{rem}\label{rem:I_m}
As in \cite[III,\S1]{Serre}, it is illuminating to 
interpret the exact sequence \eqref{eq:genjac-str}
in terms of  id\`eles.  For each closed point $x\in X(k)$,
let $v_x$ be the normalized valuation of the discrete valuation 
ring $\calO_{X,x}$ and set $U_x=U_x^{(0)}\Def\{g\in k(X)^{\times}\colon v_x(g) = 0\}$.
For $n\ge 1$ put 
$$U_x^{(n)}\Def\{g\in k(X)^{\times}\colon v_x(1-g) \ge n\}.$$
By definition, the group $I$ of id\`eles of $k(X)$
is the subgroup of 
$\prod_{x\in X(k)}k(X)^{\times}$ consisting of families of elements $a=\{a_x\}_{x\in X(k)}$ such that $a_x\in U_x$ for almost all $x$. For any modulus $\frkm=\sum_{x\in S} n_xx$ supported on $S$, we define the subgroup $I_{\frkm}$ of $I$ to be
\[
I_{\frkm}\Def\prod_{x\in S}U_x^{(n_x)}\times\prod_{x\not\in S}U_x.
\]
The exact sequence of $k$-points arising from \eqref{eq:genjac-str}
may be identified with the top row in the commutative diagram
\begin{equation*}
    \xymatrix{
        0 \ar[r] & k^{\times} \ar[r]\ar@{=}[d] & \displaystyle\prod_{x\in S} U_x/U_x^{(n_x)} \ar[r]\ar@{=}[d] & C_{\frkm}^0 \ar[r]\ar@{^{(}->}[d] & C^0 \ar[r]\ar@{^{(}->}[d] & 0 \\
        0 \ar[r] & k^{\times} \ar[r] & I_0/I_{\frkm} \ar[r] & I/I_{\frkm}k(X)^{\times} \ar[r] & I/I_0k(X)^{\times} \ar[r] & 0
    }
\end{equation*}
in which $C_{\frkm}^0$ is the group of the $\frkm$-equivalence classes of degree-zero divisors prime to $S$. Note that $I/I_{\frkm}k(X)^{\times}$
is naturally identified with the group $C_{\frkm}$
of $\frkm$-equivalence classes of divisors prime to $S$,
so that the cokernel of rightmost two vertical maps
above is $\Z$ in each case, via the degree map.

Furthermore, for any map $f\colon U\to G$ into a $k$-group $G$, if we denote by $(f,-)_x$ the corresponding local symbol \cite[III,\S1, Definition 2]{Serre}, we obtain an associated homomorphism
\[
    \theta_f\colon I/k(X)^{\times}\to G(k)\quad\text{determined by}\quad
    \theta_f(a)=\sum_{x\in X(k)}(f,a_x)_x.
\]
Then $\frkm$ is a modulus for the map $f\colon U\to G$ if and only if $\theta_f(I_{\frkm})=0$. 
Via the identification $J_{X,\frkm}(k)=C_{\frkm}^0$,
on $k$-points the homomorphism $\theta\colon J_{X,\frkm}\to G$ associated with the map $f\colon U\to G$ is 
simply the restriction of the induced homomorphism $\theta_f\colon I/I_{\frkm}k(X)^{\times}\to G(k)$ to the subgroup $C_{\frkm}^0$.
\end{rem}




\begin{rem}\label{rem:adele}
Let $R$ be the ring of ad\`eles for the curve $X$, i.e.\,$R$ is the subring of $\prod_{x\in X(k)}k(X)$ consisting of families $r=(r_x)_{x\in X(k)}$ of elements of $k(X)$ such that $r_x\in\scrO_{X,x}$ for almost all $x\in X(k)$, and let $R(0)$ be the $k$-subspace of $R$ consisting of
those families $r$ with $r_x \in \scrO_{X,x}$ for all $x$;
see \cite[II,p.11]{Serre}. If $G$ is a smooth unipotent $k$-group, we have a natural identification 
$H^1_{\fppf}(X,G)=G(R)/G(R(0)+k(X))$;
see \cite[II,p.12]{Serre}. Under this identification, for any $x\in S$, we have a commutative diagram
\[
\xymatrix{
G(\Frac\scrO_{X,x})\ar[d]_{(-,-)_x}\ar[rr]&&H^1_{\fppf}(X,G)\\
\varinjlim_n\Hom(V_{(n)},G)\ar[r]^-{\simeq}&\varinjlim_n\Hom(L_{n\cdot x},G)\ar[r]^-{\delta} &\Ext^1(J_X,G),\ar[u]_{\varphi_0^*}
}
\]
where the map $\delta$ sends each homomorphism $\alpha\colon L_{n\cdot x}\to G$ to the push-forward $\alpha_*J_{X,n\cdot x}$ of the extension $0\to L_{n\cdot x}\to J_{X,n\cdot x}\to J_X\to 0$.
The commutativity of the diagram can be checked as follows. First, note that for any $\alpha\colon L_{n\cdot x}\to G$, we have $\varphi_0^*(\alpha_*J_{X,n\cdot x})=\alpha_*(\varphi^*J_{X,n\cdot x})$. This reduces the problem to the case where $G=V_{(n)}$. According to \cite[VII,\S4, no.\,20]{Serre}, there exists an element  $\psi_x\in V_{(n)}(\Frac\scrO_{X,x})$ such that the ad\`ele $r=(r_y)_{y\in X(k)}$ with $r_x=-\psi_x$ and $r_y=0$ for $y\neq x$ represents the class of  $\varphi_0^*(J_{X,n\cdot x})$ in $H^1_{\fppf}(X,V_{(n)})$ and $(-\psi_x,-)_x={\rm id}_{V_{(n)}}\in\End(V_{(n)})$. This proves the commutativity of the diagram for $G=V_{(n)}$. 
\end{rem}





\section{Finite local-local torsors over affine curves}\label{sec:torsors with modulus}

As an illustration of the previous considerations,
we now work out explicitly the classification of finite local-local torsors in terms Corollary \ref{cor:minmod}, and its relation
to other well-known classifications. 
We begin with recalling the definition of the \textit{Rosenlicht--Serre filtrations} on smooth $k$-groups.

Throughout this section, we 
fix a discretely valued field $L$ over $k$
with valuation ring $\scrO_L$, residue field $k$, 
and normalized valuation $v_L$.



\begin{definition}\label{def:RoSe}
We set $U_L\Def U_L^{(0)}\Def\scrO_L^{\times}$ 
and for $n\ge 1$ define $U_L^{(n)}\Def\{g\in\scrO_L^{\times}\,|\,v_L(1-g)\ge n\}$. 
Let $H$ be a smooth $k$-group and $(-,-)^H_L\colon H(L)\times L^{\times}\to H(k)$ the local symbol for $H$ (see \cite{Serre}). 
We define an increasing filtration $\{\fil_nH(L)\}_{n\ge 0}$ on $H(L)$ by 
\[
\fil_nH(L)\Def\{f\in H(L)\,|\,(f,U_L^{(n)})^H_L=0\}
\] 
for any $n\ge 0$. Note that $\fil_0 H(L)=H(\scrO_L)$. 
\end{definition}


\begin{rem}\label{rem:RoSe=KR}
For a finite-length Witt group $H=W_m$, 
the increasing filtration $\{\fil_nW_m(L)\}_{n\ge 0}$ in Definition \ref{def:RoSe} coincides with Kato--Russell's filtration $\{\fil_n^FW_m(L)\}_{n\ge 0}$ in the sense of \cite[\S2]{KR}; see \cite[Proposition 6.4(3)]{KR}\cite{RS}. 
\end{rem}




\begin{prop}\label{prop:RoSe}
Let $L$ be as above. 
\begin{enumerate}
\item \label{prop:RoSe-1} For any homomorphism $\phi\colon H_1\to H_2$ of smooth $k$-groups, we have $\phi(\fil_nH_1(L))\subset\fil_nH_2(L)$ for any integer $n\ge 0$. 

\item \label{prop:RoSe-2} For any homomorphism $\phi\colon H_1\to H_2$ of smooth $k$-groups whose kernel is finite and connected, we have $\phi(\fil_nH_1(L))=\phi(H_1(L))\cap\fil_nH_2(L)$ for any $n\ge 0$. 
\end{enumerate}
\end{prop}

\begin{proof}
By \cite[III, \S1, Proposition 2]{Serre}, we have $(\phi(f),-)_L^{H_2}=\phi((f,-)_L^{H_1})$ for $f\in H_1(L)$,
which gives \eqref{prop:RoSe-1}.  It follows that we have an inclusion
$\phi(\fil_nH_1(L))\subseteq \phi(H_1(L))\cap\fil_nH_2(L)$. The reverse inclusion is a straightforward consequence of the injectivity of the map 
$\phi\colon H_1(k)\to H_2(k)$
induced by $\phi$ on $k$-valued points.
\end{proof}







\begin{lem}\label{lem:local symbol}
Assume that $L$ is complete, and for
$n>0$, let $V^L_{(n)}$ be the smooth unipotent $k$-group determined on $k$-points by $V^L_{(n)}(k)=U_L^{(1)}/U^{(n)}_L$. Then for $j=1,2$ we have
\[
\varinjlim_n\Ext^j(V^L_{(n)},\G_a)=0.
\]
\end{lem}

\begin{proof}
Fixing an integer $n>0$, we claim that the map $V^L_{(np)}\to V^L_{(n)}$ induces the zero map $\Ext^1(V_{(n)},\G_a)\xrightarrow{0}\Ext^1(V^L_{(np)},\G_a)$. For any $1\le i<n$ with $p\nmid i$, let $r_i$ denote the least integer $r$ satisfying $p^{r}\ge n/i$. For any $1\le i<pn$ with $p\nmid i$, let $l_i$ denote the least integer $l$ satisfying $p^{l}\ge np/i$. Note that for $1\le i<n$ with $p\nmid i$, we have $l_{i}=r_i+1$. Via the isomorphism (\ref{eq:local grp}), we identify $V^L_{(n)}$ (respectively $V^L_{(np)}$) with $\prod_{1\le i<n,p\nmid i}W_{r_i}$ (respectively $\prod_{1\le i<np,p\nmid i}W_{l_i}$). With these identifications, 
map $V^L_{(np)}\to V^L_{(n)}$ decomposes as
\[
V^L_{(np)}=\prod_{1\le i<np,p\nmid i}W_{l_i}\xrightarrow{{\rm pr}}\prod_{1\le i<n,p\nmid i}W_{l_{i}}=\prod_{1\le i<n,p\nmid i}W_{r_{i}+1}\xrightarrow{(R)_i}\prod_{1\le i<n,p\nmid i}W_{r_{i}}=V^L_{(n)},
\]
where $R\colon W_{r+1}\to W_r$ is the restriction map.
It therefore suffices to prove that
for any $r>0$, the map $R^*:\Ext^1(W_r,\G_a)\rightarrow\Ext^1(W_{r+1},\G_a)$
induced by restriction is zero; this is \cite[II,\S9, Lemma (9.1)(f)]{Oort}. This proves the desired vanishing for $j=1$, while for $j=2$ the claimed vanishing is immediate from \cite[II, \S2, Proposition (10.7)]{Oort}.
\end{proof}


\begin{prop}\label{prop:local symbol}
Assume that $L$ is complete, and 
let $H$ be a smooth unipotent $k$-group. 
The local symbol $(-,-)_L^H\colon H(L)\times L^{\times}\to H(k)$ induces an isomorphism
\[
H(L)/H(\scrO_L)\xrightarrow{\simeq}\varinjlim_n\Hom(V^L_{(n)},H)
\]
which maps each $\fil_nH(L)/\fil_0H(L)$ onto $\Hom(V_{(n)}^L,H)$. 
\end{prop}

\begin{proof}
By d\'evissage for smooth unipotent $k$-groups together with the vanishing of Lemma \ref{lem:local symbol} for $j=1$, we can reduce the problem to the case of $H=\G_a$. Without loss of generality, we may assume that $L=k(\!(u)\!)$. Let $U\Def\A^1_k=\Spec k[t]$ with $t=1/u$ and $X=\bbP^1_k$ the smooth compactification of $U$. The claim follows from the commutativity of the  diagram (cf.\,Remark \ref{rem:I_m})
\[ \xymatrix{ \Hom((\A_k^1,0),(\G_a,0)\ar[r]^{\simeq~}\ar[d]^{\simeq}&\varinjlim_{n}\Hom(J_{X,n\cdot\infty},\G_a)\ar@{=}[d]\\
\G_a(L)/\G_a(\scrO_L)\ar[r]&\varinjlim_n\Hom(V_{(n)}^L,\G_a),
} 
\] 
where the upper horizontal isomorphism is due to \cite[V,\S2, Theorem 2]{Serre}. 
\end{proof}

\begin{lem}\label{lem:inj F_* Ext}
For integers $l,m,r\ge 1$, the $r$-th iterated Frobenius homomorphism $F^r\colon W_m\to W_m$ induces an injective homomorphism
\[
(F^r)_*\colon \Ext^1(W_l,W_m)\to\Ext^1(W_l,W_m)
\]
Consequently, the connecting homomorphism $\Hom(W_{l},W_m)\to\Ext^1(W_l,W_m[F^r])$
is surjective, where $W_m[F^r]\Def\Ker(F^r\colon W_m\to W_m)$.
\end{lem}

\begin{proof}
As $(F^r)_*=(F_*)^r$, we are reduced to the case of $r=1$. Let $W\Def\varprojlim_nW_n$ be the additive group of Witt vectors. 
By \cite[II, \S9, Corollary (9.2)]{Oort}, we have
$\Ext^1(W,W_m)=0$, so the exact sequence
\[
0\to W\xrightarrow{p^l}W\to W_l\to 0
\]
yields the long exact sequence
\[
0\to\Hom(W_l,H_j)\to\Hom(W,W_m)\xrightarrow{p^l}\Hom(W,W_m)\to\Ext^1(W_l,W_m)\to 0. 
\]
Therefore, we have 
\[
\Ext^1(W_l,W_m)\simeq\End(W_m)/p^l\End(W_m)\simeq
\End(W_{\min\{m,l\}})
\]
(cf.\,\cite[II, \S15, (15.3)]{Oort}). Hence, the injectivity of $F_*\colon\Ext^1(W_l,W_m)\to\Ext^1(W_l,W_m)$ follows from the vanishing 
\[
\Hom(W_l,W_m[F])=0.
\]
\end{proof}



\begin{rem}\label{rem:inj F_* Ext}
Let $G=G^{\LL}$ be a finite local-local $k$-group.  Let $0\to G\to H_1\to H_2\to 0$ be a resolution of $G$ by smooth unipotent $k$-groups $H_j$,  
and let $p^n$ be the period of $H_1$, i.e.\ $p^n$ is the smallest power $p^m$ of $p$ satisfying $p^mH_1=0$ (cf.\ \cite[VII, \S2.10]{Serre}). Note that $H_2$ has period $p^n$. 
For $l\ge n$, we claim that the induced map
\[
\Ext^1(W_l,H_1)\to\Ext^1(W_l,H_2)
\]
is injective. Indeed, as $p^l=0$ on $\Hom(W,H_j)$, the natural map
$\Hom(W,H_j)\xrightarrow{\simeq}\Ext^1(W_l,H_j)$ is an isomorphism,
and the claimed injectivity follows from the vanishing $\Hom(W,G)=0$. 
\end{rem}



\begin{definition}\label{def:adm resol}
Let $G=G^{\LL}$ be a finite local-local $k$-group. A resolution $0\to G\to H_1\to H_2\to 0$ of $G$ by smooth unipotent $k$-groups $H_j$ is said to be \textit{admissible} if for any Witt vector group $W_l$ of finite length, the connecting homomorphism $\Hom(W_l,H_2)\to\Ext^1(W_l,G)$ is surjective.  \end{definition}

\begin{rem}\label{rem:adm resol}
\begin{enumerate}
\item By Lemma \ref{lem:inj F_* Ext}, for any $m,r>0$, the exact sequence
$$0\to W_m[F^r]\to W_m\xrightarrow{F^r}W_m\to 0$$
is an admissible resolution of $W_m[F^r]$. 

\item Any finite local-local $k$-group $G=G^{\LL}$ admits an admissible resolution. Indeed, let  $G\hookrightarrow W_m^N$ be an embedding for sufficiently large $m,N>0$. If $G\subset W_m[F^r]^N$ for $r>0$, we have the following commutative diagram with exact rows:
\[
\xymatrix{
0\ar[r]&G\ar[r]\ar@{^{(}->}[d]&W_m^N\ar[r]\ar@{=}[d]&W_m^N/G\ar[r]\ar@{->>}[d]&0\\
0\ar[r]&W_m[F^r]^N\ar[r]&W_m^N\ar[r]^{F^r}&W_m^N\ar[r]&0
}
\]
For any $l>0$, this yields the commutative diagram
\[
\xymatrix{ 
\Ext^1(W_l,W_m^N)\ar@{=}[d]\ar[r]&\Ext^1(W_l,W_m^N/G)\ar[d]&\\ 
\Ext^1(W_l,W_m^N)\ar@{^{(}->}[r]^{F^r_*}&\Ext^1(W_l,W_m^N)
} 
\]
and it follows that the resolution $0\to G\to W_m^N\to W_m^N/G\to 0$ of $G$ is admissible. 

\item Given a commutative diagram of resolutions of $G=G^{\LL}$ by smooth unipotent $k$-groups
\[
\xymatrix{
0\ar[r]&G\ar[r]\ar@{=}[d]&H_1\ar[r]\ar[d]&H_2\ar[r]\ar[d]&0\\
0\ar[r]&G\ar[r]&H'_1\ar[r]&H'_2\ar[r]&0
}
\]
if the upper resolution is admissible, then so is the lower one. This is immediate from the commutativity of the associated square
\[
\xymatrix{ \Hom(W_l,H_2)\ar@{->>}[r]\ar[d]&\Ext^1(W_l,G)\ar@{=}[d]\\ \Hom(W_l,H'_2)\ar[r]&\Ext^1(W_l,G)
} 
\]
\end{enumerate}
\end{rem}





\begin{prop}\label{prop:conductor vs adm resol}
Assume $L$ is complete and let
$$ ({\rm R})\quad 0\to G\to H_1\to H_2\to 0$$
be an admissible resolution of $G=G^{\LL}$. Let $\fil_n^{({\rm R})}H^1_{\fppf}(L,G)$ be the image of $\fil_nH_2(L)$ under the associated connecting homomorphism $H_2(L)\twoheadrightarrow H^1_{\fppf}(L,G)$ for any $n\ge 0$. Then there exists a natural isomorphism
\[
\dfrac{\fil_n^{({\rm R})}H^1_{\fppf}(L,G)}{\fil_0^{({\rm R})}H^1_{\fppf}(\scrO_L,G)}\xrightarrow{\simeq}\Ext^1(V^L_{(n)},G)
\]
for any $n\ge 0$, and 
the increasing filtration $\{\fil_n^{({\rm R})}H^1_{\fppf}(L,G)\}_{n\ge 0}$ is independent of the choice $({\rm R})$. 
\end{prop}

\begin{proof}
Fix $n\ge 0$, and 
let $x\in\Spec\scrO_L$ be the closed point. The long exact sequences
\[
\cdots\to H^i_x(L,G)\to H^i_x(L,H_1)\to H^i_x(L,H_2)\to H^{i+1}_x(L,G)\to\cdots
\]
and 
\[
\cdots\to H^i_x(\scrO_L,H_j)\to H^i_{\fppf}(\scrO_L,H_j)\to H^i_{\fppf}(L,H_j)\to H^{i+1}_x(\scrO_L,H_j)\to\cdots
\]
give rise to the exact sequence
\[
0\to\dfrac{H_1(L)}{H_1(\scrO_L)}\to\dfrac{H_2(L)}{H_2(\scrO_L)}\to H^2_x(\scrO_L,G)\to 0.
\]
Making the identification $H^2_x(\scrO_L,G)\simeq H^1_{\fppf}(L,G)/H^1_{\fppf}(\scrO_L,G)$, we obtain the exact sequence
\[
0\to\dfrac{\fil_nH_1(L)}{\fil_0H_1(L)}\to\dfrac{\fil_nH_2(L)}{\fil_0H_2(L)}\to \dfrac{\fil_n^{({\rm R})}H^1_{\fppf}(L,G)}{\fil_0^{({\rm R})}H^1_{\fppf}(L,G)}\to 0
\]
for any $n\ge 0$. 
By Propositions \ref{prop:RoSe} and \ref{prop:local symbol}, the local symbols $\fil_nH_j(L)\to\Hom(V_{(n)}^L,H_j)$ for $j=1,2$ make the following diagram with exact rows commute:
\[
\xymatrix{
0\ar[r]&\dfrac{\fil_nH_1(L)}{\fil_0H_1(L)}\ar[r]\ar[d]^{\simeq}&\dfrac{\fil_nH_2(L)}{\fil_0H_2(L)}\ar[r]\ar[d]^{\simeq}& \dfrac{\fil_n^{({\rm R})}H^1_{\fppf}(L,G)}{\fil_0^{({\rm R})}H^1_{\fppf}(L,G)}\ar[r]& 0\\
0\ar[r]&\Hom(V_{(n)}^L,H_1)\ar[r]&\Hom(V_{(n)}^L,H_2)\ar[r]&\Ext^1(V_{(n)}^L,G)\ar[r]&0
}
\]
and this yields an isomorphism
\[
\dfrac{\fil_n^{({\rm R})}H^1_{\fppf}(L,G)}{\fil_0^{({\rm R})}H^1_{\fppf}(L,G)}\xrightarrow{\simeq} \Ext^1(V_{(n)}^L,G).
\]
For the independence of the choice of the resolution $({\rm R})$, let 
\[
({\rm R}')\quad 0\to G\to H'_1\to H'_2\to 0
\]
be another resolution of $G$. Considering the diagonal embedding $G\hookrightarrow H_1\times H'_1$, we are reduced to the case where there exists a commutative diagram of resolutions
\[
\xymatrix{
0\ar[r]&G\ar[r]\ar@{=}[d]&H_1\ar[r]\ar[d]&H_2\ar[r]\ar[d]&0\\
0\ar[r]&G\ar[r]&H'_1\ar[r]&H'_2\ar[r]&0
}
\]
The independence of the choice $({\rm R})$ is then immediate from a diagram chase. 
\end{proof}





\begin{definition}\label{def:cond}
Assume $L$ is complete and let 
$G=G^{\LL}$ be a finite local-local $k$-group. 
We define an increasing filtration $\{\fil_nH^1_{\fppf}(L,G)\}_{n\ge 0}$ by
\[
\fil_nH^1_{\fppf}(L,G)\Def\im(\fil_nH_2(L)\subset H_2(L)\twoheadrightarrow H^1_{\fppf}(L,G))
\]
for any admissible resolution $0\to G\to H_1\to H_2\to 0$ of $G$; by Proposition \ref{prop:conductor vs adm resol}, this is independent of the choice of admissible resolution.
For any $n\ge 0$, we denote by $\psi^L_n$ the isomorphism
\[
\dfrac{\fil_nH^1_{\fppf}(L,G)}{\fil_0H^1_{\fppf}(L,G)}\xrightarrow{\simeq}\Ext^1(V_{(n)}^L,G)
\]
of Proposition \ref{prop:conductor vs adm resol} and put $\varphi^L_n\Def(\psi^L_n)^{-1}$. 
We denote by $\psi^L$ the limit of $\psi^L_n$, i.e. 
\[  
\psi^L\colon\dfrac{H^1_{\fppf}(L,G)}{H_{\fppf}^1(\scrO_L,G)}=\varinjlim_n\dfrac{\fil_nH^1_{\fppf}(L,G)}{\fil_0H^1_{\fppf}(L,G)}\xrightarrow{\simeq}\varinjlim_n\Ext^1(V_{(n)}^L,G).
\]
Furthermore, we define a map $\cond_L^{G}\colon H^1_{\fppf}(L,G)\to\Z_{\ge 0}$ by
\[
\cond_L^{G}(P)\Def\min\{n\ge 0\,|\,P\in\fil_nH^1_{\fppf}(L,G)\}.
\]
\end{definition}


\begin{rem}\label{rem:RS}
In \cite[\S9]{RS}, R\"ulling and Saito use the theory of
{\em reciprocity sheaves} to provide a new conductor for torsors
for arbitrary finite $k$-groups $G$. 
Assume that $L$ is henselian, and let
$$
    c_{L}^{H^1(G)}: H^1_{\fppf}(L,G) \rightarrow \Z_{\ge 0}
$$
be the {\em motivic conductor} of \cite{RS} associated to the presheaf with transfers $H^1(G)\Def H^1_{\fppf}(-,G)$. 
When $G=\alpha_p$ and $L=k(\!(u)\!)$, we claim that
$$\cond_L^{\alpha_p}=c_L^{H^1(\alpha_p)}.$$  
Indeed, using the admissible resolution $0\to\alpha_p\to\G_a\xrightarrow{F}\G_a\to 0$ 
of $\alpha_p$, Proposition \ref{prop:conductor vs adm resol} implies
\[
\cond_L^{\alpha_p}(P)=\min\{n\ge 0\,|\,P\in\im(\fil_n\G_a(L)\to H^1_{\fppf}(L,\alpha_p))\}
\]
for any $P\in H^1_{\fppf}(L,\alpha_p)$. 
It follows from this and the explicit description of the motivic conductor 
for $G=\alpha_p$ given in \cite[Proposition 9.10]{RS} that
$\cond_L^{\alpha_p}=c_L^{H^1(\alpha_p)}$.
\end{rem}





\begin{thm}\label{thm:m vs c}
Let $G=G^{\LL}$ be a finite local-local $k$-group and $P\in H^1_{\fppf}(U,G)$ have minimum modulus $\frkm(P)=\sum_{x\in S}n_x(P) x$. For any $x\in S$, we have
\[
n_x(P)=\cond^G_{\Frac\widehat{\scrO}_{X,x}}(P|_{\Frac\widehat{\scrO}_{X,x}})
\]
\end{thm}



\begin{lem}\label{lem:m vs c}
For any finite local-local $k$-group $G$, the map $\varphi_0^*\colon\Ext^j(J_X,G)\to H^j_{\fppf}(X,G)$ is bijective for $j=1,2$. 
\end{lem}

\begin{proof}
For $j=1$, this is well-known. We will show the claim for $j=2$.  
As $J_X$ is an abelian variety, we have $\Ext^3(J_X,H)=0$ for any $k$-group $H$ by \cite[II,\S12, Proposition (12.5)]{Oort}, so 
a d\'evissage reduces us to the case $G=\alpha_p$. 
Thanks to the vanishing  $H^2_{\fppf}(X,\G_a)=H^2_{\rm Zar}(X,\scrO_X)=0$ and $\Ext^2(J_X,\G_a)=0$ \cite[II,\S12, Lemma (12.8)]{Oort}, we have a commutative diagram with exact rows 
\begin{equation*}
    \xymatrix{
    0\ar[r]&\Ext^1(J_X,\alpha_p)\ar[r]\ar[d]&\Ext^1(J_X,\G_a)\ar[r]\ar[d]&\Ext^1(J_X,\G_a)\ar[r]\ar[d]&\Ext^2(J_X,\alpha_p)\ar[r]\ar[d]& 0\\
        0\ar[r]& H^1_{\fppf}(X,\alpha_p)\ar[r]& H^1_{\fppf}(X,\G_a)\ar[r]& H^1_{\fppf}(X,\G_a)\ar[r]& H^2_{\fppf}(X,\alpha_p)\ar[r]& 0
    }
\end{equation*}
whose vertical maps are induced by pullback along an Albanese map $\varphi_0\colon X\rightarrow J_X$.
The first vertical map is an isomorphism by the $j=1$ instance of Lemma \ref{lem:m vs c},
while the second and third vertical maps are the composites of the isomorphisms 
$\Ext^1(J_X,\G_a)\simeq H^1(J_X,\scrO_{J_X})\simeq H^1(X,\scrO_X)$ (see \cite[VII, \S3--\S4, Theorems 7, 8 and 9]{Serre}) with the identification $H^i(X,\scrO_X)=H^i_{\fppf}(X,\G_a)$ for $i=1$. 
The final vertical map must therefore be an isomorphism as well.
\end{proof}






\begin{lem}\label{lem:m vs c 2}
For any smooth unipotent $k$-group $H$, we have 
$\varinjlim_{\frkm}\Ext^1(J_{X,\frkm},H)=0$.
\end{lem}

\begin{proof}
Let $\frkm$ be a modulus supported on $S$ and $0\to H\to J\to J_{X,\frkm}\to 0$ an extension of smooth $k$-groups. As $H^1_{\fppf}(U,H)=0$, the Albanese map $\varphi_{\frkm}\colon U\to J_{X,\frkm}$ lifts to a map $f:U\rightarrow J$. By Theorems 1 and 2 of \cite[I,\S1]{Serre}, 
$f$ admits a modulus $\frkm' \ge \frkm$ supported on $S$,
and there is a unique homomorphism $\theta: J_{X,\frkm'}\rightarrow J$
factoring $f$.
Then $\theta$ is a section of the pullback of
$J$ along $J_{X,\frkm'}\twoheadrightarrow J_{X,\frkm}$,
so the class of $J$ in $\Ext^1(J_{X,\frkm'},H)$ is trivial. This proves the lemma. 
\end{proof}

\begin{proof}[Proof of Theorem \ref{thm:m vs c}]
Let $H^r_S(X,G)$ (respectively $H^r_c(U,G)$) be the fppf cohomology with support (respectively the fppf cohomology with compact support) in the sense of \cite[III, \S0]{Milne_ADT}\cite{DH}. We have a commutative diagram with exact rows
\[
\xymatrix{
0\ar[r]&H^1_c(U,G)\ar[r]
\ar@{^{(}->}[d]&H^1_{\fppf}(U,G)\ar[r]\ar@{=}[d]&\prod_{x\in S}H^1_{\fppf}(\Frac\widehat{\calO}_{X,x},G)\ar[r]\ar@{->>}[d]&H^2_c(U,G)
\ar[d]^-{\simeq}\\
0\ar[r]&H^1_{\fppf}(X,G)\ar[r]\ar@{=}[d]&H^1_{\fppf}(U,G)\ar[r]\ar@{=}[d]&H^2_S(X,G)\ar[r]\ar[d]_-{\simeq}&H^2_{\fppf}(X,G)\ar@{=}[d]\\
0\ar[r]&H^1_{\fppf}(X,G)\ar[r]&H^1_{\fppf}(U,G)\ar[r]&\prod_{x\in S}\dfrac{H^1_{\fppf}(\Frac\widehat{\scrO}_{X,x},G)}{H^1_{\fppf}(\widehat{\scrO}_{X,x},G)}
&H^2_{\fppf}(X,G).
}
\]
Let $0\to G\to H_1\to H_2\to 0$ be a resolution of $G$ by smooth unipotent $k$-groups $H_j$. Thanks to Lemma \ref{lem:m vs c 2}, the connecting homomorphism 
\[
\varinjlim_{\frkm}\Hom(J_{X,\frkm},H_2)\to\varinjlim_{\frkm}\Ext^1(J_{X,\frkm},G)
\]
is surjective. This together with the commutativity of the diagram (see Remarks \ref{rem:I_m} and \ref{rem:adele})
\[
\xymatrix{
H_2(U)\ar[r]&H_2(\Frac\widehat{\scrO}_{X,x})/H_2(\widehat{\scrO}_{X,x})\ar[d]_{\simeq}^{(-,-)^{H_2}_{\Frac\widehat{\scrO}_{X,x}}}\ar[r]&H^1_{\fppf}(X,H_2)\\
\varinjlim_{\frkm}\Hom(J_{X,\frkm},H_2)\ar[u]^{\varinjlim\varphi_{\frkm}^*}\ar@{^{(}->}[r]&\varinjlim_{n}\Hom(V_{(n)}^{\Frac\widehat{\scrO}_{X,x}},H_2)\ar[r]&\Ext^1(J_X,H_2)\ar[u]_{\varphi_0^*}
}
\]
makes the following diagram with exact rows commute:
\[
\xymatrix{
0\ar[r]&H^1_{\fppf}(X,G)\ar[r]\ar@{=}[d]&H^1_{\fppf}(U,G)\ar[r]\ar@{=}[d]&H^2_S(X,G)\ar[r]\ar[d]_-{\simeq}&H^2_{\fppf}(X,G)\ar@{=}[d]\\
0\ar[r]&H^1_{\fppf}(X,G)\ar[r]&H^1_{\fppf}(U,G)\ar[r]&\prod_{x\in S}\dfrac{H^1_{\fppf}(\Frac\widehat{\scrO}_{X,x},G)}{H^1_{\fppf}(\widehat{\scrO}_{X,x},G)}\ar[d]_{\simeq}^{(\psi^{\Frac\widehat{\scrO}_{X,x}})_{x\in S}}
&H^2_{\fppf}(X,G)\\
0\ar[r]&\Ext^1(J_X,G)\ar[u]_{\varphi_0^*}^{\simeq}\ar[r]&\varinjlim\Ext^1(J_{X,\frkm},G)\ar[u]_{\varinjlim\varphi_{\frkm}^*}^{\simeq}\ar[r]&\prod_{x\in S}\varinjlim\Ext^1(V_{(n)}^{\Frac\widehat{\scrO}_{X,x}},G)\ar[r]&\Ext^2(J_X,G)\ar[u]_{\varphi_0^*}^{\simeq}
}
\]
As a consequence, for any modulus $\frkm=\sum_{x\in S}n_x x$ supported on $S$, we have a commutative diagram with exact rows
\[
\xymatrix{
0\ar[r]&H^1_{\fppf}(X,G)\ar[r]&H^1_{\fppf}(U,G)\ar@{}[dr]|{\square}\ar[r]&\prod_{x\in S}\dfrac{H^1_{\fppf}(\Frac\widehat{\scrO}_{X,x},G)}{H^1_{\fppf}(\widehat{\scrO}_{x},G)}
\ar[r]&H^2_{\fppf}(X,G)\\
0\ar[r]&\Ext^1(J_X,G)\ar[r]\ar[u]^{\simeq}_{\varphi_0^*}&\Ext^1(J_{X,\frkm},G)\ar[r]\ar@{^{(}->}[u]_{\varphi_{\frkm}^*}&\prod_{x\in S}\Ext^1(V_{(n_x)}^{\Frac\widehat{\scrO}_{X,x}},G)\ar@{^{(}->}[u]_{(\varphi^{\Frac\widehat{\scrO}_{X,x}}_{n_x})_{x\in S}}\ar[r]&\Ext^2(J_X,G)\ar[u]^{\simeq}_{\varphi_0^*}
}
\]
in which the first and last vertical maps are isomorphisms due to 
Lemma \ref{lem:m vs c}.  It follows that the middle square is Cartesian. In particular, 
if the class of $P$ is in the image of $\Ext^1(J_{X,\frkm(P)},G)$, we have $n_x(P)= \cond^G_{\Frac\widehat{\scrO}_{X,x}}(P|_{\Frac\widehat{\scrO}_{X,x}})$ for each $x\in S$. This completes the proof. 
\end{proof}


We conclude the present section by giving an explicit description of the minimal modulus $\frkm(P)$ for $P\in H^1_{\fppf}(U,\alpha_p)$ in terms of differential forms. 

Let $Z$ be any smooth $k$-variety and write $\Omega^1_{Z/k,\cl}:=\ker(d:\Omega^1_{Z/k}\rightarrow \Omega^2_{Z/k})$ for the sheaf of 
closed differential 1-forms on $Z$ over $k$.
The {\em Cartier Operator} is an additive and $p^{-1}$-linear
map of sheaves $V: \Omega^1_{Z/k,\cl}\rightarrow \Omega^1_{Z/k}$ defined as in \cite{Seshadri}.

\begin{lem}\label{lem:fppf-diff}
    For any smooth $k$-variety $Z$, there is a functorial identification of $k$-vector spaces
    $$
        H^1_{\fppf}(Z,\alpha_p) \simeq H^0(Z,\Omega^1_{Z/k,\cl})[V]
    $$
\end{lem}

\begin{proof}
    See \cite[III, Proposition 4.14]{Milne}.
\end{proof}

Now let $H$ be a smooth $k$-group, and denote by $m: H\times_k H\rightarrow H$ the multiplication map, and
by $\pr_i : H\times_k H \rightarrow H$ projection onto the $i$-th factor.  
If $G$ is any fppf sheaf of abelian groups, the set of {\em primitive elements} in $H^1_{\fppf}(H,G)$
is by definition the kernel of the map
\begin{equation*}
    m^* - \pr_1^*-\pr_2^* : H^1_{\fppf}(H,G)\rightarrow H^1_{\fppf}(H\times_k H, G).
\end{equation*}



\begin{prop}\label{prop:ext-primitive}
    Let $H$ be a smooth $k$-group and $G$ a finite local $k$-group.
    The canonical map
    \begin{equation}
        \xymatrix{
            \Ext^1(H,G) \ar[r] & H^1_{\fppf}(H,G)
            }\label{eq:ext-fppf}
    \end{equation}
    is injective, with image equal to the set of primitive elements.
\end{prop}

\begin{proof}
    We first note that \eqref{eq:ext-fppf} is injective: if $E$ is an extension of $G$ by $H$
    that admits a section, then $E\simeq H\times G$ as $k$-schemes.  As $G$ is finite local
    and $H$ is smooth, the induced homomorphism $E_{\red}\rightarrow E\rightarrow H$ must be an 
    isomorphism, and it follows that
    $E \simeq H\times G$ as $k$-groups.
    Thanks to \cite[Lemma 2.4]{SOS}, the image of \eqref{eq:ext-fppf} is contained
    in the set of primitive elements.  To see that the image is exactly the set of
    primitive elements, one proceeds as in the proof of \cite[Theorem 2.6]{SOS}, noting that
    the proof of \cite[VII, \S3 No. 15, Theorem 5]{Serre} cited there carries over to our situation {\em mutatis mutandis} 
    due to the fact that any map from a smooth group such as $H$ or $H\times_k H$ to the local $G$ must be constant.
\end{proof}


\begin{cor}\label{cor:ext-diff}
    Let $H$ be a smooth $k$-group, and denote by $\omega_H$
    the subspace of $H^0(H,\Omega^1_{H/k})$ consisting of translation invariant 1-forms.
    There is a functorial isomorphism of $k$-vector spaces
    $$
        \Ext^1(H,\alpha_p) \simeq \omega_H[V]
    $$
\end{cor}

\begin{proof}
    The functorial isomorphism of Lemma \ref{lem:fppf-diff} and 
    Proposition \ref{prop:ext-primitive} yield a natural identification
    of $\Ext^1(H,\alpha_p)$ with the kernel of $m^*-\pr_1^*-\pr_2^*$
    on $H^0(H,\Omega^1_{H/k,\cl})[V]$.  Since every translation invariant 1-form on $H$ is closed \cite[Lemma 2.1]{Coleman},
    it therefore suffices to observe that $\omega_H$ is precisely the kernel of 
    $m^*-\pr_1^*-\pr_2^*$ on $H^0(H,\Omega^1_{H/k})$, which follows from \cite[III,\S3,Proposition 17]{Serre} applied to $(f,g)=(\pr_1,\pr_2)$. 
\end{proof}



\begin{prop}\label{prop:alphap-diff}
    Let $P\in H^1_{\fppf}(U,\alpha_p)$ and let $\omega(P)\in H^0(U,\Omega^1_X)[V]$ be the corresponding differential form.
        Then the minimal modulus $\frkm(P)$ of $P$ is given by
        $$
        \frkm(P)=\sum_{x\in S} \max\{0,-{\rm ord}_x(\omega(P))\} \cdot x
        $$
\end{prop}

\begin{proof}
Pullback along $\varphi_{\frkm}:U\rightarrow J_{X,\frkm}$ induces 
a commutative diagram
\begin{equation*}
\xymatrix{
{\omega_{J_{X,\frkm}}[V]}\ar[dd]^-{\simeq}_-{\varphi_{\frkm}^*} \ar[rr]^-{\simeq} & & \Ext^1(J_{X,\frkm},\alpha_p) \ar[d]_-{\varphi_{\frkm}^*}^-{=}\\
  & & F_{\frkm}H^1_{\fppf}(U,\alpha_p) \ar@{^{(}->}[d]\\
H^0(X,\Omega^1_{X}(\frkm))[V] \ar@{^{(}->}[r] & H^0(U,\Omega^1_X)[V] \ar[r]^-{\simeq}& H^1_{\fppf}(U,\alpha_p)
}
\end{equation*}
in which the horizontal isomorphisms are induced by the identification of Lemma \ref{lem:fppf-diff},
via Corollary \ref{cor:ext-diff}, and the left vertical isomorphism is due to \cite[V,\S2,No. 10, Proposition 5]{Serre}.
It follows that the identification $H^0(U,\Omega^1_{X/k})[V]\simeq H^1_{\fppf}(U,\alpha_p)$
carries the subspace of differential forms with poles ``no worse'' than $\frkm$
isomorphically onto $F_{\frkm}H^1_{\fppf}(U,\alpha_p)$, as claimed.
\end{proof}





















\section{The abelian fundamental group scheme}\label{sec:ab Nori}

We will continue to use the same notation as in the previous sections. For a fixed base point $x_0\in U(k)$, we denote by $\pi^{\Nori}(U,x_0)$ the {\it fundamental group scheme} for $U$ in the sense of \cite[II]{Nori82}. This is a profinite $k$-group which classifies pointed $G$-torsors $(P,p)\to (U,x_0)$ for any finite (not necessarily abelian) $k$-group scheme $G$. For any rational point $x_1\in U(k)$, $\pi^{\Nori}(U,x_1)$ is an inner twist of $\pi^{\Nori}(U,x_0)$ by \cite[II, Proposition 4]{Nori82}; in particular, the maximal abelian quotient of $\pi^{\Nori}(U,x_0)$ does not depend on the choice of the base point $x_0$, and we denote it simply by $\pi^{\ab}(U)$. This is a profinite $k$-group such that there exists a natural isomorphism of abelian groups 
\[
\Hom(\pi^{\ab}(U),G)\xrightarrow{\simeq}H^1_{\fppf}(U,G)
\]
for variable finite $k$-groups $G$.


As an application of Theorem \ref{thm:CFT}, we will provide a description of the profinite $k$-group $\pi^{\ab}(U)$ in terms of Serre--Oort fundamental groups \cite[II, \S7]{Oort}, \cite{Brion} of generalized Jacobians. Let $\calC$ be the category of $k$-groups (not necessarily connected or reduced); it is an abelian category ({cf.}~\cite[II, \S6, Lemma (6.1)]{Oort}). 
Let $\Pro(\calC)$ be the associated pro-category of $\calC$;
by definition, this is the category of proalgebraic $k$-groups.
Let $\calF\subset\calC$ be the full subcategory of $\calC$ consisting of finite $k$-groups and $\Pro(\calF)$ the category of profinite $k$-groups. 
The functor  $\varpi_0\colon\calC\to\calF;G\mapsto G/G^0_{\red}$ is a left adjoint of the inclusion functor $\calF\hookrightarrow\calC$, hence $\varpi_0$ is right exact and commutes with projective limits. It therefore extends to a right exact functor on the associated pro-categories
\[
\varpi_0\colon\Pro(\calC)\to\Pro(\calF).
\]
As $\Pro(\calC)$ has enough projective objects \cite[I,\S4]{Oort}, we
obtain the left-derived funtors:
\[
\varpi_i\Def{\rm L}^i\varpi_0\colon\Pro(\calC)\to\Pro(\calF),\quad i=0,1,2,\dots 
\]
For any object $G$ of $\Pro(\calC)$, we call $\varpi_1(G)$ the {\it Serre--Oort fundamental group} of $G$. 
According to \cite[II, \S14, Theorem (14.2)]{Oort}, we have $\varpi_i=0$ for $i\ge 2$. Hence, $\varpi_1$ is a left exact functor. Therefore, for any short exact sequence
\[
0\to N\to G\to H\to 0
\]
in $\Pro(\calC)$, we have a long exact {\it homotopy sequence}:
\begin{equation}\label{eq:homotopy seq}
0\to\varpi_1(N)\to\varpi_1(G)\to\varpi_1(H)\to\varpi_0(N)\to\varpi_0(G)\to\varpi_0(H)\to 0.
\end{equation}




\begin{lem}\label{lem:varpi}
Let $G$ be an object of $\Pro(\calF)$ and $H$ an object of $\Pro(\calC)$.
\begin{enumerate}
\item \label{lem:G-projective} $G$ is projective in $\Pro(\calF)$ if and only if it is projective
in $\Pro(\calC)$.

\item \label{lem:varpi-vanishing} We have $\varpi_1(G)=0$ and a natural isomorphism
$\varpi_1(H^0_{\red})\xrightarrow{\simeq}\varpi_1(H)$.

\end{enumerate}
\end{lem}



\begin{proof}
For \eqref{lem:G-projective}, we refer to \cite[II, \S7, Corollary (7.5)]{Oort}. To prove \eqref{lem:varpi-vanishing},
let $P_{\bullet}$ be a projective resolution of $G$ in $\Pro(\calF)$. By \eqref{lem:G-projective}, $P_{\bullet}$ is a projective resolution of $G$ in $\Pro(\calC)$. As $\varpi_0(P_\bullet)=P_{\bullet}$, we see that $\varpi_1(G)=0$. The second assertion then follows from the homotopy exact sequence \eqref{eq:homotopy seq} arising from the exact sequence $0\to H_{\red}^0\to H\to\varpi_0(H)\to 0$. 
\end{proof}

\begin{lem}(cf.\ \cite[\S6.2, Proposition 2]{Serre_GP} and \cite[II, \S7]{Oort})\label{lem:univ cov B}
For any object $H$ of $\Pro(\calC)$, 
there exists an extension in $\Pro(\calC)$
\begin{equation}
    \xymatrix{
        0 \ar[r] & \varpi_1(H) \ar[r] & \overline{H} \ar[r]^-{\overline{u}} & H^0_{\red} \ar[r] & 0
    }\label{eq:ext-univ}
\end{equation}
with the following universal property: any extension in $\Pro(\calC)$ of $H^0_{\red}$
by an object $G$ of $\Pro(\calF)$ arises by pushout of \eqref{eq:ext-univ}
along a unique homomorphism of profinite groups $\varpi_1(H)\rightarrow G$.  In other words, $\varpi_1(H)$ represents the functor 
$\Ext^1(H^0_{\red},-):\Pro(\calF)\rightarrow \Ab$
\end{lem}

\begin{proof}
Let $P\twoheadrightarrow H^0_{\red}$ be a surjective homomorphism with $P$ projective, connected and reduced, and set $R\Def\Ker(P\to H^{0}_{\red})$. We put $\overline{H}\Def P/R^0_{\red}$, so
by definition obtain an extension in $\Pro(\calC)$
\begin{equation}
 \xymatrix{
        0 \ar[r] & \varpi_0(R) \ar[r] & \overline{H} \ar[r]^-{\overline{u}} & H^0_{\red} \ar[r] & 0
 }.\label{eq:hbardefext}
\end{equation}
As $P$ is projective with $\varpi_0(P)=0$, we have  $\varpi_1(P)=0$ and
the homotopy exact sequence (\ref{eq:homotopy seq}) associated to the exact sequence $0\to R^0_{\red}\to P\to \overline{H}\to 0$ implies that $\varpi_1(\overline{H})=0$.  It follows that the homotopy exact sequence \eqref{eq:homotopy seq} associated to \eqref{eq:hbardefext}
induces a natural isomorphism 
\begin{equation}
\varpi_1(H)=\varpi_1(H^0_{\red})\xrightarrow{\simeq}\varpi_0(R),
\label{eq:varpiHpi0R}
\end{equation}
with the first equality due to Lemma \ref{lem:varpi}\eqref{lem:varpi-vanishing}.  This gives the extension \eqref{eq:ext-univ}.

By construction, we have a surjection $\rho:P\twoheadrightarrow \overline{H}$
with $P$ projective and both $P$, $\ker\rho=R^0_{\red}$
connected and reduced.  It follows from this that $\Ext^1(\overline{H},G)=0$ for any profinite $G$.  
Applying $\Hom(-,G)$ to \eqref{eq:hbardefext}, we deduce that
the connecting homomorphism in the resulting long exact sequence
is a functorial isomorphism
\begin{equation}
\Hom(\varpi_1(H),G)\xrightarrow{\simeq}\Ext^1(H^0_{\red},G).
\label{eq:pi1 represents Ext}
\end{equation}
When 
$G=\varpi_1(H)$, the image of identity element ${\rm id}_{\varpi_1(H)}$ under \eqref{eq:pi1 represents Ext} is precisely the class of the 
extension \eqref{eq:ext-univ}; by Yoneda's lemma, 
\eqref{eq:hbardefext} therefore satisfies the stated universal property.
\end{proof}

\begin{definition}\label{def:univ-cover}
    For any object $H$ of $\Pro(\calC)$, we write $u:\overline{H}\to H$
    for the composition of the map $\overline{u}:\overline{H}\twoheadrightarrow H^0_{\red}$ with the inclusion $H^0_{\red}\hookrightarrow H$.
    We call $u:\overline{H}\to H$ the {\em universal cover}
    of $H$.  
\end{definition}    



\begin{rem}\label{rem:univ-alt-character}
    It follows from the universal property of the extension 
    \eqref{eq:ext-univ} that the universal cover $u:\overline{H}\rightarrow H$
    is unique up to unique isomorphism.  Moreover, by construction we
    have
    \begin{enumerate}
    \item\label{eq:keru cokeru}$
        \ker(u) \simeq \varpi_1(H),\ \Cok(u)\simeq \varpi_0(H)
    $
    \item \label{eq:varpi Hbar vaishing} $\varpi_i(\overline{H})=0$ for $i=0,1$.
    \end{enumerate}
    In fact, these properties also characterize the universal cover
    up to unique isomorphism.  
    Indeed,
    any pair $(\overline{H},u)$ satisfying \eqref{eq:keru cokeru}--\eqref{eq:varpi Hbar vaishing} yields an extension as in \eqref{eq:hbardefext}.
    As $\varpi_i(\overline{H})=0$ for $i=0,1$, we
    may choose a surjection
    $\rho:P\twoheadrightarrow \overline{H}$ with $P$ projective and both $P$ and $\ker\rho$ connected and reduced.  As in the proof
    of Lemma \ref{lem:univ cov B}, one deduces that $\Ext^1(\overline{H},G)=0$ for any profinite $G$, and hence that the extension determined 
    by $(\overline{H},u)$ satisfies the universal property
    of Lemma \ref{lem:univ cov B}.
\end{rem}



\begin{rem}\label{rem:varpi}
When $k$ is an algebraically closed field of characteristic $0$, the isomorphism (\ref{eq:pi1 represents Ext}) is due to \cite[\S5.4, Corollaire]{Serre_GP}. In \cite[Corollary 2.7]{Brion}, Brion establishes an analogue of this in a more general setting.
\end{rem}




We now prove our main result: 


\begin{thm}\label{thm:ab Nori}
There exists an isomorphism of profinite $k$-groups, 
\[
\pi^{\ab}(U)\xrightarrow{\simeq}\varprojlim_{\frkm}\varpi_1(J_{X,\frkm}),
\]
where $\frkm$ runs over the set of moduli supported on $S$. 
\end{thm}


\begin{proof}
For any modulus $\frkm$ supported on $S$, pullback
of the universal cover $\overline{J}_{X,\frkm}\to J_{X,\frkm}$ 
along the map $\varphi_{\frkm}\colon U\to J_{X,\frkm}$
gives a $\varpi_1(J_{X,\frkm})$-torsor $\varphi_{\frkm}^*\overline{J}_{X,\frkm}\to U$. 
For variable $\frkm$ supported on $S$, these give rise
to a homomorphism
\[
\pi^{\ab}(U)\to\varprojlim_{\frkm}\varpi_1(J_{X,\frkm}).
\]
that we claim is an isomorphism. It suffices to show that for any finite $k$-group $G$, the induced map
\[
\varinjlim_{\frkm}\Hom(\varpi_1(J_{X,\frkm}),G)=\Hom\left(\varprojlim_{\frkm}\varpi_1(J_{X,\frkm}),G\right)\to\Hom(\pi^{\ab}(U),G)
\]
is bijective. By Theorem \ref{thm:CFT}, it suffices to show that the connecting homomorphism
\[
\Hom(\varpi_1(J_{X,\frkm}),G)\to\Ext^1(J_{X,\frkm},G)
\]
is bijective for any $\frkm$. This is valid thanks to the isomorphism (\ref{eq:pi1 represents Ext}).  
\end{proof}




As a special case of Theorem \ref{thm:ab Nori}, we deduce the following well-known
description of the abelianized Nori fundamental group scheme of a projective curve:


\begin{cor}(cf.\ \cite[Remark 2]{Nori83},\cite[Corollary 3.8]{Antei},\cite[Corollary 7.2]{Langer})\label{cor:ab pi X}
Let $X$ be a smooth projective curve over $k$. The
Albanese map $\varphi_0\colon X\to J_{X}$ associated to any fixed choice
of base point induces a natural isomorphism of profinite $k$-groups
\[
\varphi_{0,*}\colon\pi^{\ab}(X)\xrightarrow{\simeq}\varprojlim_{n}J_X[n].
\]
\end{cor}

\begin{proof}
Specializing Theorem \ref{thm:ab Nori} to the case $U=X$ and $S=\emptyset$,
we see that $\varphi_0$ induces an idomorphism of profinite $k$-groups $\varphi_{0,*}\colon\pi^{\ab}(X)\xrightarrow{\simeq}\varpi_1(J_X)$. It suffices to show that
\begin{equation}\label{eqn:Nori-proj-desc}
\varpi_1(J_X)=\varprojlim_{n}J_X[n].
\end{equation}
Now for any subgroup $N$ of $\varpi_1(J_X)$ with $\varpi_1(J_X)/N$ a finite $k$-group, we have $n(\varpi_1(J_X)/N)=0$, and hence  $n\varpi_1(J_X)\subset N$ for all $n>0$ sufficiently large
with respect to the divisibility ordering on the positive integers
\cite[VIIA, Proposition 8.5]{SGA3i}. 
It follows that the canonical map
\begin{equation}
\varpi_1(J_X)\xrightarrow{\simeq}\varprojlim_n\varpi_1(J_X)/n\varpi_1(J_X).
\label{eqn:varpi-Jac-A}
\end{equation}
is an isomorphism of profinite $k$-groups.
On the other hand, for any integer $n>0$, the exact sequence
\[
0\to J_X[n]\to J_X\to J_X\to 0
\]
gives rise to the long exact homotopy sequence
\[
0\to \varpi_1(J_X[n])\to \varpi_1(J_X)\xrightarrow{n} \varpi_1(J_X)\to\varpi_0(J_X[n])\to 0.
\]
As $J_X[n]$ is a finite $k$-group, we have $\varpi_0(J_X[n])=J_X[n]$, 
and $\varpi_1(J_X[n])=0$ thanks to Lemma \ref{lem:varpi}(2).
We obtain an exact sequence
\begin{equation}
0\to\varpi_1(J_{X})\xrightarrow{n}\varpi_1(J_X)\to J_X[n]\to 0.
\label{eqn:varpi-Jac-B}
\end{equation}
Combining \eqref{eqn:varpi-Jac-A} with \eqref{eqn:varpi-Jac-B}
yields the desired description \eqref{eqn:Nori-proj-desc}.
\end{proof}




\begin{cor}\label{cor:mult}
The multiplicative part $\pi^{\ab}(U)^{\rm m}$ of the abelian fundamental group scheme can be described as follows:
\[
\pi^{\ab}(U)^{\rm m}=\Diag\left(J_X(k)_{\rm tor}\times\Ker\left(\Sigma\colon\prod_{x\in S}\Q/\Z\to\Q/\Z\right)\right)
\]
\end{cor}

\begin{proof}
As $k$ is algebraically closed, a $k$-group is of multiplicative type if and only if it is diagonalizable, i.e., $G\simeq\Diag(M)$ for some abelian group $M$ (cf.\ \cite[7.3]{Wat}), in which case we have $M\simeq\Hom_{\text{$k$-grp}}(G,\G_m)$, and 
the multiplicative part $\pi^{\ab}(U)^{\rm m}$ is defined to be
\[
\pi^{\ab}(U)^{\rm m}\Def\Diag\left(\Hom(\pi^{\ab}(U),\G_m)\right).
\]
Therefore, it suffices to show that
\[
\Hom(\pi^{\ab}(U),\G_m)=J_X(k)_{\rm tor}\times\Ker\left(\Sigma\colon\prod_{x\in S}\Q/\Z\to\Q/\Z\right).
\]
By Theorem \ref{thm:ab Nori} together with the description of generalized Jacobians recalled in Remark \ref{rem:L_m}, we have
\begin{align*}
\Hom(\pi^{\ab}(U),\G_m)&=\varinjlim_{\frkm}\Hom(\varpi_1(J_{X,\frkm}),\G_m)=\Hom(\varpi_1(J_{X,\frkm_{\red}}),\G_m)\\
&=\varinjlim_{n}\Hom(\varpi_1(J_{X,\frkm_{\red}}),\mu_n)=\varinjlim_n\Ext^1(J_{X,\frkm_{\red}},\mu_n)\\
&=\varinjlim_n\Ext^1(J_X,\mu_n)\times\Ext^1\left(\left(\prod_{x\in S}\G_m\right)/\G_m,\mu_n\right)\\
&\simeq\varinjlim_nJ_X[n](k)\times\Ker\left(\Sigma\colon\prod_{x\in S}\Z/n\Z\to\Z/n\Z\right)\\
&=J_X(k)_{\rm tor}\times\Ker\left(\Sigma\colon\prod_{x\in S}\Q/\Z\to\Q/\Z\right).
\end{align*}
This completes the proof. 
\end{proof}


\begin{cor}\label{cor:pro-p et}
The maximal pro-$p$ quotient $\pi^{\ab}(U)(k)^{(p)}$ of the profinite group $\pi^{\ab}(U)(k)$ can be described as follows.
\[
\pi^{\ab}(U)(k)^{(p)}\simeq 
\varprojlim_nJ_X[p^n](k)\times 
\prod_{x\in S}\Hom\left(\varinjlim_n U_x^{(1)}/U_x^{(n)},\Q_p/\Z_p\right)
\]
\end{cor}

\begin{proof}
By Theorem \ref{thm:ab Nori}, we have
\begin{align*}
\pi^{\ab}(U)(k)^{(p)}&=\varprojlim_{\frkm}\varpi_1(J_{X,\frkm})(k)^{(p)}\simeq\varprojlim_{\frkm,n}\varpi_1(J_{X,\frkm})(k)/p^n\varpi_1(J_{X,\frkm})(k).
\end{align*}
For any modulus $\frkm$ supported on $S$ and any integer $n>0$, consider the commutative diagram with exact rows
\[
\xymatrix{
0\ar[r]&\varpi_1(L_{\frkm})\ar[r]\ar[d]^{p^n}&\varpi_1(J_{X,\frkm})\ar[r]\ar[d]^{p^n}&\varpi_1(J_X)\ar[r]\ar[d]^{p^n}&0\\
0\ar[r]&\varpi_1(L_{\frkm})\ar[r]&\varpi_1(J_{X,\frkm})\ar[r]&\varpi_1(J_X)\ar[r]&0.
}
\]
By the snake lemma, we have the exact sequence of $\Z/p^n\Z$-modules
\[
0\to\varpi_1(L_{\frkm})(k)/p^n\varpi_1(L_{\frkm})(k)\to\varpi_1(J_{X,\frkm})(k)/p^n\varpi_1(J_{X,\frkm})(k)\to J_X[p^n](k)\to 0.
\]
As $J_X[p^n](k)$ is a free $\Z/p^n\Z$-module, this is a split exact sequence, hence
\begin{equation}\label{eq:pro-p et}
\varpi_1(J_{X,\frkm})(k)/p^n\varpi_1(J_{X,\frkm})(k)\simeq J_X[p^n](k)\times\varpi_1(L_{\frkm})(k)/p^n\varpi_1(L_{\frkm})(k).
\end{equation}
Therefore, it suffices to describe $\varpi_1(L_{\frkm})(k)/p^n\varpi_1(L_{\frkm})(k)$ for any $\frkm$ and any $n>0$. 
Let $T_{\frkm}$ (respectively $U_{\frkm}$) be the multiplicative part (respectively the unipotent part) of $L_{\frkm}$. 
As the multiplication by $p^n$ map on $T_{\frkm}$ is finite surjective and $U_{\frkm}[p^n]$ is connected and reduced, we have 
\[
\varpi_1(L_{\frkm})(k)/p^n\varpi_1(L_{\frkm})(k)=\varpi_1(L_{\frkm}/p^nL_{\frkm})(k)=\varpi_1(U_{\frkm}/p^nU_{\frkm})(k).
\]
By the description of $L_{\frkm}$ recalled in Remark \ref{rem:L_m}, we have
$
U_{\frkm}=\prod_{x\in S}V_{(n_x)}
$
for $\frkm=\sum_{x\in S}n_x x$, where we denote by $V_{(n_x)}$ the smooth unipotent $k$-group with $V_{(n_x)}(k)=U_x^{(1)}/U_x^{(n_x)}$. Therefore  
\[
U_{\frkm}/p^nU_{\frkm}=\prod_{x\in S}V_{(\min\{p^n,n_x\})}.
\]
As each component $V_{(\min\{p^n,n_x\})}$ is a finite product of Witt vector groups of finite length; see Remark \ref{rem:L_m}, Serre's description of the fundamental groups for them (see \cite[8.4, Corollaire 2]{Serre_GP}) implies that
\[
\varpi_1(L_{\frkm})(k)/p^n\varpi_1(L_{\frkm})(k)=\prod_{x\in S}\Hom\left(U_x^{(1)}/U_x^{(\min\{p^n,n_x\})},\Q_p/\Z_p\right).
\]
This, together with the decompositions (\ref{eq:pro-p et}), implies that
\begin{align*}
\pi^{\ab}(U)(k)^{(p)}&=
\varprojlim_{\frkm,n}\left(J_{X}[p^n](k)\times\prod_{x\in S}\Hom\left(U_x^{(1)}/U_x^{(\min\{p^n,n_x\})},\Q_p/\Z_p\right)\right)\\
&=\varprojlim_{n}J_X[p^n](k)\times\prod_{x\in S}\Hom\left(\varinjlim_{n}U_x^{(1)}/U_x^{(n)},\Q_p/\Z_p\right).
\end{align*}
This completes the proof. 
\end{proof}



\begin{rem}
Note that $\pi^{\ab}(U)(k)$ is simply the maximal abelian quotient of the \'etale fundamental group $\pi_1^{\et}(U)$ of the curve $U$. 
In \cite[Corollary 3.5]{Kumar}, Kumar provides an explicit description of the maximal pro-$p$ abelian quotient of the \'etale fundamental group $\pi_1^{\et}(U)$ of an affine curve $U$ in terms of its coordinate ring
$\Gamma(U,\scrO_U)$. It would be interesting to understand the relation between Corollary \ref{cor:pro-p et} and his description. 
\end{rem}



For any $k$-group $G$ and any integer $m$, we write
$G^{(m)}$ for the pullback of $G$ along the automorphism
$F^m\colon k \rightarrow k$ of $k$.  By definition,
we have $(G^{(m)})^{(1)}=G^{(m+1)}$, and for any 
nonnegative integer $n$, the $n$-th iterate of the relative
Frobenius map defines a morphism $F^n: G^{(m)}\rightarrow G^{(m+n)}$.
We denote by $G[F^n]$ the kernel of $F^n:G\rightarrow G^{(n)}$.
If $P_{\bullet}$ is a projective resolution of $G$, then the relative Frobenius morphism $F$ on $G$ is extended by the relative Frobenius morphism
on each term of the resolution. Noting that the Frobenius twist of the resolution $P_{\bullet}^{(1)}$ gives a projective resolution of $G^{(1)}$, by applying $\varpi_0(-)$
to the resolution and passing to homology, we deduce that
the morphism $\varpi_1(F)$ coincides with the relative Frobenius
morphism of $\varpi_1(G)$.


\begin{lem}\label{lem:conn part}
For any connected and reduced $k$-group $G$, we have
\[
\varpi_1(G)^0\simeq\varprojlim_nG^{(-n)}[F^n],
\]
whith transition maps 
induced by the relative Frobenius morphism $F\colon G^{(-n-1)}\to G^{(-n)}$. 
\end{lem}

\begin{proof}
For any $k$-subgroup $N$ of $\varpi_1(G)^0$ with $\varpi_1(G)^0/N$ finite, as $\varpi_1(G)^0/N$ is finite 
 and connected, we have $F^n(\varpi_1(G)^{0,(-n)}/N^{(-n)})=0$, hence $F^n(\varpi_1(G)^{0,(-n)})\subset N$ for sufficiently large $n>0$.
This implies that we have a natural isomorphism 
\[
\varpi_1(G)^0\xrightarrow{\simeq}\varprojlim_n\varpi_1(G)^0/F^n(\varpi_1(G)^{0,(-n)}).
\]
Per the discussion above, for any positive integer $n>0$, the commutative diagram with exact rows
\[
\xymatrix{
0\ar[r]& G^{(-n-1)}[F^{n+1}]\ar[r]\ar[d]_F& G^{(-n-1)}\ar[r]_{F^{n+1}}\ar[d]_F& G\ar[r]\ar@{=}[d]& 0\\
0\ar[r]& G^{(-n)}[F^n]\ar[r]& G^{(-n)}\ar[r]_{F^n}& G\ar[r]& 0
}
\]
gives rise to the commutative diagram with exact rows
\[
\xymatrix{
0\ar[r]& \varpi_1(G)^{(-n-1)}\ar[r]_{F^{n+1}}\ar[d]_F& \varpi_1(G)\ar[r]\ar@{=}[d]& G^{(-n-1)}[F^{n+1}]\ar[r]\ar[d]_{F}& 0\\
0\ar[r]& \varpi_1(G)^{(-n)}\ar[r]_{F^n}& \varpi_1(G)\ar[r]& G^{(-n)}[F^n]\ar[r]& 0
}
\]
from which we deduce a natural isomorphism  
\[
\varpi_1(G)^0\xrightarrow{\simeq}\varprojlim_n\varpi_1(G)^0/F^n(\varpi_1(G)^{0,(-n)})\xrightarrow{\simeq}\varprojlim_{n}G^{(-n)}[F^n].
\]
\end{proof}

\begin{cor}\label{cor:conn part}
The connected component of the identity $\pi^{\ab}(U)^0$ of the abelian fundamental group scheme can be described as follows:
\[
\pi^{\ab}(U)^0\xrightarrow{\simeq}
\varprojlim_{\frkm}\varprojlim_{n}J^{(-n)}_{X,\frkm}[F^n]=
\varprojlim_{\frkm,n}J_{X,\frkm}^{(-n)}[F^n],
\]
where the transition maps 
are induced by the relative Frobenius morphism $F\colon J_{X,\frkm}^{(-n-1)}\to J_{X,\frkm}^{(-n)}$. 
\end{cor}


\begin{proof}
This follows immediately from Theorem \ref{thm:ab Nori}
and Lemma \ref{lem:conn part}.
\end{proof}



\section{The unipotent fundamental group schemes for singular curves}\label{sec:singular curve}


It does not seem that there exists a relevant description of the unipotent part of the abelian fundamental group scheme $\pi^{\ab}(U)$ purely in terms of the generalized Jacobians $J_{X,\frkm}$ unless $U=X$. In fact, the following result due to Nori suggests that each $J_{X,\frkm}$ is directly related to the abelian unipotent fundamental group scheme of the corresponding singular curve $X_{\frkm}$ rather than the affine curve $U$. The curve $X_{\frkm}$ is defined in \cite[IV,\S1]{Serre}; it is a projective and integral curve over $k$ with normalization $X\rightarrow X_{\frkm}$ that is an isomorphism
over $X\setminus S$, and it satisfies $\Pic_{X_{\frkm}}^0=J_{X,\frkm}$.

\begin{thm}(cf.\ \cite[IV, Proposition 6]{Nori82})\label{thm:sing curve}
The unipotent part of $\pi^{\ab}(X_{\frkm})$ can be described as follows:
\[
\pi^{\ab}(X_{\frkm})^{\uni}=\varprojlim_{G=G^0\hookrightarrow J_{X,\frkm}}G^D=\varprojlim_{n}J_{X,\frkm}[F^n]^D,
\]
where $G^D$ means the Cartier dual of $G$. 
\end{thm}


\begin{rem}
Note that the map $\pi^{\ab}(U)\to\pi^{\ab}(X_{\frkm})$ induced by the composition $U\hookrightarrow X\to X_{\frkm}$ is far from being injective or surjective. For example, when $X=\bbP^1_k$, the map $\pi^{\ab}(U)\to\pi^{\ab}(X_{\frkm})$ factors through the trivial group scheme  $\pi^{\ab}(\bbP^1_k)=1$. 
\end{rem}


We conclude the present paper with a proof of the following version of Das' description of the \'etale fundamental group of a singular curve \cite[Theorem 3.3]{Das}: 

\begin{thm}\label{thm:uni ab}
Let $\frkm=\sum_{x\in S}n_xx$. For each point $x\in S$ and any $1\le i\le n_x-1$ with $p\nmid i$, we denote by $r_{x,i}$ the smallest integer $r>0$ satisfying $p^r\ge n_x/i$. Then $\pi^{\ab}(X_{\frkm})^{\uni}$ fits into the short exact sequence 
\[
0\to\pi^{\ab}(X)^{\uni}\to\pi^{\ab}(X_{\frkm})^{\uni}\to\Z_p^{\oplus \#S-1}\times\prod_{x\in S}\prod_{1\le i \le n_x-1,\,p\nmid i} W[F^{r_{x,i}}]\to 0,
\]
in which $W\Def\varprojlim_n W_n$. 
\end{thm}

\begin{proof}
Taking Frobenius kernels on the exact sequence
$0\to L_{\frkm}\to J_{X,\frkm}\to J_X\to 0$,
yields exact sequences 
\[
0\to L_{\frkm}[F^n]\to J_{X,\frkm}[F^n]\to J_X[F^n]\to 0
\]
for all $n\ge 1$, which form an inductive system of short exact sequences.  
Dualizing, we obtain the exact sequences
\[
0\to J_X[F^n]^D\to J_{X,\frkm}[F^n]^D\to L_{\frkm}[F^n]^D\to 0
\]
for all $n\ge 1$, which form a projective system of short exact sequences.   
Taking the projective limit of these, 
and noting that the transition maps $J_X[F^{n+1}]^D\to J_X[F^n]^D$
are surjective, from \cite[Lemma 02N1]{SP}
we obtain an exact sequence
\[
\xymatrix{
0\ar[r]& \varprojlim_nJ_X[F^n]^D\ar[r]&\varprojlim_n J_{X,\frkm}[F^n]^D\ar[r]&\varprojlim_nL_{\frkm}[F^n]^D\ar[r]& 0\\
&\pi^{\ab}(X)^{\uni}\ar[u]_{\simeq}&\pi^{\ab}(X_{\frkm})^{\uni}\ar[u]_{\simeq}&&
}
\]
with vertical isomorphisms due to Theorem \ref{thm:sing curve}. 
It therefore suffices to show that
\[
\varprojlim_nL_{\frkm}[F^n]^D\simeq\Z_p^{\oplus\#S-1}\times\prod_{x\in S}\prod_{1\le i \le n_x-1,\,p\nmid i} W[F^{r_{x,i}}].
\]
To that end, it suffices to show that 
\begin{equation}\label{eq:uni sing}
L_{\frkm}[F^n]^D\simeq(\Z/p^n\Z)^{\oplus\#S-1}\times\prod_{x\in S}\prod_{1\le i \le n_x-1,\,p\nmid i} W_n[F^{r_{x,i}}]
\end{equation}
for each $n\ge 1$. Note that $\Z/p^n\Z=\mu_{p^n}^D$ and $W_n[F^{r_{x,i}}]=W_{r_{x,i}}[F^n]^D$ (cf.\ \cite[II,\S13]{Oort}). Thus, the equality (\ref{eq:uni sing}) is immediate from the description of $L_{\frkm}$ given by \eqref{eq:local grp} and Remark \ref{rem:L_m}.
\end{proof}






