\begin{document} 
	\maketitle
	\abstract{We gather tools for proving the inductive McKay--Navarro (or Galois--McKay) condition for groups of Lie type and odd primes. We use this to establish a bijection in the case of quasisimple groups of Lie type $\tA$ satisfying the equivariance properties needed for the condition. We also prove the inductive conditions for the subset of unipotent characters.}


\tableofcontents

\section{Introduction}
Since the time of Brauer, the study of the representation theory of a finite group through its relationship to local data has been a leading objective in the theory of finite groups.  
One of the most influential conjectures recently in this realm has been the McKay conjecture, along with its refinements. 
The McKay conjecture (recently announced as a theorem due to the third author and M. Cabanes \cite{CS24}) says that for a prime $\ell$ dividing the order of a finite group $G$, the number of irreducible characters of $\ell'$-degree, $\irr_{\ell'}(G)$, should be the same as that of $\Norm_G(P)$ for $P$ a Sylow $\ell$-subgroup of $G$. 

In this paper, we are concerned with the McKay--Navarro conjecture (also known as the Galois--McKay conjecture, \cite[Conjecture A]{nav04}), which suggests that a bijection between $\irr_{\ell'}(G)$
 and $\irr_{\ell'}(\Norm_G(P))$ can be further chosen to be equivariant with respect to certain Galois automorphisms 
 $\cH_\ell\leq \mathrm{Gal}(\QQ^{\mathrm{ab}}/\QQ)$. 
(See Definition \ref{defH} below.) Here, $\QQ^{\mathrm{ab}}$ denotes the extension of $\QQ$ generated by all roots of unity in $\CC$.

The McKay--Navarro conjecture was reduced by Navarro--Sp{\"a}th--Vallejo in \cite{NSV20} to the so-called ``inductive Galois--McKay" conditions for quasisimple groups. We will refer to these as the inductive McKay--Navarro (iMN) conditions. These iMN conditions build upon the inductive McKay conditions of Isaacs--Malle--Navarro in \cite{IMN}, adding $\galh_\ell$-compatibility. The first-named author
 completed these conditions when $G$ is a group of Lie type in defining characteristic in  \cite{R21}, and he and the second-named author completed the conditions when $\ell=2$ in \cite{SF22, RSF22, RSF22b}. 

The goal of this paper is to lay some foundations for dealing with the remaining cases -  namely, the case of groups of Lie type defined in characteristic $p\neq \ell$ when $\ell$ is odd.
We establish several results in this direction, which will be useful in the pursuit of the iMN conditions in this situation.
In particular, we introduce criterion in Section \ref{sec:criterion}  that will be useful for proving that groups of Lie type satisfy the iMN conditions - see Theorem \ref{crit_iGalMcK} and Corollary \ref{12vib} below.



 The iMN conditions can be roughly described as an ``equivariance" condition and an ``extension" condition.  In Sections \ref{sec:equivbij}--\ref{sec:transversallocal}, we primarily work with the  equivariance condition. Namely, this is the first part of \cite[Definition 3.1]{NSV20}, which we state here:

\begin{condition}\label{cond:equivcondition}
Let $\ell$ be a prime.
Let $G$ be a finite quasisimple group with $\ell\mid|G|$ and let $P\in\mathrm{Syl}_\ell(G)$.  
Then there is a proper $\Aut(G)_P$-stable subgroup $M$ of $G$ with $\Norm_G(P)\leqslant M$ and an 
$\Aut(G)_P\times\galh_\ell$-equivariant bijection 
$\irr_{\ell'}(G)\rightarrow\irr_{\ell'}(M)$ such that corresponding characters lie over the same character of $\Z(G)$.
\end{condition}

In Section \ref{sec:criterion}, we prove the following.

\begin{theo}\label{thm:critintro}
Let $G$ be the universal covering group of a nonabelian simple group and let $\ell\mid |G|$ be an odd prime. Assume that Conditions (i)--(vi) of Theorem \ref{crit_iGalMcK}  hold for $\galh=\galh_\ell$, $\subG=\Irr_{\ell'}(G)$ and $\subM=\Irr_{\ell'}(M)$, where $M\lneq G$ is a subgroup containing $\norm{G}{P}$ for $P$ a Sylow $\ell$-subgroup of $G$. Then Condition \ref{cond:equivcondition} holds for $G$ and $M$. 

If (vii) of Corollary \ref{12vib} additionally holds, then the inductive McKay--Navarro conditions \cite[Def.~3.1]{NSV20} hold for $G$ and the prime $\ell$.
\end{theo}

Our next main result is that Condition \ref{cond:equivcondition} holds for a group of Lie type $G$ defined in characteristic $p\neq \ell$ if certain local extension conditions hold. 

\begin{theo}\label{thm:thmA}
Assume $(\bG, F)$ is a finite reductive group such that $\bG$ is of simply connected type, and fix a Sylow $d$-torus $\bS$ of $(\bG,F)$, where $d=d_\ell(q)$, and a regular embedding $\bG\hookrightarrow\wt\bG$.

Denote by $\wt N:=\Norm_\wGF(\bS)$ and $N:=\wt N\cap \GF=\Norm_\GF(\bS)$ the normalizers of $\bS$ and set
\begin{align*}
\mathfrak{C}:= \{ \chi\in  \Irr(\Cent_\wGF(\bS))\mid  \Irr(N\mid \restr \chi|{\Cent_\GF(\bS)}) \cap \Irrl(N)\neq \emptyset \}.
\end{align*} 
Assume there exists some $\galh\ltimes (\Irr(\wt N/N)\rtimes  (\GF\EGF)_\bS
	)$-equivariant extension map $\wt \Lambda$ for $\mathfrak{C}$ with respect to $\Cent_\wGF(\bS)\lhd \wt{N}$, where $\galh\leq\galh_\ell$ is a subgroup of Galois automorphisms and $E(\bG^F)$ is the group of field and graph automorphisms as in Section~\ref{sec:bijpfthmA}.

Then there exists some  $\galh\ltimes (\Irr(\wGF/\GF)\rtimes (\GF\EGF)_{\bS})$-equivariant bijection
\begin{equation*}
\wt \Omega: \Irr(\wGF\mid \Irrl(\GF ))\lra\Irr(\wt N\mid \Irrl(N )),
\end{equation*}
such that 
$\Irr\left(\Z(\wt\bG^F)\mid \Omega(\chi)\right)=\Irr\left({\Z(\wt\bG^F)}\mid \chi\right)$
for every $\chi \in \Irr(\wGF\mid \Irrl(\GF ))$.
\end{theo}

 The proof of Theorem \ref{thm:thmA} is the goal of Section \ref{sec:equivbij}.
It turns out that it will sometimes be useful to use the result of Theorem \ref{thm:thmA} with respect to a different overgroup. In this case, Theorem \ref{thm:notbutterfly} will allow us to replace $\wt{\bG}^F$ with such an overgroup.

 In Section \ref{sec:transversal}, we use the theory of Generalized Gelfand Graev Representations to prove that there is a convenient transversal in the case of groups of type $\tA$ (see Theorem \ref{thm:typeAtransversalglobal}). We use this to prove that the equivariance condition holds for the groups $\SL_n(q)$ and $\SU_n(q)$, together with Theorem \ref{thm:thmA} and the work of Petschick and the third-named author \cite{SoniaSpaeth}, who have proved the necessary local conditions in these cases. 
 Along the way, we present candidates for the criterion in Theorem \ref{crit_iGalMcK} and Corollary \ref{12vib} in the case of type $\tA$, showing that the conditions in Theorem \ref{crit_iGalMcK} are satisfied. 


  \begin{coralph}\label{cor:equivcondtypeA}
Let $G=\bG^F\in\{\SU_n(q), \SL_n(q)\}$ and let $\ell\nmid q$ be an odd prime dividing $|G|$. Then the conditions of Theorem \ref{crit_iGalMcK} are satisfied for $\galh:=\galh_\ell$, $\subG:=\Irr_{\ell'}(G)$, and $\subM:=\Irr_{\ell'}(M)$, taking $M:=\norm{G}{\bS}$ for $\bS$ a Sylow $d_\ell(q)$-torus of $(\bG, F)$, $\widecheck{G}:=\Lang^{-1}(\rZ(\bG))$, and  $B$ as in Corollary \ref{cor:Bglobal}. 

In particular, $G$ satisfies Condition \ref{cond:equivcondition}.
\end{coralph}


We remark that we anticipate the last condition of the criterion, namely the condition stated in Corollary \ref{12vib}, will also be satisfied in the situation of Corollary \ref{cor:equivcondtypeA}. (The first part of the additional condition, namely that $B$ normalizes $\wh M$, is satisfied in this situation - see Corollary \ref{cor:Bglobal}.) This would also ensure the ``extension" part (hence the full iMN condition) for type $\tA$, and will be the objective of future work by the authors.

In Sections \ref{sec:extunip1} and \ref{sec:extunip2}, we begin treating the ``extension" condition. This condition requires that the bijection from Condition \ref{cond:equivcondition} also behaves well when taking projective extensions of the characters to the stabilizer in the automorphism group. In the case of unipotent characters, we obtain the full iMN condition. 


\begin{theo}\label{thm:unipcriterion}
Let $G=\bG^F$ with $\bG$ a connected reductive group of simply connected type and $F\colon \bG\rightarrow\bG$ a Frobenius endomorphism and suppose that $\bG$ is not of type $\tB_2,\tF_4$ if $p=2$ and $\tG_2$ if $p=3$ (so that $G$ admits no exceptional Suzuki or Ree automorphism). Let $\ell$ be an odd prime and let $\galh:=\galh_\ell$. Then $G$ satisfies the conclusion of Corollary \ref{12vib} for $\subG:=\Irr_{\ell'}(G)\cap\UCh(G)$ and $\subM:=\Omega(\subG)$, where $M:=\norm{G}{\bS}$ is the normalizer of a Sylow $d_\ell(q)$-torus and $\Omega$ is the McKay bijection given in \cite{Ma07}, and where we take $\widecheck{G}:=\wt{G}$ to be the group $\wt{G}:=\wt\bG^F$ obtained by a regular embedding $\bG\rightarrow \wt\bG$.

 That is, there exists a $\widecheck M\wh M\times\galh$-equivariant bijection $\Omega:\subG\lra\subM$ such that 
    $$((\widecheck G E)_{\chi^{\calH}}, G, \chi)_\cH \geq_c ((\widecheck{M}\wh M)_{\psi^\cH}, M, \psi)_{\cH}$$  for every $\chi\in  \subG$ and $\psi:=\Omega(\chi)$.
\end{theo}






\section{Preliminaries on the Galois automorphisms}

	We begin with some number-theoretic observations regarding the Galois automorphisms under consideration.

\begin{notation}\label{defH} As defined by Gabriel Navarro \cite{nav04}, we let $\cH_\ell$ denote the subgroup of the Galois group $\gal:=\Gal(\QQ^{\ab}/\QQ)$ comprised of those $\sigma\in\gal$ satisfying that there is some $e\geq 0$ such that  $\sigma$ acts on $\ell'$-roots of unity by $\zeta\mapsto \zeta^{\ell^e}$. 

For an integer $d\geq1$, we will also let $\cH_{[d]}$ denote the subgroup of $\gal$ stabilizing any $d$-th root of unity. 
\end{notation}


It will sometimes be useful to note that $\galh_\ell$ can be identified with the Galois group $\mathrm{Gal}(\QQ_\ell^{\mathrm{ab}}/ \QQ_\ell)$. As such, we observe the following immediate consequence of Hensel's Lifting Lemma, which could also be seen using Gauss sums and arguments as in \cite[Section 4]{SFT23}.

\begin{lem}\label{lem:square}
Let $\ell$ be an odd prime and let $a$ be an integer relatively prime to $\ell$ that  is a square modulo $\ell$. Then $\sqrt{a}^\sigma=\sqrt{a}$ for all $\sigma\in\galh_\ell$.
\end{lem}

Throughout, for an integer $q$ and odd prime $\ell$, we let $d_\ell(q)$ denote the multiplicative order of $q$ modulo $\ell$.  
\begin{lem} 
\label{lem:numtheory}
	Let $\ell$ be an odd prime and $d$ any integer dividing  $(\ell-1)$. (For  example, this is the case when $d$ is the order of an element of $\FF_\ell^\times$.) Then: 
	\begin{enumerate} 
	\item \label{H} $\cH_{\ell}\subseteq \cH_{[d]}$; 
	\item \label{2mH} if $d=2m$ with $m$ odd, then $\cH_{[d]}=\cH_{[m]}$; 
	\item \label{2msqrt} if $d=2m$ with $m$ odd and $q$ is an  integer with $d_\ell(q)=d$, then $\sqrt{-q}^\sigma=\sqrt{-q}$ for any $\sigma\in\galh_\ell$;
	\item \label{sqrt} if $d$ is odd and $q$ is an integer with $d_\ell(q)=d$, then $\sqrt{q}^\sigma=\sqrt{q}$ for any $\sigma\in\galh_\ell$.
	\end{enumerate}
	\end{lem}
\begin{proof}
If $\xi$ is a $d$th root of unity (and hence an $(\ell-1)$st root of unity), then $\sigma(\xi)=\xi^{\ell^e}=\xi$ for any $\sigma\in\galh_\ell$, so \ref{H} holds. For \ref{2mH}, note that any member of $\gal$ must necessarily fix $-1$, and that any $d$th root of unity must be of the form $\pm\zeta_m$ with $\zeta_m$ an $m$th root of unity.
In the situation of \ref{2msqrt}, we have $\ell$ divides $q^{m}+1$, and hence $q^{m}\equiv -1\pmod \ell$. Since $m$ is odd, we see $q$ is a square in $\FF_\ell^\times$ if and only if $-1$ is. This means that  $-q$ is a square in $\FF_\ell^\times$, and we apply Lemma \ref{lem:square}.

For \ref{sqrt}, note that we may assume that $q$ is not a square, since otherwise the statement is clear. Hence $q$ is an odd power of a prime $p$. By construction, $d$ is the order of $q$ in $\FF_\ell^\times$. As $\ell-1$ is even and $d$ is odd, this shows that  $q$ is a square in $\FF_\ell^\times$, and we again apply Lemma \ref{lem:square}.
\end{proof}


 \section{Criterion for the inductive McKay--Navarro condition}\label{sec:criterion}




In this section, we introduce a statement that simplifies checking the inductive McKay--Navarro condition. The statement below (\Cref{crit_iGalMcK_full}) is modeled after   \cite[Thm.~2.12]{S12}, which is a criterion for verifying the inductive McKay condition and was applied to simple groups of Lie type in various cases. 


\subsection{The inductive McKay--Navarro condition}

Before stating our criterion, we introduce the inductive conditions from \cite{NSV20}. We begin with some notation.

\begin{defi}\label{def:extmap}
Let $G\lhd A$ and  $\chi\in\Irr(G)$ invariant under $A$. Then $(A,G,\chi)$ is an ordinary character triple and there exists a projective representation $\calP$ of $A$ associated to $\chi$, see \cite[Def.~5.2]{Navarro_book}.
Assume that $H\leq A$ with $A=GH$ with $\Cent_A(G)\leq H$. If $\psi\in\Irr(M)$ is some $H$-invariant character for $M:=G\cap H$, then there exists some projective representation $\calP'$ of $H$ associated to $\psi$. We say that $(\calP,\calP')$ gives
\[(A,G,\phi)\geq_c(H,M,\psi),\]
whenever the factor set of $\calP$ restricted to $H\times H$ is the factor set of $\calP'$ and for each $c\in\Cent_A(G)$ the matrices $\calP(c)$ and $\calP'(c)$ are scalar matrices associated to the same scalar; see also \cite[Def.~10.14]{Navarro_book}. We also write $(A,G,\phi)\geq_c(H,M,\psi)$ if there exist $(\calP,\calP')$ giving that relation.
\end{defi}

For the inductive McKay--Navarro condition, we need adaptions of the above notions. 


\begin{defi} Given $G\lhd A$, the group $\gal\times \Aut(A)_G$ acts on $\Irr(G)$. 
Let $\chi\in\Irr(G)$ and $\alpha \in \gal\times \Aut(A)_G$ with $\chi^\al =\chi$. 
If $\chi$ extends to a character $\wt \chi$ of $A$, then there exists a unique linear character $\mu\in \Irr(A)$ with 
        $G\leq \ker(\mu)$ and 
        \[\wt\chi^\alpha=\wt\chi\mu\] 
    	by Gallagher's theorem \cite[Cor.~6.17]{Isa}. We will write $[\wt\chi, \alpha]:=\mu$ in this situation.
The projective representation $\calP^\alpha$ is again a projective representation of $A$ associated to $\chi$ and hence similar to $\mu \calP$, i.e. $\calP^\al\sim \mu \calP$ for a unique map $\mu: A/G\lra \CC^\times$. We denote $\mu$ again by $[\calP,\al]$, see also \cite[Lem.~1.4, Lem.~2.3]{NSV20}. 

Given $\galh\leq \calG$, $G\lhd A$ and $\chi\in \Irr(G)$ we denote by $\chi^\galh$ the sum of all $\galh$-conjugates of $\chi$ and call $(A,G,\chi)_\cH$ an $\galh$--triple if $\chi^{\cH}$ is $A$-invariant, see \cite[\S 1]{NSV20}. Assume that $H\leq A$ with $A=GH$ and $\Cent_A(G)\leq H$. Let $\psi\in\Irr(M)$ such that $(H,M,\psi)_\galh$ is an $\galh$--triple. 
Assume $(A_\chi,G,\chi) \geq_c 
(H_\psi,M,\psi) $ given by $(\calP,\calP')$. 
If $(H\times \galh)_\chi=(H\times \galh)_\psi$ and $(\calP,\calP')$ can be chosen such that they satisfy 
\[  [\calP,\al](h)=[\calP',\al](h) \forevery h\in H_\psi, \]
then we write 
\[ 
(A,G,\phi)_\galh\geq_c(H,M,\psi)_\galh ,\]
see  \cite[Def.~1.5]{NSV20}.\end{defi}

Now the \textit {inductive McKay--Navarro (iMN) condition} for a given simple group $S$ and a prime $\ell$ is satisfied if for the universal covering group $G$ of $S$, any Sylow $\ell$-subgroup $P$ of $G$ and $\Delta=\Aut(G)_P$, there exists some $\Delta$-stable subgroup $M$ of $G$ with $\NNN_G(P)\leq M\lneq G$ and an 
$(\galh_\ell\times \Delta)$-equivariant bijection $\Omega: \Irrl(G)\lra \Irrl(M)$ such that 
\[ 
(G\rtimes \Delta_{\chi^{\galh_\ell}}, G,\chi)_\galhl\geq 
(M\rtimes \Delta_{\Omega(\chi)^{\galh_\ell}}, M,\Omega(\chi))_\galhl.\]

That is, the inductive McKay--Navarro conditions essentially require Condition \ref{cond:equivcondition}, together with the above character triple condition (which we sometimes call the ``extension condition").


\subsection{A criterion for the iMN condition}

As with the criterion in \cite[Thm.~2.12]{S12}, our criterion will require the use of extension maps, but now requiring compatibility with Galois automorphisms.

\begin{defi}
For $G\lhd A$ and subsets $\subG\subseteq \Irr(G)$ and $\mathfrak{A}\subseteq\Irr(A)$, we write $\Irr(A\mid\subG)$ for the irreducible characters of $A$ whose irreducible constituents on restriction to $G$ lie in $\subG$ and $\Irr(G\mid\mathfrak{A})$ for the irreducible constituents of characters in $\mathfrak{A}$ on restriction to $G$. Further, an \textit{extension map} \wrt $G\lhd A$ for $\subG$ is a map $\Lambda:\subG\lra \bigcup_{G\leq I \leq A} \Irr(I)$ such that for every $\chi\in\mathfrak{G}$, $\Lambda(\chi)$ is an extension of $\chi$ to $A_\chi$. If an extension map \wrt $G\lhd A$ for $\subG$ exists, we say that \textit{maximal extendibility holds \wrt $G\lhd A$ for $\subG$}, see \cite[4.1]{S09} and \cite[4.3]{S10a}.

Given an extension map $\Lambda$ and a subgroup $\galh\leq\gal$, we say that $\Lambda$ is \emph{$\galh$-equivariant} if $\Lambda(\la^\si)=\Lambda(\la)^\si$ for every $\si\in \cH$. 
\end{defi}




    We also note that a subset of linear characters in $\Irr(G)$, which is at the same time a group given by multiplication, acts on $\Irr(G)$ by multiplication.



We are now ready to introduce our criterion.
The following statement helps to construct bijections as required in the inductive McKay--Navarro condition in the case where $G$ is a group of Lie type. 
\begin{theorem}\label{crit_iGalMcK}
Let $G$ be a finite group, $\ell$ a prime with $\ell\mid |G|$, $Q$ a Sylow $\ell$--subgroup of $G$ and $M\lneq G$ a proper subgroup. Let $\galh\leq\gal$ be some subgroup.
Additionally, let $\subG\subseteq \Irr(G)$ and $\subM\subseteq \Irr(M)$.  Assume all of the following: 
\begin{asslist}
    \item There exists a group $\widecheck{G}$ with $G\lhd \widecheck{G}$ and a finite group $E$ such that $\widecheck{G}\rtimes E$ is defined, $\widecheck{G}/G$ is abelian, $\Cent_{\widecheck{G}\rtimes E}(G)=\Z(\widecheck{G})\Cent_{E}(G)$;  $G\lhd \widecheck{G}\rtimes E$; and $\subG$ and $\subM$ are $\galh\times \norm{\widecheck{G}}{M}$-stable.   
    \item The subgroup $M$ is $(\widecheck{G}\rtimes E)_Q$-stable and  $\NNN_G(Q)\leq M\lneq G$.
    \item \label{hauptprop_maxext} Maximal extendibility holds with respect to  $G\lhd \widecheck{G}$ and $M \lhd \widecheck M:=\norm{\widecheck{G}}{M}$ for $\subG$ and $\subM$, respectively.
    \item \label{glo-*}\label{1.10iv}
    For $\wh M:=\NNN_{GE}(M)$ there exist some $\wh M$-stable $\widecheck M$-transversals $\subG_0$ in $\subG$ and $\subM_0$ in $\subM$. Additionally there exist  $\wh M$-equivariant extension maps $\Phi_{glo}$ and $\Phi_{loc}$ \wrt $G\lhd GE$ for $\subG_0$ and \wrt $M\lhd \wh M$ for $\subM_0$, such that 
    \[ \Irr( \Cent_E(G) \mid  \Phi_{glo}(\chi)) =  \Irr( \Cent_E(G)\mid \Phi_{loc}(\psi) ) 
 \text{ for every }\chi\in\subG_0 \und \psi\in\subM_0.\]
 \item \label{assvi} 

    There exists a subgroup $B\leq (\widecheck{G} E \times \galh)$ with
    \[  \NNN_{\widecheck{G} E}(Q) B=\NNN_{\widecheck{G} E}(Q) \times \galh,\]
    that stabilizes $\subG_0$ and $\subM_0$.
    \item \label{crit_bij}
     For $\widecheck\subM:=\Irr(\widecheck M\mid\subM)$ and $\widecheck\subG:=\Irr(\widecheck{G}\mid \subG)$ there exists a $\Irr(\widecheck M/M)\rtimes(\wh M B )$-equivariant bijection $\widecheck \Omega:\widecheck\subG\lra \widecheck\subM$ with 
    $ \widecheck\Omega(\widecheck \subG\cap\Irr(\widecheck{G}\mid \nu))= \widecheck \subM\cap\Irr(\widecheck M\mid \nu)$ for every $\nu\in\Irr(\Z(\widecheck{G}))$.

    \end{asslist}


    \noindent Then there exists a $\wh M\widecheck M\times\galh$-equivariant bijection $\Omega:\subG\lra\subM$ such that 
    \begin{align}
    \label{geqcHct}
    ((\widecheck G E)_{\chi}, G, \chi)& \geq_c ((\widecheck{M}\wh M)_{\psi}, M, \psi)  \text{ for every }\chi\in  \subG \und \psi:=\Omega(\chi).
    \end{align}
    \end{theorem}




 \begin{proof}%[Proof of Theorem \ref{crit_iGalMcK}]

        As $\subG_0$ is an $E$-stable $\wc G$-transversal, we see that $(\wc G E)_\chi=\wc{G}_\chi E_\chi$ for every $\chi\in\subG_0$, see for example the  proof of   \cite[Lem.~2.4]{typeD1}. Analogously $(\wc M\wh M)_{\psi}=\wc{M}_\psi \wh M_\psi$ for every $\psi\in\subM_0$. Assumption \ref{assvi} implies 
        \[(\wc G E\times \calH)_\chi=\wc G_\chi
    	(GEB)_\chi\] for every $\chi\in\subG_0$, 
    	and	\begin{align}
    	\label{whM_psi}
    	(\wc M\wh M\times \calH)_{\psi}=\wc M_\psi \left (  \wh M B  \right )_\psi 
    	\end{align}
    	for every $\psi\in\subM_0$. (Note that $\wh M/M\cong E$.)

    Applying the considerations of the proof of \cite[2.12]{S12} we obtain an $\wc M \wh M$-equivariant bijection $\Omega:\subG\rightarrow \subM$, such that 
    \[((\wc G E)_{\chi}, G, \chi) \geq_c ((\wc G E)_{M,\Omega(\chi)}, M, \Omega(\chi))  \text{ for every $\chi\in\subG$}.\] 
        The bijection $\Omega$ is uniquely determined by the following properties: 
        $\Omega(\subG_0)=\subM_0$, $\Omega(\Irr(G\mid \wc \chi))=\Irr(M\mid \wc\Omega(\wc \chi))$ for every $\wc\chi\in \wc\subG$, and $\Omega$ is $\wc M$-equivariant. More precisely 
        for $\chi\in\subG_0$, $\wc\chi\in\Irr(\widecheck{G}\mid \chi)$ and $\wc\psi:=\wc\Omega(\wc\chi)$ the character $\Omega(\chi)$ is defined to be the one contained in $\Irr( M\mid \wc \psi)\cap \subM_0$. 
        Now note that the equivariance of $\wc \Omega$ implies $(\wc M \wh M)_{\chi}=(\wc M \wh M)_{\Omega(\chi)}$ by the construction for $\chi\in \subG_0$. The remaining values of $\Omega$ are chosen such that $\Omega$ is $\wc{M}$-equivariant. Since $\subM_0$ and $\subG_0$ are $\wh M$-stable, $\Omega$ is then $\wh M\wc M$-equivariant. 




        For the proof of the statement it is sufficient to show 
        \[  ((\widecheck G E)_{\chi}, G, \chi) \geq_c ((\widecheck{M}\wh M)_{\psi}, M, \psi) 
        \text{ for every $\chi\in\subG_0$},\] 
        where $\psi=\Omega(\chi)$. Hence we have to find projective representations $\calP$ and $\calP'$ of $(\widecheck G E)_{\chi}$ associated to $\chi$ and $(\wc M \wh M)_\psi$ associated to $\psi$, such that:
        \begin{itemize}
        \item the factor set $\al'$ of $\calP'$ is just the restriction of the factor set $\al$ of $\calP$, and
        \item for every $c\in \Cent_{(\widecheck G E)_{\chi}}(G)$ the matrices $\calP(c)$ and $\calP'(c)$ are scalar matrices to the same scalar.
        \end{itemize}

    A projective representation $\calP$ of $(\widecheck{G} E)_\chi$ associated to $\chi$ can be obtained the following way: 
    let $\wc \chi_0\in\Irr(\wc G_\chi\mid \chi)$ and $\mathcal D$ a representation of $G$ affording $\chi$. We obtain a projective representation $\calP$ of $(\wc G E)_\chi= \wc G_\chi E_\chi$
    associated to $\chi$ by 
    	$$\calP(gd)=\calP_1(g)\calP_2(d) \forevery g\in\wc G_\chi \und d\in GE_\chi,$$ 
    	where $\calP_1$ and $\calP_2$ are representations of $\wc G_\chi$ and $(GE)_\chi$ affording $\wc \chi_0$ and $\Phi_{glo}(\chi)$, respectively, extending $\mathcal D$. 

        Analogously, let $\calP'$ be the projective representation of $(\wh M\wc M)_\psi$ associated to $\psi$ defined using $\Phi_{loc}(\psi)$ and $\wc \psi_0\in \Irr(\wc M_\psi\mid \psi)$ where $\wc \psi_0^{\wc M}=\wc \Omega(\wc \chi_0^{\wc G})$. 

        By the proof of \cite[Thm.~2.12]{S12},
        the factor sets of $\calP$ and $\calP'$ are determined by the action of $\wh M_\psi$ on $\Irr(\wc G\mid \chi)$ and $\Irr(\wc M\mid \psi)$. Additionally for $z\in \Cent_{\wc G E}(G)=\Cent_E(G)\Z(\wc G)$ with $z=ez_0$ for $e\in \Cent_E(G)$ and $z_0\in \Z(\wc G)$ we see that $\calP(z)$ and $\calP'(z)$ are scalar matrices to $\wh \nu(e) \nu(z_0)$ where $\wh \nu\in \Irr(\Cent_E(G)\mid \Phi_{loc}(\chi))=\Irr(\Cent_E(G)\mid \Phi_{glo}(\psi))$ and $ \nu\in \Irr(Z(\wG)\mid \wc\chi_0)=\Irr(Z(\wG)\mid \wc\psi_0)$ and $z_0\in \Z(\wc G)$ with $z\in z_0 \Cent_E(G)$. This uses that $\Irr(\Cent_E(G)\mid \Phi_{loc}(\chi))=\Irr(\Cent_E(G)\mid \Phi_{glo}(\psi))$. Hence
        the pair $(\calP,\calP')$ has all required properties to give
    	\begin{align}
    	\label{geqcct}
    	((\wc G E)_{\chi}, G, \chi)& \geq_c ((\wc G E)_{M,\psi}, M, \Omega(\chi)).\qedhere 
    	\end{align}
         \end{proof}



\begin{cor}\label{crit_iGalMcK_full}
    Assume in the situation of \Cref{crit_iGalMcK} that the following additionally holds: \medskip 

    \begin{asslist}
    \item[(vii)] \label{12vib} 
    The group $B$ normalizes $\wh M$ and  
    \[ \restr[\Phi_{glo}(\chi), \al]|{\wh M_\chi}=[\Phi_{loc}(\psi), \al] \text{ for every }\al \in 	\left (  \wh M  B \right )_\psi \und 
 \chi\in\subG_0,\] 
 where  $\psi\in\subM_0$ with $\widecheck\Omega(\Irr(\widecheck G \mid \chi))=
    \widecheck\Omega(\Irr(\widecheck M \mid \psi))$.
    \end{asslist}

    \noindent Then the bijection $\Omega:\subG\lra\subM$ from \Cref{crit_iGalMcK} can be chosen to satisfy additionally 
    \begin{align}
    \label{geqcHct}
    ((\widecheck G E)_{\chi^{\calH}}, G, \chi)_\cH& \geq_c ((\widecheck{M}\wh M)_{\psi^\cH}, M, \psi)_{\cH}  \text{ for every }\chi\in  \subG \und \psi:=\Omega(\chi).
    \end{align}
\end{cor}

In particular, Theorem \ref{crit_iGalMcK} and Corollary \ref{crit_iGalMcK_full} yield Theorem \ref{thm:critintro} from the introduction.

\begin{proof}[Proof of Corollary \ref{crit_iGalMcK_full}] 
As before, it suffices to prove the relation \eqref{geqcHct} for $\chi\in\subG_0$. Let $\psi:=\Omega(\chi)$. We continue using the notation from before, in particular we continue considering the projective representations $\calP$ and $\calP'$ defined in the proof of \Cref{crit_iGalMcK}, associated to $\chi$ and $\psi$.

Next, we compare the relations.
Since the character triples associated with $\chi$ and $\psi$ already satisfy $\geq_c$, we have to ensure two additional equations to verify that the $\cH$ triples also satisfy $\geq_c$. First, we have to see
$(\wh M \wt M\times \cH)_{\chi}=(\wh M \wt M\times \cH)_{\psi}$. This follows from the $\wh M \wt M\times \cH$-equivariance of $\Omega$. Second, we have to see that a pair $(\calP, \calP')$ giving $\geq_c$ additionally satisfies
\[ [\calP,\al](h) = [\calP',\al](h)\]
for every $\al\in (\wc M\wh M B)_\psi$ and $h\in (\wh M \wt M)_\psi$. As $\chi\in \subG_0$ and $\subG_0$ is an $\wh M B$-stable $\wc M$-transversal, 
$(\wh M \wc M B)_\psi=(\wh M B)_\psi \wc M_\psi$ and it is sufficient to compute $[\calP,\al] = [\calP',\al]$ in the case where $\al\in(\wh M B)_\psi$. 

To ensure \cite[Def.~2.4(iv)]{NSV20}, we examine $\calP^{\al}$ and $(\calP')^{\al}$ for $\al\in (\wh M B)_\psi$. Hence, we compute $[\calP,\al]$ and $[\calP',\al]$. The projective representation $\calP$ was defined using the representation $\calP_1$ affording $\Phi_{glo}(\chi)$ and $\calP_2$ affording $\wc \chi_0$. By our assumption $B$ stabilizes $\wh M$ and hence $\calP_1^\al$ and $\calP_2^\al$ are well-defined. 
The representation $\calP_1^{\al}$ affords by definition $\Phi_{glo}(\chi)^{\al}=\Phi_{glo}(\chi) [\Phi_{glo}(\chi),\al]$. 
    	On the other hand $\calP_2^{\al}$ affords by definition $\wc \chi_0^{\al} =\wc\chi_0[\wc \chi_0,\al]$.
        This leads to $[\calP,\al](gd)=[\wc \chi_0,\al](g)[\Phi_{glo}(\chi),\al](d)$ for every $g\in\wc G_\chi$ and $d\in GE_\chi$.

    For computing $[\calP',\al]$, recall $\psi=\Omega(\chi)$ and $\calP'$ is the projective representation of $(\wh M\wc M)_\psi$ associated to $\psi$ defined using $\Phi_{loc}(\psi)$ and $\wc \psi_0\in \Irr(\wc M_\psi\mid \psi)$ with $\wc \psi_0^{\wc M}=\wc \Omega(\wc \chi_0^{\wc G})$. 

    As $\al$ stabilizes $\wh M_\psi$, we can consider $(\restr \calP'|{\wh M_\psi})^{\al}$. By the construction of $\calP'$, it is a representation affording $\Phi_{loc}(\psi)^{\al}=\Phi_{loc}(\psi)[\Phi_{loc}(\psi),\al]$, while   $(\calP'_{\wc M_\psi})^{\al}$ is a representation affording $\wc \psi_0^{\al} =\wc\psi_0 [\wc \psi_0,\al]$.
    As before, this leads to $[\calP',\al](gd)=[\wc \psi_0,\al](g)[\Phi_{loc}(\psi),\al](d)$ for every $g\in\wc M_\psi$ and $d\in \wh M_\psi$. 

    In case $\chi_0^{\wc G}$ is not an extension of $\chi$, the characters $\mu\in \Irr(\wc G/G)$ with $(\chi_0^{\wc G})^\al=\chi_0^{\wc G} \mu$ form a $\Lin(\wc G/\wc G_{\chi_0})$-coset in $\Irr(\wc G/G)$.  By abuse of notation, we write $[\chi_0^{\wc G},\al]$ for this set as well. For $g\in\wc G_{\chi_0}$, we observe that $[\wc \Omega(\chi_0^{\wc G}),\al](g)$ is nevertheless well-defined as well. 
    As $\wc \Omega$ is $\Irr(\wc G/G)\rtimes\spa{\al}$-equivariant by \ref{crit_bij}, we see $[\wc \Omega(\chi_0^{\wc G}),\al]= [\chi_0^{\wc G},\al]$. 
    Taking into account the definition of induced characters we see that $[\wc \psi_0^{\wc M},\al]$ is the set of extensions of $[\wc \psi_0,\al]$, and analogously $[\chi_0^{\wc G},\al]$ are the  extensions of $[\chi_0,\al]$. 
   Altogether we have
    \[ [\wc \psi_0,\al] (g)= [\wc \psi_0^{\wc M},\al](g)= [\wc \Omega(\chi_0^{\wc G}),\al](g)=     [\chi_0^{\wc G},\al](g)=[\chi_0,\al](g) . \] 
    Together with the assumption $[\Phi_{loc}(\psi),\al]=[\Phi_{glo}(\chi),\al]$ we obtain $[\calP,\al]=[\calP',\al] $. This proves the condition of \cite[Def.~2.4(iv)]{NSV20} for $\chi$ and $\psi$.
\end{proof}





\subsection{Changing the overgroup}

In the context of Theorem \ref{crit_iGalMcK} and Corollary \ref{crit_iGalMcK_full}, it will sometimes be useful to change between groups $\wc G$ containing $G$ and satisfying conditions (i)--(iii). For this, we introduce the following, sometimes called a ``butterfly" theorem.
Recall that for a central product $\wc X.Z$ with abelian group $Z$, the irreducible characters of $\wc X.Z$ are of the form $\chi.\mu$ with $\chi\in\Irr(\wc X)$ and $\mu\in \Irr(Z)$ with $\Irr(\wc X\cap Z\mid\chi)=\Irr(\wc X\cap Z\mid \mu)$, see also \cite[\S 12]{IMN}.

\begin{theorem}\label{thm:notbutterfly}
Let $\overline X$ be a finite group with normal subgroups $X$, $\wt X$, and $\wc X$ such that $X\subseteq \wt X\cap \wc X$ and $\overline X= \wc X Z=\wt X Z$ for some $Z\leq \Z(\ov X)$. 

Let $\ov M$ with $\ov X= X \ov M$ and $Z\Z(X)\leq \ov M$. Let $M:=\ov M\cap X$ and $A\leq \Aut(\ov X)_{\wt X, \wc X, \ov M,Z}\times \gal$ and $\subG\subseteq \Irr(X)$ be $A\ov M$-stable and $\subM\subseteq \Irr(M)$ be $A\ov M$-stable. 
Let $\wt M:=\ov M\cap \wt X$ and $\wc M:=\ov M\cap \wc X$.

Assume there exists some $(\Lin(\wt X/X)\rtimes A)$-equivariant bijection 
\[ \wt \Omega\colon \Irr(\wt X\mid \subG)\lra \Irr(\wt M\mid \subM)\]
with $\Irr(\Z(\wt X)\mid \chi)=\Irr(\Z(\wt X)\mid \wt \Omega(\chi)) $  for every $\chi\in \Irr(\wt X\mid\subG)$. Then there exists a
$(\Lin(\wc X/X)\rtimes A)$-equivariant bijection 
\[\wc \Omega\colon \Irr(\wc X\mid \subG)\lra \Irr(\wc M\mid \subM)\]
with 
$\Irr(\Z(\wc X)\mid \chi)=\Irr(\Z(\wc X)\mid \wc \Omega(\chi))$ 
for every $\chi\in \Irr(\wc X\mid\subG)$.
\end{theorem}
\begin{proof}
We see that $\Z(\wc X) Z=\Z(\ov X)=\Z(\wt X)Z$ and hence we can assume that $Z=\Z(\ov X)$ and hence $Z\cap \wc X=\Z(\wc X)$ and $Z\cap \wt X=\Z(\wt X)$.
Let $\chi\in \Irr(\wt X\mid \subG)$ and $\mu_0\in\Irr(Z\cap \wt X\mid \chi)$. Then \[\Irr(\ov X\mid \chi)=\{ \chi.\mu\mid \mu\in\Irr(Z\mid \mu_0)\}\] and hence $\chi.\mu\mapsto \wt\Omega(\chi).\mu$ defines a bijection between $\Irr(\ov X\mid \chi)$ and $\Irr(\ov M\mid \wt \Omega(\chi))$. 
In this way, we obtain a bijection 
\[ \ov \Omega: \Irr(\ov X\mid \subG)\lra \Irr(\ov M\mid \subM).\]
Since $\wt \Omega$ is $\Lin(\wt X/X)\rtimes A$-equivariant and $Z$ is $A$-stable, the bijection $\ov \Omega$ is also $\Lin(\ov X/X)\rtimes A$-equivariant. 

Since $\ov X= \wc X Z$, we see that every $\wc \chi\in\Irr( \wc X)$ is the restriction of an irreducible character $\ov \chi$ and 
\[ 
\{\ov \chi\in \Irr(\ov X)| \restr \ov \chi|{\wc X}= \wc \chi\}
\]
forms an $\Lin(\ov X/\wc X)$-orbit. 
Hence $\restr \ov \chi|{\wc X}\mapsto \restr \ov \Omega(\ov \chi)| {\wc M}$ defines a bijection $\wc \Omega$. 
By this construction $\wc \Omega$ is $\Lin(\wc X/X)\rtimes A$-equivariant and has the stated property. 
\end{proof}




\section{Constructing an equivariant bijection }\label{sec:equivbij}

The main goal of this section is to prove \Cref{thm:thmA}, which simplifies the search of the map in   Theorem \ref{crit_bij} to a question on local extension properties. The proof of \Cref{thm:thmA}
 will finally be completed  in Section \ref{sec:bijpfthmA}, where we 
revisit the construction of Malle \cite{Ma07}, in combination with the equivariance results from \cite{CS13, CS17A}. 





\subsection{$d$-Harish-Chandra theory}
Let $(\bH, F)$  be a finite reductive group. That is,  $\bH$ is a connected reductive group defined in characteristic $p$ and $F$ is a Steinberg morphism $F\colon \bH\rightarrow\bH$.  If $F$ is a Frobenius morphism defining $\bH$ over $\FF_q$, and $d$ is some positive integer prime to $p$, then a \emph{$d$-torus} (or $\Phi_d$-torus) is an $F$-stable torus whose order polynomial is a power of the $d$th cyclotomic polynomial $\Phi_d$. A \emph{$d$-split Levi subgroup} of $\bH$ is then a Levi subgroup that is the centralizer in $\bH$ of a $d$-torus of $\bH$. (See \cite[3.5.1]{GeckMalle}.)  In particular, a \emph{Sylow $d$-torus} is a $d$-torus of maximal possible rank, and a \emph{minimal $d$-split Levi subgroup} is the centralizer of a Sylow $d$-torus, as in \cite[3.5.6]{GeckMalle}. In the case that $F$ is not a Frobenius morphism, a modified definition \cite[3.5.3]{GeckMalle} can instead be used to define $d$-split Levi subgroups. 

For an $F$-stable Levi subgroup $\bL$ of $\bG$ we denote by $R_\bL^\bH$ and $\tw{\ast}R_\bL^\bH$ Lusztig's twisted induction and restriction, as in \cite[Def.~3.3.2]{GeckMalle}. (We remark that in the situation we are interested in, these will be independent of the corresponding parabolic subgroup containing $\bL$, so we suppress the notation.) 
A character $\la\in\Irr(\bL^F)$ is called \emph{$d$-cuspidal} if  $\tw{\ast}R_\bM^\bL(\lambda)=0$ for every proper $d$-split Levi subgroup $\bM$ of $\bL$. 

Now, we denote by $\UCh(\bH^F)\subseteq \irr(\bH^F)$ the set of unipotent characters of $\bH^F$. 
A \emph{unipotent $d$-cuspidal pair} is then a pair $(\bL, \lambda)$, where $\bL$ is a $d$-split Levi subgroup of $\bH$ and $\lambda\in\UCh(\bL^F)$ is $d$-cuspidal.
Given a unipotent $d$-cuspidal pair $(\bL, \la)$ for $(\bH, F)$, we let $\UCh(\HF \mid (\bL,\la) )$ denote the unipotent characters in the $d$-Harish-Chandra series of $(\bL, \lambda)$, as defined in \cite[3.5.24]{GeckMalle}. That is, $\chi\in \UCh(\HF \mid (\bL,\la) )$ if and only if $\langle \chi, R_\bL^\bH(\lambda)\rangle\neq 0$. We further let $W_\HF(\bL, \la)$ denote the relative Weyl group of $(\bL, \la)$, defined as the group $\Norm_{\bH^F}(\bL, \la)/\bL^F$.

We note that when $d=1$, the above notions correspond to the usual notions of split Levi subgroups, cuspidal characters, and ordinary Harish--Chandra theory.



\subsection{Galois automorphisms and relative Weyl groups}



First, we work to extend the equivariance results of \cite{CS13, CS17A} to the case of Galois automorphisms in $\galh_\ell$.



	\begin{theorem}\label{thm:Wdfixed}
		Let $(\bH,F)$ be a simple adjoint group, $F$ a Frobenius endomorphism  (not Steinberg)  and $\bS$ a Sylow $d$-torus of $(\bH,F)$ for some positive integer $d$ prime to $p$. Let $W_d$ denote the relative Weyl group $\NNN_\HF(\bS)/\Cent_\HF(\bS)$. Then every $\chi\in \Irr(W_d)$ is $\cH_{[d]}$-invariant. 


\end{theorem}



Before fully proving Theorem \ref{thm:Wdfixed}, we begin with the case of exceptional groups. Here, we will see that the conductor plays a useful role.

\begin{notation}
As usual, given a finite group $X$ and a character $\chi\in\irr(X)$, we let $\QQ(\chi)$ denote the field of values for $\chi$.	The \textbf{conductor}  $c(\chi)$ for $\chi$ is then the smallest integer $c$ such that $\QQ(\chi)\subseteq \QQ(e^{2\pi i/c})$.	
\end{notation}

	\begin{lem}\label{lem:exceptconductor}
	Keep the notation of Theorem \ref{thm:Wdfixed}.	If $\bH$ is of exceptional type or if $\HF=\tw 3 \tD_4(q)$, then for any $\chi\in\irr(W_d)$, the conductor $c(\chi)$ divides $\lcm(2,d)$. 
	\end{lem}


	\begin{proof}
According to \cite[Appendix 1]{BrMi}, the group $W_d$ is often a Coxeter group, in which case all characters of $W_d$ are  rational-valued by \cite[5.3.8]{geckpfeiffer}. Hence, it is sufficient to consider the remaining cases.

If $\Cent_\HF(\bS)$ is a torus, the groups $W_d$ can be seen from \cite[Appendix 1]{BrMi}. Using calculations in MAGMA, we see that in each of these cases, $c(\chi)$ divides $\lcm(2,d)$ for all $\chi\in\irr(W_d)$. 
If $\Cent_\HF(\bS)$ is not a torus, then the groups $W_d$ can be seen from  \cite[Table 3]{S09} and from there and some computer calculation as above we see again the statement. 
\end{proof}

\begin{proof}[Proof of Theorem \ref{thm:Wdfixed}]
Let $d':=\lcm(2,d)$.	First, we observe that characters of a cyclic group of order $d'$ are $\cH_{[d]}$-invariant (see Lemma \ref{lem:numtheory}).  
	It is well known that characters of the symmetric group $\Sym_a$ are rational. From this, we see that the characters of the wreath product $\Cy_{d''}\wr \Sym_a$ are $\cH_{[d]}$-invariant for $d''$ dividing $d'$, by the construction of the characters of those groups given for example in \cite[Thm.~4.3.34]{jameskerber}. 

Now, if $\Cent_\HF(\bS)$ is a torus, the description of the groups $W_d$ are found in \cite[Appendix~1]{BrMi}. (See also \cite[Ex.~3.5.14, 3.5.15]{GeckMalle}.)
	In this case, the group $W_d$ coincides with the centralizer of a $d$-regular element $w\phi$ of the Weyl group $W$ of $\bH$. The tables list the isomorphism types of $\Cent_W(w\phi)$. 
	According to loc. cit, the group $W_d$ is a wreath product $\Cy_{d''}\wr \Sym_a$ with $d''\mid d'$ as discussed above, whenever $\bH$ is of type $\tA$, $\tB$ or $\tC$. 
	(Note that the authors denote by  $B^{(d'')}_a$ the group $\Cy_{d''}
\wr \Sym_a$.) By the above argument, we see the statement holds in these cases.

Whenever $\bH$ is of type $\tD$ and $W_d$ is not  a wreath product of the structure as mentioned above, we have $W_d$ is a subgroup of $\Cy_{d''}\wr \Sym_a $ of index $2$ given by the elements $(c_1,...,c_a)\si$, where each $c_i\in \Cy_{d''}$, $\si\in\Sym_a$, and  $\prod c_i=1$. In those cases, $d''$ divides  $d'=\lcm(2,d) $. 
Mimicking the construction of characters of wreath products, one can parametrize the characters of such a group as well and sees that its irreducible characters are $\cH_{[d]}$-invariant. 

We must now consider the case where $\Cent_\HF(\bS)$ is not a torus. In the following, we write
$W_d(\bH_1^F)$ for the quotient $\NNN_{\bH_1^F}(\bS_1)/\Cent_{\bH_1^F}(\bS_1)$, where
$(\bH_1,F)$ is a reductive group and
$\bS_1$ denotes a Sylow $d$-torus of $(\bH_1,F)$.
From the descriptions in \cite[Ex.~3.5.14, 3.5.15]{GeckMalle}, we see that the given $W_d$ also occurs as $W_d(\bH_1^F)$ for some reductive group $(\bH_1,F)$.
We have seen above that the characters of $W_d(\bH_1^F)$   are $\cH_{[d]}$-invariant and this proves our statement in all cases where $\bH$ is of classical type and $\HF\not \eq \tw 3 \tD_4(q)$. 
 The remaining cases finally follow from Lemma \ref{lem:exceptconductor}.
\end{proof}

\begin{cor}\label{cor:relweylfixed}
Let $(\bL,\la)$ be a unipotent $d$-cuspidal  pair of a finite reductive group $(\bH,F)$, where $F$ is a Frobenius endomorphism and $\bH$ is simple. Then every $\chi\in\Irr(W_\HF(\bL, \lambda))$ is $\galh_{[d]}$-invariant.
\end{cor}
\begin{proof}
From Theorem \ref{thm:Wdfixed}, the characters of $W_d$ are $\cH_{[d]}$-fixed. Then if $W_d$ is cyclic or $W_\HF(\bL,\la)=W_d(\bH_1^F)$ for some $\bH_1$, we know that  the characters in $\Irr(W_\HF(\bL,\la))$ are $\cH_{[d]}$-invariant. This then covers the cases that $\bL$ is a torus or $\bH$ is of classical type. (The latter can be seen from the description of $\bL$ in \cite[Ex.~3.5.14, 3.5.15]{GeckMalle} and the discussion in \cite[Ex.~3.5.29]{GeckMalle}; see also \cite[pp.~48--51]{BMM}.) If instead $\bH$ is of exceptional type, $W_d$ is noncyclic, and $\bL$ is not a torus, then the groups $W_\HF(\bL, \lambda)$ not covered in Lemma \ref{lem:exceptconductor} are found in \cite[Table 1]{BMM}, or by the Ennola duality \cite[Thm.~3.3]{BMM}, and we see that the conductors still divide $\lcm(2,d)$, using the same type of computer calculations as in Lemma \ref{lem:exceptconductor}.
\end{proof}

    \subsection{$d$-Harish-Chandra Theory and Unipotent Characters}\label{sec:Ibijection}
We next study certain unipotent characters of a finite reductive group $(\bH, F)$, which in our situation will be strongly related to those of degree prime to $\ell$.

\begin{defi}
Let $d$ be a positive integer. We write	$\UCh_{[\Phi_d]'}(\HF)$ for the subset of $\UCh(\HF)$ comprised of those unipotent characters whose generic polynomial, defined as in \cite[(1.31)]{BMM}, is not divisible by $\Phi_d$. 

	Let $(\bL,\la)$ be a unipotent $d$-cuspidal  pair of $(\bH,F)$ with $\la\in\UCh_{[\Phi_d]'}(\bL^F)$. Then let
	$\Irr_{[d]'}(W_\HF(\bL,\la))$ be the set of characters $\eta\in \Irr(W_\HF(\bL,\la))$, such that the polynomial degree $\operatorname{D}_\eta$ associated to $\eta$ as in \cite[Thm.~4.2]{Ma07} 
	is not divisible by $\Phi_d$.

	 Let $\UCh_{[\Phi_d]'}(\HF \mid (\bL,\la) )=\UCh(\HF \mid (\bL,\la) )\cap \UCh_{[\Phi_d]'}(\HF).$
	\end{defi}

In \cite[Thm.~3.2]{BMM}, it is shown that there is a bijection 
$\mathrm I_{(\bL,\la)}^{(\bH)}: \UCh(\HF \mid (\bL,\la) )\lra \Irr(W_\HF(\bL,\la)).$
By \cite[Thm.~3.4]{CS13}, this bijection is further $\Aut(\HF)_{(\bL, \lambda)}$-equivariant. We next extend this to consider the action of $\galh_\ell$. We let  $E(\bH^F)$ denote a suitable group of graph-field automorphisms for $\bH^F$, as constructed in \cite[2.C]{CS24}.

\begin{prop}\label{prop:HCgalequiv}
	Keep the situation of Theorem \ref{thm:Wdfixed}, where now $d:=d_\ell(q)$ for some odd prime $\ell\neq p$.	Let $(\bL,\la)$ be 
a unipotent $d$-cuspidal pair such that $\bL:=\Cent_{\bH}(\bS)$ is the centralizer of a Sylow $\Phi_d$-torus. Then the bijection $\mathrm I_{(\bL,\la)}^{(\bH)}$ above restricts to an $(\HF\rtimes E(\HF))_{(\bL,\la)}\times \galh_\ell$-equivariant bijection
	  \[ \mathrm I_{(\bL,\la)}^{(\bH)}: \UCh_{[\Phi_d]'}(\HF \mid (\bL,\la) )\lra \Irr_{[d]'}(W_\HF(\bL,\la)).\]
In fact, $\galh_\ell$ acts trivially on both sets, as well as on $\lambda$.
\end{prop}


\begin{proof}%[Proof of Proposition \ref{prop:HCgalequiv}]
Note that by the degree formula in \cite[Thm.~4.2]{Ma07}, the bijection $\mathrm I_{(\bL,\la)}^{(\bH)}$ from \cite{BMM} indeed induces a bijection on the given subsets. As noted above, it is $(\HF\rtimes E(\HF))_{(\bL,\la)}$-equivariant by \cite[Thm.~3.4]{CS13}.
From Corollary \ref{cor:relweylfixed}, we see that each character of $\irr(W_\HF(\bL, \lambda))$ is $\galh_{[d]}$-invariant, and by Lemma \ref{H}, recall that $\cH_\ell\subseteq \cH_{[d]}$.  It then suffices to show that each member of $\UCh_{[\Phi_d']}(\bH^F)$ is $\galh_\ell$-invariant. (Note that when applied to the components of the adjoint version of $\bL$, this will also yield $\lambda$ is $\galh_\ell$-invariant.)

Let $\chi$ be a unipotent character of $\bH^F$ lying in a Harish-Chandra series $\cE(\bH^F, (\bM, \psi))$ with $\psi$ a cuspidal unipotent character of $\bM^F$, where $\bM$ is an $F$-stable Levi subgroup of $\bH$. From \cite[Prop.~5.6]{geck03}, we have $\QQ(\chi)=\QQ(\psi)$, with two exceptions $\phi_{512, 11}, \phi_{512,12}$ in $\tE_7(q)$ and four exceptions from the $\phi_{4096,\ast}$ family in $\tE_8(q)$.  (Here we use the notation for unipotent characters as in \cite[Ch.~13]{Carter}.) In these exceptional cases, we instead have $\QQ(\chi)=\QQ(\sqrt{q})$. Now, a character $\chi$ occurs in $\UCh_{[\Phi_d]'}(\HF)$ only for integers $d$ that do not appear in the degree polynomials. We remark that, from the list of degree polynomials given in \cite[Sec.~13.9]{Carter}, we see that the degrees of these exceptions are divisible by $\Phi_m$ for each $m$ such that $m$ is even and $\Phi_m$ divides the order polynomial of $\HF$. That is, these exceptions occur in $\UCh_{[\Phi_d]'}(\HF)$ only for odd $d$. Hence by Lemma \ref{sqrt}, we see that these characters are fixed by $\galh_\ell$.

Further,  \cite[Table 1]{geck03} details which cuspidal unipotent characters in $\UCh_{[\Phi_d]'}(\HF)$ have non-rational values.  We summarize these in Table \ref{tab:irrationalcuspidal}. (There, we use $\zeta_n$ to denote an $n$th root of unity and we use the notation of \cite{Carter} for the unipotent characters.)

In all of these cases aside from those of $\tE_7(q)$, we see that the characters are fixed by $\galh_{[d]}$ by definition. In the case of the cuspidal characters of $\tE_7(q)$ with field of values $\QQ(\sqrt{-q})$ when $d\in\{2, 6,10,14,18\}$,  we have $\sqrt{-q}$ is fixed by $\galh_\ell$  by Lemma \ref{2msqrt}. Hence we are left to consider the case $\bM\neq \bH$.

Now suppose $\psi$ is a cuspidal unipotent character as in Table \ref{tab:irrationalcuspidal} of some proper split Levi subgroup $\bM^F$ of $\bH^F$ and such that there is some $\chi\in\cE(\bH^F, (\bM, \psi))\cap \UCh_{[\Phi_d']}(\bH^F)$.  Then we see that $\psi$ is one of the $\tE_6$ or $\tE_7$ characters in the table, and $\bH$ is of type $\tE_7$ or $\tE_8$ in the first case and of type $\tE_8$ in the latter. Further, in the cases that $\psi$ is  $E_6[\theta]$ or $E_6[\theta^2]$, we see from the list of character degrees in \cite[Sec.~13.9]{Carter} that we have $\chi$ is in $\UCh_{[\Phi_d']}(\bH^F)$ only for values of $d$ divisible by $3$. Hence $\QQ(\chi)=\QQ(\psi)=\QQ(\zeta_3)$ is still in the fixed field for $\galh_\ell$. Similarly, in the case $\psi$ is $E_7[\xi]$ or $E_7[-\xi]$, $\chi\in\UCh_{[\Phi_d']}(\bH^F)$ only for values of $d$ of the form $2m$ with $m$ odd, and hence $\QQ(\chi)=\QQ(\psi)=\QQ(\sqrt{-q})$ is in the fixed field of $\galh_\ell$ by Lemma \ref{2msqrt}, completing the proof.
\end{proof}

