	\section{Results of scattering theory for focusing CNLS}
%\numberwithin{equation}{section}
We briefly review the IST \cite{manakov1974theory,novikov1984theory} for the CNLS equation.
The focusing CNLS equation reads in the vector form:
\begin{equation}\label{CNLS}
  \ii\mathbf{q}_{t}+\frac{1}{2}\mathbf{q}_{xx}+\mathbf{q}\mathbf{q}^{\dagger}\mathbf{q}=0,
  \quad\mathbf{q}(x,t)=\begin{bmatrix}
    q_{1}(x,t),q_{2}(x,t)
  \end{bmatrix},
\end{equation}
\noindent
where $q_{1}(x,t)$ and $q_{2}(x,t)$ are the wave envelopes, which were first derived by Manakov in 1974 to describe electrical propagation 
\cite{manakov1974theory}, and are therefore known as the Manakov model. 
Subsequently, the focusing CNLS equation \eqref{CNLS} has garnered significant attention 
across various fields, ranging from Bose-Einstein condensates (BEC) \cite{busch2001dark} 
to optical fibers \cite{agrawal2000nonlinear} and biophysics \cite{scott1984launching}. 
From a mathematical perspective, the CNLS equation \eqref{CNLS} is an integrable equation 
that admits the following Lax pair:
\begin{equation}\label{lax-pair-Phi}
  \begin{array}{ll}
    \left(\partial_{x}-\mathcal{L}\right) \mathbf{\mathbf{\mathbf{\Phi}}}=0, 
    & \mathcal{L}=\ii\left(-\lambda\mathbf{\Lambda}_3+\mathbf{Q}\right), \\
    \left(\ii \partial_{t}-\mathcal{B}\right) \mathbf{\mathbf{\Phi}}=0, & \mathcal{B}=\ii\lambda\left(-\lambda\mathbf{\Lambda}_3+\mathbf{Q}\right)
    +\frac{1}{2}\left(\mathbf{Q}_{x}+\ii\mathbf{Q}^{2}\right)\mathbf{\Lambda}_3,
  \end{array}
\end{equation}
\noindent 
where $\lambda \in \mathbb{C}$ is the spectral parameter and
\begin{equation*}
  \mathbf{\Lambda}_3=\mathrm{diag}\left(1,-1,-1\right)\quad,\quad 
  \mathbf{Q}=\begin{pmatrix}0&&\mathbf{q}\\\mathbf{q}^\dagger&&0\end{pmatrix}.
\end{equation*}
The boundary conditions are given by
\begin{equation*}
  \mathbf{q}(x,t)\to0,\quad\mathbf{q}_{x}(x,t)\to0,\quad\mathrm{as}\quad x\to\pm\infty.
\end{equation*}
\noindent
We consider the Jost solutions of spectral problem,
\begin{equation*}
  \mathbf{\mathbf{\Phi}}^{\pm}(\lambda;x,t)\to\mathrm{e}^{-\mathrm{i}
  \lambda(x+\lambda t)
  \mathbf{\Lambda}_{3}},
  \quad x\to\pm\infty.
\end{equation*}
\noindent
If the function $\mathbf{q}(x,t)$ satisfies the focusing CNLS equation, which is equivalent
to the compatibility condition $\mathbf{\Phi}_{xt}(\lambda;x,t)=\mathbf{\Phi}_{tx}(\lambda;x,t)$,
then the matrix function $\mathbf{\Phi}(\lambda;x,t)$ exists and can be determined by the curve integral.
Inserting the ansatz
\begin{equation*}
  \mathbf{\Phi}^{\pm}(\lambda;x,t)=\pmb{\mu}^{\pm}(\lambda;x,t)\ee^{-\ii\lambda(x+\lambda t)\mathbf{\Lambda}_{3}}
\end{equation*}
into the spectral problem, we will obtain the Jost solution
\begin{equation}\label{lax-pair-mu}
  \begin{aligned}
    &\pmb{\mu}^{\pm}_{x}=-\ii\lambda\left[\mathbf{\Lambda}_{3},\pmb{\mu}^{\pm}
    \right]+\ii\mathbf{Q}\pmb{\mu}^{\pm},\,\begin{bmatrix}
      {\bf A,B}
    \end{bmatrix}={\bf AB-BA},\\
    &\pmb{\mu}^{\pm}_{t}=-\ii\lambda^{2}\left[\mathbf{\Lambda}_{3},\pmb{\mu}^{\pm}\right]+
    \left[\ii\lambda \mathbf{Q}+\frac{1}{2}(\mathbf{Q}_{x}+\ii\mathbf{Q}^2)\mathbf{\Lambda}_{3}\right]
    \pmb{\mu}^{\pm},
  \end{aligned}
\end{equation}

\noindent
with the normalization condition
\begin{equation*}
  \pmb{\mu}^{\pm}(\lambda;x,t)\to\mathbb{I}_{3},\quad x\to\pm\infty.
\end{equation*}
These solutions can be expressed as the Volterra type integrals
\begin{multline*}
  \pmb{\mu}^{\pm}(\lambda;x,t)
    =\mathbb{I}+\mathrm{i}\int_{(\pm\infty,t)}^{(x,t)}\mathrm{e}^{-\mathrm{i}\lambda(x-y)\mathbf{\Lambda}_{3}}
    \mathbf{Q}(y,s){\pmb{\mu}}^{\pm}(\lambda;y,s)\ee^{\mathrm{i}\lambda(x-y)\mathbf{\Lambda}_{3}}\mathrm{d}y  \\
    +\int_{(\pm\infty,0)}^{(\pm\infty,t)}\ee^{-\ii\lambda^{2}(t-s)\mathbf{\Lambda}_{3}}
    \left[\mathrm{i}\lambda \mathbf{Q}(y,s)+\frac{1}{2}\left(\mathbf{Q}_{y}(y,s)+
    \mathrm{i}\mathbf{Q}^{2}(y,s)\right)\mathbf{\Lambda}_{3}\right]{\pmb{\mu}}^{\pm}(\lambda;y,s)
    \ee^{\mathrm{i}\lambda^{2}(t-s)\mathbf{\Lambda}_{3}}\mathrm{d}s.
\end{multline*}
\noindent
From the conditions $\mathbf{q}(x,t)\to 0$ and $\mathbf{q}_{x}(x,t)\to 0$ as $x\to\pm\infty$
for arbitrary time $t$ ,the above curve integral can be reduced to
\begin{equation*}
  \pmb{\mu}^{\pm}(\lambda;x,t)
  =\mathbb{I}_{3}+\mathrm{i}\int_{\pm\infty}^{x}\mathrm{e}^{-\mathrm{i}\lambda(x-y)\mathbf{\Lambda}_{3}}
  \mathbf{Q}(y,t){\pmb{\mu}}^{\pm}(\lambda;y,t)\mathbf{e}^{\mathrm{i}\lambda(x-y)\mathbf{\Lambda}_{3}}\mathrm{d}y.
\end{equation*}
Define the following matrices
\begin{equation*}
  \pmb{\mu}_{+}(\lambda;x,t)=(\pmb{\mu}^{-}_{1},\pmb{\mu}^{+}_{2}),
  \quad\pmb{\mu}_{-}(\lambda;x,t)=(\pmb{\mu}^{+}_{1},\pmb{\mu}^{-}_{2}),
\end{equation*}
where $\pmb{\mu}_{1}$ denotes the first column of $\pmb{\mu}$ 
and $\pmb{\mu}_{2}$ denotes the last two columns of $\pmb{\mu}$.
\noindent
Through the analytic properties of Volterra integral equations, we obtain that the matrix 
$\pmb{\mu}_{+}(\lambda;x,t)$ is analytic in the upper half $\lambda$-plane and the matrix 
$\pmb{\mu}_{-}(\lambda;x,t)$ is analytic in the lower half $\lambda$-plane under the condition that 
$\{q_{1}(x,t),q_{2}(x,t)\}\in H^{1,1}(\mathbb{R})$ for the fixed time $t$.
Also, if $\mathbf{\Phi}(\lambda;x,t)$ is the solution of equation \eqref{lax-pair-Phi}, then 
$[\mathbf{\Phi}^\dagger(\lambda^*;x,t)]^{-1}$ can also solve equation \eqref{lax-pair-Phi}. Hence we have the following 
symmetry of the Jost solutions
\begin{equation}\label{symmetry-Phi-CNLS}
  \mathbf{\Phi}(\lambda;x,t)\mathbf{\Phi}^\dagger(\lambda^*;x,t)=\mathbb{I}_{3}.
\end{equation}
Define the scattering matrix
\begin{equation}\label{def-scattering-matrix}
  \mathbf{\Phi}^-(\lambda;x,t)=\mathbf{\Phi}^+(\lambda;x,t)
  \mathbf{S}(\lambda;t),\quad\lambda\in\mathbb{R}
\end{equation}
\noindent
where
\begin{equation*}
  \mathbf{S}(\lambda;t)=
  \begin{pmatrix}\bar{a}(\lambda)&&\mathbf{b}(\lambda)\\
    \overline{\mathbf{b}}(\lambda)&&\mathbf{a}(\lambda)\end{pmatrix},\quad \\ 
    \det(\mathbf{S}(\lambda;t))=1.
\end{equation*}
\noindent
Then we can also obain the symmetric relation of the scattering matrix
\begin{equation*}
  \mathbf{S}(\lambda;t)\mathbf{S}^\dagger(\lambda^*;t)=\mathbb{I}_{3},
\end{equation*}
\noindent
which implies that
\begin{equation*}
  \bar{a}(\lambda)=\det(\mathbf{a}^\dagger(\lambda^*)),\quad 
  \overline{\mathbf{b}}(\lambda)=-{\rm adj} (\mathbf{a}^\dagger(\lambda^*))\mathbf{b}^\dagger(\lambda^*),
\end{equation*}
\noindent
where ${\rm adj}(\mathbf{A})$ denotes the adjoint matrix of $\mathbf{A}$ in the context of linear algebra.

The evaluation of equation \eqref{def-scattering-matrix} at $t=0$ show that
\begin{equation*}
  \mathbf{\mathbf{S}}(\lambda;t)=\lim_{x\to+\infty}\ee^{\ii\lambda 
  x\hat{\mathbf{\Lambda}}_{3}}\pmb{\mu}_{-}(\lambda;x,t),\quad 
  \ee^{\hat{\bf B}}{\bf A}=\ee^{\bf B}{\bf A}\ee^{\bf -B},
\end{equation*}
\noindent
then we have
\begin{equation*}
  \mathbf{a}(\lambda)
  =\mathbb{I}_{2}+\mathrm{i}\int_{-\infty}^{+\infty}
  q^{\dagger}(y,0){\pmb{\mu}}^{-}_{12}(y,0)\mathrm{d}y.
\end{equation*}
Therefore, we can know that $\mathbf{a}(\lambda)$ is analytic in the lower half plane $\mathbb{C}_{-}$.
Moreover, we have $\det(\pmb{\mu}_{-})=\det(\mathbf{a}(\lambda))$. Assume the form 
$\det(\mathbf{a}(\lambda))=\prod_{i=1}^{N}\frac{\lambda-\lambda_{i}^{*}}{\lambda-\lambda_{i}}a_{0}(\lambda)$, 
where $a_{0}(\lambda)$ has no zeros and $\lambda_{i}\in\mathbb{C}_{+}$. 
So define  
$\mathcal{Z}=\left\{\lambda_i|\bar{a}(\lambda_{i})=\det(\mathbf{a}^\dagger(\lambda_i^*))=0\right\}_{i=1}^{N}$. 
Specifically, a norming constant matrix 
$\mathbf{h}_{i}=\overline{\mathbf{b}}(\lambda_i)$ exists such that:
\begin{equation*}
  \mathbf{\Phi}^-_1(\lambda_i;x,t)=\mathbf{\Phi}^+_1(\lambda_i;x,t) 
  \bar{a}(\lambda_i)+\mathbf{\Phi}^+_2(\lambda_i;x,t)
  \overline{\mathbf{b}}(\lambda_i)=\mathbf{\Phi}^+_2(\lambda_i;x,t)\mathbf{h}_i,
\end{equation*}
where $\mathbf{\Phi}^\pm_1$ denotes the first column of $\mathbf{\Phi}^\pm$ 
and $\mathbf{\Phi}^\pm_{2}$ denotes the last two columns of $\mathbf{\Phi}^\pm$.
The symmetry of scattering matrix $\mathbf{S}(\lambda)$ implies that 
\begin{equation*}
  \begin{aligned}
    \mathbf{\Phi}^-_2(\lambda_i^*;x,t){\rm adj}(\mathbf{a}(\lambda_i^*))
  &=\left(\mathbf{\Phi}^+_1(\lambda_i^*;x,t)\mathbf{b}(\lambda_i^*)+
  \mathbf{\Phi}^+_2(\lambda_i^*;x,t)\mathbf{a}(\lambda_i^*)\right)
  {\rm adj}(\mathbf{a}(\lambda_i^*))\\
  &=\mathbf{\Phi}^+_1(\lambda_i^*;x,t)\mathbf{b}(\lambda_i^*)
  {\rm adj}(\mathbf{a}(\lambda_i^*))+
  \mathbf{\Phi}^+_2(\lambda_i^*;x,t){\rm det}(\mathbf{a}(\lambda_i^*))\\
  &=-\mathbf{\Phi}^+_1(\lambda_i^*;x,t)\overline{\mathbf{b}}(\lambda_i)^\dagger
  =-\mathbf{\Phi}^+_1(\lambda_i^*;x,t)\mathbf{h}_i^\dagger.
  \end{aligned}
\end{equation*}


