\begin{assumption}\label{assumption-q0}
  The initial data $\mathbf{q}_0(x)=\left(q_{1}(x,0),q_{2}(x,0)\right)$ of the Cauchy problem \eqref{CNLS} for CNLS equation 
  generates generic 
  scattering data in the sense that:
  \begin{itemize}
    \item[(a)] There are no spectral singularities, i.e., there exists a constant $c>0$ such that 
    $|\det(\mathbf{a}^\dagger(\lambda^*))|>c$ for any $\lambda\in\mathbb{R}$.
    \item[(b)] The discrete spectrum is simple, i.e., every zero of $\det(\mathbf{a}^\dagger(\lambda^*))$ in 
    $\mathbb{C}_+$ is simple.
    \item[(c)] $\{q_{1}(x,0),q_{2}(x,0)\}\in H^{1,1}(\mathbb{R})$.
  \end{itemize}
\end{assumption}
By Proposition 3.1 in \cite{Liu_2019}, 
we can deduce an important fact that $\mathbf{R}(\lambda)\in H^{1,1}(\mathbb{R})$.

The inverse scattering theory seeks to recover the solution of equation \eqref{CNLS} through the RHP. This is done as follows: form the Jost function 
$\mathbf{\Phi}^\pm(\lambda;x,t)=\pmb{\mu}^\pm(\lambda;x,t)\ee^{-\ii\lambda(x+\lambda t)\mathbf{\Lambda}_3}$ one constructs 
the function
\begin{equation}\label{def-M}
  \hat{\M}(\lambda)=\hat{\M}(\lambda;x,t):=
  \begin{cases}
    \pmb{\mu}_+\begin{pmatrix}
      \frac{1}{\mathrm{det}(\mathbf{a}^\dagger(\lambda^*))}&0\\0&\mathbb{I}_2
    \end{pmatrix}
    ,&\lambda\in\mathbb{C}_+,\\
    \pmb{\mu}_-\begin{pmatrix}
      1&0\\0&\mathbf{a}^{-1}(\lambda)
    \end{pmatrix}
    ,&\lambda\in\mathbb{C}_-.
  \end{cases}
\end{equation}


For data $\mathbf{q}_0$ satisfying Assumption 1, the matrix $\hat{\M}$ defined by equation \eqref{def-M} is the solution 
of the following RHP.

\begin{rhp}\label{initial-rhp-with-pole}
  Find an analytic function $\hat{\M}$: 
  $\mathbb{C}\setminus(\mathbb{R}\cup\mathcal{Z}\cup\mathcal{Z}^{*})\rightarrow SL_{2}(\mathbb{C})$ 
  with the following properties
  \begin{itemize}
    \item[1.] $\hat{\M}(\lambda)=\mathbb{I}_{3}+\mathcal{O}\left(\lambda^{-1}\right)$ as $\lambda\rightarrow\infty.$
    \item[2.] For each $\lambda\in\mathbb{R}$ (with $\mathbb{R}$ oriented left-to-right),
    $\hat{\M}$ takes continuous boundary values $\hat{\M}_{\pm}(\lambda)$ which satisfy 
    the jump relation: 
    $\hat{\M}_+(\lambda)=\hat{\M}_-(\lambda)\hat{\V}(\lambda)$, where
    \begin{equation}\label{initial-Jump}
     \hat{\V}(\lambda)=
     \begin{pmatrix}
       1+\hat{\mathbf{R}}(\lambda)\hat{\mathbf{R}}^\dagger(\lambda)&-\hat{\mathbf{R}}(\lambda)\ee^{-2\ii t\theta(\lambda)}\\
       -\hat{\mathbf{R}}^\dagger(\lambda)\ee^{2\ii t\theta(\lambda)}&\mathbb{I}_2
     \end{pmatrix},
    \end{equation}
    and
    \begin{equation}\label{def-R}
     \theta=\theta(\lambda;x,t)=\lambda^{2}-2\xi 
     \lambda=(\lambda-\xi)^{2}-\xi^{2},\quad\xi=-x/(2t), 
     \quad\hat{\mathbf{R}}(\lambda)=\mathbf{b}(\lambda)\mathbf{a}(\lambda)^{-1}.
    \end{equation}
    \item[3.] $\hat{\M}(\lambda)$ has simple poles at each $\lambda_i\in\mathcal{Z}$ and $\lambda_i^*\in\mathcal{Z}^*$ 
    at which
    \begin{equation*}
      \begin{array}{ll}
        & \mathop{\rm Res}\limits_{\lambda=\lambda_i}\hat{\M}=
        \mathop{\lim}\limits_{\lambda\to\lambda_i}\hat{\M}
        \begin{pmatrix}0&0\\-\mathbf{c}_i\ee^{2\ii t\theta}&0\end{pmatrix},\\
        & \mathop{\rm Res}\limits_{\lambda=\lambda_i^*}\hat{\M}=
        \mathop{\lim}\limits_{\lambda\to\lambda_i^*}\hat{\M}
        \begin{pmatrix}0&\mathbf{c}^\dagger_i\ee^{-2\ii t\theta}\\0&0\end{pmatrix},
      \end{array}
    \end{equation*}
    where $\mathbf{c}_i=-\frac{\mathbf{h}_i}{k_i}$ and 
    $k_i=\left.\frac{\dd\left({\rm det}(\mathbf{a}^\dagger(\lambda^*))\right)}{\dd \lambda}\right|_{\lambda=\lambda_i}$.
  \end{itemize}	
\end{rhp}
It is a simple consequence of Liouville theorem that if a solution exists, 
it is unique. The existence of solutions of RHP \ref{initial-rhp-with-pole} for all $(x,t)\in\mathbb{R}^2$ 
follows by means of vanishing lemma argument \cite{zhouscatteringtransforms1989} after replacing the poles by 
jumps along small circular contours in a standard way. Expanding this solution 
as $\lambda\rightarrow\infty$, $\hat{\M}=\mathbb{I}_3+\lambda^{-1}\hat{\M}_1+\oo(\lambda^{-2})$ and 
inserting this into equation \eqref{lax-pair-mu} one finds that 
\begin{equation}\label{recover-CNLS}
  \mathbf{q}(x,t)=\lim_{\lambda\rightarrow\infty} (2\lambda \hat{\M}(\lambda;x,t))_{12}.
\end{equation}



\section{The Long-Time Asymptotics}

\noindent
In this section, we make the following basic notations:
\begin{itemize}
  \item[1.] For any matrix $\M$ define $|\M|=(tr\M^\dagger \M)^{\frac{1}{2}}$ and for any matrix 
  function $\mathbf{A}(\cdot)$ define 
  $\|\mathbf{A}(\cdot)\|_p=\| \left|\mathbf{A}(\cdot) \right|\|_p,
  \|\mathbf{A}(\cdot)\|_{H^{1,1}(\mathbb{R})}
  =\|\left|\mathbf{A}(\cdot)\right|\|_{H^{1,1}(\mathbb{R})}$.
  \item[2.] For two quantities A and B define $A\lesssim B$ if there exists a constant $C>0$ such that 
  $|A|\leq CB$.
  \item[3.] For any oriented contour $\sum$, we say that the left side is $``+"$ and the right side is $``-"$.
\end{itemize}

\subsection{Decomposition of continuous spectrum and discrete spectrum}
\noindent
Rather than directly analyzing the asymptotic behavior of the RHP \ref{initial-rhp-with-pole}, it is more convenient 
to examine a RHP without poles. Once the long-time behavior of the RHP without poles 
is established, we can readily derive the asymptotic behavior of the RHP \ref{initial-rhp-with-pole}.
In the following, we employ the Darboux transformation to decompose the sectional analytic matrix into its 
singular and analytic components. The singular part is represented by the Darboux matrix, while the 
left analytic component will satisfy a new RHP without the residue conditions. 
We will provide details for decomposing one discrete spectrum from the RHP \ref{initial-rhp-with-pole} with $N$ poles.

To begin with, we show that the solution $\hat{\M}$ of the initial RHP \ref{initial-rhp-with-pole} has 
the following symmetric property.
\begin{prop}\label{symmetry-M}
  The meromorphic matrix $\hat{\M}(\lambda;x,t)$ satisfies the follow symmetry: 
\begin{equation}
  \hat{\M}(\lambda;x,t)\hat{\M}^\dagger(\lambda^*;x,t)=\mathbb{I}_{3}.
\end{equation}
\end{prop}
\begin{proof}
  Set $\mathbf{H}(\lambda):=\mathbf{H}(\lambda;x,t)=\hat{\M}(\lambda;x,t)\hat{\M}^\dagger(\lambda^*;x,t)$ and 
  it follows from RHP \ref{initial-rhp-with-pole} that $\mathbf{H}(\lambda)$ approaches identity as $\lambda$ 
  tends to infinity. By the fact that 
  \begin{equation*}
    \det\hat{\V}(\lambda)=1\quad\text{and}\quad
    \hat{\V}(\lambda)=\hat{\V}^\dagger(\lambda), \quad \forall\lambda\in\mathbb{R},
  \end{equation*} 
  we have 
  \begin{equation*}
    \begin{aligned}
      \mathbf{H}_+(\lambda)&=\hat{\M}_+(\lambda)\hat{\M}^\dagger_-(\lambda)=
    \hat{\M}_-(\lambda)\hat{\V}(\lambda)\hat{\V}^\dagger
    (\lambda)^{-1}\hat{\M}^\dagger_+(\lambda)\\
    &=\hat{\M}_-(\lambda)\hat{\M}^\dagger_+(\lambda)=\mathbf{H}_-(\lambda),
    \end{aligned}
  \end{equation*}
  for $\lambda\in\mathbb{R}$. Therefore $\mathbf{H}(\lambda)$ has no jump on the real line. 
  By the residue relation in RHP \ref{initial-rhp-with-pole}, we have the Laurent expansions 
  \begin{equation*}
    \begin{aligned}
      \hat{\M}(\lambda)&=\mathbf{C}_i\left[\frac{\mathbf{N}_i}{\lambda-\lambda_i}+
      \mathbb{I}_3\right]+\oo(\lambda-\lambda_i),\quad 
      \mathbf{N}_i=\begin{pmatrix}0&0\\-\mathbf{c}_i\ee^{2\ii t\theta(\lambda_i)}&0\end{pmatrix}\\
      \hat{\M}(\lambda)&=\mathbf{C}_i^\prime\left[\frac{-\mathbf{N}^\dagger_i}
      {\lambda-\lambda_i^*}+\mathbb{I}_3\right]+\oo(\lambda-\lambda_i^*),
    \end{aligned}
  \end{equation*}
  where $\mathbf{C}_i$ and $\mathbf{C}_i^\prime$ are the constant terms in the Laurent expansions of $\hat{\M}(\lambda)$ 
  at $\lambda_i$ and $\lambda_i^*$ respectively. 
  This implies that as $\lambda\to\lambda_i$, we have
  \begin{equation*}
    \begin{aligned}
      \mathbf{H}(\lambda)&=\hat{\M}(\lambda)\hat{\M}^\dagger(\lambda^*)\\
      &=\left(\mathbf{C}_i\left[\frac{\mathbf{N}_i}{\lambda-\lambda_i}+
      \mathbb{I}_3\right]+\oo(\lambda-\lambda_i)\right)
      \left(\left[\frac{-\mathbf{N}_i}{\lambda-\lambda_i}+
      \mathbb{I}_3\right]\mathbf{C}_i^{\prime\dagger}+\oo(\lambda-\lambda_i)\right)\\
      &=\oo(1),
    \end{aligned}
  \end{equation*}
  since $\mathbf{N}_i$ is a nilpotent matrix, and 
  hence $\mathbf{H}(\lambda)$ is analytic in the whole complex plane.
  Then we conclude 
  that $\mathbf{H}(\lambda)\equiv\mathbb{I}_3$ %and 
  %$\hat{\M}(\lambda;x,t)\hat{\M}^\dagger(\lambda^*;x,t)=\mathbb{I}_{3}$
 by the Liouville theorem and the asymptotics $\mathbf{H}(\lambda)\to\mathbb{I}_3$ as $\lambda\to\infty$.
\end{proof}
%From Proposition \ref{symmetry-M}, we can deduce the symmetry of $\hat{\M}^{[1]}$ which is 
%the solution of RHP \ref{remove-pole-of-initial-rhp} and the following Lemma.
Now we proceed to decompose a single discrete spectrum from the matrix $\hat{\M}$ with the aid of Darboux transformation. 
\begin{lemma}\label{remove-a-pole}
  For the matrix $\hat{\M}(\lambda;x,t)$, there exist Darboux matrix $\mathbf{T}_1^{(\pm)}(\lambda; x, t)$ and $\hat{\M}^{[1]}(\lambda;x,t)$ such that 
  \begin{equation}\label{relation-M-M1}
    \begin{cases}
      \hat{\M}(\lambda ; x, t)=\mathbf{T}_1^{(+)}(\lambda ; x, t) \hat{\M}^{[1]}(\lambda ; x, t) 
      \mathrm{diag}\left(\frac{\lambda-\lambda_{1}^{*}}{\lambda-\lambda_{1}}, 1,1\right),
      \quad&{\rm Im} \lambda>0,\\
      \hat{\M}(\lambda ; x, t)=\mathbf{T}_1^{(-)}(\lambda ; x, t) \hat{\M}^{[1]}(\lambda ; x, t) 
      \mathrm{diag}\left(1, \frac{\lambda-\lambda_{1}}{\lambda-\lambda_{1}^{*}},\frac{\lambda-\lambda_{1}}{\lambda-\lambda_{1}^{*}}\right),
      &{\rm Im} \lambda<0,
    \end{cases}
  \end{equation}
  where $\hat{\M}^{[1]}$ satisfies the following RHP:
  \begin{rhp}\label{remove-pole-of-initial-rhp}
    Find an analytic function $\hat{\M}^{[1]}$: 
    $\mathbb{C}\setminus(\mathbb{R}\cup\mathcal{Z}_1\cup\mathcal{Z}_1^{*})\rightarrow SL_{2}(\mathbb{C})$, where $\mathcal{Z}_n=\mathcal{Z}\setminus\{\lambda_i\}_{i=1}^n$
    with the following properties
    \begin{itemize}
      \item[1.] $\hat{\M}^{[1]}(\lambda)=\mathbb{I}_{3}+\mathcal{O}\left(\lambda^{-1}\right)$ as $\lambda\rightarrow\infty.$
      \item[2.] For each $\lambda\in\mathbb{R}$ (with $\mathbb{R}$ oriented left-to-right),
      $\hat{\M}^{[1]}$ takes continuous boundary values $\hat{\M}^{[1]}_{\pm}(\lambda)$ which satisfy 
      the jump relation: $\hat{\M}^{[1]}_+(\lambda)=\hat{\M}^{[1]}_-(\lambda)\hat{\V}^{[1]}(\lambda)$, where
      \begin{equation*}
       \hat{\V}^{[1]}(\lambda)=
       \begin{pmatrix}
         1+\hat{\mathbf{R}}_1(\lambda)\hat{\mathbf{R}}_1^\dagger(\lambda)&-\hat{\mathbf{R}}_1(\lambda)\ee^{-2\ii t\theta(\lambda)}\\
         -\hat{\mathbf{R}}_1^\dagger(\lambda)\ee^{2\ii t\theta(\lambda)}&\mathbb{I}_2
       \end{pmatrix}
      \end{equation*}
      and $\hat{\mathbf{R}}_1(\lambda)=\frac{\lambda-\lambda_{1}^{*}}{\lambda-\lambda_{1}}\mathbf{\hat{R}}(\lambda)$.
      \item[3.] $\hat{\M}^{[1]}(\lambda)$ has simple poles at each $\lambda_i\in\mathcal{Z}_1$ and $\lambda_i^*\in\mathcal{Z}_1^*$, 
      for $i=2\ldots N$,  
      whose residue condition can be represented as
      \begin{equation*}
        \begin{array}{ll}
          & \mathop{\rm Res}\limits_{\lambda=\lambda_i}\hat{\M}^{[1]}=
          \mathop{\lim}\limits_{\lambda\to\lambda_i}\hat{\M}^{[1]}
          \begin{pmatrix}
            0&0\\
            -\mathbf{c}_{1i}e^{2\ii t\theta}&0
          \end{pmatrix},\\
          & \mathop{\rm Res}\limits_{\lambda=\lambda_i^*}\hat{\M}^{[1]}=
          \mathop{\lim}\limits_{\lambda\to\lambda_i^*}\hat{\M}^{[1]}
          \begin{pmatrix}
            0&\mathbf{c}_{1i}^{\dagger}e^{-2\ii t\theta}\\
            0&0
          \end{pmatrix},
        \end{array}
      \end{equation*}
      where $\mathbf{c}_{1i}=\mathbf{c}_i\frac{\lambda_i-\lambda_1}{\lambda_i-\lambda_1^*}$.
    \end{itemize}	
  \end{rhp}
\end{lemma}

\begin{proof}
  The elementary Darboux transformation $\mathbf{T}_1^{(\pm)}(\lambda; x, t)$ can be constructed 
  as the following from \cite{Backlundtransformations20001,lingzhang2024}:
\begin{equation}
  \mathbf{T}_1^{(+)}(\lambda ; x, t)=\mathbb{I}_3-\frac{\lambda_{1}-\lambda_{1}^*}{\lambda-\lambda_{1}^*} 
  \mathbf{P}_{1}(x, t), \quad \mathbf{P}_{1}(x, t)=\frac{\mathbf{\Phi}_{1} \mathbf{\Phi}_{1}^{\dagger}}{\mathbf{\Phi}_{1}^{\dagger} \mathbf{\Phi}_{1}},
\end{equation}
and
\begin{equation}\label{relation-T+-T-}
  \mathbf{T}_1^{(-)}(\lambda ; x, t)=
  \frac{\lambda-\lambda_{1}^*}
  {\lambda-\lambda_{1}} \mathbf{T}_1^{(+)}(\lambda ; x, t)=\mathbb{I}_3-\frac{\lambda_{1}^{*}-\lambda_{1}}
  {\lambda-\lambda_{1}}\left(\mathbb{I}_3-\mathbf{P}_{1}(x, t)\right),
\end{equation}
where
\begin{equation*}
  \mathbf{\Phi}_{1}=\hat{\M}_+^{[1]}(\lambda_{1} ; x, t) \ee^{-\mathrm{i} 
  \lambda_{1}\left(x+\lambda_{1} t\right) \pmb{\Lambda}_{3}} 
  \mathbf{v}_{1},\quad
  \mathbf{v}_{1}=[1,b_{11},b_{12}]^\dagger,
\end{equation*}
and $\mathbf{v}_{1}$ is determined below.
The Darboux matrix $\mathbf{T}_1^{(\pm)}(\lambda; x, t)$ is analytic in the upper (lower) half plane. 
In virtue of Darboux transformation, we can establish the relation between $\hat{\M}(\lambda ; x, t)$ and $\hat{\M}^{[1]}(\lambda ; x, t)$
\begin{equation}\label{relation-Mhat-M+}
  \hat{\M}_+(\lambda ; x, t)=\mathbf{T}_1^{(+)}(\lambda ; x, t) 
  \hat{\M}_+^{[1]}(\lambda ; x, t) 
  \mathrm{diag}\left(\frac{\lambda-\lambda_{1}^{*}}{\lambda-\lambda_{1}}, 1,1\right),
  \quad {\rm Im}\lambda>0,
\end{equation}
and 
\begin{equation}\label{relation-Mhat-M-}
  \hat{\M}_-(\lambda ; x, t)=\mathbf{T}_1^{(-)}(\lambda ; x, t) 
  \hat{\M}_-^{[1]}(\lambda ; x, t) 
  \mathrm{diag}\left(1, \frac{\lambda-\lambda_{1}}{\lambda-\lambda_{1}^{*}},
  \frac{\lambda-\lambda_{1}}{\lambda-\lambda_{1}^{*}}\right),
  \quad {\rm Im}\lambda<0.
\end{equation}
Note the fact that $\mathbf{P}_{1}=\mathbf{P}_{1}^\dagger$ and $\mathbf{P}_{1}^2=\mathbf{P}_{1}$, and then 
we have 
\begin{equation}\label{symmetry-T+}
    \mathbf{T}_1^{(+)}(\lambda ; x, t)\mathbf{T}_1^{(+)}(\lambda^* ; x, t)^\dagger=\mathbb{I}_3.
\end{equation}
Together with Proposition \ref{symmetry-M} and equation \eqref{relation-T+-T-}, we have 
\begin{equation}
  \begin{aligned}
    \hat{\M}_+^{[1]}(\lambda ; x, t)\hat{\M}_-^{[1]}(\lambda^* ; x, t)^\dagger
    &=\frac{\lambda-\lambda_1}{\lambda-\lambda_1^*}\mathbf{T}_1^{(+)}(\lambda ; x, t)^{-1}
    \hat{\M}_+(\lambda;x,t)\hat{\M}_-^\dagger(\lambda^*;x,t)
    \left(\mathbf{T}_1^{(-)}(\lambda^* ; x, t)^\dagger\right)^{-1}\\
    &=\frac{\lambda-\lambda_1}{\lambda-\lambda_1^*}
    \left(\frac{\lambda-\lambda_1}{\lambda-\lambda_1^*}
    \mathbf{T}_1^{(+)}(\lambda ; x, t)\mathbf{T}_1^{(+)}
    (\lambda^* ; x, t)^\dagger\right)^{-1}=\mathbb{I}_3.
  \end{aligned}
\end{equation}
Now we consider the kernel of above
elementary Darboux matrix $\mathbf{T}_1^{(\pm)}(\lambda; x, t)$:
\begin{equation}\label{kernel-T+}
  \left.\mathbf{T}_1^{(+)}(\lambda ; x, t) \hat{\M}_+^{[1]}(\lambda ; x, t) 
  \mathrm{e}^{-\mathrm{i} \lambda(x+\lambda t) \pmb{\Lambda}_{3}}
  \right|_{\lambda=\lambda_{1}} \mathbf{v}_{1}=
  \left(\mathbb{I}_3-\mathbf{P}_{1}(x, t)\right)\mathbf{P}_{1}(x, t)=0,
\end{equation}
and
\begin{equation}\label{kernel-T-}
    \begin{aligned}
      &\quad\left.\mathbf{T}_1^{(-)}(\lambda ; x, t) \hat{\M}_-^{[1]}(\lambda ; x, t) \mathrm{e}^{-\mathrm{i} 
  \lambda(x+\lambda t) \boldsymbol{\pmb{\Lambda}}_{3}}
  \right|_{\lambda=\lambda_{1}^*}\begin{bmatrix}
    \mathbf{w}_{11}, \mathbf{w}_{12}
  \end{bmatrix}\\
  &=\mathbf{P}_{1}(x, t)\left(\hat{\M}^{[1]}_+(\lambda_1 ; x, t)^\dagger\right)^{-1}
  \mathrm{e}^{-\mathrm{i} 
  \lambda_1^*(x+\lambda_1^* t) \boldsymbol{\pmb{\Lambda}}_{3}}\begin{bmatrix}
    \mathbf{w}_{11}, \mathbf{w}_{12}
  \end{bmatrix}\\
  &=\frac{\mathbf{\Phi}_{1} }{\mathbf{\Phi}_{1}^{\dagger} \mathbf{\Phi}_{1}}
  \mathbf{v}_{1}^\dagger
  \mathrm{e}^{\mathrm{i} 
  \lambda_1^*(x+\lambda_1^* t) \boldsymbol{\pmb{\Lambda}}_{3}}
  \hat{\M}^{[1]}_+(\lambda_1 ; x, t)^\dagger\left(\hat{\M}^{[1]}_+(\lambda_1 ; x, t)^\dagger\right)^{-1}
  \mathrm{e}^{-\mathrm{i} 
  \lambda_1^*(x+\lambda_1^* t) \boldsymbol{\pmb{\Lambda}}_{3}}\begin{bmatrix}
    \mathbf{w}_{11}, \mathbf{w}_{12}
  \end{bmatrix}\\
  &=\frac{\mathbf{\Phi}_{1} }{\mathbf{\Phi}_{1}^{\dagger} \mathbf{\Phi}_{1}}
  \mathbf{v}_{1}^\dagger\begin{bmatrix}
    \mathbf{w}_{11}, \mathbf{w}_{12}
  \end{bmatrix}=0,
    \end{aligned}
\end{equation}
where $\mathbf{w}_{11}=[-b_{11},1,0]^{\top}$ and 
$\mathbf{w}_{12}=[-b_{12},0,1]^{\top}$.

%By equation \eqref{relation-T+-T-}, we have
%\begin{equation*}
%  \hat{\M}_-(\lambda ; x, t)=\mathbf{T}_1^{(+)}(\lambda ; x, t) 
%  \hat{\M}_-^{[1]}(\lambda ; x, t) 
%  \mathrm{diag}\left(\frac{\lambda-\lambda_{1}^{*}}{\lambda-\lambda_{1}}, 
%  1,1\right),\quad {\rm Im}\lambda<0,
%\end{equation*}
Hence the jump condition of $\hat{\M}(\lambda;x,t)$ on $\lambda\in\mathbb{R}$ will turn to
\begin{equation}
  \begin{aligned}
    \hat{\M}_+(\lambda ; x, t)&=\mathbf{T}_1^{(+)}(\lambda ; x, t) \hat{\M}^{[1]}_{-}(\lambda ; x, t)\hat{\V}^{[1]}(\lambda)
    \mathrm{diag}\left(\frac{\lambda-\lambda_{1}^{*}}{\lambda-\lambda_{1}}, 1,1\right)\\
    &=\hat{\M}_-(\lambda ; x, t)\mathrm{diag}\left(\frac{\lambda-\lambda_{1}}{\lambda-\lambda_{1}^{*}}, 1,1\right)\hat{\V}^{[1]}(\lambda)
    \mathrm{diag}\left(\frac{\lambda-\lambda_{1}^{*}}{\lambda-\lambda_{1}}, 1,1\right)\\
    &=\hat{\M}_-(\lambda ; x, t)
    \begin{pmatrix}
      1+\hat{\mathbf{R}}_1(\lambda)\hat{\mathbf{R}}_1^\dagger(\lambda)&-\frac{\lambda-\lambda_{1}}{\lambda-\lambda_{1}^{*}}\hat{\mathbf{R}}_1(\lambda)\ee^{-2\ii t\theta(\lambda)}\\
      -\frac{\lambda-\lambda_{1}^{*}}{\lambda-\lambda_{1}}\hat{\mathbf{R}}_1^\dagger(\lambda)\ee^{2\ii t\theta(\lambda)}&\mathbb{I}_2
    \end{pmatrix}.
  \end{aligned}
\end{equation}
Therefore, it follows from equation \eqref{initial-Jump} necessarily that 
$\mathbf{\hat{R}}(\lambda)=\frac{\lambda-\lambda_{1}}{\lambda-\lambda_{1}^{*}}\hat{\mathbf{R}}_1(\lambda)$.
Moreover, by equations \eqref{relation-Mhat-M+}, \eqref{kernel-T+} and \eqref{kernel-T-}, we 
obtain the residue conditions for $\hat{\M}$:
\begin{equation*}
  \begin{aligned}
    \mathop{\rm Res}\limits_{\lambda=\lambda_1}\hat{\M}&=
  \begin{pmatrix}
    (\lambda_1-\lambda_1^*)[\mathbf{T}_1^{(+)}(\lambda_1;x,t)\hat{\M}^{[1]}(\lambda_1;x,t)]_1&0
  \end{pmatrix}\\
  &=\begin{pmatrix}
    -(\lambda_1-\lambda_1^*)\ee^{2\ii t\theta(\lambda_1)}[\mathbf{T}_1^{(+)}(\lambda_1;x,t)\hat{\M}^{[1]}(\lambda_1;x,t)]_2
  \begin{pmatrix}
    b_{11}^{*}\\b_{12}^{*}
  \end{pmatrix}&0
  \end{pmatrix}\\
  &=\mathop{\lim}\limits_{\lambda\to\lambda_1}
  \hat{\M}\begin{pmatrix}
    0&0\\
    -(\lambda_1-\lambda_1^*)\begin{pmatrix}
      b_{11}^*\\b_{12}^*
    \end{pmatrix}\ee^{2\ii t\theta(\lambda_1)}&0
  \end{pmatrix},
  \end{aligned}    
\end{equation*}
and 
\begin{equation*}
  \begin{aligned}
    \mathop{\rm Res}\limits_{\lambda=\lambda_1^*}\hat{\M}&=
  \begin{pmatrix}
    0&(\lambda_1^*-\lambda_1)[\mathbf{T}_1^{(-)}(\lambda_1;x,t)\hat{\M}^{[1]}_{-}(\lambda_1;x,t)]_2
  \end{pmatrix}\\
  &=\begin{pmatrix}
    0&(\lambda_1^*-\lambda_1)\ee^{-2\ii t\theta(\lambda_1^*)}[\mathbf{T}_1^{(-)}(\lambda_1;x,t)\hat{\M}^{[1]}_{-}(\lambda_1;x,t)]_1
  \begin{pmatrix}
    b_{11}&b_{12}
  \end{pmatrix}
  \end{pmatrix}\\
  &=\mathop{\lim}\limits_{\lambda\to\lambda_1^*}
  \hat{\M}\begin{pmatrix}
    0&(\lambda_1^*-\lambda_1)\ee^{-2\ii t\theta(\lambda_1^*)}
    \begin{pmatrix}
      b_{11}&b_{12}
    \end{pmatrix}\\
    0&0
  \end{pmatrix}.
  \end{aligned}
\end{equation*}
By comparing the RHP  \ref{initial-rhp-with-pole} and RHP \ref{remove-pole-of-initial-rhp}, a straightforward calculation shows that 
\begin{equation}
  \mathbf{c}_1=(\lambda_1-\lambda_1^*)\begin{pmatrix}
    b_{11}^*\\b_{12}^*
  \end{pmatrix}.
\end{equation}

Similarly, for $\lambda_j$, $j=2,\dots,N$, we have the residue conditions
\begin{equation*}
  \begin{aligned}
    \mathop{\rm Res}\limits_{\lambda=\lambda_j}\hat{\M}&=
    \mathbf{T}_1^{(+)}(\lambda_j;x,t)
    \mathop{\lim}\limits_{\lambda\to\lambda_j}
  \hat{\M}^{[1]}\begin{pmatrix}
    0&0\\
    -\mathbf{c}_{1j}\ee^{2\ii t\theta(\lambda_j)}&0
  \end{pmatrix}
  \mathrm{diag}\left(\frac{\lambda_j-\lambda_1^*}{\lambda_j-\lambda_1},1,1\right)\\
  &=\mathop{\lim}\limits_{\lambda\to\lambda_j}
  \hat{\M}\begin{pmatrix}
    0&0\\
    -\mathbf{c}_{1j}\frac{\lambda_j-\lambda_1^*}{\lambda_j-\lambda_1}\ee^{2\ii t\theta(\lambda_j)}&0
  \end{pmatrix},
  \end{aligned}    
\end{equation*}
and 
\begin{equation*}
  \begin{aligned}
    \mathop{\rm Res}\limits_{\lambda=\lambda_j^*}\hat{\M}&=
    \mathbf{T}_1^{(-)}(\lambda_j;x,t)
    \mathop{\lim}\limits_{\lambda\to\lambda_j^*}
  \hat{\M}^{[1]}\begin{pmatrix}
    0&\mathbf{c}^{\dagger}_{1j}\ee^{-2\ii t\theta(\lambda_j^*)}\\
    0&0
  \end{pmatrix}
  \mathrm{diag}\left(1,\frac{\lambda_j^*-\lambda_1}{\lambda_j^*-\lambda_1^*},
  \frac{\lambda_j^*-\lambda_1}{\lambda_j^*-\lambda_1^*}\right)\\
  &=\mathop{\lim}\limits_{\lambda\to\lambda_j^*}
  \hat{\M}\begin{pmatrix}
    0&\mathbf{c}^{\dagger}_{1j}\frac{\lambda_j^*-\lambda_1}{\lambda_j^*-\lambda_1^*}\ee^{-2\ii t\theta(\lambda_j^*)}\\
    0&0
  \end{pmatrix}.
  \end{aligned}    
\end{equation*}
The above residue conditions imply that 
\begin{equation*}
  \mathbf{c}_j=\mathbf{c}_{1j}\frac{\lambda_j-\lambda_1^*}{\lambda_j-\lambda_1}.
\end{equation*}
Then we complete the proof.
\end{proof}

From Lemma \ref{remove-a-pole}, the solution $\hat{\M}(\lambda;x,t)$ of RHP \ref{initial-rhp-with-pole} 
can be decomposed to three parts as equation \eqref{relation-M-M1} and hence 
the recovery formula \eqref{recover-CNLS} can be rewritten as 
% It follows from equation \eqref{recover-CNLS} and equation \eqref{relation-Mhat-M+} that 
\begin{equation*}
  \begin{aligned}
    \mathbf{q}(x,t)&=2\left(\left(\mathbf{T}_1^{(+)}\right)_1+\hat{\M}^{[1]}_1\right)_{12}\\
    &=\lim_{\lambda\rightarrow\infty} 2\lambda \left(\hat{\M}^{[1]}(\lambda;x,t)\right)_{12}-
    2(\lambda_1-\lambda_1^*)\left(\mathbf{P}_1(x,t)\right)_{12},
  \end{aligned}
\end{equation*}
where $\left(\mathbf{T}_1^{(+)}\right)_1$ and $\hat{\M}^{[1]}_1$ are the residues of 
$\mathbf{T}^{(+)}(\lambda;x,t)$ and $\hat{\M}^{[1]}(\lambda;x,t)$ at $\lambda=\infty$ respectively.
In order to recover $\mathbf{q}(x,t)$ by the solution of RHP without any pole, 
we should decompose $N$ single discrete spectrums from the matrix $\hat{\M}$. In fact, we only need to replace 
the procedure in Lemma \ref{remove-a-pole} $N$ times and then obtain the following Theorem \ref{remove-N-poles}.
Before that, we will introduce some necessary notations:
\begin{equation}\label{def-Ti}
  \begin{aligned}
    &\mathbf{T}_i^{(+)}(\lambda ; x, t)=\mathbb{I}_3-\frac{\lambda_{i}-\lambda_{i}^*}
    {\lambda-\lambda_{i}^*} 
    \mathbf{P}_{i}(x, t), \quad \mathbf{P}_{i}(x, t)=\frac{\mathbf{\Phi}_{i} 
    \mathbf{\Phi}_{i}^{\dagger}}{\mathbf{\Phi}_{i}^{\dagger} \mathbf{\Phi}_{i}},\\
    &\mathbf{T}_i^{(-)}(\lambda ; x, t)=
    \frac{\lambda-\lambda_{i}^*}
    {\lambda-\lambda_{i}} \mathbf{T}_i^{(+)}(\lambda ; x, t),\quad
    \mathbf{\Phi}_{i}=\hat{\M}_+^{[i]}(\lambda_{i} ; x, t) \ee^{-\mathrm{i} 
  \lambda_{i}\left(x+\lambda_{i} t\right) \pmb{\Lambda}_{3}} 
  \mathbf{v}_{i},\\
  &\mathbf{v}_{i}=\begin{bmatrix}
    1,b_{i1},b_{i2}
  \end{bmatrix}^\dagger, \quad
  \begin{bmatrix}
    b_{i1},b_{i2}
  \end{bmatrix}^\dagger=\frac{\mathbf{c}_i}{\lambda_i-\lambda_i^*}
  \prod_{j=1}^{i-1}\frac{\lambda_i-\lambda_j}{\lambda_i-\lambda_j^*}.
  \end{aligned}
\end{equation}
where $\hat{\M}^{[i]}$, for $1\le i\le N-1$, is the solution of the following RHP 
\begin{rhp}
  Find an analytic function $\hat{\M}^{[i]}$: 
  $\mathbb{C}\setminus(\mathbb{R}\cup\mathcal{Z}_i\cup\mathcal{Z}_i^{*})\rightarrow SL_{2}(\mathbb{C})$, where $\mathcal{Z}_n=\mathcal{Z}\setminus\{\lambda_i\}_{i=1}^n$
  with the following properties
  \begin{itemize}
    \item[1.] $\hat{\M}^{[i]}(\lambda)=\mathbb{I}_{3}+\mathcal{O}\left(\lambda^{-1}\right)$ as $\lambda\rightarrow\infty.$
    \item[2.] For each $\lambda\in\mathbb{R}$ (with $\mathbb{R}$ oriented left-to-right),
    $\hat{\M}^{[i]}$ takes continuous boundary values $\hat{\M}^{[i]}_{\pm}(\lambda)$ which satisfy 
    the jump relation: $\hat{\M}^{[i]}_+(\lambda)=\hat{\M}^{[i]}_-(\lambda)\hat{\V}^{[i]}(\lambda)$, where
    \begin{equation*}
     \hat{\V}^{[i]}(\lambda)=
     \begin{pmatrix}
       1+\hat{\mathbf{R}}_i(\lambda)\hat{\mathbf{R}}_i^\dagger(\lambda)&-\hat{\mathbf{R}}_i(\lambda)\ee^{-2\ii t\theta(\lambda)}\\
       -\hat{\mathbf{R}}_i^\dagger(\lambda)\ee^{2\ii t\theta(\lambda)}&\mathbb{I}_2
     \end{pmatrix}
    \end{equation*}
    and $\mathbf{R}_i(\lambda)=\prod_{k=1}^{i}\frac{\lambda-\lambda_k^*}{\lambda-\lambda_k}\hat{\mathbf{R}}(\lambda)$.
    \item[3.] $\hat{\M}^{[i]}(\lambda)$ has simple poles at each $\lambda_j\in\mathcal{Z}_i$ 
    and $\lambda_j^*\in\mathcal{Z}_i^*$
    at which
    \begin{equation*}
      \begin{array}{ll}
        & \mathop{\rm Res}\limits_{\lambda=\lambda_j}\hat{\M}^{[i]}=
        \mathop{\lim}\limits_{\lambda\to\lambda_j}\hat{\M}^{[i]}
        \begin{pmatrix}
          0&0\\
          -\mathbf{c}_{ij}e^{2\ii t\theta}&0
        \end{pmatrix},\\
        & \mathop{\rm Res}\limits_{\lambda=\lambda_j^*}\hat{\M}^{[i]}=
        \mathop{\lim}\limits_{\lambda\to\lambda_j^*}\hat{\M}^{[i]}
        \begin{pmatrix}
          0&\mathbf{c}_{ij}^{\dagger}e^{-2\ii t\theta}\\
          0&0
        \end{pmatrix},
      \end{array}
    \end{equation*}
    where $\mathbf{c}_{ij}=\mathbf{c}_j\prod_{k=1}^{i}\frac{\lambda_j-\lambda_k}{\lambda_j-\lambda_k^*}$.
  \end{itemize}	
\end{rhp}
Let $\M$ be the solution of RHP without poles 
\begin{rhp}\label{initial-rhp-without-role}
  Find an analytic function $\M$: 
$\mathbb{C}\setminus\mathbb{R}\rightarrow SL_{2}(\mathbb{C})$ 
with the following properties
\begin{itemize}
  \item[1.] $\M(\lambda)=\mathbb{I}_{3}+\mathcal{O}\left(\lambda^{-1}\right)$ as $\lambda\rightarrow\infty.$
  \item[2.] For each $\lambda\in\mathbb{R}$ (with $\mathbb{R}$ oriented left-to-right),
  $\M$ takes continuous boundary values $\M_{\pm}(\lambda)$ which satisfy 
  the jump relation: $\M_+(\lambda)=\M_-(\lambda)\V(\lambda)$ where
  \begin{equation}\label{def-R-no-soliton}
   \V(\lambda)=
   \begin{pmatrix}
    1+\mathbf{R}(\lambda)\mathbf{R}^\dagger(\lambda)&-\mathbf{R}(\lambda)\ee^{-2\ii t\theta(\lambda)}\\
    -\mathbf{R}^\dagger(\lambda)\ee^{2\ii t\theta(\lambda)}&\mathbb{I}_2
  \end{pmatrix},
  \end{equation}
  where $\mathbf{R}(\lambda)=\prod_{i=1}^{N}\frac{\lambda-\lambda_i^*}{\lambda-\lambda_i}\hat{\mathbf{R}}(\lambda)$.
\end{itemize}
\end{rhp}


\begin{theorem}\label{remove-N-poles}
  For $\hat{\M}$ which is the solution of RHP \ref{initial-rhp-with-pole} with N poles, 
  there exist Darboux matrix $\mathbf{T}^{(\pm)}=\prod_{i=1}^{N}\mathbf{T}^{(\pm)}_i$ and $\M$ such that 
  \begin{equation}\label{relation-hatM-M}
    \begin{cases}
      \hat{\M}(\lambda ; x, t)=\mathbf{T}^{(+)}(\lambda ; x, t) \M(\lambda ; x, t) 
      \mathrm{diag}\left(\prod_{i=1}^{N}\frac{\lambda-\lambda_{i}^{*}}{\lambda-\lambda_{i}}, 1,1\right),
      \quad&{\rm Im}\lambda>0,\\[4pt]
      \hat{\M}(\lambda ; x, t)=\mathbf{T}^{(-)}(\lambda ; x, t) \M(\lambda ; x, t) 
      \mathrm{diag}\left(1, \prod_{i=1}^{N}\frac{\lambda-\lambda_{i}}{\lambda-\lambda_{i}^{*}},
      \prod_{i=1}^{N}\frac{\lambda-\lambda_{i}}{\lambda-\lambda_{i}^{*}}\right),
      &{\rm Im}\lambda<0.
    \end{cases}
  \end{equation}
  where $\M$ is the solution of RHP \ref{initial-rhp-without-role} without any poles.

  In particular, the solution $\mathbf{q}(x,t)$ of CNLS equation \eqref{CNLS} can be recovered by a 
  better formula
  \begin{equation}\label{matrix-form-T1}
    \mathbf{q}(x,t)=\lim_{\lambda\rightarrow\infty} \left(2\lambda \M(\lambda;x,t)\right)_{12}-
    2\mathbf{X}_1\mathbf{G}^{-1}(\mathbf{X}_2)^\dagger,
  \end{equation}
  where 
  \begin{equation*}
    \begin{aligned}
      &\mathbf{X}=\begin{bmatrix}
        |x_1\rangle,\cdots,|x_N\rangle
      \end{bmatrix},\quad \mathbf{G}=\left(\mathbf{G}_{ji}\right)_{1\le j,i\le N},\quad
      \mathbf{G}_{ji}=\frac{\langle x_j|x_i\rangle}{\lambda_i-\lambda_j^*},\\
      &|x_i\rangle=\M(\lambda_i; x, t)\mathrm{diag}\left(\prod_{j=i+1}^{N}\frac{\lambda_i-\lambda_{j}^{*}}{\lambda_i-\lambda_{j}}, 1,1\right)
      \ee^{-\ii\lambda_i(x+\lambda_i t)\pmb{\Lambda}_3}\mathbf{v}_i,
      \quad\langle x_j|=|x_j\rangle^\dagger,
    \end{aligned}
  \end{equation*}
  and $\mathbf{X}_1$ represents the first row of 
  $\mathbf{X}$ and $\mathbf{X}_2$ represents the second and third row of $\mathbf{X}$.
\end{theorem}
\begin{proof}
Repeated the procedure in Lemma \ref{remove-a-pole} $N$ times, we can obtain the 
  relation \eqref{relation-hatM-M} between $\hat{\M}(\lambda)$ and $\M(\lambda)$. 
  Moreover, $\M(\lambda)$ would satisfy RHP \ref{initial-rhp-without-role} without 
  residue conditions.

  Then we only need to rewrite $\mathbf{T}^{(\pm)}=\prod_{i=1}^{N}\mathbf{T}^{(\pm)}_i$ as another 
  matrix form \eqref{matrix-form-T1}.
  Now we consider the kernel of $\mathbf{T}_i^{(+)}(\lambda ; x, t)$ at $\lambda=\lambda_i$
  \begin{equation*}
    \mathbf{T}_i^{(+)}(\lambda_i; x, t)\mathbf{\Phi}_{i}=(\mathbb{I}_3-\mathbf{P}_i)\mathbf{\Phi}_{i}=0,\qquad i=1,2,\cdots, N,
  \end{equation*}
  and hence we deduce the kernel of $\mathbf{T}^{(+)}(\lambda ; x, t)$ at $\lambda=\lambda_N$
  \begin{equation*}
    \mathbf{T}^{(+)}(\lambda; x, t)\mathbf{\Phi}_{N}|_{\lambda=\lambda_N}=0.
  \end{equation*}
Then we will determine the kernel of $\mathbf{T}^{(+)}(\lambda; x, t)$ at other points $\lambda_i$, $i=1,2,\cdots, N-1$,  i.e. $\mathbf{T}^{(+)}(\lambda; x, t)\pmb{\varphi}_{i}|_{\lambda=\lambda_i}=0$. And the kernel $\pmb{\varphi}_{i}$ can be determined by 
  \begin{multline*}
    \prod_{j=i+1}^{N}\mathbf{T}_j^{(+)}(\lambda ; x, t)\pmb{\varphi}_i\big|_{\lambda=\lambda_i}=\mathbf{\Phi}_i
    =\hat{\M}^{[i]}(\lambda_i)\ee^{-\ii\lambda_i(x+\lambda_i t)\pmb{\Lambda}_3}\mathbf{v}_i\\
    =\prod_{j=i+1}^{N}\mathbf{T}_j^{(+)}(\lambda ; x, t)\M(\lambda ; x, t)\big|_{\lambda=\lambda_i}
    \mathrm{diag}\left(\prod_{j=i+1}^{N}\frac{\lambda_i-\lambda_{j}^{*}}{\lambda_i-\lambda_{j}}, 1,1\right)
    \ee^{-\ii\lambda_i(x+\lambda_i t)\pmb{\Lambda}_3}\mathbf{v}_i,
  \end{multline*}
which implies that
  \begin{equation*}
    \pmb{\varphi}_{i}=\M(\lambda_i; x, t)\mathrm{diag}\left(\prod_{j=i+1}^{N}\frac{\lambda_i-\lambda_{j}^{*}}{\lambda_i-\lambda_{j}}, 1,1\right)
    \ee^{-\ii\lambda_i(x+\lambda_i t)\pmb{\Lambda}_3}\mathbf{v}_i.
  \end{equation*}

  By equation \eqref{def-Ti}, $\mathbf{T}^{(+)}$ can be written in a fractional form
  \begin{equation}\label{eq:ndt}
    \mathbf{T}^{(+)}(\lambda;x,t)=\mathbb{I}_3-
    \sum_{i=1}^{N}\frac{\,|y_i\rangle \langle x_i|\,}{\lambda-\lambda_i^*},
  \end{equation}
  where $|y_i\rangle$ and $\langle x_i|$ have been not determined yet and denote $\langle y_i|=|y_i\rangle^\dagger$ and 
  $|x_i\rangle=\langle x_i|^\dagger$.
  By the symmetry of $\mathbf{T}_i^{(+)}$, we have $\mathbf{T}^{(+)}(\lambda)(\mathbf{T}^{(+)}(\lambda^*))^\dagger=\mathbb{I}_3$ and hence 
  \begin{equation*}
    0=\mathop{\rm Res}\limits_{\lambda=\lambda_i}\mathbf{T}^{(+)}(\lambda)(\mathbf{T}^{(+)}(\lambda^*))^\dagger
    =-\mathbf{T}^{(+)}(\lambda_i)|x_i\rangle \langle y_i|.
  \end{equation*}
  Since $\langle y_i|\neq0$, the matrix $\mathbf{T}^{(+)}(\lambda_i)|x_i\rangle=0$. 
  Then we can choose $|x_i\rangle$ as $\pmb{\varphi}_i$ and further we have
  \begin{equation*}
    |x_i\rangle=\sum_{j=1}^{N}\frac{\,|y_j\rangle \langle x_j|\,}
    {\lambda_i-\lambda_j^*}|x_i\rangle.
  \end{equation*}
   The above equation can be represented in the matrix form so that $\mathbf{X}=\mathbf{Y}\mathbf{G}$, where
  \begin{equation*}
    \mathbf{X}=\begin{bmatrix}
      |x_1\rangle,\cdots,|x_N\rangle
    \end{bmatrix}=\begin{bmatrix}
      \pmb{\varphi}_1,\cdots,\pmb{\varphi}_N
    \end{bmatrix},\quad \mathbf{Y}=\begin{bmatrix}
      |y_1\rangle,\cdots,|y_N\rangle
    \end{bmatrix}\quad\text{and}\quad
    \mathbf{G}_{ji}=\frac{\langle x_j|x_i\rangle}{\lambda_i-\lambda_j^*},
  \end{equation*}
 $\mathbf{G}_{ji}$s denote the $(j,i)$ element of matrix $\mathbf{G}$.
  Hence, the Darboux matrix $\mathbf{T}^{(+)}(\lambda;x,t)$ can be rewritten
  \begin{equation}\label{matrix-form-T+}
    \mathbf{T}^{(+)}(\lambda;x,t)=\mathbb{I}_3-\mathbf{X}\mathbf{G}^{-1}(\lambda\mathbb{I}_3-\mathbf{D})^{-1}\mathbf{X}^\dagger,
  \end{equation}
  where $\mathbf{D}=\mathrm{diag}(\lambda_1^*,\cdots,\lambda_N^*)$.
  By equation \eqref{relation-hatM-M}, the recovery formula \eqref{recover-CNLS} can be rewritten as
  \begin{equation*}
    \mathbf{q}(x,t)=
    \lim_{\lambda\rightarrow\infty} \left(2\lambda \M(\lambda;x,t)\right)_{12}
      +\left(2\lambda \mathbf{T}^{(+)}(\lambda;x,t)\right)_{12}.
  \end{equation*}
  Together with equation \eqref{matrix-form-T+}, we can obtain the formula \eqref{matrix-form-T1}. 
  This completes the proof.
\end{proof}

By Theorem \ref{remove-N-poles}, the solution $\mathbf{q}(x,t)$ in equation \eqref{matrix-form-T1} can 
be recovered by the matrix 
$\M(\lambda;x,t)$ at $\lambda=\infty$ and  $\lambda=\lambda_i\in\mathcal{Z}$. 
To obtain the long-time behavior of the solution $\mathbf{q}(x,t)$ for the CNLS equation \eqref{CNLS}, 
it suffices to analyze the long-time behavior of the matrix 
$\M(\lambda;x,t)$ at infinity and $\mathcal{Z}$ with respect to the spectral parameter $\lambda_i$. 
In the next subsection, we apply INSD to obtain the long-time asymptotic behavior of solution $\M(\lambda;x,t)$ at $\lambda\in\mathcal{Z}\cup\{\infty\}$.  


\subsection{Factorization of the jump matrix}

\noindent

An analogue of the classical NSD for RHPs was developed by Deift and 
Zhou \cite{deift1993steepest}. The key idea is to deform the jump matrix $\V(\lambda)$, which involves the oscillatory 
factor $\ee^{\pm 2\ii\theta}$ on the real axis, 
onto new contours in the plane where $\ee^{\pm 2\ii\theta}$
decay, as illustrated in figure \ref{region-decay-e}. And we can note that the jump matrix $\V(\lambda)$ has 
two distinct factorizations, which are needed in the contour deformation described in subsection \ref{contour-deformation},
\begin{equation*}
  \V(\lambda)=
  \begin{cases}
    \begin{pmatrix}
      1&-\mathrm{e}^{-2\ii t\theta}\mathbf{R}(\lambda)\\
      0&\mathbb{I}_2\end{pmatrix}
    \begin{pmatrix}1&0\\
      -\mathrm{e}^{2\ii t\theta}\mathbf{R}^\dagger(\lambda^*)&\mathbb{I}_2
    \end{pmatrix},\\
    \begin{pmatrix}1&0\\
      -\frac{\mathrm{e}^{2\ii t\theta}\mathbf{R}^\dagger(\lambda^*)}
      {\mathbb{I}_2+\mathbf{R}
      (\lambda)\mathbf{R}^\dagger(\lambda^*)}&\mathbb{I}_2
    \end{pmatrix}
    \begin{pmatrix}
      1+\mathbf{R}(\lambda)\mathbf{R}^\dagger(\lambda^*)&0\\0&(\mathbb{I}_2+\mathbf{R}^\dagger(\lambda^*)\mathbf{R}(\lambda))^{-1}\end{pmatrix}\begin{pmatrix}1&-\frac{\mathrm{e}^{-2\ii t\theta}\mathbf{R}(\lambda)}{1+\mathbf{R}(\lambda)\mathbf{R}^\dagger(\lambda^*)}\\
        0&\mathbb{I}_2
    \end{pmatrix}.
  \end{cases}
\end{equation*}
We can see that the second factorization involves a diagonal matrix. 
Then we introduce a matrix function $\pmb{\delta}(\lambda)$ to conjugate the matrix $\M$, leading 
to a new RHP 
which has lower/upper factorization for the jump matrix on the real axis without the diagonal matrix.
Let $\pmb{\delta}(\lambda)$ be the solution of the matrix RHP
\begin{equation}\label{RHP-delta}
  \begin{cases}
  \pmb{\delta}_+(\lambda)=(\mathbb{I}_2+\mathbf{R}^\dagger\mathbf{R})\pmb{\delta}_-(\lambda),\quad&\lambda<\xi,\\
  \pmb{\delta}(\lambda)\rightarrow\mathbb{I}_2, &\lambda\rightarrow\infty,
  \end{cases}
\end{equation}
where $\xi=-\frac{x}{2t}$ is the stationary point of phase function $\theta(\lambda)$. 
Then the determinant of $\pmb{\delta}(\lambda)$ satisfies the following RHP:
\begin{equation}\label{RHP-det-delta}
  \begin{cases}
    \det\pmb{\delta}_+(\lambda)=\det\pmb{\delta}_-(\lambda)(1+|\mathbf{R}(\lambda)|^2),\quad  &\lambda<\xi,\\
    \det\pmb{\delta}(\lambda)\rightarrow1, &\lambda\rightarrow\infty.
  \end{cases}
\end{equation}

