    \node at (-1, 1) {\fontsize{7}{24}\selectfont $\ee^{-2\ii t\theta}\ll1$};\node at (1, -1)  {\fontsize{7}{24}\selectfont $\ee^{-2\ii t\theta}\ll1$};
