%     &\beta(\lambda,\xi)=-\kappa(\xi)ln(\lambda-\xi+1)+\int_{-\infty}^{\xi}\frac{\kappa(s)-\chi(s)\kappa(\xi)}{s-\lambda}ds.
%   \end{aligned}\right.
% \end{equation}
% where $\chi(s)$ is the characteristic function of the interval $(\xi-1,\xi)$ and the logarithm is principally branched along $(-\infty,\xi-1]$.
Let $\mathbf{g}(\lambda)=[\pmb{\delta}^\dagger(\lambda^*)]^{-1}$, then we have
\begin{equation*}
  \begin{aligned}
    \mathbf{g}_+(\lambda)
    &=\lim_{\varepsilon\rightarrow0_+}\mathbf{g}(\lambda+\ii\varepsilon)
    =\lim_{\varepsilon\rightarrow0_+}\left(\pmb{\delta}^\dagger(\lambda-\ii\varepsilon)\right)^{-1}\\
    &=\lim_{\varepsilon\rightarrow0_+}\left(\pmb{\delta}^\dagger(\lambda-\ii\varepsilon)\right)^{-1}
    =\left(\pmb{\delta}_-(\lambda)^\dagger\right)^{-1}\\
    &=\left(\mathbb{I}_2+\mathbf{R}^\dagger\mathbf{R}\right)(\pmb{\delta}_+^\dagger(\lambda))^{-1}
    =\left(\mathbb{I}_2+\mathbf{R}^\dagger\mathbf{R}\right)
    \lim_{\varepsilon\rightarrow0_+}\left(\pmb{\delta}^\dagger(\lambda+\ii\varepsilon)\right)^{-1}\\
    &=\left(\mathbb{I}_2+\mathbf{R}^\dagger\mathbf{R}\right)\lim_{\varepsilon\rightarrow0_+}\mathbf{g}(\lambda-\ii\varepsilon)
    =\left(\mathbb{I}_2+\mathbf{R}^\dagger\mathbf{R}\right)\mathbf{g}_-(\lambda).
  \end{aligned}
\end{equation*}
Noticing the uniqueness of the solution for the matrix RHP \eqref{RHP-delta}, we have
\begin{equation}\label{symmetry-delta}
  \pmb{\delta}(\lambda)=[\pmb{\delta}^\dagger(\lambda^*)]^{-1}.
\end{equation}
Inserting equation \eqref{symmetry-delta} into equation \eqref{RHP-delta}, we obtain
\begin{equation*}
  \begin{aligned}
      &
      |\pmb{\delta}_-(\lambda)|^2= 
      \begin{cases}
        2-\frac{|\mathbf{R}(\lambda)|^2}{1+|\mathbf{R}(\lambda)|^2},\\
        2,
      \end{cases} 
      &
      \begin{aligned}
        &\lambda<\xi,\\
        &\lambda>\xi,
      \end{aligned}\\
      &
      |\pmb{\delta}_+(\lambda)|^2= 
      \begin{cases}
        2+|\mathbf{R}(\lambda)|^2,\\
        2, 
      \end{cases}
      &
      \begin{aligned}
        &\lambda<\xi,\\
        &\lambda>\xi,
      \end{aligned}
  \end{aligned}
\end{equation*}
for $\lambda\in\mathbb{R}$. Similarly, we have
\begin{equation*}
  \det\pmb{\delta}(\lambda)(\det\pmb{\delta}(\lambda^*))^*=1,
\end{equation*}
then for real $\lambda$,
\begin{equation*}
  |\det\pmb{\delta}_+(\lambda)|=|\det\pmb{\delta}_-^{-1}(\lambda)|
  =\left(1+|\mathbf{R}(\lambda)|^2\right)^{\frac{1}{2}},
  \quad\lambda<\xi.
\end{equation*}
Hence, by the maximum principle, we obtain the boundedness of $\det\pmb{\delta}$ and $\pmb{\delta}$
\begin{equation}\label{bdd-delta}
  |\left(\det\pmb{\delta}(\lambda)\right)^{\pm1}|\leq const<\infty,
  \quad|\pmb{\delta}^{\pm1}(\lambda)|\leq const<\infty
\end{equation}
for any $\lambda\in\mathbb{C}$.

Now we utilize $\det\pmb{\delta}$ and $\pmb{\delta}$ to define a new function $\M^{(1)}(\lambda)$
\begin{equation}\label{def-Delta}
  \M^{(1)}(\lambda)= \M(\lambda)\pmb{\Delta}^{-1}(\lambda),
  \quad\pmb{\Delta}(\lambda)=
  \begin{pmatrix}
    \det\pmb{\delta}(\lambda)&0\\
    0&\pmb{\delta}^{-1}(\lambda)
  \end{pmatrix},
\end{equation}
and $\M^{(1)}(\lambda)$ satisfies the following RHP.

\begin{rhp}\label{rhp-M1}
  Find an analytic function $\M^{(1)}$: 
$\mathbb{C}\setminus\mathbb{R}\rightarrow SL_{2}(\mathbb{C})$ 
with the following properties
\begin{itemize}
  \item[1.] $\M^{(1)}(\lambda)=\mathbb{I}_{3}+\mathcal{O}\left(\lambda^{-1}\right)$ as $\lambda\rightarrow\infty.$
  \item[2.] For each $\lambda\in\mathbb{R}$ (with $\mathbb{R}$ oriented left-to-right),
  $\M^{(1)}$ takes continuous boundary values $\M^{(1)}_{\pm}(\lambda)$ which satisfy 
  the jump relation: $\M_+^{(1)}(\lambda)=\M_-^{(1)}(\lambda)\V^{(1)}(\lambda)$ where
  \begin{equation*}
   \V^{(1)}(\lambda)=
   \begin{cases}
    \begin{pmatrix}
      1 & -\det\pmb{\delta}\ee^{-2\ii t\theta}\mathbf{R}(\lambda)\pmb{\delta}\\
      0 & \mathbb{I}_2
    \end{pmatrix}
    \begin{pmatrix}
      1 & 0\\
      -(\det\pmb{\delta})^{-1}\ee^{2\ii t\theta}\pmb{\delta}^{-1}\mathbf{R}^\dagger(\lambda) & \mathbb{I}_2
    \end{pmatrix},
    &\lambda\in(\xi,+\infty),\\
    \begin{pmatrix}
      1 & 0\\
      -(\det\pmb{\delta}_-)^{-1}\ee^{2\ii t\theta}\pmb{\delta}_-^{-1}
      \frac{\mathbf{R}^\dagger(\lambda)}{1+\mathbf{R}\mathbf{R}^\dagger} & \mathbb{I}_2
    \end{pmatrix}
    \begin{pmatrix}
      1 & -\det\pmb{\delta}_+\ee^{-2\ii t\theta}
      \frac{\mathbf{R}(\lambda)}{1+\mathbf{R}\mathbf{R}^\dagger}\pmb{\delta}_+\\
      0 & \mathbb{I}_2
    \end{pmatrix},
    &\lambda\in(-\infty,\xi).
   \end{cases}
  \end{equation*}
\end{itemize}
\end{rhp}
