and the Cauchy operator
\begin{equation}
  (C_{\mathbb{R}} h)(z)=\int\limits_{\mathbb{R}}\frac{h(s)}{s-z}\frac{ds}{2\pi \ii} 
  ,\quad z\in\mathbb{C}\setminus\mathbb{R}.
\end{equation}

