    \begin{pmatrix}
      1 & 0\\
      (\det\pmb{\delta})^{-1}\ee^{2\ii t\theta}\pmb{\delta}^{-1}[\mathbf{R}^\dagger](\lambda) & \mathbb{I}_2
     \end{pmatrix},  
    &\lambda \in\Omega_1,\\
    \begin{pmatrix}
      1 & \det\pmb{\delta} \ee^{-2\ii t\theta}
      [\frac{\mathbf{R}(\lambda)}{1+\mathbf{R}\mathbf{R}^\dagger}]\pmb{\delta}\\
      0 & \mathbb{I}_2
    \end{pmatrix},
    &\lambda \in\Omega_3,\\
    \begin{pmatrix}
      1 & 0\\
      -(\det\pmb{\delta})^{-1}\ee^{2\ii t\theta}\pmb{\delta}^{-1}
      [\frac{\mathbf{R}^\dagger(\lambda)}{1+\mathbf{R}\mathbf{R}^\dagger}] & \mathbb{I}_2
    \end{pmatrix},
    &\lambda \in \Omega_4,\\
    \begin{pmatrix}
      1 & -\det\pmb{\delta} \ee^{-2\ii t\theta}[\mathbf{R}](\lambda)\pmb{\delta}\\
      0 & \mathbb{I}_2
    \end{pmatrix}  ,
    &\lambda \in\Omega_6,\\
    \mathbb{I}_3,
    &\lambda \in\Omega_2\cup\Omega_5,
  \end{cases} 
\end{equation}
and we set $\M^{(3)}=\M^{(2)}\mathbf{\Xi}$. 
Direct calculation shows that $\M^{(3)}$ satisfies the following RHP.

\begin{rhp}\label{rhp-M3}
  Find an analytic function $\M^{(3)}$: 
$\mathbb{C}\setminus\Sigma\rightarrow SL_{2}(\mathbb{C})$ 
with the following properties
\begin{itemize}
  \item[1.] $\M^{(3)}(\lambda)=\mathbb{I}_{3}+\mathcal{O}\left(\lambda^{-1}\right)$ as $\lambda\rightarrow\infty.$
  \item[2.] For each $\lambda\in\Sigma$ ,
  $\M^{(3)}$ takes continuous boundary values $\M^{(3)}_{\pm}(\lambda)$ which satisfy 
  the jump relation: $\M_+^{(3)}(\lambda)=\M_-^{(3)}(\lambda)\V^{(3)}(\lambda)$ where
  \begin{equation*}
   \V^{(3)}(\lambda)=
   \begin{cases}
    \begin{pmatrix}
      1 & 0\\
      -(\det\pmb{\delta})^{-1}\ee^{2\ii t\theta}\pmb{\delta}^{-1}[\mathbf{R}^\dagger](\lambda) & \mathbb{I}_2
     \end{pmatrix},  
    &\lambda \in\Sigma_1,\\
    \begin{pmatrix}
      1 & -\det\pmb{\delta} \ee^{-2\ii t\theta}
      [\frac{\mathbf{R}(\lambda)}{1+\mathbf{R}\mathbf{R}^\dagger}]\pmb{\delta}\\
      0 & \mathbb{I}_2
    \end{pmatrix},
    &\lambda \in\Sigma_2,\\
    \begin{pmatrix}
      1 & 0\\
      -(\det\pmb{\delta})^{-1}\ee^{2\ii t\theta}
      [\frac{\mathbf{R}^\dagger(\lambda)}{1+\mathbf{R}\mathbf{R}^\dagger}] & \mathbb{I}_2
    \end{pmatrix},
    &\lambda \in \Sigma_3,\\
    \begin{pmatrix}
      1 & -\det\pmb{\delta} \ee^{-2\ii t\theta}[\mathbf{R}](\lambda)\pmb{\delta}\\
      0 & \mathbb{I}_2
    \end{pmatrix},
    &\lambda \in\Sigma_4.
   \end{cases}
  \end{equation*}
\end{itemize}
\end{rhp}
Because $\mathbf{\Xi}$ is analytic and uniformly bounded in 
$\mathbb{C}\setminus(\mathbb{R}\cup\Sigma)$ for all $x\in\mathbb{R}$ and $t>0$, we can obtain the 
following lemma.

\begin{lemma}
  (cf. \cite[pp.1044-1045]{deift2002long}) 
The operator $(1-C_{\mathbf{w}_e})^{-1}$ is bounded in $L^2(\mathbb{R}\cup\Sigma)$ if and 
only if $(1-C_{\mathbf{w}_3})^{-1}$ is bounded in $L^2(\Sigma)$.
\end{lemma} 


The key point to note is that RHP \ref{rhp-M2} has been transformed into RHP \ref{rhp-M3} 
with jump matrix $\V^{(3)}$, where all the exponential factors $\ee^{\pm \ii\theta}$ are now 
exponentially decreasing. Then we need to provide some estimates on $\det\pmb{\delta}(\lambda)$. 
By equation \eqref{RHP-det-delta}, the expression of $\det\pmb{\delta}$ can be rewritten as 
\begin{equation}
  \det\pmb{\delta}(\lambda)=
  \exp\left(C_{(-\infty,\xi)}\ln\left(1+\left|\mathbf{R}\right|^2\right)(\lambda)\right),\quad
  \lambda\in\mathbb{C}\setminus(-\infty,\xi). 
\end{equation}
Let $\chi(s)$ denote the characteristics function of the interval 
$(\xi-1,\xi)$. For 
$\lambda\in\mathbb{C}\setminus(-\infty,\xi)$,
\begin{equation*}
  \begin{aligned}
  &\quad C_{(-\infty,\xi)}\ln\left(1+\left|\mathbf{R}\right|^2\right)(\lambda) \\
  &=\int_{-\infty}^{\xi}\left(\ln\left(1+|\mathbf{R}(s)|^2\right)-
  \ln\left(1+|\mathbf{R}(\xi)|^2\right)
  \chi(s)(s-\xi+1)\right)\frac{\dd s}{2\pi \ii(s-\lambda)} \\
  &\quad+\ln\left(1+\left|\mathbf{R}(\xi)\right|^2\right)
  \int_{\xi-1}^{\xi}\frac{s-\xi+1}{s-\lambda}\frac{\dd s}{2\pi \ii} \\
  &=\beta(\lambda,\xi)+\ii\kappa(\xi)(1-(\lambda-\xi+1)\ln(\lambda-\xi+1) \\
  &\quad+(\lambda-\xi)\ln(\lambda-\xi)+\ln(\lambda-\xi)),
  \end{aligned}
\end{equation*}
where $\kappa(\xi)=-\frac{1}{2\pi}\ln\left(1+|\mathbf{R}(\xi)|^2\right)$ as defined in equation \eqref{def-kappa}, and 
\begin{equation*}
    \quad\beta(\lambda,\xi)
    =\int_{-\infty}^{\xi}\left(\ln(1+|\mathbf{R}(s)|^2)-\ln(1+|\mathbf{R}(\xi)|^2)
    \chi(s)(s-\xi+1)\right)\frac{ds}{2\pi \ii(s-\lambda)}.
\end{equation*}
We decompose $\det\pmb{\delta}$ as
\begin{equation*}
  \det\pmb{\delta}=\delta_0\delta_1,
\end{equation*}
where
\begin{equation*}
  \delta_0=\ee^{\beta(\xi,\xi)+\ii\kappa(\xi)}(\lambda-\xi)^{\ii\kappa(\xi)},
  \quad\delta_1=\ee^{\zeta(\lambda,\xi)},
\end{equation*}
and 
\begin{equation*}
  \zeta(\lambda,\xi)=(\beta(\lambda,\xi)-\beta(\xi,\xi))
    +\ii\kappa(\xi)\Big((\lambda-\xi)\ln(\lambda-\xi)-(\lambda-\xi+1)\ln(\lambda-\xi+1)\Big).
\end{equation*}
Then we will utilize $\delta_0$ to construct a solvable model RHP \ref{rhp-M4} 
whose solution $\M^{(4)}$ is a suitable approximation to $\M^{(3)}$.
% Define $\M^{(4)}$ satisfies the following RHP.

\begin{rhp}\label{rhp-M4}
  Find an analytic function $\M^{(4)}$: 
$\mathbb{C}\setminus\Sigma\rightarrow SL_{2}(\mathbb{C})$ 
with the following properties
\begin{itemize}
  \item[1.] $\M^{(4)}(\lambda)=\mathbb{I}_{3}+\mathcal{O}\left(\lambda^{-1}\right)$ as $\lambda\rightarrow\infty.$
  \item[2.] For each $\lambda\in\Sigma$ ,
  $\M^{(4)}$ takes continuous boundary values $\M^{(4)}_{\pm}(\lambda)$ which satisfy 
  the jump relation: $\M_+^{(4)}(\lambda)=\M_-^{(4)}(\lambda)\V^{(4)}(\lambda)$ where
  \begin{equation}\label{jump-parabolic-cylinder-model}
   \V^{(4)}(\lambda)=
   \begin{cases}
    \begin{pmatrix}
      1 & 0\\
      -\pmb{\delta}_0^{-2}\ee^{2\ii t\theta}\mathbf{R}^\dagger(\xi) & \mathbb{I}_2
     \end{pmatrix},
    &\lambda \in\Sigma_1,\\
    \begin{pmatrix}
      1 & -\pmb{\delta}_0^2 \ee^{-2\ii t\theta}
      \frac{\mathbf{R}}{1+\mathbf{R}\mathbf{R}^\dagger}(\xi)\\
      0 & \mathbb{I}_2
    \end{pmatrix},
    &\lambda \in\Sigma_2,\\
    \begin{pmatrix}
      1 & 0\\
      -\pmb{\delta}_0^{-2}\ee^{2\ii t\theta}
      \frac{\mathbf{R}^\dagger}{1+\mathbf{R}\mathbf{R}^\dagger}(\xi) & \mathbb{I}_2
    \end{pmatrix},
    &\lambda \in \Sigma_3,\\
    \begin{pmatrix}
      1 & -\pmb{\delta}_0^2 \ee^{-2\ii t\theta}\mathbf{R}(\xi)\\
      0 & \mathbb{I}_2
    \end{pmatrix},  
    &\lambda \in\Sigma_4.
   \end{cases}
  \end{equation}
\end{itemize}
\end{rhp}
Next we will provide a proper estimate between jump matrices $\V^{(3)}(\lambda)$ and 
$\V^{(4)}(\lambda)$. Compared to the estimate in the 
scalar case \cite{deift2002long}, the main challenge lies in providing 
a proper estimate on $\pmb{\delta}$ without a closed form. To address this challenge, 
the key idea is using $\det\pmb{\delta}$ with 
explicit expression given in equation \eqref{def-kappa} to approximate $\pmb{\delta}$.  
We decompose the estimate between 
$\V^{(3)}(\lambda)$ and $\V^{(4)}(\lambda)$ into two parts, as shown in equation 
\eqref{decompose-V3-V4}. The first part, which 
does not involve $\pmb{\delta}$, can be estimated similarly to the scalar case \cite{deift2002long}. For 
the estimate on the second part, we construct a non-homogeneous RHP defined in 
equation \eqref{non-homogeneous-RHP}, whose solution $\tilde{\pmb{\delta}}$ represents 
the estimate between $\pmb{\delta}$ and $\det\pmb{\delta}$.

\begin{lemma}\label{bdd-V3-V4}
  For $1\leq p\leq\infty$,
\begin{equation*}
  \left\|\V^{(3)}-\V^{(4)}\right\|_{L^p(\Sigma)}\leq
  \frac c{t^{1/4+1/(2p)}}\quad\textit{uniformly for }
  t\geq1\mathrm{~and~all~}x\in\mathbb{R}\mathrm{~.}
\end{equation*}
\end{lemma}
\begin{proof}
We give the details of the estimate on the contour $\Sigma_4$ only, the situation 
  on the other rays in $\Sigma$ is similar.
  For $\lambda=\xi+ue^{-\ii\pi/4},u\ge0$,
  \begin{equation}\label{decompose-V3-V4}
    \begin{aligned}
      &\quad\left|\V^{(3)}-\V^{(4)}\right|\\
      &\le\left|[\mathbf{R}](\det\pmb{\delta})^2\ee^{-2\ii t\theta}
      -\mathbf{R}(\xi)\pmb{\delta}_0^2\ee^{-2\ii t\theta}\right|
      +\left|[\mathbf{R}]\pmb{\delta} (\det\pmb{\delta}) \ee^{-2\ii t\theta}-[\mathbf{R}](\det\pmb{\delta})^2
      \ee^{-2\ii t\theta}\right|\\
      &\le D+\left|\det\pmb{\delta}\right|\ee^{-t\left|\lambda-\xi\right|^2}
      |\tilde{\pmb{\delta}}|,
    \end{aligned}
  \end{equation}
  where $\tilde{\pmb{\delta}}=[\mathbf{R}]\pmb{\delta} \ee^{-\ii t\theta}-[\mathbf{R}](\det\pmb{\delta})\ee^{-\ii t\theta}$.
  According to \cite[pp.1047]{deift2002long}, we derive the estimate 
  $D\lesssim t^{-1/4}\ee^{-t\left|\lambda-\xi\right|^2}$. 
  By the boundedness of $\det\pmb{\delta}$, it suffices to estimate $\tilde{\pmb{\delta}}$. 
  It follows from equations \eqref{RHP-delta} and \eqref{RHP-det-delta} that $\tilde{\pmb{\delta}}$ satisfies the following 
  RHP:
  \begin{equation}\label{non-homogeneous-RHP}
    \begin{cases}\tilde{\pmb{\delta}}_+(\lambda)=\tilde{\pmb{\delta}}_-(\lambda)
      (1+|\mathbf{R}(\lambda)|^2)+\mathbf{f}(\lambda)\pmb{\delta}_-\ee^{-\ii t\theta},
      &\quad \lambda\in(-\infty,\xi),\\
      \tilde{\pmb{\delta}}(\lambda)\to0,
      &\quad \lambda\to\infty,
    \end{cases}
  \end{equation}
  where 
  $\mathbf{f}(\lambda)=([\mathbf{R}](\mathbf{R}^\dagger\mathbf{R}-\mathbf{R}\mathbf{R}^\dagger\mathbb{I}_2))(\lambda)$. 

  The solution for the above RHP can be expressed as follow
  \begin{equation*}
    \begin{aligned}
      &\tilde{\pmb{\delta}}(\lambda)=X(\lambda)\int_{-\infty}^{\xi}
      \frac{\mathbf{f}(s)\pmb{\delta}_-(s)\ee^{-\ii t\theta(s)}}{X_+(s)(s-\lambda)}\mathrm{d}s,\\
      &X(\lambda)=\exp\left(\frac1{2\pi \ii}\int_{-\infty}^{\xi}
      \frac{\ln\left(1+|\mathbf{R}(\lambda)|^2\right)}{s-\lambda}\mathrm{d}s\right).
    \end{aligned}
  \end{equation*}
  Clearly, since $\mathbf{R}$ belongs to the Sobolev space $H^{1,1}(\mathbb{R})$, 
  it follows that $\mathbf{f}$ also lies in $H^{1,1}(\mathbb{R})$. Notably, we have $\mathbf{f}(\xi)=0$, which implies that 
  $\left|\mathbf{f}(\lambda)\right|\leq\left|\lambda-\xi\right|^{1/2}\|\mathbf{f}\|_{H^{1,1}}$. 
  Additionally, the boundedness of $X^{\pm1}(\lambda)$ is similar to that of $(\det\pmb{\delta}(\lambda))^{\pm1}$ and then we have 
  \begin{equation*}
    \begin{aligned}
      |\tilde{\pmb{\delta}}(\lambda)|&\le|X(\lambda)|
      \left|\int_{-\infty}^{\xi}
      \frac{\mathbf{f}(s)\pmb{\delta}_-\ee^{-\ii t\theta}}{X_+(s)(s-\lambda)}\mathrm{d}s\right|\\
      &\lesssim\left|\int_{\xi-t^{-1/2}}^{\xi}
      \frac{\mathbf{f}(s)\pmb{\delta}_-\ee^{-\ii t\theta}}{X_+(s)(s-\lambda)}\mathrm{d}s\right|+
      \left|\int_{-\infty}^{\xi-t^{-1/2}}
      \frac{\mathbf{f}(s)\pmb{\delta}_-\ee^{-\ii t\theta}}{X_+(s)(s-\lambda)}\mathrm{d}s\right|\\
      &\lesssim \mathrm{I}+\mathrm{II}.
    \end{aligned}
  \end{equation*}
  For $\mathrm{I}$, we use the fact that 
  \begin{equation}
    \frac{1}{\left|s-\lambda\right|}\le\frac{2}{\left|s-\xi\right|},\quad
    \forall\lambda\in\Sigma,s\in(-\infty,\xi).
  \end{equation}
  Then we obtain
  \begin{equation*}
    \begin{aligned}
      \mathrm{I}&\le\|X_+^{-1}\|_{L^\infty} \|\pmb{\delta}_-\|_{L^\infty}
      \int_{\xi-t^{-1/2}}^{\xi}
      \frac{|\mathbf{f}(s)|}{|s-\lambda|}\mathrm{d}s\\
      &\lesssim\int_{\xi-t^{-1/2}}^{\xi}
      \frac{\left|s-\xi\right|^{1/2}}{|s-\xi|}\mathrm{d}s\\
      &\lesssim t^{-1/4}.
    \end{aligned}
  \end{equation*}
  For $\mathrm{II}$, we can decompose it into five parts:
  \begin{equation*}
    \begin{aligned}
      \mathrm{II}
      &=\left|\int_{-\infty}^{\xi-t^{-1/2}}\frac{X^{-1}_+(s)\mathbf{f}(s)\pmb{\delta}_-(s)}{(s-\lambda)}
      \frac{\dd\ee^{-\ii t\theta(s)}}{-2\ii t(s-\xi)}\right|\\
      &\le\left|\left.\frac{X^{-1}_+(s)\mathbf{f}(s)\pmb{\delta}_-(s)}{2\ii t(s-\lambda)(s-\xi)}\right|
      _{s=\xi-t^{-1/2}}\right|+
      \frac{1}{2 t}\int_{-\infty}^{\xi-t^{-1/2}}
      \left|\frac{(X^{-1}_+(s))^{\prime}\mathbf{f}(s)\pmb{\delta}_-(s)}{(s-\lambda)(s-\xi)}\right|\dd s\\
      &+
      \frac{1}{2 t}\int_{-\infty}^{\xi-t^{-1/2}}
      \left|\frac{X^{-1}_+(s)\mathbf{f}^{\prime}(s)\pmb{\delta}_-(s)}{(s-\lambda)(s-\xi)}\right|
      +\left|\frac{X^{-1}_+(s)\mathbf{f}(s)(\pmb{\delta}_-(s))^{\prime}}{(s-\lambda)(s-\xi)}\right|
      +\left|X^{-1}_+(s)\mathbf{f}(s)\pmb{\delta}_-(s)\left(\frac{1}{(s-\lambda)(s-\xi)}\right)^{\prime}\right|\dd s\\
      &\le\mathrm{II}_1+\mathrm{II}_2+\mathrm{II}_3+\mathrm{II}_4+\mathrm{II}_5.
    \end{aligned}
  \end{equation*}
  For $\mathrm{II}_1$, we have 
  \begin{equation*}
    \mathrm{II}_1\lesssim t^{-1}\frac{|\mathbf{f}(\xi-t^{-1/2})|}{|\xi-t^{-1/2}-\xi|^2}\lesssim t^{-1/4}.
  \end{equation*}
  Next, for $\mathrm{II}_2$, we first consider the boundedness of $(X^{-1}_+)^{\prime}$,
  \begin{equation*}
    \begin{aligned}
      \left|(X^{-1}_+)^{\prime}\right|
      &=\left|\frac{\dd}{\dd\lambda}\exp\{-C^+_{(-\infty,\xi)}(\ln(1+\mathbf{R}\mathbf{R}^\dagger))\}\right|\\
      &=\left|X^{-1}_+\frac{\dd}{\dd\lambda}C^+_{(-\infty,\xi)}(\ln(1+\mathbf{R}\mathbf{R}^\dagger))\right|\\
      &\lesssim\left|-\int_{-\infty}^{\xi}\frac{\ln(1+\mathbf{R}\mathbf{R}^\dagger)}{2\pi \ii}
      \dd\frac{1}{s-\lambda}\right|\\
      &\leq\left|\frac{1}{2\pi \ii}\ln(1+\mathbf{R}\mathbf{R}^\dagger(\xi))\frac{1}{\lambda-\xi}
      \right|+\left|C^+_{(-\infty,\xi)}\left(\frac{\mathbf{R}^{'}\mathbf{R}^\dagger+\mathbf{R}(\mathbf{R}^\dagger)^{\prime}}
      {1+\mathbf{R}\mathbf{R}^\dagger}\right)\right|\\
      &\equiv\mathrm{II}^{(1)}+\mathrm{II}^{(2)}.
    \end{aligned}
  \end{equation*}
  Clearly, we can obtain the following two properties 
  \begin{equation*}
    \mathrm{II}^{(1)}\lesssim\frac{1}{\left|\lambda-\xi\right|},\quad
    \|\mathrm{II}^{(2)}\|_{L^{2}}\lesssim
    \|\mathbf{R}^{\prime}\mathbf{R}^\dagger+\mathbf{R}(\mathbf{R}^\dagger)^{\prime}\|_{L^{2}}
    \leq C.
  \end{equation*}
  Then we obtain 
  \begin{equation*}
    \begin{aligned}
      |\mathrm{II}_2|
      &\lesssim t^{-1}
      \int_{-\infty}^{\xi-t^{-1/2}}
      \frac{(|\mathrm{II}^{(1)}|+|\mathrm{II}^{(2)}|)\left|\mathbf{f}\right|}
      {\left|s-\xi\right|^2}\dd s\\
      &\lesssim t^{-1}(\int_{-\infty}^{\xi-t^{-1/2}}
      \frac{\left|s-\xi\right|^{1/2}}{\left|s-\xi\right|^3}\dd s
      +\|\mathrm{II}^{(2)}\|_{L^{2}}\|\mathbf{f}\|_{L^{\infty}}
      (\int_{-\infty}^{\xi-t^{-1/2}}\frac{1}{\left|s-\xi\right|^4}\dd s)^{1/2})\\
      &\lesssim t^{-\frac{1}{4}}.
    \end{aligned}
  \end{equation*}
  For $\mathrm{II}_3$, we have 
  \begin{equation*}
    \left|\mathrm{II}_3\right|\lesssim t^{-1}\|\mathbf{f}^{\prime}\|_{L^2(\mathbb{R})}
    \|(s-\xi)^{-2}\|_{L^2(-\infty,\xi-t^{-1/2})}\lesssim t^{-1/4}.
  \end{equation*}
  For $\mathrm{II}_4$, we begin by considering the boundedness of 
  $\|\pmb{\delta}_-^{\prime}\|_{L^2(\mathbb{R})}$. 
    It follows from equation \eqref{RHP-delta} that $\pmb{\delta}^{\prime}$ satisfies the following RHP:
    \begin{equation}
  	\begin{cases}
  	\pmb{\delta}^{\prime}_+(\lambda)=
  	(\mathbb{I}_2+\mathbf{R}^\dagger\mathbf{R})\pmb{\delta}^{\prime}_-(\lambda)
  	+g(\lambda),\quad&\lambda<\xi,\\
  	\pmb{\delta}^{\prime}(\lambda)\rightarrow0, &\lambda\rightarrow\infty.
  	\end{cases}
    \end{equation}
    where $g(\lambda)=(\mathbf{R}^\dagger\mathbf{R}^{\prime}+
    (\mathbf{R}^\dagger)^{\prime}\mathbf{R})\pmb{\delta}_-$.

    The solution for the above RHP can be expressed as follow,
    \begin{equation*}
  	\pmb{\delta}^{\prime}(\lambda)=\mathbf{Y}(\lambda)\int_{-\infty}^{\xi}
  	\frac{\mathbf{Y}_+^{-1}(s)g(s)}{(s-\lambda)}\mathrm{d}s,
    \end{equation*}
    where $\mathbf{Y}(\lambda)$ satisfies the following RHP:
    \begin{equation}
  	\begin{cases}
  	\mathbf{Y}_+(\lambda)=
  	(\mathbb{I}_2+\mathbf{R}^\dagger\mathbf{R})\mathbf{Y}_-(\lambda),\quad&\lambda<\xi,\\
  	\mathbf{Y}(\lambda)\rightarrow\mathbb{I}_2, &\lambda\rightarrow\infty.
  	\end{cases}
    \end{equation}
    By the uniqueness of RHP \eqref{RHP-delta} and equation \eqref{bdd-delta}, 
    we can deduce the boundedness of solution $\mathbf{Y}(\lambda)$ such that 
    \begin{equation}
      \left|\mathbf{Y}^{\pm1}(\lambda)\right|\lesssim 1\ \ \text{for any }\lambda\in\mathbb{C}.
    \end{equation}
    Then we can show 
    \begin{equation*}
      \begin{aligned}
        \|\pmb{\delta}^{\prime}_-(\lambda)\|_{L^2(\mathbb{R})}
        &\lesssim \|C^-_{(-\infty,\xi)}(\mathbf{Y}_+^{-1}g)\|_{L^2(\mathbb{R})}
        \lesssim \|\mathbf{Y}_+^{-1}g\|_{L^2(\mathbb{R})}\\
        &\lesssim \|\mathbf{R}^\dagger\mathbf{R}^{\prime}+
        (\mathbf{R}^\dagger)^{\prime}\mathbf{R}\|_{L^2(\mathbb{R})}
        \lesssim 1.
      \end{aligned}
      \end{equation*}
  It follows from the fact that $\pmb{\delta}^\prime\in L^2(\mathbb{R})$ that 
  \begin{equation*}
    \left|\mathrm{II}_4\right|\lesssim t^{-1}\|\pmb{\delta}_-^{\prime}\|_{L^2}
    \|(s-\xi)^{-2}\|_{L^2(-\infty,\xi-t^{-1/2})}\lesssim t^{-1/4}.
  \end{equation*}
  For $\mathrm{II}_5$, we have
  \begin{equation*}
    \left|\mathrm{II}_5\right|\lesssim t^{-1}\int_{-\infty}^{\xi-t^{-1/2}}
    \frac{\left|s-\xi\right|^{1/2}}{\left|s-\xi\right|^3}ds\lesssim t^{-1/4}.
  \end{equation*}
  Therefore, we can deduce $\mathrm{II}\lesssim t^{-1/4}$. 
  Together with $\mathrm{I}\lesssim t^{-1/4}$, 
  this implies that $|\tilde{\pmb{\delta}}|\lesssim t^{-1/4}$. By adding 
  the estimates for $D$ and 
  $|\tilde{\pmb{\delta}}|$, we obtain 
  \begin{equation}
    \left|\V^{(3)}-\V^{(4)}\right|\lesssim t^{-1/4}\ee^{-t\left|\lambda-\xi\right|^2}. 
  \end{equation}
  Then the result follows immediately
  \begin{equation}
    \left\|\V^{(3)}-\V^{(4)}\right\|_{L^p(\Sigma)}\lesssim
    t^{-1/4}(\int_{0}^{+\infty}\ee^{-tu^{2p}}du)^{1/p}
    \lesssim t^{-1/4-1/(2p)}.
  \end{equation}
\end{proof}

