By Lemma \ref{bdd-V3-V4}, we can show that the 
operator $(1-C_{\mathbf{w}_3})^{-1}$ exists and is bounded in $L^2(\Sigma)$, which 
guarantees the existence of solution $\M^{(3)}$.


\begin{lemma}
  For sufficiently large $t>t_0$ , 
the operator $(1-C_{\mathbf{w}_3})^{-1}$ exists and is bounded in $L^2(\Sigma)$ 
for all $x\in\mathbb{R}$.
\end{lemma}

\begin{proof}
  By \cite[pp.1049]{deift2002long}, the bound on $(1-C_{\mathbf{w}_4})^{-1}$ in $L^2(\Sigma)$ is equivalent to 
  the bound on $(1-C_{\tilde{\mathbf{w}}})^{-1}$ in $L^2(\mathbb{R})$, where
  \begin{equation*}
    \tilde{\V}=
     \begin{pmatrix}
       1+|\mathbf{R}(\xi)|^2&-\mathbf{R}(\xi)\ee^{-2\ii t\theta}\\
       -\mathbf{R}^\dagger(\xi)\ee^{2\ii t\theta}&\mathbb{I}_2
     \end{pmatrix}.
  \end{equation*}
  But the bound on $(1-C_{\tilde{\mathbf{w}}})^{-1}$ can be ensured by the same argument as 
  $(1-C_{\mathbf{w}})^{-1}$ in Lemma \ref{bdd-w}. Hence $(1-C_{\mathbf{w}_4})^{-1}$ is bounded in $L^2(\Sigma)$.
  Set $\mathbf{w}_{3}=(\mathbf{w}^{-}_3=0,\mathbf{w}^{+}_3=\V^{(3)}-\mathbb{I}_3)$ and 
  $\mathbf{w}_{4}=(\mathbf{w}^{-}_4=0,\mathbf{w}^{+}_4=\V^{(4)}-\mathbb{I}_3)$. 
  By Lemma \ref{bdd-V3-V4},
  \begin{equation*}
    \|C_{\mathbf{w}_3}-C_{\mathbf{w}_4}\|_{L^2}
    =\sup_{\|\mathbf{f}\|_{L^2}=1}\|C^-_{\Sigma}\mathbf{f}(\V^{(3)}-\V^{(4)})\|_{L^2}\lesssim 
    \|\V^{(3)}-\V^{(4)}\|_{L^\infty}\lesssim t^{-\frac{1}{4}}.
  \end{equation*}


  Then we conclude by the resolvent identity that $(1-C_{\mathbf{w}_3})^{-1}$ exists in $L^2(\Sigma)$ 
  for sufficiently large $t>t_0$ and that
  \begin{equation*}
    \left\|(1-C_{{\mathbf{w}_{4}}})^{-1}\right\|_{{L^{2}(\Sigma)}}\lesssim1,
    \quad\left\|(1-C_{{\mathbf{w}_3}})^{-1}-(1-C_{{\mathbf{w}_4}})^{-1}\right\|_{{L^{2}}}
    \lesssim t^{-\frac{1}{4}},
  \end{equation*}
  uniformly for all $x\in\mathbb{R}$ and $t>t_0$. By \cite[Proposition 2.6 and Corollary 2.7]{deift2002long}, $(1-C_{\mathbf{w}_3})^{-1}$ exists and is bounded in $L^2(\Sigma)$ for any 
  factorization and hence the result follows immediately.
\end{proof}

From the previous results,  we observe that for sufficiently large $t>t_0$,  
$(1-C_{\mathbf{w}_i})^{-1}$ exists and is bounded in $L^2$, for $i=1,2,3,4$.

We now reverse the orientation
on $(-\infty,\xi)$ of RHP \ref{rhp-M1}, as shown in figure \ref{initial-contour} to obtain a contour 
$\mathbb{R}_\xi=(\ee^{\ii\pi}\mathbb{R}_++\xi)\cup(\mathbb{R}_++\xi)$ with associated jump matrix
$\hat{\V}^{(1)}=\V^{(1)}$ for $\lambda>\xi$ and $\hat{\V}^{(1)}=\left(\V^{(1)}\right)^{-1}$ 
for $\lambda<\xi$. 
From the form of $\hat{\V}^{(1)}$, we see that 
$\hat{\V}^{(1)}=(\mathbb{I}_{3}-\hat{\mathbf{w}}_1^-)^{-1}(\mathbb{I}_{3}+\hat{\mathbf{w}}_1^+)$, where
\begin{equation*}
  \begin{aligned}
    \hat{\mathbf{w}}_1
    &=(\hat{\mathbf{w}}^-_1,\hat{\mathbf{w}}^+_1)\\
    &=\begin{cases}
      \left(
        \begin{pmatrix}
          0&-\det\pmb{\delta} \ee^{-2\ii t\theta}\mathbf{R}(\lambda)\pmb{\delta}\\
          0&0\end{pmatrix},
        \begin{pmatrix}0&0\\
          -(\det\pmb{\delta})^{-1}\ee^{2\ii t\theta}\pmb{\delta}^{-1}\mathbf{R}^\dagger(\lambda)&0
        \end{pmatrix}
      \right),&\lambda>\xi ,\\
      \left(
        \begin{pmatrix}
          0&\det\pmb{\delta}_+\ee^{-2\ii t\theta}
          \frac{\mathbf{R}(\lambda)}{1+\mathbf{R}\mathbf{R}^\dagger}\pmb{\delta}_+\\
          0&0
        \end{pmatrix},
        \begin{pmatrix}
          0&0\\
          (\det\pmb{\delta}_-)^{-1}\ee^{2\ii t\theta}\pmb{\delta}_-^{-1}
          \frac{\mathbf{R}^\dagger(\lambda)}{1+\mathbf{R}\mathbf{R}^\dagger}&0
        \end{pmatrix}
        \right),&\lambda<\xi .
      \end{cases}
    \end{aligned}
  \end{equation*}
  Observe that if we reverse the orientation as above 
  for the RHP \ref{rhp-M2}, we obtain a new RHP with 
  contour $\mathbb{R}_\xi$ and jump matrix 
  $\hat{\V}^{(2)}=(\mathbb{I}_{3}-\hat{\mathbf{w}}_2^-)^{-1}(\mathbb{I}_{3}+\hat{\mathbf{w}}_2^+)$ where 
  $\hat{\mathbf{w}}_2=(\hat{\mathbf{w}}_2^-,\hat{\mathbf{w}}_2^+)$ is the same as $\hat{\mathbf{w}}_1$ except $\mathbf{R}$ 
  is replaced by $[\mathbf{R}]$, etc. 
  Then we can obtain the following expansion of $\hat{\M}^{(i)}$, for $i=1,2$,
  \begin{equation}
    \hat{\M}^{(i)}(\lambda)=\mathbb{I}_3+\frac{\hat{\M}^{(i)}_1}{\lambda}
    +\oo(\lambda^{-2}),\quad \lambda\rightarrow\infty.
  \end{equation}
  Moreover, the extension $\hat{\M}^{(i)}$ of $\hat{\M}^{(i)}_\pm$ off $\mathbb{R}_\xi$ 
  is the same as the extension $\M^{(i)}$ of $\M^{(i)}_\pm$ off $\mathbb{R}$, for $i=1,2$. 
  Thus we can deduce
  $\hat{\M}^{(i)}_1=\M^{(i)}_1$, for $i=1,2$. 
  By Proposition 2.8 in \cite{deift2002long}, we can also obtain 
  $C_{\hat{\mathbf{w}}_1}=C_{\mathbf{w}_1}$ and hence 
  $\|(1-C_{\hat{\mathbf{w}}_i})^{-1}\|_{L^2(\mathbb{R}_\xi)}\lesssim1$, for $i=1,2$.
  Extend $\mathbb{R}_\xi$ to a contour 
  $\Gamma_{\xi}=\mathbb{R}\cup(\xi+\ee^{\ii\pi/2}\mathbb{R}_-)\cup(\xi+\ee^{-\ii\pi/2}\mathbb{R}_-)$ 
  as shown in figure \ref{extend-contours}. 
  As a complete contour, $\Gamma_{\xi}$ has the important property \cite{deift2002long}
  \begin{equation}\label{complete-contour}
	C_{\Gamma_{\xi}}^+C_{\Gamma_{\xi}}^-
	=C_{\Gamma_{\xi}}^-C_{\Gamma_{\xi}}^+=0.
  \end{equation}


