  Our goal is to prove that $\hat{\M}^{(1)}_1$ is close to $\hat{\M}^{(2)}_1$ with the above
  property \eqref{complete-contour} of complete contour and the following lemmas.






  \begin{lemma}\label{lemma1-CNLS}
	Suppose $1\times2$ vector function $\mathbf{f}\in H^{1,1}(\mathbb{R})$. Then for any $2\leq p<\infty$ and for all $t\ge0$,
  \begin{equation*}
	\begin{cases}
	  \|C^-_{(\xi,+\infty)\rightarrow\Gamma_\xi}
	  (\det\pmb{\delta})^{-1}\ee^{2\ii t\theta}\pmb{\delta}^{-1}\mathbf{f}^\dagger\|_{L^p}
	  \lesssim t^{-1/(2p)},\\
	  \|C^-_{(-\infty,\xi)\rightarrow\Gamma_\xi}
	  (\det\pmb{\delta}_-)^{-1}\ee^{2\ii t\theta}\pmb{\delta}_-^{-1}
	  \mathbf{f}^\dagger|_{L^p}
	  \lesssim t^{-1/(2p)},\\
	  \|C^+_{(\xi,+\infty)\rightarrow\Gamma_\xi}
	  \det\pmb{\delta} \ee^{-2\ii t\theta}\mathbf{f}\pmb{\delta}\|_{L^p}
	  \lesssim t^{-1/(2p)},\\
	  \|C^+_{(-\infty,\xi)\rightarrow\Gamma_\xi}
	  \det\pmb{\delta}_+\ee^{-2\ii t\theta}
	  \mathbf{f}\pmb{\delta}_+\|_{L^p}
	  \lesssim t^{-1/(2p)},
	\end{cases}
  \end{equation*}
  where $\Gamma_{\xi}=\mathbb{R}\cup(\xi+\ee^{\ii\pi/2}\mathbb{R}_-)\cup(\xi+\ee^{-\ii\pi/2}\mathbb{R}_-)$.
  \end{lemma}
  % A proof of Lemma \ref{lemma1-CNLS} is detailed in Appendix A.





  \begin{lemma}\label{lemma2-CNLS}
	Suppose $1\times2$ vector function $\mathbf{f}\in H^{1,1}(\mathbb{R})$, $\mathbf{f}(\xi)=0$ and 
  g is a $2\times2$ vector function in the Hardy space $H^q(\mathbb{C}\setminus\mathbb{R})$. 
  Then for any $2\leq q\le\infty$ and for all $t\ge0$,
  \begin{equation*}
	\begin{cases}
	  \|C^-_{(\xi,+\infty)\rightarrow\Gamma_\xi}
	  \ee^{2\ii t\theta}g_+\mathbf{f}^\dagger\|_{L^2}
	  \lesssim t^{-1/2+1/q}\|g\|_{H^q(\mathbb{C}\setminus\mathbb{R})},\\
	  \|C^-_{(-\infty,\xi)\rightarrow\Gamma_\xi}
	  \ee^{-2\ii t\theta}fg_-|_{L^2}
	  \lesssim t^{-1/2+1/q}\|g\|_{H^q(\mathbb{C}\setminus\mathbb{R})},\\
	  \|C^+_{(\xi,+\infty)\rightarrow\Gamma_\xi}
	  \ee^{-2\ii t\theta}fg_-\|_{L^2}
	  \lesssim t^{-1/2+1/q}\|g\|_{H^q(\mathbb{C}\setminus\mathbb{R})},\\
	  \|C^+_{(-\infty,\xi)\rightarrow\Gamma_\xi}
	  \ee^{2\ii t\theta}g_+\mathbf{f}^\dagger\|_{L^2}
	  \lesssim t^{-1/2+1/q}\|g\|_{H^q(\mathbb{C}\setminus\mathbb{R})}.
	\end{cases}
  \end{equation*}
  \end{lemma}
  The proofs of Lemma \ref{lemma1-CNLS} and Lemma \ref{lemma2-CNLS} 
  are detailed in Appendix A for the sake of completeness. 
  Then we need the following $L^P$ bound on $(1-C_{\mathbf{w}_1})^{-1}$.

  \begin{lemma}\label{Lp-w1}\cite[Proposition 4.5]{deift2002long}
  Suppose that $\mathbf{R}$ is a continuous function on
  $\mathbb{R}$ such that
  \begin{equation*}
	\lim_{\lambda\to\infty}\mathbf{R}(\lambda)=0\quad\mathrm{and}
	\quad\|\mathbf{R}\|_{L^\infty(\mathbb{R})}<\infty.
  \end{equation*}
  Then for any $p\ge2$, there exists $t_0$ such that for $t\ge t_0$ and 
  $x\in\mathbb{R}$, $(1-C_{\mathbf{w}})^{-1}$ exists in $L^p(\mathbb{R})$ and 
  \begin{equation*}
	\|(1-C_{\mathbf{w}})^{-1}\|_{L^p(\mathbb{R})\rightarrow L^p(\mathbb{R})}\lesssim1.
  \end{equation*}
  \end{lemma} 
  By Lemma \ref{bbd-w1}, Lemma \ref{Lp-w1} and Proposition 2.8 in \cite{deift2002long}, 
  we conclude that for $\mathbf{R}(\lambda)\in H^{1,1}(\mathbb{R})$ and $2\le p<\infty$,
  \begin{equation}\label{lp-hat-w1}
    \|(1-C_{\hat{\mathbf{w}}_1})^{-1}\|_{L^p(\mathbb{R}_\xi)\rightarrow L^p(\mathbb{R}_\xi)}\lesssim1.
  \end{equation}
  Using equation \eqref{lp-hat-w1}, we obtain the following results.

  \begin{lemma}\label{lemma3-CNLS}
	For any $2\leq p<\infty$ and for t sufficiently large,
	\begin{equation*}
	  \|\hat{\pmb{\mu}}_1-\mathbb{I}_3\|_{L^p}\lesssim t^{-1/(2p)}.
	\end{equation*}
  \end{lemma}
  \begin{proof}
    The result follows from Lemma \ref{lemma1-CNLS} 
    \begin{equation*}
  	\begin{aligned}
  	  \|\hat{\pmb{\mu}}_1-\mathbb{I}_3\|_{L^p}
  	  &=\|(1-C_{\hat{\mathbf{w}}_1})^{-1}(C_{\hat{\mathbf{w}}_1}\mathbb{I}_3)\|_{L^p}\\
  	  &\le \|(1-C_{\hat{\mathbf{w}}_1})^{-1}\|_{L^p(\mathbb{R}_\xi)\rightarrow L^p(\mathbb{R}_\xi)}
  	  \|C_{\hat{\mathbf{w}}_1}\mathbb{I}_3\|_{L^p}\lesssim t^{-1/(2p)}.
  	\end{aligned}
    \end{equation*}
  \end{proof}

  \begin{lemma}\label{lemma4-CNLS}
    For any $2\leq p<\infty$ and for t sufficiently large,
    \begin{equation*}
    \|C^\pm_{\mathbb{R}_\xi}\hat{\pmb{\mu}}_1(\hat{\mathbf{w}}_1^\mp-\hat{\mathbf{w}}_2^\mp)\|_{L^2}
    \lesssim t^{-\frac{1}{2}+\frac{1}{2p}}.
    \end{equation*}
    \end{lemma} 
    \begin{proof}
      By triangularity and $\hat{\pmb{\mu}}_1=\mathbb{I}_3+C_{\hat{\mathbf{w}}_1}\hat{\pmb{\mu}}_1$,
      \begin{equation*}
      \begin{aligned}
        C^\pm_{\mathbb{R}_\xi}\hat{\pmb{\mu}}_1(\hat{\mathbf{w}}_1^\mp-\hat{\mathbf{w}}_2^\mp)
        &=C^\pm_{\mathbb{R}_\xi}(\hat{\mathbf{w}}_1^\mp-\hat{\mathbf{w}}_2^\mp)
        C^\pm_{\mathbb{R}_\xi}(C_{\hat{\mathbf{w}}_1}\hat{\pmb{\mu}}_1)(\hat{\mathbf{w}}_1^\mp-\hat{\mathbf{w}}_2^\mp)\\
        &=C^\pm_{\mathbb{R}_\xi}(\hat{\mathbf{w}}_1^\mp-\hat{\mathbf{w}}_2^\mp)
        +C^\pm_{\mathbb{R}_\xi}(C^\mp\pmb{\mu}_1\mathbf{w}_1^\pm)(\hat{\mathbf{w}}_1^\mp-\hat{\mathbf{w}}_2^\mp)
        \equiv\mathrm{I}+\mathrm{II}.
      \end{aligned}
      \end{equation*}
      %  and $(\det\pmb{\delta})\pmb{\delta}\in H^\infty(\mathbb{C}\setminus\mathbb{R})$
      By Lemma \ref{lemma2-CNLS}, 
      we obtain that $\|\mathrm{I}\|_{L^2}\lesssim t^{-1/2}$. For $\mathrm{II}$, 
      by Lemma \ref{lemma3-CNLS} and Lemma \ref{lemma1-CNLS},
      \begin{equation*}
      \begin{aligned}
        \|C^\mp_{\mathbb{R}_\xi}\hat{\pmb{\mu}}_1\hat{\mathbf{w}}_1^\pm\|_{L^2}
        &\le\|C^\mp_{\mathbb{R}_\xi}(\hat{\pmb{\mu}}_1-\mathbb{I}_3)\hat{\mathbf{w}}_1^\pm\|_{L^2}+
        \|C^\mp_{\mathbb{R}_\xi} \hat{\mathbf{w}}_1^\pm\|_{L^2}\\
        &\lesssim \|\hat{\pmb{\mu}}_1-\mathbb{I}_3\|_{L^2}+t^{-1/(2p)}
        \lesssim t^{-1/(2p)}.
      \end{aligned}
      \end{equation*}
      Together with Lemma \ref{lemma2-CNLS}, we obtain that 
      $\|\mathrm{II}\|_{L^2}\lesssim t^{-1/2+1/p}t^{-1/2p}\lesssim t^{-\frac{1}{2}+\frac{1}{(2p)}}$. 
      The result follows immediately.
    \end{proof}
  Next we can show that $\int_{\mathbb{R}_\xi}\hat{\pmb{\mu}}_2 \hat{\mathbf{w}}_2$ is a good enough 
  approximation to $\int_{\mathbb{R}_\xi}\hat{\pmb{\mu}}_1 \hat{\mathbf{w}}_1$ for large $t$.

  \begin{lemma}\label{bdd-M1-M2}
	For any $2\leq p<\infty$ and for t sufficiently large,
  \begin{equation*}
	\left|\int_{\mathbb{R}_\xi}\hat{\pmb{\mu}}_1 \hat{\mathbf{w}}_1-
  \int_{\mathbb{R}_\xi}\hat{\pmb{\mu}}_2 \hat{\mathbf{w}}_2\right|
	\lesssim t^{{-\frac{3}{4}+\frac{1}{(2p)}}}.
  \end{equation*}
  \end{lemma} 
  A proof of Lemma \ref{bdd-M1-M2} is provided in Appendix A for the sake of completeness.



  Set $\mathbf{w}_{3}=(\mathbf{w}^{-}_3=0,\mathbf{w}^{+}_3=\V^{(3)}-\mathbb{I}_3)$ and 
  $\mathbf{w}_{4}=(\mathbf{w}^{-}_4=0,\mathbf{w}^{+}_4=\V^{(4)}-\mathbb{I}_3)$ 
  on $\Sigma$. Then we will show that $\int_\Sigma\pmb{\mu}_4\mathbf{w}_4$ is a good enough 
  approximation to $\int_\Sigma\pmb{\mu}_3\mathbf{w}_3$ for large $t$.

  \begin{lemma}\label{bdd-M3-M4}
	For t sufficiently large,
  \begin{equation*}
	\left|\int_{\Sigma}\pmb{\mu}_3 \pmb{w}_3-\int_{\Sigma}\pmb{\mu}_4 \pmb{w}_4\right|
	\lesssim t^{{-\frac{3}{4}}}.
  \end{equation*}
  \end{lemma} 

  \begin{proof}
    We decompose the estimate into three parts as follows:
    \begin{equation}
  	\begin{aligned}
  	  \int_{\Sigma}\pmb{\mu}_3 \pmb{w}_3-\int_{\Sigma}\pmb{\mu}_4 \pmb{w}_4
  	& =\int_{\Sigma} \pmb{w}_3-\pmb{w}_4+
  	\int_{\Sigma}(\pmb{\mu}_4-\mathbb{I}_{3})(\pmb{w}_3-\pmb{w}_4)+\int_{\Sigma}(\pmb{\mu}_3-\pmb{\mu}_4)\pmb{w}_3 \\
  	&\equiv\mathrm{I}+\mathrm{II}+\mathrm{III}.
  	\end{aligned}
    \end{equation}
    For $\mathrm{I}$, by the Lemma \ref{bdd-V3-V4},
    \begin{equation*}
  	|\mathrm{I}|\le\left\|\V^{(3)}-\V^{(4)}\right\|_{L^1(\Sigma)}\lesssim t^{-3/4}.
    \end{equation*}
    For $\mathrm{II}$, we have
    \begin{equation*}
  	\|\pmb{\mu}_4-\mathbb{I}_{3}\|_{L^2(\Sigma)}=\|C^-_{\Sigma}(\V^{(4)}-\mathbb{I}_3)\|_{L^2(\Sigma)}
  	\lesssim\|\V^{(4)}-\mathbb{I}_3\|_{L^2(\Sigma)}.
    \end{equation*}
    we consider $\lambda=\xi+ue^{-\ii\pi/4}\in\Sigma_4$ only, the situation 
    on the other rays in $\Sigma$ is similar. 
    By $|\pmb{\delta}_0|=|\ee^{\ii\kappa(\xi)\ln(\lambda-\xi)}|=|\ee^{\kappa(\xi)\pi/4}|\lesssim1$, 
    \begin{equation*}
  	\|\V^{(4)}-\mathbb{I}_3\|_{L^2(\Sigma_4)}\lesssim(\int_{0}^{+\infty}\ee^{-2tu^2}\dd u)^{1/2}
  	\lesssim t^{-1/4}.
    \end{equation*}
    Therefore 
    $\|\pmb{\mu}_4-\mathbb{I}_{3}\|_{L^2(\Sigma)}\lesssim\|\V^{(4)}-\mathbb{I}_3\|_{L^2(\Sigma)}\lesssim t^{-1/4}$. 
    Then 
    \begin{equation*}
  	\begin{aligned}
  	  |\mathrm{II}|
  	  &\le\|\pmb{\mu}_4-\mathbb{I}_{3}\|_{L^2(\Sigma)}\|\pmb{w}_3-\pmb{w}_4\|_{L^2(\Sigma)}\\
  	  &\lesssim t^{-1/4}\left\|\V^{(3)}-\V^{(4)}\right\|_{L^2(\Sigma)}\\
  	  &\lesssim t^{-3/4}.
  	\end{aligned}
    \end{equation*}
    For $\mathrm{III}$, we compute
    \begin{equation*}
  	\begin{aligned}
  	  \pmb{\mu}_3-\pmb{\mu}_4&=(1-C_{\pmb{w}_3})^{-1}C_{\pmb{w}_3-\pmb{w}_4}\pmb{\mu}_4\\
  	  &=(1-C_{\pmb{w}_3})^{-1}C_{\Sigma}^-\pmb{\mu}_4(\V^{(3)}-\V^{(4)}),
  	\end{aligned}
    \end{equation*}
    then by Lemma \ref{bdd-V3-V4} 
    \begin{equation*}
  	\begin{aligned}
  	  \|\pmb{\mu}_3-\pmb{\mu}_4\|_{L^2(\Sigma)}
  	  &\lesssim\|\pmb{\mu}_4(\V^{(3)}-\V^{(4)})\|_{L^2(\Sigma)}\\
  	  &\lesssim\|(\pmb{\mu}_4-\mathbb{I}_3)(\V^{(3)}-\V^{(4)})\|_{L^2(\Sigma)}
  	  +\|\V^{(3)}-\V^{(4)}\|_{L^2(\Sigma)}\\
  	  &\lesssim\|(\pmb{\mu}_4-\mathbb{I}_3)\|_{L^2(\Sigma)}
  	  \|\V^{(3)}-\V^{(4)}\|_{L^\infty(\Sigma)}+t^{-1/2}\\
  	  &\lesssim t^{-1/4}t^{-1/4}+t^{-1/2}\lesssim t^{-1/2}.
  	\end{aligned}
    \end{equation*}
    Therefore by $\|\V^{(3)}-\mathbb{I}_3\|_{L^2(\Sigma_4)}\lesssim t^{-1/4}$ 
    as $\|\V^{(4)}-\mathbb{I}_3\|_{L^2(\Sigma_4)}$,
    \begin{equation*}
  	|\mathrm{III}|\le\|\pmb{\mu}_3-\pmb{\mu}_4\|_{L^2(\Sigma)}\|\pmb{w}_3\|_{L^2(\Sigma)}
  	\lesssim t^{-1/2}t^{-1/4}\lesssim t^{-3/4}.
    \end{equation*}
    Adding the estimates for $\mathrm{I}$, $\mathrm{II}$, and $\mathrm{III}$, the result follows.
  \end{proof}

  By Beals and Coifman \cite{beals1984scattering}, we know that 
  \begin{equation*}
	\M^{(4)}(x,t)=\mathbb{I}_{3}+C_{\Sigma}(\pmb{\mu}_4(\pmb{w}^-_4 + \pmb{w}^+_4))
  \end{equation*}
  solves RHP \ref{rhp-M4}, where $\pmb{\mu}_4$ is the solution of 
  $(1-C_{\pmb{w}_4})\pmb{\mu}_4=\mathbb{I}_{3}$. Thus, we can obtain the expansion of 
  $\M^{(4)}(\lambda;x,t)$
  \begin{equation}\label{residue-M4}
     \begin{aligned}
      &\M^{(4)}(\lambda;x,t)=\mathbb{I}_3+
      \frac{\M_1^{(4)}(x,t)}{\lambda}+\oo(\lambda^{-2}),\ \ \lambda\to\infty\\
      &\M_1^{(4)}(x,t)=\frac{\ii}{2\pi}\int_{\Sigma}\pmb{\mu}_4 \pmb{w}_4.
     \end{aligned}
  \end{equation}
  But the RHP \ref{rhp-M4} can be solved explicitly in the terms of parabolic 
  cylinder function, which appears frequently in the literature of long-time asymptotic calculations for 
  integrable nonlinear waves \cite{dieng2008long,grunert2009long,jenkins2017global,liujiaqi2018long}. The jump matrices \eqref{jump-parabolic-cylinder-model} 
  are exactly the jump matrices of the parabolic cylinder model problem 
  which was first introduced and solved in \cite{its1981asymptotics}, and later applied to the mKdV equation in \cite{deift1993steepest}.
  Set $y=\varphi(\lambda)=2\sqrt{t}(\lambda-\xi)$ and 
  $\M^{(5)}(y;x,t)=\M^{(4)}(\varphi^{-1}(y);x,t)$, 
  it follows RHP 3.4 that $\M^{(5)}(y):=\M^{(5)}(y;x,t)$ satisfies the following RHP.

\begin{rhp}\label{solvable-RHP-model}
  Find an analytic function $\M^{(5)}$: 
  $\mathbb{C}\setminus\Sigma^{\prime}\rightarrow SL_{2}(\mathbb{C}),\Sigma^{\prime}=\cup_{k=1}^{4}\ee^{\frac{(2k-1)\pi\ii}{4}}\mathbb{R}_+$ 
  with the following properties
  \begin{itemize}
	\item[1.] $\M^{(5)}(y)=\mathbb{I}_{3}+\mathcal{O}\left(y^{-1}\right)$ as $y\rightarrow\infty.$
	\item[2.] For each $y\in\Sigma^\prime$ ,
	$\M^{(5)}$ takes continuous boundary values $\M^{(5)}_{\pm}(y)$ which satisfy 
	the jump relation: $\M_+^{(5)}(y)=\M_-^{(5)}(y)\V^{(5)}(y)$ where
	\begin{equation*}
	 \V^{(5)}(y)=
	 \begin{cases}
	  \begin{pmatrix}
		1 & 0\\
		-\eta^{-2} y^{-2\ii\kappa(\xi)} \ee^{\frac{1}{2}\ii y^2} \mathbf{R}^\dagger(\xi) & \mathbb{I}_2
	   \end{pmatrix},  
	  &y \in \ee^{\frac{\ii\pi}{4}}\mathbb{R}_+,\\
	  \begin{pmatrix}
		1 & -\eta^2 y^{2\ii\kappa(\xi)} \ee^{-\frac{1}{2}\ii y^2}
		\frac{\mathbf{R}}{1+\mathbf{R}\mathbf{R}^\dagger}(\xi)\\
		0 & \mathbb{I}_2
	  \end{pmatrix},
	  &y \in \ee^{-\frac{\ii\pi}{4}}\mathbb{R}_-,\\
	  \begin{pmatrix}
		1 & 0\\
		-\eta^{-2}y^{-2\ii\kappa(\xi)} \ee^{\frac{1}{2}\ii y^2}
		\frac{\mathbf{R}^\dagger}{1+\mathbf{R}\mathbf{R}^\dagger}(\xi) & \mathbb{I}_2
	  \end{pmatrix},
	  &y \in \ee^{\frac{\ii\pi}{4}}\mathbb{R}_-,\\
	  \begin{pmatrix}
		1 & -\eta^2 y^{2\ii\kappa(\xi)} \ee^{-\frac{1}{2}\ii y^2}\mathbf{R}(\xi)\\
		0 & \mathbb{I}_2
	  \end{pmatrix},  
	  &y \in \ee^{-\frac{\ii\pi}{4}}\mathbb{R}_+,
	 \end{cases}
	\end{equation*}
	where $\eta=(2\sqrt{t})^{-\ii\kappa(\xi)}\ee^{\ii t\xi^2}\ee^{-\beta(\xi,\xi)-\ii\kappa(\xi)}$.
  \end{itemize}
\end{rhp}

\subsection{Solving model problem}
Since it is a standardized procedure to solve a 
$2\times2$ model RHP \cite{deift1993steepest}, we consider reducing RHP \ref{solvable-RHP-model} to 
a $2\times2$ model RHP. We set $-\mathbf{R}^\dagger(\xi)=[a,b]^{\top}$ and then define
\begin{equation}\label{decrease-dimension-weber-equ-B}
	\mathbf{A}=\begin{pmatrix}
		a^{*} & b^{*}\\
		-b & a
	  \end{pmatrix}|\mathbf{R}(\xi)|^{-1},\quad
	  \mathbf{B}=\begin{pmatrix}
		1 & 0\\
		0 & \mathbf{A}
	  \end{pmatrix}.
\end{equation}
Clearly, $\mathbf{A}\mathbf{A}^\dagger=\mathbb{I}_2$ and 
$\mathbf{B}\mathbf{B}^\dagger=\mathbb{I}_3$. Let 
$\M^{(6)}(y):=\M^{(6)}(y;x,t)=\mathbf{B}\M^{(5)}(y)\mathbf{B}^{-1}$ and then 
$\M^{(6)}(y)$ satisfies the following RHP.

\begin{rhp}\label{rhp-M6}
  Find an analytic function $\M^{(6)}$: 
  $\mathbb{C}\setminus\Sigma^{\prime}\rightarrow SL_{2}(\mathbb{C}),\Sigma^{\prime}=\cup_{k=1}^{4}\ee^{\frac{(2k-1)\pi}{4}}\mathbb{R}_+$ 
  with the following properties
  \begin{itemize}
	\item[1.] $\M^{(6)}(y)=\mathbb{I}_{3}+\mathcal{O}\left(y^{-1}\right)$ as $y\rightarrow\infty.$
	\item[2.] For each $y\in\Sigma^\prime$ ,
	$\M^{(6)}$ takes continuous boundary values $\M^{(6)}_{\pm}(y)$ which satisfy 
	the jump relation: $\M_+^{(6)}(y)=\M_-^{(6)}(y)\V^{(6)}(y)$ where
	\begin{equation*}
	 \V^{(6)}(y)=
	 \begin{cases}
	  \begin{pmatrix}
		1 & 0 & 0\\
		\eta^{-2} y^{-2\ii\kappa(\xi)} \ee^{\frac{1}{2}\ii y^2} |\mathbf{R}^\dagger(\xi)| & 1 & 0\\
		0 & 0 & 1
	   \end{pmatrix},  
	  &y \in \ee^{\frac{\ii\pi}{4}}\mathbb{R}_+,\\
	  \begin{pmatrix}
		1 & \eta^2 y^{2\ii\kappa(\xi)} \ee^{-\frac{1}{2}\ii y^2} \frac{|\mathbf{R}^\dagger(\xi)|}{1+|\mathbf{R}^\dagger(\xi)|^2} & 0\\
		0 & 1 & 0\\
		0 & 0 & 1
	   \end{pmatrix}, 
	  &y \in \ee^{-\frac{\ii\pi}{4}}\mathbb{R}_-,\\
	  \begin{pmatrix}
		1 & 0 & 0\\
		\eta^{-2} y^{-2\ii\kappa(\xi)} \ee^{\frac{1}{2}
    \ii y^2} \frac{|\mathbf{R}^\dagger(\xi)|}{1+|\mathbf{R}^\dagger(\xi)|^2} & 1 & 0\\
		0 & 0 & 1
	   \end{pmatrix},
	  &y \in \ee^{\frac{\ii\pi}{4}}\mathbb{R}_-,\\
	  \begin{pmatrix}
		1 & \eta^2 y^{2\ii\kappa(\xi)} \ee^{-\frac{1}{2}\ii y^2} |\mathbf{R}^\dagger(\xi)| & 0\\
		0 & 1 & 0\\
		0 & 0 & 1
	   \end{pmatrix}, 
	  &y \in \ee^{-\frac{\ii\pi}{4}}\mathbb{R}_+,
	 \end{cases}
	\end{equation*}
	where $\eta=(2\sqrt{t})^{-\ii\kappa(\xi)}\ee^{\ii t\xi^2}\ee^{-\beta(\xi,\xi)-\ii\kappa(\xi)}$.
  \end{itemize}
\end{rhp}

  Next, we can transform RHP \ref{rhp-M6} into a $2\times2$ model RHP and 
  $\M^{(6)}(y)$ needs to be rewritten in the following block form
  \begin{equation*}
	\M^{(6)}(y)=
	\begin{pmatrix}
		\mathbf{N}(y) & \M^{(6)}_{12}(y)\\
		\M^{(6)}_{21}(y) & \M^{(6)}_{22}(y)
	\end{pmatrix},
  \end{equation*}
  where $\M^{(6)}_{22}(y)$ is scalar.
  It follows from RHP \ref{rhp-M6} that 
  $\M^{(6)}_{12}(y)=0$, $\M^{(6)}_{21}(y)=0$, 
  $\M^{(6)}_{22}(y)=1$ and $\mathbf{N}(y)$ satisfies the following RHP.

  \begin{rhp}\label{rhp-N}
    Find an analytic function $N$: 
  $\mathbb{C}\setminus\Sigma^{\prime}\rightarrow SL_{2}(\mathbb{C}),\Sigma^{\prime}=\bigcup_{k=1}^{4}\ee^{\frac{(2k-1)\pi\ii}{4}}\mathbb{R}_+$ 
  with the following properties
  \begin{itemize}
	\item[1.] $\mathbf{N}(y)=\mathbb{I}_{2}+\mathcal{O}\left(y^{-1}\right)$ as $y\rightarrow\infty.$
	\item[2.] For each $y\in\Sigma^\prime$ ,
	$N$ takes continuous boundary values $N_{\pm}(y)$ which satisfy 
	the jump relation: $N_+^{(6)}(y)=N_-^{(6)}(y)\V_N(y)$ where
	\begin{equation*}
	 \V_N(y)=
	 \begin{cases}
	  \begin{pmatrix}
		1 & 0 \\
		\eta^{-2} y^{-2\ii\kappa(\xi)} \ee^{\frac{1}{2}\ii y^2} |\mathbf{R}^\dagger(\xi)| & 1 
	   \end{pmatrix},  
	  &y \in \ee^{\frac{\ii\pi}{4}}\mathbb{R}_+,\\
	  \begin{pmatrix}
		1 & \eta^2 y^{2\ii\kappa(\xi)} \ee^{-\frac{1}{2}\ii y^2} \frac{|\mathbf{R}^\dagger(\xi)|}{1+|\mathbf{R}^\dagger(\xi)|^2} \\
		0 & 1 
	   \end{pmatrix}, 
	  &y \in \ee^{-\frac{\ii\pi}{4}}\mathbb{R}_-,\\
	  \begin{pmatrix}
		1 & 0 \\
		\eta^{-2} y^{-2\ii\kappa(\xi)} \ee^{\frac{1}{2}\ii y^2} \frac{|\mathbf{R}^\dagger(\xi)|}{1+|\mathbf{R}^\dagger(\xi)|^2} & 1
	   \end{pmatrix},
	  &y \in \ee^{\frac{\ii\pi}{4}}\mathbb{R}_-,\\
	  \begin{pmatrix}
		1 & \eta^2 y^{2\ii\kappa(\xi)} \ee^{-\frac{1}{2}\ii y^2} |\mathbf{R}^\dagger(\xi)| \\
		0 & 1
	   \end{pmatrix}, 
	  &y \in \ee^{-\frac{\ii\pi}{4}}\mathbb{R}_+,
	 \end{cases}
	\end{equation*}
	where $\eta=(2\sqrt{t})^{-\ii\kappa(\xi)}\ee^{\ii t\xi^2}\ee^{-\beta(\xi,\xi)-\ii\kappa(\xi)}$.
  \end{itemize}
  \end{rhp}
  The solution $\mathbf{N}$ is described in Appendix B and we can obtain the expansion of $\mathbf{N}$ 
  \begin{equation}
    \mathbf{N}(y)=\mathbb{I}_2+\frac{\mathbf{N}_1}{y}+\oo(y^{-2}),
  \end{equation}
  where, using equations \eqref{relation-beta-N}, \eqref{def-beta} and \eqref{relation-b12-b21}, 
  we have 
  \begin{equation}
    \mathbf{N}_1=\begin{pmatrix}
      0&-\ii\eta^{2}\beta_{12}\\
      \ii\eta^{-2}\beta_{21}&0
    \end{pmatrix},\,
    \beta_{12}=
	\frac{|\mathbf{R}(\xi)|}{\sqrt{2\pi}}\ee^{\frac{\pi\kappa_{\xi}}{2}+
	\frac{5\pi \ii}{4}}\kappa_{\xi}\Gamma(\ii\kappa_{\xi}),\,
  \beta_{21}=-\beta_{12}^*.
  \end{equation}
  Then we can also obtain the expansion of $\M^{(6)}$
  \begin{equation}
    \begin{aligned}
      &\M^{(6)}(y)=\mathbb{I}_3+\frac{\M^{(6)}_{1}}{y}+\oo(y^{-2}),
      &\M^{(6)}_{1}=\begin{pmatrix}
        \mathbf{N}_1 & 0\\
        0 & 0
      \end{pmatrix}.
    \end{aligned}
  \end{equation}
It follows from $\M^{(6)}(y)=\mathbf{B}\M^{(5)}(y)\mathbf{B}^{-1}$ that 
we can deduce the expansion of $\M^{(5)}$
\begin{equation}\label{M5_1}
    \M^{(5)}(y)=\mathbb{I}_3+\frac{\M^{(5)}_{1}}{y}+\oo(y^{-2}),
    \quad \M^{(5)}_{1}=\mathbf{B}^{-1}\M^{(6)}_1\mathbf{B}.
\end{equation}
Actually, our ultimate goal is to recover the soluiton $\mathbf{q}(x,t)$ for 
CNLS equation \eqref{CNLS} by the recovery formula \eqref{matrix-form-T1}. Therefore, 
we focus on the behavior of $\left(\M^{(5)}_{1}\right)_{12}$
\begin{equation}
  \left(\M^{(5)}_{1}\right)_{12}=[-\ii\eta^2\beta_{12},0]\mathbf{A}=
    \frac{\eta^2e^{\frac{\pi\kappa_{\xi}}{2}-
    \frac{\pi \ii}{4}}\kappa_{\xi}\Gamma(\ii\kappa_{\xi})}{\sqrt{2\pi}}\mathbf{R}(\xi).
\end{equation}
By the definition of rescaled variable $y=2\sqrt{t}(\lambda-\xi)$, we can obtain the expansion 
of $\M^{(4)}(\lambda)$
  \begin{equation}
	\begin{aligned}
	  \M^{(4)}(\lambda)=\M^{(5)}(y)
	  &=\mathbb{I}_3+\frac{\M^{(5)}_1}{y}+\mathcal{O}(y^{-2}),&y\rightarrow\infty,\\
	  &=\mathbb{I}_3+\frac{\M^{(5)}_1}{2\sqrt{t}\lambda}+\mathcal{O}(\lambda^{-2})
	  ,&\lambda\rightarrow\infty.
	\end{aligned}
  \end{equation}
  Together with equation \eqref{residue-M4}, we find
  \begin{equation}\label{M4_1-M5_1}
	\M_1^{(4)}(x,t)=\frac{\ii}{2\pi}\int_{\Sigma}\pmb{\mu}_4 \pmb{w}_4=\frac{1}{2\sqrt{t}}\M^{(5)}_1(x,t).
  \end{equation}
Inverting the above sequence of transformations, we have 
\begin{equation}\label{inverse-rhp}
  \M(\lambda)=\M^{(1)}(\lambda)\pmb{\Delta}(\lambda),\quad
  \M^{(2)}(\lambda)=\M^{(3)}(\lambda)\mathbf{\Xi}(\lambda),\quad
  \M^{(4)}(\lambda)=\mathbf{B}^{-1}
  \begin{pmatrix}
    \mathbf{N}(\varphi(\lambda))&0\\
    0&1
  \end{pmatrix}\mathbf{B},
\end{equation}
and then, by Lemma \ref{bdd-M1-M2}, 
\begin{equation}
  \begin{aligned}
  2(\M_1)_{12}&=2\left(\hat{\M}^{(1)}_1\right)_{12}
  =\left(\frac{\ii}{\pi}\int_{\mathbb{R}_\xi}\hat{\pmb{\mu}}_1 \hat{w}_1\right)_{12}\\
  &=\left(\frac{\ii}{\pi}\int_{\mathbb{R}_\xi}\hat{\pmb{\mu}}_2 \hat{w}_2\right)_{12}+\mathcal{O}(t^{-\frac{3}{4}+\frac{1}{(2p)}})\\
  &=2\left(\M^{(2)}_1\right)_{12}+\mathcal{O}(t^{-\frac{3}{4}+\frac{1}{(2p)}}).
  \end{aligned}
\end{equation}
Since $\mathbf{\Xi}(\lambda)=\mathbb{I}_3$ in region $\Omega_2$, we obtain 
$\M^{(3)}=\M^{(2)}\mathbf{\Xi}=\M^{(2)}=\hat{\M}^{(2)}$ which implies 
\begin{equation}
  \begin{aligned}
  2(\M_1)_{12}
  &=2\left(\M^{(3)}_1\right)_{12}+\mathcal{O}(t^{-\frac{3}{4}+\frac{1}{(2p)}})\\
  &=\left(\frac{\ii}{\pi}\int_{\Sigma}\pmb{\mu}_3 \pmb{w}_3\right)_{12}+\mathcal{O}(t^{-\frac{3}{4}+\frac{1}{(2p)}})\\
  &=\left(\frac{\ii}{\pi}\int_{\Sigma}\pmb{\mu}_4 \pmb{w}_4\right)_{12}
  +\mathcal{O}(t^{-\frac{3}{4}+\frac{1}{(2p)}}),
  \end{aligned}
\end{equation}
by Lemma \ref{bdd-M3-M4}.
Together with equations \eqref{residue-M4}, \eqref{M5_1} and \eqref{M4_1-M5_1}, we obtain
\begin{equation}
  2(\M_1)_{12}
	=\frac{\ee^{\frac{\pi\kappa_{\xi}}{2}-
	\frac{\pi \ii}{4}}\eta^2\kappa_{\xi}\Gamma(\ii\kappa_{\xi})\mathbf{R}(\xi)}{\sqrt{2\pi t}}+\mathcal{O}(t^{-\frac{3}{4}+\frac{1}{(2p)}}).
\end{equation}
Hence, by recovery formula \eqref{matrix-form-T1}, we have 
\begin{equation}\label{recovery-formula2}
  \mathbf{q}(x,t)
	=\frac{\ee^{\frac{\pi\kappa_{\xi}}{2}-
	\frac{\pi \ii}{4}}\eta^2\kappa_{\xi}\Gamma(\ii\kappa_{\xi})\mathbf{R}(\xi)}{\sqrt{2\pi t}}
	-2\mathbf{X}_1\mathbf{G}^{-1}(\mathbf{X}_2)^\dagger+\mathcal{O}(t^{-\frac{3}{4}+\frac{1}{(2p)}}).
\end{equation}
But for matrices $\mathbf{X}$ and $\mathbf{G}$, we must obtain $\M(\lambda;x,t)$ evaluated at $\lambda=\lambda_i$.
It follows from equation \eqref{inverse-rhp} that
\begin{equation}
  \begin{aligned}
    &\M(\lambda_i)=\M^{(1)}(\lambda_i)\pmb{\Delta}(\lambda_i),\quad
  \M^{(2)}(\lambda_i)=\M^{(3)}(\lambda_i)\mathbf{\Xi}(\lambda_i),\quad\\
  &\M^{(4)}(\lambda_i)=B^{-1}
  \begin{pmatrix}
    \mathbf{N}(y_i)&0\\
    0&1
  \end{pmatrix}B.
  \end{aligned}
\end{equation}
where $y_i=2\sqrt{t}(\lambda_i-\xi)$. The solution $\mathbf{N}(y)$ can be  given by
\begin{equation}
  \mathbf{N}(y)=\eta^{\pmb{\sigma}_3}\pmb{\Psi}(y)
  y^{-\ii\kappa_\xi\pmb{\sigma}_3}
  \mathrm{\ee}^{\frac14\ii y^2\pmb{\sigma}_3}
  \eta^{-\pmb{\sigma}_3}.
\end{equation}
By equation \eqref{asymptotic-Da} and equation \eqref{weber-equ-Psi}, we obtain 
the long-time asymptotic behavior of $\mathbf{N}(y_i)$
\begin{equation}
  \mathbf{N}(y_i)=\mathbb{I}_2+t^{-1/2}\mathbf{P}(y_i)+\oo(t^{-1}),
\end{equation}
\begin{equation}
  \mathbf{P}(y_i)=
  \begin{cases}
    \begin{pmatrix}
      0&\frac{\eta^2\beta_{12}\ee^{-\frac34\pi \ii}}{2(\lambda_i-\xi)}\\
      \frac{\eta^{-2}\beta_{21} \ee^{\frac34\pi \ii}}{2(\lambda_i-\xi)}&0
    \end{pmatrix},
    &\mathrm{arg}(y_i)\in[0,\frac{\pi}{4}],\\
    \begin{pmatrix}
      0&\frac{\eta^2\beta_{12}\ee^{-\frac34\pi \ii}}{2(\lambda_i-\xi)}\\
      \frac{\eta^{-2}\beta_{21}\ee^{-\frac14\pi \ii}}{2(\lambda_i-\xi)}&0
    \end{pmatrix},
    &\mathrm{arg}(y_i)\in[\frac{\pi}{4},\frac{3\pi}{4}],\\
    \begin{pmatrix}
      0&\frac{\eta^2\beta_{12}\ee^{\frac14\pi \ii}}{2(\lambda_i-\xi)}\\
      \frac{\eta^{-2}\beta_{21}\ee^{-\frac14\pi \ii}}{2(\lambda_i-\xi)}&0
    \end{pmatrix},
    &\mathrm{arg}(y_i)\in[\frac{3\pi}{4},\pi].\\
  \end{cases}
\end{equation}
