  \section*{Appendix A}\label{trivial-extend}
  \setcounter{equation}{0} % 重置方程编号
  \renewcommand{\theequation}{A.\arabic{equation}} % 设置方程编号格式
  The scalar version of the following lemmas has already been proposed in previous literature \cite{deift2002long,deift2011long}. 
  We extend these lemmas trivially to the vector case and provide a more detailed proof for the sake of completeness.

  \begin{proof}[Proof of Lemma \ref{bdd-w}]
    Our proof follows that found in \cite[Lemma 5.2]{deift2011long}.
    Define $\mathbf{w}=(\mathbf{w}_-,\mathbf{w}_+)=(0,\V-\mathbb{I}_3)$ and $\hat{\mathbf{w}}=(\hat{\mathbf{w}}_-,\hat{\mathbf{w}}_+)=(0,\V^{-1}-\mathbb{I}_3)$, then we will show 
    that $1-C_{\mathbf{w}}$ is a Fredholm operator with index 0. For $\mathbf{f}\in L^2(\mathbb{R})$, 
    \begin{equation*}
      \begin{aligned}
      C_{\mathbf{w}}(C_{\hat{\mathbf{w}}}\mathbf{f}) 
      &=C^{-}_{\mathbb{R}}[C^{-}_{\mathbb{R}}(\mathbf{f}(\V^{-1}-\mathbb{I}_3))(\V-\mathbb{I}_3)] \\
      &=C^{-}_{\mathbb{R}}[(C^{+}_{\mathbb{R}}(\mathbf{f}(\V^{-1}-\mathbb{I}_3))-\mathbf{f}(\V^{-1}-\mathbb{I}_3))(\V-\mathbb{I}_3)] \\
      &=C^{-}_{\mathbb{R}}[C^{+}_{\mathbb{R}}(\mathbf{f}(\V^{-1}-\mathbb{I}_3))(\V-\mathbb{I}_3)+
      \mathbf{f}(\V-\mathbb{I}_3+\V^{-1}-\mathbb{I}_3)] \\
      &=P\mathbf{f}+C_{\mathbf{w}}\mathbf{f}+C_{\hat{\mathbf{w}}}\mathbf{f}.
      \end{aligned}
    \end{equation*}
    where $P\mathbf{f}=C^{-}_{\mathbb{R}}[C^{+}_{\mathbb{R}}(\mathbf{f}(\V^{-1}-\mathbb{I}_3))(\V-\mathbb{I}_3)]$. 
    As $\V$ is continuous and $\V-\mathbb{I}_3\rightarrow0$ as 
    $\lambda\rightarrow\infty$, we can approximate $\V-\mathbb{I}_3$ by a sequence 
    of rational functions of the following form 
    \begin{equation*}
      \sum_{i=1}^n\frac{{\bf A}_i}{z-a_i},\quad a_i\in\mathbb{C}\setminus\mathbb{R}.
    \end{equation*}
    By the Cauchy theorem, 
    \begin{equation*}
      \begin{aligned}
        P_i \mathbf{f}(z)
        &=C^{-}_{\mathbb{R}}\left(C^{+}_{\mathbb{R}}(\mathbf{f}(\V^{-1}-\mathbb{I}_3))(s)\frac{1}{s-a_i}\right)(z)\\
        &=\lim_{\varepsilon\downarrow0}\int_{\mathbb{R}}
        \frac{C^{+}_{\mathbb{R}}(\mathbf{f}(\V^{-1}-\mathbb{I}_3))(s)}{(s-a_i)(s-(z-\ii\varepsilon))}
        \frac{\dd s}{2\pi \ii}\\
        &=
        \begin{cases}
          0,& a_i\in\mathbb{C}^-,\\
          \frac{C^{+}(\mathbf{f}(\V^{-1}-\mathbb{I}_3))(a_i)}{a_i-z},&a_i\in\mathbb{C}^+.
        \end{cases}
      \end{aligned}
    \end{equation*}
    This implies operator $P_i$ has either rank 0 or 1 and hence is compact in 
    $L^2(\mathbb{R})$. Together with 
    $P=\displaystyle\lim_{n\rightarrow\infty}\sum_{i=1}^n{\bf A}_iP_i$, $P$ is operator limit of 
    compact operators and hence is compact. It follows from 
    $(1-C_\mathbf{w})(1-C_{\hat{\mathbf{w}}})=1+P$ that $(1-C_\mathbf{w})(1-C_{\hat{\mathbf{w}}})-1$ is compact. 
    Similarly, we can obain that $(1-C_{\hat{\mathbf{w}}})(1-C_\mathbf{w})-1$ is also compact. 
    Therefore, $1-C_\mathbf{w}$ is a Fredholm operator. For $0\le\alpha\le1$, set 
    \begin{equation*}
      \V_\alpha=\begin{pmatrix}
        1+\alpha^2|\mathbf{R}|^2&-\alpha\mathbf{R}\ee^{-2\ii t\theta}\\
        -\alpha\mathbf{R}^\dagger \ee^{2\ii t\theta}&\mathbb{I}_2
      \end{pmatrix}.
    \end{equation*}
    Clearly $\V_0=\mathbb{I}_3$ and $\V_1=\V$. Then we can show that 
    $1-C_{\mathbf{w}_\alpha}$ is a Fredholm operator as same as $1-C_\mathbf{w}$ 
    and conclude that ${\rm ind}(1-C_{\mathbf{w}_1})=ind(1-C_{\mathbf{w}_0})=0$. Hence 
    $1-C_{\mathbf{w}}$ is a Fredholm operator with index 0. Then we want to 
    show that $(1-C_{\mathbf{w}})\mathbf{f}=0$, $\mathbf{f}\in L^2(\mathbb{R})$ implies that $\mathbf{f}=0$. 
    Set ${\bf m}_\pm=C^\pm_{\mathbb{R}}(\mathbf{f}(\V-\mathbb{I}_3))$. Since $(1-C_{\mathbf{w}})\mathbf{f}=0$, we have 
    \begin{equation*}
      \mathbf{f}=C_{\mathbf{w}}\mathbf{f}=C^-_{\mathbb{R}}(\mathbf{f}(\V-\mathbb{I}_3))={\bf m}_-,
    \end{equation*}
    and 
    \begin{equation*}
      \begin{aligned}
        {\bf m}_+&
        =C^+_{\mathbb{R}}(\mathbf{f}(\V-\mathbb{I}_3))=C^-_{\mathbb{R}}
        (\mathbf{f}(\V-\mathbb{I}_3))+\mathbf{f}(\V-\mathbb{I}_3)\\
        &={\bf m}_-+{\bf m}_-(\V-\mathbb{I}_3)={\bf m}_-\V.
      \end{aligned}
    \end{equation*}
    By the Cauchy theorem,
    \begin{equation*}
      0=\int_\mathbb{R}{\bf m}_+{\bf m}_-^\dagger =\int_\mathbb{R}{\bf m}_-\V {\bf m}_-^\dagger.
    \end{equation*}
    But $\V$ is clearly strictly positive and hence $\mathbf{f}={\bf m}_-=0$. Thus 
    $1-C_\mathbf{w}$ is injective. It follow form 
    $1-C_{\mathbf{w}}$ is a Fredholm operator with index 0 that 
    $1-C_{\mathbf{w}}$ is bijective and $(1-C_{\mathbf{w}})^{-1}$ exists. 
    By Corollary 2.7 in \cite{deift2002long}, we conclude that 
    $1-C_{\mathbf{w}}$ is invertible in $L^2(\mathbb{R})$ for any factorization. 
    To complete the proof, we must show that $(1-C_{\mathbf{w}})^{-1}$ is bounded 
    in $L^2(\mathbb{R})$.

    By proposition 2.6 in \cite{deift2002long}, 
    we suppose that $\M_\pm\in\partial C(L^2)$ solve $IRHP2_{L^2}$ defined in \cite[pp.1035]{deift2002long} 
    which implies $\M_+=\M_-\V+\mathbf{f}$ for $\mathbf{f}\in L^2(\mathbb{R})$. As above, we have 
    \begin{equation*}
      0=\int_\mathbb{R}\M_+\M_-^\dagger =\int_\mathbb{R}\M_-\V\M_-^\dagger
      +\int_\mathbb{R}\mathbf{f}\M_-^\dagger.
    \end{equation*}
    Since $\V$ is clearly strictly positive, set $\lambda_0>0$ be the smallest eigenvalue of $\V$. 
    Then we have 
    \begin{equation*}
      \lambda_0\|\M_-\|^2_{L^2}\le
      \left|\int_\mathbb{R}\M_-\V\M_-^\dagger\right|
      =\left|\int_\mathbb{R}\mathbf{f}\M_-^\dagger\right|\le
      \|\mathbf{f}\|_{L^2}\|\M_-\|_{L^2}.
    \end{equation*}
    Hence $\|\M_\pm\|_{L^2}\lesssim\|\mathbf{f}\|_{L^2}$, which implies 
    $\|(1-C_\mathbf{w})^{-1}\|_{L^2(\mathbb{R})}\lesssim 1$ for any factorization of $\V$ by 
    proposition 2.6 and corollary 2.7 in \cite{deift2002long}. 
    This completes the proof.
  \end{proof}


  \begin{proof}[Proof of Lemma \ref{lemma1-CNLS}]
    Our proof follows that found in \cite[Lemma 4.3]{deift2002long}.
    Consider the first inequality. The other cases are similar. For convenience, 
    we assume that $x=0$. We only need to show
    \begin{equation*}
  	\|C^-_{\mathbb{R}_+\rightarrow\Gamma}
  	  (\det\pmb{\delta})^{-1}\ee^{2\ii t\lambda^2}\pmb{\delta}^{-1}\mathbf{f}^\dagger\|_{L^p},
    \end{equation*}
    where $\Gamma=\mathbb{R}\cup(\ee^{\ii\pi/2}\mathbb{R}_-)\cup(\ee^{-\ii\pi/2}\mathbb{R}_-)$. 
    Then the result follows immediately by the translation of 
    $\lambda\rightarrow\lambda-\xi$ since the $H^{1,1}$ and $L^\infty$ norm of 
    $\mathbf{f}$ is invariant under the translation. By Fourier theory, 
    $\mathbf{f}^\dagger(\lambda)=1/\sqrt{2\pi}\int \ee^{-iy\lambda}\check{\mathbf{f}}^\dagger(y)\dd y$. For any 
    $\varepsilon>0$, 
    \begin{equation*}
  	\begin{aligned}
  	  C^-_{\mathbb{R}_+\rightarrow\Gamma}\ee^{-\varepsilon\lambda}
  	(\det\pmb{\delta})^{-1}\ee^{2\ii t\lambda^2}\pmb{\delta}^{-1}\mathbf{f}^\dagger
  	&=\frac1{\sqrt{2\pi}}\int \ee^{-\ii\frac{y^2}{8t}}F_1\check{\mathbf{f}}^\dagger(y)\dd y
  	+\frac1{\sqrt{2\pi}}\int \ee^{-\ii\frac{y^2}{8t}}F_2\check{\mathbf{f}}^\dagger(y)\dd y\\
  	&\equiv \mathrm{I}+\mathrm{II},
  	\end{aligned}
    \end{equation*}
    where 
    \begin{equation*}
  	\begin{aligned}
  	  &F_1(y)=C^-_{\mathbb{R}_+\rightarrow\Gamma}
  	  (\ee^{-\varepsilon\lambda}
  	  (\det\pmb{\delta})^{-1}\ee^{2\ii t(\lambda-\frac{y}{4t})^2}
  	  \chi_{(0,a)}\pmb{\delta}^{-1}),\\
  	  &F_2(y)=C^-_{\mathbb{R}_+\rightarrow\Gamma}
  	  (\ee^{-\varepsilon\lambda}
  	  (\det\pmb{\delta})^{-1}\ee^{2\ii t(\lambda-\frac{y}{4t})^2}
  	  \chi_{(a,\infty)}\pmb{\delta}^{-1}),
  	\end{aligned}
    \end{equation*}
    and $a=\max(0,\frac{y}{4t})$. The factor $\ee^{-\varepsilon\lambda}$ is included to 
    ensure that $\|F_2\|_{L^p}\lesssim\|\ee^{-\varepsilon\lambda}\|_{L^p(a,\infty)}$ and 
    hence $F_2(y)$ exists in $L^p$.

    Assume first that $p>2$. For $y>0$, then $a=\frac{y}{4t}$, 
    \begin{equation*}
  	\|F_1\|_{L^p(\Gamma)}\lesssim \|(\det\pmb{\delta})^{-1}\|_{L^\infty(\mathbb{R}_+)}
  	\|\pmb{\delta}^{-1}\|_{L^\infty(\mathbb{R}_+)}
  	\|\chi_{(0,a)}\|_{L^p}
  	\lesssim \frac{|y|^{1/p}}{t^{1/p}},
    \end{equation*}
    and hence 
    \begin{equation*}
     \begin{aligned}
  	\|\mathrm{I}\|_{L^p(\Gamma)}
  	&\lesssim t^{-1/p}
  	\int_{0}^{\infty}y^{1/p}|\check{\mathbf{f}}^\dagger(y)|\dd y\\
  	&\lesssim t^{-1/p}
  	(\int_{0}^{1}y^{1/p}|\check{\mathbf{f}}^\dagger(y)|\dd y+
  	\int_{1}^{\infty}y|\check{\mathbf{f}}^\dagger(y)|y^{1/p-1}\dd y)\\
  	&\lesssim t^{-1/p}
  	(\|\check{\mathbf{f}}^\dagger\|_{L^2}\|y^{1/p}\|_{L^2(0,1)}+
  	\|y\check{\mathbf{f}}^\dagger\|_{L^2}\|y^{1/p-1}\|_{L^2(1,\infty)})\\
  	&\lesssim t^{-1/p}\|\mathbf{f}\|_{H^{1,1}}.
     \end{aligned}
    \end{equation*}
    For $p=2$, the part $\mathrm{I}$ can be rewritten as 
    \begin{equation*}
  	\frac1{\sqrt{2\pi}}C^-_{\mathbb{R}_+\rightarrow\Gamma}
  	(\int_{4t\lambda}^{\infty} \ee^{-\varepsilon\lambda}
  	(\det\pmb{\delta})^{-1}\ee^{2\ii t\lambda^2-iy\lambda}
  	\pmb{\delta}^{-1}\check{\mathbf{f}}^\dagger\dd y).
    \end{equation*}
    By Hardy inequality, we get 
    \begin{equation*}
  	\begin{aligned}
  	  \|\int_{4t\lambda}^{\infty}| \check{\mathbf{f}}^\dagger|\dd y\|_{L^2(\mathbb{R}_+)}
  	  &=\|\int_{\lambda}^{\infty}\frac{| 4ty\check{\mathbf{f}}^\dagger(4ty)|}{y}\dd y\|_{L^2(\mathbb{R}_+)}\\
  	  &\le 2\|| \check{\mathbf{f}}^\dagger(4ty)|4ty\|_{L^2(\mathbb{R}_+)}\\
  	  &\le 2\frac{1}{\sqrt{4t}}\|| y\check{\mathbf{f}}^\dagger|\|_{L^2(\mathbb{R}_+)}\lesssim t^{-1/2},
  	\end{aligned}
    \end{equation*}
    and hence 
    \begin{equation*}
  	\|\mathrm{I}\|_{L^2(\Gamma)}\lesssim
  	\|\int_{4t\lambda}^{\infty} \ee^{-\varepsilon\lambda}
  	(\det\pmb{\delta})^{-1}\ee^{2\ii t\lambda^2-iy\lambda}
  	\pmb{\delta}^{-1}\check{\mathbf{f}}^\dagger\dd y\|_{L^2(\mathbb{R}_+)}\lesssim
  	\|\int_{4t\lambda}^{\infty} | \check{\mathbf{f}}^\dagger|\dd y\|_{L^2(\mathbb{R}_+)}
  	\lesssim t^{-1/2}.
    \end{equation*}
    For $F_2$, first consider the case when $y<0$, and hence $a=0$. Then for $p\ge2$, by 
    Cauchy theorem,
    \begin{equation*}
  	\begin{aligned}
  	  \|F_2\|_{L^p(\Gamma)}
  	  &=\|C_{\ee^{\ii\pi/4}\mathbb{R}_+\rightarrow\Gamma}
  	  (\ee^{-\varepsilon\lambda}
  	  (\det\pmb{\delta})^{-1}\ee^{2\ii t(\lambda-\frac{y}{4t})^2}
  	  \pmb{\delta}^{-1})\|_{L^p}\\
  	  &\lesssim\|\ee^{-\varepsilon\lambda}
  	  (\det\pmb{\delta})^{-1}\ee^{2\ii t(\lambda-\frac{y}{4t})^2}
  	  \pmb{\delta}^{-1}\|_{L^p(\ee^{\ii\pi/4}\mathbb{R}_+)}\\
  	  &\lesssim \|\ee^{2\ii t\lambda^2}
  	  \ee^{-\ii y\lambda}\|_{L^p(\ee^{\ii\pi/4}\mathbb{R}_+)}.
  	\end{aligned}
    \end{equation*}
    Since $y<0$ and $\lambda\in \ee^{\ii\pi/4}\mathbb{R}_+$, it follows from 
    ${\rm Re}(-\ii y\lambda)<0$ that 
    \begin{equation*}
  	\|F_2\|_{L^p(\Gamma)}\lesssim\|\ee^{2\ii t\lambda^2}
  	\|_{L^p(\ee^{\ii\pi/4}\mathbb{R}_+)}\lesssim t^{-1/(2p)}.
    \end{equation*}
    When $y>0$, then $a=\frac{y}{4t}$ and for $p\ge2$, again by Cauchy theorem,
    \begin{equation*}
  	\begin{aligned}
  	  \|F_2\|_{L^p(\Gamma)}
  	  &=\|C^-_{(y/4t,\infty)\rightarrow\Gamma}
  	  (\ee^{-\varepsilon\lambda}
  	  (\det\pmb{\delta})^{-1}\ee^{2\ii t(\lambda-\frac{y}{4t})^2}
  	  \pmb{\delta}^{-1})\|_{L^p}\\
  	  &=\|C_{(y/4t+\ee^{\ii\pi/4}\mathbb{R}_+)\rightarrow\Gamma}
  	  (\ee^{-\varepsilon\lambda}
  	  (\det\pmb{\delta})^{-1}\ee^{2\ii t(\lambda-\frac{y}{4t})^2}
  	  \pmb{\delta}^{-1})\|_{L^p}\\
  	  &\lesssim\|\ee^{2\ii t(\lambda-\frac{y}{4t})^2}
  	  \|_{L^p(y/4t+\ee^{\ii\pi/4}\mathbb{R}_+)}\\
  	  &\lesssim t^{-1/(2p)}.
  	\end{aligned}
    \end{equation*}
    Thus for $p\ge2$, we have $\|F_2\|_{L^p(\Gamma)}\lesssim t^{-1/(2p)}$. Then
    \begin{equation*}
  	\begin{aligned}
  	  \|\mathrm{II}\|_{L^p(\Gamma)}
  	  &\lesssim t^{-1/(2p)}\int_{-\infty}^{\infty}|\check{\mathbf{f}}^\dagger(y)|\dd y\\
  	  &\lesssim t^{-1/(2p)}(\int_{|y|\le1}|\check{\mathbf{f}}^\dagger(y)|+\int_{|y|>1}|y|^{-1}|y\check{\mathbf{f}}^\dagger(y)|)\dd y\\
  	  &\lesssim t^{-1/(2p)}\|\mathbf{f}\|_{H^{1,1}}.
  	\end{aligned}
    \end{equation*}
    Letting $\varepsilon\downarrow0$ and adding the estimates for $\mathrm{I}$ and $\mathrm{II}$, 
    the result follows immediately.
  \end{proof}


  \begin{proof}[Proof of Lemma \ref{lemma2-CNLS}]
    Our proof follows that found in \cite[Lemma 4.3 ]{deift2002long}.
    We only consider the first inequality, the other cases are similar. Again, 
    we assume that $x=0$. We only need to show
    \begin{equation*}
  	\|C^-_{\mathbb{R}_+\rightarrow\Gamma}
  	  \ee^{2\ii t\lambda}g_+\mathbf{f}^\dagger\|_{L^2}
  	  \lesssim t^{-1/2+1/q}\|g\|_{H^q(\mathbb{C}\setminus\mathbb{R})}.
    \end{equation*}
    It follows from $\mathbf{f}(0)=0$ and Fourier theorem that $\int\check{\mathbf{f}}^\dagger\dd y=0$ and 
    \begin{equation*}
  	\begin{aligned}
  	  C^-_{\mathbb{R}_+\rightarrow\Gamma}
  	  \ee^{-\varepsilon\lambda}\ee^{2\ii t\lambda^2}g_+\mathbf{f}^\dagger
  	  &=\frac1{\sqrt{2\pi}}C^-_{\mathbb{R}_+\rightarrow\Gamma}
  	  \ee^{-\varepsilon\lambda}\ee^{2\ii t\lambda^2}g_+\int (\ee^{-iy\lambda}-1)\check{\mathbf{f}}^\dagger\dd y\\
  	  &=\frac1{\sqrt{2\pi}}\int \ee^{-\ii\frac{y^2}{8t}}F_1\check{\mathbf{f}}^\dagger(y)\dd y
  	  +\frac1{\sqrt{2\pi}}\int \ee^{-\ii\frac{y^2}{8t}}F_2\check{\mathbf{f}}^\dagger(y)\dd y\\
  	  &\equiv \mathrm{I}+\mathrm{II},
  	\end{aligned}
    \end{equation*}
    where 
    \begin{equation*}
  	\begin{aligned}
  	  &F_1(y)=C^-_{\mathbb{R}_+\rightarrow\Gamma}
  	  (\ee^{-\varepsilon\lambda}
  	  \ee^{2\ii t(\lambda-\frac{y}{4t})^2}
  	  \chi_{(0,a)}(1-\ee^{iy\lambda})g_+),\\
  	  &F_2(y)=C^-_{\mathbb{R}_+\rightarrow\Gamma}
  	  (\ee^{-\varepsilon\lambda}
  	  \ee^{2\ii t(\lambda-\frac{y}{4t})^2}
  	  \chi_{(a,\infty)}(1-\ee^{iy\lambda})g_+),
  	\end{aligned}
    \end{equation*}
    and $a=\max(0,\frac{y}{4t})$. For $y>0$, $\mathrm{I}$ can be rewritten as 
    \begin{equation*}
  	\frac1{\sqrt{2\pi}}C^-_{\mathbb{R}_+\rightarrow\Gamma}
  	(g_+\int_{4t\lambda}^{\infty} \ee^{-\varepsilon\lambda}\ee^{2\ii t\lambda^2}
  	(\ee^{-iy\lambda}-1)\check{\mathbf{f}}^\dagger(y)\dd y).
    \end{equation*}
    Then for $q^{'}\ge2$ which satisfies $\frac{1}{q}+\frac{1}{q^{'}}=\frac{1}{2}$, we have
    \begin{equation*}
  	\begin{aligned}
  	 \|\mathrm{I}\|_{L^2(\Gamma)}
  	 &\lesssim \|g_+\int_{4t\lambda}^{\infty} \check{\mathbf{f}}^\dagger(y)\dd y\|_{L^2(\mathbb{R}_+)}\\
  	 &\lesssim \|g_+\|_{L^q(\mathbb{R}_+)}
  	 \|\int_{4t\lambda}^{\infty} \check{\mathbf{f}}^\dagger(y)\dd y\|_{L^{q^{'}}(\mathbb{R}_+)}\\
  	 &\lesssim \|g\|_{H^q(\mathbb{C}\setminus\mathbb{R})}
  	 \left(\int_{0}^{\infty}\left( \int_0^\infty|\check{\mathbf{f}}^\dagger(y)|\dd y\right)^{q^\prime-2}
  	 \left(\int_{4t\lambda}^\infty|\check{\mathbf{f}}^\dagger(y)|\dd y\right)^2d\lambda\right)^{1/q^{\prime}}\\
  	 &\lesssim \|g\|_{H^q(\mathbb{C}\setminus\mathbb{R})}
  	 \left\|\int_{4t\lambda}^\infty|\check{\mathbf{f}}^\dagger(y)|\dd y\right\|_{L^2(\mathbb{R}_+)}^{2/q^{\prime}}.
  	\end{aligned}
     \end{equation*}
    Together with Hardy inequality
    \begin{equation*}
  	\left\|\int_{4t\lambda}^\infty|\check{\mathbf{f}}^\dagger(y)|\dd y\right\|_{L^2(\mathbb{R}_+)}\lesssim
  	t^{-1/2},
    \end{equation*}
    then we get
    \begin{equation*}
  	\|\mathrm{I}\|_{L^2(\Gamma)}\lesssim\|g\|_{H^q(\mathbb{C}\setminus\mathbb{R})}t^{-1/q^{'}}
  	\lesssim \|g\|_{H^q(\mathbb{C}\setminus\mathbb{R})}t^{-1/2+1/q}.
    \end{equation*}
    For $F_2$, first consider the case when $y<0$, then $a=0$ and 
    \begin{equation*}
  	\begin{aligned}
  	  \|F_2\|_{L^2(\Gamma)}
  	  &=\|C_{(\ee^{\ii \pi/4}\mathbb{R}_+)\rightarrow\Gamma}
  	  (\ee^{-\varepsilon\lambda}
  	  \ee^{2\ii t(\lambda-\frac{y}{4t})^2}
  	  (1-\ee^{iy\lambda})g_+)\|_{L^2(\Gamma)}\\
  	  &\lesssim\|\ee^{2\ii t\lambda^2}
  	 (\ee^{-iy\lambda}-1)g_+\|_{L^2(\ee^{\ii \pi/4}\mathbb{R}_+)}.
  	\end{aligned}
    \end{equation*}
    Let $\lambda=ue^{\ii \pi/4},u\ge0$, then
    \begin{equation*}
  	\begin{aligned}
  	  \|\mathrm{II}\|_{L^2(\Gamma)}
  	  &=\|\frac1{\sqrt{2\pi}}\int_{-\infty}^{0} 
  	  \ee^{-\ii\frac{y^2}{8t}}F_2\check{\mathbf{f}}^\dagger(y)\dd y\|_{L^2(\Gamma)}\\
  	  &\lesssim\int_{-\infty}^{0} 
  	  \left(\int_0^\infty du\left|g(\ee^{\ii\frac\pi4}u)\right|^2
  	  \ee^{-4tu^2}\left|\ee^{-ie^{\ii\frac\pi4}u y}-1\right|^2\right)
  	  ^{\frac12}|\check{\mathbf{f}}^\dagger(y)|\dd y.
  	\end{aligned}
    \end{equation*}
    Since ${\rm Re}(-ie^{\ii\frac\pi4}u y)<0$, then
    \begin{equation*}
  	\left|\ee^{-ie^{\ii\frac\pi4}u y}-1\right|
  	=\left|\int_{0}^{-ie^{\ii\frac\pi4}u y}\ee^zdz\right|\le|uy|.
    \end{equation*}
    Hence 
    \begin{equation*}
  	\begin{aligned}
  	  \|\mathrm{II}\|_{L^2(\Gamma)}
  	  &\lesssim\left(\int_0^\infty du\left|g(\ee^{\ii\frac\pi4}u)\right|^2
  	  \ee^{-4tu^2}\right)
  	  ^{\frac12}\int_{-\infty}^{-t^{\frac{1}{2}}} 
  	  |\check{\mathbf{f}}^\dagger(y)|\dd y\\
  	  &+\left(\int_0^\infty du\left|g(\ee^{\ii\frac\pi4}u)\right|^2
  	  \ee^{-4tu^2}u^2\right)
  	  ^{\frac12}\int_{-t^{\frac{1}{2}}}^{0} 
  	  |y\check{\mathbf{f}}^\dagger(y)|\dd y\\
  	  &\lesssim \left(\int_0^\infty dx\left|g(\ee^{\ii\frac\pi4}\frac{x}{\sqrt{t}})
  	  \right|^2e^{-4x^2}\right)
  	  ^{\frac12}t^{-\frac{1}{4}}t^{-\frac{1}{4}}
  	  +\left(\int_0^\infty dx\left|g(\ee^{\ii\frac\pi4}\frac{x}{\sqrt{t}})
  	  \right|^2e^{-4x^2}x^2\right)
  	  ^{\frac12}t^{-\frac{3}{4}}t^{\frac{1}{4}}\\
  	  &\lesssim t^{-\frac{1}{2}}
  	  \|g(\frac{x}{\sqrt{t}})\|_{L^q(\ee^{\ii\frac\pi4}\mathbb{R}_+)}
  	  \lesssim t^{-\frac{1}{2}+\frac{1}{2q}}\|g\|_{L^q(\ee^{\ii\frac\pi4}\mathbb{R}_+)}
  	  \lesssim t^{-\frac{1}{2}+\frac{1}{2q}}
  	  \|g\|_{H^q(\mathbb{C}\setminus\mathbb{R})}.
  	\end{aligned}
    \end{equation*}
    When $y>0$, then $a=y/4t$ and 
    \begin{equation*}
  	\begin{aligned}
  	  \|F_2\|_{L^2(\Gamma)}
  	  &=\|C^-_{(y/4t,\infty)\rightarrow\Gamma}
  	  (\ee^{-\varepsilon\lambda}
  	  \ee^{2\ii t(\lambda-\frac{y}{4t})^2}
  	  (1-\ee^{iy\lambda})g_+)\|_{L^2}\\
  	  &\lesssim\|C_{(y/4t+\ee^{\ii \pi/4}\mathbb{R}_+)\rightarrow\Gamma}
  	  (\ee^{2\ii t(\lambda-\frac{y}{4t})^2}
  	  (1-\ee^{iy\lambda})g_+)\|_{L^2}\\
  	  &\lesssim\|(\ee^{2\ii t(\lambda-\frac{y}{4t})^2}
  	  (1-\ee^{iy\lambda})g_+)\|_{L^2(y/4t+\ee^{\ii \pi/4}\mathbb{R}_+)}.
  	\end{aligned}
    \end{equation*}
    Let $\lambda=\frac{y}{4t}+ue^{\ii \pi/4},u\ge0$, then
    \begin{equation*}
  	\begin{aligned}
  	  \|\mathrm{II}\|_{L^2(\Gamma)}
  	  &\lesssim\int_{0}^{\infty} 
  	  \left(\int_0^\infty du\left|g(\frac{y}{4t}+ue^{\ii \pi/4})\right|^2
  	  \ee^{-4tu^2}\left|1-\ee^{iy(\frac{y}{4t}+ue^{\ii \pi/4})}\right|^2\right)
  	  ^{\frac12}|\check{\mathbf{f}}^\dagger(y)|\dd y\\
  	  &\lesssim\int_{t^{\frac12}}^{\infty} 
  	  \left(\int_{0}^\infty du\left|g(\frac{y}{4t}+ue^{\ii \pi/4})\right|^2
  	  \ee^{-4tu^2}\right)^{\frac12}|\check{\mathbf{f}}^\dagger(y)|\dd y\\
  	  &+\int_{0}^{t^{\frac12}} 
  	  \left(\int_{0}^\infty du\left|g(\frac{y}{4t}+ue^{\ii \pi/4})\right|^2
  	  \ee^{-4tu^2}
  	  (|\ee^{-\ii\frac{y^2}{4t}}-1|^2+|1-\ee^{iyue^{\ii \pi/4}}|)
  	  \right)
  	  ^{\frac12}|\check{\mathbf{f}}^\dagger(y)|\dd y.
  	\end{aligned}
    \end{equation*}
    Together with $|\ee^{-\ii\frac{y^2}{4t}}-1|\lesssim t^{-1}y^2$,
    \begin{equation*}
  	\begin{aligned}
  	  \|\mathrm{II}\|_{L^2(\Gamma)}
  	  &\lesssim t^{-\frac14}
  	  \left(\int_{0}^\infty dx\left|g(\frac{y}{4t}+\frac{x}{\sqrt{t}}\ee^{\ii \pi/4})\right|^2
  	  \ee^{-4tx^2}\right)^{\frac12}
  	  \int_{t^{\frac12}}^{\infty}y^{-1} |y\check{\mathbf{f}}^\dagger(y)|\dd y\\
  	  &+t^{-1}t^{-\frac14}
  	  \left(\int_{0}^\infty dx\left|g(\frac{y}{4t}+\frac{x}{\sqrt{t}}\ee^{\ii \pi/4})\right|^2
  	  \ee^{-4tx^2}\right)^{\frac12}
  	  \int_{0}^{t^{\frac12}} y |y\check{\mathbf{f}}^\dagger(y)|\dd y\\
  	  &+t^{-\frac34}
  	  \left(\int_{0}^\infty dx\left|g(\frac{y}{4t}+\frac{x}{\sqrt{t}}\ee^{\ii \pi/4})\right|^2
  	  \ee^{-4tx^2}x^2\right)^{\frac12}
  	  \int_{0}^{t^{\frac12}} |y\check{\mathbf{f}}^\dagger(y)|\dd y\\
  	  &\lesssim t^{-\frac12}
  	  \|g(\frac{y}{4t}+\frac{x}{\sqrt{t}}\ee^{\ii \pi/4})\|_{L^q(\mathbb{R}_+)}
  	  \lesssim t^{-\frac12+\frac{1}{2q}}
  	  \|g\|_{L^q(\frac{y}{4t}+\ee^{\frac{\ii\pi}4}\mathbb{R}_+)}
  	  \lesssim t^{-1/2+1/2q}\|g\|_{H^q(\mathbb{C}\setminus\mathbb{R})}.
  	\end{aligned}
    \end{equation*}
    Letting $\varepsilon\downarrow0$ and adding the estimates for $\mathrm{I}$ and $\mathrm{II}$, 
    the result follows immediately.
  \end{proof}



  \begin{proof}[Proof of Lemma \ref{bdd-M1-M2}]
    Our proof follows that found in \cite[Lemma 4.8]{deift2002long}.
    \begin{equation}
  	\begin{aligned}
  	  \int\hat{\pmb{\mu}}_1 \hat{\mathbf{w}}_1-\int\hat{\pmb{\mu}}_2 \hat{\mathbf{w}}_2
  	& =\int \hat{\mathbf{w}}_1-\hat{\mathbf{w}}_2+
  	\int(\hat{\pmb{\mu}}_2-\mathbb{I}_{3})(\hat{\mathbf{w}}_1-\hat{\mathbf{w}}_2)+\int(\hat{\pmb{\mu}}_1-\hat{\pmb{\mu}}_2)\hat{\mathbf{w}}_1 \\
  	&\equiv\mathrm{I}+\mathrm{II}+\mathrm{III}.
  	\end{aligned}
    \end{equation}
    For $\mathrm{I}$, it can be decomposed into four parts 
    which have the same bound of $t^{-\frac{3}{4}}$:
    \begin{equation*}
  	\begin{aligned}
  	  \int \hat{\mathbf{w}}_1-\hat{\mathbf{w}}_2
  	&=\int_{\xi}^{+\infty}\hat{\mathbf{w}}_1^--\hat{\mathbf{w}}_2^--\int_{-\infty}^{\xi}\hat{\mathbf{w}}_1^--\hat{\mathbf{w}}_2^-\\
  	&+\int_{\xi}^{+\infty}\hat{\mathbf{w}}_1^+-\hat{\mathbf{w}}_2^+-\int_{-\infty}^{\xi}\hat{\mathbf{w}}_1^+-\hat{\mathbf{w}}_2^+,
  	\end{aligned}
    \end{equation*}
    we only give the rest of the details for the first term, the other terms 
    are easily inferred.

    Set $\mathbf{f}(\lambda)=\mathbf{R}(\lambda)-[\mathbf{R}](\lambda)\in H^{1,1}(\mathbb{R})$, 
    then 
    \begin{equation}
  	\left|\int_{\xi}^{+\infty}\hat{\mathbf{w}}_1^--\hat{\mathbf{w}}_2^-\right|
  	\leq\left|\int_{\xi}^{\xi+t^{-1/2}}
  	\ee^{-2\ii t\theta}\det\pmb{\delta}_-\mathbf{f}\pmb{\delta}_-\right|
  	+\left|\int_{\xi+t^{-1/2}}^{+\infty}
  	\ee^{-2\ii t\theta}\det\pmb{\delta}_-\mathbf{f}\pmb{\delta}_-\right|.
    \end{equation}
    Since $\mathbf{f}(\lambda)\in H^{1,1}(\mathbb{R})$ and $\mathbf{f}(\xi)=0$, we have that 
    $\left|\mathbf{f}(\lambda)\right|\leq\left|\lambda-\xi\right|^{1/2}\|\mathbf{f}\|_{H^{1,1}}$. Then 
    \begin{equation*}
  	\begin{aligned}
  	  \left|\int_{\xi}^{\xi+t^{-1/2}}
  	  \ee^{-2\ii t\theta}\det\pmb{\delta}_-\mathbf{f}\pmb{\delta}_-\dd\lambda\right|
  	  &=\left|\int_{0}^{1}\ee^{-2i\lambda_1^2+2\ii t\xi^2}[\det\pmb{\delta}_-\mathbf{f}\pmb{\delta}_-]
  	  (\frac{\lambda_1}{\sqrt{t}}+\xi)\dd\lambda_1t^{-\frac{1}{2}}\right|\\   
  	  &\leq t^{-\frac{1}{2}}\|\det\pmb{\delta}_-\|_{L^{\infty}}\|\pmb{\delta}_-\|_{L^{\infty}}
  	  \int_{0}^{1}\left|\mathbf{f}(\frac{\lambda_1}{\sqrt{t}}+\xi)\right|\dd\lambda_1\\
  	  &\lesssim t^{-\frac{1}{2}}\int_{0}^{1}\left|\lambda_1t^{-1/2}\right|^{1/2}\dd\lambda_1\\
  	  &\lesssim t^{-\frac{3}{4}}.
  	\end{aligned}
    \end{equation*}
    For the second term, 
    \begin{equation*}
  	\begin{aligned}
  	  &\quad\int_{\xi+t^{-1/2}}^{+\infty}\ee^{-2\ii t\theta}\det\pmb{\delta}_-\mathbf{f}\pmb{\delta}_-\dd\lambda\\
  	  &=\int_{\xi+t^{-1/2}}^{+\infty}\det\pmb{\delta}_-\mathbf{f}\pmb{\delta}_-\frac{\dd\ee^{-2\ii t\theta}}{-4\ii t(\lambda-\xi)}\\
  	  &=\frac{1}{4i\sqrt{t}}[\det\pmb{\delta}_-\mathbf{f}\pmb{\delta}_-](\xi+t^{-1/2})\\
  	  &+
  	  \frac{1}{4\ii t}\int_{\xi+t^{-1/2}}^{+\infty}\ee^{-2\ii t\theta}
  	  (\frac{(\det\pmb{\delta}_-)^{\prime}\mathbf{f}\pmb{\delta}_-}{\lambda-\xi}+
  	  \frac{\det\pmb{\delta}_-\mathbf{f}^{\prime}\pmb{\delta}_-}{\lambda-\xi}+
  	  \frac{\det\pmb{\delta}_-\mathbf{f}(\pmb{\delta}_-)^{\prime}}{\lambda-\xi}-
  	  \frac{\det\pmb{\delta}_-\mathbf{f}\pmb{\delta}_-}{(\lambda-\xi)^2})\dd\lambda\\
  	  &\equiv\mathrm{II}_1+\mathrm{II}_2+\mathrm{II}_3+\mathrm{II}_4+\mathrm{II}_5.
  	\end{aligned}
    \end{equation*}
    For $\mathrm{II}_1$, 
    \begin{equation*}
  	\left|\mathrm{II}_1\right|\lesssim 
  	t^{-1/2}\|\det\pmb{\delta}_-\|_{L^{\infty}}\|\pmb{\delta}_-\|_{L^{\infty}}\left|\mathbf{f}(\xi+t^{-1/2})\right|
  	\lesssim t^{-\frac{3}{4}}.
    \end{equation*}
    For $\mathrm{II}_2$, we consider the boundedness of $(\det\pmb{\delta}_-)^{\prime}$ 
    as $(X^{-1}_+)^{\prime}$ in Lemma \ref{bdd-V3-V4}, then we have 
    \begin{equation*}
  	\begin{aligned}
  	  &|(\det\pmb{\delta}_-)^{\prime}|\le\mathrm{II}^{(1)}+\mathrm{II}^{(2)},\\
  	  &|\mathrm{II}^{(1)}|\lesssim\frac{1}{|s-\xi|},\quad
  	  \|\mathrm{II}^{(2)}\|_{L^2}\lesssim1.
  	\end{aligned}
    \end{equation*}

    Therefore
    \begin{equation*}
  	\begin{aligned}
  	  \left|\mathrm{II}_2\right|
  	  &\lesssim t^{-1}\|\pmb{\delta}_-\|_{L^{\infty}}
  	  \int_{\xi+t^{-1/2}}^{+\infty}
  	  \frac{(\left|\mathrm{II}^{(1)}\right|+\left|\mathrm{II}^{(2)}\right|)\left|\mathbf{f}\right|}
  	  {\left|\lambda-\xi\right|}\dd\lambda\\
  	  &\lesssim t^{-1}(\int_{\xi+t^{-1/2}}^{+\infty}
  	  \frac{\left|\lambda-\xi\right|^{1/2}}{\left|\lambda-\xi\right|^2}d\lambda
  	  +\|\mathrm{II}^{(2)}\|_{L^{2}}\|\mathbf{f}\|_{L^{\infty}}
  	  (\int_{\xi+t^{-1/2}}^{+\infty}\frac{1}{\left|\lambda-\xi\right|^2}\dd\lambda)^{1/2})\\
  	  &\lesssim t^{-\frac{3}{4}}.
  	\end{aligned}
    \end{equation*}
    For $\mathrm{II}_3$, 
    \begin{equation*}
  	\left|\mathrm{II}_3\right|\lesssim t^{-1}
  	\|\mathbf{f}^{\prime}\|_{L^{2}}
  	  (\int_{\xi+t^{-1/2}}^{+\infty}\frac{1}{\left|\lambda-\xi\right|^2}\dd\lambda)^{1/2}
  	  \lesssim t^{-\frac{3}{4}}.
    \end{equation*}
    For $\mathrm{II}_4$, 
    by the boundedness of 
    $\|\pmb{\delta}_-^{\prime}\|_{L^2}$ in Lemma \ref{bdd-V3-V4},
    we have 
    \begin{equation*}
  	\left|\mathrm{II}_4\right|
  	\lesssim t^{-1}\|\pmb{\delta}^{\prime}_-\|_{L^{2}}
  	(\int_{\xi+t^{-1/2}}^{+\infty}\frac{1}{\left|\lambda-\xi\right|^2}\dd\lambda)^{1/2}
  	\lesssim t^{-\frac{3}{4}}.
    \end{equation*}
    For $\mathrm{II}_5$, 
    \begin{equation*}
  	\left|\mathrm{II}_5\right|\lesssim t^{-1}
  	\int_{\xi+t^{-1/2}}^{+\infty}
  	  \frac{\left|\lambda-\xi\right|^{1/2}}{\left|\lambda-\xi\right|^2}\dd\lambda
  	  \lesssim t^{-\frac{3}{4}}.
    \end{equation*}
    By the above calculations,
    \begin{equation*}
  	\left|\int_{\xi+t^{-1/2}}^{+\infty}
  	\ee^{-2\ii t\theta}\det\pmb{\delta}_-\mathbf{f}\pmb{\delta}_-\right|\lesssim t^{-\frac{3}{4}}.
    \end{equation*}
    Therefore $\left|\mathrm{I}\right|\lesssim t^{-\frac{3}{4}}$.

    For $\mathrm{II}$, by triangularity,
    \begin{equation*}
  	\begin{aligned}
  	  \mathrm{II}
  	  &=\int(C_{\hat{\mathbf{w}}_2}\hat{\pmb{\mu}}_2)(\hat{\mathbf{w}}_1-\hat{\mathbf{w}}_2)\\
  	  &=\int (C^+_{\mathbb{R}_{\xi}} \hat{\pmb{\mu}}_2 \hat{\mathbf{w}}_2^-)(\hat{\mathbf{w}}_1^+-\hat{\mathbf{w}}_2^+)+
  	  \int (C^- _{\mathbb{R}_{\xi}}\hat{\pmb{\mu}}_2 \hat{\mathbf{w}}_2^+)(\hat{\mathbf{w}}_1^--\hat{w}_2^-)\\
  	  &\equiv\mathrm{II}_++\mathrm{II}_- .
  	\end{aligned}
    \end{equation*}
    Extending the integrand trivially from $\mathbb{R}_\xi$ to a complete contour
    $\Gamma_{\xi}=\mathbb{R}\cup(\xi+\ee^{\ii\pi/2}\mathbb{R}_-)\cup(\xi+\ee^{-\ii\pi/2}\mathbb{R}_-)$ 
    and using the following properties
    \begin{equation}\label{property-C}
  	C_{\Gamma_{\xi}}^+C_{\Gamma_{\xi}}^-
  	=C_{\Gamma_{\xi}}^-C_{\Gamma_{\xi}}^+=0,\quad
  	C^+_{\Gamma_{\xi}}-C^-_{\Gamma_{\xi}}=1,
    \end{equation}
    we can have 
    \begin{equation*}
  	\begin{aligned}
  	  |\mathrm{II}_+|
  	  &=\left|\int (C^+_{\Gamma_{\xi}} \hat{\pmb{\mu}}_2 \hat{\mathbf{w}}_2^-)(C^+_{\Gamma_{\xi}}-C^-_{\Gamma_{\xi}})(\hat{\mathbf{w}}_1^+-\hat{\mathbf{w}}_2^+)\right|\\
  	  &=\left|-\int (\hat{\mathbf{w}}_1^+-\hat{\mathbf{w}}_2^+)C^-_{\Gamma_{\xi}}C^+_{\Gamma_{\xi}} (\hat{\pmb{\mu}}_2 \hat{\mathbf{w}}_2^-)
  	  -\int (C^+_{\Gamma_{\xi}} \hat{\pmb{\mu}}_2 \hat{\mathbf{w}}_2^-)C^-_{\Gamma_{\xi}}(\hat{\mathbf{w}}_1^+-\hat{\mathbf{w}}_2^+)\right|\\
  	  &=\left|\int (C^+_{\Gamma_{\xi}} \hat{\pmb{\mu}}_2 \hat{\mathbf{w}}_2^-)C^-_{\Gamma_{\xi}}(\hat{\mathbf{w}}_1^+-\hat{\mathbf{w}}_2^+)\right|.
  	\end{aligned}
    \end{equation*}
    By Lemma \ref{lemma3-CNLS} and Lemma \ref{lemma1-CNLS}, 
    \begin{equation*}
  	\begin{aligned}
  	  \|C^+ _{\Gamma_{\xi}}\hat{\pmb{\mu}}_2 \hat{\mathbf{w}}_2^-\|_{L^2}
  	  &\leq\|C^+_{\Gamma_{\xi}} (\hat{\pmb{\mu}}_2-\mathbb{I}_3) \hat{\mathbf{w}}_2^-\|_{L^2}+
  	  \|C^+ _{\Gamma_{\xi}} \hat{\mathbf{w}}_2^-\|_{L^2}\\
  	  &\lesssim\|\hat{\pmb{\mu}}_2-\mathbb{I}_3\|_{L^2}+t^{-\frac{1}{4}}\\
  	  &\lesssim t^{-\frac{1}{4}}.
  	\end{aligned}
    \end{equation*}
    By Lemma \ref{lemma2-CNLS},
    \begin{equation*}
  	\|C^-_{\Gamma_{\xi}}(\hat{\mathbf{w}}_1^+-\hat{\mathbf{w}}_2^+)\|_{L^2}
    \lesssim t^{-\frac{1}{2}}.
    \end{equation*}



    Hence 
    \begin{equation*}
  	\|\mathrm{II}_+\|_{L^2}\leq\|C^+_{\Gamma_{\xi}} \hat{\pmb{\mu}}_2 \hat{\mathbf{w}}_2^-\|_{L^2}
    \|C^-_{\Gamma_{\xi}}(\hat{\mathbf{w}}_1^+-\hat{\mathbf{w}}_2^+)\|_{L^2}
  	\lesssim t^{-\frac{3}{4}}.
    \end{equation*}

    The estimate for $\mathrm{II}_-$ is similar and therefore 
    $\left|\mathrm{II}\right|\lesssim t^{-\frac{3}{4}}$. Then we compute
    \begin{equation*}
  	\hat{\pmb{\mu}}_1-\hat{\pmb{\mu}}_2
  	=(1-C_{\hat{\mathbf{w}}_2})^{-1}C_{\hat{\mathbf{w}}_1-\hat{\mathbf{w}}_2}\hat{\pmb{\mu}}_1
  	=C_{\hat{\mathbf{w}}_1-\hat{\mathbf{w}}_2}\hat{\pmb{\mu}}_1+C_{\hat{\mathbf{w}}_2}h ,
    \end{equation*}
    where $\pmb{h}=(1-C_{\hat{\mathbf{w}}_2})^{-1}C_{\hat{\mathbf{w}}_1-\hat{\mathbf{w}}_2}\hat{\pmb{\mu}}_1$. 
    Again by triangularity and equation \eqref{property-C},
    \begin{equation*}
  	\begin{aligned}
  	\mathrm{III}
  	&=\int(C_{\hat{\mathbf{w}}_1-\hat{\mathbf{w}}_2}\hat{\pmb{\mu}}_1)\hat{\mathbf{w}}_1+\int(C_{\hat{\mathbf{w}}_2}\pmb{h})\hat{\mathbf{w}}_1 \\
  	&=-\int\left(C^+_{\mathbb{R}_\xi}\hat{\pmb{\mu}}_1(\hat{\mathbf{w}}_1^--\hat{\mathbf{w}}_2^-)\right)C^-_{\mathbb{R}_\xi}
    \hat{\mathbf{w}}_1^++
  	\int\left(C^-_{\mathbb{R}_\xi}\hat{\pmb{\mu}}_1(\hat{\mathbf{w}}_1^+-\hat{\mathbf{w}}_2^+)\right)C^+_{\mathbb{R}_\xi}\hat{\mathbf{w}}_1^- \\
  	&\quad-\int\left(C^+_{\mathbb{R}_\xi}\pmb{h}\mathbf{w}_2^-\right)C^-_{\mathbb{R}_\xi}\hat{\mathbf{w}}_1^++
  	\int\left(C^-_{\mathbb{R}_\xi}\pmb{h}\mathbf{w}_2^+\right)C^+_{\mathbb{R}_\xi}\hat{\mathbf{w}}_1^-\\
  	&\equiv \hat{\mathrm{III}}_++\hat{\mathrm{III}}_-
  	+\tilde{\mathrm{III}}_++\tilde{\mathrm{III}}_- .
  	\end{aligned}
    \end{equation*}
    By Lemma \ref{lemma1-CNLS} and Lemma \ref{lemma4-CNLS},
    \begin{equation*}
  	\left|\hat{\mathrm{III}}_+\right|\leq\|C^+_{\mathbb{R}_\xi}\hat{\pmb{\mu}}_1(\hat{\mathbf{w}}_1^--\hat{\mathbf{w}}_2^-)\|_{L^2}
  	\|C^-_{\mathbb{R}_\xi}\hat{\mathbf{w}}_1^+\|_{L^2}\lesssim t^{-\frac{1}{2}+\frac{1}{(2p)}}t^{-\frac{1}{4}}
  	\lesssim t^{-\frac{3}{4}+\frac{1}{(2p)}},
    \end{equation*}
    with a similar estimate for $\mathrm{III}_-^{'}$. Again by Lemma \ref{lemma4-CNLS}, 
    $\|C^{\pm}_{\mathbb{R}_\xi}\hat{\pmb{\mu}}_1(\hat{\mathbf{w}}_1^{\mp}-\hat{\mathbf{w}}_2^{\mp})\|_{L^2}\lesssim t^{-\frac{1}{2}+\frac{1}{(2p)}}$ 
    and hence $\|\pmb{h}\|_{L^2}\lesssim t^{-\frac{1}{2}+\frac{1}{(2p)}}$. Together with 
    Lemma \ref{lemma1-CNLS}, this implies that 
    $\left|\tilde{\mathrm{III}}_{\pm}\right|\lesssim t^{-\frac{3}{4}+\frac{1}{(2p)}}$ and 
    therefore $\left|\mathrm{III}\right|\lesssim t^{-\frac{3}{4}+\frac{1}{(2p)}}$. 
    Adding the estimates for $\mathrm{I}$, $\mathrm{II}$, and $\mathrm{III}$, the result follows immediately.
  \end{proof}





  \section*{Appendix B}
  \setcounter{equation}{0} % 重置方程编号
  \renewcommand{\theequation}{B.\arabic{equation}} % 设置方程编号格式
  In the Appendix B, we will provide a detailed procedure for solving RHP \ref{rhp-N} and 
  obtaining the long-time asymptotic behavior of the solution $\mathbf{N}(y)$. 
  Set $\pmb{\sigma}_3=
  \begin{pmatrix}
    1&0\\
    0&-1
  \end{pmatrix}$, $\kappa_\xi=\kappa(\xi)$  and 
  $\pmb{\Psi}(y)=\eta^{-\pmb{\sigma}_3}\mathbf{N}(y)\eta^{\pmb{\sigma}_3}y^{\ii\kappa_\xi
  \pmb{\sigma}_3}\mathrm{\ee}^{-\frac14\ii y^2\pmb{\sigma}_3}$, 
  then we have 
  \begin{equation*}
	\pmb{\Psi}_+(y)=\pmb{\Psi}_-(y)\mathbf{v}_0,\quad \mathbf{v}_0=y^{-\ii\kappa_\xi\hat{\pmb{\sigma}}_3}
	\mathrm{e}^{\frac14\ii y^2\hat{\pmb{\sigma}}_3}
	\eta^{-\hat{\pmb{\sigma}}_3}\V_{N}(y).
  \end{equation*}
  Clearly, the jump matrix $\mathbf{v}_0$ is constant along each ray. Thus
  \begin{equation*}
	\frac{\mathrm{d}\pmb{\Psi}_+(y)}{\mathrm{d}y}=
	\frac{\mathrm{d}\pmb{\Psi}_-(y)}{\mathrm{d}y}\mathbf{v}_0,
  \end{equation*}
  and $\frac{\mathrm{d}\pmb{\Psi}(y)}{\mathrm{d}y}\pmb{\Psi}^{-1}(y)$ has no jump discontinuity 
  along any of the rays. Moreover, it follows from the expansion
  $\mathbf{N}(y)=\mathbb{I}_3+\frac{\mathbf{N}_1}{y}+O(y^{-2}),\quad y\rightarrow\infty$ that 
  \begin{equation*}
	\begin{aligned}
	  \frac{\mathrm{d}\pmb{\Psi}}{\mathrm{d}y}\pmb{\Psi}^{-1}
	  &=\eta^{-\hat{\pmb{\sigma}}_3}\left(\frac{\dd \mathbf{N}}{\dd y}\mathbf{N}^{-1}-
	  \frac{1}{2}\ii y\mathbf{N}\pmb{\sigma}_3\mathbf{N}^{-1}+
	  \ii\kappa_\xi y^{-1}\mathbf{N}\pmb{\sigma}_3\mathbf{N}^{-1}\right)\\
	  &=\oo(y^{-1})-\frac{1}{2}\ii y\pmb{\sigma}_3-\frac12\ii\eta^{-\hat{\pmb{\sigma}}_3}[\mathbf{N}_1,\pmb{\sigma}_3].
	\end{aligned}
  \end{equation*}
  By the Liouville theorem, we can obtain 
  \begin{equation}\label{2*2Psi-equation}
	\frac{\mathrm{d}\pmb{\Psi}(y)}{\mathrm{d}y}+\frac12\ii y\pmb{\sigma}_3\pmb{\Psi}(y)
	=\beta\pmb{\Psi}(y),
  \end{equation}
  where 
  \begin{equation}\label{relation-beta-N}
	\beta=-\frac12\ii\eta^{-\hat{\pmb{\sigma}}_3}[\mathbf{N}_1,\pmb{\sigma}_3]
	=\begin{pmatrix}
		0&\ii\eta^{-2}[\mathbf{N}_1]_{12}\\
		-\ii\eta^{2}[\mathbf{N}_1]_{21}&0
	\end{pmatrix}=
  \begin{pmatrix}
    0&\beta_{12}\\
    \beta_{21}&0
  \end{pmatrix}.
  \end{equation}
  We can further show that the solution $\mathbf{N}(y)$ for RHP \ref{rhp-N} is unique, 
  and then obtain the symmetry of $\mathbf{N}(y)$ 
  \begin{equation}
    \mathbf{N}^{-1}(y)=\mathbf{N}^\dagger(y^*),
  \end{equation}
  which implies 
  \begin{equation}\label{relation-b12-b21}
    \beta_{12}=-\beta^*_{21}.
  \end{equation}

From equation \eqref{2*2Psi-equation} we obain
\begin{equation}\label{relation-Psi-ij}
  \begin{aligned}
    \frac{\mathrm{d}\pmb{\Psi}_{11}(y)}{\mathrm{d}y}+\frac \ii2y\pmb{\Psi}_{11}& =\beta_{12}\pmb{\Psi}_{21},\\
    \frac{\mathrm{d}\pmb{\Psi}_{12}(y)}{\mathrm{d}y}+\frac \ii2y\pmb{\Psi}_{12}& =\beta_{12}\pmb{\Psi}_{22},\\
    \frac{\mathrm{d}\pmb{\Psi}_{21}(y)}{\mathrm{d}y}-\frac \ii2y\pmb{\Psi}_{21}& =\beta_{21}\pmb{\Psi}_{11},\\
    \frac{\mathrm{d}\pmb{\Psi}_{22}(y)}{\mathrm{d}y}-\frac \ii2y\pmb{\Psi}_{22}& =\beta_{21}\pmb{\Psi}_{12},
  \end{aligned}
\end{equation}
and
\begin{equation}\label{psi11-psi22}
  \begin{aligned}
  \frac{\mathrm{d}^2\pmb{\Psi}_{11}(y)}{\mathrm{d}y^2}& =
  \left(-\frac \ii2-\frac14y^2+\beta_{12}\beta_{21}\right)\pmb{\Psi}_{11}(y), \\
  \frac{\mathrm{d}^2\pmb{\Psi}_{22}(y)}{\mathrm{d}y^2}& 
  =\left(\frac \ii2-\frac14y^2+\beta_{12}\beta_{21}\right)\pmb{\Psi}_{22}(y).
  \end{aligned}
\end{equation}

As is well known, the Weber equation
\begin{equation}\label{weber-eq}
  \frac{\mathrm{d}^2g(\zeta)}{\mathrm{d}\zeta^2}+
  \left(a+\frac12-\frac{\zeta^2}4\right)g(\zeta)=0
\end{equation}
has the solution
\begin{equation}\label{soliton-weber}
  g(\zeta)=c_1D_a(\zeta)+c_2D_a(-\zeta),
\end{equation}
where $D_a(\cdot)$ denotes the standard parabolic-cylinder function \cite{NIST_DLMF_2016} and satisfies
\begin{equation}\label{parabolic-cylinder-function}
  \begin{aligned}
    &\frac{\mathrm{d}D_a(\zeta)}{\mathrm{d}\zeta}+\frac\zeta2D_a(\zeta)-aD_{a-1}(\zeta)=0,\\
    &D_a(\pm\zeta)=\frac{\Gamma(a+1)\mathrm{e}^{\frac{\ii\pi a}2}}
    {\sqrt{2\pi}}D_{-a-1}(\pm \ii\zeta)+\frac{\Gamma(a+1)\mathrm{e}^{-\frac{\ii\pi a}2}}
    {\sqrt{2\pi}}D_{-a-1}(\mp \ii\zeta).
  \end{aligned}
\end{equation}
From Whittaker and Watson \cite{Whittaker_Watson_1927}, we obain the asymptotic properties of $D_a(\cdot)$
\begin{equation}\label{asymptotic-Da}
  D_a(\zeta)=
  \begin{cases}
    \zeta^a \ee^{-\frac{\zeta^2}{4}}(1+\mathcal{O}(\zeta^{-2})),&\quad|\arg(\zeta)|<\frac{3\pi}{4},\\
    \zeta^a \ee^{-\frac{\zeta^2}{4}}(1+\mathcal{O}(\zeta^{-2}))
    -\frac{\sqrt{2\pi}}{\Gamma(-a)}\mathrm e^{a\pi \ii
    +\frac{\zeta^2}{4}}\zeta^{-a-1}(1+\mathcal{O}(\zeta^{-2})),&\quad\frac{\pi}{4}<\arg(\zeta)<\frac{5\pi}{4},\\
    \zeta^a\mathrm e^{-\frac{\zeta^2}{4}}(1+\mathcal{O}(\zeta^{-2}))
    -\frac{\sqrt{2\pi}}{\Gamma(-a)}\mathrm e^{-a\pi \ii
    +\frac{\zeta^2}{4}}\zeta^{-a-1}(1+\mathcal{O}(\zeta^{-2})),&\quad-\frac{5\pi}{4}<\arg(\zeta)<-\frac{\pi}{4},
  \end{cases}
\end{equation}
where $\Gamma$ is the Gamma function.
Set $a=-\ii\beta_{12}\beta_{21}$, it follows from equation \eqref{psi11-psi22} and 
equation \eqref{soliton-weber} that 
\begin{equation}
  \begin{aligned}
  &\pmb{\Psi}_{11}(y) =c_1D_{-a}\left(\mathrm{e}^{-\frac{3\pi \ii}{4}}y\right)
  +c_2D_{-a}\left(\mathrm{e}^{\frac{\pi \ii}{4}}y\right), \\
  &\pmb{\Psi}_{22}(y) =c_3D_a\left(\mathrm{e}^{\frac{3\pi \ii}4}y\right)+
  c_4D_a\left(\mathrm{e}^{-\frac{\pi \ii}4}y\right) .
  \end{aligned}
\end{equation}

As $y\rightarrow\infty$, 
$\pmb{\Psi}(y)y^{-\ii\kappa_\xi\pmb{\sigma}_3}\mathrm{e}^{\frac14\ii y^2\pmb{\sigma}_3}=\eta^{-\pmb{\sigma}_3}\mathbf{N}(y)\eta^{\pmb{\sigma}_3}\rightarrow\mathbb{I}_2$ and hence
\begin{equation}\label{asymptotic-Psi}
  \pmb{\Psi}_{11}(y)\rightarrow y^{\ii\kappa_\xi}\mathrm{e}^{-\frac14\ii y^2},\quad
  \pmb{\Psi}_{22}(y)\rightarrow y^{-\ii\kappa_\xi}\mathrm{e}^{\frac14\ii y^2}.
\end{equation}
If $\mathrm{arg}(y)\in[-\frac{\pi}{4},\frac{3\pi}{4}]$, we have
\begin{equation}
  D_a(y\ee^{-\frac{\pi}{4}\ii})\to 
  \ee^{-\frac{\pi}{4}\ii a} y^a \ee^{\frac14\ii y^2},
\end{equation}
and then $c_3=0$, $c_4=\ee^{\frac{\pi}{4}k_\xi}$, hence
\begin{equation*}
  \pmb{\Psi}_{22}(y)=\ee^{\frac{\pi\kappa_\xi}{4}}
  D_a(y\ee^{-\frac{\pi}{4}\ii}),\quad a=-\ii\kappa_\xi,\quad 
  \kappa_\xi=\beta_{12}\beta_{21},
\end{equation*}
by equation \eqref{asymptotic-Da} and equation \eqref{asymptotic-Psi}. Consequently, 
it follows from equation \eqref{relation-Psi-ij} and equation \eqref{parabolic-cylinder-function} that
\begin{equation*}
  \pmb{\Psi}_{12}(y)=\beta_{12}\ee^{\frac{\pi}{4}\kappa_\xi-\frac34\pi \ii}D_{a-1}(y\ee^{-\frac{\pi}{4}\ii}).
\end{equation*}
If $\arg(y)\in[\frac{3\pi}{4},\frac{7\pi}{4}]$, we can obain similar conclusions
\begin{equation*}
  \pmb{\Psi}_{22}(y)=\ee^{\frac{-3\pi\kappa_\xi}{4}}D_a(y\ee^{\frac{3\pi}{4}\ii}),\quad
  \pmb{\Psi}_{12}(y)=\beta_{12}\ee^{-\frac{3\pi\kappa_\xi}{4}+\frac14\pi \ii}D_{a-1}(y\ee^{\frac{3\pi}{4}\ii}).
\end{equation*}
If $\arg(y)\in[-\frac{3\pi}{4},\frac{\pi}{4}]$, we have
\begin{equation}
  D_{-a}(y\ee^{\frac{\pi}{4}\ii})\to 
  \ee^{-\frac{\pi}{4}ia} y^{-a} \ee^{-\frac14iy^2},
\end{equation}
and then $c_1=0$, $c_2=\ee^{\frac{\pi}{4}k_\xi}$, hence
\begin{equation*}
  \pmb{\Psi}_{11}(y)=\ee^{\frac{\pi\kappa_\xi}{4}}D_{-a}(y\ee^{\frac{\pi}{4}\ii}).
\end{equation*}
Consequently, 
it follows from equation \eqref{relation-Psi-ij} and equation \eqref{parabolic-cylinder-function} that
\begin{equation*}
  \pmb{\Psi}_{21}(y)=\beta_{21} \ee^{\frac{\pi}{4}\kappa_\xi+\frac34\pi \ii}D_{-a-1}(y\ee^{\frac{\pi}{4}\ii}).
\end{equation*}
If $\arg(y)\in[\frac{\pi}{4},\frac{5\pi}{4}]$, we can also obain similar conclusions
\begin{equation*}
  \pmb{\Psi}_{11}(y)=
  \ee^{-\frac{3\pi}{4}\kappa_\xi}D_{-a}(y\ee^{-\frac{3\pi \ii}{4}}),\quad
  \pmb{\Psi}_{21}(y)=\beta_{21}\ee^{-\frac{3\pi}{4}\kappa_\xi-\frac14\pi \ii}D_{-a-1}(y\ee^{-\frac{3\pi}{4}\ii}).
\end{equation*}

Hence, the unique solution $\pmb{\Psi}(y)$ to problem \eqref{2*2Psi-equation} can be given by
\begin{equation}\label{weber-equ-Psi}
  \pmb{\Psi}(y)=
  \begin{cases}
    \begin{bmatrix}
      \ee^{\frac{\pi\kappa_\xi}{4}}D_{-a}(y\ee^{\frac{\pi}{4}\ii})&\beta_{12}\ee^{\frac{\pi}{4}\kappa_\xi-\frac34\pi \ii}D_{a-1}(y\ee^{-\frac{\pi}{4}\ii})\\
      \beta_{21} \ee^{\frac{\pi}{4}\kappa_\xi+\frac34\pi \ii}D_{-a-1}(y\ee^{\frac{\pi}{4}\ii})&\ee^{\frac{\pi\kappa_\xi}{4}}D_a(y\ee^{-\frac{\pi}{4}\ii})
    \end{bmatrix},
    &\mathrm{arg}(y)\in[-\frac{\pi}{4},\frac{\pi}{4}],\\
    \begin{bmatrix}
      \ee^{-\frac{3\pi}{4}\kappa_\xi}D_{-a}(y\ee^{-\frac{3\pi \ii}{4}})&\beta_{12}\ee^{\frac{\pi}{4}\kappa_\xi-\frac34\pi \ii}D_{a-1}(y\ee^{-\frac{\pi}{4}\ii})\\
      \beta_{21}\ee^{-\frac{3\pi}{4}\kappa_\xi-\frac14\pi \ii}D_{-a-1}(y\ee^{-\frac{3\pi}{4}\ii})&\ee^{\frac{\pi\kappa_\xi}{4}}D_a(y\ee^{-\frac{\pi}{4}\ii})
    \end{bmatrix},
    &\mathrm{arg}(y)\in[\frac{\pi}{4},\frac{3\pi}{4}],\\
    \begin{bmatrix}
      \ee^{-\frac{3\pi}{4}\kappa_\xi}D_{-a}(y\ee^{-\frac{3\pi \ii}{4}})&\beta_{12}\ee^{-\frac{3\pi\kappa_\xi}{4}+\frac14\pi \ii}D_{a-1}(y\ee^{\frac{3\pi}{4}\ii})\\
      \beta_{21}\ee^{-\frac{3\pi}{4}\kappa_\xi-\frac14\pi \ii}D_{-a-1}(y\ee^{-\frac{3\pi}{4}\ii})&\ee^{\frac{-3\pi\kappa_\xi}{4}}D_a(y\ee^{\frac{3\pi}{4}\ii})
    \end{bmatrix},
    &\mathrm{arg}(y)\in[\frac{3\pi}{4},\frac{5\pi}{4}],\\
    \begin{bmatrix}
      \ee^{\frac{\pi\kappa_\xi}{4}}D_{-a}(y\ee^{\frac{\pi}{4}\ii})&\beta_{12}\ee^{-\frac{3\pi\kappa_\xi}{4}+\frac14\pi \ii}D_{a-1}(y\ee^{\frac{3\pi}{4}\ii})\\
      \beta_{21} \ee^{\frac{\pi}{4}\kappa_\xi+\frac34\pi \ii}D_{-a-1}(y\ee^{\frac{\pi}{4}\ii})&\ee^{\frac{-3\pi\kappa_\xi}{4}}D_a(y\ee^{\frac{3\pi}{4}\ii})
    \end{bmatrix},
    &\mathrm{arg}(y)\in[-\frac{3\pi}{4},-\frac{\pi}{4}].\\
  \end{cases}
\end{equation}
Along the ray $\arg(y)=-\frac\pi4$, we have 
$\psi_{12}^+=|\mathbf{R}(\xi)|\pmb{\Psi}_{11}^-+\pmb{\Psi}_{12}^-$ and hence
\begin{equation}\label{coefficient1}
  |\mathbf{R}(\xi)|\ee^{\frac{\pi}{4}\kappa}D_{-a}(y\ee^{\frac{\pi}{4}\ii})=
  -\beta_{12}\ee^{\frac{\pi}{4}\kappa-\frac34\pi \ii}D_{a-1}(y\ee^{-\frac{\pi}{4}\ii})
  +\beta_{12}\ee^{-\frac{3\pi}{4}\kappa+\frac14\pi \ii}D_{a-1}(y\ee^{\frac{3\pi}{4}\ii}).
\end{equation}
It follows from equation \eqref{parabolic-cylinder-function} that 
\begin{equation}\label{coefficient2}
  \begin{aligned}
  |\mathbf{R}(\xi)|\ee^{\frac{\pi}{4}\kappa_\xi}D_{-a}(y\ee^{\frac{\pi}{4}\ii})
  =&|\mathbf{R}(\xi)|\ee^{\frac{\pi}{4}\kappa_\xi}
  \frac{1}{\sqrt{2\pi}}\Gamma(-a+1)\ee^{-\frac\pi2\ii a}D_{a-1}(y\ee^{\frac{3\pi}{4}\ii})\\
  &+|\mathbf{R}(\xi)|\ee^{\frac{\pi}{4}\kappa_\xi}
  \frac{1}{\sqrt{2\pi}}\Gamma(-a+1)\ee^{\frac\pi2\ii a}D_{a-1}(y\ee^{-\frac{\pi}{4}\ii}).
  \end{aligned}
\end{equation}
Comparing the coefficient in equation \eqref{coefficient1} and equation \eqref{coefficient2}, we have
\begin{equation}\label{def-beta}
  \beta_{12}=
	\frac{|\mathbf{R}(\xi)|}{\sqrt{2\pi}}\ee^{\frac{\pi\kappa_{\xi}}{2}+
	\frac{5\pi \ii}{4}}\kappa_{\xi}\Gamma(\ii\kappa_{\xi}).
\end{equation}
