    Let $\rho>0$, $y\in \partial\Omega_u\cap B_\rho^+$
    and $y_0$ be the projection of $y$ on the set of branching points, namely $r:=|y-y_0|\le |y-z_0|$ for every $z_0$ branching point. In particular, $r \leq \abs{y} \leq \rho$ and in the following, we assume that $\rho$ is small enough (for a geometrical representation see \cref{fig:eps_reg_bordo}).
    Since $u$ satisfies the hypothesis of \cref{lemma:proprieta_blowup_boundary}, then for every $x\in B_{2r}(y_0)\cap\overline\Omega_u$ we have
    $$u(x)\ge \omega_{y_0}x_d -Cr^{1+\alpha}.$$
    In particular, by \eqref{eq:diff-v-v0} and \eqref{stima-basso-nuova}, we have 
    $$\omega_{y_0}\ge \frac{2\delta}{\tens{A}(y_0)e_d\cdot e_d}\ge \delta.$$
    By taking $ C_\delta:=\frac{C}{\delta}$, then for every $x\in B_{2r}(y_0)\cap \overline\Omega_u\cap\left\{x_d>C_\delta r^{1+\alpha}\right\}$, we have $u(x)>0$. Thus $y_d\le C_\delta r^{1+\alpha}$. We divide the rest of the proof into some steps.\\
    \\
    {\it Step 1. In $B_r'(y)$ there are only vanishing points.}
According to the notation introduced in \cref{rem:caratterizzazione_punti} and since $y_0$ is the projection of $y$ on the set of branching points, $B_r'(y)$ contains only interior contact points or vanishing points. 
Since, both the set of interior contact points and the set of vanishing points are open sets in the topology of $\{x_d=0\}$, it follows that $B_r'(y)$ contains either only interior contact points or only vanishing points.
To conclude, we need to show that the first possibility does not occur.
By \cref{lemma:rimango_in_parte_positiva} and $u(y)=0$, we know that there exists a curve $\gamma$, with $\gamma'(t)= \tens{A}(\gamma(t))V(\gamma(t))$ and $\gamma(0)=y$ such that $u(\gamma(t))=0$ for every $t<0$ with $\gamma_d(t):=\gamma(t)\cdot e_d\ge0$. Then, by \eqref{stima-basso-nuova}, $\gamma'_d(t)= \tens{A}(\gamma(t))V(\gamma(t))\cdot e_d>0$, implying that $t\mapsto\gamma_d(t)$ is non decreasing in $t$.
Thus, there exists $\overline t<0$ such that $\gamma_d(\overline t)=0$ and we call $z:=\gamma(\overline t)$.
Hence, using \eqref{eq:diff-v-v0}, we end up with
\bea C_{\delta}r^{1+\alpha}&\ge y_d=\gamma_d(0)-\gamma_d(\overline t)=\int_{\overline t}^0\left(\tens{A}(\gamma(s)) V(\gamma(s))\cdot e_d-V_d(0)\right)\,ds-V_d(0)\overline t\\&\ge \Pi_0 \overline t-V_d(0)\overline t\ge -\frac{V_d(0)}{2}\overline t=\frac{V_d(0)}{2}|\overline t|,\eea
since $\Pi_0>0$ chosen in \eqref{eq:diff-v-v0} is small enough. Then, by \eqref{eq:diff-v-v0} and \eqref{stima-basso-nuova}, there is a constant $C>0$ such that 
$$|z-y|=|\gamma(\overline t)-\gamma(0)|\le C|\overline t|\le Cr^{1+\alpha}.$$ Hence $z\in B_r'(y)$.
Moreover, since $u(\gamma(t))=0$ for every $t\in[\overline t,0]$, then, by \cref{prop:punti_regolari_al_bordo}, $z$ cannot be an interior contact point, yielding that $z$ is a vanishing point.
\\ 
\\
{\it Step 2. Near branching points, all points are regular.} Since $B_r'(y)$ contains only vanishing points, by defining
$$\widetilde u(x):=\left\{
\begin{aligned}
&u(x)&&\text{in }B_r(y)^+,\\
    &0 &&\text{in }B_r(y)\cap\{x_d\le0\},
\end{aligned}
\right.$$
we have that $\widetilde u$ is a viscosity solution of \eqref{e:u_viscosity_sol_riscalato} replacing $B_1$ with $B_r(y)$.
Since $u$ satisfies the hypothesis of \cref{lemma:proprieta_blowup_boundary}, then
$$\|u-\omega_{y_0}x_d\|_{L^\infty\left(B_{2r}(y_0)\cap\overline\Omega_u\right)}\le Cr^{1+\alpha},$$ 
implying that
$$\|u-\omega_{y_0}x_d\|_{L^\infty\left(B_{r}(y)\cap\overline\Omega_u\right)}\le Cr^{1+\alpha}.$$ 
Thus, by rescaling, we have that
\be\label{eq:stimafinale1_boundary_reg}
\|u_{y,r}-\omega_{y_0}x_d\|_{L^\infty\left(B_1\cap\overline\Omega_u\right)}\le Cr^{\alpha}.\ee 
This means that $u_{y,r}$, and thus $\widetilde u_{y,r}$, is $Cr^{\alpha}$-flat along the direction $e_d$ in $B_1$. 
By \cref{remark:interior}, there exist $\widetilde\omega_{y,\nu_y}\in\R$ and $\nu_y\in \pa B_1$ such that 
\be\label{e:stima_finale2_boundary_reg}
\|u_{y,r}-x\cdot \widetilde\omega_{y,\nu_{y}}\nu_{y}\|_{L^\infty\left(B_1\cap\overline\Omega_u\right)}\le Cr^{\alpha},
\ee 
implying that $y$ is a regular point.
\\
\\
\textit{Step 3. $\partial\Omega_u$ is a $C^{1,\alpha}$ graph.}
Combining \eqref{eq:stimafinale1_boundary_reg} and \eqref{e:stima_finale2_boundary_reg}, and arguing as in \cite[Lemma 8.8]{velichkov2023regularity},
we obtain
$$|\widetilde\omega_{y,\nu_{y}}\nu_y-\omega_{y_0}e_d|\le Cr^\alpha.$$
Finally, using the fact that $\tens{A}$ is smooth and the definition of $\omega_{x}$ as in \eqref{e:bound_omega_x}, we have
$$|\widetilde\omega_{y,\nu_{y}}\nu_y-\omega_0e_d|\le|\widetilde\omega_{y,\nu_{y}}\nu_y-\omega_{y_0}e_d|+|\omega_{y_0}-\omega_0|\le Cr^{\alpha}+|y_0|^\alpha\le 2Cr^{\alpha}+|y|^\alpha\le (2C+1)|y|^\alpha,$$
which implies the $C^{1,\alpha}$ regularity of the graph of the free boundary $\partial\Omega_u$ around $0$ and concluding the proof.
\end{proof}
\begin{proof}[Proof of \cref{th:eps_reg_bordo}]
The $C^{1, \alpha}$ regularity of the free boundary $\partial \Omega_u$ is a consequence of the change of variable provided in \cref{sec:change_coordinates} and then by \cref{prop:grafico}. 
\end{proof}



  \section{\texorpdfstring{$C^{1,\alpha}$}{C1alpha} regularity for the oblique thin obstacle problem}
  \label{susec:reg_linarized_proble_bordo}

   In this section we establish the $C^{1,\alpha}$ regularity for viscosity solutions of the oblique thin obstacle problem. Precisely, we show the following theorem.

\begin{theorem}
    \label{lemma:regolaita_prob_lin-thin}
    For all $\delta >0$, there are constants $C>0$ and $\alpha_0 \in (0,1)$ such that the following holds. Suppose that for some unit vector $W\in\partial B_1$, we have $W_d:=W\cdot e_d\ge\delta$.
  Let $v:\overline {B_1^+}\to\R$ be a viscosity solution of the oblique thin obstacle problem
    \begin{equation}\label{linearizzato-bordo}
        \left\{
\begin{aligned}
    & \Delta v = 0 && \hbox{ in } B_{1}^+,\\
    & \nabla v\cdot W=0 && \hbox{ on } B_{1}'\cap\Omega_v,\\
    & \nabla v\cdot W\le 0 && \hbox{ on } B_{1}',\\
    &v\ge0 && \hbox{ on } B_{1}'.\\
\end{aligned}
        \right.
    \end{equation} 
     Then, $v\in C^{1,\alpha_0}(\overline{B_{\sfrac{1}{2}}^+})$, and the following estimate holds true 
     \bea\label{thesis:oblthin}\|v\|_{C^{1,\alpha_0}(\overline{B_{\sfrac{1}{2}}^+})}\le C\|v\|_{L^\infty(B_1^+)}.\eea
\end{theorem}
We remark that \cref{thm:oblthin2} is an immediate consequence of \cref{lemma:regolaita_prob_lin-thin}.
The strategy to prove \cref{lemma:regolaita_prob_lin-thin} is similar to the original proof of Caffarelli in \cite{caf79}, where the Author proved the $C^{1,\alpha}$ regularity for the classical thin obstacle problem, namely $W = e_d$. The proof of \cref{lemma:regolaita_prob_lin-thin} is divided into four steps split into four subsections:
\begin{itemize}
    \item in \cref{subsec:preliminare}, we recall some definitions of viscosity solutions of \eqref{linearizzato-bordo} and we prove a maximum principle;
    \item in \cref{lipandsemiconvest}, we show that the function $v$ is Lipschitz and semiconvex in the tangential directions;
    \item in \cref{estimatefinal0}, we define the function $\sigma_W$, which is the derivative along the oblique direction $W$ on the hyperplane $\{x_d =0\}$;
    \item in \cref{estimatefinal}, we deduce the $C^{0,\alpha}$ estimates for the function $\sigma_{W}$, which implies the $C^{1,\alpha}$ regularity for $v$ up to the boundary $\{x_d=0\}$.
\end{itemize}

\subsection{Preliminary results}
\label{subsec:preliminare}

First we recall the definition of viscosity solutions for the oblique thin obstacle problem.
   \begin{definition}[Viscosity solutions of \eqref{linearizzato-bordo}]
\label{def:def-sol_sezione_esistenza-oblique-thin}
Let $v:\overline {B_1^+}\to\R$ be a continuous function. We say that {\em $v$ is a viscosity solution} of the oblique thin obstacle problem \eqref{linearizzato-bordo} if $v\ge0$ on $B_1'$ and for every $x_0 \in B_1^+\cup B_1'$ and $\varphi \in C^{\infty}(\overline{B_1^+})$, we have
\begin{itemize}
    \item if $x_0 \in B_1^+$ and $\varphi$ touches $v$ from below at $x_0$, then $\Delta \varphi(x_0) \leq 0$;
    \item if $x_0\in B_1^+$ and $\varphi$ touches $v$ from above at $x_0$, then $\Delta \varphi(x_0) \geq 0$;
    \item if $x_0\in B_1'$ and $\varphi$ touches $v$ from below at $x_0$, then $\nabla \varphi(x_0)\cdot W\le0 $;
    \item if $x_0\in B_1'\cap\Omega_v$ and $\varphi$ touches $v$ from above at $x_0$, then $\nabla \varphi(x_0)\cdot W\ge0 $.
\end{itemize}
Without loss of generality, we suppose that a solution of \eqref{linearizzato-bordo} is defined in the entire $B_1$. 
Indeed, one can extend it in an even way in the $e_d$ direction by setting $$v(x',x_d)=v(x',-x_d).$$
According to the classical notations for the thin obstacle problem, we define the contact set of $v$ as
$$\Lambda(v):=\{v=0\}\cap B_{1}'.$$
\end{definition}

\noindent We show the following maximum principle.

\begin{lemma}[Maximum principle]\label{lemma:maximum-principle-thin}
    Let $W\in\partial B_1$ be a unit vector such that $W_d >0$.
    Let $A\subset B_1'$ be an open set and let $v_1,v_2:\overline {B_1^+}\to \R$ be viscosity solutions of  \begin{equation*}
        \left\{
\begin{aligned}
    & \Delta v_1 = 0 && \hbox{ in } B_{1}^+,\\
    & \nabla v_1\cdot W\ge0 && \hbox{ on } A,\\
\end{aligned}
        \right.\qquad \text{and}\qquad\left\{
\begin{aligned}
    & \Delta v_2 = 0 && \hbox{ in } B_{1}^+,\\
    & \nabla v_2\cdot W\le0 && \hbox{ on } A.\\
\end{aligned}
        \right.
    \end{equation*} 
    Suppose that $v_1\le v_2$ on $\partial (B_1^+ \cup A)$, 
    then $v_1\le v_2$ in $\overline{B_1^+}$. In particular, the maximum of $v_1$ in $B_1^+\cup A$ is attained on the boundary $\partial( B_1^+\cup A)$.
\end{lemma}
\begin{proof}
    Let $\chi_i\in C^\infty(B_1^+\cup A)$, with $i=1,2$, the functions defined as \begin{equation*}
        \left\{
\begin{aligned}
    & \Delta \chi_i = 0 && \hbox{ in } B_{1}^+,\\
    & \nabla \chi_i\cdot W=0 && \hbox{ on } A,\\
    & \chi_i=v_i && \hbox{ on } \partial (B_1^+ \cup A),\\
\end{aligned}
        \right.
    \end{equation*} We prove that $v_1\le \chi_1\le\chi_2\le v_2$ in $\overline {B_1^+}$. Since proofs are similar, we only show that $v_1\le \chi_1$. 
    For every $\eps >0$, let us define
    $$\chi^\eps_1:=\chi_1-\eps x_d-\eps x_d^2+2\eps,$$
    then $v_1\le \chi^\eps_1$ on $\partial (B_1^+ \cup A)$ since $\chi_1=v_1$ on $\partial (B_1^+ \cup A)$.
    Let us consider the function $\chi^\eps_1+t$ for $t>0$ large, and let us decrease $t\ge0$ until a contact point $x_0$ occurs in $\overline {B_1^+}$. 
    Since $\Delta \chi^\eps_1=-2\eps<0$ and $\nabla \chi^\eps_1\cdot W=-\eps W_d<0$, then $x_0\not \in B_1^+\cup A$. Thus, we can choose $t=0$ getting that $v_1\le\chi^\eps_1$. 
    By sending $\eps\to0^+$, we get the thesis.

    Finally, we observe that to show that the maximum of $v_1$ in $B_1^+\cup A$ is attained on the boundary $\partial( B_1^+\cup A)$, it is enough to choose $v_2:=\max_{\partial( B_1^+\cup A)} v_1$.
\end{proof}

\subsection{Lipschitz and semiconvex estimates}\label{lipandsemiconvest}

The next step to prove \cref{lemma:regolaita_prob_lin-thin} is to show that a solution of the oblique thin obstacle problem is locally Lipschitz and semiconvex in the tangential directions. We split these two results into the following two lemmas.


\begin{lemma}
    [Lipschitz continuity]\label{lemma:semiconv0}
    Let $v:{B_1}\to\R$ be a viscosity solution of \eqref{linearizzato-bordo}. Then, there is a constant $ C= C(\delta)>0$ such that
    $v$ is locally Lipschitz, namely
    $$\|\nabla v\|_{L^\infty(B_{\sfrac{1}{2}})}\le  C\|v\|_{L^\infty(B_1)}.$$
\end{lemma}

\begin{lemma}
    [Tangential semiconvexity]\label{lemma:semiconv1}
    Let $v:{B_1}\to\R$ be a viscosity solution of \eqref{linearizzato-bordo}. Then, there is a constant $ C=C(\delta)>0$ such that
    \begin{itemize}
        \item[i)] $v$ is semiconvex in the tangential directions, precisely, for every $e=(e',0)\in \mathbb{S}^{d-1}$, we have
        $$\inf_{B_{\sfrac{1}{2}}}\partial_{ee}v \ge - C\|v\|_{L^\infty(B_1)};$$
        \item[ii)] $v$ is semiconcave in the normal direction
        $$\sup_{B_{\sfrac{1}{2}}^+}\partial_{dd}v \le  C\|v\|_{L^\infty(B_1)}$$ and, if we denote by $\widetilde W:=(-W',W_d)$ the adjoint direction of $W$, then $$\sup_{B_{\sfrac{1}{2}}^+}\partial_{\widetilde WW}v\le C\|v\|_{L^\infty(B_1)}.$$ 
    \end{itemize}
\end{lemma}

    \begin{proof}[Proof of \cref{lemma:semiconv0}]     
    Without loss of generality, we suppose that $\|v\|_{L^\infty(B_1)}\le 1$.  
    Consider the function $h:B_1\to\R$ defined as
\begin{equation*}
        \left\{
\begin{aligned}
    & \Delta h = 0 && \hbox{ in } B_{{1}}^+\cup B_1^-,\\
    & h=0 && \hbox{ on } B_{{1}}',\\
    & h=-\|v\|_{L^\infty(B_1)} && \hbox{ on } \partial B_1.
\end{aligned}
        \right.
    \end{equation*}
Then, by boundary estimates for harmonic functions, $h$ is Lipschitz continuous in $B_{\sfrac{3}{4}}$. Thus, for every $x_0\in B_{\sfrac{1}{2}}'$ and $r\in(0,\sfrac{1}{4})$, we have
$$\sup_{B_r(x_0)}|h(x)|\le Cr,$$
for some $C>0$. 

Let $x_0\in B_{\sfrac{1}{2}}'\cap \Lambda(v)$ and $r\in (0,\sfrac{1}{4})$. By the maximum principle for harmonic functions, $v\ge h$ on $B_{\sfrac{3}{4}}$, then $$v\ge h\ge -Cr\quad\text{in }B_r(x_0).$$ Take the function $q:=v+Cr\ge 0$ in $B_r(x_0)$ and we define $\overline q$ such that 
\begin{equation}\label{e:qbar}
        \left\{
\begin{aligned}
    & \Delta \overline q = 0 && \hbox{ in } B_{{r}}^+(x_0)\cup B_{{r}}^-(x_0),\\
    & \nabla \overline q\cdot W = 0 && \hbox{ in } B_{{r}}'(x_0),\\
    & \overline q=q && \hbox{ on } \partial B_{{r}}(x_0).\\
\end{aligned}
        \right.
    \end{equation}
        Then, by maximum principle \cref{lemma:maximum-principle-thin}, we have that $0\le \overline q\le q$ in $B_r(x_0)$ since $q$ is a supersolution of \eqref{e:qbar}.
        It follows that $q\le \overline q+Cr$ on $\partial B_r(x_0)$ and $q\le \overline q+Cr$ on $B_r'(x_0)\cap\Lambda(v)$. 
        Since $\Delta q=0$ in $B_r^+(x_0)$ and $\nabla q\cdot W=0$ on $B_r'(x_0)\cap\Omega_v$, then by maximum principle \cref{lemma:maximum-principle-thin}, we have that 
        $$q\le \overline q+Cr\quad\text{in }B_r(x_0).$$
        Since $\overline q$ is Lipschitz continuous in $B_{\sfrac{r}{2}}(x_0)$ and $q(x_0)=Cr$, for every $x\in B_{\sfrac{r}{2}}(x_0)$, we obtain 
        $$\overline q(x)\le |\overline q(x)-\overline q(x_0)|+\overline q(x_0)\le L\|q\|_{L^\infty(B_r(x_0))}r+q(x_0)\le L\|v\|_{L^\infty(B_1)}r+LCr+Cr \leq \left(L+ LC + C\right)r.$$ 
        Therefore, 
        for every $x\in B_{\sfrac{r}{2}}(x_0)$ we have that
        $$v(x)\le q(x)\le \overline q(x)+Cr\le C_0 r.$$
        Thus, we have proved that for every $x_0\in B_{\sfrac{1}{2}}'\cap \Lambda(v)$ and $r\in (0,\sfrac{1}{8})$, we obtain
        $$\sup_{B_{r}(x_0)}|v|\le 2C_0 r.$$ 
        The conclusion follows using a similar argument as the one in \cref{lemma:classical-result-pde} where we need to combine the above estimate on the contact set $\Lambda(v)$ with the boundary estimates for harmonic functions with oblique boundary conditions \cite{lieberman2013oblique}.
        \end{proof}

        \begin{proof}[Proof of \cref{lemma:semiconv1}] 
        First of all, we observe that $ii)$ is an immediate consequence of $i)$.
        Indeed, if $i)$ holds, then since $\Delta v=0$ in $B_1^+$, for every $x\in B_{\sfrac{1}{2}}^+$, we have that
        $$\partial_{dd}v=-\sum_{i=1}^{d-1}\partial_{ii}v\le C\|v\|_{L^\infty(B_1)}$$ 
        and, if we denote by $\widehat W':=(\sfrac{W'}{|W'|},0)$, then 
        $$ \partial_{\widetilde WW}v=-|W'|^2\partial_{\widehat W'\widehat W'}v+W_d^2\partial_{dd}v\le C \|v\|_{L^\infty(B_1)}.$$

    Thus, it is sufficient to prove $i)$.
    For every $\ell\in(0,1)$, we consider the solution of the oblique thin obstacle problem in $B_{\sfrac{7}{8}}$ with boundary datum $v+\ell$, namely \begin{equation}\label{vell}
     \left\{
\begin{aligned}
    &\Delta v_\ell= 0  &&  \mbox{in }B_{\sfrac{7}{8}}^+,\\
     &\nabla v_\ell \cdot W =0 && \mbox{on } B_{\sfrac{7}{8}}'\cap\Omega_{ v_\ell},\\
        &\nabla v_\ell \cdot W \le0 && \mbox{on } B_{\sfrac{7}{8}}',\\
		 &v_\ell \ge 0 &&  \mbox{on } B_{\sfrac{7}{8}}',\\
		 &v_\ell= v+\ell &&\mbox{on } \partial B_{\sfrac{7}{8}},\\
         &v_\ell(x',x_d)=v_\ell(x',-x_d)&&  \mbox{in }B_{\sfrac{7}{8}}^+
\end{aligned}
    \right.
\end{equation}
Notice that $v_{\ell}\to v$ uniformly in $B_{\sfrac{7}{8}}$ as $\ell\to 0^+$ (as a consequence of Lipschitz regularity in \cref{lemma:semiconv0}). 
We point out that a solution of \eqref{vell} can be constructed by the classical Perron's method, similarly as done in \cref{t:existence}, as the minimum supersolution of
\begin{equation*}
     \left\{
\begin{aligned}
    &\Delta v_\ell\le 0  &&  \mbox{in }B_{\sfrac{7}{8}}^+,\\
     &\nabla v_\ell \cdot W \le0 && \mbox{on } B_{\sfrac{7}{8}}',\\
\end{aligned}
    \right.
\end{equation*}
satisfying $v_\ell\ge0$ on $B_{\sfrac{7}{8}}'$ and $v_\ell\ge v+\ell$ on $\partial B_{\sfrac{7}{8}}$.
Since $v_\ell >0$ in $B_{\sfrac{7}{8}}$, we observe that for some $\beta=\beta(\ell)>0$, the function $v_{\ell}$ is harmonic in $(B_{\sfrac{7}{8}}\setminus B_{\sfrac{7}{8}-2\beta})^+$, with an oblique boundary condition in $(B_{\sfrac{7}{8}}\setminus B_{\sfrac{7}{8}-2\beta})'$. 
We divide the rest of the proof into two steps.\\
\\
{\it Step 1.} We claim that, for every $\ell>0$,
\begin{equation}\label{claim:semiconvexity}
     \left\{
\begin{aligned}
    &\Delta(\partial_{ee}v_{\ell})^{-}\ge 0&& \text{in } B_{\sfrac{2}{3}}^+,\\ &\nabla(\partial_{ee}v_{\ell})^{-}\cdot W\ge  0&& \text{on } B_{\sfrac{2}{3}}'\setminus\Lambda(v_\ell),
    \end{aligned}
    \right.\qquad\text{and}\qquad  (\partial_{ee}v_{\ell})^{-}\equiv0\quad\text{on }\Lambda(v_\ell)\cap B_{\sfrac{2}{3}}.
\end{equation}
To define $(\partial_{ee}v_{\ell})^{-}$, first, for every $\eps>0$, we set $f^\ell_{\eps,e,h}:=\max\{-\delta^2_{e,h} v_\ell,\eps\}$, where
$$\delta^2_{e,h} w(x)=\frac{ w(x+he)+ w(x-he)-2 w(x)}{h^2},\quad\mbox{for every } x\in B_{\sfrac{7}{8}},$$
and for any $w:B_1\to\R$, $e=(e',0)\in \mathbb{S}^{d-1}$, $h\in(0,\sfrac{1}{8})$. To define $(\partial_{ee}v_{\ell})^{-}$ and get \eqref{claim:semiconvexity}, we want to send $\eps \to 0^+$ and then $h \to 0^+$ in $f^\ell_{\eps,e,h}$.
We notice that, since $v_\ell= 0$ on $\Lambda(v_\ell)$ and $v_\ell\ge0$ on $B_{\sfrac{7}{8}}'$, then
\be\label{up}\delta^2_{e,h} v_\ell\ge 0\quad\text{on }\Lambda(v_\ell).
\ee
Moreover, we have that $\Delta(\delta^2_{e,h}v_\ell)=0$ in $B_{\sfrac{7}{8}}^+$. 
Since the maximum of harmonic functions is subharmonic (similarly as in \cref{lemma:min2soprasol}), then
\be\label{eq:syst1}\Delta f^\ell_{\eps,e,h}\ge 0\quad\text{on }B_{\sfrac{7}{8}}^+.\ee
Regarding the boundary condition, since $\nabla v_\ell\cdot W=0$ on $B_{\sfrac{7}{8}}'\setminus\Lambda(v_\ell)$ and $\nabla v_\ell\cdot W\le0$ on $B_{\sfrac{7}{8}}'$, then $\nabla (\delta^2_{e,h} v_\ell)\cdot W\le0$ in $B_{\sfrac{7}{8}}'\setminus\Lambda(v_\ell)$.
By \eqref{up}, we have that
\be\label{neigh}f^\ell_{\eps,e,h}\equiv \eps\quad\text{in a neighborhood of }\Lambda(v_\ell),\ee then, arguing as above we get \be\label{eq:syst2}\nabla f^\ell_{\eps,e,h}\cdot W\ge0\quad\text{on }B_{\sfrac{7}{8}}'.\ee
To conclude the first step, namely proving \eqref{claim:semiconvexity}, we would like to pass to the limit as $\eps\to0^+$ and then $h\to0^+$ in \eqref{eq:syst1}, \eqref{neigh}, \eqref{eq:syst2}.
To pass to the limit in \eqref{eq:syst1}, it is sufficient to show that
\be\label{claim:seminconvexity2}
\|f_{\eps,e,h}^\ell\|_{L^\infty(B_{\sfrac{3}{4}})}\le C(\ell),
\ee for some $C(\ell)>0$ which does not depend on $\eps$ and $h$. 
Indeed, if \eqref{claim:seminconvexity2} holds, then we have a family of uniformly bounded subharmonic functions $\{f^\ell_{\eps,e,h}\}_{\eps,h}$ in $B_{\sfrac{2}{3}}^+$, which pointwise converges to $(\partial_{ee}v_\ell)^-$. Then $(\partial_{ee}v_\ell)^-$ is subharmonic in $B_{\sfrac{2}{3}}^+$. By passing to the limit in the mean value inequality for subharmonic functions, we get the first equation in \eqref{claim:semiconvexity}.
Moreover, we can pass to the limit also in \eqref{neigh}, getting that $(\partial_{ee}v_\ell)^-\equiv 0$ on $\Lambda(v_\ell)\cap B_{\sfrac{2}{3}}'$.
Finally, since the function $v_\ell$ is smooth up to $B_{\sfrac{2}{3}}'\cap\Omega_{v_\ell}$, by estimates up to the boundary for harmonic functions with oblique boundary conditions, see \cite{lieberman2013oblique}, then we get $\nabla (\partial_{ee}v_\ell)\cdot W=0$ on $B_{\sfrac{2}{3}}'\cap\Omega_{v_\ell}$. Then, the final inequality $\nabla (\partial_{ee}v_\ell)^-\cdot W\ge0$ on $B_{\sfrac{2}{3}}'\cap\Omega_{v_\ell}$ follows by the fact that maximum of supersolutions is a supersolution, concluding \eqref{claim:semiconvexity}.  

It remains to provide \eqref{claim:seminconvexity2}. We observe that since $f^\ell_{\eps,e,h}$ satisfies \eqref{eq:syst1}, \eqref{eq:syst2}, then by maximum principle \cref{lemma:maximum-principle-thin}, the maximum of $f^\ell_{\eps,e,h}$ in a ball $B_r$ with $r\le \sfrac{7}{8}$, is attained on the boundary of such a ball $\partial B_r$.
Since $v_\ell$ is harmonic in $(B_{\sfrac{7}{8}}\setminus B_{\sfrac{7}{8}-2\beta})^+$ with an oblique boundary condition in $(B_{\sfrac{7}{8}}\setminus B_{\sfrac{7}{8}-2\beta})'$, using the corresponding $C^{2,\alpha}$ estimates in \cite{lieberman2013oblique}, we have 
$$\sup_{B_{\sfrac{3}{4}}}|f^\ell_{\eps,e,h}|=\sup_{B_{\sfrac{3}{4}}}f^\ell_{\eps,e,h}\le \sup_{B_{\sfrac{7}{8}-\beta}}f^\ell_{\eps,e,h}\le\sup_{\partial B_{\sfrac{7}{8}-\beta}}f^\ell_{\eps,e,h} \le \sup_{\partial B_{\sfrac{7}{8}-\beta}}|\delta^2_{e,h}v_\ell|+\eps\le C(\ell),$$
getting \eqref{claim:seminconvexity2}.\\
\\
{\it Step 2.}
We now proceed by Bernstein's technique. Let $\eta'\in C^\infty_c(B_{\sfrac{6}{11}}')$ be a cutoff function such that $0\le \eta'\le 1$ and $\eta'\equiv1$ in $B_{\sfrac{7}{11}}'$. Let 
$$\eta(x):=\eta'\left(x'+\frac{W'}{W_d}x_d\right)$$
be defined in the strip $|x_d|\le \sigma$ for some $\sigma >0$ small enough.
We can extend $\eta$ in $\R^d$ in the following way
$$
\eta\in C^\infty_c(B_{\sfrac{2}{3}}), \qquad 0\le \eta\le 1, \qquad \eta\equiv1 \hbox{ in } B_{\sfrac{1}{2}}, \qquad \nabla \eta\cdot W=0 \hbox{ on } \{x_d=0\}.
$$ 
Introducing the auxiliary function 
$$\psi_\ell:=\eta^2((\partial_{ee}v_\ell)^-)^2+\mu(\partial_ev_\ell)^2,$$
and providing that $\mu>0$ large enough (independently on $\ell$), using \eqref{claim:semiconvexity}, we prove that $\Delta\psi_{\ell}\ge 0$ in $B_{\sfrac{2}{3}}^+$. Indeed, 
\bea \Delta \psi_\ell&=((\partial_{ee}v_\ell)^-)^2\Delta \eta^2 +\eta^2\Delta ((\partial_{ee}v_\ell)^-)^2+2\nabla \eta^2\cdot\nabla ((\partial_{ee}v_\ell)^-)^2+2\mu |\nabla \partial_ev_\ell|^2\\
&\ge ((\partial_{ee}v_\ell)^-)^2\Delta \eta^2+2\eta^2 (\partial_{ee}v_\ell)^-\Delta (\partial_{ee}v_\ell)^-+2|\nabla (\partial_{ee}v_\ell)^-|^2\eta^2-8|\eta||\nabla\eta||(\partial_{ee}v_\ell)^-||\nabla (\partial_{ee}v_\ell)^-|+2\mu |\nabla \partial_ev_\ell|^2\\
&\ge ((\partial_{ee}v_\ell)^-)^2\Delta \eta^2+2|\nabla (\partial_{ee}v_\ell)^-|^2\eta^2-8|\eta||\nabla\eta||(\partial_{ee}v_\ell)^-||\nabla (\partial_{ee}v_\ell)^-|+2\mu |\nabla \partial_ev_\ell|^2\\
&\ge ((\partial_{ee}v_\ell)^-)^2\Delta \eta^2 -8|\nabla \eta|^2|(\partial_{ee} v_\ell)^-|^2+2\mu |\nabla \partial_ev_\ell|^2\\&\ge ((\partial_{ee}v_\ell)^-)^2(2\mu-C_\eta)\\
&\ge0,
\eea 
having chosen $C_{\eta}>0$ such that $-\Delta\eta^2+8|\nabla \eta|^2\le C_{\eta}.$
Moreover, by \eqref{claim:semiconvexity} and the regularity of $v_\ell$ in $\Omega_{v_\ell}$, we have that $\nabla \eta\cdot W=0$, $\nabla (\partial_ev_\ell)\cdot W=0$ and $\nabla (\partial_{ee}v_\ell)^-\cdot W\ge0$ on $B_{\sfrac{2}{3}}'\cap\Omega_{v_\ell}$, then $$\nabla\psi_{\ell}\cdot W\ge 0 \quad\text{in }B_{\sfrac{2}{3}}'\cap \Omega_{v_\ell}.$$
By maximum principle \cref{lemma:maximum-principle-thin}, the maximum in $B_{\sfrac{2}{3}}\setminus\Lambda(v_{\ell})$ of $\psi_\ell$ is attained on the boundary. 
Since $\eta\equiv 1$ in $B_{\sfrac{1}{2}}$, $\eta\equiv0$ on $\partial B_{\sfrac{2}{3}}$ and by \eqref{claim:semiconvexity} $(\partial_{ee}v_\ell)^-\equiv0$ on $\Lambda(v_{\ell})\cap B_{\sfrac{2}{3}}$, we obtain
\bea \|\psi_\ell\|_{L^\infty(B_{\sfrac{2}{3}})}\le\|\psi_\ell\|_{L^\infty(\partial B_{\sfrac{2}{3}})}+\|\psi_\ell\|_{L^\infty(\Lambda(v_{\ell})\cap B_{\sfrac{2}{3}})}\le 2\mu\lVert \partial_ev_\ell\rVert_{L^{\infty}(B_{\sfrac{2}{3}})}^2\le C\|v_\ell\|_{L^\infty(B_1)}^2\le C\|v\|_{L^\infty(B_1)}^2.
\eea 
having used the Lipschitz regularity in \cref{lemma:semiconv0}. 
Therefore,
$$\|(\partial_{ee}v_\ell)^-\|_{L^\infty(B_{\sfrac{1}{2}})}\le\|\psi_\ell\|_{L^\infty(B_{\sfrac{1}{2}})}^{\sfrac{1}{2}}\le C\|v\|_{L^\infty(B_1)},$$ 
implying that the family of function $v_\ell$ is uniformly semiconvex. Letting $\ell\to0^+$ we conclude the proof.
    \end{proof}


\subsection{The function \texorpdfstring{$\sigma_{W}$}{sigmaW}}
\label{estimatefinal0} 

In the following, we show that the oblique derivative
is well-defined on the thin space. 
For technical reason, we introduce the modified functions $v_\ell$ for $\ell \in (0,1)$, as in the proof of \cref{lemma:semiconv1}.
Precisely, for every $\ell\in(0,1)$, we consider the solution of the following problem
\begin{equation}\label{vell2}
     \left\{
\begin{aligned}
    &\Delta v_\ell= 0  &&  \mbox{in }B_{1}^+,\\
     &\nabla v_\ell \cdot W =0 && \mbox{on } B_{1}'\cap\Omega_{ v_\ell},\\
        &\nabla v_\ell \cdot W \le0 && \mbox{on } B_{1}',\\
		 &v_\ell \ge 0 &&  \mbox{on } B_{1}',\\
		 &v_\ell= v+\ell &&\mbox{on } \partial B_{1},\\
         &v_\ell(x',x_d)=v_\ell(x',-x_d)&&  \mbox{in }B_{1}^+.
\end{aligned}
    \right.
\end{equation}
We point out that such a solution can be constructed by Perron's method, as already observed in the proof of \cref{lemma:semiconv1}.
In the rest of the proof of \cref{lemma:regolaita_prob_lin-thin}, we fix $\ell \in (0,1)$ and we establish $C^{1, \alpha}$ estimates for $v_\ell$ that are uniform in $\ell$, implying that the same $C^{1, \alpha}$ estimates hold true for $v$.

\begin{remark}\label{re:fundamental-rem} 
    Let $v:{B_1}\to\R$ be a viscosity solution of \eqref{linearizzato-bordo} and $v_\ell$ be as in \eqref{vell2}.
    By \cref{lemma:semiconv1}, for every $(x',0)\in B_1'$ the following quantity 
    \be\label{sigmadef}\sigma_W(x'):=\lim_{t\to0^+}\nabla v_\ell(x'+t\widetilde W)\cdot W\ee 
    is well-defined, where 
    $\widetilde W:=(-W',W_d)$ is the adjoint direction. 
    Indeed, for every $x=(x',0)\in B_1'$, there is $\rho>0$ such that $B_{\rho}'(x)\subset B_1'$, and, by \cref{lemma:semiconv1},
    there is a constant $C=C(\rho)>0$ such that 
    $$\partial_{\widetilde WW}v_\ell(x)\le C.$$
    Therefore, $\partial_{W}v_\ell(x'+t\widetilde W)-Ct$ is monotone non increasing in $t$, and thus \eqref{sigmadef} is well-defined. Moreover, by the elliptic regularity for the oblique boundary problems \cite{lieberman2013oblique}, we have 
    \be\label{sigma=0}\sigma_{W}(x')\equiv0\quad\text{for every }(x',0)\in\Omega_{v_\ell}.\ee
    \end{remark}

    We notice that the viscosity condition $\nabla v\cdot W\le0$ on $B_1'$ suggests that $\sigma_{W}(x')\le0$ on $B_1'$. This claim is proved in the next lemma by a penalization argument.

    \begin{lemma}\label{lemma:penalized}
        Let $v:{B_1}\to\R$ be a viscosity solution of \eqref{linearizzato-bordo} and $v_{\ell}$ be as in \eqref{vell2}.
        If $\sigma_{W}$ is defined as in \eqref{sigmadef}, then $$\sigma_{W}(x')\le 0\quad\text{for every}\quad (x',0)\in B_1'.$$
    \end{lemma}
    \begin{proof}
        The proof is based on a penalization argument, similarly as in \cite{milakissilvestre-signorini}. The function $v_\ell$ can be constructed as limit of the following problem
        \begin{equation*}
     \left\{
\begin{aligned}
    &\Delta v_\ell^k=0&& \text{in } B_{1}^+,\\ 
    &\nabla v_\ell^k\cdot W=  0&& \text{on } B_{1}'\cap\{v_\ell^k>0\},\\
    &\nabla v_\ell^k\cdot W=kv_\ell^k&& \text{on } B_{1}'\cap\{v_\ell^k\le0\},\\
    &v_\ell^k=v_\ell&& \text{on }\partial B_1,\\
    &v_\ell^k(x',x_d)=v_\ell^k(x',-x_d),&&
    \end{aligned}
    \right.
\end{equation*}
as $k\to +\infty$.
The existence of a solution can be obtained by Perron’s method. By maximum principle, regularity for oblique elliptic PDE \cite{lieberman2013oblique} and the fact that $v_\ell>0$ in $\partial B_1$, we can get the following conditions for $v_\ell^k$ exactly as in \cite[Section 2]{milakissilvestre-signorini}:
\begin{itemize}
    \item[(a)] $\|v_\ell^k\|_{L^\infty(B_1)}\le \|v_\ell\|_{L^\infty(B_1)}$;
    \item[(b)] $\nabla v^k_\ell\cdot W$ is uniformly bounded in $B_{1-\eta}'$, by a constant $C=C(\ell,\eta)>0$ independently on $k$, for every $\eta>0$;
    \item[(c)] $v_\ell^k\to v_\ell$ uniformly in $B_1$; 
    \item[(d)] $\nabla v_\ell^k\to \nabla v_\ell$ uniformly in $B_{1-\eta}\cap\{x_d>\eta\}$, for every $\eta>0$;
    \item[(e)] $v_\ell^k\in C^{1,\alpha}(\overline B_{1-\eta})$ for every $\eta>0$, but (a priori) the $C^{1,\alpha}$ norm possibly depending on $k$.
\end{itemize}
Since $v_\ell>0$ in $\partial B_1$, there is $\beta=\beta(\ell)>0$ such that $v_{\ell}>0$ and $(B_{1}\setminus B_{1-\beta})'$, thus it is harmonic in $(B_{1}\setminus B_{1-\beta})^+$, with an oblique boundary condition in $(B_{1}\setminus B_{1-\beta})'$. Moreover, combining $(b)$ and the oblique elliptic regularity in \cite{lieberman2013oblique}, there exists $M=M(\beta)>0$ such that 
$\nabla v_\ell^k\cdot W\le M$ in $B_{1-\sfrac{\beta}{3}}\setminus B_{1-\sfrac{2\beta}{3}}$.
Let $\Psi$ be the solution of the following elliptic problem
$$
\left\{
\begin{aligned}
    &\Delta \Psi = 0&&\hbox{in }B_{1- \sfrac{\beta}{2}}^+,\\
    &\Psi = 0&&\hbox{on }B_{1- \beta}',\\
     &\Psi= M&&\hbox{on }\partial B_{1- \sfrac{\beta}{2}},\\
     &\Psi=  \frac{2M\left(\abs{x}-1 + \beta\right) }{\beta}&&\hbox{on } B'_{1- \sfrac{\beta}{2}}\setminus B_{1- {\beta}}'.\\
\end{aligned}
\right.
$$
By comparison $\nabla v_\ell^k\cdot W \leq \Psi$ in $B_{1- \sfrac{\beta}{2}}^+$. Letting $k\to+\infty$ and using $(d)$, we have that $\nabla v_\ell\cdot W \leq \Psi$ in $B_{1- \sfrac{\beta}{2}}^+$.
Thus, for every $(x',0)\in B'_{1- \sfrac{\beta}{2}}$, 
$$\sigma_{W}(x')=\lim_{t\to0^+}\nabla v_\ell(x'+t\widetilde W)\cdot W \leq \Psi(x',0)=0.$$
     On the other hand, by \eqref{sigma=0}, $\sigma_W\equiv0$ in $B_1'\setminus B_{1-\beta}'$, concluding the proof.
    \end{proof}

    In the following lemma we show that we can link almost everywhere on the contact set the normal derivative with the one along the oblique obstacle $W$, on the hyperplane $\{x_d=0\}$.

   \begin{lemma}\label{rem:q.o.}
      Let $v:{B_1}\to\R$ be a viscosity solution of \eqref{linearizzato-bordo} and $v_{\ell}$ be as in \eqref{vell2}. Then there exists a set $\mathcal{G}\subset B_1'$ such that, for every $(x',0)\in \Lambda(v_\ell)\cap \mathcal{G}$ 
$$\sigma_d(x'):=\lim_{t\to0^+}\partial_{d}v_\ell(x'+t\widetilde W)=\sigma_{W}(x')$$ and $$\mathcal{H}^{d-1}(B_1'\setminus\mathcal{G})=0.$$ 
   \end{lemma}
    \begin{proof}
       In the rest of the proof, without loss of generality, we suppose that $\|v\|_{L^\infty(B_1)}\le 1$.
        We observe that, by the Lipschitz regularity of $v_\ell$ proved in \cref{lemma:semiconv0}, $v_\ell(x',0)$ is differentiable almost everywhere along the direction $\widehat W':=(\sfrac{W'}{|W'|},0)$.
        Namely, there exists a set $\mathcal{G}\subset B_1'$ such that for every $x_0\in\mathcal{G}$, the tangential derivative
        $$\partial_{\widehat W'}v_\ell(x_0)=\lim_{h\to0}\frac{v_\ell(x_0+h\widehat W')-v_\ell(x_0)}{h}$$
     is well-defined, and $\mathcal{H}^{d-1}(B_1'\setminus \mathcal{G})=0$. 
     In particular, for every $x_0\in\Lambda(v_\ell)\cap \mathcal{G}$, since $v_\ell(x_0)=0$ and $v_\ell\ge0$ on $B_1'$, we have that 
     \be\label{eq:richiama}\partial_{\widehat W'}v_\ell(x_0)=0.\ee
     Moreover, since $v_\ell$ is smooth in $B_1^+$, for every $x\in B_1^+$ and $h$ small enough, by \cref{lemma:semiconv1}, we have
     $$v_\ell(x+h \widehat W')=v_\ell(x)+\partial_{\widehat W'}v_\ell(x) h+\iint_{[x_0,x_0+h\widehat W']}\partial_{\widehat W'\widehat W'}v_\ell\ge v_\ell(x)+\partial_{\widehat W'}v_\ell(x) h-Ch^2.$$
     Here we used the notation
     \be\label{notation-doubleintegral}\iint_{[a,b]}w:=\int_{0}^{|b-a|}\int_0^s w\left(a+\frac{b-a}{|b-a|}t\right)\,dt\,ds\ee 
     for the double integral over the segment between points $a$ and $b$. It follows that, for $h>0$,
     $$\partial_{\widehat W'}v_\ell(x)\le \frac{v_\ell(x+h\widehat W')-v_\ell(x)}{h}+Ch,$$
     thus for $x = x'+t\widetilde W$, we get
    $$\limsup_{t\to0^+}\partial_{\widehat W'}v_\ell(x'+t\widetilde W)\le \frac{v_\ell((x',0)+h\widehat W')-v_\ell(x',0)}{h}+Ch.$$ 
    In particular, if $(x',0)\in\Lambda(v_\ell)\cap \mathcal{G}$, by \eqref{eq:richiama},
    we obtain 
    $$\limsup_{t\to0^+}\partial_{\widehat W'}v_\ell(x'+t\widetilde W)\le 0.$$
    On the other hand, arguing similarly in the case $h<0$, we get the reverse inequality for the liminf. Then, for $(x',0)\in\Lambda(v_\ell)\cap\mathcal{G}$, we have 
    $$\lim_{t\to0^+}\partial_{\widehat W'}v_\ell(x'+t\widetilde W)= 0,$$
    which concludes the proof.
     \end{proof}

\subsection{\texorpdfstring{$C^{1,\alpha}$}{C1alpha} estimates}
\label{estimatefinal} 
In this section we conclude the proof of \cref{lemma:regolaita_prob_lin-thin}.
In the following, we use the notation 
$$\tens{P}_{W^\perp}x:=x-(x\cdot W)W,$$ 
to denote the projection of $x\in\R^d$ onto the hyperplane orthogonal to $W$ and passing through the origin.

\begin{lemma}\label{lemmab6}
    Let $v:B_1\to\R$ be a viscosity solution of \eqref{linearizzato-bordo} and $v_\ell$ be as in \eqref{vell2}. For every $x_0\in B_1'\cap\Omega_{v_\ell}$, let $h_{x_0}$ be the function defined as 
    $$h_{x_0}(x):=|\tens{P}_{W^\perp}(x-x_0)|^2-(d-1)x_d^2.$$ 
    For every neighborhood $U_{x_0}\subset B_1$ of $x_0$, there exists $y\in\partial U_{x_0}\cap\{x_d>0\}$ such that 
    $$v_\ell(y)\ge h_{x_0}(y).$$ 
\end{lemma}

\begin{proof}
    Let $x_0\in B_1'\cap\Omega_{v_\ell}$. We observe that, for all $x \in \R^d$
    $$|\tens{P}_{W^\perp}(x-x_0)|^2=(x-x_0)^2-((x-x_0)\cdot W)^2.$$ 
    By simple computations $\Delta h_{x_0}=0$ in $B_1$ and $\nabla h_{x_0}\cdot W=0$ on $B_1'$.
    Therefore $p:=v_\ell-h_{x_0}$ is harmonic in $B_1^+$ and satisfies $\nabla p\cdot W=0$ in $B_1'\setminus \Lambda(v_\ell)$.
    Then, by maximum principle \cref{lemma:maximum-principle-thin}, in $U_{x_0}\setminus\Lambda(v_\ell)$, the function $p$ must achieve its maximum on the boundary $\partial(U_{x_0}\setminus\Lambda(v_\ell))$. Since $p(x_0)=v_\ell(x_0)>0$, then 
    $$\sup_{\partial (U_{x_0}\setminus\Lambda(v_\ell))\cap\{x_d\ge0\}}(v_\ell-h_{x_0})\ge p(x_0)>0.$$ 
    On the other hand, on $\Lambda(v_\ell)$, we have $v_\ell-h_{x_0}=-h_{x_0}<0$. Then 
    $$\sup_{\partial U_{x_0}\cap\{x_d\geq0\}}(v_\ell-h_{x_0})=\sup_{\partial (U_{x_0}\setminus\Lambda(v_\ell))\cap\{x_d\ge0\}}(v_\ell-h_{x_0})>0.$$ 
    To conclude the proof, if the supremum is attained in $z \in \{x_d >0\}$, then we choose $y = z$, otherwise if $z \in \{x_d = 0\}$, then we choose $y \in \{x_d >0\}$ close to $z$.
\end{proof}

Next we show that, given a point $x_0\in\Omega_{v_\ell}\cap B_1'$ and $\gamma>0$ small, we can find a ball of radius comparable to $\gamma$ which is almost everywhere contained in $\{\sigma_W(x')>-\gamma\}$.

\begin{lemma}\label{lemmab7}
    There are constants $C_1>0$, $C_2>0$, and $\gamma_0>0$ depending on $\delta$ and $\|v\|_{L^\infty(B_1)}$ such that the following holds.
    Let $v:B_1\to\R$ be a viscosity solution of \eqref{linearizzato-bordo}, $v_\ell$ be as in \eqref{vell2} and $\mathcal{G}$ be the set defined in \cref{rem:q.o.}.
    Let $x_0\in B_{\sfrac{3}{4}}'\cap\Omega_{v_\ell}$ and 
    $$S_\gamma:=\{(x',0)\in B_1':\sigma_{W}(x')>-\gamma\},$$
    for $\gamma\in(0,\gamma_0)$. 
    Then, there is $\overline x\in B_1'$ such that 
    $$B'_{C_1\gamma}(\overline x)\cap\mathcal{G}\subset B'_{C_2\gamma}(x_0)\cap S_\gamma.$$
\end{lemma}
\begin{proof}
    In the rest of the proof, without loss of generality, we suppose that $\|v\|_{L^\infty(B_1)}\le 1$.
    Let $U_{x_0}$ be the oblique cylinder defined as follows
    $$U_{x_0}:=\{(x',x_d)\in \R^d:\ |\tens{P}_{W^\perp}(x-x_0)|\le 2\gamma ,\ |x_d|\le \eps_1\gamma\},$$ for a constant $\eps_1>0$ to be chosen later.
    By \cref{lemmab6}, there exists $y \in \partial U_{x_0} \cap \{x_d >0\}$
    such that $ v_{\ell}(y)\ge h_{x_0}(y)$.
    We split two cases.\\
    \\
    \textit{Step 1.} Suppose that $y=(y',y_d)$ belongs to the lateral face of the oblique cylinder $U_{x_0},$ i.e.~$|\tens{P}_{W^\perp}(y-x_0)|= 2\gamma$ and $0< y_d\le \eps_1\gamma$. If $\eps_1$ is small, then 
    $$v_\ell(y)\ge h_{x_0}(y)=|\tens{P}_{W^\perp}(y-x_0)|^2-(d-1)y_d^2\ge 4\gamma^2-(d-1)\eps_1^2\gamma^2\ge \gamma^2.$$
         We claim that we can find $\eps_2>0$ such that 
         \be\label{claim-z'} 
        \hbox{if }\, (z',0)\in\mathcal{D}:=\left\{ (z',0)\in B'_{\eps_2\gamma}((y',0)):\ \nabla'v_\ell(y)\cdot ( z'- y')\ge0\right\}\cap\mathcal{G}\implies (z',0)\in S_\gamma,\ee
        where $\nabla'v_{\ell}(y):=(\partial_{1}v_\ell(y),\ldots,\partial_{d-1}v_\ell(y))$.
         If \eqref{claim-z'} holds true, then we get the conclusion choosing $\overline x$ and $C_1>0$, $C_2>0$ such that $B'_{C_1\gamma}(\overline x)\cap\mathcal{G}\subset \mathcal{D}$ and $C_2$ depending on $\delta$, $\eps_1$ and $\eps_2$.
        It is left to ensure that \eqref{claim-z'} yields.
        Take $(z',0)\in\mathcal{D}$ and let $e=(e',0)\in\mathbb{S}^{d-1},$ with $e':=\frac{z'- y'}{| z'- y'|}$. Since $v_\ell$ is smooth in $B_1^+$, by \cref{lemma:semiconv1}, we have that $$v_\ell(z',y_d)=v_\ell(y',y_d)+\nabla'v_\ell(y)\cdot (z'-y')+\iint_{[(y',y_d),(z',y_d)]}\partial _{ee}v_\ell\ge \gamma^2- C|z'-y'|^2\ge (1- C\eps_2^2)\gamma^2>0$$
        having chosen $\eps_2$ small enough. Here we used the notation \eqref{notation-doubleintegral} for the double integral.  
        Suppose by contradiction that $ (z',0)\not\in S_\gamma$, then $ (z',0)\in\Lambda(v_\ell)$, since $\sigma_W\equiv0$ in $B_1'\cap \Omega_{v_\ell}$ by \eqref{sigma=0}. 
        Then, using the semiconcavity \cref{lemma:semiconv1} together with \cref{rem:q.o.}, we get
        $$
        \begin{aligned}
            v_\ell(z',y_d)&=v_\ell(z',0)+\sigma_{d}(z')y_d+\iint_{[(z',0),(z',y_d)]}\partial_{dd}v_\ell=
        \sigma_{W}(z')y_d+\iint_{[(z',0),(z',y_d)]}\partial_{dd}v_\ell\\
        &\le 
        -\gamma y_d+Cy_d^2\le y_d\gamma (C\eps_1-1)<0,
        \end{aligned}$$
        where we have chosen $\eps_1$ small enough and we get the contradiction. We point out that the above expansion of $v_\ell(z',y_d)$ is obtained for points like $x'+t\widetilde W$ and then sending $t\to0^+$.
        \\
        \\
        \textit{Step 2.} Now, we suppose that $y=(y',y_d)$ belongs on the upper base of the oblique cylinder $U_{x_0},$ i.e.~$|\tens{P}_{W^\perp}(y-x_0)|\le 2\gamma$ and $y_d=\eps_1\gamma$. 
        Then 
        $$v_\ell(y)\ge h_{x_0}(y)=|\tens{P}_{W^\perp}(y-x_0)|^2-(d-1)y_d^2\ge -\eps_1^2(d-1)\gamma^2.$$ As above, if $(z',0)\in \mathcal{D}$, similarly as in the previous step, we have 
        $$v_\ell(z',y_d)=v_\ell(y',y_d)+\nabla'v_\ell(y)\cdot (z'-y')+\iint_{[(y'y_d),(z',y_d))]}\partial_{ee}v_\ell\ge -(d-1)\eps_1^2\gamma^2-C|z'-y'|^2\ge-\gamma^2((d-1)\eps_1^2+C\eps_2^2).$$ 
        If by contradiction $(z',0)\not\in S_\gamma$, then, since $y_d=\eps_1\gamma$, we have
        $$v_\ell(z',y_d)=v_\ell(z',0)+\sigma_{d}(z')y_d+\iint_{[(z',0),(z',y_d)]}\partial_{dd}v_\ell= 
        \sigma_{W}(z')y_d+\iint_{[(z',0),(z',y_d)]}\partial_{dd}v_\ell\le 
        -\gamma y_d+Cy_d^2=\gamma^2\eps_1(C\eps_1-1).$$ 
        Combining the two estimates, we get the contradiction by choosing $\eps_2=\eps_1$ small enough.
        \end{proof}


        In the following, we will use the cylinders
            $$\mathcal{C}(x_0,r,\gamma_1,\gamma_2):=\left\{x=(x',x_d)\in \R^d:\ (x',0)\in B'_{r}(x_0),\ \gamma_1\le x_d\le \gamma_2\right\},$$
            and 
            $$\mathcal{C}(x_0,r):=\left\{x=(x',x_d)\in \R^d:\ (x',0)\in B'_{r}(x_0),\ 0< x_d\le r\right\}.$$

        To conclude the proof of \cref{lemma:regolaita_prob_lin-thin}, it will be fundamental the following technical lemma.


        \begin{lemma}\label{teclemma-w} 
        Let $q:\mathcal{C}(0,1)\to\R$ be a bounded non-negative continuous function such that $\Delta q=0$ in $\mathcal{C}(0,1)$. 
        Assume that, given $\mathcal{G}\subset B_1'$ such that $\mathcal{H}^{d-1}(B_1'\setminus\mathcal{G})=0$ and $\widetilde W\in\partial B_1$ with $\widetilde W_d\ge\delta$, we have
            \begin{equation}
                \label{e:ipotesi_tecnica}
                \lim_{t\to0^+} q(x'+t\widetilde W)\ge 1\quad\text{for every}\quad (x',0)\in B_{\rho}'(\overline x)\cap\mathcal{G},
            \end{equation}
            for some ball $B_{\rho}'(\overline x)\subset B_1'$ (we do not assume continuity up to $\overline{\mathcal{C}(0,1)}$).
            For every $c>0$, there is a constant $\eps=\eps(\delta,\rho,c)>0$ such that
            $$q\ge \eps\quad\text{in }\mathcal{C}\left(0,\frac{1}{2},c,\frac{3}{4}\right).$$
        \end{lemma}

        \begin{proof}
           Let $\mathcal{T}\subset \mathcal{C}(0,1)$ be a smooth approximation of $\mathcal{C}(0,1)$ such that $B_\rho'(\overline x)\subset\partial\mathcal{T}\cap B_1'$. For every $g\in L^\infty(\partial \mathcal{T})$, we denote by
           $$\mathcal{S}_\mathcal{T}(g):=\int_{\partial \mathcal{T}} K(x,y) g(y) \, d\mathcal{H}^{d-1}(y)
           $$ the harmonic function with ``boundary datum'' $g$,
           where $K$ is the Green's function of the smooth domain $\mathcal{T}$. By \cite[Theorem 1]{stein-book}, since $q$ is a bounded harmonic function, there exists a function $f \in L^\infty(\partial \mathcal{T})$, such that 
           $$
           \mathcal{S}_\mathcal{T}(f) =q.
           $$
           Moreover, by \cite[Theorem 4]{stein-book} and \eqref{e:ipotesi_tecnica}, we have that $f\ge 1$ on $B'_\rho(\overline x)\cap\mathcal{G}$. Thus there exists $\widetilde f\in L^\infty(\partial \mathcal{T})$ such that $\widetilde f\ge 1$ on $B'_\rho(\overline x)$ and $\widetilde f=f$ almost everywhere. Then, in $\mathcal{T}$, we have 
           $$\widetilde q:=\mathcal{S}_{\mathcal{T}}(\widetilde f)=\mathcal{S}_{\mathcal{T}}(f)=q.$$
           Applying a standard barrier argument (see e.g. \cite[Lemma 3.5]{milakissilvestre-signorini}) to the function $\widetilde q$ and using that $\widetilde q=q$ in $\mathcal{T}$, we conclude the proof.
        \end{proof}

        The final lemma establishes the $C^{0,\alpha}$ regularity of $\sigma_{W}$ around points in $\Omega_{v_\ell}$, and it is the key step in concluding the proof of \cref{lemma:regolaita_prob_lin-thin}.
        \begin{lemma}\label{lemma:final-c}
            There are constants $C>0$ and $\alpha_0\in(0,1)$ depending on $\delta$ such that the following holds. 
            Let $v:B_1\to\R$ be a viscosity solution of \eqref{linearizzato-bordo}, $v_{\ell}$ be as in \eqref{vell2} and let $x_0\in B_{\sfrac{1}{2}}'\cap\Omega_{v_\ell}$. Then, for every $x'\in B_{\sfrac{1}{2}}'$, we have that 
            \be\label{eq:stimac0alpha-persigma}\sigma_{W}(x')\ge -C\|v\|_{L^\infty(B_1)}|x'-x_0'|^{\alpha_0}.\ee
        \end{lemma}
        \begin{proof}
            In the rest of the proof, without loss of generality, we suppose that $\|v\|_{L^\infty(B_1)} \le 1$.
            To prove \eqref{eq:stimac0alpha-persigma}, it is sufficient to show that there are constants $\theta\in(0,1)$ and $\eta\in(0,1)$ such that for every $k\in\N$
            \be\label{indhyp-k}\nabla v_\ell(x)\cdot W\ge -\theta^k\quad\text{for every}\quad x\in \mathcal{C}(x_0,\eta^k).\ee
            By induction, we suppose that \eqref{indhyp-k} holds for $k \in \N$, we prove that \eqref{indhyp-k} holds for $k+1$. 
            By \cref{lemmab7} with $\gamma:=C_2^{-1}\eta^k$, there exists $\overline x\in B_1'$ such that 
            $$B'_{C_1C_2^{-1}\eta^k}(\overline x)\cap\mathcal{G}\subset B'_{\eta^k}(x_0)\cap S_{C_2^{-1}\eta^k},$$ 
            where $\mathcal{G}$ is the set defined in \cref{rem:q.o.}.
            For a constant $c>0$ to be chosen later
            and $\rho:=C_1C_2^{-1}$, we can apply \cref{teclemma-w} to the function $q:B_{\eta^k}^+(x_0)\to \R$ defined as
            $$q:=\frac{\nabla v_\ell(x)\cdot W+\theta^k}{\theta^k-C_2^{-1}\eta^k}$$
            to get that
            $$\nabla v_\ell(x)\cdot W\ge -\theta^k+\eps(\theta^k-C_2^{-1}\eta^k)\ge -\theta^k+\frac{1}{2}\eps\theta^k
            \quad\text{in }
            \mathcal{C}\left(x_0,\frac{\eta^k}2,c\eta^k,\frac{3\eta^k}{4}\right),$$ choosing $\eta<< \theta$, where $\eps>0$ depends only on $d$, $\delta$ and $c$. 
            Precisely, we choose the constant $c= c(\delta)$ such that if
            $$y\in \mathcal{C}\left(x_0,\frac{\eta^k}{4},0,c\eta^k\right),\quad y_d>0,$$ 
            there is $t>0$ such that along the adjoin direction $\widetilde W$ we can find a point $\overline{y}$ such that
            $$\overline y=y+t\widetilde W\in\mathcal{C}\left(x_0,\frac{\eta^k}2,c\eta^k,\frac{3\eta^k}{4}\right)\quad\text{and}\quad \overline y_d=c\eta^k.$$
            In particular 
            $$t=\frac{c\eta^k-y_d}{W_d}.$$
            By the semiconcavity in \cref{lemma:semiconv1} and the fundamental theorem of calculus, we have
            $$\partial_W v_\ell(y)=-t\int_{0}^{1}\partial_{\widetilde WW}v_\ell(sy+(1-s)\overline y)\,ds+\partial_{W}v_\ell\left(\overline y\right)\ge -C\left(\frac{c\eta^k-y_d}{{W_d}}\right)-\theta^k+\frac{1}{2}\eps\theta^k\ge -C \frac{c}{\delta}\eta^k-\theta^k+\frac{1}{2}\eps\theta^k.$$
            Combining the above inequalities, we get  that
            $$\nabla v_\ell(y)\cdot W\ge -C \frac{c}{\delta}\eta^k-\theta^k+\frac{1}{2} \eps\theta^k\quad\text{for every}\quad y\in\mathcal{C}\left(x_0,\frac{\eta^k}4\right). $$
            To conclude, it is sufficient to choose $\theta$ such that
            $$\theta^{k+1}\ge C \frac{c}{\delta}\eta^k+\theta^k-\frac{1}{2}\eps\theta^k.$$ 
            This is possible, since if we choose
            $\eta<<\theta$ and $\theta>1-\frac{1}{4}\eps$, we end up with
            $$
            C \frac{c}{\delta}\eta^k+\theta^k-\frac{1}{2}\eps\theta^k \leq\left(1- \frac{1}{4} \eps\right)\theta^{k}\le \theta^{k+1}, 
            $$
            concluding the proof.
        \end{proof}
        Now we are ready to prove \cref{lemma:regolaita_prob_lin-thin}, which is a consequence of \cref{lemma:final-c}.
        \begin{proof}[Proof of \cref{lemma:regolaita_prob_lin-thin}]
        Notice that $\sigma_W \equiv 0$ in $\Omega_{v_\ell}$ by \eqref{sigma=0}, and that $\sigma_W$ is $C^{0,\alpha}$ regular in the interior of the contact set $\Lambda(v_\ell)$. By \cref{lemma:final-c}, and since $\sigma_W \le 0$ by \cref{lemma:penalized}, we deduce that $\sigma_W$ is $C^{0,\alpha}$ also up to points on the free boundary $\partial \Omega_{v_\ell} \cap B_{\sfrac{1}{2}}'$. Therefore, $\sigma_W \in C^{0,\alpha}(B_{\sfrac{1}{2}}')$.

            Then (see \cite{milakissilvestre-signorini,fullyfernandez} for more details) the $C^{1,\alpha}$ regularity up to the boundary for $v_{\ell}$ follows by classical estimates for oblique boundary problem \cite{lieberman2013oblique}.
            Since the $C^{1,\alpha}$ estimates for $v_{\ell}$ do not depend on $\ell$, the same conclusion holds for $v$, namely $v\in C^{1,\alpha}(\overline{B_{\sfrac{1}{2}}^+})$ with uniform estimates.
        \end{proof}

\begin{appendix}
    \section{Change of coordinates around contact points}
\label{sec:change_coordinates}

This appendix provides a detailed description for the change of coordinates done in \cref{subsec:flatproblem} to make the boundary of $K$ flat. Without loss of generality, let $x_0=0 \in \partial \Omega_u \cap K\cap \mathcal{B}$ be a contact point. 
For all $\eta_0 >0$, we can find a radius $\sigma >0$ and $g \in C^\infty(B_\sigma \cap \{x_d = 0\})$, such that
\begin{equation}
\label{e:ipotesi_boundary_reg_wlog_g}
\partial K \cap B_\sigma = \left\{x_d = g(x')\right\}\qquad \hbox{and} \qquad \norm{g}_{L^\infty(B_\sigma \cap \{x_d = 0\})}\leq \eta_0.
\end{equation}
Moreover, let $\delta>0$ such that $V\cdot \nu_K(x_0)\ge 4\delta$  and  suppose that
\begin{equation}
\label{e:ipotesi_boundary_reg_wlog}
    V\cdot\nu_K(x) \geq 3\delta >0 \quad \hbox{ for all } x \in B_\sigma.
\end{equation}
We consider the diffeomorphism 
$$
\Theta:\left\{\begin{aligned}
B_\sigma &\to \Theta(B_\sigma)\\
(x', x_d)&\mapsto \Theta(x', x_d):= (x', x_d - g(x')),
\end{aligned}
\right.
$$
and we define the function $v:\Theta(B_\sigma)\to \R^+$ such that 
\begin{equation*}
v(y):=u(\Theta^{-1}(y)).
\end{equation*}
Up to rescaling $v$, 
we get that $v:B_1\to\R$. Moreover, the function $v$ is a viscosity solution of
\begin{equation*}
\left\{\begin{aligned}
&{\rm div}\left(\tens{A}(y) \nabla v\right) =0 &&\Omega_v \cap B_1 \cap\{y_d >0\},\\
&\tens{A}(y) \nabla v \cdot \nabla v = \tens{A}(y) \nabla v \cdot \widetilde{V}(y) &&\partial \Omega_v \cap B_1 \cap\{y_d >0\},\\
&\tens{A}(y) \nabla v \cdot \nabla v \geq \tens{A}(y) \nabla v \cdot \widetilde{V}(y) &&\partial \Omega_v \cap B_1 \cap\{y_d =0\},\\
&v = 0 &&\{y_d \leq 0\},
\end{aligned}
\right.
\end{equation*}
where, since $D\Theta^{-1}$ is a triangular matrix,
\begin{equation*}	
	\tens{A}(y) :=\left(D\Theta^{-1}(y)\right)^{-T}
	\left(D\Theta^{-1}(y)\right)^{-1}
	 \abs{
		{\rm det}\left(D \Theta^{-1}(y)\right)}=\left(D\Theta^{-1}(y)\right)^{-T}
	\left(D\Theta^{-1}(y)\right)^{-1}
\end{equation*}
 is a smooth uniform elliptic symmetric matrix with $\tens{A}(0)=\tens{I}$ and for some smooth vector
\begin{equation*}
    \widetilde V(y):=D\Theta^{-1}(y)V.
\end{equation*} 
We observe that the function $u$ is locally Lipschitz continuous in $\mathcal{B}$, by \cref{rem:lipschitz_tutte_viscose}, thus also $v$ is locally Lipschitz continuous in $B_1$.
Given $\Pi_0=\Pi_0(\delta)>0$ small enough, we can take $\eta_0=\eta_0(\Pi_0,\delta)>0$ in \eqref{e:ipotesi_boundary_reg_wlog_g} small enough such that
\be\label{e:widetildeV-diff}
\| \tens{A}(y)-\tens{I}\|_{L^\infty(B_1)}\le \Pi_0\qquad\text{and}\qquad
\| \tens{A}(y)\widetilde V(y) - V\|_{L^\infty(B_1)} \leq \Pi_0.
\ee
Moreover, by \eqref{e:ipotesi_boundary_reg_wlog} and \eqref{e:widetildeV-diff}, choosing the constant $\eta_0$ in \eqref{e:ipotesi_boundary_reg_wlog_g} small enough, for every $y\in B_1$, we have that  
$$\tens{A}(y)\widetilde V(y) \cdot e_d \ge 2\delta.$$ 
In addition, by \cref{lemma:graph}, we have that if $x_0\in\Omega_u\cap D$, then $0<u(x_0+tV)=v(\Theta(x_0+tV))$, for every $t>0$ such that $x_0+tV\in D$, where
 \be\label{eq:oss-utile}
    \gamma(t):=\Theta(x_0+tv):\R\to\R^d \quad \hbox{ such that } \quad
    \left\{
\begin{aligned}
    \gamma'(t) &= \tens{A}(\gamma(t))\widetilde V(\gamma(t)),\\
    \gamma'(0) &= x_0.
 \end{aligned}
 \right.\ee
Finally, we remark that the rate of convergence in \cref{lemma:proprieta_blowup} is still valid for $v = u\circ \Theta^{-1}$, where the statement and the notations must by modified according to the change of variable $\Theta$, as done in \cref{remark:interior}. 
\end{appendix}

