\section{Energy conservation law}
\label{appendix:energy_law}

The energy conservation law is given by 
\begin{equation}
	\label{eq:energy_conservation_law}
	\begin{gathered}
		\frac{ \partial \mathcal{E}}{\partial t} + \sum \limits_{j=1}^3 \frac{\partial J_j}{\partial a_j} = \sigma,
	\end{gathered}
\end{equation}
with the energy density defined by
\begin{equation}
	\label{eq:energy_density}
	\begin{gathered}
		\mathcal{E} = \frac{1}{2}mn^{\mathrm{ref}} \left( \frac{\partial \vec{x}}{\partial t} \right)^2 + \frac{3}{2} n^{\mathrm{ref}} k_B T + \frac{1}{2} \int n^{\mathrm{ref}} (n^{\mathrm{ref}})^T \phi  \left( \frac{g + g^T}{2} \right) \mathrm{d}\vec{a}',
	\end{gathered}
\end{equation}
the energy flux
\begin{equation}
	\label{eq:energy_flux}
	\begin{gathered}
		J_j = - \sum \limits_{i=1}^3 \frac{\partial x_i}{\partial t} \frac{\partial (\mathrm{det}(\partial \vec{x}/\partial \vec{a}))}{\partial (\partial_j x_i)}  \frac{\partial T}{\partial (1/n)} \bigg|_s \left\{ \frac{3}{2} k_B + \frac{1}{2} \int (n^{\mathrm{ref}})^T \phi \frac{\partial g}{\partial T} \bigg|_{n^{\mathrm{ref}}, |\vec{a}-\vec{a}'|} \mathrm{d}\vec{a}' \right\},
	\end{gathered}
\end{equation}
and the nonlocal source term
\begin{equation}
	\label{eq:energy_nonlocal_source}
	\begin{gathered}
		\sigma = \sum \limits_{i=1}^3 \frac{1}{2} \int n^{\mathrm{ref}} (n^{\mathrm{ref}})^T \left( \frac{g + g^T}{2} \right) \left( \frac{\partial \phi}{\partial x_i^T}\bigg|_{\vec{x}} \frac{\partial x_i^T}{\partial t} - \frac{\partial \phi}{\partial x_i}\bigg|_{\vec{x}^T} \frac{\partial x_i}{\partial t} \right) \mathrm{d}\vec{a}'
		\\
		+ \sum \limits_{i=1}^3 \sum \limits_{j=1}^3 \frac{1}{2} \int \phi \bigg( n^{\mathrm{ref}} \frac{\partial \left(g^T/2\right)}{\partial T^T} \bigg|_{(n^{\mathrm{ref}})^T, |\vec{a}-\vec{a}'|} \frac{\partial T^T}{\partial (1/n^T)} \bigg|_{s^T} \frac{\partial (\mathrm{det}(\partial \vec{x}^T/\partial \vec{a}'))}{\partial (\partial'_j x^T_i)} \frac{\partial^2 x_i^T}{\partial t \partial a'_j} 
		\\
		-(n^{\mathrm{ref}})^T  \frac{\partial \left(g/2\right)}{\partial T} \bigg|_{n^{\mathrm{ref}}, |\vec{a}-\vec{a}'|} \frac{\partial T}{\partial (1/n)} \bigg|_s \frac{\partial (\mathrm{det}(\partial \vec{x}/\partial \vec{a}))}{\partial (\partial_j x_i)} \frac{\partial^2 x_i}{\partial t \partial a_j}  \bigg) \mathrm{d}\vec{a}'.
	\end{gathered}
\end{equation}
\par

\section{Linearized equations of motion}
\label{appendix:linearized_eom}

Using the solution form given in Eq.~\eqref{eq:linearized_x}, the equations of motion from Eq.~\eqref{eq:equations_of_motion} yield the first-order correction
\begin{equation}
	\begin{gathered}
		m \frac{\partial^2 {\xi}_i}{\partial t^2} = - \frac{\partial (\vec{\nabla} \cdot \vec{\xi})}{\partial a_i} \bigg( \frac{\partial}{\partial n_0} \bigg|_{s_0} \left( \frac{3}{2} k_B \frac{\partial T_0}{\partial (1/n_0)} \bigg|_{s_0}  \right) \\
		+ \frac{n_0}{2} \frac{\partial^2 T_0}{\partial n_0 \partial (1/n_0)} \bigg|_{s_0} \int \phi (|\vec{r}|) \frac{\partial g_0}{\partial T_0} \bigg|_{n_0, |\vec{r}|} \mathrm{d}\vec{r} \\
		+\frac{n_0}{2} \frac{\partial T_0}{\partial (1/n_0)} \bigg|_{s_0} \frac{\partial T_0}{\partial n_0} \bigg|_{s_0} \int \phi (|\vec{r}|) \frac{\partial^2 g_0}{\partial T_0^2} \bigg|_{n_0, |\vec{r}|} \mathrm{d}\vec{r} \bigg) \\
		+ \frac{1}{2} \frac{\partial T_0}{\partial (1/n_0)} \bigg|_{s_0} \sum \limits_{j=1}^3 \frac{\partial}{\partial a_i} \int \frac{\partial \phi}{\partial a_j}\bigg|_{\vec{a}'} \frac{\partial g_0}{\partial T_0} \bigg|_{n_0, |\vec{a}-\vec{a}'|} \left( \xi_j - \xi^T_j \right) \mathrm{d}\vec{a}' \\
		+ \frac{n_0^2}{2} \frac{\partial T_0}{\partial n_0} \bigg|_{s_0} \int \frac{\partial \phi}{\partial a_i}\bigg|_{\vec{a}'}\frac{\partial g_0}{\partial T_0} \bigg|_{n_0, |\vec{a}-\vec{a}'|} \left( \vec{\nabla} \cdot \vec{\xi} + \vec{\nabla}' \cdot \vec{\xi^T} \right) \mathrm{d}\vec{a}' \\
		- \sum \limits_{j=1}^3 n_0 \int \frac{\partial^2 \phi}{\partial a_i \partial a_j}\bigg|_{\vec{a}'} g_0\left(n_0, T_0, |\vec{a}-\vec{a}'| \right) \left( \xi_j - \xi^T_j \right) \mathrm{d}\vec{a}'.
	\end{gathered}
\end{equation}
As before, the subscript $``0"$ indicates that a function is evaluated at equilibrium.
\par 

For the Fourier transform we use the convention
\begin{equation}
	\begin{gathered}
		\vec{\Psi}(\vec{k}, t) = \widehat{\vec{\xi}}(\vec{k}, t) = \int \vec{\xi}(\vec{a}, t) e^{-i\vec{k}\cdot \vec{a}} \mathrm{d}\vec{a},
	\end{gathered}
\end{equation}
in which case, for any functions $f$ and $g$ that depend on $\vec{a}$, we have $\widehat{\partial f/\partial a_j} = ik_j \widehat{f}$ and $\widehat{f \star g} = \widehat{f}\widehat{g}$, where $\star$ denotes convolution.
In addition, we use the identities 
\begin{equation}
	\label{eq:yukawa_derivatives}
	\begin{gathered}
		\frac{\partial \phi}{\partial r_i} = -\frac{q^2}{4 \pi \varepsilon_0} \frac{r_i e^{-|\vec{r}|/\lambda}}{|\vec{r}|^3} \left(1 + \frac{|\vec{r}|}{\lambda} \right), \\
		\frac{\partial^2 \phi}{\partial r_i \partial r_j} = \frac{q^2}{4 \pi \varepsilon_0} \frac{e^{-|\vec{r}|/\lambda}}{|\vec{r}|^5} \left( r_i r_j \left( 3 + 3\frac{|\vec{r}|}{\lambda} + \frac{|\vec{r}|^2}{\lambda^2} \right) - \delta_{ij} |\vec{r}|^2 \left( 1 + \frac{|\vec{r}|}{\lambda} \right) \right) - \frac{q^2}{3 \varepsilon_0} \delta_{ij} \delta(\vec{r}),
	\end{gathered}
\end{equation}
derived by delta-function properties \cite{10.1119/1.13127}.
\par 

Combining these results leads to 
\begin{equation}
	\begin{gathered}
		m \frac{\partial^2 \vec{\Psi}}{\partial t^2} = \vec{k} (\vec{k} \cdot \vec{\Psi}) \bigg( \frac{\partial}{\partial n_0} \bigg|_{s_0} \left( \frac{3}{2} k_B \frac{\partial T_0}{\partial (1/n_0)} \bigg|_{s_0}  \right) \\
		+ \frac{q^2 n_0}{8 \pi \varepsilon_0} \frac{\partial^2 T_0}{\partial n_0 \partial (1/n_0)} \bigg|_{s_0} \int \frac{e^{-|\vec{r}|/\lambda}}{|\vec{r}|} \frac{\partial g_0}{\partial T_0} \bigg|_{n_0, |\vec{r}|} \mathrm{d}\vec{r} \\
		+\frac{q^2 n_0}{8 \pi \varepsilon_0} \frac{\partial T_0}{\partial (1/n_0)} \bigg|_{s_0} \frac{\partial T_0}{\partial n_0} \bigg|_{s_0} \int \frac{e^{-|\vec{r}|/\lambda}}{|\vec{r}|} \frac{\partial^2 g_0}{\partial T_0^2} \bigg|_{n_0, |\vec{r}|} \mathrm{d}\vec{r} \bigg) \\
		- \frac{iq^2 \vec{k}}{8 \pi \varepsilon_0} \frac{\partial T_0}{\partial (1/n_0)} \bigg|_{s_0} \int \frac{(\vec{r} \cdot \vec{\Psi}) e^{-|\vec{r}|/\lambda}}{|\vec{r}|^3} \left(1 + \frac{|\vec{r}|}{\lambda} \right) \frac{\partial g_0}{\partial T_0} \bigg|_{n_0, |\vec{r}|} \left( 1 - e^{-i\vec{k} \cdot \vec{r}} \right) \mathrm{d}\vec{r} \\
		+ \frac{iq^2 (\vec{k} \cdot \vec{\Psi})}{8 \pi \varepsilon_0 }\frac{\partial T_0}{\partial (1/n_0)} \bigg|_{s_0} \int \frac{\vec{r} e^{-|\vec{r}|/\lambda}}{|\vec{r}|^3} \left(1 + \frac{|\vec{r}|}{\lambda} \right) \frac{\partial g_0}{\partial T_0} \bigg|_{n_0, |\vec{r}|} \left( 1 + e^{-i\vec{k} \cdot \vec{r}} \right) \mathrm{d}\vec{r} \\
		- \frac{q^2 n_0}{4 \pi \varepsilon_0} \int g_0 e^{-|\vec{r}|/\lambda} \bigg( \frac{\vec{r} (\vec{r} \cdot \vec{\Psi})}{|\vec{r}|^5} \left( 3 + 3\frac{|\vec{r}|}{\lambda} + \frac{|\vec{r}|^2}{\lambda^2} \right) \\
		- \frac{\vec{\Psi}}{|\vec{r}|^3} \left( 1 + \frac{|\vec{r}|}{\lambda} \right)  \bigg)  \left( 1 - e^{-i\vec{k} \cdot \vec{r}} \right) \mathrm{d}\vec{r},
	\end{gathered}
\end{equation}
which is then used to obtain Eqs.~\eqref{eq:general_transverse_law} and \eqref{eq:general_longitudinal_law}.

