\subsection{Notations}\label{sec: notations}
\begin{enumerate}[-]%$\triangleright\,\,$]
\item $\kk$ --- ground field of characteristic zero
\item $n\geq 1$ --- number of dimensions
\item $k\geq 1$ --- number of marked points
\item $z^r_i$, $r\in \{1,\dots,n\}$, $i\in \{1,\dots,k\}$ --- coordinates on $(\AA^n)^k$
\item $z^r_{ij} := z^r_i - z^r_j$
\item $u^r_{ij}$ --- coordinates on the polysimplex $\triangle_{n-1}^{\times \binom k2}$, cf. \cref{sec: polysimplices}
\item $I,J,K,\dots \subseteq \{1,\dots,k\}$ --- finite sets of indices, labelling marked points
\item $(\AA^n)^I$ --- a copy of $(\AA^n)^{|I|}$ associated to the index set $I$
\item $I\two := \{(i,j) \in I\times I: i\neq j\}$ for any subset $I\subset \{1,\dots,k\}$
\item $\O_{\AA^1}^I := \kk[z_i]_{i\in I}$, $\B_{\AA^1}^I := \kk[z_i,\frac 1{z_{j\ell}}]_{i\in I; (j,\ell)\in I\two}$
\item $\O_{(\AA^n)^I} := \left( \O_{\AA^1}^I \right)^{\ox n} = \kk[z^r_i]^{1\leq r\leq n}_{i\in I}$, $\B_{\AA^n}^I := \left( \B_{\AA^1}^I \right)^{\ox n} = \kk[z^r_i,\frac 1{z^r_{j\ell}}]^{1\leq r\leq n}_{i\in I; (j,\ell) \in I\two}$
\item $[p]$ --- the $\kk$-vector space of dimension one sitting in homological degree $p$
\item $V[p]:= [p]\ox V$ --- degree-shifted copy of a (possibly graded) $\kk$-vector space $V$
\item $\omega_{\AA^n}$ --- global sections of the canonical sheaf on $\AA^n$
\item $\oms:= \omega_{\AA^n}[n-1]$ --- degree-shifted copy of $\omega_{\AA^n}$
\item $\dd \mathbf z\shifted := \dd z^1 \dots \dd z^n[n-1] \in \oms$ --- shifted volume form
\item $\TS^I_{\AA^n}(\F)$ -- \polysimplicial model of derived sections of  $\F$  on $(\AA^n)^I$; see \cref{sec: TS def}
\end{enumerate}



