\section{A \polysimplicial model of derived sections}
%Higher configuration space and movable punctures}
\label{sec: higher configuration space and movable punctures in two complex dimensions}
We work over a field $\kk$ of characteristic zero (for example $\CC$, the complex numbers).
Let us consider the configuration space $\Conf_k(\AA^n)$ of $k$-tuples of distinguishable, pairwise distinct closed points in affine $n$-space
\be \AA^n:= \AA^n_\kk:= \Spec \kk[z^1,\dots,z^n]. \nn\ee
%(Here and in what follows, we use super- and subscripts for indices of formal variables.)
By definition, %it
$\Conf_k(\AA^n)$
is obtained by starting with the affine scheme
\begin{equation} (\AA^{n})^k = \underbrace{\left(\AA^n \times \dots \times \AA^n\right)}_{\text{$k$ copies}} = \Spec(\kk[z^1_1,\dots,z^n_1;\dots;z^1_k,\dots,z^n_k])
\nn\end{equation}
and removing the diagonals:
\begin{equation} \Conf_k(\AA^n)  := (\AA^{n})^k \setminus \bigcup\ijk \{ z^1_i=z^1_j,\dots,z^n_i=z^n_j\} \label{def: CNN}. \end{equation}
%Here $\{ z^1_i=z^1_j,\dots,z^n_i=z^n_j\}$ is the Zariski-closure of the generalised point corresponding to the prime ideal generated by $(z^1_i=z^1_j)\dots(z^n_i=z^n_j)$.
In the special case of dimension $n=1$, these diagonals are of codimension one and the configuration space is itself an affine scheme,
\be \Conf_k(\AA^1) = \Spec \B_k, \nn\ee
where
\be  \B_k := \Gamma(\Conf_k(\AA^1),\O) = \kk[z_i,(z_j-z_\ell)^{-1}]_{1\leq i\leq k;1\leq j<\ell\leq k}\label{Bkdef}\ee
is the commutative algebra of global sections over $\Conf_k(\AA^1)$ of the structure sheaf.
For all $n>1$, however, the configuration space $\Conf_k(\AA^n)$ is not affine and its structure sheaf has higher cohomology.

The space $R\Gamma(\Conf_k(\AA^n),\O)$ of derived sections %of the structure sheaf $\O$
 comes with a dg commutative algebra structure, unique up to zigzags of quasi-isomorphisms of dg commutative algebras.
Let us describe the model of $R\Gamma(\Conf_k(\AA^n),\O)$ we shall use.


\subsection{Forms on polysimplices}
\label{sec: polysimplices}
Let $\Omega^\bul(\triangle_{n-1})$ denote the dg commutative algebra
\begin{equation} %\Omega_n^\bul:=
\Omega^\bul(\triangle_{n-1})  :=  \kk[u^1,\dots,u^{n}; \dd u^1, \dots \dd u^{n}]\big/\langle \sum_{r=1}^n u^r -1, \sum_{r=1}^n \dd u^r \rangle \nn\end{equation}
with $u^r$ in degree $0$ and $\dd u^r$ in degree $1$, for each $r$, and equipped with the usual de Rham differential.
%
One should think of $\Omega^\bul(\triangle_{n-1})$ as the algebra of polynomial differential forms on the algebro-geometric $(n-1)$-simplex
\be \triangle_{n-1} := \Spec\left( \kk[u^1,\dots,u^{n}]\big/\langle \sum_{r=1}^{n} u^r -1\rangle\right) .\nn\ee
A product $\triangle_{n-1}\times \dots \times \triangle_{n-1}$ of several copies of this simplex is called a  \dfn{polysimplex}. %(prod simplex)
We shall need the algebra of polynomial differential forms on the $\binom k 2$-fold polysimplex:
\begin{align} \Omega^\bul(\triangle_{n-1}^{\times \binom k 2}) &:= \Omega^\bul(\underbrace{\triangle_{n-1}\times \dots \times \triangle_{n-1}}_{\text{$\binom k 2$ times}})\nn\\
&= \kk[u^1_{ij},\dots,u^{n}_{ij}; \dd u^1_{ij}, \dots \dd u^{n}_{ij}]\ijk\big/\langle \sum_{r=1}^{n} u^r_{ij} -1, \sum_{r=1}^{n} \dd u^r_{ij} \rangle\ijk \nn.
\end{align}

\begin{rem}\label{rem: cubes}
In the case of $n=2$ dimensions, the polysimplex is a hypercube
\be \square_{\binom k 2} := \underbrace{\triangle_1\times \dots \times \triangle_1}_{\text{$\binom k 2$ copies}}\nn\ee
and the dg commutative algebra of forms on it admits a simpler description
\begin{equation}
\Omega^\bul(\square_{\binom k 2}) \cong \kk[u_{ij},\dd u_{ij}]\ijk. \nn\end{equation}
%(where $u_{ij} := u_{ij}^1$).
\end{rem}


% More generally, for any totally ordered finite set of indices $(J,<)$, it will be useful to introduce
% \begin{align} \Omega_{n,J}^\bul &:=  \kk[u^1_{ij},\dots,u^{n}_{ij}; \dd u^1_{ij}, \dots \dd u^{n}_{ij}]\ijII \big/\langle \sum_{r=1}^{n} u^r_{ij} -1, \sum_{r=1}^{n} \dd u^r_{ij} \rangle\ijII. \nn
%\end{align}

\subsection{The model $\TS$}\label{sec: TS def}
Recall that $\B_k := \Gamma(\Conf_k(\AA^1),\O)=\kk[z_i,(z_j-z_\ell)^{-1}]_{1\leq i\leq k;1\leq j<\ell\leq k}$ as in \cref{Bkdef}. We think of the tensor product
\begin{align} %\underbrace{\B_k \ox \dots \ox \B_k}_{\text{$n$ fold}}
\B_k^{\ox n} \ox \Omega(\triangle_{n-1}^{\times \binom k 2})
\cong \kk[z^r_i,(z^r_j-z^r_\ell)^{-1}]^{1\leq r\leq n}_{1\leq i\leq k; 1\leq j<\ell<k} \ox \Omega(\triangle_{n-1}^{\times \binom k 2})  \nn
\end{align}
as the algebra of $\B_k^{\ox n}$-valued polynomial differential forms on the polysimplex $\triangle_{n-1}^{\times \binom k 2}$.
Let $\TS_{\AA^n}^{k,\bul}$ denote the following dg commutative subalgebra, in which we place certain boundary conditions on such forms:
\begin{align} \TS_{\AA^n}^{k,\bul}  := &\bigl\{ \tau \in
 \kk[z^r_i,(z^r_j-z^r_\ell)^{-1}]^{1\leq r\leq n}_{1\leq i\leq k; 1\leq j<\ell<k} \ox \Omega^\bul(\triangle_{n-1}^{\times \binom k 2}) \label{def: TS}\\
& \quad :          \text{$\tau|_{u^r_{ij}=0}$ is regular in $(z^r_i-z^r_j)$,  for $1\leq r\leq n$ and $1\leq i<j\leq k$} \bigr\}. \nn
\end{align}
Here $\tau|_{u^r_{ij}=0}$ denotes the pull-back of the form $\tau$ to the face of the polysimplex on which $u^r_{ij} =0$. The differential $\dd_{\TS}$ on $\TS_{\AA^n}^k$ is given by the de Rham differential on the polysimplex.

\begin{thm}\label{thm: polysimplex model NN}
This dg commutative algebra $(\TS_{\AA^n}^k,\dd_{\TS})$ is a model of $R\Gamma(\Conf_k(\AA^n),\O)$:
\begin{equation} \TS_{\AA^n}^k \simeq R\Gamma(\Conf_k(\AA^n),\O). \nn\end{equation}
\end{thm}
\begin{proof}
The proof is given in \cref{sec: proof of polysimplex model NN}.
\end{proof}


%Recall that if $\F$ is a quasicoherent sheaf of (possibly dg) $\O$-modules on $(\AA^{n})^k$ then for every affine open $U\subset (\AA^n)^k$ we have
%\be \Gamma(U,\F) \equiv \F_U \quad\cong_{\O_U}\quad \O_U  \ox_{\O_{(\AA^{n})^k}} \F_{(\AA^{n})^k}.  \nn\ee
Here and subsequently, $\underline{E}$ stands for the quasi-coherent sheaf on ${(\AA^{n})^k}$ corresponding to a module $E$ over $\kk[z^r_i]^{1\leq r\leq n}_{1\leq i\leq k}$. For a sheaf $\F$ of dg $\O_{(\AA^n)^k}$-modules, we define the sheaf $\underline{\TS_{\AA^n}^k}(\F)$ to be the totalization
\be  \underline{\TS_{\AA^n}^{k}}(\F) := \Tot\left(\underline{\TS_{\AA^n}^{k}} \ox_{\O_{(\AA^{n})^k}} \F\right). \nn\ee
Note that $\TS_{\AA^n}^k$ is not only a dg algebra over the regular functions $\mathcal{O}_{(\AA^{n})^k}$, but also a $\mathcal{D}_{(\AA^{n})^k}$-module: we take the usual derivatives $\frac{\partial}{\partial z^r_j}$ and view elements in $\Omega^\bul(\triangle_{n-1}^{\times \binom k 2})$ as constants. Thus, if $\F$ is furthermore a sheaf of right (resp. left) $\D_{(\AA^n)^k}$-modules, % on $(\AA^{n})^k$,
 then $\underline{\TS_{\AA^n}^{k}}(\F)$ is a sheaf of right (resp. left) $\D_{(\AA^n)^k}$-modules via the left $\mathcal{D}_{(\AA^{n})^k}$-module structure on $\underline{\TS_{\AA^n}^{k}}$.
We give our conventions on $\D$-modules in \cref{sec: D module background}.
\begin{thm}\label{thm: F model}
Let $j:\Conf_k(\AA^n)\hookrightarrow (\AA^{n})^k$ denote the open embedding.
\begin{enumerate}[(1)]
\item Let $\F$ be a bounded complex of $\O_{(\AA^{n})^k}$-modules with $\mathcal{O}_{(\AA^{n})^k}$-quasi-coherent cohomology. Then
\be \underline{\TS_{\AA^n}^{k,\bul}}(\F)  \simeq \underline{R\Gamma(\Conf_k(\AA^n),j^{\centerdot}\F)}\simeq Rj_{\centerdot}j^{\centerdot}\F \nn\ee
in the bounded derived category of $\O_{(\AA^{n})^k}$-modules.

\item Let $\F$ be a bounded complex of $\D_{(\AA^{n})^k}$-modules with $\mathcal{O}_{(\AA^{n})^k}$-quasi-coherent cohomology. Then
\be \underline{\TS_{\AA^n}^{k,\bul}}(\F)  \simeq \int_jj^{*}\F \nn\ee
in the bounded derived category of $\D_{(\AA^{n})^k}$-modules.
\end{enumerate}


Here $j_{\centerdot},j^{\centerdot}$ are direct and inverse image for $\O_{(\AA^{n})^k}$-modules. And $\int_j,j^*$ are the (derived) direct and inverse image for $\D_{(\AA^{n})^k}$-modules (in our case $j^*=j^{\centerdot}$).
\end{thm}
\begin{proof}
The proof is given in \cref{sec: proof of F model}.
\end{proof}

In this paper, we will mainly deal with quasi-coherent $\D$-modules on $(\AA^n)^k$ and we will not distinguish the global section $\Gamma((\AA^n)^k,\F)$ and $\F$ itself. For example, we will just write ${\TS_{\AA^n}^{k,\bul}}(\F) $ instead of $\underline{\TS_{\AA^n}^{k,\bul}}(\F) $.



\subsection{Generators and relations for $\TS$}\label{sec: gens and rels for TS}
In \cref{sec: TS def} we gave the algebro-geometric definition of the model $\TS$, as the dg commutative algebra of polynomial differential forms on a polysimplex, valued in a particular ring, and obeying certain boundary conditions.

The model also has the following purely algebraic description in terms of generators and relations.
\begin{thm}\label{thm: TS gens and rels} There is an isomorphism of dg commutative algebras
\be \TS^k_{\AA^n} \cong \directlim_{m\geq 0}\kk\left[ z^r_i, \frac{u^r_{j\ell}}{(z^r_j-z^r_\ell)^m}, \frac{\dd u^r_{j\ell}}{(z^r_j-z^r_\ell)^m}, \right]^{1\leq r\leq n}_{\substack{1\leq i\leq k\\ 1\leq j<\ell\leq k}}\big/\langle \sum_{r=1}^{n} u^r_{ij} -1, \sum_{r=1}^{n} \dd u^r_{ij} \rangle\ijk \nn. \ee
\end{thm}
\begin{proof} \cref{thm: TS gens and rels} is a special case of \cref{thm: TSIE gens and rels}, below.
\end{proof}
Let $I\two := \left\{ (i,j) \in I \times I \,\middle|\, i\neq j\right\}$ denote the set of ordered pairs of distinct elements of an index set $I$.
Let $I\two/S_2$ denote the set of unordered pairs.
Given an ordered pair $e=(i,j) \in I\two$ we write
\be z_{e} := z_{ij} := z_i - z_j = - z_{ji}. \nn\ee
Given an unordered pair $e\in I\two/S_2$, for definiteness we set $z_e := z_i-z_j$ for the choice of representative $(i,j)$ such that $i<j$ relative to some fixed but arbitrary ordering $<$ of the index set $I$.
%
%(Mostly we are concerned with unordered pairs; the exceptions occur where it is important to keep track of the relative sign in $z_{ij} = -z_{ji}$, as for example in the Arnold relations \cref{eq: arnold relations} below.)
%
We think of elements of $I$ as vertices and elements of $I\two/S_2$ as undirected edges.
For a set of undirected edges $E\subset I\two/S_2$, let us define% such that $(i,j)\in E\Leftrightarrow (j,i) \in E$:
\begin{enumerate}[-]
%\item  $\B_{\AA^1}^{I,E} := \kk[z_i,\frac 1{z_e}]_{i\in I; e\in E}$,
%\item $\B_{\AA^n}^{I,E} := \left( \B_{\AA^1}^{I,E} \right)^{\ox n} = \kk[z^r_i,\frac 1{z^r_e}]^{1\leq r\leq n}_{i\in I; e \in E}$
\item $\Omega_{n}^{I,E} := \kk[u^r_e; \dd u^r_e]^{1\leq r\leq n}_{e \in E} \big/\langle \sum\limits_{r=1}^{n} u^r_e -1, \sum\limits_{r=1}^{n} \dd u^r_e \rangle_{e\in E}$, we sometimes write $u^s_{ij}=u^s_{ji}=u^s_e$ if $e=(i,j)$.
\item $\mathbf \Omega_{\AA^n}^{I,E} := \kk[z^r_i,\frac 1{z^r_e}]^{1\leq r\leq n}_{i\in I; e \in E} \ox_\kk \Omega_{n}^{I,E}$
\end{enumerate}
Given also an undirected edge $e\in E$ and a direction $s\in \{1,\dots,n\}$, let
\begin{enumerate}[-]
\item $\Omega^{I,E}_{n,(e,\del_s)} := \Omega_{n}^{I,E}\big/ \langle u_e^s = 0, \dd u_e^s=0\rangle$
\item $\mathbf \Omega^{I,E}_{\AA^n,(e,\del_s)} %= \B^{I,E}_{\AA^n} \ox \Omega^{I,E}_{\AA^n,(e,\del_s)}
:= \mathbf \Omega^{I,E}_{\AA^n}\big/  \langle u_e^s = 0, \dd u_e^s=0\rangle=\kk[z^r_i,\frac 1{z^r_e}]^{1\leq r\leq n}_{i\in I; e \in E} \ox_\kk \Omega_{n,(e,\partial_s)}^{I,E}$
\item $\mathbf \Omega^{I,E}_{\AA^n,(e,\del_s)^{\mathbf{reg}}} := \kk[z^r_i,\frac 1{z^t_{f}}]^{(r,i)\in \{1,\dots,n\}\times I}_{(t,f)\in (\{1,\dots,n\}\times E) \setminus \{(s,e)\}} \ox \Omega^{I,E}_{n,(e,\del_s)}$
\item $\mathbf \Upsilon^{I,E}_{\AA^n,u^s_e=0} := \mathbf \Omega^{I,E}_{\AA^n,(e,\del_s)}\big/  \mathbf \Omega^{I,E}_{\AA^n,(e,\del_s)^{\mathbf{reg}}}$
\end{enumerate}
We get the canonical quotient maps
$\Res_e^{I,E}|_{u^s_e=0} : \mathbf \Omega^{I,E}_{\AA^n} \to \mathbf\Upsilon^{I,E}_{\AA^n,u^s_e=0}$
(these quotient maps behave like residue maps) and define the dg commutative algebra
\be \TS^{I,E}_{\AA^n} := \bigcap_{\substack{e\in E\\ s\in\{1,\dots,n\}}} \ker\left( \Res_e^{I,E}|_{u^s_e=0}\right) \subset \mathbf \Omega^{I,E}_{\AA^n} .\label{def: TSIE}\ee
Observe that then the model $\TS^k_{\AA^n}$ as we defined it in \cref{def: TS} is equivalently given by
\be \TS_{\AA^n}^k \cong \TS^{I}_{\AA^n} := \TS^{I,I\two/S_2}_{\AA^n} \nn\ee
with $I= \{1,\dots,k\}$. Define the dg commutative algebra
\be \mathbf B^{I,E} := \directlim_{m\geq0}\kk\left[ z^r_i, \frac{u^r_{e}}{(z^r_{e})^m}, \frac{\dd u^r_{e}}{(z^r_{e})^m}\right]^{1\leq r\leq n}_{i\in I, e\in E}\big/\langle \sum_{r=1}^{n} u^r_{e} -1, \sum_{r=1}^{n} \dd u^r_e\rangle_{e\in E}\nn. \ee
%Note that $\bigotimes_{\O^I_{\AA^n}}^{e\in E}\mathbf{B}_{\AA^n}^{I,\{e\}}=\mathbf{B}_{\AA^n}^{I,E}$.

\begin{thm}\label{thm: TSIE gens and rels}
There is an isomorphism of commutative dg algebras
\be \TS^{I,E}_{\AA^n} \cong \mathbf B^{I,E}_{\AA^n} ,\nn\ee
for any finite sets of indices $I$ and of undirected edges $E\subset I\two/S_2$.% such that $(i,j) \in E \Leftrightarrow (j,i)\in E$.
\end{thm}
\begin{proof} The proof is given in \cref{sec: proof of thm TSIE gens and rels}.
\end{proof}

\section{Main result: The homology of the \polysimplicial unit chiral operad}\label{sec: main}

In this section we define the unit chiral operad on $\AA^n$, in the \polysimplicial model. It is a dg operad -- that is, an operad in chain complexes of $\kk$-vector spaces.
Our main result is that its homology is isomorphic to the Lie operad.



\subsection{The shifted canonical sheaf $\omega\shifted$}\label{sec: shifted canonical bundle}

We will first introduce some notations. The canonical sheaf $\omega_{\AA^n}$ on $\AA^n$ is a right module over $\D_{\AA^n} = \kk[ z^r, \del_{z^r}]^{1\leq r\leq n}$. The action is given by
\begin{align} (p(z) \dd z^1\dots \dd z^n) \cdot \del_{z^s} &:= - \left(\del_{z^s} p(z)\right) \dd z^1\dots \dd z^n,\nn\\
 (p(z) \dd z^1\dots \dd z^n) \cdot z^s &:= \phantom{+} \left(z^s p(z)\right) \dd z^1\dots \dd z^n .\nn
\end{align}
Similarly, $\Gamma((\AA^{n})^k,\omega_{\AA^n}^{\boxtimes k}) = \omega_{(\AA^{n})^k}$ is a right module over $\DAAnk= \kk[ z^r_i, \del_{z^r_i}]^{1\leq r\leq n}_{1\leq i\leq k}$.

Whenever $\F$ is a left $\D$-module and $\G$ a right $\D$-module, the tensor product $\F\ox_\O \G$ is canonically a right $\D$-module
(with $(f \ox g)\cdot \del := (-\del f)\ox \tau + f\ox(\tau\cdot \del)$ for any derivation $\del$).
Thus, as $\TS_{\AA^n}^{k}$ (defined in \cref{def: TS}) is a left $\D$-module,
\be \TS_{\AA^n}^{k}((\omega_{\AA^n})^{\boxtimes k}) := \TS_{\AA^n}^{k} \ox_{\O_{(\AA^{n})^k}} \omega_{(\AA^{n})^k} \nn\ee
is a right $\DAAnk$-module.

The $\D$-module pushforward $\Delta_* \omega_{\AA^n}$ of $\omega_{\AA^n}$ along the closed diagonal embedding $\AA^n\into (\AA^n)^k$
%(defined, dually, by $z^r_i \mapsto z^r$)
is given as a $\kk$-vector space by
\be \Delta_* \omega_{\AA^n} := \omega_{\AA^n} \ox_{\kk[\lambda^r]^{1\leq r\leq n}} \kk[\lambda^r_i]^{1\leq r\leq n}_{1\leq i\leq k}. \nn\ee
The commutative variables $\lambda^s, \lambda^s_i$ should be viewed as $\del_{z^s}, \del_{z^s_i}$ respectively. The right action of $\lambda^s$ on $\omega_{\AA^n}$ is given by the right action of $\del_{z^s}$ as above; the left action of $\lambda^s$ on $\kk[\lambda^r_i]^{1\leq r\leq n}_{1\leq i\leq k}$ is via the map $\lambda^s\mapsto \sum\limits^k_{i=1}\lambda^s_i$. The right $\DAAnk$-module structure of $\Delta_* \omega_{\AA^n}$ is given by
\[
\left(\tau\otimes P(\lambda)\right)\del_{z^s_i}:=\tau\otimes P(\lambda)\cdot\lambda^s_i,\quad \left(\tau\otimes P(\lambda)\right){z^s_i}:=\tau\otimes (\del_{\lambda^s_i}P(\lambda))+(z^s\tau)\otimes P(\lambda).
\]

Our main interest is in the shifted canonical sheaf, the copy of $\omega_{\AA^n}$ degree-shifted into cohomological degree $1-n$:
\be \oms := \omega_{\AA^n}[n-1] .\nn\ee
(The reason for this shift is that it will put the binary chiral bracket $\mu_2$ correctly in degree zero, as we shall see in \cref{sec: higher operations}.)

As a shorthand, we shall write
$\dd \mathbf z\shifted := \dd z^1 \dots \dd z^n[n-1]$.
Then sections of $(\oms)^{\boxtimes k}= \omega_{(\AA^{n})^k}[k(n-1)]$ over $(\AA^{n})^k$ take the form
\be f\left((z^r_i)^{1\leq r\leq n}_{1\leq i\leq k} \right) \dd\zz_1\shifted \dots  \dd\zz_k\shifted \nn\ee
and sit in cohomological degree $k(1-n)$. We will mainly work with the $\D_{(\AA^n)^k}$-modules $\TS_{\AA^n}^{k}((\oms)^{\boxtimes k})$and $\Delta_*\oms$. Notice that in our convention, the degree $\bullet$ in $\TS_{\AA^n}^{k,\bullet}((\oms)^{\boxtimes k})$ is the total degree
$$
\TS_{\AA^n}^{k,\bullet}((\oms)^{\boxtimes k})=\Tot^{\bullet}\left(\underline{\TS_{\AA^n}^{k}} \ox_{\O_{(\AA^{n})^k}} \oms\right).
$$

\subsection{The \polysimplicial unit chiral operad}\label{sec: TS unit chiral operad}
We shall define a dg operad $\P^{ch}_{\AA^n}$.
%To that end we must first specify a chain complex $\P^{ch}_{\AA^n,\bul}(k)$ of $k$-ary operations, for each $k\geq 0$.
%We set
%$ \P^{ch}_{\AA^n,\bul}(0) := 0$
%and f
For every strictly positive $k$ we let
\be \P^{ch}_{\AA^n}(k) := \Hom_{\DAAnk}\left(\TS_{\AA^n}^{k}((\oms)^{\boxtimes k}), \Delta_*\oms \right).\nn\ee
Recall that $\Delta_*\oms$ is by our definition concentrated in cohomological degree $-(n-1)$. Therefore, more explicitly, one has
\be \P^{ch}_{\AA^n,\bul}(k) := \mathop\oplus\limits_{l\in\mathbb{Z}}\Hom_{\DAAnk}\left(\TS_{\AA^n}^{k,\bul+l}((\oms)^{\boxtimes k}), (\Delta_*\oms)^{l} \right)\nn\ee
\be=\Hom_{\DAAnk}\left(\TS_{\AA^n}^{k,\bul-(n-1)}((\oms)^{\boxtimes k}), \Delta_*\omega_{\AA^n}\right),\nn\ee
%cohom degree of map = cohom degree of target - cohom degree of source = (n-1) - \bul
%hom degree of map = - cohom degree of map = \bul - (n-1)
with the differential given by
\be \dd_\P(-) := (-)\circ \ddts .\nn\ee
% Recall here from \cref{sec: shifted canonical bundle} that
% \begin{enumerate}[--]
% \item $\oms:= \omega_{\AA^n}[n-1]$ denotes the global sections of the canonical bundle put into cohomological degree $-(n-1)$, and $\Delta_*\oms$ its $\D$-module pushforward by the diagonal embedding $\Delta: \AA^n \into  (\AA^n)^k$; and
% \item $\TS_{\AA^n}^{k,\bul}((\oms)^{\boxtimes k})$ is defined in \cref{def: TSomega}.
% \end{enumerate}
Thus, for each strictly positive $k$ we have a chain complex of $k$-ary operations\footnote{Indeed, since elements of $\TS_{\AA^n}^{k,p}((\oms)^{\boxtimes k})$ are given by  $p+ k(n-1)$-forms on the polysimplex $\triangle_{n-1}^{\times \binom k2}$, the cochain complex $\TS_{\AA^n}^{k,\bul}((\oms)^{\boxtimes k})$ is concentrated in cohomological degrees $[-k(n-1), -k(n-1) + \binom k 2 (n-1)]$. Therefore the chain complex $\P^{ch}_{\AA^n,\bul}(k)$ is concentrated in homological degrees $[-(k-1)(n-1),-(k-1)(n-1) + \binom k 2 (n-1)]$. }
\begin{align}
0 \leftarrow \P^{ch}_{\AA^n,-(k-1)(n-1)}(k) \xleftarrow{\dd_\P} \dots \xleftarrow{\dd_\P} \P^{ch}_{\AA^n,0}(k) \xleftarrow{\dd_\P} \dots \xleftarrow{\dd_\P} \P^{ch}_{\AA^n, \binom{k-1} 2 (n-1)}(k) \leftarrow 0.
\nn\end{align}
\begin{prop}\label{prop: operad}
$\P^{ch}_{\AA^n}$ is a dg operad.
\end{prop}
\begin{proof}
The proof is given in \cref{sec: operad}.
\end{proof}

\begin{comment}
In particular, for the $1$-ary and $2$-ary operations we have
\begin{align}
\P^{ch}_{\AA^n,\bul}(1)&: &\bigl( 0\leftarrow  \P^{ch}_{\AA^n,0}(1)=\Hom_{\DAAnk}\left(\oms,\oms\right)=
&\kk\leftarrow 0 \bigr)                       \nn\\
\P^{ch}_{\AA^n,\bul}(2)&: &\bigl( 0\leftarrow \P^{ch}_{\AA^n,-(n-1)}(2) \xleftarrow{\dd_\P} \dots \xleftarrow{\dd_\P} &\P^{ch}_{\AA^n,0}(2)\leftarrow 0\bigr).\nn
\end{align}
\end{comment}

\begin{rem}\label{rem: reln to DS} From \cref{thm: F model}, $\TS_{\AA^n}^{k}((\omega_{\AA^n})^{\boxtimes k})$ represents $\int_jj^*(\omega_{\AA^n})^{\boxtimes k}$.
In the case of dimension $n=1$, the higher direct image vanishes and we have
  \[
  \Gamma\bigl((\AA^{1})^k,\smallint_j(j^*M)\bigr)\simeq     \Gamma\bigl((\AA^{1})^k,j_{\centerdot}j^{\centerdot}M\bigr)=\TS^{k}_{\AA^1}(M).
  \]
Beilinson and Drinfeld \cite{BDChiralAlgebras} define the unit chiral operad, i.e., the operad of chiral operations on $\omega_X$, for curves $X$; in the case of $X=\AA^1$ their definition is
\begin{align}\P_{\AA^1}^{ch}(k)&:=\Hom_{\D_{(\AA^1)^k}
}\left(j_*j^{*}\omega_{\AA^1}^{\boxtimes k},\Delta_*\omega_{\AA^1}\right)\nn\\
% \end{align}
% When $X=\AA^1$, it is enough to consider global sections (since $\AA^k$ are $\D$-affine) and one has
% \begin{align}
%\P_{\AA^1}^{ch}(k)
&=\Hom_{\D_{(\AA^1)^k}}\left(\TS^{k}_{\AA^1}(\omega_{\AA^1}^{\boxtimes k}),\Delta_*\omega_{\AA^1}\right)\nn.
\end{align}
It is thus natural to use $\TS^{k}_{\AA^n}(\omega_{\AA^n}^{\boxtimes k})$ to construct higher analogs of the unit chiral operad for affine spaces.
\end{rem}
\begin{prop}\label{prop: mu2Residue}
    The residue operation $\mu$ defined in \cref{sec: higher operations} is an antisymmetric element in $\P^{ch}_{\AA^n,0}(2)$ and it is closed, $\dd_\P(\mu_2)=0$.
\end{prop}
\begin{proof}
    Recall that $\mu_2\in \Hom_{\mathbf{k}}\left(\TS_{\AA^n}^{2,-(n-1)}((\oms)^{\boxtimes 2}), \Delta_*\omega_{\AA^n}\right)$ is defined by
    $$
    \mu_2=
\mu_2^{2\rightarrow 1}=\int_{\triangle_{n-1}}
\res_{z^1_2 \to z^1_1} e^{\lambda^1_2(z^1_2- z^1_1) } \dots \res_{z^n_2 \to z^n_1} e^{\lambda^n_2(z^n_2- z^n_1) }
    ,$$
    where we identify $\Delta_*\omega_{\AA^n}=\omega_{\AA^n} \ox_{\kk[\lambda^r]^{1\leq r\leq n}} \kk[\lambda^r_1,\lambda^r_2]^{1\leq r\leq n}$ with $\omega_{\AA^n} \ox_{\kk} \kk[\lambda^r_2]^{1\leq r\leq n}$. Here we use the notation $\res_{z^s_2 \to z^s_1} e^{\lambda^s_2(z^s_2- z^s_1) }$ following \cite{vanEkerenHeluaniChiralHomologyEllipticCurvesZhu}. The fact that $\mu_2$ is a $\D_{(\AA^n)^2}$-module map follows from the construction, and the antisymmetry can be checked directly after we introduce the symmetric group action in \cref{sec: operad}. To see that $\mu_2$ is closed, we use Stokes' theorem and the defining boundary conditions \cref{def: TS} of the model.
\end{proof}
\subsection{The main theorem}
Our main result is the following.

\begin{thm}\label{thm: ChiralIsoLie}
    The homology of the \polysimplicial unit chiral operad $\P^{ch}_{\AA^n,\bul}$ is isomorphic to the usual Lie operad:
\be \LieOperad \cong H(\P^{ch}_{\AA^n,\bul}). \nn\ee
\end{thm}

The proof is given in \cref{sec: main proof} and consists of two steps. First for given $k\geq 2$, we fixed a base point to reduce the complex $\P^{ch}_{\AA^n,\bul}(k)$ to a complex of Hom spaces of translation invariant $\D$-modules. Then we show that these in turn map injectively to the dual of the top degree part of the de Rham cohomology of the configuration space, which is isomorphic to the Lie operad (see \cite{totaro1996configuration} and references therein). Then we use the chain level residue map to show that this map is also surjective.

Beilinson and Drinfeld prove (\cite[Theorem 3.1.5]{BDChiralAlgebras} with $X=\AA^1$)  that the operad of chiral operations on $\omega_{\AA^1}$ is isomorphic to the Lie operad:
\be \LieOperad \cong \P^{ch}_{\AA^1} .\nn\ee
Our theorem generalizes this to affine spaces $\AA^n$ of any dimension $n$.


Theorem \ref{thm: ChiralIsoLie}
%implies
is equivalent to the following result (whose meaning we described more explicitly in \cref{sec: higher operations} above).
Let $\LieInfinityOperad$ denote the dg operad governing  \Linfinity-algebras.
\begin{thm}\label{thm: quasi-isomorphism from LieInfinity}
    There is a quasi-isomorphism, of operads in chain complexes of $\kk$-vector spaces,
\[\LieInfinityOperad\xrightarrow\sim \P_{\AA^n}^{ch}.\]
\end{thm}
\begin{proof}
The argument is standard in the theory of dg operads; see for instance \cite{berger2003axiomatic,HinichHomotopyAlgebras,LodayVallette} and also the recent survey \cite{campos2023operadic}.
%
The category of dg operads has a model category structure in which the weak equivalences are quasi-isomorphisms and the fibrations are degree-wise surjections; see \cite[\S1.4.3]{campos2023operadic} and references given there.
%
The dg-operad $\LieInfinityOperad$ is the minimal cofibrant resolution of the Lie operad $\LieOperad$; see \cite[\S1.5]{campos2023operadic}.
%
We have the following diagram
\be \begin{tikzcd}                                                                        &                                       & \P_{\AA^n}^{ch}                                                                                              \\
\bullet \arrow[d, "\text{cofibration}"'] \arrow[rr]                      &                                       & \P^{ch}_{\AA^n,\geq 0} \arrow[d, "\text{fibration}\cap\text{W}", two heads] \arrow[u, "\text{quasi-iso}"'] \\
\LieInfinityOperad \arrow[r, "\text{quasi-iso}"'] \arrow[rru, dashed] & \LieOperad \arrow[r, "\text{iso}"] & {H\P_{\AA^n}^{ch}}
\end{tikzcd}\nn\ee
Here $\P_{\AA^n,\geq 0}^{ch}$ is the truncation
\be
\begin{tikzcd}
\P_{\AA^n}^{ch}(k):                                        & \dots \arrow[r] & \P_{\AA^n,1}^{ch}(k) \arrow[r,"d_\mathcal{P}"]                                & \P_{\AA^n,0}^{ch}(k)\arrow[r, "d_\mathcal{P}"]             & \P_{\AA^n,-1}^{ch}(k) \arrow[r] & \dots \\
\P_{\AA^n,\geq 0}^{ch}(k): \arrow[u, "\text{quasi-iso}"] & {\cdots} \arrow[r]    & \P_{\AA^n,1}^{ch}(k) \arrow[r,"d_\mathcal{P}"] \arrow[u] & \mathrm{Ker}(\dd_\P) \arrow[r] \arrow[u] & 0 \arrow[u]           &
\end{tikzcd}\nn\ee
and the vertical map is a quasi-isomorphism by virtue of \cref{thm: ChiralIsoLie}.
By the left lifting property of the cofibration $\bullet\rightarrow \LieInfinityOperad$ we have the quasi-isomorphism $\LieInfinityOperad\xrightarrow\sim \P_{\AA^n,\geq 0}^{ch}$ and hence the required quasi-isomorphism
$\LieInfinityOperad\xrightarrow\sim \P_{\AA^n}^{ch}$.
\end{proof}

\subsection{Homotopy polysimplicial chiral algebras on $\AA^n$}\label{sec: homotopy polysimplicial chiral algebras}
Malikov and Schechtman \cite{MalikovSchechtman} define the notion of a \dfn{homotopy chiral algebra} on a curve $X$ as a map
from $\LieInfinityOperad$ to the usual chiral operad $\P_{X}^{ch}[\A](k):=\Hom_{\D_{X^k}}\left(j_*j^{*}\mathcal{A}^{\boxtimes k},\Delta^{}_*\A\right)$ associated to a dg $\D_X$-module $\mathcal{A}$ (here $j:\Conf_k(X)\hookrightarrow X^k\hookleftarrow X:\Delta$). It is natural to generalize their definition to higher dimensions, at least for affine spaces $\AA^n$, using the \polysimplicial model, as follows.

Suppose that $(\A,\dd_\A)$ is a quasi-coherent dg $\D_{\AA^n}$-module.
We define
\[\P^{ch}_{\AA^n}[\A](k):=\Hom_{\DAAnk}\left(\TS^{k}_{\AA^n}(\mathcal{A}^{\boxtimes k}),\Delta_*\A\right)\]
with the differential $\dd_\P[\A]$ given by
\[\left(\dd_\P[\A]\mu\right)(-)=\dd_\A\left(\mu(-)\right)\pm\mu\left((\dd_{\A^{\boxtimes k}}+\ddts)(-)\right)\]
(where $\pm$ is the required Koszul sign).

This defines a dg operad (by a generalization of \cref{prop: operad}).
\begin{defn}
%  Let $(\A,\dd_\A)$ be a dg $\D_{\AA^n}$-module.
A \dfn{homotopy polysimplicial chiral algebra} structure on $\mathcal{A}$ is a map of dg operads
\[  \LieInfinityOperad\rightarrow \P_{\AA^n}^{ch}[\A].\]
\end{defn}

In this language, our result \cref{thm: quasi-isomorphism from LieInfinity} implies the following:
\begin{cor}
The degree-shifted canonical sheaf $\oms := \omega_{\AA^n}[n-1]$ on $\AA^n$ has the structure of a homotopy polysimplicial chiral algebra.  \qed
\end{cor}
\begin{rem}
Our definition is not equivalent to that in \cite{FrancisGaitsgory} since we are working with a specific model (the \polysimplicial model) and the dg operad depends on the choice of model. In our definition, the hom spaces are not derived; one needs to work with $\infty-$operads to handle the fully derived chiral operations.  However, using Drinfeld's dg quotient construction, one can embed our polysimplicial hom space into the derived one. Thus, we expect homotopy chiral algebras in the \polysimplicial model can be turned into special examples of higher dimensional chiral algebras in \cite{FrancisGaitsgory}. Details are left to future work.
\end{rem}


\section{Operad structure of $\P^{ch}_{\AA^n,\bul}$}\label{sec: operad}


In \cite[\S1.3.1]{BDChiralAlgebras}, an operad consisting of the chiral operations of a $\mathcal{D}_X$-module $M$ on a smooth curve $X$ is constructed. For a more detailed study of this operad and its relation to vertex algebra cohomology, we refer the reader to \cite{bakalov2020chiral} and the references given there. In this section, we extend the construction in \cite[\S1.3.1]{BDChiralAlgebras} to $X=\AA^n$ for all $n\geq 1$ using our polysimplicial model.

We will first define the symmetric group action on each component of $\P^{ch}_{\AA^n}[M]$ explicitly. For a nonempty finite index set $I$ with $k>0$-many elements, the \polysimplicial chiral $I$-operations are the chain complex of $\kk$-vector spaces
\be \P^{ch}_{\AA^n}[M](k) := \P^{ch}_{\AA^n}[M](I\to \{\star\}) := \Hom_{\D_{(\AA^n)^I}}\left(\TS_{\AA^n}^{I}(M^{\boxtimes I}), \Delta_*^{I/\{\star\}}M \right).\nn\ee
Here, $\Delta^{I/\{\star\}}$ is defined as the diagonal embedding $\Delta^{I/\{\star\}}:(\AA^n)^{\{\star\}}\cong\AA^n\into (\AA^n)^I$.
\begin{defn}
We define the action of the symmetric group $S_{|I|}$ on  $\P^{ch}_{\AA^n}[M](I\to \{\star\})$ by
  \[
 (\sigma\mu)(-):=\sigma\mu(\sigma^{-1}-)
  \]
where
\begin{enumerate}[-]
\item
the action on $\TS_{\AA^n}^I(M^{\boxtimes I})$ is given by
\begin{align}
&\sigma\left(\alpha(z^r_i, u_{ij},\dd u_{ij})\cdot m_1\boxtimes \cdots\boxtimes m_k\right)\nn\\
&
\quad :=(-1)^{\chi(m_1,\dots,m_k;\sigma)}\alpha(z^r_{\sigma(i)},u^r_{\sigma(i)\sigma(j)},\dd u^r_{\sigma(i)\sigma(j)}) \cdot m_{\sigma^{-1}(1)}\boxtimes \cdots\boxtimes m_{\sigma^{-1}(k)}\nn
\end{align}
where $m_i\in \Gamma(\AA^n,M)$ and $\chi(m_1,\dots,m_k;\sigma)$ is the Koszul sign.\footnote{
Note here that $z^r_1 = z^r \ox 1 \ox \dots \ox 1 \in \O_{\AA^n}^{\ox k} \cong \O_{(\AA^{n})^k}$ and so on, and hence
\[
\cdots\boxtimes \underbrace{f(z)m}_{\text{i-th}}\boxtimes\cdots =f(z_i)\cdot \left(\cdots\boxtimes \underbrace{m}_{\text{i-th}}\boxtimes\cdots \right).
\]
}
\item the action on $\Delta_*M$ is given by
\[
\sigma\left(m\otimes f(\lambda^r_1,\dots,\lambda^r_k)\right):=m\otimes f(\lambda^r_{\sigma(1)},\dots,\lambda^r_{\sigma(k)}).
\]
\end{enumerate}
\end{defn}

