\begin{subequations}\label{def: c maps}
Next we observe that there is a well-defined map
\begin{equation}
 \TS^{\{K_{J_i}\}_{i\in I}}\rightarrow \TS^{\{J_i\}_{i\in I}}
\nn\end{equation}
defined by sending
\be z^r_k \mapsto z^r_{\pi(k)},\qquad
 u^r_{kk'} \mapsto u^r_{\pi(k)\pi(k')},\ee
where $\pi : K \onto J$ is the surjection sending $K_j \onto \{j\}$ for each $j\in J$. This is a $\kk[\lambda^r_j]^{1\leq r\leq n}_{j\in J}-$module map if we use $\lambda^r_j=\sum\limits_{k\in K_j} \lambda^r_k$ to define the $\kk[\lambda^r_j]^{1\leq r\leq n}_{j\in J}-$module structure on $ \TS^{\{K_{J_i}\}_{i\in I}}$.
Thus we get a $\D$-module map
\begin{gather}
c^{[K_{J_i}]_{i\in I}}_{[J_i]_{i\in I}}:  \left(  (\mathop\boxtimes_{i\in I}M_{J_i})\ox_{\O_{(\AA^n)^K}}\TS^{\{K_{J_i}\}_{i\in I}}\right)\ox_{\kk[\lambda^r_{j}]^{1\leq r\leq n}_{j\in J}}\kk[\lambda^r_{k}]^{1\leq r\leq n}_{k\in K}\nn\\
\rightarrow \left(  (\mathop\boxtimes_{i\in I}M_{J_i})\ox_{\O_{(\AA^n)^J}}\TS^{\{J_i\}_{i\in I}}\right)\ox_{\kk[\lambda^r_{j}]^{1\leq r\leq n}_{j\in J}}\kk[\lambda^r_{k}]^{1\leq r\leq n}_{k\in K}.
\end{gather}
\end{subequations}

\begin{defn}\label{def: Imap}
  We define a $\D$-module map
  \[
\mathbf{I}^{[K_{J_i}]_{i\in I}}_{[J_i]_{i\in I}}:  \TS^{\{K_{J_i}\}_{i\in I}}\left(\mathop\boxtimes_{i\in I}\Delta^{ K_{J_i}/J_i}_*M_{J_i}\right)\rightarrow \Delta^{K/J}_*\TS^{\{J_i\}_{i\in I}}\left(\mathop\boxtimes_{i\in I}M_{J_i}\right)
  \]
  to be the composition $c^{[K_{J_i}]_{i\in I}}_{[J_i]_{i\in I}}\circ v^{[K_{J_i}]_{i\in I}}_{[J_i]_{i\in I}}$.
\end{defn}
