   &\underset{\cref{OperadLem}-(1)}{=}\Delta^{K/I}_*\mu_I\circ \Delta^{K/J}_*\mathbf{I}^{[J_i]_{i\in I}}_{[\{i\}]_{i\in I}}\circ \underline{\Delta^{K/J}_*\left(\mathop\boxtimes_{i\in I}\mu_{J_i}\right)\circ \mathbf{I}^{[K_{J_i}]_{i\in I}}_{[J_i]_{i\in I}}}\circ\mathop\boxtimes_{i\in I}\mathbf{I}^{[K_j]_{j\in J_i}}_{[\{j\}]_{j\in J_i}}\circ \left(\mathop\boxtimes_{j\in J}\mu_{K_j}\right)\\
   &\underset{ \cref{OperadLem}- (2)}{=}\Delta^{K/I}_*\mu_I\circ \underline{\Delta^{K/J}_*\mathbf{I}^{[J_i]_{i\in I}}_{[\{i\}]_{i\in I}}\circ \mathbf{I}^{[K_{J_i}]_{i\in I}}_{[J_i]_{i\in I}}}\circ\left(\mathop\boxtimes_{i\in I}\Delta^{K_{J_i}/J_i}_*\mu_{J_i}\right)\circ\mathop\boxtimes_{i\in I}\mathbf{I}^{[K_j]_{j\in J_i}}_{[\{j\}]_{j\in J_i}}\circ \left(\mathop\boxtimes_{j\in J}\mu_{K_j}\right)\\
    &\underset{\cref{OperadLem}-(3)}{=}\Delta^{K/I}_*\mu_I\circ \mathbf{I}^{[K_{J_i}]_{i\in I}}_{[\{i\}]_{i\in I}}\circ\left(\mathop\boxtimes_{i\in I}\Delta^{K_{J_i}/J_i}_*\mu_{J_i}\right)\circ\mathop\boxtimes_{i\in I}\mathbf{I}^{[K_j]_{j\in J_i}}_{[\{j\}]_{j\in J_i}}\circ \left(\mathop\boxtimes_{j\in J}\mu_{K_j}\right)\\
    &=\Delta^{K/I}_*\mu_I\circ \mathbf{I}^{[K_{J_i}]_{i\in I}}_{[\{i\}]_{i\in I}}\circ\left(\mathop\boxtimes_{i\in I}\Delta^{K_{J_i}/J_i}_*\mu_{J_i}\circ\mathbf{I}^{[K_j]_{j\in J_i}}_{[\{j\}]_{j\in J_i}}\circ \left(\mathop\boxtimes_{j\in J_i}\mu_{K_j}\right)\right)\\
    &=\gamma\left(\mu_{I}\otimes\left(\otimes^{i\in I}\gamma\left(\mu_{J_i}\otimes (\otimes^{j\in J_i}\mu_{K_j})\right)\right)\right),
\end{align*}
which is the required associativity property of the composition map $\gamma$.


\section{Propagators and Arnold relations}\label{sec: arnold relations}
In this section we introduce elements
\[ \Prop_{ij}\in \TS_{\AA^n}^k \simeq R\Gamma(\Conf_k(\AA^n),\O) \]
in cohomological degree $n-1$, called \dfn{propagators}. They generate nontrivial cohomology classes
\be [\Prop_{ij}] \in H(\TS_{\AA^n}^k) \cong H(\Conf_k(\AA^n),\O).\nn\ee
We shall show that these cohomology classes obey (a natural analog of) the \dfn{Arnold relations}; see \cref{thm: arnold} below.
Recall that the usual Arnold relations are the identities
\be \frac1{z_{ij} z_{j\ell}} + \frac1{z_{j\ell} z_{\ell i}} + \frac1{z_{\ell i} z_{ij}} = 0, \qquad 1\leq i<j<\ell\leq k, \label{eq: arnold relations}\ee
which hold in the commutative algebra of global sections of the structure sheaf over the configuration space of $k$ points in one dimension,
\be \kk\left[z_1,\dots,z_k\right]\left[\prod\ijk \frac1 {z_{ij}}\right]= \Gamma(\Conf_k(\AA^1),\O) .\nn\ee
Here, as throughout, we continue to %write $z_1,\dots,z_k$ for coordinates on $\AA^k$, and to
use the abbreviation $z_{ij} := z_i - z_j$.


%\subsection{The volume form}
