\subsection{Proof of \cref{thm: cohFin}}\label{sec: proof of thm cohFin}
Our general strategy is inspired by \cite{CLM}: we shall consider a ``relative'' version of the complex in which all but one of the points are ``fixed'', leaving only one ``moving'' point, labelled $*$. This relative complex is sufficiently simple that its cohomology can be computed directly. Then we compute the cohomology of the original complex using induction and a spectral sequence.

Recall from \cref{sec: gens and rels for TS} the definition of $\TS_{\AA^n}^{I,E}$ for a finite set $I$ of vertices and $E\subset I^{[2]}/S_2$ of undirected edges. Given a set of directed edges $E\subset I\two$, we shall write
$\TS_{\AA^n}^{I,E} := \TS_{\AA^n}^{I,(E\cup \sigma E)/S_2}$,
where $S_2 = \{\id, \sigma\}$.

%We shall compute the cohomology of $\TS_{\AA^n}^{I} = \TS_{\AA^n}^{I,I\two}$ inductively by adding vertices.

We begin with the simple case of two points $\{i,*\}$ and one edge $e = (i,*)$. Notice that the differential $\dd$ on $\TS_{\AA^n}^{\{i,\ast\},\{(i,\ast)\}}$ is
$$
\dd_{(i,\ast)}=\sum_{r=1}^n \dd u_{i\ast}^r \frac{\del}{\del u^r_{i\ast}} .
$$
\begin{lem} There is an isomorphism of graded $\D_{(\AA^n)^{\{i,*\}}}$-modules
    \label{lem: cohMin}
    \begin{align*}
        \Coh_{\dd_{(i,\ast)}}(\TS_{\AA^n}^{\{i,\ast\},\{(i,\ast)\}})\cong \mathbf{H}_{\AA^n}^{\{i\}\smile\{\ast\}}.
    \end{align*}
\end{lem}
\begin{proof}
For $S\subset \{1,\dots,n\}$ consider the algebra $\Omega_S^\bul(\triangle_{n-1})=\{\tau \in   \Omega^\bul(\triangle_{n-1}) : \tau\vert_{\cap_{s\in S}(u^s=0)}=0\}\nn$ of polynomial differential forms on the simplex $\triangle_{n-1}$ vanishing on boundaries along directions $s\in S$. It is standard that
    \begin{align*}
        \Coh^p(\Omega^\bul_S(\triangle_{n-1}))=\left.
        \begin{cases}
            \kk, & \text{for $S=\emptyset$ and $p=0$} \\
            \kk [\Vol(\triangle_{n-1})], & \text{for $S=\{1,\dots,n\}$ and $p=n-1$} \\
             0, & \text{else},
        \end{cases}
        \right.
    \end{align*}
where $\Vol(\triangle_{n-1})_{ij} := (-1)^n\dd u^1_{ij} \dd u^2_{ij} \dots \dd u^{n-1}_{ij}$.
See for example \cite[Lemma 9.5]{GriffithsMorgan}

Now note that (since $z_i^r=z^r_\ast+(z_i^r-z^r_\ast)$) we have
    \begin{align*}
        \TS_{\AA^n}^{\{i,\ast\},\{(i,\ast)\}}
        &= \{\tau \in  \kk[z_\ast^r,(z_i^r-z_\ast^r)^{\pm 1}]^{1\leq r\leq n}\ox\Omega(\triangle_{n-1})\nn\\
        &\qquad: \tau|_{u^r_{i\ast} =0} \text{ regular in $(z_i^r-z_\ast^r)$, for $1\leq r\leq n$}\}.
    \end{align*}
As a dg vector space,
\be \TS_{\AA^n}^{\{i,\ast\},\{(i,\ast)\}} \cong \oplus_{f}\Omega_{S_f}^\bul(\triangle_{n-1})\nn\ee where $f$ runs over monic  monomials in $\kk[z_\ast^r,(z_i^r-z_\ast^r)^{\pm1}]^{1\leq r\leq n}$ and $S_f:=\{s\in\{1,\dots,n\} : f \text{ singular in $(z_i^s-z_\ast^s)$}\}$.
    %The result then follows due to the following observation:
    %Every primitive monomial $f$ with $I_f=\{1,\dots,n\}$ is of the form $\prod_{r=1}^n\frac{1}{(z_l^r-z_{k+1}^r)^{n'_r}}\prod_{i=1}^{k+1}(z_i^r)^{m'_{r,i}}$ for $n'_r>0$ and $m'_{r,i}\geq 0$. Using $z_i^r=z^r_{k+1}+(z_i^r-z^r_{k+1})$ it is clear that $f$ can be written as a linear combination of elements of the form $\prod_{r=1}^n\frac{(z_{k+1}^r)^{m_r}}{(z_l^r-z_{k+1}^r)^{n_r}}$ for $n_r>0$ and $m_r\geq 0$ and elements $\wt f$ with $I_{\wt f}\neq \{1,\dots,n\}$.
   The monomials $f$ such that $S_f=\{1,\dots,n\}$ are of the form
\be (z_*^1)^{m_1}\dots (z_*^n)^{m_n} \left(\frac{\del}{\del z^1_{*}}\right)^{p_1} \dots \left(\frac{\del}{\del z^n_{*}}\right)^{p_n} \prod_{r=1}^n \frac1 {z^r_i-z^r_*} ,\qquad m_1,\dots,m_n,p_1,\dots,p_n\geq 0.\nn\ee
Thus, with the identification
\be\label{propIdentify} \Prop_{i*} \simeq  \left(\prod_{r=1}^n \frac1 {z^r_i-z^r_*}\right)[\Vol(\triangle_{n-1})], \ee
we have the result.
    %This establishes the proof.
\end{proof}
Next we note that
\be\label{decompTS}\TS_{\AA^n}^{I\sqcup\{\ast\},I\times\{\ast\}} \cong \bigotimes_{i\in I}\TS_{\AA^n}^{\{i,\ast\},\{(i,\ast)\}}.\ee
Here the tensor product on the right-hand side is of modules over $\O_{\AA^n}=\kk[z_*^r]^{1\leq r\leq n}$. Note that both $\TS_{\AA^n}^{\{i,*\},\{(i,*)\}}$ and its cohomology $\mathbf{H}_{\AA^n}^{\{i\}\smile\{\ast\}}$ are projective (in fact, free) over $\O_{\AA^n}=\kk[z_*^r]^{1\leq r\leq n}$. Therefore by the K\"unneth theorem \cite[Theorem 3.6.3]{Weibel} we obtain that
\be\label{decompTS2} \Coh_{\dd_{I\times\{\ast\}}}(\TS_{\AA^n}^{I\sqcup\{\ast\},I\times\{\ast\}}) \cong \bigotimes_{i\in I}\Coh(\TS_{\AA^n}^{\{i,\ast\},\{(i,\ast)\}}) = \bigotimes_{i\in I}  \mathbf{H}_{\AA^n}^{\{i\}\smile\{\ast\}}\nn\ee
as an isomorphism of graded vector spaces. This isomorphism is compatible with $\mathcal{D}_{(\mathbb{A}^{n})^{I\sqcup \{\ast\}}}$-structure. Here we have introduced an explicit notation for the differential
\be \dd_{I\times\{\ast\}} = \sum_{1\leq i\leq k} \sum_{r=1}^n \dd u_{i\ast}^r \frac{\del}{\del u^r_{i\ast}} \nn\ee
of the complex $\TS_{\AA^n}^{I\sqcup\{\ast\},I\times\{\ast\}}$.

At this point, roughly speaking, what we have shown is that the cohomology $\Coh_{\dd_{I\times\{*\}}}(\TS_{\AA^n}^{I\sqcup\{\ast\},I\times\{\ast\}})$ is generated by \emph{products} of propagators $\Prop_{i*}$ (and their derivatives). The next result shows that when we change base (dg) ring and work over $\TS_{\AA^n}^{I}$, then the cohomology of $\dd_{I\times \{*\}}$ is \emph{linearly} generated by such propagators (and their derivatives).
\begin{lem}\label{lem: isom}
There is an isomorphism of graded $\mathcal{D}_{(\mathbb{A}^{n})^{I\sqcup \{\ast\}}}$-modules
\begin{align}           \Coh_{\dd_{I\times\{\ast\}}}\left(\TS_{\AA^n}^{I,I^{[2]}}\ox_{\O_{(\AA^n)^{I}}} \TS_{\AA^n}^{I\sqcup\{\ast\},I\times\{\ast\}}\right)\cong\TS_{\AA^n}^{I,I^{[2]}} \ox_{\O_{(\AA^n)^{I}}} \mathbf{H}_{\AA^n}^{I\smile\{\ast\}}.
\end{align}
\end{lem}
\begin{proof}
%By \cref{cohInterm} $\Coh_{\dd_{I\times\{\ast\}}}\left( \TS_{\AA^n}^{I\sqcup\{\ast\},I\times\{\ast\}}\right)$ consists of products of elements in $\kk[z^r_\ast,(z_i^r-z^r_\ast)]^{1\leq r\leq n}$ respectively $\\Prop_{\AA^n}^{i,\ast}$ for $i\in I$.
We have that $\TS_{\AA^n}^{I,I^{[2]}}$ is flat over $\ox_{\O_{(\AA^n)^{I}}} $ (by \cref{thm: TSIE gens and rels} together with \cref{lem: FlatE}). Hence, we find using \cref{decompTS} that
\begin{align*}
    \Coh_{\dd_{I\times\{\ast\}}}\left(\TS_{\AA^n}^{I,I^{[2]}} \ox_{\O_{(\AA^n)^{I}}} \TS_{\AA^n}^{I\sqcup\{\ast\},I\times\{\ast\}}\right)
&\cong \TS_{\AA^n}^{I,I^{[2]}} \ox_{\O_{(\AA^n)^{I}}} \Coh_{\dd_{I\times\{\ast\}}}\left( \TS_{\AA^n}^{I\sqcup\{\ast\},I\times\{\ast\}}\right)\nn\\
&\cong \TS_{\AA^n}^{I,I^{[2]}} \ox_{\O_{(\AA^n)^{I}}}  \bigotimes_{i\in I} \mathbf{H}_{\AA^n}^{\{i\}\smile\{\ast\}} \nn
\end{align*}
The result follows if we can show that, in this graded ring, all products of the form $[\Prop^{p_1,\dots,p_n}_{i\ast}][\Prop^{p'_1,\dots,p'_n}_{j\ast}]$ are zero for $i\neq j\in I$.
Indeed, we have that
\begin{align*}
    &1\ox[\Prop_{i\ast}][\Prop_{j\ast}]=1\ox[\Prop_{i\ast}\Prop_{j\ast}]\\
    &\qquad\qquad=\sum_{r=1}^nu_{ij}^r\ox[\Prop_{i\ast}\Prop_{j\ast}]=\sum_{r=1}^nu_{ij}^r\frac{z^r_{ij}}{z^r_{ij}}\ox[\Prop_{i\ast}\Prop_{j\ast}]\\
    &\qquad\qquad=\sum_{r=1}^n\frac{u_{ij}^r}{z^r_{ij}}\ox[z^r_{ij}\Prop_{i\ast}\Prop_{j\ast}]\\
    &\qquad\qquad=\sum_{r=1}^n\frac{u_{ij}^r}{z^r_{ij}}\ox[z^r_{i\ast}\Prop_{i\ast}\cdot\Prop_{j\ast}]-\sum_{r=1}^n\frac{u_{ij}^r}{z^r_{ij}}\ox[\Prop_{i\ast}\cdot z^r_{j\ast}\Prop_{j\ast}]=0.
\end{align*}


The same argument generalizes to arbitrary elements in $\mathbf{H}_{\AA^n}^{\{i\}\smile\{\ast\}}$ and $\mathbf{H}_{\AA^n}^{\{j\}\smile\{\ast\}}$ of degree $n-1$ if we replace $\frac{z^r_{ij}}{z^r_{ij}}\to (\frac{z^r_{ij}}{z^r_{ij}})^N$ for $N$ sufficiently large.
\end{proof}


Next we observe that (by \cref{thm: TS gens and rels})
\be  \TS_{\AA^n}^{I\sqcup\{\ast\}} \cong \TS_{\AA^n}^{I} \ox_{\O_{(\AA^n)^I}} \mathbf{Q}^I_{\AA^n},\quad \mathbf{Q}^I_{\AA^n}:=\TS_{\AA^n}^{I\sqcup \{\ast\}, I \times \{\ast\}}.\nn\ee
In this way $\TS_{\AA^n}^{I\sqcup\{\ast\}}$ is a bigraded $\kk$-vector space. There is a corresponding decomposition of the differential $\dd$ on $\TS_{\AA^n}^{I\sqcup\{\ast\}}$ as a sum of two anticommuting differentials,
\be \dd_{\TS} = \dd'_{\mathbf{P}} + \dd_{\mathbf{Q}},\nn\ee
\be \dd'_{\mathbf{P}} = \sum_{1\leq i<j\leq k} \sum_{r=1}^n \dd u_{ij}^r \frac{\del}{\del u^r_{ij}}, \qquad
