\begin{rem}
 One may expect to use the K\"unneth formula \cite[Theorem 3.6.3]{Weibel}. However, although $\mathbf{P}^I_{\AA^n},\mathbf{Q}^I_{\AA^n}$ are complexes of flat $\mathcal{O}_{(\mathbb{A}^n)^I}$-module, the modules of coboundary $d_{\mathbf{P}}(\mathbf{P}^{I,p}_{\AA^n}),d_{\mathbf{Q}}(\mathbf{Q}^{I,q}_{\AA^n})$ are not flat. Thus, the K\"unneth formula does not apply directly.
\end{rem}

\subsection{Translation invariant version}\label{sec:TransInv-Coh}
Later in this paper, we will use a translation invariant version of \cref{thm: cohFin}.  If we choose a base point $\bp=1\in I=\{1,\dots,k\}$, then we can define the translation invariant subcomplex of $\TS_{\AA^n}^{I}$
\begin{align} \TS_{\AA^n,\circ}^{I}&=\TS_{\AA^n,\circ}^{I,\bul}  := \bigl\{ \tau \in
 \kk[(z^r_i-z^r_{\circ}),(z^r_j-z^r_\ell)^{-1}]^{1\leq r\leq n}_{{i\in I- \{\circ\}, j\neq \ell\in I}} \ox \Omega^\bul(\triangle_{n-1}^{\times \binom k 2}) \\
& \quad :          \text{$\tau|_{u^r_{ij}=0}$ is regular in $(z^r_i-z^r_j)$,  for $1\leq r\leq n$ and $i\neq j\in I$} \bigr\}. \nn
\end{align}

By an argument that parallels to the proof of \cref{thm: TS gens and rels}, there is an isomorphism of commutative dg algebras
\be \TS^I_{\AA^n,\circ} \cong \mathbf{B}^I_{\mathbb{A}^n,\circ} :=\directlim_{m\geq 0}\frac{\kk\left[ (z^r_i-z^r_{\circ}), \frac{u^r_{j\ell}}{(z^r_j-z^r_\ell)^m}, \frac{\dd u^r_{j\ell}}{(z^r_j-z^r_\ell)^m}, \right]^{1\leq r\leq n}_{i\in I-\{\circ\},j\neq l\in I}}{\langle \sum\limits_{r=1}^{n} u^r_{ij} -1, \sum\limits_{r=1}^{n} \dd u^r_{ij} \rangle\ijk} \nn. \ee

Then
$$
\TS_{\AA^n}^{I}\cong \mathbf{B}_{\AA^n}^{I}=\mathbf{k}[z^r_{\circ}]^{1\leq r\leq n}\otimes_{\mathbf{k}}\mathbf{B}_{\AA^n,\circ}^{I}\cong \mathbf{k}[z^r_{\circ}]^{1\leq r\leq n}\otimes_{\mathbf{k}}\TS_{\AA^n,\circ}^{I}.
$$
Thus the cohomology of $\TS_{\AA^n}^{I}$ can be identified as the cohomology of the translation invariant part with a tensor factor $\mathbf{k}[z^r_{\circ}]^{1\leq r\leq n}$
\be
 \Coh_{\dd_{\TS}}(\TS_{\AA^n}^{I}) \cong  \mathbf{k}[z^r_{\circ}]^{1\leq r\leq n}\otimes_{\mathbf{k}} \Coh_{\dd_{\TS}}(\TS_{\AA^n,\circ}^{I}) .\nn\ee
For $I_l=\{1=\circ,\dots,l\},l<k$, we have
 \be
 \mathbf{H}_{\AA^n}^{I_l\smile\{l+1\}}=\mathbf{k}[z^r_{\circ}]^{1\leq r\leq n}\otimes_{\mathbf{k}} \mathbf{H}_{\AA^n,\circ}^{I_l\smile\{l+1\}}
 \nn\ee
 where\be\mathbf{H}_{\AA^n,\circ}^{I_l\smile\{l+1\}}=\mathcal{O}_{(\mathbb{A}^n)^{I_l\setminus\{\circ\}\sqcup\{l+1\}}}\oplus\bigoplus^{}_{i\in I_l,p_1,\dots,p_n\geq 0}\mathcal{O}_{(\mathbb{A}^n)^{I_l\setminus\{\circ\}}}\cdot\Prop_{i\ast}^{p_1,\dots,p_n},\ast=l+1,\nn\ee
 \be\mathcal{O}_{(\mathbb{A}^n)^{I_l\setminus\{\circ\}}}\cong \mathbf{k}[(z^r_i-z^r_{\circ})]_{i\in I_l\setminus\{\circ\}}^{1\leq r\leq n}.\nn\ee

With the above notation, we have the following theorem.
\begin{thm}
\label{thm: cohFinTransInv}
 We have the isomorphism
\begin{align} \Coh_{\dd_{\TS}}(\TS_{\AA^n,\circ}^{I}) &\cong \mathbf{H}_{\AA^n,\circ}^{I_1\smile\{2\}} \ox_{\O_{(\AA^n)^{I_2\setminus\{\circ\}}}} \mathbf{H}_{\AA^n,\circ}^{I_2\smile\{3\}} \ox_{\O_{(\AA^n)^{I_3\setminus\{\circ\}}}} \dots%\nn\\&\qquad\qquad  \dots
\ox_{\O_{(\AA^n)^{I_{k-1}\setminus\{\circ\}}}} \mathbf{H}_{\AA^n,\circ}^{I_{k-1}\smile\{k\}}\nn\end{align}
of graded modules over $\kk[(z_i^r-z_\circ^r),\partial_{z^r_i},\partial_{z^r_\circ}]_{i\in I\setminus\{\circ\}}^{1\leq r\leq n}$.
\end{thm}
\begin{proof}
    The same argument as in the proof of \cref{thm: cohFin}.
\end{proof}
\begin{cor}\label{cor:TransInvBasis}
    Within the same notation in \cref{cor: basis}, we have the following basis of  $\Coh_{\dd_{\TS}}(\TS_{\AA^n,\circ}^{I})$
    $$
        \left(\prod_{i\in  I_{J,(\ell_j)}}\prod_{r=1}^n(z_{i}^r-z_{k}^r)^{n_{r,i}}\right)
        \left(\prod_{j\in J}[\Prop_{\ell_jj}^{m_{1,j},\dots,m_{n,j}}]\right).
    $$
\end{cor}
