\begin{prop}[Translation invariant description of chiral operad]\label{prop: translation invariant Pch}
We have
\begin{align}
\P^{ch}_{\AA^n,\bul}(k)&:=\Hom_{\DAAnk}\left(\TS_{\AA^n}^{k,\bul-(n-1)}((\oms)^{\boxtimes k}),\Delta_*\om\right)\nn\\
&\cong\Hom_{\kk[z^s_{v\bp},\del_{z^s_v}]^{1\leq s\leq n}_{v\in I\setminus\{\bp\}}}\left(\TS_{{\AA^n},\basepoint}^{k,\bul-(n-1)}((\oms)^{\boxtimes k}),\dd\zz\ox \kk[\lambda^r_v]^{1\leq r\leq n}_{v\in I\setminus\{\bp\}}\right),\nn
\end{align}
where the right $\kk[z^s_{v\bp},\del_{z^s_v}]^{1\leq s\leq n}_{v\in I\setminus\{\bp\}}$-module structure on $\dd\zz\ox \kk[\lambda_v]$ is given by
\[ \dd\zz\cdot z^s_{v\bp}=0,\qquad \dd\zz\cdot \del_{z^s_v}=d\mathbf{z}\cdot\lambda^s_v.\]
\end{prop}
\begin{proof}
Recall that in \cref{sec: shifted canonical bundle} we have
\begin{equation}
\Delta_*\om=\kk[z^r]^{1\leq r\leq n} \dd\zz\ox_{\kk[\lambda^r]^{1\leq r\leq n}}\kk[\lambda^r_i]^{1\leq r\leq n}_{i\in I}
\label{DAn}\end{equation}
where $\kk[\lambda^r]^{1\leq r\leq n}$ acts on $\kk[\lambda^r]^{1\leq r\leq n}_{i\in I}$  as $\lambda^r \cdot p := \sum\limits_{i\in I} \lambda^r_i p$ and acts on $\kk[z^r]^{1\leq r\leq n} \dd\zz$ as $p(z) \dd\zz \cdot \lambda^r := -\del_{z^r} p(z)\cdot\dd\zz$.
Here the $z^1,\dots,z^n$ are the coordinates on the main-diagonal copy of $\AA^n$.
Relative to our choice of base point $\bp\in I$, we have an isomorphism
\begin{equation} \Delta_*
\om
\cong \kk[z^r]^{1\leq r\leq n}  \dd\zz \ox_\kk \kk[\lambda^r_v]^{1\leq r\leq n}_{v\in I \setminus \{\bp\}}. \nn\end{equation}
Since
\(\TS_{\AA^n}^{k,\bul}=\kk[z^s_\bp]^{1\leq s\leq n}\ox_\kk\TS_{\AA^n,\basepoint}^{k,\bul},\)
we certainly have the map
\begin{align} &\Hom_{\DAAnk}\left(\TS_{\AA^n}^{k,\bul-(n-1)}((\oms)^{\boxtimes k}),\Delta_*\om\right)\nn\\
&\rightarrow\Hom_{\kk[z^s_{v\bp},\del_{z^s_v}]^{1\leq s\leq n}_{v\in I\setminus\{\bp\}}}\left(\TS_{{\AA^n},\basepoint}^{k,\bul-(n-1)}((\oms)^{\boxtimes k}),\kk[z^r]^{1\leq r\leq n}%\cdot
 \dd\zz\ox_\kk\kk[\lambda^r_i]^{1\leq r\leq n}_{i\in I\setminus\{\bp\}}\right).
\nn\end{align}
We first want to show that for any chiral operation $\mu$ and any $\alpha \in \TS_{{\AA^n},\basepoint}^{k,\bul-(n-1)}((\oms)^{\boxtimes k})$, we in fact have
\begin{equation} \mu(\alpha)\in \dd\zz\ox_\kk\kk[\lambda^r_i]^{1\leq r\leq n}_{i\in I\setminus\{\bp\}}\nn\end{equation}
with no remaining dependence on the coordinates $z^r$. Suppose that
\begin{equation} \mu(\alpha)=\sum_{\mathbf{m}} f_{\mathbf{m}}(z^1,\dots,z^n) \dd\zz\ox \lambda^{\mathbf{m}}.
\nn\end{equation}
Then for every $s$, since $\alpha \cdot \sum\limits_{i\in I} \del_{z_i^s} = 0$, we have
\begin{align*}
 0  =\mu(\alpha\cdot \sum_{i\in I}\del_{z^s_i} )=\mu(\alpha )\cdot \sum_{i\in I}\del_{z^s_i} &=\left( \sum_{\mathbf{m}} f_{\mathbf{m}}(z^1,\dots,z^n) \dd\zz\ox \lambda^{\mathbf{m}}\right) \cdot \sum_{i\in I}\del_{z^s_i} \nn\\
&= - \sum_{\mathbf{m}} \left(\del_{z^s} f_{\mathbf{m}}(z^1,\dots,z^n)\right) \dd\zz\ox \lambda^{\mathbf{m}}.
\end{align*}
This implies that the polynomial coefficients $f_{\mathbf{m}}(z^1,\dots,z^n) $ are indeed constants.
Thus, we in fact have a map
\begin{align} &\Hom_{\DAAnk}\left(\TS_{\AA^n}^{k,\bul-(n-1)}((\oms)^{\boxtimes k}),\Delta_*\om\right)\nn\\
&\rightarrow\Hom_{\kk[z^s_{v\bp},\del_{z^s_v}]^{1\leq s\leq n}_{v\in I\setminus\{\bp\}}}\left(\TS_{{\AA^n},\basepoint}^{k,\bul-(n-1)}((\oms)^{\boxtimes k}), \dd\zz\ox_\kk\kk[\lambda^r_i]^{1\leq r\leq n}_{i\in I\setminus\{\bp\}}\right).
\nn\end{align}
To complete the proof, we must show it is invertible. We shall construct the inverse.
Suppose that we have \[\mu^{\bp}\in \Hom_{\kk[z^s_{v\bp},\del_{z^s_v}]^{1\leq s\leq n}_{v\in I\setminus\{\bp\}}}\left(\TS_{\AA^n,\basepoint}^{k,\bul-(n-1)}((\oms)^{\boxtimes k}), \dd\zz\ox\kk[\lambda^s_v]^{1\leq s\leq n}_{v\in I\setminus\{\bp\}}\right).\]
Using again the fact that $\TS_{\AA^n}^{k,\bul}=\kk[z^s_\bp]^{1\leq s\leq n}\ox_\kk\TS_{\AA^n,\basepoint}^{k,\bul}$. If $\mu$ is to be a $\D$-module map, we certainly must have
\[\mu(f(z^1_\bp,\dots,z^n_\bp)\cdot \alpha):= f(z^1,\dots,z^n)\mu^{\bp}(\alpha).\]
We check that
  \begin{align*}
    \mu\left((f(z_\bp)\cdot \alpha)\del_{z^s_\bp}\right) &=  \mu\left(-(\del_{z^s_\bp}f(z_\bp))\cdot \alpha\right)+    \mu\left(f(z_\bp)\cdot (\alpha\del_{z^s_\bp})\right)\\
    &= -\left(\del_{z^s}f(z)\right)\cdot \mu^{\bp}(\alpha)- f(z)\cdot \mu^{\bp}(\alpha\cdot\sum_{v\in I\setminus\{\bp\}}\del_{z^s_v}) \\
     & =    \mu\left((f(z_\bp)\cdot \alpha)\right)\del_{z^s_\bp},
  \end{align*}
and this suffices to establish that $\mu$ is indeed a $\D$-module map, i.e. \[\mu \in \Hom_{\DAAnk}\left(\TS_{\AA^n}^{k,\bul-(n-1)}((\oms)^{\boxtimes k}),\Delta_*\om\right).\] It is by construction a preimage of $\mu^\bp$.
\end{proof}

In view of \cref{prop: translation invariant Pch}, to prove \cref{prop: Injectivity} it suffices to prove the following translation invariant analog. (It is actually this version we shall ultimately use in the proof of \cref{thm: ChiralIsoLie}.)
\begin{prop}[Injectivity property, translation invariant version]\label{prop: translation invariant injectivity}
If
\[\mu\in \Hom_{\kk[z^s_{v\bp},\del_{z^s_v}]^{1\leq s\leq n}_{v\in I\setminus\{\bp\}}}\left(H_{\ddts}\left(\TS_{\AA^n,\basepoint}^{k,p-(n-1)}((\oms)^{\boxtimes k})\right),\dd\zz\ox\kk[\lambda^s_v]^{1\leq s\leq n}_{v\in I\setminus\{\bp\}}\right)\]
is such that
    \[
    \mu|_{\ker(\ddts)}=0,
    \]
    then there exists
\[ \tilde{\mu}\in \Hom_{\kk[z^s_{v\bp},\del_{z^s_v}]^{1\leq s\leq n}_{v\in I\setminus\{\bp\}}}\left(H_{\ddts}\left(\TS_{\AA^n,\basepoint}^{k,p+1-(n-1)}((\oms)^{\boxtimes k})\right),\dd\zz\ox\kk[\lambda^s_v]^{1\leq s\leq n}_{v\in I\setminus\{\bp\}}\right)\]
such that
    \[
\tilde{\mu}\circ \ddts =\mu.
    \]
Equivalently, the following induced map from the homology is injective:
  \begin{align}
 &H^p_{\dd_{\P}}\left(  \Hom_{\kk[z^s_{v\bp},\del_{z^s_v}]^{1\leq s\leq n}_{v\in I\setminus\{\bp\}}}\left(\TS_{\AA^n,\basepoint}^{k,\bul-(n-1)}((\oms)^{\boxtimes k}),\dd\zz\ox\kk[\lambda^s_v]^{1\leq s\leq n}_{v\in I\setminus\{\bp\}}\right)\right)\nn\\
 &\quad\rightarrow\Hom_{\kk[z^s_{v\bp},\del_{z^s_v}]^{1\leq s\leq n}_{v\in I\setminus\{\bp\}}}\left(H^p_{\ddts}\left(\TS_{\AA^n,\basepoint}^{k,\bul-(n-1)}((\oms)^{\boxtimes k})\right),\dd\zz\ox\kk[\lambda^s_v]^{1\leq s\leq n}_{v\in I\setminus\{\bp\}}\right).\quad p\in  \ZZ.
  \nn\end{align}
\end{prop}
To prove this we require various lemmas.


We first introduce a $\kk^{\times}$-action on the coordinates $\rho_t:z^s_i\rightarrow t\cdot z^s_i$, $t\in \kk^{\times}$. We extend this action to other variables as follows
 \[
 \rho_t\left(\dd\zz\shifted_i\right)=t^{n}\cdot \dd\zz\shifted_i,\quad \rho_t\left(\lambda^s_v\right)=t^{-1}\cdot \lambda^s_v.
 \]
We say $\alpha \in \TS_{{\AA^n},\basepoint}^{k,\bul}((\oms)^{\boxtimes k})$ is of homogeneous $z$-degree $d$ if $\rho_t(\alpha)=t^d\cdot \alpha$.
\begin{prop}\label{prop: Scaling}
Chiral operations preserve the homogeneous $z$-degree.
That is,
\[ \mu\left(\rho_t(\alpha (\dd\zz\shifted)^I)\right)=  \rho_t\left(\mu(\alpha (\dd\zz\shifted)^I)\right),\]
for all $\mu\in\P^{ch}_{\AA^n,\bul}(I)$.
\end{prop}
\begin{proof}
Consider the Euler vector field
$\mathbf{E} :=\sum\limits_{v\in I}\sum\limits^n_{s=1}z^s_{v}\del_{z^s_v}$.
Since $\mathbf{E} \in \DAAnk$, chiral operations are $\mathbf{E}$-equivariant by definition:
$\mu(\alpha) \cdot \mathbf E = \mu(\alpha\cdot \mathbf E)$.
It is enough to note that eigenvectors of $\mathbf E$ with eigenvalue $d$ are precisely elements of homogeneous $z$-degree $-d$.
\end{proof}
