We compute the action of the Euler vector field $\mathbf{E}_\bp$ to get
  \begin{align*}
    \mu((\alpha (\dd\zz\shifted)^I)\cdot \mathbf{E}_\bp)   &=    \mu(\alpha (\dd\zz\shifted)^I)\cdot\mathbf{E}_\bp  \\
     & =\dd\zz\shifted\cdot (\sum_{v\in I\setminus\{\bp\}}\sum^n_{s=1}\lambda^s_{v}\del_{\lambda^s_v})(f_0+f_1+\cdots+f_N)\\
     &=\dd\zz\shifted\cdot(0\cdot f_0+1\cdot f_1+2\cdot f_2+\cdots+N\cdot f_N).
  \end{align*}
On the other hand,
  \begin{align*}
    \mu((\alpha (\dd\zz\shifted)^I)\cdot \mathbf{E}_\bp) &=\mu(-(\sum_{v\in I\setminus\{\bp\}}\sum^n_{s=1}\del_{z^s_v}z^s_{v\bp}\alpha)\cdot (\dd\zz\shifted)^I)  \\
     &= \mu((d-(k-1)(n-1))\alpha (\dd\zz\shifted)^I)\\
     &=(d-(k-1)(n-1))\cdot \dd\zz\shifted\cdot (f_0+f_1+\cdots+f_N).
  \end{align*}
We conclude that $\mu(\alpha (\dd\zz\shifted)^I)=0$ for $d<(k-1)(n-1)$ and
  \[
      \mu(\alpha (\dd\zz\shifted)^I)=\dd\zz\shifted\cdot f_{d-(k-1)(n-1)},\quad (k-1)(n-1)\leq d
  \]
  which is equivalent to the statement in the proposition.
  %Since $l<(k-1)(n-1)$, we get
  %\[
  %d\mathbf{z}_\bp^{\blacklozenge}\cdot (f_0+f_1+\cdots+f_N)=0.
  %\]
\end{proof}
