Now we want to argue that chiral operations are determined by their action on certain preferred elements of $\TS_{\AA^n}^{k,\bul-(n-1)}$, whose pole structures correspond to tuples of maximal trees, as follows.

Suppose we are given a directed graph $\Gamma = (V(\Gamma), E(\Gamma))$ with vertex set $V(\Gamma) = I = \{1,\dots,k\}$ and edge set $E(\Gamma) \subset V(\Gamma)\two$.
We shall write
\[ \frac{1}{(z)_{\Gamma}} :=\prod_{e\in E(\Gamma)}\frac{1}{z_e}\equiv \prod_{(i,j)\in E(\Gamma)}\frac{1}{z_i-z_j} .\]
The graph $\Gamma$ is a tree if its underlying undirected graph contains no cycles.
%; a tree $\Gamma$ is maximal if its underlying undirected graph has exactly $k-1$ edges.
Let
\[
\mathbf{Q}_{\mathbf{Tree}}^{k,p}
:=\Span_\kk\left\{\frac{F(u)}{(z^1)_{\Gamma_1}\cdots (z^n)_{\Gamma_n}} (\dd\zz\shifted)^I\in \TS_{\AA^n,\basepoint}^{k,p-(n-1)}\left((\oms)^{\boxtimes k}\right) \,\middle|\, \Gamma_1,\dots,\Gamma_n \text{ are trees}%,\frac{F(u)}{(z^1)_{\Gamma_1}\cdots (z^n)_{\Gamma_n}}\in \TS_{\AA^n,\basepoint}^{k,p}
\right\}.
\]
We have the direct sum decomposition as a $\kk$-vector space
\[\mathbf{Q}_{\mathbf{Tree}}^{k,\bul}=\mathbf{Q}_{\mTree}^{k,\bul}\oplus\mathbf{Q}_{\mathbf{Tree},<}^{k,\bul},\]
where:\begin{enumerate}[--]
\item  $\mathbf{Q}_{\mTree}^{k,p}$ is the subspace spanned by monomials such that the trees $\Gamma_1,\dots,\Gamma_n$ are maximal, i.e. $|E(\Gamma_1)/S_2|=\dots=|E(\Gamma_n)/S_2|=k-1$, and where
\item $\mathbf{Q}_{\mathbf{Tree},<}^{k,\bul}$ is the subspace spanned by monomials such that at least one of the trees is non-maximal, i.e., there exists $s$ such that $|E(\Gamma_s)/S_2|<k-1$.
\end{enumerate}
Elements of $\mathbf{Q}_{\mTree}^{k,\bul}$ are homogeneous of $z$-degree \[nk-n(k-1) = n.\] Homogeneous elements of $\mathbf{Q}_{\mathbf{Tree},<}^{k,\bul}$ have $z$-degrees $>n$.
% The Euler vector field $\mathbf{E}_\bp$ from the proof of \cref{prop: Scaling} acts on $\mathbf{Q}_{\mathbf{Tree}}^{k,\bul}$ with integer eigenvalues.
% \[ \mathbf{Q}_{\mathbf{Tree}}^{k,\bul}=\oplus^{n(k-1)}_{l=0}\mathbf{Q}_{\mathbf{Tree}}^{k,\bul}[-l]=\underbrace{\mathbf{Q}_{\mathbf{Tree}}^{k,\bul}[-n(k-1)]}_{\mathbf{Q}_{\mTree}^{k,\bul}}\oplus\underbrace{\oplus^{n(k-1)-1}_{l=0}\mathbf{Q}_{\mathbf{Tree}}^{k,\bul}[-l]}_{\mathbf{Q}_{\mathbf{Tree},<}^{k,\bul}}.
% \]
\begin{lem}\label{lem: tree less}
  As a $\kk[z^s_{v\bp},\del_{z^s_v}]^{1\leq s\leq n}_{v\in I\setminus\{\bp\}}$-module,  $\TS_{\AA^n,\basepoint}^{k,\bul-(n-1)}\left((\oms)^{\boxtimes k}\right)$ is generated by the $\kk$-vector subspace
  \[
\mathbf{Q}_{\mathbf{Tree}}^{k,\bul}=\mathbf{Q}_{\mTree}^{k,\bul}\oplus\mathbf{Q}_{\mathbf{Tree},<}^{k,\bul}\subset  \TS_{\AA^n,\basepoint}^{k,\bul-(n-1)}\left((\oms)^{\boxtimes k}\right).
  \]
Let $\TS_{\mathbf{Tree},<}^{k,\bul}$ denote the sub $\kk[z^s_{v\bp},\del_{z^s_v}]^{1\leq s\leq n}_{v\in I\setminus\{\bp\}}$-module generated by $\mathbf{Q}_{\mathbf{Tree},<}^{k,\bul}$; then, furthermore, for any $\mu\in \P^{ch}_{\AA^n,\bul}(k)$ we have
  \[
  \mu|_{\TS_{\mathbf{Tree},<}^{k,\bul}}=0,\quad\text{and}\quad \mu\left(\mathbf{Q}_{\mathbf{Tree}}^{k,\bul}\right)\subset\mathbf{k}\cdot \dd\mathbf z.
  \]

\end{lem}
\begin{proof} We shall use the algebraic description of the model from \cref{sec: gens and rels for TS} freely without further comment.
  Suppose that we have an element in $\TS_{\AA^n,\basepoint}^{k,\bul-(n-1)}\left((\oms)^{\boxtimes k}\right)$ which contains a factor
  \[
  \alpha=\frac{\varepsilon u^1_{e_1}}{(z^1_{e_1})^{l_1}}\cdots \frac{\varepsilon u^1_{e_K}}{(z^1_{e_K})^{l_K}},\quad\text{where each}\quad \varepsilon u^1_{e_r}=u^1_{e_r} \text{or}\ du^1_{e_r},
  \]
  such that the edges $(e_1,\dots,e_K)$ form a directed cycle, i.e. such that
  \[
  \sum^K_{r=1} z^1_{e_r}=0.
  \]
  Notice that
  %\[
  %\alpha=\frac{\varepsilon u^1_{e_1}}{z^1_{e_1}}\cdots \frac{\varepsilon u^1_{e_k}}{z^1_{e_k}}=\sum^k_{i=2}\frac{\varepsilon u^1_{e_1}}{(z^1_{e_1})^2}\cdots  {\varepsilon u^1_{e_i}}\cdots \frac{\varepsilon u^1_{e_k}}{z^1_{e_k}}.
  %\]
  \begin{align*}
   -\sum^K_{i=2}\frac{\varepsilon u^1_{e_1}}{(z^1_{e_1})^{l_1+1}}\cdots  \frac{\varepsilon u^1_{e_i}}{(z^1_{e_i})^{l_i-1}}\cdots \frac{\varepsilon u^1_{e_K}}{(z^1_{e_K})^{l_K}}  &=-\sum^K_{i=2}z^1_{e_i}\cdot\frac{\varepsilon u^1_{e_1}}{(z^1_{e_1})^{l_1+1}}\cdots \frac{\varepsilon u^1_{e_i}}{(z^1_{e_i})^{l_i}}\cdots \frac{\varepsilon u^1_{e_K}}{(z^1_{e_K})^{l_K}}  \\
     & =z^1_{e_1}\cdot \frac{\varepsilon u^1_{e_1}}{(z^1_{e_1})^{l_1+1}}\cdots \frac{\varepsilon u^1_{e_K}}{(z^1_{e_K})^{l_K}}=\alpha.
  \end{align*}
Repeating the same procedure to each $\frac{\varepsilon u^1_{e_1}}{(z^1_{e_1})^{l_1+1}}\cdots  \frac{\varepsilon u^1_{e_i}}{(z^1_{e_i})^{l_i-1}}\cdots \frac{\varepsilon u^1_{e_K}}{(z^1_{e_K})^{l_K}} $, we can decrease the power of $z^{1}_{e_i},2\leq i\leq K$ until one of them is zero. We repeat this procedure for other factors again until finally we have reduced the element into tree expressions.

Each such expression is in the $\kk[z^s_{v\bp},\del_{z^s_v}]^{1\leq s\leq n}_{v\in I\setminus\{\bp\}}$-module generated by $\mathbf{Q}_{\mathbf{Tree}}^{k,\bul}$. (Recall that $\del_{z^s_v}$ increases the strength of poles in $z_{jv}$, $j\in I \setminus\{v\}$.)

Now we proceed to the second part of the lemma. Since $\TS_{\mathbf{Tree},<}^{k,\bul-(n-1)}$ is the sub $\kk[z^s_{v\bp},\del_{z^s_v}]^{1\leq s\leq n}_{v\in I\setminus\{\bp\}}$-module generated by $\mathbf{Q}_{\mathbf{Tree},<}^{k,\bul}$ and $\mu$ is a map of $\kk[z^s_{v\bp},\del_{z^s_v}]^{1\leq s\leq n}_{v\in I\setminus\{\bp\}}$-modules, we only need to show that
  \[
  \mu|_{\mathbf{Q}_{\mathbf{Tree},<}^{k,\bul}%\left((\oms)^{\boxtimes k}\right)
}=0,\quad \mu\left(\mathbf{Q}_{\mathbf{Tree}}^{k,\bul}%\left((\oms)^{\boxtimes k}\right)
\right)\subset\mathbf{k}\cdot \dd\mathbf z.
  \]
This follows from Proposition \ref{prop: Scaling}.
\end{proof}

\begin{lem}\label{lem: tree tilde mu}
  Suppose that we are given a $\mu\in \P^{ch,\bul-(n-1)}_{\AA^n}(k)$ satisfying $ \mu|_{\ker(\ddts)}=0$. We can find a $\kk$-linear map
  \[ \tilde{\mu}_{\mathbf{Tree}}:\mathbf{Q}_{\mathbf{Tree}}^{k,\bul+1}%\left((\oms)^{\boxtimes k}\right)
\rightarrow\kk\cdot\dd\mathbf z
  \]
  such that
  \[
\tilde{\mu}_{\mathbf{Tree}}(\ddts\alpha)=\mu(\alpha),\quad\text{for all}\quad \alpha\in\mathbf{Q}_{\mathbf{Tree}}^{k,\bul}%((\oms)^{\boxtimes k})
  \]
and
  \[ \tilde{\mu}_{\mathbf{Tree}}|_{\mathbf{Q}_{\mathbf{Tree},<}^{k,\bul+1}%((\oms)^{\boxtimes k})
}=0.
  \]
\end{lem}
\begin{proof}
The differential $ \ddts$ decomposes into a direct sum
  \[
  \ddts=  \ddts^{\mTree}\oplus   \ddts^{\mathbf{Tree},<}\]
with
\[ \ddts^{\mTree} : \mathbf{Q}_{\mTree}^{k,p} \to \mathbf{Q}_{\mTree}^{k,p+1},\quad\text{and}\quad
 \ddts^{\mathbf{Tree,<}} : \mathbf{Q}_{\mathbf{Tree,<}}^{k,p} \to \mathbf{Q}_{\mathbf{Tree,<}}^{k,p+1}.\]
The differential $\ddts^{\mTree}$ defines a $\kk$-linear isomorphism
\[
 \mathbf{Q}_{\mTree}^{k,p}%\left((\oms)^{\boxtimes k}\right)
/\ker(  \ddts^{\mTree})\xrightarrow{\sim }\mathrm{Im}(\ddts^{\mTree})\subset \mathbf{Q}_{\mTree}^{k,p+1}.%\left((\oms)^{\boxtimes k}\right)
\]
We may pick a complement $\mathbf{U}$ such that $ \mathbf{Q}_{\mTree}^{k,p+1}=\mathrm{Im}(\ddts^{\mTree})\oplus \mathbf{U}$ as a $\kk$-vector space. Let $\pi_U: \mathbf{Q}_{\mTree}^{k,p+1} \to \mathrm{Im}(\ddts^{\mTree})$ denote the $\kk$-linear projection along $\mathbf{U}$.  Relative to the choice of $\mathbf{U}$ we then define $\tilde\mu$ to be the map
  \[
   \tilde{\mu}_{\mathbf{Tree}}:\mathbf{Q}_{\mathbf{Tree}}^{k,\bul+1}=\mathbf{Q}_{\mTree}^{k,\bul+1}\oplus\mathbf{Q}_{\mathbf{Tree},<}^{k,\bul+1} %\left((\oms)^{\boxtimes k}\right)
 %\tilde{\mu}_{\mathbf{Tree}}
\xrightarrow{\pi_U\oplus 0} \mathrm{Im}(\ddts^{\mTree})\xrightarrow{\sim}\mathbf{Q}_{\mTree}^{k,\bul}%\left((\oms)^{\boxtimes k}\right)
/\ker(  \ddts^{\mTree})\xrightarrow{\mu}\mathbf{k}\dd\mathbf z\shifted.
  \]
Then $ \tilde{\mu}_{\mathbf{Tree}}$ satisfies the property in the lemma.
\end{proof}

\begin{rem}
  In this paper, we focus on the algebraic aspect of the space of chiral operations. It is important to study the topology of the space of chiral operations (which we left for future study).
\end{rem}

\begin{lem}\label{lem: IntersectionZero}
  We have
  \[
 z^s_{v\bp}\cdot  \mathbf{Q}_{\mTree}^{k,\bul}\subset \mathbf{Q}_{\mathbf{Tree},<}^{k,\bul},\quad\text{and}\quad \mathbf{Q}_{\mTree}^{k,\bul}\cap\TS_{\mathbf{Tree},<}^{k,\bul}=0.
  \]
\end{lem}
\begin{proof}
Consider the expression
\[
 z^s_{v\bp}\cdot \frac{1}{(z^1)_{\Gamma_1}\cdots (z^n)_{\Gamma_n}}.
\]
Whenver each tree graph $\Gamma_s$ is maximal, we can write \[z^s_{v\bp}=z^{s}_{vv_1}+z^{s}_{v_1v_2}+\cdots+z^s_{v_r\bp}\] in such a way that $(v,v_1),(v_1,v_2),\dots,(v_r,\bp)$ are edges of the underlying undirected graph of $\Gamma_s$. This implies that $ z^s_{v\bp}\cdot  \mathbf{Q}_{\mTree}^{k,\bul}\subset \mathbf{Q}_{\mathbf{Tree},<}^{k,\bul}$.

For the second part, let us suppose that we have an element
\[ \alpha \in \mathbf{Q}_{\mTree}^{k,\bul}\cap\TS_{\mathbf{Tree},<}^{k,\bul}.\]
Such an element is of the form
\[
\alpha=  \sum_{(\Gamma_1,\dots,\Gamma_n)\in \mTree^{\times n}}\frac{F_{\Gamma_1,\dots,\Gamma_n}(u)}{(z^1)_{\Gamma_1}\cdots (z^n)_{\Gamma_n}}(\dd\zz\shifted)^I
  \]
where the sum is over tuples of maximal trees and where, for each such tuple, the polynomial differential form $F_{\Gamma_1,\dots,\Gamma_n}(u)$ on the polysimplex must obey boundary conditions specified by those trees, as in \cref{sec: TS def}. Now let us consider the following way of reexpressing $\alpha$. Suppose we are given any monomial
\be \frac{1}{(z)_\Gamma} = \prod_{(i,j)\in E(\Gamma)} \frac 1 {z_{ij}} \nn\ee
where $\Gamma$ is drawn from the set $\mTree$ of maximal trees.
We may always use the Arnold relations, \cref{eq: arnold relations}, and skewsymmetry, $z_{ij} = - z_{ji}$, to rewrite $\frac{1}{(z)_\Gamma}$ as a linear combination of monomials of the form $\frac{1}{(z)_{\Gamma'}}$ where $\Gamma'$ is a maximal tree of a special type: for each $i\in \{2,\dots,k\}$ there is a unique directed edge $(i,j) \in \Gamma'$ out of $i$ and its target $j$ has $j<i$.
Let $\mTree_\rightarrow$ denote this special set of maximal trees:
\begin{align} &\mTree_\rightarrow\nn\\&\qquad := \left\{ \Gamma \in \mTree\, \middle| \,E(\Gamma) = \{ (i,t(i))\}_{2\leq i\leq k} \text{ for some strictly decreasing map $t$}\right\}. \label{special trees}
\end{align}
In this way we rewrite our element $\alpha$ in the form
\[
\alpha=  \sum_{(\Gamma_1,\dots,\Gamma_n)\in \mTree_\rightarrow^{\times n}}\frac{G_{\Gamma_1,\dots,\Gamma_n}(u)}{(z^1)_{\Gamma_1}\cdots (z^n)_{\Gamma_n}} (\dd\zz\shifted)^I%\in \mathbf{Q}_{\mTree}^{k,\bul}\cap\TS_{\mathbf{Tree},<}^{k,\bul}.
  \]
(Let us stress that in this new form, it will not in general be true that each individual term in the sum obeys the defining boundary conditions of $\TS$, though of course the sum itself still does.)

Given a special maximal tree $\Gamma \in \mTree_\rightarrow$ consider the residue operation
\[\Res^z_{\Gamma}:=\res_{z^2\rightarrow z^{t(2)=1}}\circ\cdots \circ\res_{z^k\rightarrow z^{t(k)}} \]
where $t$ is the corresponding strictly decreasing function as in \cref{special trees}.
Observe that
\be \Res_{\Gamma} \frac{1}{(z)_{\Gamma'}} \dd\zz = \pm \delta_{\Gamma,\Gamma'} \quad\text{for}\quad \Gamma,\Gamma' \in \mTree_\rightarrow \nn\ee
up to a sign which is unimportant for us here.
Therefore for each tuple
$(\Gamma_1,\dots,\Gamma_n)\in \mTree_\rightarrow^{\times n}$
of such special maximal trees,
we have
%the product of such residue operators over the coordinate directions picks out the coefficients $G_{\Gamma_1,\dots,\Gamma_n}(u)$ up to a sign and $z$-degree-shift:
\be \prod_{r=1}^n \Res^{z^r}_{\Gamma_r} \alpha = \pm G_{\Gamma_1,\dots,\Gamma_n}(u)[k(n-1)]. \nn\ee
But on the other hand, notice that $\prod\limits_{r=1}^n \Res^{z^r}_{\Gamma_r}$ annihilates the space $\TS_{\mathbf{Tree},<}^{k,\bul}$. Therefore $\prod\limits_{r=1}^n \Res^{z^r}_{\Gamma_r} \alpha=0$. We conclude that $G_{\Gamma_1,\dots,\Gamma_n}(u) =0$ for each tuple $(\Gamma_1,\dots,\Gamma_n)\in \mTree_\rightarrow^{\times n}$, and hence that $\alpha = 0$. That is, $\mathbf{Q}_{\mTree}^{k,\bul}\cap\TS_{\mathbf{Tree},<}^{k,\bul}=0$, as required.
\end{proof}

Now we are ready to prove \cref{prop: translation invariant injectivity}
\begin{proof}[Proof of \cref{prop: translation invariant injectivity}]
Consider the $\kk$-linear map
\[ \tilde{\mu}_{\mathbf{Tree}}:\mathbf{Q}_{\mathbf{Tree}}^{k,\bul+1}%\left((\oms)^{\boxtimes k}\right)
\rightarrow\kk\cdot\dd\mathbf z
\]
we obtain from \cref{lem: tree tilde mu}. We shall first show that it can be uniquely extended to a well-defined $\kk[z^s_{v\bp},\del_{z^s_v}]^{1\leq s\leq n}_{v\in I\setminus\{\bp\}}$-module map
