\end{align}
where in the final equality we used the fact that $\mu|_{\TS^{k,\bul}_{\mathbf{Tree,<}}}=0$ from \cref{lem: tree less}.
This completes the proof of \cref{prop: translation invariant injectivity}, and hence, in view of \cref{prop: translation invariant Pch}, the proof of \cref{prop: Injectivity}.
\end{proof}


\subsection{Completion of the proof}\label{sec: Surjectivity}
In this section we will finish the proof of the main theorem, \cref{thm: ChiralIsoLie}.

%Recall the injective map from \cref{prop: Injectivity}.  We will first show that there is an injective map  $\Hom_{\kk[z^s_{v\bp},\del_{z^s_v}]^{1\leq s\leq n}_{v\in I \setminus\{\bp\}}\left(H_{\ddts}\left(\TS_{\AA^n,\basepoint}^{k,-(k-1)(n-1)-\bullet}((\oms)^{\boxtimes k})\right),\dd\zz\shifted\ox\kk[\lambda^r_v]^{1\leq r\leq n}_{v\in I\setminus\{\bp\}}\right)\to \Lie(k)$. Then we shall observe that this map is also surjective.

We may define the de Rham cohomology, i.e. the quotient by all total $z$ derivatives, of $ H_{\ddts}\left(\TS_{\AA^n,\basepoint}^{k,\bul-(n-1)}((\oms)^{\boxtimes k})\right)$ as
\begin{align}
&h_{dR}\left( H_{\ddts}\left(\TS_{\AA^n,\basepoint}^{k,\bul-(n-1)}((\oms)^{\boxtimes k})\right)\right)\nn\\&\qquad:=\frac{H_{\ddts}\left(\TS_{\AA^n,\basepoint}^{k,\bul-(n-1)}((\oms)^{\boxtimes k})\right)}{\left< \left[\alpha\cdot \del_{z^s_v}\right]\,\middle|\,\alpha\in \TS_{\AA^n,\basepoint}^{k,\bul-(n-1)}((\oms)^{\boxtimes k}),v\in I\setminus\{\bp\}, 1\leq s\leq n\right>}.
\end{align}

%(Strictly $h_{dR}$ is the quotient by the submodule obtained by acting with the de Rham differential $\dd_{dR} := \sum_{s=1}^n \sum_{v\in I\setminus\{\bp\}} \dd z^s_v \del_{z^s_v}$ on $\TS^{k,\bul}_{\AA^n,\basepoint}( \Omega^{(kn-1)}_{(\AA^{n})^k}[k(n-1)])$, where $\left(\Omega^{*}_{(\AA^{n})^k},\dd_{dR}\right)$ is the sheaf of sections of the algebraic de Rham complex on $(\AA^{n})^k$. But our definition above is evidently equivalent.)

Our goal is now to prove \cref{lem: de rham} below which identifies this de Rham cohomology with the dual $\LieOperad(k)^\vee$ of the space of $k$-ary operations of the Lie operad.

First, the following lemma and its corollary are useful:
\begin{lem}
Pick any nonempty $J\subset \{2,\dots,k\}$ and for each $j\in J$ pick $\ell_j \in \{1,\dots,j-1\}$. Pick $(m_{r,j}\in \ZZ_{\geq 0})^{1\leq r\leq n}_{j\in J}$ and consider the element
\be \alpha = \prod_{j\in J} \left(\prod_{r=1}^n \del_{z^r_j}^{m_{r,j}}\right) \Prop_{\ell_jj}
\nn\ee
If any one of the $m_{r,j}$ is nonzero, then this element is a total $z$ derivative.
\end{lem}
\begin{proof}[Proof (sketch)]
Suppose $j_1>j_2>\dots$ are the elements of $J$ in decreasing order. By induction on $p$ one checks that if $m_{r,j_p}>0$ for any $r$ then $\alpha$ is a total $z$ derivative. The induction is straightforward, and we shall just give an illustrative an example. The following sketch shows the situation when $J=\{6,5,3,2,1\}$.
\be
\begin{tikzpicture}[]
        \foreach \x in {1,2,3,4,5,6}{
            \coordinate (\x) at (\x,0);
           \node[draw,circle,fill=black,minimum size=0.3pt,inner sep=.5pt,label=below:{$\x$}]() at (\x) {};
        }
        \draw (1) to[out=60,in=120] (2);
        \draw (1) to[out=60,in=120] (3);
        \draw (3) to[out=60,in=120] (5);
        \draw (3) to[out=60,in=120] (6);
        % \draw[densely dotted] (1) to[out=-45,in=-135] (3);
        % \draw[dashed] (1) to[out=-45,in=-135] (6);
        % \draw[dashed] (3) to[out=-45,in=-135] (6);
    \end{tikzpicture}\nn\ee
Clearly any derivatives $\del_{z^r_6}$ act nontrivially only on $\Prop_{36}$ and can immediately be pulled out. Likewise for any derivatives $\del_{z^r_5}$. For the nontrivial inductive step, we note that
\begin{align}
 (\del_{z^r_3} \Prop_{13}) \Prop_{35} \Prop_{36} &= \del_{z^r_3} \left( \Prop_{13} \Prop_{35} \Prop_{36} \right) - \Prop_{13} \left( \del_{z^r_3} \Prop_{35} \Prop_{36} \right) \nn\\
&= \del_{z^r_3} \left( \Prop_{13} \Prop_{35} \Prop_{36} \right) + \Prop_{13} \left(\del_{z^r_5}  \Prop_{35} \right) \Prop_{36} + \Prop_{13} \Prop_{35}\left( \del_{z^r_6} \Prop_{36}\right)  \nn
\end{align}
where the key observation is that $\del_{z^r_i} \Prop_{ij} = - \del_{z^r_j} \Prop_{ij}$.

(Note that this argument is exactly as in the case of dimension $n=1$, since the index $r$ plays no real role.)
\end{proof}

Now recall the basis of $\Coh_{\dd_{\TS}}(\TS_{\AA^n,\basepoint}^{k,\bul})$ we found in \cref{sec: cohomology}, \cref{cor:TransInvBasis}
\begin{align}\label{b1}
        \left(\prod_{i\in  I_{J,(\ell_j)}}\prod_{r=1}^n(z_{i}^r-z_{k}^r)^{n_{r,i}}\right)
        \left(\prod_{j\in J}[\Prop_{\ell_jj}^{m_{1,j},\dots,m_{n,j}}]\right)
    \end{align}
where the set $I_{J,(\ell_j)}$ is as we defined it in \cref{sec: cohomology}. We have the following immediate corollary.

\begin{cor}
Consider the representative
\begin{align}
      \alpha=  \left(\prod_{i\in  I_{J,(\ell_j)}}\prod_{r=1}^n(z_{i}^r-z_{k}^r)^{n_{r,i}}\right)
        \left(\prod_{j\in J}\Prop_{\ell_jj}^{m_{1,j},\dots,m_{n,j}}\right)
\nn\end{align}
in $\TS_{\AA^n,\basepoint}^{k,\bul}$
of any one of the basis vectors in \cref{b1} above. We can find $\beta\in \TS_{\AA^n,\basepoint}^{k,\bul}$ which is a linear combination of the following terms
$$
\left(\prod_{i\in  I_{J,(\ell_j)}}\prod_{r=1}^n(z_{i}^r-z_{k}^r)^{n'_{r,i}}\right)
        \left(\prod_{j\in J}\Prop_{\ell_jj}\right)
$$
and $\alpha-\beta$ is a total $z$ derivative.
\end{cor}

We are now ready to compute the de Rham cohomology.
\begin{lem}\label{lem: de rham}
The de Rham cohomology is isomorphic to $\LieOperad(k)^{\vee}$. That is,
\[ h_{dR}\left( H^p_{\ddts}\left(\TS_{\AA^n,\basepoint}^{k,\bullet-(n-1)}((\oms)^{\boxtimes k})\right)\right)\cong \begin{cases} \LieOperad(k)^{\vee} & p = 0 ,\nn\\ 0 & \text{otherwise.} \end{cases}\]
Moreover this isomorphism is compatible with the action of the symmetric group $S_k$.
\end{lem}
\begin{proof}
Consider the following Euler vector field, which performs rescaling relative to our chosen base point:% labelled by the index $\bp\in I$:
\[
\mathbf{E}_\bp:=\sum_{v\in I\setminus\{\bp\}}\sum^n_{s=1}z^s_{v\bp}\del_{z^s_v}.
\]
Clearly $\TS_{\AA^n,\basepoint}^{k,\bullet-(n-1)}((\oms)^{\boxtimes k})$ is the direct sum of its eigenspaces for the action of $\mathbf E_\bp$. Observe that if $\alpha \in \TS_{\AA^n,\basepoint}^{k,\bullet-(n-1)}((\oms)^{\boxtimes k})$ has nonzero eigenvalue for the action (from the right, since this is a right $\D$-module) of $\mathbf E_{\bp}$ then it is a total $z$ derivative:
\be\left( \alpha \cdot \mathbf{E}_\bp = \lambda \alpha ,\, \lambda\neq 0\right) \implies \alpha = \frac 1 \lambda \sum_{v\in I\setminus\{\bp\}}\sum^n_{s=1} \left(\alpha z^s_{v\bp}\right)\cdot \del_{z^s_v}.\nn\ee
Therefore we may confine our attention to the kernel of $\mathbf E_\bp$.

Now, from the basis in \cref{cor:TransInvBasis} we get a basis of $H_{\ddts}\left(\TS_{\AA^n,\basepoint}^{k,\bullet-(n-1)}((\oms)^{\boxtimes k})\right)$. And by the preceding corollary, it is enough to consider those basis vectors represented by elements of the form
\begin{align} \label{b2}
       \left(\prod_{i\in  I_{J,(\ell_j)}}\prod_{r=1}^n(z_{i}^r-z_{k}^r)^{n_{r,i}}\right)
        \left(\prod_{j\in J}\Prop_{\ell_jj}\right)(\dd\zz\shifted)^I.
\end{align}
(i.e. with no derivatives acting on the propagators $\Prop_{ij}$).
\iffalse
The kernel of $\mathbf E_{\bp}$ acting (from the right) on $\TS_{\AA^n,\basepoint}^{k}((\oms)^{\boxtimes k})$ is isomorphic to the eigenspace of eigenvalue $-n(k-1)$ of $\mathbf E_{\bp}$ acting (from the left) on $\TS_{\AA^n,\basepoint}^{k}((\O_{\AA^n}))^{\boxtimes k})$.% (cf. the proof of \cref{prop: Scaling}).
\fi
Since propagators $\Prop_{ij}$ have eigenvalue $-n$ for $\mathbf E_\bp$ and factors $(z^r_i-z^r_j)$ have eigenvalue $+1$, we see that the vectors of the form \cref{b2} which lie in the kernel of $\mathbf E_{\bp}$ are precisely those corresponding to maximal trees (i.e. with $k-1$ propagators  $\Prop_{ij}$) and with no nontrivial polynomial prefactor.

Therefore, every cohomology class in $ H_{\ddts}\left(\TS_{\AA^n,\basepoint}^{k,\bullet-(n-1)}((\oms)^{\boxtimes k})\right)$ is represented, modulo some total $z$ derivative, by a $\kk$-linear combination of the cohomology classes represented by the vectors
\begin{align} \label{b3}
        \left(\prod_{j=2}^k\Prop_{\ell_j,j}\right)(\dd\zz\shifted)^I, \qquad 1\leq \ell_j<j.
\end{align}
We want to show that this representative is unique. In other words, we want to show that the subspace, of the span of these vectors, consisting of total $z$ derivatives is trivial. Consider a general linear combination
\be \alpha = \sum_{(\ell_j)} c_{(\ell_j)} \left(\prod_{j=2}^k\Prop_{\ell_j,j}\right)(\dd\zz\shifted)^I , \qquad c_{(\ell_j)} \in \kk.\nn\ee
For each tuple $(\ell_j)$ in the sum, there is a residue operation (here, cf. \cref{sec: pairing of residues and propagators})
\be R_{(\ell_j)} = \mu_2^{2\to 1}\circ\dots\mu_2^{j\to l_j}\circ\dots\circ\mu_2^{k\to \ell_k} \label{residue operator}\ee
which picks out precisely that term
\be R_{(\ell_j)}(\alpha) = c_{(\ell_j)} \dd\zz_1  \in \dd\zz_1 \ox \kk[\lambda^s_v]^{1\leq s\leq n}_{v\geq 2}.\label{pickout}\ee
(Here we pick, for the first time, $1=\bp$ as the label of our base point.)

The operation $R_{(\ell_j)}$ is a map of $\D$-modules.
Therefore if $\alpha$ is a total $z$ derivative then so is $R_{(\ell_j)}(\alpha)$. But to be a total   $z$ derivative in $\dd\zz_1 \ox \kk[\lambda^s_v]^{1\leq s\leq n}_{v\geq 2}$ is to belong to the subspace $\bigoplus\limits_{r=1}^n \bigoplus\limits_{i\geq 2} \dd\zz_1 \ox \lambda^r_i \kk[\lambda^s_v]^{1\leq s\leq n}_{v\geq 2}$, and the only way $R_{(\ell_j)}(\alpha) = c_{(\ell_j)} \dd\zz_1 $ belongs to that subspace is if $c_{(\ell_j)}=0$. This establishes that the only linear combination of the vectors in \cref{b3} which is a total $z$ derivative is the zero vector.

We conclude that the de Rham cohomology
\[ h_{dR}\left( H_{\ddts}\left(\TS_{\AA^n,\basepoint}^{k,\bullet-(n-1)}((\oms)^{\boxtimes k})\right)\right)\]
has a $\kk$-basis given by the representatives of the vectors
\be \left(\prod_{j=2}^k \Prop_{\ell_jj} \right) (\dd\zz\shifted)^{\boxtimes k}\label{b4}\ee
labelled by tuples $(\ell_2,\dots,\ell_k)$ such that $\ell_j<j$ for each $j$.
In particular, it is concentrated in the cohomological degree
\be (k-1)(n-1) - k(n-1) = -(n-1) \Rightarrow \bullet=0.\nn\ee
(Recall that $(\dd\zz\shifted)^I$ is in cohomological degree $-k(n-1)$, and the propagators $\Prop_{ij}$ are in cohomological degree $n-1$.)

To complete the proof, let us recall an explicit description of $\LieOperad(k)^{\vee}$, the dual of the $\kk$-vector space of $k$-ary operations of the Lie operad. The Orlik-Solomon algebra $OS(k) = \bigoplus_{p\geq 0} OS(k)^p$ is the quotient of the free graded-commutative unital $\kk$-algebra in generators $(A_{ij}\equiv A_{ji})_{1\leq i<j\leq k}$ in degree one, by the ideal generated by the Arnold relations $A_{ij}A_{j\ell} + A_{j\ell}A_{\ell i} + A_{\ell i} A_{ij}=0$. (The relations $A_{ij}A_{ij}=0$ are automatic since $A_{ij}$ is in odd degree.)
As a $\kk$-vector space, $\LieOperad(k)^\vee \cong OS(k)^{k-1}$. It has a $\kk$-basis
\be \prod_{j=2}^{k} A_{\ell_jj} \nn\ee
labelled by tuples $(\ell_2,\dots,\ell_k)$ such that $\ell_j<j$ for each $j$. On comparing this with \cref{b4}, we have the required isomorphism of vector spaces.
The compatibility with $S_k$-module structure follows from the Arnold relations, \cref{sec: arnold relations}, \cref{thm: arnold}.

(See, for example, \cite{totaro1996configuration}, and  \cite[13.2.4]{LodayVallette} for a discussion of the basis of $\mathrm{LieOperad}(n)$.)
\end{proof}
\iffalse
 \cref{lem: de rham} implies the following

\begin{cor}\label{cor: Lie}
\be \Hom_{\kk}\left(h_{dR}\left( H_{\ddts}\left(\TS_{\AA^n,\basepoint}^{k}((\oms)^{\boxtimes k})\right)\right),\dd\zz\shifted\ox \kk\right)\cong \LieOperad(k) ,
\nn\ee
where we regard the space $\LieOperad(k)$ of $k$-ary operations of the Lie operad as a chain complex concentrated in degree zero.
\end{cor}
\fi
We get a map
\begin{align}
&\Hom_{\kk[z^s_{v\bp},\del_{z^s_v}]^{1\leq s\leq n}_{v\in I \setminus\{\bp\}}}\left(H_{\ddts}\left(\TS_{\AA^n,\basepoint}^{k,\bullet-(n-1)}((\oms)^{\boxtimes k})\right),\dd\zz\ox\kk[\lambda^r_v]^{1\leq r\leq n}_{v\in I\setminus\{\bp\}}\right)\nn\\
&\qquad  \xrightarrow{[h_{dR}]} \Hom_{\kk}\left(h_{dR}\left( H_{\ddts}\left(\TS_{\AA^n,\basepoint}^{k,\bullet-(n-1)}((\oms)^{\boxtimes k})\right)\right),\kk\cdot \dd\zz \right).
\nn\end{align}
induced by taking de Rham cohomologies.
\begin{prop}\label{prop: dR injective}
This map is $[h_{dR}]$ injective.
\end{prop}
\begin{proof}
  This is proved in \cite[\S2.2.7]{BDChiralAlgebras}. We present an elementary proof here. Suppose that
\[\mu\in   \Hom_{\kk[z^s_{v\bp},\del_{z^s_v}]^{1\leq s\leq n}_{v\in I \setminus\{\bp\}}}\left(H^p_{\ddts}\left(\TS_{\AA^n,\basepoint}^{k,\bullet-(n-1)}((\oms)^{\boxtimes k})\right),\dd\zz\ox\kk[\lambda^r_v]^{1\leq r\leq n}_{v\in I\setminus\{\bp\}}\right)
\]
is in the kernel of this map, $[h_{dR}](\mu)=0$. That means, suppose that
\[
 \mu(\beta)\equiv 0 \mod \bigoplus_{r=1}^n \bigoplus_{i\in I\setminus\{\bp\}} \dd\zz \ox \lambda^r_i \kk[\lambda^s_v]^{1\leq s\leq n}_{v\in I\setminus\{\bp\}} \]
for all $\beta\in H^p_{\ddts}\left(\TS_{\AA^n,\basepoint}^{k,\bullet-(n-1)}((\oms)^{\boxtimes k})\right)$.
We want to argue that in that case $\mu(\alpha) = 0$ holds on the nose for all $\alpha\in H^p_{\ddts}\left(\TS_{\AA^n,\basepoint}^{k,\bullet-(n-1)}((\oms)^{\boxtimes k})\right)$. We may write
\be \mu(\alpha) = \dd\zz\ox\sum_{\mathbf v;\mathbf s} c_{\mathbf v;\mathbf s}(\alpha) \lambda^{s_1}_{v_1} \dots \lambda^{s_\ell}_{v_{\ell}} , \qquad c_{\mathbf v;\mathbf s}(\alpha) \in \kk.\nn\ee
for some sum over distinct monomials.
But then for each such monomial we compute
\[ \mu\left(\alpha \cdot z_{v_1\bp}^{s_1}\dots z_{v_\ell\bp}^{s_\ell} \right)
 \equiv c_{\mathbf v;\mathbf s}  \mod \bigoplus_{r=1}^n \bigoplus_{i\in I\setminus\{\bp\}} \dd\zz \ox \lambda^r_i \kk[\lambda^s_v]^{1\leq s\leq n}_{v\in I\setminus\{\bp\}}\]
and we conclude (setting $\beta = \alpha \cdot z_{v_1\bp}^{s_1}\dots z_{v_\ell\bp}^{s_\ell}$) that $c_{\mathbf v;\mathbf s}=0$ on the nose. So $\mu$ must indeed be the zero map, and thus $[h_{dR}]$ is indeed injective.
\end{proof}

Now we are ready to complete the proof of \cref{thm: ChiralIsoLie}, which is the main theorem of the paper.
\begin{proof}[Proof of \cref{thm: ChiralIsoLie}]
  We already proved that the composition of maps
\begin{align}
&\bigoplus_{p\in \ZZ}H^p_{\dd_\P}\left(P^{ch}_{\AA^n}(k)\right)\nn\\
&\underset{\text{\cref{prop: translation invariant Pch}}} \cong \bigoplus_{p\in \ZZ} H^p_{\dd_\P}\left(  \Hom_{\kk[z^s_{v\bp},\del_{z^s_v}]^{1\leq s\leq n}_{v\in I \setminus\{\bp\}}}\left(\TS_{\AA^n,\basepoint}^{k,\bullet-(n-1)}((\oms)^{\boxtimes k}),\dd\zz\ox\kk[\lambda^r_v]^{1\leq r\leq n}_{v\in I\setminus\{\bp\}}\right)\right)\nn\\
&\underset{\text{\cref{prop: translation invariant injectivity}}} \hookrightarrow\bigoplus_{p\in\ZZ}\Hom_{\kk[z^s_{v\bp},\del_{z^s_v}]^{1\leq s\leq n}_{v\in I \setminus\{\bp\}}}\left(H^p_{\ddts}\left(\TS_{\AA^n,\basepoint}^{k,\bullet-(n-1)}((\oms)^{\boxtimes k})\right),\dd\zz\ox\kk[\lambda^r_v]^{1\leq r\leq n}_{v\in I\setminus\{\bp\}}\right)\nn\\
&  \underset{\text{\cref{prop: dR injective}}} \hookrightarrow \bigoplus_{p\in\ZZ}\Hom_{\kk}\left(h_{dR}\left( H^p_{\ddts}\left(\TS_{\AA^n,\basepoint}^{k,\bullet-(n-1)}((\oms)^{\boxtimes k})\right)\right),\kk\cdot \dd\zz \right)\underset{\text{\cref{lem: de rham}}}\cong \LieOperad(k).\nn
\end{align}
is injective. We only need to observe that it is surjective, and this follows from the existence of the residue map $\mu_2\in P^{ch}_{\AA^n,0}(2)$.

So we have found an isomorphism of differential graded vector spaces for each $k$ which is in fact an isomorphism of $S_k$ modules.
By inspection, one sees that the operadic compositions agree, c.f. the composition of residue operators \cref{residue operator} and their action on the basis elements \cref{b3}.
\end{proof}



\section{The Chevalley-Cousin complex}\label{sec: Chevalley-Cousin complex}
From \cite{BDChiralAlgebras}, a chiral algebra on a smooth curve can be thought of as a Lie algebra object in a certain tensor category. The Chevalley-Cousin complex of this chiral algebra is defined to be the reduced Chevalley complex of the corresponding Lie algebra object. It is an important ingredient when defining the chiral homology \cite[Chapter 4]{BDChiralAlgebras}. The derived section of the Chevalley-Cousin complex for the unit chiral algebra can be thought of as singular differential forms  (associated to Feynman diagrams) that appear in 2d Lagrangian chiral QFT. The theory of chiral homology can be used to define such a priori divergent Feynman integrals, see \cite{gui2022elliptictracemapchiral,gui2023tracemapchiralweyl}. In this section, we give an analogous construction of the Chevalley-Cousin complex for the homotopy polysimplicial chiral algebra $\oms.$

Following \cite[\S1.3.1]{BDChiralAlgebras} we let
\be Q(I):= \{ I \xonto \pi T \}\nn\ee
denote the lattice of surjections out of a finite set $I$, and abuse notation by sometimes writing $T\in Q(I)$ for the surjection $\pi:I\onto T$.

We define the graded vector space
\be \ChirCompTot^\bul_{(\AA^n)^I} := \bigoplus_{T \in Q(I)} \Delta_*^{(I/T)} \TS^{T,\bul}((\oms)^{\boxtimes T}[1]). \nn\ee
It comes equipped with a differential $D$ which we are about to describe. The resulting chain complex $(\ChirCompTot^\bul_{(\AA^n)^I},D)$ is the \dfn{Chevalley-Cousin complex} in our setting. Compare \cite[\S3.4.11]{BDChiralAlgebras}.

First observe that as a graded vector space $\ChirCompTot^\bul_{(\AA^n)^I}$ is equivalently  the totalization
%\begin{align*}
$\ChirCompTot_{(\AA^n)^I}^\bul = \Tot(\ChirComp_{(\AA^n)^I}^{\bul,\bul})$
%\qquad\text{i.e.}\qquad     \ChirCompTot_{(\AA^n)^k}^p = \bigoplus_{q=0}^{k-1} \ChirComp_{(\AA^n)^k}^{p-q,q}
%\end{align*}
of the bigraded vector space
\be %\ChirComp_{(\AA^n)^I}^{\bul,\bul}:= \bigoplus_{p\geq 0} \bigoplus_{q=0}^{k-1} \ChirComp_{(\AA^n)^k}^{p,q},\qquad
\ChirComp_{(\AA^n)^I}^{q,p} :=
\bigoplus_{\substack{T\in Q(I) : \\ |T|=-q}} \Delta_*^{(I/T)}\TS^{T,p}((\oms)^{\boxtimes T}).\nn\ee

Recall that for us the canonical sheaf $\omega_{\AA^n}$ sits in cohomological degree zero, and $\TS^{k,\bul}((\omega_{\AA^n})^{\boxtimes k})$ is concentrated in cohomological degrees $\{0,1\dots,\binom k 2 (n-1)\}$. Thus our model $\TS^{k,\bul}((\oms)^{\boxtimes k})$ of the derived global sections of the \emph{shifted} canonical sheaf $(\oms)^{\boxtimes k}:= (\omega_{\AA^n}[n-1])^{\boxtimes k}$ is concentrated in cohomological degrees
$\{ -k(n-1), -k(n-1) + 1, \dots, \left(\binom k 2 - k\right)(n-1)\}$.
The chiral operations $\mu_\ell$ from \cref{sec: higher operations} define maps of bidegree $(-1+\ell,2-\ell)$
\be \ddmu \ell : \ChirComp_{(\AA^n)^k}^{q,p} \to \ChirComp_{(\AA^n)^k}^{q+\ell-1,p+2-\ell} \nn\ee
for every $\ell\geq 2$, as follows. We first define $\ddmu \ell$ on $\TS^T((\oms)^{\boxtimes T})$ to be the sum
\begin{align} \ddmu\ell|_{\TS^T((\oms)^{\boxtimes T})} &\quad: \TS^T((\oms)^{\boxtimes T}) \to \bigoplus_{ \substack{L\subset T \\: |L| = \ell}} \Delta_*^{T/(\{\star\}\sqcup T\setminus L)} \TS^{\{\star\}\sqcup T\setminus L}((\oms)^{\boxtimes (\{\star\}\sqcup T\setminus L)})\nn
\end{align}
over all ways of partially applying the operation $\mathbf{I}^{[L,T\setminus L]}_{[\{\star\},T\setminus L]}\circ\mu_\ell$, where the map $\mathbf{I}^{[L,T\setminus L]}_{[\{\star\},T\setminus L]}$ is defined in \cref{def: Imap} (none, if $|T|<\ell$, of course, so it is the zero map in such cases). See \cref{fig:mudifferential}.
