Then we extend $\ddmu\ell$ uniquely as a map of $\D$-modules to all the summands appearing in the definition of $\ChirComp_{(\AA^n)^I}$, i.e.
\(\ddmu \ell := \sum\limits_{\substack{T\in Q(I)}} \Delta_*^{I/T} \left(\ddmu\ell|_{\TS^T((\oms)^{\boxtimes T})}\right). \nn
\)
The sum
\begin{align}    D=\ddts+\sum_{\ell=2}^k\ddmu{\ell}:\ChirCompTot_{(\AA^n)^I}^p\to\ChirCompTot_{(\AA^n)^I}^{p+1}
\end{align}
is then a map of cohomological degree $+1$ on the total complex, and the $L_\8$-algebra coherence relations are equivalent to the statement that $D^2=0$, i.e. that
\begin{align}
    \label{eq:differentials}
\ddts\circ\ddmu{\ell}+\ddmu{\ell}\circ\ddts+\sum_{m=2}^{\ell-1}\ddmu{m}\circ \ddmu{\ell-m+1}=0
\end{align}
for all $\ell\geq 2$, in addition to $\ddts^2=0$.

\begin{exmp}\label{exmp: cousin}
In the case  $I=\{1,2,3\}$ of three marked points we have the following. (In our notation here, we are using the fact that surjections $(\pi:I \twoheadrightarrow T)\in Q(I)$ out of $I$ can be seen as equivalence relations on $I$.)
\begin{align} \ChirComp_{(\AA^n)^3}^{-3,\bul} &= \TS^{3,\bul}(\oms)\nn\\
\ChirComp_{(\AA^n)^3}^{-2,\bul} &= \Delta_*^{1\sim 2} \TS^{2,\bul}(\oms) \oplus
\Delta_*^{1\sim 3} \TS^{2,\bul}(\oms) \oplus
\Delta_*^{2\sim 3} \TS^{2,\bul}(\oms)\nn\\
\ChirComp_{(\AA^n)^3}^{-1,\bul} &=  \Delta_*^{1\sim 2 \sim 3} (\oms)^{\bul}
\end{align}
If we further specialize to  $n=1$ dimensions, we recover  the usual Chevalley-Cousin complex for 3 marked points (in this case, $\ddts=0$ and $d_{\mu^l}=0$ for all $l\geq 3$),
\be
\begin{tikzcd}
\ChirComp_{(\AA^1)^3}^{-3,0} \rar{\ddmu 2}& \ChirComp_{(\AA^1)^3}^{-2,0} \rar{\ddmu 2}& \ChirComp_{(\AA^1)^3}^{-1,0}  \\
\end{tikzcd}
\nn\ee
while in $n=2$ and $n=3$ dimensions respectively, $\ChirComp$ is concentrated in the following bidegrees (we have non-trivial $\ddts$ and $d_{\mu^l},l\geq 3$)
\be
\begin{tikzcd}
\ChirComp_{(\AA^2)^3}^{-3,-3} \dar{\ddts}& & \\
\ChirComp_{(\AA^2)^3}^{-3,-2} \dar{\ddts}\rar{\ddmu 2}& \ChirComp_{(\AA^2)^3}^{-2,-2} \dar{\ddts}& \\
\ChirComp_{(\AA^2)^3}^{-3,-1} \dar{\ddts}\rar{\ddmu 2}& \ChirComp_{(\AA^2)^3}^{-2,-1} \rar{\ddmu 2}& \ChirComp_{(\AA^2)^3}^{-1,-1}  \\
\ChirComp_{(\AA^2)^3}^{-3,0} \arrow[urr,bend right=0,"\ddmu 3"']& &
\end{tikzcd}
% \nn\ee
% In the case of $n=3$ dimensions, we have instead
% \be
\qquad
\begin{tikzcd}
\ChirComp_{(\AA^3)^3}^{-3,-6} \dar{\ddts}& & \\
\ChirComp_{(\AA^3)^3}^{-3,-5} \dar{\ddts}& & \\
\ChirComp_{(\AA^3)^3}^{-3,-4} \dar{\ddts}\rar{\ddmu 2}& \ChirComp_{(\AA^3)^3}^{-2,-4} \dar{\ddts}& \\
\ChirComp_{(\AA^3)^3}^{-3,-3} \dar{\ddts}\rar{\ddmu 2}& \ChirComp_{(\AA^3)^3}^{-2,-3} \dar{\ddts}& \\
\ChirComp_{(\AA^3)^3}^{-3,-2} \dar{\ddts}\rar{\ddmu 2}& \ChirComp_{(\AA^3)^3}^{-2,-2} \rar{\ddmu 2}& \ChirComp_{(\AA^3)^3}^{-1,-2}  \\
\ChirComp_{(\AA^3)^3}^{-3,-1} \dar{\ddts}\arrow[urr,bend right=0,"\ddmu 3"']& &\\
\ChirComp_{(\AA^3)^3}^{-3,0} & &
\end{tikzcd}
\nn\ee
