Beilinson and Drinfeld prove the following theorem.

\begin{thm}[\cite{BDChiralAlgebras}] Let $k\geq 2$.
The Chevalley-Cousin complex $\left(\ChirCompTot_{(\AA^1)^k}^\bul,D=d_{\mu^2}\right)$ is a resolution of the
%$\kk[z_i]_{1\leq i\leq k} = \O_{(\AA^{1})^k}$-module $\Gamma\left((\AA^{1})^k,(\omega_{(\AA^1)})^{\boxtimes k}\right)$ of
global sections of the shifted canonical sheaf. Namely, we have the following complex of $\D$-modules
\be 0 \to\Gamma\left((\AA^{1})^k,(\omega_{(\AA^1)})^{\boxtimes k}\right) \to \ChirCompTot_{(\AA^1)^k}^{-k} \xrightarrow{d_{\mu^2}} \ChirCompTot_{(\AA^1)^k}^{-k+1} \xrightarrow{d_{\mu^2}} \cdots  \xrightarrow{d_{\mu^2}} \ChirCompTot_{(\AA^1)^k}^{-1} \rightarrow 0\nn\ee
which is exact.
\end{thm}
Our goal in this section is to generalize this theorem to arbitrary dimensions $n\geq 1$. We need some preparations.  From \cref{eq:differentials}, we have
\begin{align*}
\ddts\circ\ddmu{3}+\ddmu{3}\circ\ddts+\ddmu{2}\circ \ddmu{2}=0.
\end{align*}
Thus $\ddmu{2}$ induces a differential on $\ddts$-cohomology. We denote the induced differential by $[\ddmu 2]$. The proof of Beilinson and Drinfeld can be generalized to obtain the following lemma and we get their original theorem if we take $n=1$.
\begin{lem}\label{lem:cohom}
Let $k\geq 2$. The chain complex
\be
  \begin{tikzcd}
 0  \rar&   \Coh_{\ddts}^p(\ChirComp_{(\AA^n)^k}^{-k,\bul}) \rar{[\ddmu 2]} & \Coh_{\ddts}^p(\ChirComp_{(\AA^n)^k}^{-k+1,\bul})\rar{[\ddmu 2]} &\cdots\\
  \end{tikzcd}
  \nn\ee
is exact for any $p>-k(n-1)$.
% \begin{enumerate}
% \item If $p \notin (n-1) \ZZ$ then $\Coh_{\ddts}^p(\TS^{q,\bul}(\oms))=0$ and hence
% \be \Coh_{\ddts}^p(\ChirComp_{(\AA^n)^I}^{-q,\bul}) = 0.\nn\ee
% \item If $p \in (n-1) \ZZ$ then the map of $\ddts$-cohomologies induced by $\ddmu 2$ -- cf. \cref{eq:differentials} --
% \be [\ddmu2] : \Coh_{\ddts}^p(\ChirComp_{(\AA^n)^I}^{-q,\bul}) \to \Coh_{\ddts}^p(\ChirComp_{(\AA^n)^I}^{-q+1,\bul}) \nn\ee
% is injective.
% \end{enumerate}
\qed\end{lem}
\begin{proof} We have $\ChirComp_{(\AA^n)^k}^{-k,\bul} = \TS^{k,\bul}((\oms)^{\boxtimes k})$, by definition.
In \cref{sec: cohomology}  we gave an explicit basis of the cohomology $\Coh_{\ddts}^p(\TS^{k,\bul}((\oms)^{\boxtimes k}))$ as a $\kk$-vector space.
The basis vectors are of the form
\be P_{f,\Gamma} = f(z,\del) \left(\prod_{e\in \Gamma} P_{e}\right) (\dd \mathbf z[n-1])^{\ox k} \nn\ee
labelled by certain tree graphs $\Gamma$ on the vertex set $I=\{1,\dots,k\}$, and certain elements $f(z,\del) \in \kk[z^r_i,\del_r^i]^{1\leq r\leq n}_{1\leq i\leq k} = \D((\AA^n)^k)$.

(Such a product involving $|\Gamma|$ many propagators sits in cohomological degree $|\Gamma|(n-1) - k(n-1)$. Whenever $p$ is not of that form for some tree graph $\Gamma$ then the cohomology is trivial,
 $\Coh_{\ddts}^p(\TS^{k,\bul}((\oms))^{\boxtimes k})=0$, and there is nothing more to check.)

Since the push forward functors $\Delta_*^{(I/T)}, T\in Q(I)$, are exact, we have
\[
\Coh_{\ddts}^p(\ChirComp_{(\AA^n)^k}^{q,\bul})=\bigoplus_{\substack{T\in Q(I) : \\ |T|=-q}} \Delta_*^{(I/T)}\left(\Coh_{\ddts}^p(\TS^{T,\bul}((\oms)^{\boxtimes T}))\right).
\]
For $T=(T,\pi:I\twoheadrightarrow T)\in Q(I)$, and $t\in T$, let us write
\be I_t: =\pi^{-1}(t). \nn\ee
If we pick a vertex $1 \in I$, then the above direct sum can be written as
\begin{align}
\Coh_{\ddts}^p(\ChirComp_{(\AA^n)^k}^{q,\bul})&=\bigoplus_{\substack{T\in Q(I) : \\ |T|=-q,\\ I_{\pi(1)}=\{1\}}} \Delta_*^{(I/T)}\left(\Coh_{\ddts}^p(\TS^{T,\bul}((\oms)^{\boxtimes T}))\right)\nn\\&\qquad\oplus \bigoplus_{\substack{T\in Q(I) : \\ |T|=-q,\\ |I_{\pi(1)}|\geq 2}} \Delta_*^{(I/T)}\left(\Coh_{\ddts}^p(\TS^{T,\bul}((\oms)^{\boxtimes T}))\right).
\nn\end{align}
Suppose that we have an element
\begin{align}
\alpha \in \Delta_*^{(I/T)}\left(\Coh_{\ddts}^p(\TS^{T,\bul}((\oms)^{\boxtimes T}))\right)&=\Coh_{\ddts}^p(\TS^{T,\bul}((\oms)^{\boxtimes T}))\ox_{\kk[\lambda_T]}\kk[\lambda_I],\nn\\&\qquad\qquad\quad T\in Q(I) : |T|=-q, |I_{\pi(1)}|\geq 2.\nn
\end{align}
We claim that we can find
\[
\beta \in \Delta_*^{(I/T')}\left(\Coh_{\ddts}^p(\TS^{T',\bul}(\oms))\right),\quad |T'|=-q+1,
\]
such that
\[
[\ddmu 2](\beta)-\alpha\in \bigoplus_{\substack{T\in Q(I) : \\ |T|=-q,\\ I_{\pi(1)}=\{1\}}} \Delta_*^{(I/T)}\left(\Coh_{\ddts}^p(\TS^{T,\bul}((\oms)^{\boxtimes T}))\right).
\]
Since $\Coh_{\ddts}^p(\TS^{T,\bul}((\oms)^{\boxtimes T}))$ generates $\Delta_*^{(I/T)}\left(\Coh_{\ddts}^p(\TS^{T,\bul}((\oms)^{\boxtimes T}))\right)$ as a $\D$-module, we can assume that $\alpha\in \Coh_{\ddts}^p(\TS^{T,\bul}((\oms)^{\boxtimes T}))$. Let $(T',\pi')=(T\sqcup\{\star\},\pi')\in Q(I)$, and we have sequence of surjective maps
\[
\pi=\pi^{(T'/T)}\circ\pi':I\twoheadrightarrow T'\twoheadrightarrow T,\quad \pi^{(T'/T)}:T'\twoheadrightarrow T,
\]
such that $\pi'^{-1}(\star)=1,\pi^{(T'/T)}(\star)=\pi(1)=t, \pi^{(T'/T)}|_{T}=\mathrm{id}_T$. We view $\alpha$ as an element in $\Coh_{\ddts}^p(\TS^{T',\bul}((\oms)^{\boxtimes T'}))$ and define
\[
\beta=\alpha\cdot [P_{\star t}]\in \Coh_{\ddts}^p(\TS^{T,\bul}((\oms)^{\boxtimes T})).
\]
Then it is clear that (see Fig. \ref{TwoSummand})
\[
[\ddmu 2](\beta)-\alpha\in \bigoplus_{\substack{T\in Q(I) : \\ |T|=-q,\\ I_{\pi(1)}=\{1\}}} \left(\Coh_{\ddts}^p(\TS^{T,\bul}((\oms)^{\boxtimes T}))\right).
\]
