\begin{thm}\label{thm: Chevalley-Cousin} Let $n\geq 2$ and $k\geq 2$.
The Chevalley-Cousin complex $\left(\ChirCompTot_{(\AA^n)^k}^\bul,D\right)$ is a resolution of the
%$\kk[z^r_i]^{1\leq r\leq n}_{1\leq i\leq k} = \O_{(\AA^{n})^k}$-module $\Gamma\left((\AA^{n})^k,(\omega\shifted_{(\AA^n)})^{\boxtimes k}\right)$
of global sections of the shifted canonical sheaf. Namely, we have the following complex of $\D$-modules
\be 0 \to\Gamma\left((\AA^{n})^k,(\omega\shifted_{(\AA^n)})^{\boxtimes k}\right) \to \ChirCompTot_{(\AA^n)^k}^{-kn} \xrightarrow{D} \ChirCompTot_{(\AA^n)^k}^{-kn+1} \xrightarrow{D} \cdots  \xrightarrow{D} \ChirCompTot_{(\AA^n)^k}^{-n} \xrightarrow{}0\nn\ee
which is exact.
\end{thm}
\begin{proof}
We need to prove that the complex  $(\ChirCompTot_{(\AA^n)^k}^\bul,D)$ has vanishing cohomology in all degrees except $-kn$. Note that
\[
\ChirCompTot_{(\AA^n)^k}^{-kn}=\ChirComp_{(\AA^n)^I}^{-k,-k(n-1)} :=
\TS^{I,-k(n-1)}(\oms).
\]
Furthermore $\mathrm{Ker}(D)=\mathrm{Ker}(\ddts)=\Gamma\left((\AA^{n})^k,(\omega\shifted_{(\AA^n)})^{\boxtimes k}\right)$ from the computation of the cohomology in the previous section.

Now consider an element $\alpha \in \ChirCompTot_{(\AA^n)^k}^{p},p>-kn$. Such an element is, more explictly, a sum
\be \alpha = \alpha^{-k,p+k} + \alpha^{-k+1,p+k-1} + \dots + \alpha^{-1,p+1} \nn\ee
with each $\alpha^{-q,p+q} \in \ChirComp_{(\AA^n)^k}^{-q,p+q}$. Let us demand that $\alpha$ be $D$-closed,
\be (\ddts + \ddmu 2 + \dots + \ddmu k)\alpha = 0, \nn\ee
so that it defines a cohomology class $[\alpha]_D \in \Coh_D^p(\ChirCompTot_{(\AA^n)^k}^{\bul})$.
That demand entails in particular that
\be \ddts \alpha^{-k,p+k} = 0 \quad\text{and}\quad \ddmu 2 \alpha^{-k,p+k} = -\ddts \alpha^{-k+1,p+k-1} .\nn\ee
The first of these implies that $\alpha^{-k,p+k}$ represents class $[\alpha^{-k,p+k}]_{\ddts} \in \Coh_{\ddts}^{p+k}(\ChirComp_{(\AA^n)^k}^{-k,\bul})$ for the cohomology of $\ddts$. Now we shall use \cref{lem:cohom} to argue that this class is the zero class. Indeed, \cref{lem:cohom} implies that the class $[\alpha^{-k,p+k}]_{\ddts}$ is zero whenever its image $[\ddmu2 \alpha^{-k,p+k}]_{\ddts} \in \Coh_{\ddts}^{p+k}(\ChirComp_{(\AA^n)^k}^{-k+1,\bul})$ is zero. By the second equation above this image is $[-\ddts \alpha^{-k+1,p+k-1}]_{\ddts}$ which is indeed the zero class. We conclude that
\be \alpha^{-k,p+k} = \ddts \beta^{-k,p+k-1}\nn\ee
for some $\beta^{-k,p+k-1} \in \ChirComp_{(\AA^n)^k}^{-k,p+k-1}$.
Therefore we have that
\begin{align} [\alpha]_D &= [\alpha^{-k+1,p+k-1} + \dots + \alpha^{-1,p+1} + \ddts \beta^{-k,p+k-1}]_D \nn\\
&= [\alpha^{-k+1,p+k-1} + \dots + \alpha^{-1,p+1} + \ddts \beta^{-k,p+k-1} - D\beta^{-k,p+k-1}]_D \nn\\
&= [\alpha^{-k+1,p+k-1} + \dots + \alpha^{-1,p+1} - (\ddmu 2+\dots+\ddmu k)\beta^{-k,p+k-1} ]_D\nn\\
&= [\tilde\alpha]_D
\end{align}
where
\be \tilde\alpha = \tilde\alpha^{-k+1,p+k-1} + \dots + \tilde\alpha^{-1,p+1} \nn\ee
with $\tilde\alpha^{-k+q,p+k-q} := \alpha^{-k+q,p+k+q} - \ddmu {q+1} \beta^{-k,p+k-1}$.
So we have found a new representative, $\tilde\alpha$, of our original cohomology class $[\alpha]_D$. The condition $D\tilde{\alpha}$ now implies that
\be \ddts \tilde\alpha^{-k+1,p+k-1} = 0 \quad\text{and}\quad \ddmu 2 \tilde\alpha^{-k+1,p+k-1} = -\ddts \tilde{\alpha}^{-k+2,p+k-2} .\nn\ee
We conclude that $[\alpha^{-k+1,p+k-1}]\in \Coh_{\ddts}^{p+k-1}(\ChirComp_{(\AA^n)^k}^{-k,\bul})$ and $[\ddmu 2][\alpha^{-k+1,p+k-1}]=0$. Again by Lemma \ref{lem:cohom}, $[\alpha^{-k+1,p+k-1}]$ is $[\ddmu 2]$-exact which means that there is $\gamma^{-k,p+k-1},\delta^{-k+1,p+k-2}\in \ChirComp_{(\AA^n)^k}^{-k,p+k-1}$ such that
\be \ddts\gamma^{-k,p+k-1} = 0 \quad\text{and}\quad \alpha^{-k+1,p+k-1}-\ddmu 2\gamma^{-k,p+k-1} = \ddts \delta^{-k+1,p+k-2} .\nn\ee
Define
\[
\tilde{\tilde{\alpha}}=\tilde{\alpha}-D(\gamma^{-k,p+k-1}+\delta^{-k+1,p+k-2}).
\]
Then
\be \tilde{\tilde{\alpha}} =\tilde{ \tilde{\alpha}}^{-k+2,p+k-2} + \dots + \tilde{\tilde{\alpha}}^{-1,p+1} .\nn\ee
Repeating the above procedure, we conclude that $\alpha$ is in fact $D$-exact.

\end{proof}



\section{Examples of higher chiral operations}\label{sec: examples}
Our main result, in the form \cref{thm: quasi-isomorphism from LieInfinity}, asserts the existence of chiral operations $\mu_k\in \P^{ch}_{\AA^n,k-2}[k]$, for $k=2,3,4,\dots$ obeying the coherence relations governing \Linfinity-algebras as in \cref{mucoherence}.
% :
% \begin{align*}
%   (\mu_k\circ \ddts)(-) & =\sum_{\substack{ k_1+k_2=k+1\\k_1,k_2>1}} \sum_{\sigma\in \mathrm{Sh}^{-1}_{k_1-1,k_2}}\mathrm{sgn}(\sigma)(-1)^{(k_1-1)k_2} (\mu_{k_1}\circ_1\mu_{k_2})^{\sigma}(-).
% \end{align*}
It is instructive to construct the first higher operation, $\mu_3$, explicitly in low dimensions.

\subsection{The Jacobiator and $\mu_3$ in $n=2$ dimensions}
In $n=2$ dimensions the \polysimplicial model $\TS_{\AA^2}^k$ of $R\Gamma(\Conf_k(\AA^2),\O)$ reduces to a model of polynomial differential forms on hypercubes by identifying $u^1_e=u_e$ and $u^2_e=1-u_e$, cf. \cref{rem: cubes}, obeying certain boundary conditions.
Explicitly, we have
\begin{align}
\TS_{\AA^2}^k = &\bigl\{ \tau \in
 \kk[z_i^r,(z_j^r-z_l^r)^{-1})]^{1\leq r\leq 2}_{1\leq i\leq k; 1\leq j<\ell<k} \ox \kk[u_{j\ell},\dd u_{j\ell}]_{1\leq j<\ell<k}\nn\\
& \quad : \text{$\omega|_{u_{ij}=0}$ is regular in $(z^1_i-z^1_j)$ }\nn\\ &\quad \qquad\text{and $\omega|_{u_{ij}=1}$ is regular in $(z^2_i-z^2_j)$, for $1\leq i<j\leq k$} \bigr\}. \nn
\end{align}
In particular, $\TS_{\AA^2}^3$ consists of polynomial differential forms on the $\binom 3 2 =3$-cube, cf. \cref{fig}.

The first coherence relation is
\be \mu_3 \circ \ddts = \mu_2 \circ_1 \mu_2 - (\mu_2 \circ_1 \mu_2)^{[2 1 3]} + (\mu_2 \circ_1 \mu_2)^{[2 3 1]}=:\Jac_3 \nn\ee
where the three $(1,2)$-unshuffles are $[1 2 3]$, $[2 1 3]$ and $[2 3 1]$.

If we identify $\omega_{\AA^2} \ox_{\kk[\lambda^r]^{1\leq r\leq 2}} \kk[\lambda^r_i]^{1\leq r\leq 2}_{1\leq i\leq k}\cong \omega_{\AA^2} \ox_{\kk} \kk[\lambda^r_i]^{1\leq r\leq 2}_{2\leq i\leq k}$,
by carefully working out the signs and using the explicit description of $\mu_2$ from \cref{sec: higher operations}, the Jacobiator in the cube model is given by
\begin{align} \Jac_3(\tau)
%&:= \mu^2_{3\to 1} \mu^2_{2\to 1}(-) + \mu^2_{2\to 1} \mu^2_{3\to 1}(-) + \mu^2_{(32) \to 1} \mu^2_{3 \to 2}(-)\nn \\
&= \Biggl(+\int_{u_{13}=0}^1 \int_{u_{12}=0}^1 \res_{z^1_3 \to z^1_1} \res_{z^1_2\to z^1_1} \res_{z^2_3 \to z^2_1} \res_{z^2_2\to z^2_1}(-)|_{u_{23} = u_{13}}
\nn\\&\qquad
+ \int_{u_{12}=0}^1 \int_{u_{13}=0}^1 \res_{z^1_2 \to z^1_1} \res_{z^1_3\to z^1_1} \res_{z^2_2 \to z^2_1} \res_{z^2_3\to z^2_1}(-)|_{u_{23} = u_{12}} \nn\\
&\qquad + \int_{u_{12}=0}^1 \int_{u_{23}=0}^1 \res_{z^1_2 \to z^1_1} \res_{z^1_3\to z^1_2} \res_{z^2_2\to z^2_1} \res_{z^2_3\to z^2_2}(-)|_{u_{13} = u_{12}}\Biggr)\nn\\
&\qquad\qquad\qquad \circ e^{\lambda^1_3(z^1_3-z^1_1) + \lambda^1_2(z^1_2-z^1_1) + \lambda^2_3(z^2_3-z^2_1) + \lambda^2_2(z^2_2-z^2_1)} \tau. \nn
%\\
% &= -\int_{u_{12}=0}^1 \int_{u_{13}=0}^1 \res_{x_3 \to x_1} \res_{x_2\to x_1} \res_{y_3 \to y_1} \res_{y_2\to y_1}(-)|_{u_{23} = u_{13}}
% \nn\\&\quad
% + \int_{u_{12}=0}^1 \int_{u_{13}=0}^1 \res_{x_2 \to x_1} \res_{x_3\to x_1} \res_{y_2 \to y_1} \res_{y_3\to y_1}(-)|_{u_{32} = u_{12}} \nn\\
% &\qquad\quad + \int_{u_{12}=0}^1 \int_{u_{23}=0}^1 \res_{x_2 \to x_1} \res_{x_3\to x_2} \res_{y_2\to y_1} \res_{y_3\to y_2}(-)|_{u_{31} = u_{21}} \nn\\
\label{jacobiator}
\end{align}
The integrals in these three terms are over, respectively, the yellow, purple and green rectangles in \cref{fig}.

By a direct calculation (using Stokes theorem and the Jacobi relation satisfied by the residue maps) one finds that the solution to the first coherence relation $\mu_3\circ \ddts = \Jac_3$ is in fact unique and is given by
\begin{align*}
    \mu_3(\tau) &= \Biggl(+\int_{u_{23}=0}^1\int_{u_{12}=0}^{u_{23}}\int_{u_{13}=0}^{u_{12}} \res_{z^1_2\to z^1_1}\res_{z^1_3\to z^1_1}\res_{z^2_2\to z^2_1}\res_{z^2_3\to z^2_2}(-)\\
    &\qquad+\int_{u_{13}=0}^1\int_{u_{12}=0}^{u_{13}}\int_{u_{23}=0}^{u_{12}} \res_{z^1_2\to z^1_1}\res_{z^1_3\to z^1_2}\res_{z^2_2\to z^2_1}\res_{z^2_3\to z^2_1}(-)\\
    &\qquad-\int_{u_{12}=0}^1\int_{u_{13}=0}^{u_{12}}\int_{u_{23}=0}^{u_{13}} \res_{z^1_2\to z^1_1}\res_{z^1_3\to z^1_2}\res_{z^2_3\to z^2_1}\res_{z^2_2\to z^2_1}(-)\\
    &\qquad-\int_{u_{23}=0}^1\int_{u_{13}=0}^{u_{23}}\int_{u_{12}=0}^{u_{13}} \res_{z^1_3\to z^1_1}\res_{z^1_2\to z^1_1}\res_{z^2_2\to z^2_1}\res_{z^2_3\to z^2_2}(-)\\
    &\qquad-\int_{u_{13}=0}^1\int_{u_{23}=0}^{u_{13}}\int_{u_{12}=0}^{u_{23}} \res_{z^1_3\to z^1_1}\res_{z^1_2\to z^1_1}\res_{z^2_2\to z^2_1}\res_{z^2_3\to z^2_1}(-)\\
    &\qquad-\int_{u_{12}=0}^1\int_{u_{23}=0}^{u_{12}}\int_{u_{13}=0}^{u_{23}} \res_{z^1_2\to z^1_1}\res_{z^1_3\to z^1_1}\res_{z^2_3\to z^2_1}\res_{z^2_2\to z^2_1}(-)\Biggl)\\
    &\qquad\qquad\qquad \circ e^{\lambda^1_3(z^1_3-z^1_1) + \lambda^1_2(z^1_2-z^1_1) + \lambda^2_3(z^2_3-z^2_1) + \lambda^2_2(z^2_2-z^2_1)} \tau. \nn
\end{align*}
The integrals in these six terms are over the tetrahedra dissecting the cube which are obtained by cutting the cube along the yellow, purple and green rectangles in \cref{fig}.

