\section{Conventions for $\D$-modules}\label{sec: D module background}
In this section we set the notations related to $\D$-modules in this paper. For basic backgrounds on $\D$-modules, we refer to \cite{HTT_Dmodules2008}.
%%Here we follow the presentation and notation in \cite{van2021chiral}.

Let $X$ be a smooth algebraic variety over $\kk$. We denoted by $\omega_X$ the canonical sheaf of $X$. The tangent sheaf $\Theta_X$ acts on $\omega_X$ by minus the Lie derivative, and this extends to a right action of the sheaf of differential operators $\D_X$. More explicitly, for local sections $\tau\in \omega_X, \theta,\theta_1,\dots,\theta_n\in \Theta_X$ ($n=\dim X$)
\[
\left(\mathcal{L}_\theta\tau\right)(\theta_1,\dots,\theta_n):=\theta\left(\tau(\theta_1,\dots,\theta_n)\right)-\sum^n_{i=1}\tau(\theta_1,\dots,[\theta,\theta_i],\dots,\theta_n).
\]
The right $\D_X$-action is then given by $\tau\theta:=-\mathcal{L}_{\theta}\tau.$
Given a left $\D_X$-module $M$, one can form a right $\D_X$-module $M\ox_{\O_X}\omega_X$ via the Leibniz rule
\[
(m\otimes \tau)\theta := m\otimes \tau\theta-\theta m\otimes \tau.
\]
Conversely, for a right $\D_X$-module $M^r$ we can equip $M^r\ox_{\O_X}\omega_X^{-1}$ with a left $\D_X$-module structure using the canonical isomorphism $\D_X^{op}\cong \omega_X\ox_{\O_X}\D_X\ox_{\O_X}\omega_X^{-1}$.

Suppose that we have a morphism $f:X\rightarrow Y$. We denote by $f^{\centerdot}$ and $f_{\centerdot}$ the sheaf-theoretic pullback and pushforward (in \cite{HTT_Dmodules2008}, they use $f^{-1}.f_*$). Define the transfer bimodule $\D_{f}$ by
\[\D_{f} :=\O_X\ox_{f^{\centerdot}\O_Y}f^{\centerdot}\D_Y.\]
It is naturally a right $f^{\centerdot}\D_Y$-module. The left $\D_X$-module structure is given in terms of local coordinates $\{y_i,\del_i\}_{i=1,\dots,\dim Y}$ on $Y$ by
\[
\theta(s\otimes P)=\theta(s)\otimes P+ \sum_{i=1}^{\dim Y}\left(s\theta(y_i\circ f)\right)\otimes\del_iP.
\]

The pullback of a left $\D_Y$-module $M$ is
\[ f^*(M) := \D_{f}\ox_{f^{\centerdot}\D_Y}f^{\centerdot}(M). \]
For a right $\D_Y$-module $M^r$, the pullback is defined to be
\[
f^*(M^r) := \omega_X\ox_{\O_X}\left(\D_{f}\ox_{f^{\centerdot}\D_Y}f^{\centerdot}(\omega^{-1}_Y\ox_{\O_Y}M^r)\right).
\]
To define the pushforward of $\D$-modules, we need to use derived functors. We are mainly interested in the pushforwards of right $\D$-modules. Denote by $D^b(\D^{op}_X)$ the bounded derived category of right $\D_X$-modules. Define a functor $\int_f:D^b(\D^{op}_X)\rightarrow D^b(\D^{op}_Y)$
\[
\int_f N^{\bul}:=Rf_{\centerdot}\left(N^{\bul}\otimes^{L}_{\D_X}\D_{f}\right),\quad N^{\bul}\in D^b(\D^{op}_X),
\]
where we use a flat resolution of $N^{\bul}$ to build $N^{\bul}\otimes^{L}_{\D_X}\D_{f}$ and an injective resolution of $N^{\bul}\otimes^{L}_{\D_X}\D_{f}$ to define $Rf_{\centerdot}$.

If $j:U\hookrightarrow Y$ is an open embedding, then we have $\D_j=j^{\centerdot}\D_Y=\D_U$ and $j^*$ is exact
\[
j^*M=j^{\centerdot}M=M|_{U},
\]
and for the pushforward we have
\[
\smallint_jN^{\bul}=Rj_{\centerdot}\left(N^{\bul}\otimes^{L}_{\D_U}\D_{j}\right)=Rj_{\centerdot}N^{\bul},\quad N^{\bul}\in D^b(\D^{op}_U).
\]
We may have non-trivial higher cohomology groups.
(This is the case for example when $j:\AA^{2}-\{0\}\hookrightarrow\AA^2$.)

If $i: X\hookrightarrow Y$ is a closed embedding of smooth algebraic varieties, then $\D_i$ is a locally free $\D_X$-module and
\[
i_*(N):=H^0\left(\int_iN\right)=i_{\centerdot}\left(N\ox_{\D_X}\D_{f}\right).
\] is exact.

In this paper, we mainly focus on the open inclusion
\[
j^{(k)}:\Conf_k(\AA^n)\hookrightarrow (\AA^n)^k
\]
and the diagonal embedding
\[
\Delta^{(k)}:\AA^n\hookrightarrow (\AA^n)^k.
\]
One of our main results is a construction of a complex of $\DAAnk$-modules $\TS^{k,\bul}_{\AA^n}(M)$ which computes $\Gamma\left((\AA^{n})^k,\smallint_j(j^*M)\right)$, where $M$ is a right $\D$-module.% which is homotopically $\O_{(\AA^n)^k}$-flat (K-flat).

For the diagonal embedding $\Delta^{(k)}:\AA^n\hookrightarrow (\AA^n)^k$, we can write everything explicitly as in \cref{sec: shifted canonical bundle}.

Since we mainly consider $\D$-modules on $(\AA^{n})^k$ which is $\D$-affine (more precisely, is $\D^{op}$-affine since we are considering right $\D$-modules), we will not distinguish the module and its global section.

\section{Construction of the polysimplicial model}%Proof of \cref{thm: polysimplex model NN}}
In this section we prove \cref{thm: polysimplex model NN}. We first recall the definition of the Thom-Sullivan functor $\Th$.
\subsection{Semisimplicial objects}\label{sec: simplicial sets}
Let $\triangle$ denote the category whose objects are the finite totally-ordered sets
\([n] := \{0<1<\dots<n\}, \, n\in \ZZ_{\geq 0}, \nn\)
and whose morphisms are the strictly %weakly
order-preserving maps $\theta: [n] \to [N]$.
% Such maps are generated by \dfn{coface maps},
% \begin{equation} d_j : [n] \to [n+1];\quad i\mapsto \begin{cases} i & i<j \\ i+1 & i\geq j \end{cases} \quad\text{for}\quad j=0,1,\dots,n+1.\nn\end{equation}
% and \dfn{codegeneracy maps},
% \begin{equation} s_j : [n] \to [n-1];\quad i\mapsto \begin{cases} i & i<j \\ i-1 & i\geq j \end{cases} \quad\text{for}\quad
% j=1,\dots,n.\nn\end{equation}
% (These maps obey certain relations; see e.g. \cite[\S8]{Weibel}.)
% We write
% \begin{equation}
% \begin{tikzcd}
%  \dots \quad \left[2\right]
% \rar[<-,shift left=8pt]\rar[<-,shift left=4pt]\rar[<-]\rar[shift right = 4pt]\rar[shift right = 8pt]&
% \left[1\right] \rar[<-,shift left=4pt]\rar[<-] \rar[shift right=4pt]& \left[0\right]
% \end{tikzcd}.
% \nn\end{equation}
A \dfn{semisimplicial object} $Z$ in a category $\C$ is a functor $Z: \triangle^\op\to \C$.  A \dfn{semicosimplicial object} $A$ is a functor $A: \triangle \to \C$.

(\dfn{(Co)simplicial objects} are obtained by taking altering ``strictly order-preserving'' to ``weakly order-preserving'' in the definition above.% One then has (co)degeneracy as well as (co)face maps.
)


\subsection{Polynomial differential forms on the algebro-geometric simplex}\label{sec: omega}
There is a semisimplicial dg commutative algebra
$\Omega:\triangle^\op \to \dgCAlg \nn$
defined as follows.
For each $n\geq 0$, $\Omega([n])$ is the dg commutative algebra
\begin{equation} \Omega([n]) :=  \kk[t_0,\dots,t_n; \dd t_0, \dots \dd t_n]\big/\langle \sum_{i=0}^n t_i -1, \sum_{i=0}^n \dd t_i \rangle \nn\end{equation}
with $t_i$ in degree $0$ and $\dd t_i$ in degree $1$, for each $i$, and equipped with the usual de Rham differential. One should think of $\Omega([n])$ as the complex of polynomial differential forms on the algebro-geometric $n$-simplex.
For any map $\phi: [n] \to [N]$ of $\triangle$, the map
\(\Omega(\phi) : \Omega([N]) \to \Omega([n]) \nn\)
is the map of dg commutative algebras defined by $t_i \mapsto \sum_{j\in \phi^{-1}(i)} t_j$. (The set $\phi^{-1}(i)$ here is either empty or has one element, since for us $\phi$ is \emph{strictly} order-preserving.)


\subsection{The functor $\Th$}\label{sec: Thom-Sullivan functor}
Suppose we are given a functor $A : \triangle \to \CAlg(\dgVect_\kk)$; that is, suppose we are given a semicosimplicial object in dg commutative algebras. One can construct a dg commutative algebra, given by the graded vector space
\begin{align} \Th^\bul(A)  &:= \Tot\biggl\{ \mathbf a = (a_X)_{X\in \Ob(\triangle)} \in \prod_{X \in \Ob(\triangle) } A^\bul(X) \ox \Omega^\bul(X) :\nn\\&\qquad\qquad\qquad
\left(A(\phi) \ox \id \right) a_X
= \left(\id\ox\Omega(\phi)\right) a_Y \quad \text{in}\quad A(Y) \ox \Omega(X)   \nn\\&\qquad\qquad\qquad
\qquad\text{for all maps $\phi:X \to Y$ of $\triangle$} \biggr\}\label{def: Thom-Sullivan functor}
\end{align}
equipped with the differential
\begin{equation} \dd = \dd_A\ox \id + \id \ox \dd_{\text{de Rham}}\nn\end{equation}
and the graded commutative product given by $(a\ox \omega)(b\ox \tau) := (-1)^{\gr \omega \gr b} ab \ox \omega \wedge \tau$.
This defines the action on objects of a functor, the Thom-Sullivan or Thom-Whitney functor, from semicosimplicial dg commutative algebras to dg commutative algebras,
\begin{equation} \Th:[\triangle, \CAlg(\dgVect_\kk)] \to \dgCAlg. \nn\end{equation}
This functor computes (a model of) the homotopy limit of the functor $A$,
\begin{equation} \Th A \simeq \holim A .\nn\end{equation}
See \cite{HS} and e.g. \cite{Manetti}, \cite[Appendix A]{Kapranov}, \cite[Appendix A]{FHK}.

\subsection{Cech cohomology}\label{sec: cech cohomology}
Let $\I := \Hom_\Set\left(\{ (i,j)\}\ijk , \{1,\dots,n\}\right)$ denote the set of all ordered partitions of the set $\{(i,j)\}\ijk$ into $n$ disjoint subsets: if $X\in \I$ then
\begin{equation} \{(i,j)\}\ijk = X^1\sqcup \dots \sqcup X^n, \quad\text{where}\quad X^r := X^{-1}(r)\quad\text{for each}\quad r.\nn\end{equation}
For each $X\in \I$, let us set
\begin{equation} U_X := (\AA^{n})^k\setminus \bigcup_{(i,j) \in X_1} \{z^1_i=z^1_j\} \setminus \dots \setminus \bigcup_{(i,j)\in  X_n} \{z^n_i=z^n_j\}. \nn\end{equation}
Then $\mc U := (U_X)_{X\in \I}$ is an open cover of
\begin{equation} \Conf_k(\AA^n)  := (\AA^{n})^k \setminus \bigcup\ijk \{z^1_i=z^1_j,\dots,z^n_i=z^n_j\}\nn. \end{equation}
The sets $U_X$ of this cover and all their intersections are affine schemes: for every tuple $(X_1,\dots,X_K) \in \I^K$ we have
$U_{X_1} \cap \dots \cap U_{X_K} =  \Spec \Gamma(U_{X_1} \cap \dots \cap U_{X_K},\O)$
where
\begin{align} &\Gamma(U_{X_1} \cap \dots \cap U_{X_K},\O) \label{OUXXX} %\\&\quad
= \bigotimes_{r=1}^n \kk[z^r_1,\dots,z^r_k]\left[ \prod_{(i,j) \in \bigcup_{p=1}^K X^r_p} (z^r_i-z^r_j)^{-1}\right]  .
\end{align}
So $\mc U$ is a Leray cover: it is sufficiently refined that the Cech complex of $\O$ with respect to $\mc U$ computes the sheaf cohomology of the structure sheaf $\O$.
Recall that the usual Cech complex is the cochain complex which computes the homotopy limit in dg vector spaces of the diagram
\begin{equation} \Gamma(\Cech(\mc U),\O) = \left(
\begin{tikzcd}
\dots \quad %\prod_{\substack{(X,Y,Z) \in \I^3\\ X<Y<Z}} \O(U_X \cap U_Y \cap U_Z)
%\rar[<-,shift left=8pt]\rar[<-,shift left=4pt]\rar[<-]\rar[->,shift right = 4pt]\rar[->,shift right = 8pt]&
\rar[<-,shift left=4pt]\rar[<-,shift left=0pt]\rar[<-,shift right = 4pt]&
\prod_{\substack{(X,Y)\in \I^2\\X<Y}} \Gamma(U_X \cap U_Y,\O)
%\rar[<-shift left=4pt]\rar[<-] \rar[->,shift right=4pt]&
\rar[<-,shift left=2pt]\rar[<-,shift right=2pt]&
\prod_{X\in \I} \Gamma(U_X,\O)
\end{tikzcd}\right).
\nn
\end{equation}
Here we pick and fix any total ordering $<$ on the index set $\I$. But this is also a diagram in dg commutative algebras and we want to compute its homotopy limit there. The Thom-Sullivan functor allows us to do this, because this diagram is given by a semicosimplicial object, i.e. the indexing category is $\triangle$ and $\Gamma(\Cech(\mc U),\O)$ the functor
\begin{equation} \triangle \xrightarrow{\Gamma(\Cech(\mc U),\O)}  \CAlg(\dgVect_\kk) \label{gammacech}\end{equation}
whose action on objects is
\begin{equation} \Gamma(\Cech(\mc U),\O)([p]) := \prod_{\substack{(X_0,\dots,X_p)\in \I^{p+1}\\ X_0<\dots<X_p}} \Gamma\left(\bigcap_{i=0}^p U_{X_i},\O\right). \nn\end{equation}
Thus, we have that
\begin{equation} R\Gamma(\Conf_k(\AA^n),\O)\simeq \holim \Gamma(\Cech(\mc U),\O)  \simeq \Th\left( \Gamma(\Cech(\mc U),\O) \right).\label{Th computes RGamma}\end{equation}
The dg commutative algebra $\Th\left( \Gamma(\Cech(\mc U),\O)\right)$ has an intuitively natural geometric interpretation as a dg algebra of forms on the $N$-simplex, where
\[N:= |\I|-1,\]
as we shall now describe.

First, observe that the functor $\Gamma(\Cech(\mc U),\O)$ in \cref{gammacech} sends $[p] \mapsto \mathbf 0$ for all $p > N$ and it sends $[N] \mapsto \Gamma\left(\bigcap_{X\in \I} U_X,\O\right)= \kk[z^r_i,(z^r_j-z^r_\ell)^{-1}]^{1\leq r\leq n}_{1\leq i\leq k; 1\leq j<\ell<k}$. Indeed, we picked a totally ordered cover $\mc U$ consisting of $|\I|=N+1<\8$ many open sets. So there \emph{are} no strictly ordered tuples of $p>|\I|$ of opens from our cover.
(Here it matters that we are working with a totally ordered cover and therefore with \emph{semi}(co)simplicial objects.)

Now, we may regard the power set $2^\I$ as a poset and hence as a category. Our choice of total order $<$ on $\I$ defines an identification of $2^\I$ with the overcategory $\triangle/\topsimplex$.\footnote{Recall that the overcategory $\triangle/\topsimplex$ is the category in which an object is an object $[n]$ of $\triangle$ together with a morphism $[n]\to \topsimplex$ of $\triangle$, and a morphism from $[n] \to \topsimplex$ to $[m] \to \topsimplex$ is a morphism $[n]\xrightarrow\phi [m]$ of $\triangle$ such that the diagram
\[\begin{tikzcd}[ampersand replacement = \&]\left[n\right] \arrow{rr}{\phi}\drar \& \& \left[m\right] \dlar \\ \& \topsimplex \&  \end{tikzcd}\]
commutes. The identification with the poset $2^\I$ is by picking a bijection $[N] \isom \I$, which amounts to picking a total order on $\I$.} The latter is, intuitively speaking, the category of facets of the $N$-simplex.
We have the functor
\begin{equation} 2^\I \cong \triangle/\topsimplex \xrightarrow{F} \CAlg(\dgVect_\kk)  \nn\end{equation}
whose action on objects is
\begin{equation} F(\mc J) := \Gamma\left(\bigcap_{X \in \mc J} U_{X},\O\right),\qquad \mc J \subset \mc I.\nn\end{equation}
The forgetful functor $2^\I \to \triangle$ sends $\mc J\mapsto [|\mc J|-1]$ for each $\mc J\subset \I$.
(The functor $\Gamma(\Cech(\mc U),\O)$ is actually the left Kan extension of $F$ along this forgetful functor.)

On inspection of the definitions \cref{def: Thom-Sullivan functor} and \cref{gammacech}, one sees that $\Th^\bul(\Gamma(\Cech(\mc U), \O))$ is equivalently given by
\begin{align} &\Th^\bul(\Gamma(\Cech(\mc U), \O))\label{ontheNsimplex} \\  &\cong \Tot\biggl\{ \mathbf a = (a_\mc J)_{\mc J\in \Ob(\triangle/[N])} \in \prod_{\mc J \in \Ob(\triangle/[N]) } F^\bul(\mc J) \ox \Omega^\bul([|\mc J|-1]) :\nn\\&\qquad\qquad\qquad
\left(F(\phi) \ox \id \right) a_\mc J
= \left(\id\ox\Omega(\phi)\right) a_\mc K \quad \text{in}\quad F(\mc K) \ox \Omega([|\mc J|-1])   \nn\\&
\qquad\qquad\qquad\qquad\qquad\qquad\text{whenever there is a map $\phi:\mc J \to \mc K$ of $\triangle/[N]$}\biggr\}.
\nn\end{align}
In words, this just says that an element of $\Th^\bul(\Gamma(\Cech(\mc U), \O))$ is equivalent to the data of a $F(\mc J)$-valued polynomial differential form on the facet labelled by $\mc J$ of the $N$-simplex, for each such facet, subject to the compatibility conditions that whenever $\mc J\subset \mc K$ the pullback of the form on the facet labelled by $\mc K$ to the facet labelled by $\mc J$ must agree with the image, under the application of the sheaf restriction map $\Gamma(\bigcap_{X\in \mc J} U_{X},\O)  \to \Gamma(\bigcap_{X\in \mc K} U_{X},\O)$, of the form on the facet labelled by $\mc J$.

Moreover, the algebra maps \(\Gamma(\bigcap_{X\in \mc J} U_X,\O) \into \Gamma\left(\bigcap_{X\in \I} U_X,\O\right)\) are injective, for all $\mc J\subset \mc I$. That means once the form on the top facet, labelled $\I$, is fixed, then all the forms on lower dimensional facets are fixed too.
Thus $\Th^\bul\left( \Gamma(\Cech(\mc U),\O)\right)$ is equivalently the dg commutative algebra of $\Gamma\left(\bigcap_{X\in \I} U_X,\O\right)$-valued polynomial differential forms on the algebro-geometric $N:=(|\I|-1)$-simplex, obeying certain boundary conditions:
\begin{align} \Th^\bul\left( \Gamma(\Cech(\mc U),\O) \right) &\cong \biggl\{ \tau \in \Gamma\left(\bigcap_{X\in \I} U_X,\O\right) \ox \kk[t_X; \dd t_X]_{X\in \I}\big/\langle \sum_{X\in \I} t_X -1, \sum_{X\in \I} \dd t_X \rangle  \label{boundaryconditions}\\
&\quad :\text{ $\tau|_{\bigcap_{X\in \mc I \setminus \mc J}(t_{X} = 0)}$ has coefficients in $\Gamma\left(\bigcap_{X\in \mc J} U_{X},\O\right)$ for all $\mc J \subset \mc I$} \biggr\}.\nn
\end{align}
(Cf. \cref{ontheNsimplex}, where the tuple $\mathbf a$ consists of such a form $\tau$ together with all its pullbacks to facets of the $N$-simplex.)

This much is true for any Leray cover $\mc U = \{U_X\}_{X\in \I}$ of finite cardinality $N+1=|\I|$. But in our case one can do rather better because $\Gamma(U_{X_1} \cap \dots \cap U_{X_K},\O)$ depends on the tuple of set partitions $X_1,\dots,X_K$ only through
\begin{equation} \bigcup_{p=1}^K X^1_p, \quad\bigcup_{p=1}^K X^2_p,\quad \dots, \quad\bigcup_{p=1}^K X^n_p, \nn\end{equation} as one sees in \cref{OUXXX}. It follows that the boundary conditions on $\Th\left( \Gamma(\Cech(\mc U),\O) \right)$ are nonempty only for facets of the $(|\I|-1)$-simplex on which at least one of these unions fails to be the full set $\{(i,j)\}\ijk$. The facets of highest dimension on which this happens are those for which, for precisely one direction $r$, $1\leq r\leq n$, and for precisely one pair of the marked points, with indices say $(i,j)$, $1\leq i<j\leq k$, the union $\bigcup_{p=1}^K X^r_p$ fails to contain $(i,j)$. (Such a facet corresponds to an intersection of opens in which it may happen that $z^r_i=z^r_j$, for this specific pair of points $(i,j)$ and this specific direction $r$ only.) Moreover, one sees that all boundary conditions on facets of lower dimensions follow from taking intersections of these. Reasoning in this way, one checks that
\begin{subequations}\label{ThSimplex}
\begin{equation} \Th\left( \Gamma(\Cech(\mc U),\O) \right)\cong \Th^k_{\AA^n} \end{equation}
where
\begin{align} \Th^k_{\AA^n}&:= \biggl\{ \tau \in \kk[z^r_i,(z^r_j-z^r_\ell)^{-1}]^{1\leq r\leq n}_{1\leq i\leq k; 1\leq j<\ell<k}  \nn\\&\qquad\qquad\ox \kk[t_X; \dd t_X]_{X\in \I}\big/\langle \sum_{X\in \I} t_X -1, \sum_{X\in \I} \dd t_X \rangle  \\
&\qquad\quad : \text{$\tau|_{\bigcap_{X\in \I: X^r \ni (i,j)}(t_{X} = 0)}$ is regular in $(z^r_i-z^r_j)$}\nn\\ & \quad\qquad\qquad\text{for all $1\leq i<j\leq k$ and all $1\leq r\leq n$}  \biggr\}. \nn
\end{align}
\end{subequations}
\begin{rem}
    The construction $\Th\left( \Gamma(\Cech(\mc U),\mathcal{E}) \right)$ works for any quasi-coherent sheaf $\mathcal{E}$ on $\Conf_k(\AA^n)$. However, we will not have the above simplification if $\mathcal{E}$ is not locally free.
\end{rem}
\subsection{Proof of \cref{thm: polysimplex model NN}}\label{sec: proof of polysimplex model NN}
In view of \cref{ThSimplex}, \cref{thm: polysimplex model NN} now follows from \cref{Th computes RGamma} together with the following lemma.

\begin{prop}\label{prop: retract of simplex to polysimplex}
There is a deformation retract of dg vector spaces, in which both $\id\ox\pi^*$ and $\id\ox\iota^*$ are maps of dg commutative algebras,
\begin{equation}\begin{tikzcd}
\TS_{\AA^n}^k  \rar[shift left]{\id\ox\pi^*}  & \lar[shift left]{\id\ox\iota^*}
\ar[loop right,""] \Th_{\AA^n}^k \end{tikzcd}.\nn\end{equation}
%where $\TS_{\AA^n}^k$ is the dg commutative algebra defined in \cref{sec: higher configuration space and movable punctures in two complex dimensions}.
Recall the definition of $\TS_{\AA^n}^k$ from \cref{sec: higher configuration space and movable punctures in two complex dimensions},
\begin{align} \TS_{\AA^n}^{k,\bul}  := &\bigl\{ \tau \in
 \kk[z^r_i,(z^r_j-z^r_\ell)^{-1}]^{1\leq r\leq n}_{1\leq i\leq k; 1\leq j<\ell<k} \ox \Omega(\triangle_{n-1}^{\times \binom k 2}) \nn\\
& \quad :          \text{$\tau|_{u^r_{ij}=0}$ is regular in $(z^r_i-z^r_j)$,  for $1\leq r\leq n$ and $1\leq i<j\leq k$} \bigr\}. \nn
\end{align}

\end{prop}
\begin{proof} Recall that $\I = \{1,\dots,n\}^S$ is the set of ordered partitions into $n$ parts of a set $S$. Let $m=|S|$, so $|\I|= n^m$.

(In our case $S$ is actually the set $\{(i,j): 1\leq i<j\leq k\}$ and $m= \binom k 2$.)

Let $\pi^*$ and $\iota^*$ be the maps of dg commutative algebras
\begin{equation}\begin{tikzcd}
\kk[u^r_\alpha, \dd u^r_\alpha]^{1\leq r\leq n}_{\alpha \in S} \rar[shift left]{\pi^*}  &\lar[shift left]{\iota^*} \kk[t_X, \dd t_X]_{X\in \I}
\end{tikzcd}\nn
\end{equation}
defined by setting
\begin{equation} \pi^*(u^r_\alpha) := \sum_{\substack{X \in \I  \\ X^r \ni \alpha }} t_X\qquad\text{and}\qquad \iota^*(t_X) := \prod_{r=1}^n \prod_{\alpha \in X^r} u^r_\alpha .\nn\end{equation}
Let us also write \[ t_X^*:=\pi^*(\iota^*(t_X)) \quad\text{and}\quad t_X^\lambda:=\lambda t_X + (1-\lambda) t_X^*,\]
and define a $\kk$-linear map $h:\kk[t_X, \dd t_X]_{X\in \I} \to \kk[t_X, \dd t_X]_{X\in \I}$ by setting
\begin{align}
    &h(t_{X_1} \dots t_{X_p} \dd t_{X'_{1}} \dots \dd t_{X'_{q}})\nn\\ &:= \int_{\lambda=0}^1 \tl_{X_1} \dots \tl_{X_p}\sum_{s=1}^q(-1)^{s-1}(t_{X'_{s}}-t_{X'_{s}}^*)\dd\tl_{X'_{1}} \dots \widehat{\dd\tl_{X'_{s}}} \dots \dd\tl_{X'_{q}} \dd\lambda,\nn
\end{align}
for any collection of $p\geq 0$ elements $X_1,\dots,X_p \in \mc I$ and any collection of $q\geq 0$ pairwise distinct elements $X'_1,\dots,X'_q \in \mc I$.

Let $\mathscr I$ and $\mathscr K$ denote  the dg ideals which define $\Omega(\triangle_{n^m-1})$ and  $\Omega(\triangle_{n-1}^{\times m})$ respectively:
\begin{align} \mathscr I& :=\left< \sum_{X\in \I} t_X-1 ,\sum_{X\in\I} \dd t_X\right>\subset \kk[t_X,\dd t_X]_{X\in \I}\nn\\
\mathscr K&:=\left< \sum_{r=1}^n u^r_\alpha-1,\sum_{r=1}^n \dd u^r_\alpha\right>_{\alpha\in S}\subset \kk[u^r_\alpha,\dd u^r_\alpha]^{1\leq r\leq n}_{\alpha \in S}\nn
\end{align}
Let us introduce also the dg ideals, for each $1\leq r\leq n$ and $\alpha \in S$,
\begin{align}\mathscr I^r_\alpha &:= \bigl< t_X, \dd t_X \bigr>_{X\in \I: X^r\ni \alpha} \subset \kk[t_X,\dd t_X]_{X\in \I}\nn\\
\mathscr K^r_\alpha &:= \left< u^r_\alpha, \dd u^r_\alpha\right> \subset \kk[u^s_\beta,\dd u^s_\beta]^{1\leq s\leq n}_{\beta\in S}.\nn
\end{align}
To prove \cref{prop: retract of simplex to polysimplex} it is enough to establish the claims of \cref{lem: retract} below.
Indeed, parts (i) and (iii) imply that the maps $\pi^*$, $\iota^*$ and $h$ induce well-defined maps
\begin{equation}\begin{tikzcd} \Omega^\bul(\triangle_{n-1}^{\times m})
\rar[shift left]{\pi^*}  & \lar[shift left]{\iota^*}
 \ar[loop right,"h"] \Omega^\bul(\triangle_{n^m-1})   \end{tikzcd}\label{hrt}\end{equation}
(whose names we keep the same, by a slight abuse).
Parts (ii) and (iv) ensure that this diagram is a deformation retract.

It remains to show that the maps respect the defining boundary conditions of $\TS_{\AA^n}^k$ and  $\Th_{\AA^n}^k$. This is the content of parts (v) and (vi). Indeed, the boundary conditions of $\Th_{\AA^n}^k$ can be expressed as the statement that $\tau \in \kk[z^r_i,(z^r_j-z^r_\ell)^{-1}]^{1\leq r\leq n}_{1\leq i\leq k; 1\leq j<\ell<k} \ox \kk[t_X; \dd t_X]_{X\in \I}\big/\mathscr I$ belongs to $\Th_{\AA^n}^k$ if and only if, for each $1\leq r\leq n$ and each $(i,j) \in S$, the $\D$-module residue $\res_{z^r_{i}-z^r_{j}} \tau$ has coefficients in (the image in $\Omega(\Delta_{n^m-1})$ of) the ideal $\mathscr I^r_{(ij)}$; and similarly for $\TS_{\AA^n}^k$.
\end{proof}
\begin{lem}\label{lem: retract} The maps $\pi^*$, $\iota^*$ and $h$ are such that:
\begin{enumerate}[(i)]
\item $\pi^*(\mathscr K) \subset \mathscr I$ and $\iota^*(\mathscr I) \subset \mathscr K$
\item $\iota^*(\pi^*(u^r_\alpha)) \equiv u^r_\alpha \mod \mathscr K$ for each $1\leq r\leq n$ and each $\alpha\in S$
\item $h(\mathscr I) \subset \mathscr I$
\item $\pi^*\circ\iota^* - \id = [h,\dd]$ as an equality of $\kk$-linear maps $\kk[t_X,\dd t_X]_{X\in \I}\to\kk[t_X,\dd t_X]_{X\in \I}$
\item $\iota^*(\mathscr I^r_\alpha) \subset \mathscr K^r_\alpha$ and $
\pi^*(\mathscr K^r_\alpha) \subset \mathscr I^r_\alpha$ for each $1\leq r\leq n$ and $\alpha\in S$
\item  $h(\mathscr I^r_\alpha) \subset \mathscr I^r_\alpha$ for each $1\leq r\leq n$ and $\alpha\in S$.
\end{enumerate}
\end{lem}
\begin{proof}
We observe that
\(\iota^*(\sum\limits_{X \in \I } t_X) = \sum\limits_{X \in \I} \prod\limits_{r=1}^n \prod\limits_{\alpha \in X^r}u^r_\alpha = \prod\limits_{\alpha \in S} \sum\limits_{r=1}^n u^r_\alpha
    \label{IdSimplex}
\)
and, for each $\alpha \in S$,
\(\pi^*(\sum\limits_{r=1}^nu^r_\alpha) = \sum\limits_{r=1}^n \sum\limits_{\substack{X \in \I  \\ X^r \ni \alpha }} t_X = \sum\limits_{X \in \I} t_X.\nn\) This establishes part (i).

Now, in fact
\(\iota^*(\sum\limits_{X \in \{1,\dots,n\}^{S'} } t_X) = \sum\limits_{X \in \{1,\dots,n\}^{S'}} \prod\limits_{r=1}^n \prod\limits_{\alpha \in X^r}u^r_\alpha = \prod\limits_{\alpha \in S'} \sum\limits_{r=1}^n u^r_\alpha
\) holds
for any subset $S'\subset S$ of the index set $S$. In particular this holds for the subset $S\setminus \{\alpha\}$ for any $\alpha \in S$. It follows that for every $\alpha \in S$, we have
$$
\iota^*(\pi^*(u^r_\alpha)) =\sum_{\substack{X \in \I  \\ X^r \ni \alpha }}\prod_{p=1}^n \prod_{\beta \in X^p}u^p_\beta%\nn\\&
=u^r_\alpha \sum_{\substack{X \in \{1,\dots,n\}^{S\setminus\{\alpha\}} }}\prod_{p=1}^n \prod_{\beta \in X^p}u^p_\beta
=u^r_\alpha \prod_{\beta \in S\setminus\{\alpha\}} \sum_{r=1}^n u_\beta^r
.
$$ This establishes part (ii).

We turn to the statements (iii) and (iv) about the homotopy, whose definition is similar in spirit to homotopies used in \cite{AlfonsiYoung} (morally the definition is ``$h= \int_{\iota(\pi(*))}^*$'').

Consider part (iii). We must show that $h(\mathscr I) \subset \mathscr I$. As we have already checked,   $\sum\limits_{X \in \I} t^*_X-1$ and $\sum\limits_{X \in \I} \dd t^*_X$ belong to $\mathscr I$. Therefore $\sum\limits_{X \in \I} t^\lambda_X-1$ and $\sum\limits_{X \in \I} \dd t^\lambda_X$
%both belong to the ideal generated by $\sum_{X\in \I} t_X-1$ and $\sum_{X\in \I} \dd t_X$ in $\kk[t_X, \dd t_X,]_{X\in \I}[\lambda,\dd\lambda]$. That is, they
are polynomials in $\lambda$ and $\dd\lambda$ whose coefficients lie in $\mathscr I$. In this way, we observe that in the expressions
\begin{align}
    &h\biggl(\bigl(\sum_{X\in \I} t_X-1\bigr)t_{X_1} \dots t_{X_p} \dd t_{X'_{1}} \dots \dd t_{X'_{q}}\biggr)\nn\\ &= \int_{\lambda=0}^1 \bigl(\sum_{X\in \I} t^\lambda_X-1\bigr)\tl_{X_1} \dots \tl_{X_p}\sum_{s=1}^q(-1)^{s-1}(t_{X'_{s}}-t_{X'_{s}}^*)\dd\tl_{X'_{1}} \dots \widehat{\dd\tl_{X'_{s}}} \dots \dd\tl_{X'_{q}} \dd\lambda\nn,
\end{align}
and
\begin{align}
    &h\biggl(t_{X_1} \dots t_{X_p} \dd \bigl(\sum_{X\in \I} t_X\bigr) \dd t_{X'_{1}} \dots \dd t_{X'_{q}}\biggr)\nn\\
&=  \int_{\lambda=0}^1 \tl_{X_1} \dots \tl_{X_p}
\bigl(\sum_{X\in \I} (t_{X}-t_{X}^*)\bigr) \dd\tl_{X'_{1}} \dots \widehat{\dd\tl_{X'_{s}}} \dots \dd\tl_{X'_{q}} \dd\lambda\nn\\&
\quad
+\int_{\lambda=0}^1 \tl_{X_1} \dots\tl_{X_p}\bigl(\sum_{X\in \I} \dd t_X^\lambda \bigr)\sum_{s=1}^q(-1)^{s}(t_{X'_{s}}-t_{X'_{s}}^*)\dd\tl_{X'_{1}} \dots \widehat{\dd\tl_{X'_{s}}} \dots \dd\tl_{X'_{q}} \dd\lambda\nn
\end{align}
the integrands are polynomials in $\lambda$ with coefficients in $\mathscr I$.
%(Note that $\sum_{X\in \I} (t_{X}-t_{X}^*)\bigr) = \sum_{X\in \I} ((t_{X}-1)-(t_{X}^*-1))\bigr)$.)
The integral $\int_{\lambda=0}^1P(\lambda) \dd \lambda$ of any such polynomial $P(\lambda) \in \mathscr I[\lambda]$ belongs to $\mathscr I$. This completes the proof of part (iii).

We turn to part (iv). %Let us consider $h\circ\dd+\dd\circ h$, as a $\kk$-linear map $\kk[t_X, \dd t_X]_{X\in \I} \to \kk[t_X, \dd t_X]_{X\in \I}$.
We have \[\dd(t_{X_1} \dots t_{X_p} \dd t_{X'_{1}} \dots \dd t_{X'_{q}}) = \sum_{r=1}^p  t_{X_1} \dots \widehat{t_{X_r}} \dots t_{X_s} \dd t_{X_r} \dd t_{X'_{1}} \dots \dd t_{X'_{q}}\]
and hence
\begin{align}
    &h(\dd(t_{X_1} \dots t_{X_p} \dd t_{X'_{1}} \dots \dd t_{X'_{q}}))\nn\\
& = \int_0^1 \sum_{r=1}^p \tl_{X_1} \dots \wh{\tl_{X_r}} \dots \tl_{X_p} \nn \\
   &\quad\left((t_{X_r}-t_{X_r}^*) \dd\tl_{X'_{1}} \dots  \dd\tl_{X'_{q}} - \sum_{s=1}^q (-1)^{s-1}(t_{X'_{s}}-t_{X'_{s}}^*) \dd\tl_{X_r} \dd\tl_{X'_{1}} \dots \widehat{\dd\tl_{X'_{s}}} \dots \dd\tl_{X'_{q}} \right)\dd\lambda \nn
\end{align}
and similarly
\begin{align}
    &\dd (h(t_{X_1} \dots t_{X_p} \dd t_{X'_{1}} \dots \dd t_{X'_{q}}))\nn\\
&= \dd \int_{\lambda=0}^1 \tl_{X_1} \dots \tl_{X_p}\sum_{s=1}^q(-1)^{s-1}(t_{X'_{s}}-t_{X'_{s}}^*)\dd\tl_{X'_{1}} \dots \widehat{\dd\tl_{X'_{s}}} \dots \dd\tl_{X'_{q}} \dd\lambda,\nn\\
&= \int_0^1 \sum_{r=1}^p  \tl_{X_1} \dots \wh{\tl_{X_r}} \dots \tl_{X_p} \sum_{s=1}^q(-1)^{s-1} (t_{X'_{s}}-t_{X'_{s}}^*) \dd \tl_{X_r} \dd \tl_{X'_{1}} \dots \widehat{\dd \tl_{X'_{s}}} \dots \dd \tl_{X'_{q}} \dd \lambda \nn \\
    &\qquad +\int_0^1 \tl_{X_1} \dots \tl_{X_p} \sum_{s=1}^q(-1)^{s-1} (\dd t_{X'_{s}}-\dd t_{X'_{s}}^*) \dd \tl_{X'_{1}} \dots \widehat{\dd \tl_{X'_{s}}} \dots \dd \tl_{X'_{q}} \dd \lambda. \nn
\end{align}
In this way, one finds that
\begin{align}
    &h(\dd (t_{X_1} \dots t_{X_p} \dd t_{X'_{1}} \dots \dd t_{X'_{q}})) + \dd h(t_{X_1} \dots t_{X_p} \dd t_{X'_{1}} \dots \dd t_{X'_{q}}) \nn \\
    &= \int_0^1 \sum_{r=1}^p  \tl_{X_1} \dots \wh{\tl_{X_r}} \dots \tl_{X_p}(t_{X_r}-t_{X_r}^*) \dd \tl_{X'_{1}} \dots  \dd \tl_{X'_{q}} \dd \lambda \nn \\
    &\qquad +\int_0^1 \tl_{X_1} \dots \tl_{X_p} \sum_{s=1}^q \dd \tl_{X'_{1}} \dots (\dd t_{X'_{s}}-\dd t_{X'_{s}}^*) \dots \dd \tl_{X'_{q}} \dd \lambda. \nn \\
    &= \int_0^1 \frac{d}{d\lambda}\left( \tl_{X_1} \dots \tl_{X_p}
   \dd \tl_{X'_{1}} \dots  \dd \tl_{X'_{q}}  \right)\dd \lambda \nn \\
   &\qquad = t_{X_1} \dots t_{X_p} \dd t_{X'_{1}} \dots \dd t_{X'_{q}} - t^*_{X_1} \dots t^*_{X_p} \dd t^*_{X'_{1}} \dots \dd t^*_{X'_{q}} \nn.
\end{align}
This establishes that
\begin{equation} h\circ\dd + \dd\circ h = \id  - \pi^*\circ \iota^* \nn\end{equation}
as an equality of $\kk$-linear endomorphisms of $\kk[t_X,\dd t_X]_{X\in \I}$, which is part (iv).

Part (v) is clear on inspection.

The argument for part (vi) is parallel to that for part (iii), as follows. Consider any generator $t_Y$ of $\mathscr I^r_\alpha$, i.e. pick any $Y\in \I$ be such that $Y^r\ni \alpha$. It follows from part (v) that $t_Y^* \in \mathscr I^r_\alpha$ also. Therefore $t_Y-t_Y^*\in \mathscr I^r_\alpha$ and hence $t^\lambda_Y \in \mathscr I^r_\alpha[\lambda,\dd \lambda]$. Then one argues as for part (iii) that, for any $p\in \kk[t_X,\dd t_X]_{X\in \I}$, $h(t_Y p)$ and $h(\dd t_Y p)$ are both integrals of polynomials in $\lambda$ with coefficients in $\mathscr I^r_\alpha$ and therefore belong to $\mathscr I^r_\alpha$. Thus $h(\mathscr I^r_\alpha)\subset \mathscr I^r_\alpha$, which is part (vi).

The proof of \cref{lem: retract} is complete.
\end{proof}

This completes the proof of \cref{prop: retract of simplex to polysimplex} and hence of \cref{thm: polysimplex model NN}.

\subsection{Proof of \cref{thm: F model}}\label{sec: proof of F model}
For any complex $\G$ of quasi-coherent sheaves on $(\AA^{n})^k$, one defines the ordered Cech sheaf (complex) $\mathfrak{C}_{ord}^{p}(\mathcal{U},j^*\G)$ on $\Conf_k(\AA^n)$ as follows
\[
\mathfrak{C}_{ord}^{\bullet}(\mathcal{U},j^*\G):=\prod_{\substack{(X_0,\dots,X_p)\in \I^{p+1}\\ X_0<\dots<X_p}} (j_{X_0\cdots X_p})_*\left(j^*\G\right)|_{\bigcap_{i=0}^p U_{X_i}}=\prod_{\substack{(X_0,\dots,X_p)\in \I^{p+1}\\ X_0<\dots<X_p}} (j_{X_0\cdots X_p})_*\G|_{\bigcap_{i=0}^p U_{X_i}},
\]
here $\quad j_{X_0\cdots X_p}:\bigcap_{i=0}^p U_{X_i}\hookrightarrow \Conf_k(\AA^n).
$ Taking global sections, we get the usual ordered Cech complex
\[
\Gamma\left((\AA^{n})^k,j_*\mathfrak{C}_{ord}^{\bullet}(\mathcal{U},j^*\G)\right)=\Gamma\left(\Conf_k(\AA^n) ,\mathfrak{C}_{ord}^{\bullet}(\mathcal{U},j^*\G)\right)=\Cech_{ord}^{\bullet}(\mc U,j^*\G),
\]
\[
\Cech_{ord}^{p}(\mc U,j^*\G)=\prod_{\substack{(X_0,\dots,X_p)\in \I^{p+1}\\ X_0<\dots<X_p}}\G({\bigcap_{i=0}^p U_{X_i}}).
\]
Since $(\AA^{n})^k$ is affine, we have $j_*\mathfrak{C}_{ord}(\mathcal{U},j^*\G)=\underline{\Cech_{ord}^{\bullet}(\mc U,j^*\G)}$. The integration along simplices gives rise to a quasi-isomorphism (see \cite[Theorem 7.4.5]{Manetti} or \cite[(4.4.1)]{hinich2006homotopy})
\[
\int_{\triangle}:\Th\left( \Gamma(\Cech(\mc U),j^*\G) \right)\xrightarrow{\sim}\Cech_{ord}^{\bullet}(\mc U,j^*\G) .
\]
Since the cover $\mathcal{U}$ is finite, the double complex $\Cech_{ord}^{\bullet}(\mc U,j^*\G)$ (thus $\Th\left( \Gamma(\Cech(\mc U),j^*\G) \right)$) computes $R\Gamma\left(\Conf_k(\AA^n),\G\right)$ without any boundedness condition on $\G$ (see  \cite[\href{https://stacks.math.columbia.edu/tag/08BZ}{Tag 08BZ}]{stacks-project}). And if $\G\xrightarrow{\sim}\M$ is a quasi-isomorphism of complexes of quasi-coherent sheaves, we have the induced quasi-isomorphism (see \cite[Lemma 7.4.3]{Manetti})
\[
\Th\left( \Gamma(\Cech(\mc U),j^*\G)\right)\xrightarrow{\sim}\Th\left( \Gamma(\Cech(\mc U),j^*\M)\right).
\]
Now suppose that $\F$ is a bounded complex of $\D_{(\AA^{n})^k}$-modules with quasi-coherent cohomology. By a theorem by Bernstein \cite[1.5.7]{HTT_Dmodules2008} we can find a bounded complex $\G$ of quasi-coherent $\D_{(\AA^{n})^k}$-modules quasi-isomorphic to $\F$. Then we can find a bounded above complex of locally free $\D_{(\AA^{n})^k}$-modules $\M$ which resolves $\G$, cf. \cite[1.4.20]{HTT_Dmodules2008}. The claim that $\Tot\left(\underline{\TS_{\AA^n}^{k}} \ox_{\O_{(\AA^{n})^k}} \F\right)\sim \int_jj^*\F$ follows from the following diagram.
\[
\begin{tikzcd}
\Tot\left(\underline{\TS_{\AA^n}^{k}} \ox_{\O_{(\AA^{n})^k}} \F\right) \rar["\sim"] & \Tot\left(\underline{\TS_{\AA^n}^{k}} \ox_{\O_{(\AA^{n})^k}} \G\right)\dar["\sim"]  & \lar["\sim"] \Tot(\underline{\TS_{\AA^n}^k} \ox_{\O_{(\AA^{n})^k}} \M) \dar["\sim"] \\
 %\rar
& \Tot(\underline{\Th_{\AA^n}^k} \ox_{\O_{(\AA^{n})^k}} \G) \dar["i"] & \lar["\sim"]\Tot(\underline{\Th_{\AA^n}^k} \ox_{\O_{(\AA^{n})^k}} \M)\dar["\cong"] \\
\int_jj^{*}\F\sim \int_jj^{*}\G \rar["\sim"]& \underline{\Th\left( \Gamma(\Cech(\mc U),j^*\G) \right) } & \lar["\sim"] \underline{\Th\left( \Gamma(\Cech(\mc U),j^*\M) \right) }
\end{tikzcd}
\]
In this diagram,
\begin{enumerate}[-]
 \item Every arrow respects $\D_{(\AA^{n})^k}$-module structures.
 \item The arrows in the first row are quasi-isomorphisms. This is because $\TS_{\AA^n}^k$ is a bounded complex of flat $\O_{(\AA^{n})^k}$-modules. (We prove flatness in \cref{lem: FlatE}, cf. \cref{thm: TSIE gens and rels}). Therefore it is K-flat. (See \cite[\href{https://stacks.math.columbia.edu/tag/06Y7}{\S06Y7}]{stacks-project}.)
 \item The first two vertical arrows are quasi-isomorphisms since $\underline{\TS_{\AA^n}^{k}} $ and $\Th_{\AA^n}^{k}$ are chain homotopy equivalent by \cref{prop: retract of simplex to polysimplex}. This implies that the horizontal arrow in the second row is a quasi-isomorphism.
 \item Since $\M$ is locally free, we have the identification $\underline{\Th\left( \Gamma(\Cech(\mc U),j^*\M) \right) }\cong \Tot(\underline{\Th_{\AA^n}^k} \ox_{\O_{(\AA^{n})^k}} \M) $ by the same argument as before.
 \item The map $i$ comes from the map $\Th\left( \Gamma(\Cech(\mc U),\O) \right)\otimes_{\Gamma((\AA^n)^k,O_{(\AA^n)^k})}\Gamma((\AA^n)^k,\G)\rightarrow \Th\left( \Gamma(\Cech(\mc U),j^*\G) \right)$ and we use the fact that $\G$ is quasi-coherent.
    \item The first two columns are bounded complexes of $\D_{(\AA^{n})^k}$-modules.
    \item $\int_jj^{*}\G$ is represented by $j_*\mathfrak{C}_{ord}(\mathcal{U},j^*\G)=\underline{\Cech_{ord}^{\bullet}(\mc U,j^*\G)}$. This can be seen using injective resolutions and the fact that $\mathcal{U}$ is affine and finite.
\end{enumerate}

\begin{rem}
One could also use the projection formula \cite[Corollary 1.7.5]{HTT_Dmodules2008} directly by the flatness of $\TS_{\AA^n}^k$.
\end{rem}
\begin{rem}
The statement seems to be true for unbounded complexes. However, we did not find proof of the unbounded Bernstein theorem in the literature (it is mentioned in \cite[pp.207]{neeman1996grothendieck}). For bounded below complexes of quasi-coherent $D_{(\AA^{n})^k}$-modules, the statement is true by using the truncation of the complexes.
\end{rem}
\subsection{Proof of \cref{thm: TSIE gens and rels}}{\label{sec: proof of thm TSIE gens and rels}}
In this subsection we prove \cref{thm: TSIE gens and rels}, i.e. that $\TS_{\AA^n}^{I,E} \cong \mathbf B_{\AA^n}^{I,E}$. We first recall the notations:
\begin{enumerate}[-]
%\item  $\B_{\AA^1}^{I,E} := \kk[z_i,\frac 1{z_e}]_{i\in I; e\in E}$,
%\item $\B_{\AA^n}^{I,E} := \left( \B_{\AA^1}^{I,E} \right)^{\ox n} = \kk[z^r_i,\frac 1{z^r_e}]^{1\leq r\leq n}_{i\in I; e \in E}$
\item $\Omega_{n}^{I,E} := \kk[u^r_e; \dd u^r_e]^{1\leq r\leq n}_{e \in E} \big/\langle \sum\limits_{r=1}^{n} u^r_e -1, \sum\limits_{r=1}^{n} \dd u^r_e \rangle_{e\in E}$
\item $\mathbf \Omega_{\AA^n}^{I,E} := \kk[z^r_i,\frac 1{z^r_e}]^{1\leq r\leq n}_{i\in I; e \in E} \ox_\kk \Omega_{n}^{I,E}$
\end{enumerate}
Given also an undirected edge $e\in E$ and a direction $s\in \{1,\dots,n\}$, let
\begin{enumerate}[-]
\item $\Omega^{I,E}_{n,(e,\del_s)} := \Omega_{n}^{I,E}\big/ \langle u_e^s = 0, \dd u_e^s=0\rangle$
\item $\mathbf \Omega^{I,E}_{\AA^n,(e,\del_s)} %= \B^{I,E}_{\AA^n} \ox \Omega^{I,E}_{\AA^n,(e,\del_s)}
:= \mathbf \Omega^{I,E}_{n}\big/  \langle u_e^s = 0, \dd u_e^s=0\rangle$
\item $\mathbf \Omega^{I,E}_{\AA^n,(e,\del_s)^{\mathbf{reg}}} := \kk[z^r_i,\frac 1{z^t_{f}}]^{(r,i)\in \{1,\dots,n\}\times I}_{(t,f)\in (\{1,\dots,n\}\times E) \setminus \{(s,e)\}} \ox \Omega^{I,E}_{n,(e,\del_s)}$
\item $\mathbf \Upsilon^{I,E}_{\AA^n,u^s_e=0} := \mathbf \Omega^{I,E}_{\AA^n,(e,\del_s)}\big/  \mathbf \Omega^{I,E}_{\AA^n,(e,\del_s)^{\mathbf{reg}}}$
\end{enumerate}
We have the canonical quotient maps
$\Res_e^{I,E}|_{u^s_e=0} : \mathbf \Omega^{I,E}_{\AA^n} \to \mathbf\Upsilon^{I,E}_{\AA^n,u^s_e=0}.$

The general strategy is to start with simple cases and add vertices and edges.
We begin with the case of two vertices and one edge.
\begin{prop} Let $e = (v',v'')$.
$\TS_{\AA^n}^{\{v',v''\},\{e\}}$ is isomorphic to
$
\mathbf{B}^{\{v',v''\},\{e\}}_{\AA^n}%=\frac{\kk[z_{v'}^s,z^s_{v''},\frac{u^s_e}{(z^s_e)^{\mathbf{m}_{e,s}}},\frac{\dd u^s_e}{(z^s_e)^{\mathbf{m}_{e,s}}}]^{1\leq s\leq n}_{\mathbf{m}_{e,s}\geq 0}}{\langle \sum^n\limits_{s=1}u^s_e=1, \sum^n\limits_{s=1}\dd u^s_e=0,u^s_{i_1i_2}=-u^s_{i_2i_1}\rangle}
.
$
% Similarly, $\TS^{\{v',v''\},\{e\}}_{\AA^n,\basepoint}$ is isomorphic to  $\mathbf{B}^{\{v',v''\},\{e\}}_{\AA^n,\basepoint}%=\frac{\kk[z^s_{v'v''},\frac{u^s_e}{(z^s_e)^{\mathbf{m}_{e,s}}},\frac{\dd u^s_e}{(z^s_e)^{\mathbf{m}_{e,s}}}]^{1\leq s\leq n}_{\mathbf{m}_{e,s}\geq 0}}{\langle \sum^n\limits_{s=1}u^s_e=1, \sum^n\limits_{s=1}\dd u^s_e=0,u^s_{i_1i_2}=-u^s_{i_2i_1}\rangle}
% .
% $
\end{prop}
\begin{proof}
It is clear that
\[ \mathbf{B}^{\{v',v''\},\{e\}}_{\AA^n}\hookrightarrow \TS_{\AA^n}^{\{v',v''\},\{e\}} \]
 is a subalgebra. It remains to establish the containment in the other direction.
As a $\kk$-vector space, $\TS_{\AA^n}^{\{v',v''\},\{e\}}$ is spanned by elements of the form
\[
\sum_{l_s \in \ZZ_{\geq 0}} \sum_{r_s\in \ZZ} \left(\prod^n_{s=1}(z^s_{v''})^{l_s} (z^s_{e})^{-r_s}\right) \alpha_{(l_1,\dots,l_n),(r_1,\dots,r_n)} \in\TS_{\AA^n}^{\{v',v''\},\{e\}}
\]
with each $\alpha_{(l_1,\dots,l_n),(r_1,\dots,r_n)} \in \Omega_{\AA^n}^{\{v',v''\},\{e\}}$.
This element must belong to $\mathbf{\Omega}^{\{v',v''\},\{e\}}_{\AA^n,(e,\del_s)^{\mathbf{reg}}}$ for each $s$, i.e. it must obey the defining boundary conditions, namely that
\[\alpha_{(l_1,\dots,l_n),(r_1,\dots,r_n)}|_{u^s_e=0}=0 \quad \text{if}\ r_s>0.\]
Then the proposition follows from the following claim: For any subset $S\subset \{1,\dots,n\}$, if a polynomial differential form $\alpha\in \Omega^{\bul}(\triangle_{n-1})$ on the $(n-1)$-simplex satisfies the boundary condition
\[\alpha|_{u^{s}_e=0} \quad\text{for all } s\in S,\]
then it can be written as $\kk$-linear combination of monomials of the form
\begin{equation} \prod_{s\in S} (\varepsilon u_e^{s})^{p_s}\quad\text{with}\quad\varepsilon u^{s}_e \in \{u^{s}_e, \dd u^{s}_e\} \quad\text{and}\quad p_s>0\quad\text{for each $s\in S$}.\label{form}\end{equation}
To see this, note that for any $t\in \{1,\dots,n\}$, we may use the relations
$\sum\limits_{s=1}^{n}u^{s}_e=1, \sum\limits_{s=1}^{n}\dd u^{s}_e=0$
to write $\alpha$ uniquely as a polynomial $\alpha_t$ in the variables $\{u^s_e,\dd u^s_e\}_{s\neq t}$. If $S\neq \{1,\dots,n\}$ we may pick any $t\notin S$, write $\alpha = \alpha_t$, and the claim follows immediately from the boundary condition.
When $S=\{1,\dots,n\}$, then we argue in two steps. First, for every $t\in S$, $\alpha$ satisfies in particular the boundary conditions above for $S\setminus\{t\}\subset S$. Therefore, as we just saw, $\alpha_t$ is of the form \cref{form} for $S\setminus\{t\}$. Then we need only note that
\[
  \alpha =\sum_{s=1}^{n}u^s_e\alpha=\sum_{s=1}^{n}u^s_e\alpha_s
\]
is of the required form. This establishes the claim and hence the proposition.
\end{proof}

