We also need the following simple lemma.

\begin{lem}\label{RegularBoth} Let $e,e'\in E\subset I\two$ and $s,s'\in \{1,\dots,n\}$ such that $(e,s) \neq (e',s')$.
We have
\begin{align} &\kk[z^r_i]^{1\leq r\leq n}_{i\in I}\left[  \frac 1{z^r_f}\right]_{\substack{(r,f) \in (\{1\dots,n\}\times E)\setminus\{(s,e)\}}} \cap
\kk[z^r_i]^{1\leq r\leq n}_{i\in I}\left[  \frac 1{z^r_f}\right]_{\substack{(r,f) \in (\{1\dots,n\}\times E)\setminus\{(s',e')\}}}\nn\\
& \qquad\qquad=
\kk[z^r_i]^{1\leq r\leq n}_{i\in I}\left[  \frac 1{z^r_f}\right]_{\substack{(r,f) \in (\{1\dots,n\}\times E)\setminus\{(s,e),(s',e')\} }},
\nn\end{align}
where the intersection is taken in $\kk[z^r_i]^{1\leq r\leq n}_{i\in I}\left[  \frac 1{z^r_f}\right]_{\substack{(r,f) \in (\{1\dots,n\}\times E)}} $.
\end{lem}
\begin{proof}
We write an element in the intersection as
\[
F(z)=\sum_{l'}\frac{F'_{l'}(z)}{(z^{s'}_{e'})^{l'}}=\sum_{l}\frac{F_l(z)}{(z^s_e)^l},
\]
where $F'_{l'}(z)$ and $F_l(z)$  are regular in both $z^s_e$ and $z^{s'}_{e'}$. We can find $N\gg0$ and set $G(z)=\left(\prod\limits_{(\tilde{e},\tilde{s})\neq (e,s),(e',s')}z^{\tilde{s}}_{\tilde{e}}\right)^N$ such that $G(z)F_l(z),G(z)F'_{l'}(z)\in \kk[z^r_i]^{1\leq r\leq n}_{i\in I}$. Then
\[
G(z)F(z)\in\kk[z_i^r,{\frac{1}{z^s_{e}}}]^{1\leq r\leq n}_{i\in I}\cap  \kk[z_i^r,{\frac{1}{z^{s'}_{e'}}}]^{1\leq r\leq n}_{i\in I}=\kk[z^r_i]^{1\leq r\leq n}_{i\in I}.
\]
We conclude that
\[
F(z)=\frac{G(z)F(z)}{G(z)}\in \kk[z^r_i]^{1\leq r\leq n}_{i\in I}\left[  \frac 1{z^r_f}\right]_{\substack{(r,f) \in (\{1\dots,n\}\times E)\setminus\{(s,e),(s',e')\} }}
\]
as required.
\end{proof}

