\subsection{A lemma on flatness}
In the proof above, and also in \cref{sec: cohomology}, we required the following result.
\begin{lem}\label{lem: FlatE}
 The ring $\mathbf{B}^{I,E}_{\AA^n}$ is flat over $\O_{(\AA^n)^I}.$
\end{lem}
\begin{proof}
It is manifest from the definition, \cref{sec: gens and rels for TS}, of $\mathbf{B}^{I,E}_{\AA^n}$ that  \begin{equation} \mathbf{B}_{\AA^n}^{I,E}=\bigotimes_{e\in E}\mathbf{B}_{\AA^n}^{I,\{e\}},\nn\end{equation}
the tensor product being taken in $\O_{(\AA^n)^I}$-modules.
Therefore, it is enough to show that $\mathbf{B}_{\AA^n}^{I,\{e\}}$ is flat over $\O_{(\AA^n)^I}$, for if so then the tensor product above is a tensor product of flat $\O^I_{\AA^n}$-modules and thus a flat $\O_{(\AA^n)^I}$-module.

Our goal is thus to prove the following:
The ring $\mathbf{B}^{I,\{e\}}_{\AA^n}$ is flat over $\O_{(\AA^n)^I}$.

We have the sequence of inclusions
\[
\O_{(\AA^n)^I}\into  \mathbf{B}^{I,\{e\},0}_{\AA^n}=
\directlim_{m\geq0}\kk\left[ z^r_i, \frac{u^r_{e}}{(z^r_{e})^m}\right]^{1\leq r\leq n}_{i\in I}\big/\langle \sum_{r=1}^{n} u^r_{e} -1\rangle
\into \mathbf{B}^{I,\{e\}}_{\AA^n}.\]
Given any fixed positive integer $m$, consider% the affine scheme
\[ Y_m := \Spec\left( \kk\left[ z^r_i, \frac{u^r_{e}}{(z^r_{e})^m}\right]^{1\leq r\leq n}_{i\in I}\big/\langle \sum_{r=1}^{n} u^r_{e} -1\rangle \right).\]
We have %(recall here $z_e = z_i-z_j$ where $e=(i,j)$)
\[ Y_m =\{(z^r_i,y^r)^{1\leq r\leq n}_{i\in I} : \sum^n_{s=1}(z^s_e)^{m}y^s=1\}\subset(\AA^{n})^k\times \AA^{n}.\]
Notice that the affine variety $Y_{m}$ is non-singular and every fiber of the morphism $Y_{m}\rightarrow (\AA^{n})^k$ is of the same dimension $n-1$. Hence $Y_{m}$ is flat over $(\AA^{n})^k$ by the miracle flatness (\cite[\href{https://stacks.math.columbia.edu/tag/00R4}{Tag 00R4}]{stacks-project}).

Thus the ring $\mathbf{B}^{I,\{e\},0}_{\AA^n}$ is the direct limit of flat rings, and is therefore itself flat.

Now we prove the second inclusion, $\mathbf{B}^{I,\{e\},0}_{\AA^n} \into \mathbf{B}^{I,\{e\}}_{\AA^n}$, is also flat.
The degree 1 component $\mathbf{B}^{I,\{e\},1}_{\AA^n}$ is a $\mathbf{B}^{I,\{e\},0}_{\AA^n}$-module and
\[ \mathbf{B}^{I,\{e\}}_{\AA^n}=\bigwedge{}_{\mathbf{B}^{I,\{e\},0}_{\AA^n}}\mathbf{B}^{I,\{e\},1}_{\AA^n}.\]
We only need to prove that $\mathbf{B}^{I,\{e\},1}_{\AA^n}$ is flat over $\mathbf{B}^{I,\{e\},0}_{\AA^n}$. We shall use the equational criterion for flatness. Namely, suppose that we have a relation in $\mathbf{B}^{I,\{e\},1}_{\AA^n}$,
\[\sum_{s=1}^n F_s\cdot \frac{\dd u^s_e}{(z^s_e)^{\ell_s}}=0,\quad F_s\in\mathbf{B}^{I,\{e\},0}_{\AA^n}.\]
We must show that it is possible to rewrite $\frac{\dd u^s_e}{(z^s_e)^{\ell_s}} = \sum\limits_{j} a_{sj} b_j$, for some elements $b_j \in \mathbf{B}^{I,\{e\},1}_{\AA^n}$ and coefficients $a_{ij}\in \mathbf{B}^{I,\{e\},0}_{\AA^n}$, in such a way that for each $j$ we have the relations $\sum\limits_{s=1}^n F_s a_{sj} = 0$ in $\mathbf{B}^{I,\{e\},0}_{\AA^n}$.

To that end, first observe that we have the relations
\begin{equation} F_s \cdot (z^r_e)^{\ell_r} - F_r \cdot (z^s_e)^{\ell_s} =0 \quad\text{in}\quad \mathbf{B}^{I,\{e\},0}_{\AA^n}. \label{star}
\end{equation}
To see this, we note that $\mathbf{B}^{I,\{e\},1}_{\AA^n}$ embeds into $\kk[z_i^s, \frac 1 {z^s_e},u^s_e]^{1\leq s\leq n}_{i\in I}\{\dd u^s_e\}^{1\leq s\leq n}\big/\langle \sum_{r=1}^{n} \dd u^r_{e}\rangle$. There, we may eliminate $\dd u_e^n$ and then compare coefficients of the remaining $\dd u^r_e$ to find that $\frac{F_r}{(z^r_e)^{\ell_r}}=\frac{F_n}{(z^n_e)^{\ell_n}}$ for each $r$, and hence $\frac{F_s}{(z^s_e)^{\ell_s}}=\frac{F_t}{(z^t_e)^{\ell_t}}$ for all $1\leq s<t\leq n$. The relations \cref{star} in $\mathbf{B}^{I,\{e\},0}_{\AA^n}$ follow.

Now we rewrite
\begin{gather}
\frac{\dd u^s_e}{(z^s_e)^{\ell_s}}=\frac{\dd u^s_e}{(z^s_e)^{\ell_s}} \sum_{t=1}^n u^t_e=\sum_{\substack{t=1\\t\neq s}}^n(z^t_e)^{\ell_t}\cdot\left(\frac{u^t_e \dd u^s_e}{(z^s_e)^{\ell_s} (z^t_e)^{\ell_t}}\right)+\frac{u^s_e \dd u^s_e}{(z^s_e)^{\ell_s}}\nn\\
%&=\sum_{\substack{t=1\\t\neq s}}^n(z^t_e)^{\ell_t} \left(\frac{u^t_e \dd u^s_e}{(z^s_e)^{\ell_s} (z^t_e)^{\ell_t}}\right)-\sum_{\substack{t=1\\t\neq s}}^n(z^t_e)^{\ell_t} \left(\frac{u^s_e du^t_e}{(z^s_e)^{\ell_s} (z^t_e)^{\ell_t}}\right)\nn\\
=\sum_{\substack{t=1\\t\neq s}}^n(z^t_e)^{\ell_t} \cdot \left(\frac{u^t_e \dd u^s_e -u^s_e du^t_e}{(z^s_e)^{\ell_s} (z^t_e)^{\ell_t}}\right),\quad \text{using}\ \sum^n_{t=1}du^t_e=0,\nn
\end{gather}
and hence find that the relation in  $\mathbf{B}^{I,\{e\},1}_{\AA^n}$  comes from the relations \cref{star} in $\mathbf{B}^{I,\{e\},0}_{\AA^n}$:
\begin{gather}
\sum_{s=1}^n F_s\cdot\frac{\dd u^s_e}{(z^s_e)^{\ell_s}}=\sum_{\substack{s,t=1\\s\neq t}}^n
F_s \cdot (z^t_e)^{\ell_t} \cdot\left(\frac{u^t_e \dd u^s_e -u^s_e du^t_e}{(z^s_e)^{\ell_s} (z^t_e)^{\ell_t}}\right)\nn\\
=\sum_{\substack{s,t=1\\s<t}}^n (F_s\cdot (z^t_e)^{\ell_t}-F_t\cdot (z^s_e)^{\ell_s})\cdot \left(\frac{u^t_e \dd u^s_e -u^s_e du^t_e}{(z^s_e)^{\ell_s} (z^t_e)^{\ell_t}}\right).\nn
\end{gather}
This establishes that   $\mathbf{B}^{I,\{e\},1}_{\AA^n}$ is flat over   $\mathbf{B}^{I,\{e\},0}_{\AA^n}$, completing the proof.
\end{proof}



