\begin{algorithm}[t]
\caption{Curious Causality-Seeking Meta Causal World Modeling}
\label{alg:meta_causal}
\begin{algorithmic}[1]
\REQUIRE Observational states $X$, meta state embedding space $U$, initial codebook embeddings $\{e_u\}$, encoder $E$, decoder $D$, hyperparameters $\lambda_{\text{sparse}}, \lambda_{\text{mask}}, \lambda_{\text{quantization}}$
\STATE Initialize encoder parameters $\phi$, decoder parameters $\theta$, and embeddings $\{e_u\}_{u \in U}$
\WHILE{not converged}
    \STATE Compute embedding assignment: $u \leftarrow \operatorname*{arg\,min}_{u \in U}\|E(X)-e_u\|_2^2$
    \STATE Compute causal skeleton probabilities matrix: $\hat{M}_u \leftarrow D(e_u)$ 
    % \CommentLine{Observation Step}
    \STATE Sample causal skeleton matrix $M_u[i,j] \sim \text{GumbelSoftmax}(\hat{M}_u[i,j])$

    \STATE Select intervention $\text{do}(X_i=x'_i)$ maximizing reward $R(\text{do}(X_i=x'_i))$ via Eq.~(\ref{eq:reward}) 
    % \CommentLine{Curiosity-driven Exploration}
    \STATE Perform intervention and record resulting state transitions

    \STATE Estimate causal effects $\Delta_{ij}$ from interventions and update causal mask parameters via $\mathcal{L}_{\text{mask}}$ 
    % \CommentLine{Causal Effect Estimation}

    \STATE Predict next state $X_j^{t+1}$ from parent set $Pa_{\mathcal{G}_u}(X_j)$ and update world model via $\mathcal{L}_{\text{MLE}}$ 
    % \CommentLine{Transition Model Learning}

    \STATE Encourage sparsity in causal graph via $\mathcal{L}_{\text{sparse}}$
    \STATE Update embedding codebook $\{e_u\}$ via $\mathcal{L}_{\text{quantization}}$

    % \STATE Perform joint optimization step using combined loss:
    % \[
    % \mathcal{L}=\mathcal{L}_{\text{MLE}}+\lambda_{\text{sparse}}\mathcal{L}_{\text{sparse}}+\lambda_{\text{mask}}\mathcal{L}_{\text{mask}}+\lambda_{\text{quantization}}\mathcal{L}_{\text{quantization}}
    % \]
\ENDWHILE
\RETURN Learned causal subgraphs $\mathcal{G}_u$, world model parameters, and embeddings $\{e_u\}$
\end{algorithmic}
\end{algorithm}

