\subsection{Proof of Theorem \ref{thm:identifiability_of_domain_variables}}
\begin{proof}
    Consider the reconstruction objective for learning causal skeleton matrices from mixed data. For any clustering $\hat{C}: \mathcal{X} \to \hat{U}$, let $\hat{M}_{\hat{u}}$ denote the learned skeleton matrix for meta state $\hat{u}$. Under Assumption~\ref{assumption:mixed_data_structure_learning}, this matrix satisfies:
    \begin{align*}
        \hat{M}_{\hat{u}}[i,j] = \mathbb{I}\left[\bigcup_{x: \hat{C}(x)=\hat{u}} M_{C(x)}[i,j] = 1\right]
    \end{align*}

    Now consider two cases:

    \textbf{Case 1:} $\hat{C}$ perfectly aligns with $C$ up to label permutation. Then there exists a bijection $g: U \to \hat{U}$ such that $\hat{C}(x) = g(C(x))$ for all $x \in \mathcal{X}$. In this case, $\hat{M}_{g(u)} = M_u$ for each $u \in U$, achieving perfect reconstruction of individual causal structures.

    \textbf{Case 2:} $\hat{C}$ merges states from different true meta states. Then there exist $x_1, x_2 \in \mathcal{X}$ with $C(x_1) = u_1 \neq u_2 = C(x_2)$ but $\hat{C}(x_1) = \hat{C}(x_2) = \hat{u}$. By Assumption~\ref{assumption:mixed_data_structure_learning}:
    \begin{align*}
        \hat{M}_{\hat{u}} = M_{u_1} \cup M_{u_2}
    \end{align*}
    where $\cup$ denotes element-wise logical OR. Since $M_{u_1} \neq M_{u_2}$, we have $\hat{M}_{\hat{u}} \neq M_{u_1}$ and $\hat{M}_{\hat{u}} \neq M_{u_2}$.

    Let $\|\cdot\|_1$ denote the L1 norm. For binary matrices, $\|M\|_1$ equals the number of edges in the corresponding causal graph. Since the union operation can only add edges (never remove them), we have:
    \begin{align*}
        \|\hat{M}_{\hat{u}}\|_1 = \|M_{u_1} \cup M_{u_2}\|_1 \geq \max\{\|M_{u_1}\|_1, \|M_{u_2}\|_1\}
    \end{align*}

    Moreover, since $M_{u_1} \neq M_{u_2}$, there exists at least one position $(i,j)$ where $M_{u_1}[i,j] \neq M_{u_2}[i,j]$. 
    \begin{align*}
        \|\hat{M}_{\hat{u}}\|_1 > \|M_{u_1}\|_1 \quad \text{and} \quad \|\hat{M}_{\hat{u}}\|_1 > \|M_{u_2}\|_1
    \end{align*}

    Consider the expected L1 norm under each partition. For the true partition $C$:
    \begin{align*}
        \mathbb{E}_{x \sim \mathcal{X}}[\|M_{C(x)}\|_1] = \sum_{u \in U} P(C(x) = u) \cdot \|M_u\|_1
    \end{align*}

    For the suboptimal partition $\hat{C}$ that merges distinct meta states:
    \begin{align*}
        \mathbb{E}_{x \sim \mathcal{X}}[\|\hat{M}_{\hat{C}(x)}\|_1] = \sum_{\hat{u} \in \hat{U}} P(\hat{C}(x) = \hat{u}) \cdot \|\hat{M}_{\hat{u}}\|_1
    \end{align*}

    Since merging increases the L1 norm (as shown above), and each merged cluster $\hat{u}$ has $\|\hat{M}_{\hat{u}}\|_1 > \|M_u\|_1$ for the constituent true meta states $u$, we have:
    \begin{align*}
        \mathbb{E}_{x \sim \mathcal{X}}[\|\hat{M}_{\hat{C}(x)}\|_1] > \mathbb{E}_{x \sim \mathcal{X}}[\|M_{C(x)}\|_1]
    \end{align*}
\end{proof}


