\subsection{Proof of Theorem \ref{thm:identifiability_of_overparameterized_domain_variables}}
% \begin{theorem}[Identifiability of Overparameterized Meta States]
%     Under Assumption~\ref{assumption:mixed_data_structure_learning}, 
% if the learned mapping \(\hat{C}: \mathcal{X}\to\hat{U}\) satisfies \(|\hat{U}|> |U|\), the learned mapping \(\hat{C}\) is observationally equivalent to the ground truth mapping \(C: \mathcal{X}\to U\).
% \end{theorem}
\begin{proof}
    We prove that despite overparameterization, the learned mapping preserves the causal structure of the ground truth mapping.

    Let $\hat{U}_{\text{active}} = \{\hat{u} \in \hat{U} : \exists x \in \mathcal{X} \text{ s.t. } \hat{C}(x) = \hat{u}\}$ denote the set of meta states that are actually assigned to some state in $\mathcal{X}$.

    \textbf{Step 1:} We first establish that the learned mapping cannot merge distinct true meta states. Suppose for contradiction that there exist $x_1, x_2 \in \mathcal{X}$ such that:
    \begin{align*}
        C(x_1) = u_1 \neq u_2 = C(x_2) \quad \text{but} \quad \hat{C}(x_1) = \hat{C}(x_2) = \hat{u}
    \end{align*}

    By Assumption~\ref{assumption:mixed_data_structure_learning}, the learned causal skeleton matrix would be:
    \begin{align*}
        \hat{M}_{\hat{u}} = M_{u_1} \cup M_{u_2}
    \end{align*}

    Since $M_{u_1} \neq M_{u_2}$, we have $\|\hat{M}_{\hat{u}}\|_1 > \max\{\|M_{u_1}\|_1, \|M_{u_2}\|_1\}$, increasing the expected structural complexity as shown in Theorem~\ref{thm:identifiability_of_domain_variables}. This contradicts optimal clustering.

    \textbf{Step 2:} Since distinct true meta states cannot be merged, each active learned meta state $\hat{u} \in \hat{U}_{\text{active}}$ corresponds to exactly one true meta state. That is, for each $\hat{u} \in \hat{U}_{\text{active}}$, there exists a unique $u \in U$ such that:
    $
        \{x : \hat{C}(x) = \hat{u}\} \subseteq \{x : C(x) = u\}
    $

    \textbf{Step 3:} For any $x \in \mathcal{X}$, if $\hat{C}(x) = \hat{u}$ and the corresponding true meta state is $u$, then by Assumption~\ref{assumption:mixed_data_structure_learning}:
    \begin{align*}
        \hat{M}_{\hat{u}} = M_u
    \end{align*}

    Therefore, $M_{C(x)} = \hat{M}_{\hat{C}(x)}$ for all $x \in \mathcal{X}$, establishing observational equivalence.

    % The remaining meta states in $\hat{U} \setminus \hat{U}_{\text{active}}$ are unused and do not affect the observational equivalence.
\end{proof}
