	\arrow["{(e,e_{v})}"', from=1-10, to=1-9]
	\arrow["{(e,e_{w})}", from=1-10, to=1-11]
	\arrow["e"', no head, from=1-2, to=1-1]
	\arrow["{e_{w}}"', from=1-6, to=1-5]
	\arrow["{e_{v}}", from=1-4, to=1-5]
	\arrow["{(w,e_{w})}"', from=1-12, to=1-11]
\end{tikzcd}\]


\begin{definition}\label{pathextension}
Fix a graphic quiver $Q=Q(G)$ and a diagram $X\in \ob(\mc M^{F(Q)})$. The \textbfit{path extension} of $X$ is the diagram $P (X)\in \ob( \mc M^{F(\olin Q)})$ obtained by performing the following insertion at each edge $e=\{v,w\}$.
% https://q.uiver.app/#
\[\begin{tikzcd}
	{X^{v}} & {X^e} & {X^{w}} & \rightsquigarrow & {X^{v}} & {X^e} & {P(X^e)} & {X^e} & {X^{w}}
	\arrow["{X(e_{v})}", from=1-5, to=1-6]
	\arrow["{\pi_1}"', from=1-7, to=1-6]
	\arrow["{\pi_2}", from=1-7, to=1-8]
	\arrow["{X(e_{w})}"', from=1-3, to=1-2]
	\arrow["{X(e_{v})}", from=1-1, to=1-2]
	\arrow["{X(e_{w})}"', from=1-9, to=1-8]
\end{tikzcd}\]
Similarly, the \textbfit{padding} of $X$ is the diagram $\olin X\in \ob( \mc M^{F(\olin Q)})$ obtained from $P(X)$ by replacing $P(X^{e})$ by $X^{e}$ and each $\pi_{i}$ by $\id$.\\
\end{definition}

\begin{lemma} Let $Q=Q(G)$ be a finite graphic quiver, let $\mc M$ be a model category in which all projections are fibrations, and fix a diagram $X\in \ob(\mc M^{F(Q)})$. Then $\holim X \simeq \holim \olin X$.
\end{lemma} 
\begin{proof}
Choose $X'$ to be a fibrant replacement of $X$ in some Reedy model structure on $\mc M^{F(Q)}$ with cofibrant constants. The weak equivalence $X\lr X'$ of diagrams over $Q$ induces another weak equivalence $\olin X\lr \olin {X'}$ of diagrams over $\olin Q$. Let $\mathfrak o$ be the acyclic orientation on the simplification $G^{\mathrm{s}}$ corresponding to an ideal Reedy structure for which $X'$ is fibrant. Then for each vertex $v\in V$ of $G$, $\vp_{\mathfrak o}^{X'}(v)$ is a fibration in $\mc M$.

By definition, $\olin Q$ is graphic, being the quiver associated to the simple graph $U(Q)$. The orientation $\mathfrak o$ on $G^{\mathrm{s}}$ induces an orientation $\mathfrak o'$ on $U(Q)^{\mathrm{s}}= U(Q)$ as follows. Take $e=\{v,w\}$ in $E$ as before. If $v\neq w$ and we write the $\mathfrak o$-orientation of $e$ as above, then the corresponding $\mathfrak o'$-orientation in $U(Q)$ is
% https://q.uiver.app/#q=WzAsNixbMCwwLCJ2Il0sWzEsMCwidyJdLFsyLDAsIlxccmlnaHRzcXVpZ2Fycm93Il0sWzMsMCwidiJdLFs0LDAsImUiXSxbNSwwLCJ3Il0sWzAsMSwiZSJdLFszLDQsImVfdiJdLFs0LDUsImVfdyJdXQ==
\[\begin{tikzcd}
	v & w & \rightsquigarrow & v & e & w
	\arrow["e", from=1-1, to=1-2]
	\arrow["{e_v}", from=1-4, to=1-5]
	\arrow["{e_w}", from=1-5, to=1-6]
\end{tikzcd}\]
The remaining edges in $U(Q)$ come in parallel edge pairs
% https://q.uiver.app/#q=WzAsMixbMCwwLCJ3Il0sWzEsMCwiZSJdLFswLDEsImVfe3csMX0iLDAseyJjdXJ2ZSI6LTEsInN0eWxlIjp7ImhlYWQiOnsibmFtZSI6Im5vbmUifX19XSxbMCwxLCJlX3t3LDJ9IiwyLHsiY3VydmUiOjEsInN0eWxlIjp7ImhlYWQiOnsibmFtZSI6Im5vbmUifX19XV0=
\begin{tikzcd}
	w & e
	\arrow["{e_{w,1}}", bend right=-30, no head, from=1-1, to=1-2]
	\arrow["{e_{w,2}}"', bend right=30, no head, from=1-1, to=1-2]
\end{tikzcd}\!\!, each one corresponding to a loop $e=\{w,w\}$ in $G$. Define $\mathfrak o'$ on this pair as
% https://q.uiver.app/#q=WzAsNCxbMCwwLCJ2Il0sWzEsMCwiZSJdLFsyLDAsInYiXSxbMywwLCJlIl0sWzAsMSwiIiwwLHsiY3VydmUiOi0xfV0sWzAsMSwiIiwyLHsiY3VydmUiOjF9XSxbMywyLCIiLDIseyJjdXJ2ZSI6LTF9XSxbMywyLCIiLDAseyJjdXJ2ZSI6MX1dXQ==
\begin{tikzcd}
	w & e
	\arrow["{e_{w,1}}"', bend right=30, from=1-2, to=1-1]
	\arrow["{e_{w,2}}", bend right=-30, from=1-2, to=1-1]
\end{tikzcd}\!\!. This choice makes $e$ into a source, so $e$ will never be involved in a $\mathfrak o'$-directed cycle in $U(Q)$. Furthermore, since all $\mathfrak o$-directed arrows have been split into two $\mathfrak o'$-directed arrows, and $\mathfrak o$ is acyclic, $\mathfrak o'$ is also acyclic. Therefore, there is an adequate Reedy model structure on $\mc M^{F(\olin Q)}$ corresponding to $\mathfrak o'$. 

The diagram $\olin {X'}\in \ob(\mc M^{F(\olin Q)})$ is fibrant in this Reedy model structure if and only if for each vertex $p\in V\sqcup E$ of $U(Q)$, the resulting map $\vp_{\mathfrak o'}^{\olin{X'}}(p)$ arising from the set $A_{\mathfrak o'}(p) {\sube} U(Q)_{1}$ is a fibration in $\mc M$. Fixing a vertex $p$ of $U(Q)$, we now describe the set of arrows $A_{\mathfrak o'}(p)$. First, since $U(Q)$ is simple, the set $S_{U(Q)}(p)$ of self-loops is empty. So $A_{\mathfrak o'}(p)$ is determined by $E_{\mathfrak o'}(p)$, the set of edges in $U(Q)$ oriented by $\mathfrak o'$ with target $p$. 

\emph{Case 1:} $p=w\in V$ is a \textit{vertex} in $G$. The edges of $U(Q)$ containing $w$ all come from edges in $G$ containing $v$. For each self-loop $e\in S_{G}(w)$ of $w$ in $G$, there are two edges $e_{w,1},e_{w,2}\in U(Q)_{1}$ containing $w$ in $U(Q)$, and both of these have target $v$ under $\mathfrak o'$. For each non-self-loop edge $e\in E^{\mathrm{s}}$ which contains $w$, there is one edge $e_{w}\in U(Q)_{1}$ containing $w$ in $U(Q)$, and $e_{w}$ has target $w$ under $\mathfrak o'$ if and only if $e$ has target $w$ under $\mathfrak o$. So $E_{\mathfrak o'}(w)=\{e_{w}\mid e\in E_{\mathfrak o}(w)\}\cup \{e_{w,1},e_{w,2}\mid e\in S_{G}({w})=A_{\mathfrak o}(w)\}$ and $A_{\mathfrak o'}(w)= \{(w,x)\mid x\in A_{\mathfrak o}(w)\}.$

\emph{Case 2:} $p=e=\{v,w\}\in E$ is an \textit{edge} in $G$. Since $G$ is a graph, there are exactly two arrows $e_{v}=\{v,e\}$ and $e_{w}=\{w,e\}$ in $U(Q)$ containing $e$. If $e$ is a self-loop in $G$, then $e$ is an $\mathfrak o'$-source, so neither of these edges have target $p$. Then $A_{\mathfrak o'}(p)=E_{\mathfrak o'}(p)=\es$. If $e$ is not a self-loop, then $v\neq w$, and $\mathfrak o$ orients $e$ as, say $v\overset{e}\lr w$. Then $\mathfrak o'$ at $e$ looks like $v\overset{e_{v}}\to e\overset{e_{w}}\to w.$, so $E_{\mathfrak o'}(p)=\{e_{d(e)}\}$ and $A_{\mathfrak o'}(e)=\{(e,e_{d(e)})\}.$

We now describe the maps $\vp_{\mathfrak o'}^{\olin X}(p)$. When $p=e\in E$ is a loop, $A_{\mathfrak o'}(p)$ is empty, so there is no fibrancy condition (since all objects of $\mc M$ are fibrant). Otherwise, $A_{\mathfrak o'}(e)=\{(e,e_{d(e)})\}$, so $\vp_{\mathfrak o'}^{\olin X}(e)=\olin {X'}(e,e_{d(e)})=\id_{X'^{e}}$ is a fibration in $\mc M$. Finally, let $p=w\in V$ be a vertex in $G$. Recall that for any $x\in Q(w)$ we have $\olin {X'}(w,x)=X'(x)$, so $\vp^{\olin {X'}}_{\mathfrak o'}(w)= \prod_{x\in A_{\mathfrak o}(w)}\olin{X'}(w,x)=\prod_{x\in A_{\mathfrak o}(w)}X'(x)=\vp^{ {X'}}_{\mathfrak o}(w)$ is a fibration as well, by our assumption on $X'$. Therefore, $X'$ is fibrant in the adequate Reedy model structure corresponding to $\mathfrak o'$.

To conclude, we have $\holim X \simeq \holim X' \simeq \lim X' = \lim \olin{X'} \simeq \holim \olin {X'} \simeq \holim {\olin X}.$ The first and fifth equivalences follow because $X\lr X'$ and the induced map $\olin X\lr \olin{X'}$ are both weak equivalences. The second and fourth equivalences follow because $X'$ and $\olin {X'}$ are both fibrant in a Reedy model structure with cofibrant constants. The equality in the middle is elementary because the two diagrams differ only by inserted identity arrows.
\end{proof}

\begin{remark}This proof was local at each edge, so we can always pad any subset of edges without changing the homotopy limit. In particular, if we pad all self-loops, we end up with a diagram over a graph without self-loops. With this in mind, we can always assume without loss of generality that $G$ has no self-loops.\\
\end{remark}

\begin{lemma}\label{patheq}
Fix a finite graph $G=(V,E)$. Let $\mc M$ be a model category in which all projections are fibrations, and let $X\in \ob(\mc M^{F(Q(G))})$ be an arbitrary diagram. Then $\holim \olin {X} \simeq \lim P(X)$.
\end{lemma}
\begin{proof}
Write $G=(V,E)$. For each edge $e\in E$, the canonical weak equivalence $X^{e}\lr P(X^{e})$ extends with identities to a weak equivalence $\olin X\lr P(X)$. Then $\holim \olin {X} \simeq \holim P(X)$, so it remains to show $\holim P(X) \simeq \lim P(X)$. 

Recall that $\olin Q$ is the quiver associated to the graph $U(Q)$. Consider $Q$ as an orientation $\mathfrak o$ on $U(Q)$. Since 
$Q$ is graphic, $Q$ has diameter $1$, so $\mathfrak o$ is acyclic, and there is a corresponding adequate Reedy model structure on $\mc M^{F(\olin Q)}$. Note that a vertex $p$ in $Q$ has an arrow pointing into it if and only if $p=e\in E$ is an edge in $G$, and in this case there are exactly two arrows in $Q$ with target $e$, namely $v\overset{e_{v}}\to e\overset{e_{w}}\leftarrow w$, where $v$ and $w$ are the endpoints of $e$ in $G$ (allowing for $v=w$ or $v\neq w$). 

Therefore, a diagram $Y\in \ob(\mc M^{F(\olin Q)})$ is fibrant in this Reedy model structure if and only if, for each edge $e\in E$ in $G$, the induced map $\vp^{Y}_{\mathfrak o}(e)=Y(e,e_{v})\times Y(e,e_{w})$ is a fibration in $\mc M$. In the case $Y=P(X)$, this map is $\pi_{1}\times \pi_{2}$, which is a fibration. It follows that $P(X)$ is fibrant in the adequate Reedy model structure corresponding to the orientation $\mathfrak o$ from $Q$, so $\holim P(X) \simeq \lim P(X)$.
\end{proof}

\begin{lemma}\label{patheq2}
Take the same situation as above. Fix an acyclic subgraph $T\sube G$. Replace $\olin{X}$ (resp. $P(X)$) with $\widetilde{X}$ (resp. $\widetilde{P}(X)$), which is formed from $X$ by padding (resp. path extending) all edges except for those in $T$. Assume that $X(e_{v})$ is a fibration in $\mc M$ for each edge $e$ in $T$ and vertex $v\in e$.\footnote{This can be weakened to require fibrancy for only half of these edges, as the proof will show. Specifically, we only need there to exist a root vertex $\rh$ in $T$ such that $X(e_{v})$ is a fibration whenever $e=\{\hat v,v\}$ connects $v$ to its parent in the rooted tree $(T,\rho)$.\label{half}} Then the same result above holds. 
\end{lemma}

\begin{proof}
 We only need to check that $\widetilde{P}(X)$ is still fibrant. Fixing any vertex $\rh$ in $T$ as a root, introduce the quiver $\widetilde Q= \widetilde Q(G,\rh)$ which differs from $Q= Q(G)$ by not subdividing any edge in $T$ and orienting $T$ out from $\rh$. Then just as $\olin X$ and $P(X)$ are defined over $\olin Q\coloneqq Q(U(Q))$, so $\widetilde X$ and $\widetilde P(X)$ are defined over $\olin{\widetilde Q} Q(U(\widetilde Q))$. Since this latter quiver is graphic, we can proceed.

Having made these replacements, we mimic the above proof. Consider $\widetilde Q$ as an orientation on $U(\widetilde Q)$. Although $\widetilde Q$ may not have diameter 1 (in particular, may not be graphic), it is still acyclic: since $T$ is still a tree in $\widetilde Q$, any cycle would involve going through some edge $e_{v}\in (\widetilde Q)_{1}$ where $e\in E\sm T_{1}$, but this path must terminate in the sink $e\in (\widetilde Q)_{0}$.

We now check the fibrancy condition on the vertices of $U(\widetilde Q)$ equipped with the orientation $\mathfrak o$ coming from $\widetilde Q$. The vertices are  $U(\widetilde Q)_{0}=V\cup (E\setminus T_{1})$. Any $e'\in E\setminus T_{1}$ still has $\vp_{\mathfrak o}^{\widetilde P(X)}(e')=\pi_{1}\times \pi_{2}$ a fibration. In the previous proof, there was nothing to check on the vertices coming from $V$ because these were all sources under $\mathfrak o$. Now this is true for all elements of $V\sm (T_{0}\sm \{\rh\})$. Any vertex $v\in T_{0}\sm \{\rh\}$ has exactly one edge with target $v$, the edge $e$ with source $\hat v$, the parent of $v$ with respect to the root $\rh$. So $A_{\mathfrak o}(v)=\{e\overset{e_{v}}\to v\}$ and $\vp_{\mathfrak o}^{\widetilde P(X)}(v)=X(e_{v})$, which is a fibration by assumption.
\end{proof}

\begin{proposition}\label{pathresult}
Let $Q$ be a graphic quiver. Let $\mc M$ be a model category in which all projections are fibrations, and let $X\in \ob(\mc M^{F(Q)})$ be an arbitrary diagram. Then $\holim {X} \simeq \lim P(X)$. The same result holds if we choose an acyclic subgraph $T\subseteq G$ along whose edges we don't path extend, as long as each $X(e_{w})$ from $T$ is a fibration (or only half of these, see \cref{half} ).\label{maincor}
\end{proposition}
\begin{proof}
Combine the previous three results.
\end{proof}

We will see in Section 2 that when $\mc M$ is the category of dg-categories, path objects have a concrete description, so we will obtain explicit formulas for $\holim X$. Most of the arrows in our diagrams will be fibrations, so by \cref{pathresult} we will be able to choose a forest's worth of edges to \textit{not} path extend. The resulting smaller path extension $\widetilde{P}(X)$ still has the property that $\holim X \simeq \lim \widetilde{P}(X)$.



%%%%%%%%%%KAN RESULT%%%%%%%%%%%%%
\subsection{Homotopy limits in steps}
We finish with a technical result that will be used in Section 3 to calculate homotopy limits in multiple steps, rather than all at once.\\

\begin{lemma}\label{kanresult}
Fix a diagram $D\in \ob(\mc M^{J})$ over any category $\mc M$. Let $I\subseteq J$ be a faithful embedding of $F(Q(T))$ for some acyclic graph $T$. Assume that there are no morphisms in $J\sm I$ with codomain in $I$. Define $D'\in \ob(\mc M^{J/I})$ by replacing $D|_{I}$ with $\lim D|_{I}$. Then $\lim D'=\lim D$.
\end{lemma}

\begin{proof}
The replacement is well-defined because the vertices in $T$ are all sources in $J$. The result will follow from the fact that right Kan extensions preserve limits once we show that $D'$ is the right Kan extension of $D$ along the quotient $p: J\lr J/I$. This in turn follows from the pointwise formula for Kan extensions.
\end{proof}

\begin{proposition}\label{steps}
Let $G$ be a graph and $\mc M$ a model category in which all projections are fibrations. Fix a diagram $D\in \ob(\mc M^{J=Q(G)})$. Let $I\subseteq J$ be the subquiver given by an acyclic subgraph $T\sube G$ as above. Suppose $D(e_{v})$ is a fibration for each edge $e$ in $T$ and vertex $v\in e$.\footnote{Or only half of these, see \cref{maincor}.} Define $D'\in \ob(\mc M^{J/I})$ by replacing $D|_{I}$ with $\lim D|_{I}$. Then $\holim D'\simeq \holim D$.
\end{proposition}
\begin{proof}

First form the path extensions $\widetilde P(D)$ and $P(D')$, where the former is obtained by path extending all edges except for $e$. By \cref{maincor}, we have $\holim D\simeq\lim \widetilde P(D)$ and $\holim D'\simeq\lim P(D')$. It now remains to show that these two limits are equal. 

This will follow from \cref{kanresult} once we show that $\widetilde P(D)$ stands in the same relation to $ P(D')$ as $D$ stands to $D'$, meaning $P(D')=\widetilde P(D)'$. Of course this is true: in $D\rightsquigarrow D'\rightsquigarrow P(D')$, we first collapse $T$ and then path extend all remaining edges, while in $D\rightsquigarrow \widetilde P(D)\rightsquigarrow \widetilde P(D)'$, we first path extend all edges other than $T$ and then collapse $T$. The operations of collapsing $T$ and path extending all other edges do not interact because the latter does not change the diagram on the original vertices of $G$.
\end{proof}



%%%%%%%%%%%%%%%%%%% SECTION 2%%%%%
\section{Homotopy limits of dg-categories}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
In \cite[4.1.13]{K}, Karaba\c{s} gives an explicit formula for homotopy pullbacks of dg-categories. Since our diagrams are made of pullbacks, we will generalize this formula. In Section 1, we proved that path extending is a valid way of representing homotopy limits as limits, and in this section we calculate that representation explicitly. We give straightforward generalizations of Karaba\c{s}' Lemmas, and then finish with local manipulations of diagrams that will be crucial for Section 3.

\subsection{Differential graded categories}
Throughout the rest of this paper, we fix a commutative unital ring $k$ and a cyclic abelian group $R\in\{\zb/n\mid n\in \mathbb Z_{\geq 0}\}$. We will usually think of the case $R=\mathbb Z$, but our final invariant will be $R=\mathbb Z/2$-graded. A \textbfit{dg-category} is a category enriched over cohomologically $R$-graded chain complexes over $k$. We will write $\mc C_{\mathrm{dg}}^{(n)}(k)$ for the dg-category of $\zb/n$-graded chain complexes.\\

\begin{definition}
A dg-category is \textbfit{pointed} if it has a distinguished zero object 0. A dg-functor between pointed dg-categories is \textbfit{pointed} if it respects 0. Fixing $k$ and $R=\zb/n$, the category of pointed dg-categories and pointed dg-functors will be denoted $\dgcat_{k}^{(n)}$, or simply $\dgcat$.\\
\end{definition}

\begin{remark}
In the literature, a general dg-category is usually not required to be pointed, but all of the dg categories we use in this paper will be pointed. Similarly, the few dg-functors we employ are also pointed. So from here on we will omit the adjective ``pointed,'' taking it to be implicit.\\
\end{remark}

\begin{proposition}[Tabuada \cite{T}]\label{tabuadathm}There exists a unique model structure on $\dgcat_{k}^{(1)}$ whose weak equivalences are the quasi-equivalences, and whose \textbfit{fibrations} are those full dg-functors $F:\mc A\lr \mc B$ such that $H^{0}F$ is an isofibration: any isomorphism $F(a)\to b$ in $H^{0}\mc B$ lifts to an isomorphism $a\to a'$ in $H^{0}\mc A$.\\
\end{proposition}

\begin{remark}
Although Tabuada's theorem is formulated for dg-categories graded by $R=\zb$, by \cite{DK}, the same result holds for $R=\zb/2$, which suffices for our applications. Additionally, though the modern form of Tabuada's theorem is given for the category of unpointed dg-categories, the original proof was for pointed dg-categories, so the result holds for our purposes.
\end{remark}

All projections in $\dgcat_{k}^{(n)}$ are fibrations, so our results from Section 1 will apply.

Let $ \mc B$ and $\mc C$ be dg-categories. We write $\mathrm{Fun}(\mc B,\mc C)$ for the dg-category of unital $A_{\infty}$-functors from $\mc B$ to $\mc C$.\footnote{Since the only categories $\mathrm{Fun}(\mc B,\mc C)$ we will look at are those for which $\mc B$ is a very simple quiver, we choose to define each instance of $\mathrm{Fun}(\mc B,\mc C)$ explicitly rather than give the full definition of an $A_{\infty}$-functor. See \cite{Sei} for more on $A_{\infty}$-functors.} 

\begin{example}
If $\mc C=\mc C_{\tx{dg}}^{(n)}(k)$, then $\mathrm{Mod}(\mc B):=\mathrm{Fun}(\mc B,\mc C_{\tx{dg}}^{(n)}(k))$ is the dg-category of $A_{\infty}$-modules over $\mc B$.\\
\end{example}

\begin{example} When $\mc B$ is the free dg-category on the $A_{2}$-quiver, an object of $\mc B^{\to}\coloneqq\mathrm{Fun}(A_{2},\mc C)$ is $X=(X_{1}\overset{x}\to X_{2}),$ where $x\in Z^{0}\mc C(X_{1},X_{2})$ The morphism complexes are \[\mc C^{\to}(X,Y)^{k}\coloneqq \mc C(X_{1},Y_{1})^{k}\oplus \mc C(X_{1},Y_{2})^{k-1}\oplus \mc C(X_{2},Y_{2})^{k},\] with differential $d(f_{1},h,f_{2})=(df_{1},dh +(-1)^{k}(yf_{1}-f_{2}x),df_{2})$ and composition $(f_{1}',h',f_{2}')(f_{1},h,f_{2})=(f_{1}'f_{1},f_{2}'h+(-1)^{k}h'f_{1},f_{2}'f_{2})$.
\end{example}

We will often implicitly use the following characterization, due to Karaba\c{s}, of homotopy equivalences in $\mc C^{\to}$.\\

\begin{lemma}[{\cite[Lemma 4.1.4]{K}}]\label{simpler}
Let $\mc C$ be a dg-category and fix objects $X=(X_{1}\overset{x}\to X_{2})$ and $Y=(Y_{1}\overset{y}\to Y_{2})$ in  $\mc C^{\to}$. For each $i=1,2$, let $f_{i}:X_{i}\lr Y_{i}$ be a homotopy equivalence\footnote{A \textbfit{homotopy equivalence} in a dg-category $\mc C$ is a morphism in $Z^{0}\mc C$ which becomes an isomorphism in $H^{0}\mc C$.}. Then $f_{2}x\sim yf_{1}$\footnote{The notation $x\sim y$ means that $x-y$ is exact.} if and only if there exists a map $h\in \mc C(X_{1},Y_{2})^{-1}$ such that $(f_{1},h,f_{2})\in \mc C^{\to}(X,Y)^{0}$ is a homotopy equivalence.
\end{lemma}

We use $\rho_{1},\rho_{2}:\mc C^{\to}\lr \mc C$ to denote the projection functors, which are fibrations. The \textbfit{path object} $P(\mc C)$ of a dg-category $\mc C$ is the full dg-subcategory of $\mc C^{\to}$ spanned by the homotopy equivalences of $\mc C$. In particular, we have the canonical dg-functors $\mc C\overset{i}\lr P(\mc C)\overset{\pi_{1}\times \pi_{2}}\lr \mc C\times \mc C,$ where $i$ acts by $X\mapsto \id_{X}$, $f\mapsto (f,0,f)$, and $\pi_{j}\coloneqq \rh_{j}|_{P(\mc C)}$. The functor $i$ is a quasi-equivalence, and $\pi_{1}\times \pi_{2}$ is a fibration.

We conclude by verifying that it is sufficient for equivalences of diagrams in $\dgcat$ to commute only up to natural homotopy equivalence. This will be useful for our subsequent calculations in which we will have multiple homotopic models for a given dg-functor. \\

\begin{lemma}\label{right} Two dg-functors $F,G:\mc B\lr\mc C$ are right homotopic in the Tabuada model structure if they are naturally homotopy equivalent.
\end{lemma}

\begin{proof} A homotopy $\ph:\mc B\lr P(\mc C)$ realizing $F\overset{r}\sim G$ via the path object $P(\mc C)$ is the following data: for each $B\in \ob(\mc B)$, a homotopy equivalence $\ph_{B}:FB\to G$, and for each $f\in \mc B(B,B')^{n}$, a morphism $\ph(f)\in P(\mc C)(\ph_{B},\ph_{B'})^{n}$ of the form $(Ff, \ph(f)_{0},Gf)$ for some $\ph(f)_{0}\in \mc C(FB,GB')^{n-1}$. To be a dg-functor, these data must satisfy (i) identities: $\ph(\id_{B})_{0}=0$; (ii) composition: $\ph(g\circ f)_{0}=Gg \circ \ph(f)_{0}+(-1)^{n}\ph(g)_{0}\circ Ff$; and (iii) chain map: $f\mapsto \ph(f)_{0}$ is linear, and $\ph(df)_{0}=d\ph(f)_{0}+(-1)^{n}(\ph_{B}\circ Ff-Gf\circ \ph_{B})$. Any natural homotopy equivalence $\ph:F\lr G$ immediately yields a right homotopy by setting $\ph(f)_{0}=0$ for all $f$.
\end{proof}

\begin{proposition}\label{onthenose} Fix two diagrams $X,Y$ in $\dgcat^{J}$ for some shape $J$. If we specify dg-functors $\ph\coloneqq(\ph^{\a}:X^{\a}\lr Y^{\a})_{\a\in\ob(J)}$ which commute with $X$ and $Y$ only up to natural homotopy equivalence, then $\ph$ yields a legitimate map in $\Ho(\dgcat)^{J}$.
\end{proposition}
\begin{proof}
By \cref{right}, squares in $\dgcat$ which commute up to natural homotopy equivalence also commute up to right homotopy, so by \cite[5.10]{DS} the image of such a square under the localization $\g:\dgcat\lr \Ho(\dgcat)$ commutes in $\Ho(\dgcat)$. So the association $\a\mapsto \g(\ph^{\a})$ defines a morphism $\g(X)\lr \g(Y)$ in $\Ho(\dgcat)^{J}$.
\end{proof}

The next result will often be used implicitly in what follows.\\
\begin{corollary}\label{abstractsimple}
Let $J$ be the free category on a quiver. Fix diagrams $X,Y$ in $\dgcat^{J}$. If there exist objectwise quasi-equivalences from $X$ to $Y$ such that the resulting squares commute up to natural homotopy equivalence, then $X\simeq Y$. In particular, $\holim X\simeq\holim Y$.
\end{corollary}
\begin{proof}
Immediate from \cref{commute2} and \cref{onthenose}.
\end{proof}






\subsection{Explicit formulas}

Here we generalize \cite[4.1]{K} to our setting. We will use these results in the rest of the paper, in particular to construct homotopy equivalences within dg-categories arising as the homotopy limit of a diagram.\footnote{The proofs are the same as in \cite{K}, so we claim no originality for this subsection.} 

In the following, a \textbfit{graphic diagram} in $\dgcat$ will mean an object $X$ in $\dgcat^{F(Q(G))}$ for some finite graph $G$. Note that the definition of path extension $P(X)$ of $X$ carries an ambiguity over where to put $\pi_{1}$ versus $\pi_{2}$ on each edge in $G$. This ambiguity is removed by specifying an orientation on $G$. If we fix an orientation, then given an edge $e$ in $G$, we write $e_{1}$ and $e_{2}$ for the source and target vertices of $e$, respectively. We can now justify an explicit formula for the homotopy limit of $X$, which is a straightforward generalization of \cite[4.1.13]{K}.\\

\begin{lemma}\label{formula}
Fix a finite graph $G=(V,E)$ and a graphic diagram $X$ in $\dgcat^{F(Q(G))}$. Given an orientation of $G$, the following dg-category $\mc L$ presents $\holim X$: Objects are
\[\ob(\mc L)=\{M=((M_{v})_{v\in V},(m_{e})_{e\in E})\mid M_{v}\in \ob(X^{v}), m_{e}\in X^{e}(M^{e_{1}},M^{e_{2}})\, \tx{ are homotopy equivalences}\},\]
where $M^{e_{i}}\coloneqq X(e_{i},e)(M_{e_{i}})$ (and $e$ is understood from context). Morphisms are
\[\mc L(M,N)^{k}=\{\m=((\m_{v})_{v\in V},(\m_{e})_{e\in E})\mid \m_{v}\in X^{v}(M_{v},N_{v})^{k},\m_{e}\in X^{e}(M^{e_{1}},N^{e_{2}})^{k-1}\},\]
with differential $d\m=((d\m_{v})_{v\in V},(d\m_{e}+(-1)^{k}(n_{e}\m^{e_{1}}-\m^{e_{2}}m_{e}))_{e\in E})$ and composition $\n\m=((\n_{v}\m_{v})_{v\in V},(\n^{e_{2}}\m_{e}+(-1)^{k}\n_{e}\m^{e_{1}})_{e\in E}),$
where $\m^{e_{i}}\coloneqq X(e_{i},e)(\m_{e_{i}})$ (and $e$ is understood from context). Also, $\id_{M}=((\id_{M_{v}})_{v\in V},(0)_{e\in E})$.
\end{lemma}

\begin{proof}
Limits of dg-categories are computed concretely, so the formulas given follow on the nose from \cref{pathresult} and the definition of path objects in $\dgcat$.
\end{proof}

Now fix $M,N\in \ob(\mc L)$ and $\m,\n\in \mc L(M,N)^{k}$.\\

\begin{lemma}[Homotopy Lemma, {\cite[4.1.15]{K}}]We have $\m\sim\n$ if and only if there exist $(\xi_{v}\in X^{v}(M_{v},N_{v})^{k-1})_{v\in V}$ such that $d\xi_{v}=\m_{v}-\n_{v}$ for all $v\in V$ and $(-1)^{k-1}(n_{e}\xi^{e_{1}}-\xi^{e_{2}}m_{e})\sim \m_{e}-\n_{e}$ for all $e\in E$.\\
\end{lemma}

\begin{lemma}[{\cite[4.1.16]{K}}]
Suppose $d\m=0$. If for each $v\in V$, $\m_{v}$ is a homotopy equivalence with homotopy inverse $\n_{v}$, then there exist $(\n_{e}\in X^{e}(M^{e_{1}},N^{e_{2}})^{0})_{e\in E}$ such that $d((\n_{v})_{v\in V},(\n_{e})_{e\in E})=0$.\\
\end{lemma}

\begin{lemma}[Equivalence Lemma, {\cite[4.1.17]{K}}] The morphism $\m$ is a homotopy equivalence if and only if $d\m=0$, $\m_{v}$ is a homotopy equivalence for each $v\in V$, and $n_{e}\m^{e_{1}}\sim \m^{e_{2}}m_{e}$ for all $e\in E$.\\
\end{lemma}

\begin{proposition}
Suppose only the data $(\m_{v}\in X^{v}(M_{v},N_{v})^{0})_{v\in V}$ is given, where each $\m_{v}$ is a homotopy equivalence. If in addition, $n_{e}\m^{e_{1}}\sim \m^{e_{2}}m_{e}$ for all $e\in E$, then there exist 
$(\m_{e}\in X^{e}(M^{e_{1}},N^{e_{2}})^{-1})_{e\in E}$ such that $\m\coloneqq((\m_{v})_{v\in V},(\m_{e})_{e\in E})\in \mc L(M,N)^{0}$ is a homotopy equivalence.\footnote{Compare to \cref{simpler} and \cref{abstractsimple}.}
\end{proposition}

\begin{proof}
Set $\m_{e}$ so that $n_{e}\m^{e_{1}}- \m^{e_{2}}m_{e}=-d\m_{e}$. Then $d\m=0$ by construction, and the result follows from the Equivalence Lemma.
\end{proof}

Therefore, to prove that two objects in $\mc L$ are homotopy equivalent, it suffices to supply homotopy equivalences $(\m_{v}\in X^{v}(M_{v},N_{v})^{0})_{v\in V}$ and check that $n_{e}\m^{e_{1}}\sim \m^{e_{2}}m_{e}$ for each $e\in E$.\\

\begin{proposition}\label{simplify}
Let $G$ be a finite graph and $D$ a diagram in $\dgcat^{F(Q(G))}$. Fix a tree $T\sube G$, and assume that for each edge in $T$, the corresponding cospan (coming from $Q(T)\sube Q(G)$) in $D$ has at least one fibration among its two arrows. Let $\mc L \coloneqq \holim D$ be our model for the homotopy limit of a graphic diagram of dg-categories. Define the dg-subcategory $\mc L'\sube \mc L$ given by the condition that, for each edge $f=\{u,w\}$ in $T$, objects $M$ satisfy $M^{u}=M^{w}$ and $m_{f}=\id$, and morphisms $\m$ satisfy $\m^{u}=\m^{w}$ and $\m_{f}=0$. The inclusion of this subcategory is a quasi-equivalence.
\end{proposition}
\begin{proof}
We use the notation of \cref{steps}. We have $\mc L=\holim \mc D'\simeq \holim D$ from \cref{steps}, so it suffices to identify $\mc L'$ with $\holim  D'$. Below is a sketch of an \textit{isomorphism} between these two categories.

The diagram $ D'$ is obtained by collapsing $T\sube G$ to a point, at which we place $\lim \mc D|_{T}$. The category $\lim  D|_{T}$ is precisely the subcategory of $\holim  D|_{T}$ obtained using the restrictions defining $\mc L'$. Then $\holim  D'$ is obtained by gluing $\lim  D|_{T}$ to all other vertices of $G$ using path objects. This is the same as including all other information in $\mc L'$, namely objects and morphisms coming from $G\sm T$.
\end{proof}



%%%%%%%%%%%LOCAL MOVES%%%%%%%%%%%
\subsection{Local moves}\label{localmoves}

We apply the results above to arboreal diagrams, meaning diagrams of dg-categories arising as the microlocal sheaf categories associated to arboreal singularities in the skeleta of Weinstein surfaces. These diagrams arise from the local picture presented in \cite{N1}. 

The categories and functors used in arboreal diagrams are very simple in this dimension. Fix once and for all a strongly pretriangulated dg-category $\mc A\in \ob(\dgcat_{k}^{(n)})$, which the reader, if desired may take to be $\mc C_{\tx{dg}}^{(n)}(k)$. In this setting, the mapping cone $C:\mc A^{\to}\lr \mc A$ is a dg-functor. The quasi-equivalence $T:\mc A^{\to}\lr \mc A^{\to}$ defined by $ {T(X_{1}\overset{x}\to X_{2})\coloneqq(X_{2}\to C(x))}$ has quasi-inverse $T'(X_{1}\overset{x}\to X_{2})\coloneqq(C(x)[-1]\to X_{1})$ and satisfies the natural homotopy equivalence $C\circ T \simeq [1]\circ \rho_{1}$.

Given a dg-functor $f:\mc C\lr \mc B$, we write $\mc C_{f}$ for the full dg-subcategory of $\mc C$ on the objects $X$ in $\mc C$ which satisfy $f(X)\simeq 0$. By \cref{formula} we have
\be\label{edge}\mc C_{f}\simeq \holim(\mc C\overset{f}\lr \mc B\longleftarrow0).\ee
We denote the canonical quasi-equivalence $\mc A\lr P(\mc A)=\mc A_{C}^{\to}$ by $j_{C}$, and we define quasi-equivalences $j_{\rh_{i}}:\mc A^{\to}\lr \mc A_{\rh_{i}}$ by $j_{\rh_{1}}(X)\coloneqq(0\to X)$ and $j_{\rh_{2}}(X)\coloneqq(X\to 0)$.\\

\begin{lemma} [Rotation Lemma]\label{rotationlemma}
Let $X$ be a graphic diagram in $\dgcat$ which at a trivalent vertex looks like the following, for some $i,j,k\in \zb$, with modification $X'$.
% https://q.uiver.app/#
\[\begin{tikzcd}
	& {\mc A} &&&&& {\mc A} \\
	{X:} && {\mc A^{\to}} & {\mc A} && {X':} && {\mc A^{\to}} & {\mc A} \\
	& {\mc A} &&&&& {\mc A}
	\arrow["{[k]\circ C}", from=2-3, to=2-4]
	\arrow["{[i]\circ \rho_1}"', from=2-3, to=1-2]
	\arrow["{[j]\circ \rho_2}", from=2-3, to=3-2]
	\arrow["{[i-1]\circ C}"', from=2-8, to=1-7]
	\arrow["{[j]\circ \rho_1}", from=2-8, to=3-7]
	\arrow["{[k]\circ \rho_2}", from=2-8, to=2-9]
\end{tikzcd}\]
Then $X\simeq X'$, and in particular $\holim X \simeq \holim X'$.
\end{lemma}

\begin{proof}
By \cref{abstractsimple}, the quasi-equivalence $T:\mc A^{\to}\lr \mc A^{\to}$ defines a weak equivalence $X\lr X'$ with identities elsewhere.
\end{proof}



\begin{lemma}[Shift Lemma]
Fix $n\in \zb$. Let $X$ be a graphic diagram in $\dgcat$ which at a trivalent vertex looks as shown below, and let $X'$ be the shown local modification.
% https://q.uiver.app/#
\[\begin{tikzcd}
	& {\mc A} &&&&& {\mc A} \\
	{X:} && {\mc A^{\to}} & {\mc A} && {X':} && {\mc A^{\to}} & {\mc A} \\
	& {\mc A} &&&&& {\mc A}
	\arrow["{[k]\circ C}", from=2-3, to=2-4]
	\arrow["{ [i] \circ \rho_1}"', from=2-3, to=1-2]
	\arrow["{[j]\circ \rho_2}", from=2-3, to=3-2]
	\arrow["{[i+n]\circ \rho_{1}}"', from=2-8, to=1-7]
	\arrow["{[j+n]\circ \rho_{2}}", from=2-8, to=3-7]
	\arrow["{[k+n]\circ C}", from=2-8, to=2-9]
\end{tikzcd}\]
Then $X\simeq X'$, and in particular $\holim X \simeq \holim X'$.
\end{lemma}
\begin{proof}
Apply \cref{rotationlemma} $3n$ times.
\end{proof}

