\section{CITEVAL Scoring Guidelines}

\begin{itemize}
    \item \textbf{Purpose-driven Articulation (0.35)}
    \begin{description}
        \item[90-100:] Directly supports core arguments, forming indispensable logical closure.
        \item[80-89:] Effectively addresses main research questions, enhancing credibility.
        \item[70-79:] Provides relevant background without direct support.
        \item[60-69:] Partial relevance with limited argumentative value.
        \item[0-59:] Severe deviation or misleading content.
    \end{description}

    \item \textbf{Semantic Accuracy (0.25)}
    \begin{description}
        \item[90-100:] Fully preserves key elements with 100\% term accuracy.
        \item[80-89:] No core content distortion, reasonable simplification of minor parameters.
        \item[70-79:] Non-critical phrasing differences.
        \item[60-69:] Important concept/data inaccuracies.
        \item[0-59:] Substantive errors or fabricated content.
    \end{description}

    \item \textbf{Contextual Fit (0.25)}
    \begin{description}
        \item[90-100:] Seamlessly embedded, significantly enhances reading efficiency.
        \item[80-89:] Smooth transitions without comprehension barriers.
        \item[70-79:] Requires moderate cognitive adjustment.
        \item[60-69:] Causes localized logical disruptions.
        \item[0-59:] Severely compromises textual coherence.
    \end{description}

    \item \textbf{Information Density (0.20)}
    \begin{description}
        \item[90-100:] Pareto-optimal compression (balance of completeness and conciseness).
        \item[80-89:] Lossless compression of core information.
        \item[70-79:] Non-essential redundancy present.
        \item[60-69:] Critical omissions or oversimplification.
        \item[0-59:] Severe information density imbalance.
    \end{description}
\end{itemize}


