It is easy to check that the edge $v_1 \to v_3$ is underdetermined in $\overline{S}$. A key observation is that this remains true even when $\overline{S}$ is part of a larger graph structure. 

\begin{lemma}\label{lem:admg-underdetermined}
    Let $G$ be an ADMG that contains $\overline{S}$ as a (labeled) subgraph on the vertices $(v_1, v_2, v_3)$. Then, the edge $v_1 \to v_3$ is underdetermined in $G$. 
\end{lemma}

\begin{proof}
    Let $G$ be an ADMG containing $\overline{S}$ as a labeled subgraph on $(v_1, v_2, v_3)$ and let $G'$ be the graph obtained from deleting the edge $v_1 \to v_3$ from $G$. Since $G'$ is a subgraph of $G$, any two vertices $a, b$ that are d-separated given $Z$ in $G$ are also d-separated given $Z$ in $G'$. Now, assume $a$ and $b$ are d-connected in $G$ given $Z$. First, note that each vertex has the same descendants in $G$ and $G'$, since $G'$ still contains a directed path from $v_1$ to $v_3$. Hence, if $\pi$ is an active path from $a$ to $b$ given $Z$ in $G$ that does not contain the edge $v_1 \to v_3$, then $\pi$ is also an active path from $a$ to $b$ given $Z$ in $G'$. Otherwise, if $\pi$ is an active path from $a$ to $b$ given $Z$ in $G$ that contains the edge $v_1 \to v_3$, then we distinguish two cases: \\
    First, if $v_2 \notin Z$, then replacing the edge $v_1 \to v_3$ in $\pi$ by the path $v_1 \to v_2 \to v_3$ gives an active path in $G'$. Secondly, if $v_2 \in Z$, then replacing the edge $v_1 \to v_3$ in $\pi$ by the path $v_1 \to v_2 \leftrightarrow v_3$ gives an active path in $G'$. In all cases, we get that $a$ and $b$ are also $d$-connected given $Z$ in $G'$, so $G$ and $G'$ are Markov equivalent. 
\end{proof}

This leads to the following corollary: 
\begin{corollary} \label{cor:admg-underdetermined}
    Let $G$ be an ADMG on $n$ vertices and suppose there are $m$ different subsets of vertices $V_1, \dots, V_m$ such that $|V_i| = 3$ and the induced graph $G[V_i]$ contains a copy of $S$ or of $\overline{S}$ for all $i$. Then, $|\MEC(G)| \geq 2^{m/(3n)}$.
\end{corollary} 

\begin{proof}
Given the setup as in the Corollary, note that each subset $V_i$ only intersects with at most $3(n-1)$ other subsets in two vertices. Hence, we can select at least $m/(3n)$ different subsets $V_i$ that pairwise intersect in at most one vertex. However, this implies that the copies of $S$ and $\overline{S}$ on these vertex sets are all edge-disjoint. In particular, deleting or adding the underdetermined edge in these copies does not influence the other copies, so we can add or delete an edge for each of the sub-selected vertex sets independently while preserving Markov-equivalence. This implies $|\MEC(G)| \geq 2^{m/(3n)}$.
\end{proof}

All that is left to do in order to prove Theorem~\ref{thm:MECs}, part~\ref{item:admg} is to show that in a uniformly random ADMG $G$, a constant fraction of all possible vertex sets of size $3$ is expected to have a copy of $S$ or $\overline{S}$.

\begin{proofof}{Theorem~\ref{thm:MECs}, part~\ref{item:admg}}
    Let $G$ be a uniformly random ADMG on $n$ vertices. Note that the distribution of $G$ can be described by sampling a uniformly random DAG and adding a bidirected edge for each pair of vertices independently with probability $1/2$. We extend the notion of tower decompositions to ADMGs and denote by $\sigma(G)$ the tower of the DAG formed by the directed edges of $G$. Let $\cA$ be the set of towers $\sigma$ that only have layers of size at most $n/48$. For each $\sigma \in \cA$, let $\cV_\sigma$ be the set of all vertex subsets of size $3$ that do not contain two vertices in adjacent layers. We have $|\cV_\sigma| \geq \frac{1}{6} \cdot n \cdot \frac{23}{24}n \cdot \frac{11}{12}n \geq n^3/7.$ By Lemma~\ref{lem:tower_conditioning}, after conditioning on $\sigma(G) = \sigma$, the edges induced  by each $W \in \cV_\sigma$ occur independently with probability $1/2$ each, so we get $\Pr(W \text{ contains a copy of $S$ or $\overline{S}$} \mid \sigma(G) = \sigma) \geq 1/8$. Then, if $X$ denotes the number of vertex sets $W \in \cV_\sigma$ that contain a copy of $S$ or $\overline{S}$, we get $\E[X \mid \sigma(G) = \sigma] \geq n^3/56$. By Corollary~\ref{cor:admg-underdetermined} and Jensen's inequality, we deduce
    \begin{align*}
    \E\left[|\MEC(G)| \middle | \sigma(G) = \sigma\right] &\geq \E\left[2^{X/(3n)} \middle | \sigma(G) = \sigma \right]\\ &\geq 2^{n^2/168}.
    \end{align*}

    After summing over all $\sigma \in \cA$, we conclude using Lemma~\ref{lem:tower_size}: 
    \begin{align*}
        \E\left[|\MEC(G)|\right] &\geq \Pr\left(\sigma(G) \in \cA\right) \cdot 2^{n^2/168}\\
        &= \Pr\left( h_i \leq n/48 \text{ for all $i$}\right) \cdot 2^{n^2/168}\\
        &\geq (1 - n \cdot 2^{-n^2/9216+2}) \cdot 2^{n^2/168}\\ 
        &= 2^{\Omega(n^2)}.
    \end{align*}
\end{proofof}

We remark that it is straightforward to show tight concentration of the random variable $X$, counting the occurrence of underdetermined edges in $G$ by Chebychev's inequality. This means that in fact almost all ADMGs on $n$ vertices have at least $2^{\Omega(n^2)}$ Markov-equivalent graphs. 


\section{Directed Cyclic Graphs}\label{sec:DCGs}
\subsection{Underdetermined Edges}
For DCGs, we can apply essentially the same reasoning as in the previous section. Consider the following DCG:  
\begin{defn}
    We define the DCG $T$ on an ordered set of three vertices $(v_1, v_2, v_3)$ as the graph with edges $v_1 \to v_2$, $v_2 \to v_3$, and $v_3 \to v_2$. Moreover, we denote the graph $T \cup \{v_1 \to v_3\}$ as $\overline{T}$, see Figure~\ref{fig:dcg}.
\end{defn}

