\section{Proofs for Sparse DAGs} \label{apx:dags}

Here, we restate and prove our technical results on random DAGs sampled from $D(n,p)$.

{
\renewcommand{\thetheorem}{\ref{lem:tower-distr}}
\begin{lemma}
    Let $G \sim D(n,p)$, and fix a tower vector $h = (h_1, \dots, h_s)$ with entries that sum up to $n$, and a tower decomposition $H = (H_1 \dots, H_s)$ with $|H_i| = h_i$. Then, the following holds:

    \begin{enumerate}[label=(\alph*)]
        \item the probability that $h$ is the tower vector of $G$ is proportional to 
    \begin{align*}
        w(h) = \binom{n}{h_1, \dots, h_s} \prod_{k=2}^s\frac{\left(1 - (1-p)^{h_{k-1}}\right)^{h_k}}{(1-p)^{h_k \sum_{i=1}^{k-1}h_i}}; 
    \end{align*}
        \item conditional on the event that $H$ is the tower decomposition of $G$, the parent sets $\Pa(v)$ are independently distributed for all $v \in V(G)$, and for $v \in H_j$ and $S \subseteq \bigcup_{i=1}^{j-1}H_i$, we have 
        \begin{align*}
            \Pr\left(\Pa(v) = S\right) = \begin{cases}
                C \cdot \left(\frac{p}{1-p}\right)^{|S|} \text{ if } S \cap H_{j-1} \neq \emptyset\\
                0 \text{ otherwise,}
            \end{cases}
        \end{align*}
        where $C$ is the normalization constant.
    \end{enumerate}
\end{lemma}
\addtocounter{theorem}{-1}
}


\begin{proof}
    Fix a tower vector $h = (h_1, \dots, h_s)$ with entries that sum up to $n$ and a tower decomposition $H = (H_1, \dots, H_s)$ with $|H_k| = h_k$. The key observation is that a DAG $G$ has tower decomposition $H$ if and only if for each vertex $v \in H_k$, the parents of $v$ are a subset of $\bigcup_{i = 1}^{k-1} H_i$ that intersects $H_{k-1}$ (Lemma 3 of \citet{talvitie}). We define 
    \begin{align*}
        \mathcal{C}_k = \{S \subseteq \bigcup_{i = 1}^{k-1} H_i \mid S \cap H_{k-1} \neq \emptyset\}; \;
        \mathcal{C}_{k,s} = \{S \in \cC_k \mid |S| = s\}, 
    \end{align*}
    setting $H_0 = \emptyset$ to cover the case $k = 1$. In particular, given that $H$ is the tower decomposition of $G$, the parent sets of each vertex in $H_k$ can be chosen independently in $\mathcal{C}_k$, which together with Definition~\ref{defn:Dnp} of $D(n,p)$ implies part~\ref{item:b} of the Lemma. Moreover, we get that the probability for $G \sim D(n,p)$ to have tower decomposition $H$ is proportional to
    \begin{align*}
       w(H) &:= \sum_{G: H(G) = H} \prod_{k = 1}^s \prod_{v \in H_k} \left(\frac{p}{1-p}\right)^{|\Pa(v)|}\\
        &= \prod_{k = 1}^s \prod_{v \in H_k} \sum_{P \in \cC_k} \left(\frac{p}{1-p}\right)^{|P|}  \\ 
        &= \prod_{k = 1}^s \prod_{v \in H_k} \sum_{s=0}^n \left(\frac{p}{1-p}\right)^{s} \cdot |\cC_{k,s}|\\
        &= \prod_{k = 2}^s \prod_{v \in H_k} \sum_{s=0}^n \left(\frac{p}{1-p}\right)^{s} \cdot \left(\binom{\sum_{i=1}^{k-1}h_i}{s} - \binom{\sum_{i=1}^{k-2}h_{i}}{s}\right)\\
        &= \prod_{k = 2}^s \prod_{v \in H_k} \left( \left(1 + \frac{p}{1-p}\right)^{\sum_{i=1}^{k-1}h_i} - \left(1 + \frac{p}{1-p}\right)^{\sum_{i=1}^{k-2}h_i}\right)\\
        &= \prod_{k = 2}^s (1-p)^{-h_k \sum_{i=1}^{k-1}h_i} \cdot \left(1 - (1-p)^{h_{k-1}}\right)^{h_k}. 
    \end{align*}

Now part~\ref{item:a} of Lemma~\ref{lem:tower-distr} follows from summing over all $\binom{n}{h_1, \dots, h_s}$ choices of tower decompositions with layer sizes $h_1, \dots, h_s$. 
\end{proof}


{
\renewcommand{\thetheorem}{\ref{lem:upper-tailbd}}
\begin{lemma}
    Let $p = o\left(\frac{1}{\log n}\right)$ and $G \sim D(n,p)$. Then, the number of sources in $G$ is less than or equal to $\frac{5}{p}$ with high probability. 
\end{lemma}
\addtocounter{theorem}{-1}
}


\begin{proof}
    Let $p = o\left(\frac{1}{\log n}\right)$. Without loss of generality, we assume that $p^{-1}$ is an integer. For each index $j$, we define $\cH_j$ to be the set of tower vectors $h=(h_1, \dots, h_s)$ with entries that sum up to $n$ and $h_j \geq 5p^{-1} \geq h_{j+1}$. Consider the functions $\varphi_j$ that map $h=(h_1, \dots, h_s) \in \cH_j$ to the vector $\varphi_j(h) = (h_1, \dots, h_{j-1}, \ell_1, \dots, \ell_r, h_{j+1}, \dots, h_s)$, where $r$ is equal to $h_j p$ rounded to the nearest integer, $\ell_2 = \ell_3 = \dots = \ell_r = p^{-1}$ and $\ell_1 = h_j - \sum_{i=2}^r \ell_i$. Note that the entries of $\varphi_j(h)$ are still positive integers that sum up to $n$, so it is a valid tower vector. Moreover, $\ell_1 \in [p^{-1}/2, 3p^{-1}/2]$. We are now going to bound the ratio of the weights of $h$ and $\varphi_j(h)$. By Lemma~\ref{lem:tower-distr},
    \begin{align*}
        \frac{w(h)}{w(\varphi_j(h))} = \frac{\prod_{i=1}^r\ell_i!}{h_j!} (1-p)^{\sum_{1\leq i<k\leq r}\ell_i \ell_k} \cdot \frac{(1-(1-p)^{h_{j-1}})^{h_j-\ell_1}}{\prod_{i=2}^r (1-(1-p)^{\ell_{i-1}})^{\ell_i}} \cdot \left(\frac{1-(1-p)^{h_j}}{1-(1-p)^{\ell_r}}\right)^{h_{j+1}}.
    \end{align*}
    For the edge cases of this formula to be correct, we set $h_0 = \infty$ and $h_{s+1} = 0$. We bound each term separately: First, since $\sum_{i=1}^r \ell_i = h_j$, we have $\prod_{i=1}^r \ell_i! \leq h_j!$.\\
    Secondly, since $r \geq 5$, we get the estimate
    \begin{align*}
        \sum_{1 \leq i < k \leq r}\ell_i\ell_k &= \ell_r (h_j - \ell_r) + \ell_{r-1} ( h_j - \ell_r - \ell_{r-1}) + \sum_{1 \leq i < k \leq r-2} \ell_i\ell_k\\ &= 2h_jp^{-1} - 3p^{-1} + \sum_{1 \leq i < k \leq r-2} \ell_i\ell_k \geq 2h_jp^{-1}.
    \end{align*}
    Thirdly, since $\ell_i \geq (2p)^{-1}$, we may use 
    \begin{align*}
        1-(1-p)^{\ell_i} \geq 1-(1-p)^{1/(2p)} \geq 1 - e^{-1/2} \geq 7/20,
    \end{align*}
    and
    \begin{align*}
        1 - (1-p)^{\ell_r} = 1-(1-p)^{1/p} \geq 1-e^{-1} \geq 1/2.
    \end{align*}
    Finally, using the condition $h_{j} \geq 5p^{-1} \leq  h_{j+1}$, we obtain
    \begin{align*}
        \frac{w(h)}{w(\varphi_j(h))} \leq (1-p)^{2h_jp^{-1}} \cdot (20/7)^{\sum_{i=2}^r\ell_i} \cdot 2^{h_{j+1}} \leq e^{-2h_j + \log(20/7)\cdot h_j + \log(2)\cdot h_j} \leq e^{-h_j/4} \leq e^{-p^{-1}}.
    \end{align*}
    Now, let $G \sim D(n,p)$. Note that each function $\varphi_j$ maps at most $np$ vectors to the same image (the extreme case is when $\varphi_1(h) = (p^{-1}, \dots, p^{-1})$). We calculate
    \begin{align*}
        \Pr\left(h_{j}(G) \geq 5p^{-1} \geq  h_{j+1}(G)\right) = C \cdot \sum_{h \in \mathcal{H}_j}w(h) \leq C \cdot \sum_{h \in \mathcal{H}_j}w(\varphi(h))\cdot e^{-p^{-1}} \leq np \cdot e^{-p^{-1}},
    \end{align*}
    where $C = \left(\sum_h w(h)\right)^{-1}$ is the normalization constant. We conclude
    \begin{align*}
        \Pr\left(h_1(G) \geq 5p^{-1}\right) &\leq \Pr\left(h_{1}(G) \geq 5p^{-1} \geq  h_{2}(G)\right) + \Pr\left(h_2(G) \geq 5p^{-1}\right)\leq \dots\\ &\leq \sum_{i=1}^{T(G)-1}\Pr\left(h_{j}(G) \geq 5p^{-1} \geq  h_{j+1}(G)\right) \leq n^2p \cdot e^{-p^{-1}} = o(1).
    \end{align*}


\end{proof}

We will need the following bound in the proof of the next Lemma:

\begin{lemma}\label{lem:multinomial}
    Let $h_1, \dots, h_r$ be positive integers that sum up to $n$. Then, 
    \begin{align*}
        \binom{n}{h_1, \dots, h_r} \leq \frac{n^n}{ h_r^{h_1} \cdot \prod_{i=2}^rh_{i-1}^{h_i}}
    \end{align*}
\end{lemma}

\begin{proof}
    The lemma simply follows from: 
    \begin{align*}
        n^n = \left(\sum_{i=1}^r h_i\right)^n = \sum_{j_1 + \dots + j_r = n} \binom{n}{j_1, \dots, j_r}h_1^{j_1} \cdot \ldots \cdot h_r^{j_r} \geq \binom{n}{h_2, \dots, h_r, h_1}h_1^{h_2} \cdot \ldots \cdot h_{r-1}^{h_r} \cdot h_r^{h_1}.
    \end{align*}
\end{proof}

{
\renewcommand{\thetheorem}{\ref{lem:lower-tailbd}}
\begin{lemma}
    Let $\frac{6}{n} \leq p \leq o\left(\frac{1}{\log n}\right)$ and $G \sim D(n,p)$. Then, with high probability, we have $h_1(G) \geq \frac{p^{-1}}{20 \log(p^{-1})}$ and $h_2(G) \geq \frac{p^{-1}}{\log^2(p^{-1})}$.
\end{lemma}
\addtocounter{theorem}{-1}
}


\begin{proof}
    Let $6/n \leq p \leq o\left(\frac{1}{\log n}\right)$. First, we define $\cH_1$ to be the set of tower vectors $h= (h_1, \dots, h_s)$ with entries that sum up to $n$ and $h_1 \leq p^{-1}/(20\log (p^{-1}))$. Consider the function $\varphi_1$ that maps a tower vector $h = (h_1, \dots, h_s) \in \cH_1$ to the vector $\varphi_1(h) = (L, h_{r+1}, \dots, h_s)$, where $r = \min \{k:\sum_{i=1}^{k} h_i > p^{-1}/5\}$ and $L = \sum_{i=1}^{r} h_i$. Note that $\varphi_1(h)$ is again a valid tower vector, and by Lemma~\ref{lem:tower-distr}, we get
    \begin{align}
        \notag \frac{w(h)}{w(\varphi_1(h))} &= \frac{L!}{\prod_{i=1}^{r} h_i!} (1-p)^{-\sum_{1\leq i<k\leq r}h_i h_k} \cdot \prod_{i=2}^{r} (1-(1-p)^{h_{i-1}})^{h_i} \cdot \left(\frac{1-(1-p)^{h_{r}}}{1-(1-p)^{L}}\right)^{h_{r+1}}\\
        &\leq \frac{L!}{\prod_{i=1}^{r} h_i!} (1-p)^{-\sum_{1\leq i<k\leq r}h_i h_k} \cdot \prod_{i=2}^{r} (1-(1-p)^{h_{i-1}})^{h_i}. \label{eq1}
    \end{align}
    We are interested in further bounding expression \eqref{eq1} under the constraint $L = \sum_{i=1}^r h_i$. First of all, note that increasing $h_r$ by $1$, while leaving $h_1, \dots, h_{r-1}$ the same, changes expression \eqref{eq1} by a factor of 
    \begin{align*}
        \frac{L+1}{h_r + 1} \cdot (1-p)^{-\sum_{i=1}^{r-1}h_i} \cdot (1-(1-p)^{h_{r-1}}) \leq \frac{L}{h_r} \cdot (1-p)^{-p^{-1}/5}  \cdot p h_{r-1} \leq \frac{L}{h_r} \cdot e^{1/5} \cdot \frac{1}{5}.
    \end{align*}
    Here, we used the fact that $\sum_{i=1}^{r-1}h_i \leq p^{-1+\eps}$. This factor is strictly less than $1$ if, $h_r > L/4$, hence, we may assume $h_r \leq L/4$, and therefore $L \leq 4 p^{-1}/15$. Now, we can bound \eqref{eq1} using Lemma~\ref{lem:multinomial}:
    \begin{align*}
        \frac{w(h)}{w(\varphi_1(h))} &\leq \frac{L^L}{h_r^{h_1} \cdot \prod_{i=2}^{r}h_{i-1}^{h_i}} (1-p)^{-L^2} \prod_{i=2}^r (h_{i-1}p)^{h_i}\\ &\leq L^L e^{pL^2}p^{L-h_1} \leq \left(\frac{4}{15}\right)^Lp^{-L}e^{4L/15}p^{L}p^{p^{-1}/(20\log p)}\\
        &\leq e^{L(\log(4/15) + 4/15)) + p^{-1}/20} \leq e^{p^{-1}/5 \cdot (\log(4/15)+4/15+1/4)} \leq \left(\frac{5}{11}\right)^{p^{-1}/5}.
    \end{align*}

    Note that for a fixed tower vector of the form $ \varphi_1(h) = (L, h_{r+1}, \dots, h_s)$, the entries $h_1, \dots, h_{r-1}$ of the preimage must sum up to a number less than $p^{-1}/5$, for which there are less than $2^{p^{-1}/5}$ choices. After choosing $h_1, \dots, h_{r-1}$, the entry $h_r = L - \sum_{i=1}^{r-1}$ and the rest of the preimage is uniquely defined. Hence, the function $\varphi_1$ sends at most $2^{p^{-1}/5}$ tower vectors to the same image. Now, let $G \sim D(n,p)$ and $C = \left(\sum_h w(h)\right)^{-1}$. We get
    \begin{align*}
        \Pr\left(h_{1}(G) \leq \frac{p^{-1}}{20 \log(p^{-1})}\right) &= C \cdot \sum_{h \in \mathcal{H}_1}w(h) \leq C \cdot \sum_{h \in \mathcal{H}_1}w(\varphi_1(h))\cdot \left(\frac{5}{11}\right)^{p^{-1}/5}\\ &\leq 2^{p^{-1}/5} \cdot \left(\frac{5}{11}\right)^{p^{-1}/5} = \left(\frac{10}{11}\right)^{p^{-1}/5} = o(1).
    \end{align*}

    Now, let $\cH_2$ be the set of tower vectors $h = (h_1, \dots, h_s)$ with the following properties: 
    \begin{enumerate}[label = (\alph*)]
        \item the entries $h_i$ sum up to $n$;
        \item $\frac{p^{-1}}{20 \log (p^{-1})} \leq h_1 \leq 5p^{-1}$;
        \item $h_2 \leq \frac{p^{-1}}{\log^2(p^{-1})}$.
    \end{enumerate}
    Consider the function $\varphi_2$ that maps a tower vector $h = (h_1, \dots, h_s) \in \cH_2$ to the vector $\varphi_2(h) = (h_1, L, h_{r+1}, \dots, h_s)$, where $r = \min \{k:\sum_{i=2}^{k} h_i > p^{-1}/(800\log(p^{-1}))\}$ and $L = \sum_{i=2}^{r} h_i$. This is well-defined, as $p \geq 6/n$, so $\sum_{i=2}^s h_i \geq n - 5p^{-1} \geq n/6 > p^{-1}/(800\log(p^{-1}))$. Moreover, $\varphi_2(h)$ is again a valid tower vector, and by Lemma~\ref{lem:tower-distr}, we get
    \begin{align*}
        \frac{w(h)}{w(\varphi_2(h))} \leq \frac{L!}{\prod_{i=2}^{r} h_i!} (1-p)^{-\sum_{2\leq i<k\leq r}h_i h_k} \cdot \frac{\prod_{i=2}^{r} (1-(1-p)^{h_{i-1}})^{h_i}}{(1-(1-p)^{h_1})^{L}}.
    \end{align*}
    Here, increasing $h_r$ by $1$, while leaving $h_1, \dots, h_{r-1}$ the same, changes the expression above by a factor of 
    \begin{align*}
        \frac{L+1}{h_r + 1} \cdot (1-p)^{-\sum_{i=2}^{r-1}h_i} \cdot \frac{1-(1-p)^{h_{r-1}}}{1-(1-p)^{h_1}} \leq \frac{L}{h_r} \cdot (1-p)^{-p^{-1}/800}  \cdot \frac{6h_{r-1}}{h_1} \leq \frac{L}{h_r} \cdot \frac{1}{4}.
    \end{align*}
    Here, we used the Bernoulli-type inequalities $1-pm \leq (1-p)^m \leq 1-pm/(1+pm)$ together with the fact $h_1 \leq 5p^{-1}$. The factor above is strictly less than $1$ if, $h_r > L/4$, hence, we may assume $h_r \leq L/4$, and therefore $L \leq p^{-1}/(600 \log(p^{-1}))$. Reusing the bound on \eqref{eq1} from before, we get:
    \begin{align*}
        \frac{w(h)}{w(\varphi_1(h))} &\leq L^L e^{pL^2}\left(\frac{6p}{h_1p}\right)^{L-h_2} \leq L^L e^{L/600} \left(\frac{6}{30L}\right)^{L-h_2}\\ &\leq \left(\frac{1}{4}\right)^L \cdot e^{\log(5L)\cdot h_2} \leq \left(\frac{1}{4}\right)^{p^{-1}/(800 \log(p^{-1}))} e^{\log(5L) \cdot p^{-1} / \log^2(p^{-1})} \leq \left(\frac{1}{3}\right)^{p^{-1}/(800 \log(p^{-1}))},
    \end{align*}
    where the last step follows when $p$ is small enough. 
    Now, the function $\varphi_2$ sends at most $2^{p^{-1}/(800\log(p^{-1}))}$ tower vectors to the same image. Let $G \sim D(n,p)$ and $C = \left(\sum_h w(h)\right)^{-1}$. We conclude using Lemma~\ref{lem:upper-tailbd} and the result above:
    \begin{align*}
        \Pr\left(h_{2}(G) \leq \frac{p^{-1}}{\log^2(p^{-1})}\right) &\leq \Pr\left(h_{2}(G) \leq \frac{p^{-1}}{\log^2(p^{-1})} \wedge \frac{p^{-1}}{20 \log (p^{-1})} \leq h_1 \leq 5p^{-1}\right)\\
        &+ \Pr\left(h_1(G) < \frac{p^{-1}}{20\log(p^{-1})}\right) + \Pr\left(h_1(G) > 5p^{-1}\right)\\
        &\leq C \cdot \sum_{h \in \mathcal{H}_2}w(h) + o(1)\\ 
        &\leq C \cdot \sum_{h \in \mathcal{H}_2}w(\varphi_2(h)) \cdot \left(\frac{1}{3}\right)^{p^{-1}/(800 \log(p^{-1}))} + o(1) \\
        &\leq \left(\frac{2}{3}\right)^{p^{-1}/(800 \log(p^{-1}))} + o(1) = o(1).
    \end{align*}
\end{proof}


In the final proof of this section, we will make use of the Chernoff bound:

\begin{lemma}{(Chernoff bound, see \citet{mitzenmacher2005probability}, Theorem 4.5)} \label{lem:chernoff}
    Let $X_1, \dots, X_n$ be independent random variables with $\Pr(X_i=1) = p$ and $\Pr(X_i = 0) = 1-p$ and define $X = \sum_{i=1}^n X_i$. Then, for any $\delta \in (0,1)$, we have 
    \begin{align*}
        \Pr\left(X \leq (1-\delta)np\right) \leq e^{-np\delta^2/2}.
    \end{align*}
\end{lemma}

{
\renewcommand{\thetheorem}{\ref{prop:DAGs}}
\begin{prop}
    Let $6/n \leq p \leq o\left(\frac{1}{\log n}\right)$ and $G \sim D(n,p)$. Then, with probability $1-o(1)$, $G$ has a matching of reversible layer-2-edges of size at least $\frac{p^{-1}}{16e^5\log^2(p^{-1})}$.
\end{prop}
\addtocounter{theorem}{-1}
}


\begin{proof}
    Let $6/n \leq p \leq o\left(\frac{1}{\log n}\right)$ and $G \sim D(n,p)$. For technical reasons that will become apparent later, let us define $\widetilde{H_2}(G)$ to be a subset of $H_2(G)$ of at most $h_1(G)/2$ vertices. This subset can be picked by an arbitrary but fixed rule (for instance, take the $h_1(G)/2$ vertices in $H_2(G)$ with the smallest indices, according to some indexing of the vertex set $V(G)$), and $\widetilde{H_2}(G) = H_2(G)$ in the case $h_2(G) \leq h_1(G) / 2$. Now, let $S(G) \subseteq \widetilde{H_2}(G)$ be the set of vertices in $\widetilde{H_2}(G)$ that have exactly one parent. Furthermore, let $X(G)$ be the set of vertices in $S$ whose parent is different from all the other parents of vertices in $S$. By definition, the edges that connect vertices in $X(G)$ to their parents form a matching of reversible layer-2-edges. Hence, it suffices to bound $|X(G)|$. First, note that conditional on the tower decomposition $H(G) = H = (H_1, \dots, H_s)$ and on the event $S(G) = S$, the parent vertex of each vertex $v \in S$ is distributed uniformly and independently in $H_1$. Uniformity follows from the symmetry of the $D(n,p)$ distribution with respect to permuting vertices, and independence follows from Lemma~\ref{lem:tower-distr}, part~\ref{item:b}. By a union bound, we get for $v \in S$:
    \begin{align*}
        &\Pr\left(v \in X(G) \mid H(G) = H, S(G) = S\right)\\ &\geq 1 - \sum_{w \in S, w \neq v} \Pr\left(\Pa(v) = \Pa(w)\right)\\ &= 1 - \frac{|S|}{h_1} \geq 1 - \frac{|\widetilde{H_2}|}{h_1} \geq \frac{1}{2}.
    \end{align*}
    Hence, $\E[|X(G)| \mid H(G) = H, S(G) = S] \geq |S|/2$, and by a standard Chernoff concentration bound (see Lemma~\ref{lem:chernoff}), we get 
    \begin{align}
        \notag &\Pr\left(|X(G)| \leq |S|/4 \mid H(G) = H, S(G) = S\right)\\
        &\leq e^{-|S|/16}. \label{eq:conc-X}
    \end{align}
    Next, we turn our attention to bounding $|S(G)|$. Conditional on the tower distribution $H(G) = H = (H_1, \dots, H_s)$, we have for each vertex $v \in \widetilde{H_2}(G)$ by Lemma~\ref{lem:tower-distr}, part~\ref{item:b}:
    \begin{align*}
        &\Pr\left(v \in S \mid H(G) = H\right) = \Pr\left(|\Pa(v)| = 1 \mid H(G) = H\right)\\ &= \frac{h_1 \cdot p (1-p)^{h_1-1}}{\sum_{i = 1}^s\binom{h_1}{s}p^s(1-p)^{h_1-s}}
        =\frac{h_1 \cdot p (1-p)^{h_1-1}}{1 - (1-p)^{h_1}}\\ &\geq  \frac{h_1 \cdot p (1-p)^{h_1-1}}{h_1 \cdot p} \geq (1-p)^{h_1}.
    \end{align*}
    Here, we used Bernoulli's inequality in the third line of the derivation. This implies $\E[|S(G)| \mid H(G) = H] \geq (1-p)^{h_1}\cdot |\widetilde{H_2}|$. Since the events $v \in S(G)$ are again independent for different $v \in \widetilde{H_2}$ conditional on the tower distribution, we get by the Chernoff bound (Lemma~\ref{lem:chernoff}):
    \begin{align}
        \notag &\Pr\left(|S(G)| \leq \frac{(1-p)^{h_1}}{2} \cdot |\widetilde{H_2}| \middle | H(G) = H\right)\\ &\leq e^{-(1-p)^{h_1}|\widetilde{H_2}|/8}. \label{eq:conc-S}
    \end{align}
    Now, let $\cH$ be the set of tower decompositions $H = (H_1, \dots, H_s)$ satisfying $|H_1| \leq 5p^{-1}$ and $|H_2| \geq p^{-1}/\log^2(p^{-1})$. For $H \in \cH$, we get
    \begin{equation*}
        (1-p)^{h_1} \cdot |\widetilde{H_2}| \geq (1-p)^{5/p} \cdot \frac{p^{-1}}{\log^2(p^{-1})} \geq \frac{e^{-5}}{2}\cdot \frac{p^{-1}}{\log^2(p^{-1})},
    \end{equation*}
    where the last steps holds when $p$ is small enough. Set $\alpha(p) := p^{-1} / (4e^5 \log^2(p^{-1}))$. Then, for $H \in \cH$, equation~\eqref{eq:conc-S} implies 
    \begin{align*}
        &\Pr\left(|S(G)| \leq \alpha(p) \mid H(G) = H\right)\ \leq e^{-\alpha(p)/2}.
    \end{align*}
    Summing over all $H \in \cH$ gives 
    \begin{align*}
        \Pr\left(|S(G)| \leq \alpha(p) \wedge H(G) \in \cH\right) \leq e^{-\alpha(p)/2}.
    \end{align*}
    And by Lemma~\ref{lem:lower-tailbd} and~\ref{lem:upper-tailbd}, we get 
    \begin{align*}
        \Pr\left(|S(G)| \leq \alpha(p)\right) &\leq e^{-\alpha(p)/2} + \Pr\left(H(G) \notin \cH\right)\\ &= o(1). 
    \end{align*}
    Now, summing equation~\eqref{eq:conc-X} over all graphs with $S(G) \geq \alpha(p)$ gives 
    \begin{align*}
        \Pr\left(|X(G)| \leq \alpha(p)/4 \wedge S(G) \geq \alpha(p)\right) \leq e^{-\alpha(p)/16}.
    \end{align*}
    So, we finally obtain
    \begin{align*}
        \Pr\left(|X(G)| \leq \alpha(p)/4\right) &\leq e^{-\alpha(p)/16} + \Pr\left(S(G) \leq \alpha(p)\right)\\ &= o(1). 
    \end{align*}
    Hence, with high probability, $G$ has a matching of reversible layer-2-edges of size at least $\alpha(p)/4$.
\end{proof}



\section{Proofs for Directed Cyclic Graphs} \label{apx:dcgs}

The following statement is a simple observation of the properties of the construction given in Definition~\ref{defn:reverse}.

\begin{lemma}\label{lem:reverse-properties}
Let $G$ be a directed cyclic graph containing a cycle $C$. Let $H = \rgc$ and let $\overline{C}$ be the reversed version of $C$ that occurs in $H$. We have the following properties: 
\begin{enumerate}
    \item each vertex has the same descendants in $G$ as in $H$;
    \item $G = \textsc{Reverse}(H, \overline{C})$.
\end{enumerate}
\end{lemma}

Now, we prove the key property of the construction in Definition~\ref{defn:reverse}.

{
\renewcommand{\thetheorem}{\ref{prop:ME-reverse}}
\begin{prop}
    Let $G$ be a directed cyclic graph containing a cycle $C$. Then, the graph $H = \textsc{Reverse}(G, C)$ is Markov equivalent to $G$. 
\end{prop}
\addtocounter{theorem}{-1}
}

\begin{proofof}{Proposition~\ref{prop:ME-reverse}}
    Suppose $C = (v_1, \dots, v_k)$ in $G$ and $H = \textsc{Reverse}(G, C)$. Fix an arbitrary conditioning set $Z \subseteq V(G)$. Let $\pi = (w_1, \dots, w_t)$ be a simple active path between $w_1$ and $w_t$ given $Z$ in $G$. The first part of the proof is to show that there exists an active path from $w_1$ to $w_t$ given $Z$ in $H$. \\

    \textbf{Case 1:} Suppose some vertex of $C$ is in $Z$, i.e. $C \cap Z \neq \emptyset$. Consider the path $\pi'$ in $H$ obtained as follows: 
    \begin{itemize}
        \item whenever $w \to v_i$ occurs in $\pi$ for $v_i \in C$, replace it with $w \to v_{i-1} \leftarrow v_i$ (similarly, if $v_i \leftarrow w$ occurs in $\pi$, replace it with $v_i \to v_{i-1} \leftarrow w$). 
        \item make the resulting path simple by deleting any self-loops if they exist.
    \end{itemize}
    By definition of $H = \rgc$, $\pi'$ is a valid simple path from $w_1$ to $w_t$ in $H$. We show that $\pi'$ is also an active path given $Z$. 

    First, consider any segment $a - b - c$ in $\pi'$ with $b \notin C$. If $b$ is a collider in the segment, i.e., we have $a \to b \leftarrow c$, then $a \to b \leftarrow c$ must occur in $\pi$ as well, since incoming edges to $b \notin C$ are never changed between $\pi$ and $\pi'$. This means $b$ has a $G$-descendant in $Z$, and by part 1 of Lemma~\ref{lem:reverse-properties}, $b$ must also have an $H$-descendant in $Z$, so $a \to b \leftarrow c$ is active in $\pi'$. If $b$ is a non-collider in $a - b - c$, then it must also occur as a non-collider in $\pi$ (but perhaps in a different segment). This is because outgoing edges from $b$ in $\pi'$ that do not exist in $\pi$ must have been a replacement for another outgoing edge from $b$ in $\pi$. Since $\pi$ is active, this means $b \notin Z$, and hence the segment $a - b - c$ is active in $\pi'$. 

    Since $C$ contains a vertex of $Z$, any collider in $C$ is automatically active. To show that the entire path $\pi'$ is active, it now suffices to show that any vertex $v_i \in C$ that is a non-collider in $\pi'$ must have been a non-collider in $\pi$ as well. Indeed, if $v_i$ is a non-collider in $\pi'$ with an outgoing edge $v_i \to w$ with $w \neq v_{i-1}$, then this outgoing edge must exist in $\pi$ or must be a replacement for another outgoing edge in $\pi$ from $v_i$, so $v_i$ is also a non-collider in $\pi$. If $v_i$ is a non-collider in a circle segment $v_{i+1} \to v_i \to v_{i-1}$ in $\pi'$, then $v_i$ must occur as a non-collider in the segment $v_{i+1} \leftarrow v_i \leftarrow v_{i-1}$ in $\pi$. Finally, we could have $w \to v_i \to v_{i-1}$ in $\pi'$ for $w \neq v_{i+1}$, but this is only possible if $w \to v_{i+1} \leftarrow v_i \leftarrow v_{i-1}$ occurred in $\pi$. In each case, $v_i$ is also a non-collider in $\pi$, which concludes the argument. 

    \textbf{Case 2:} Suppose none of the vertices in $C$ is part of the conditioning set $Z$, i.e. $C \cap Z = \emptyset$. In this case, we have to construct the path $\pi'$ in $H$ in a different way: 
    \begin{itemize}
        \item whenever $w \to v_i$ occurs in $\pi$ for $v_i \in C$, replace it with $w \to v_{i-1} \to v_{i-2} \to \dots \to v_{i}$ (similarly, if $v_i \leftarrow w$ occurs in $\pi$, replace it with $v_i \leftarrow v_{i+1} \leftarrow \dots \leftarrow v_{i-1} \leftarrow w$). 
        \item make the resulting path simple by deleting any self-loops if they exist.
    \end{itemize}
    By definition of $H = \rgc$, $\pi'$ is a valid simple path from $w_1$ to $w_t$ in $H$. We show that $\pi'$ is also an active path given $Z$. 

    By the same argument as in the first case, any segment $a - b - c$ of $\pi'$ with $b \notin C$ must be active. Since $C$ does not contain any vertex in $Z$, any non-collider of $\pi'$ in $C$ is active too. Hence, it suffices to show that every collider of $\pi'$ in $C$ is active. If $\pi'$ contains a segment $w \to v_i \leftarrow u$ with $w, u \neq v_{i+1}$, then $\pi$ must contain the segment $w \to v_{i+1} \leftarrow u$. Since $\pi$ is active, $v_{i+1}$ must have a $G$-descendant in $Z$, and by part 1 of Lemma~\ref{lem:reverse-properties}, this is also an $H$-descendant. Hence, also $v_i$ has an $H$-descendant in $Z$, so $w \to v_i \leftarrow u$ is active in $\pi'$. Finally, note that $\pi'$ cannot contain a segment of the form $w \to v_i \leftarrow v_{i+1}$, by construction. This completes the first part of the proof. 

    We have shown that, whenever $a$ and $b$ are d-separated in $H = \rgc$ given $Z$, they also must be d-separated in $G$ given $Z$. However, since $G = \textsc{Reverse}(H, \overline{C})$ by part 2 of Lemma~\ref{lem:reverse-properties}, the converse must also hold. Hence, $G$ and $H$ are Markov equivalent. 
\end{proofof}




