\section{Theorems} \label{app:theorems}

Here we provide mathematical details concerning the stability of equilibria of the Equation \ref{eq:replicator} and the selection gradient. Additionally, we consider an extension of the model to a system of delay differential equation, where there is a delay $\tau>0$ in the realization of reallocations. Thus, allocations are of the form $X_{i,j}(p_i(t-\tau))$ and utility is:
    \begin{equation}
        U_i(t) = U(p_i(t),p_i(t-\tau)) = \sum_{j=1}^m \alpha_j \ln\!\left(1 + \frac{X_{i,j}(p_i(t-\tau))}{Y_{0,j} (p_i(t)N)^{\beta_j}}\right). \label{eqn:utility_lag}
    \end{equation}
Theorems \ref{thm:superlinear} and \ref{thm:sublinear} apply to the base model and Corollaries \ref{thm:superlinear_lag} and \ref{thm:sublinear_lag} apply to the model with delays.

\begin{theorem} \label{thm:superlinear}
    Let $\bar{p}_i = \bar{p}_j = \bar{p} \: \forall i,j$. If the weighted average scaling exponent is superlinear, then the equilibrium is stable. If it is sublinear, then the equililbrium is unstable.
\end{theorem}

\begin{proof}
    First we define the utility $U_i = \sum_{k=1}^m \alpha_k U_{i,k}$ and note the following:
    \begin{equation}
        \frac{\partial}{\partial p_i}(U_i-U_j) = \sum_{k=1}^m \alpha_k \frac{\partial}{\partial p_i}U_
        {i,k}\!\left(\frac{X_{i,k}}{Y_{0,k}(p_iN)^{\beta_k}}\right) = \sum_{k=1}^m \alpha_k \frac{U_{i,k}'}{Y_{0,k}(p_iN)^{\beta_k}}\!\left(X_{i,k}' - \beta_k\frac{X_{i,k}}{p_i}\right),
    \end{equation}
    where $U_{i,k}'$ and $X_{i,k}'$ are the derivatives of $U_{i,k}$ and $X_{i,k}$, respectively. The equilibrium $\bar{p}_i=\bar{p}_j=\bar{p} \: \forall i,j \implies U_i=U_j \: \forall i,j$. Then, linearizing about this equilibrium, the entries of the Jacobian matrix $\mathbf{J} = \{j_{i,j}\}$ with $i\neq j$ are:
    \begin{align}
        j_{i,i} &= \sum_{k=1}^m \bar{p}r_{i,k}\underbrace{(U_i-U_k)}_{0} + \bar{p}^2 r_{i,k}\frac{\partial U_i}{\partial p_i} = \bar{p}^2\bar{r}_i\sum_{l=1}^m \alpha_l \frac{U_{i,l}'}{Y_{0,l}(\bar{p}N)^{\beta_l}}\!\left(X_{i,l}' - \beta_l\frac{X_{i,l}}{\bar{p}}\right), \\
        j_{i,j} &= \bar{p}r_{i,j}\underbrace{(U_i-U_j)}_{0} - \bar{p}^2r_{i,j}\frac{\partial U_j}{\partial p_j} = - \bar{p}^2r_{i,j} \sum_{l=1}^m \alpha_l \frac{U_{j,l}'}{Y_{0,l}(\bar{p}N)^{\beta_l}}\!\left(X_{j,l}' - \beta_l\frac{X_{j,l}}{\bar{p}}\right),
    \end{align}
    where $\bar{r}_i = \sum_{j=1}^n r_{i,j}$. Note that though there may be a different utility function for each resource, we are assuming homogeneity among cities. Thus, $U_{i,l}'=U_{j,l}'$, $X_{i,l}=X_{j,l}$, and $X_{i,l}'=X_{j,l}' \: \forall i,j$. The Jacobian is thus:
    \begin{equation}
        \mathbf{J} = \underbrace{\left(\bar{p}^2\sum_{l=1}^m \alpha_l \frac{U_{i,l}'}{Y_{0,l}(\bar{p}N)^{\beta_l}} \left(X_{i,l}' - \beta_l\frac{X_{i,l}}{\bar{p}}\right)\right)}_{\Phi}
        \underbrace{\begin{bmatrix}
        \bar{r}_1 & -r_{1,2} & \cdots & -r_{1,n} \\
        -r_{1,2} & \bar{r}_2 & \cdots & -r_{2,n} \\
        \vdots & \cdots & \ddots & -r_{n-1,n} \\
        -r_{1,n} & -r_{2,n} & \cdots & \bar{r}_n
        \end{bmatrix}}_{\mathbf{M}},
    \end{equation}
    Note that the matrix $\mathbf{M} = \{m_{ij}\}$ is symmetric, has positive diagonal entries, and is zero-line (and row) sum. Particularly, it is positive semi-definite. Its eigenvalues are thus positive but for a zero eigenvalue corresponding to the constraint $\sum_{i=1}^n p_i=1$. Thus, $\mathbf{J}$ has all negative eigenvalues if $\Phi<0$.

    Recall that $U'_{il}>0$ by the assumption that utility is increasing with respect to resources allocated to the city. Thus, in the case where utility functions are the same across resource ($U_i=U_{ij}=U_{ik}$), $\Phi<0$ simplifies to:
    \begin{equation}
        \sum_{l=1}^m \kappa_l\left(X_{i,l}' - \beta_l\frac{X_{i,l}}{\bar{p}}\right) < 0, \label{eq:thm1_condition}
    \end{equation}
    where $\kappa_l = \alpha_l/(Y_{0,l}(\bar{p}N)^{\beta_l})$. In the scenario of proportional distribution ($X_{i,l} = \gamma_l\bar{p}$), this condition simplifies further to $\sum_{l=1}^m \tilde{\kappa}_l \beta_l > 1$ where $\tilde{\kappa}_l = \gamma_l\kappa_l/(\sum_{l=1}^m \gamma_l\kappa_l)$ (i.e\ the weighted average is superlinear). Further, since there are diminishing returns to social welfare under the Nash social welfare function, the optimal allocation rule is a concave function. Thus, $X_{i,l}'<X_{i,l}/\bar{p}$. And therefore, this condition will also hold for legislatures that allocate by the Nash rule.
\end{proof}

\begin{corollary} \label{thm:superlinear_lag}
    Let $\bar{p}_i = \bar{p}_j \: \forall i, j$. Theorem \ref{thm:superlinear} holds for the corresponding system of delay differential equations where utility is defined by Equation \ref{eqn:utility_lag}.
\end{corollary}
\begin{proof}
    Linearizing with respect to $p(t)$ and $p(t-\tau)$, we have the following characteristic equation:
    \begin{equation}
        \det(\lambda\mathbf{I} - (\Phi_1e^{-\lambda_i\tau} - \Phi_2)\mathbf{M}) = 0,
    \end{equation}
    with
    \begin{align}
        \Phi_1 &= \bar{p}^2\sum_{l=1}^m \alpha_l \frac{U_{i,l}'}{Y_{0,l}(\bar{p}N)^{\beta_l}}X_{i,l}' > 0, \\
        \Phi_2 &= \bar{p}^2\sum_{l=1}^m \alpha_l \frac{U_{i,l}'}{Y_{0,l}(\bar{p}N)^{\beta_l}}\beta_l\frac{X_{i,l}}{\bar{p}} > 0.
    \end{align}
    Note that $\Phi_1 < \Phi_2$ is the condition for stability in Theorem \ref{thm:superlinear}. Since $\mathbf{M}$ is a real symmetric matrix, we may diagonalize it with invertible matrix $\mathbf{P}$ such that $\mathbf{M}=\mathbf{P}\mathbf{D}\mathbf{P}^{-1}$. We may then rewrite the characteristic equation:
    \begin{equation}
        \det(\lambda\mathbf{I} - (\Phi_1e^{-\lambda_i\tau} - \Phi_2)\mathbf{M}) = \det(\lambda \mathbf{I} - (\Phi_1e^{-\lambda_i\tau} - \Phi_2)\mathbf{D}) = 0.
    \end{equation}
    We thus have $n$ linear equations of the form $\lambda_i = (\Phi_1e^{-\lambda_i\tau} - \Phi_2)\mu_i$, where $\mu_i \geq 0$ are the diagonal entries of $\mathbf{D}$. Letting $\lambda_i = a + bi$ have positive real part and taking the modulus of both sides of the equation $\lambda_i/\mu_i + \Phi_2 = \Phi_1e^{-\lambda_i\tau}$, we have:
    \begin{equation}
        \Phi_2 < \sqrt{(a/\mu_i+\Phi_2)^2+(b/\mu_i)^2} = \Phi_1e^{-a\tau} < \Phi_1.
    \end{equation}
    However, $\Phi_2 < \Phi_1$ is a contradiction.
\end{proof}

\begin{theorem} \label{thm:sublinear}
    Let $\bar{p}_i = 1$ for some $i$, and thus $\bar{p}_j=0 \: \forall i \neq j$. If the weighted average scaling exponent is sublinear, then each $\bar{p}_i=1$ is a stable equilibrium.  If it is sublinear, then the equilibria are all unstable.
\end{theorem}
\begin{proof}
    We require that $U_i$ is an increasing function with respect to $p_i$ near $\bar{p}_i=1$. Taking the derivative we then have the condition:
    \begin{equation}
        \sum_{l=1}^m \kappa_l(X_{i,l}' - \beta_l X_{i,l}) > 0.
    \end{equation}
    where $\kappa_l = \alpha_l/(Y_{0,l}N^{\beta_l})$. In the scenario of proportional distribution ($X_{i,l} = \gamma_l$), this condition simplifies further to $\sum_{l=1}^m \tilde{\kappa}_l \beta_l < 1$ where $\tilde{\kappa}_l = \gamma_l\kappa_l/(\sum_{l=1}^m \gamma_l\kappa_l)$ (i.e\ the weighted average is sublinear).
\end{proof}

\begin{corollary} \label{thm:sublinear_lag}
    Let $\bar{p}_i = 1$ for some $i$, and thus $\bar{p}_j=0 \: \forall i \neq j$. Then, Theorem \ref{thm:sublinear} holds for the corresponding system of delay differential equations where utility is defined by Equation \ref{eqn:utility_lag}.
\end{corollary}
\begin{proof}
    Linearizing with respect to $p(t-\tau)$ and evaluating at the equilibrium conditions, the coefficient of the term $e^{-\lambda\tau}$ in the linearization is zero. Thus, the characteristic equation is identical to the non-delay equation, and the stability conditions remain unchanged from that of Theorem \ref{thm:sublinear}.
\end{proof}

\begin{lemma}
    Let allocations be proportional and $\beta_1>\beta_2$. Then, $\Theta \geq 1$ is a sufficient condition for $S'(\alpha_i) > 0$.
\end{lemma}
\begin{proof}
    The selection gradient is:
\begin{equation}
    S'(\alpha_i) = \frac{\partial S(\tilde{\alpha}_i,\alpha_i)}{\partial \tilde{\alpha}_i} \bigg|_{\tilde{\alpha}_i=\alpha_i} = \ln\!\left(1 + \frac{\gamma_1p^{1-\beta_1}}{Y_{0,1}N^\beta_1} \right) - \ln\!\left(1 + \frac{\gamma_2p^{1-\beta_2}}{Y_{0,2}N^\beta_2} \right).
\end{equation}
$S'(\alpha_i)$ is positive if:
\begin{equation}
    \ln\!\left(1 + \frac{\gamma_1p^{1-\beta_1}}{Y_{0,1}N^\beta_1} \right) > \ln\!\left(1 + \frac{\gamma_2p^{1-\beta_2}}{Y_{0,2}N^\beta_2} \right)
    \implies \frac{\gamma_1p^{1-\beta_1}}{Y_{0,1}N^\beta_1} > \frac{\gamma_2 p^{1-\beta_2}}{Y_{0,2}N^\beta_2}
    \implies \Theta p^{\beta_2-\beta_1} > 1.
\end{equation}
Since $\beta_2-\beta_1 < 0 \implies p^{\beta_2-\beta_1} > 1$, $\Theta \geq 1$ is a sufficient condition for $S'(\alpha_i) > 0$.
\end{proof}

\section{Simulation methods and Nash social welfare allocations} \label{app:methods}

Here we detail the simulation methods and present supplementary results for a scenario in which allocations are determined by a legislature maximizing the Nash social welfare function.

All simulations were implemented in Julia and use the DifferentialEquations package \citep{rackauckas17}. The setup consists of $10^2$ cities arranged in a square grid. Three resources are considered with weights $\alpha_j=1/3$ and constant baselines $Y_{0,j}=1$ for all $j$. Utility is defined by Equation \ref{eq:utility}, and the total population size is normalized to $N=1$. $r_{ij}$ is the square of the Euclidean distance between cities $i$ and $j$ on the grid.

The Interior Point OPTimizer (Ipopt) \citep{wachter06} and the JuMP packages \citep{lubin23} are used to compute the allocations that maximize Nash social welfare assuming a total budget $B=1$. Note that the budget can be either divided into fixed sub-budgets for each allocation, $B_j$, or allocations can be drawn from a single common budget. In the former scenario, $\sum_{i=1}^n X_{i,j} = B_j$ and $\sum_{j=1}^m = B$. In the latter, $\sum_{i=1}^n\sum_{j=1}^m X_{i,j} = B$. Here we depict results for the latter scenario, though both results are similar (and both are implemented in the code). Additionally, we also assume that there is no local funding of allocations: they are entirely determined by the central government's allocations.

