	For subsequent constructions it will be useful to introduce coordinates on $\cT$. Denote by $L_{n,k}$ the distance between the root $o$ and  $X_{n,k}$, i.e. the length of the unique path between $o$ and $X_{n,k}$ obtained by summing the lengths of all edges in the path. Then by $(n,k,t)$ with $t\in[L_{n,k}-\ell_{n,k},L_{n,k}]$ we denote the point of $e_{n,k}$ which is at the distance  $L_{n,k}-t$ from $X_{n,k}$. In this notation,
	\[
	X_{n,k}=(n,k,L_{n,k})=(n+1,pk+j,L_{n,k}) \text{ for any } j\in\{0,\dots,p-1\}.
	\]
	Let $w:\cT\to(0,\infty)$ be a locally bounded measurable function, which will be used
	as an integration weight: for $f:\cT\to\C$ one defines
	\[
	\int_\cT f\dd\mu:=\sum_{n=0}^\infty\sum_{k=0}^{p^n-1} \int_{L_{n,k}-\ell_{n,k}}^{L_{n,k}}f(n,k,t)\,w(n,k,t)\dd t,
	\]
	then
	\[
	L^2(\cT):=\big\{f:\cT\to\C:\ \|f\|^2_{L^2(\cT)}:=\int_\cT |f|^2\dd\mu<\infty\big\}.
	\quad
	\]
	Due to the above definition the set of vertices has zero measure. Therefore, each measurable function $f:\cT\to\C$
	can be identified with a family of functions $(f_{n,k})$,
	\begin{gather*}
		f_{n,k}:=f(n,k,\cdot):\ (L_{n,k}-\ell_{n,k},L_{n,k})\to \C,\quad
		n\in\N_0,
		\quad
		k\in\{0,\dots,p^n-1\}.
	\end{gather*}
	Then $f=(f_{n,k})$ belongs to $L^2(\cT)$ if and only if
	\[
	\|f\|^2_{L^2(\cT)}:=\sum_{n=0}^\infty\sum_{k=0}^{p^n-1} \int_{L_{n,k}-\ell_{n,k}}^{L_{n,k}}\big|f_{n,k}(t)\big|^2w_{n,k}(t)\dd t<\infty.
	\]
	A function $f:\T\to\C$ is called continuous if $t\mapsto f_{n,k}(t)$ is continuous for all $n, k$ and, additionally, $f$ is continuous in the vertices. 
	In other words, $f_{n,k}(L_{n,k}^-)=f_{n+1,pk+j}(L_{n,k}^+)$ for all $n,k,j$. 
	If $f=(f_{n,k})$ is such that all $f_{n,k}$ have locally integrable distributional derivatives $f'_{n,k}$, we denote $f':=(f'_{n,k})$.


	The first Sobolev space $H^1(\cT)$ on $\cT$ is then introduced as
	\begin{gather*}
		H^1(\cT):=\{f\in L^2(\cT): f \text{ is continuous with } f'\in  L^2(\cT)\},\\
		\|f\|^2_{H^1(\cT)}:=\|f\|^2_{L^2(\cT)}+\|f'\|^2_{L^2(\cT)}.
	\end{gather*}
	Moreover, we denote
	\begin{align*}
		H^1_c(\cT)&:=\{f\in H^1(\cT): \text{ there exists $N\in\N$ such that } f_{n,k}\equiv 0\\
		&\qquad\qquad\qquad \text{ for all $(n,k)$ with $n>N$}\},\\
		H^1_0(\cT)&:=\text{the closure of $H^1_c(\cT)$ in $H^1(\cT)$,}\\
		\Tilde H^1(\cT)&:=\big\{ f\in H^1(\cT):\ f(o)=0\big\},\\
		\Tilde H^1_0(\cT)&:=\big\{ f\in H^1_0(\cT):\ f(o)=0\big\},\\
		\Tilde H^1_c(\cT)&:=\big\{ f\in H^1_c(\cT):\ f(o)=0\big\},
	\end{align*}
and remark that $\Tilde H^1_c(\cT)$ is a dense subset of $\Tilde H^1_0(\cT)$.

While the above definitions make sense for any choice of lengths $\ell_{n,k}$ and weights $w$, we introduce
additional conditions in order to have a more controllable global structure of $\cT$ and nice properties
of the associated Sobolev spaces. First, we assume that the weight function $w$ is constant on each edge, which 
induces the edge weigths
\[
\omega_{n,k}:=w|_{e_{n,k}}\in(0,\infty).
\]
The above $p$-adic metric tree $\cT$ equipped with edge lengths $\ell_{n,k}$ and edge weights $\omega_{n,k}$ will
be sometimes denoted as
\[
\cT^p\big((\ell_{n,k}),(\omega_{n,k})\big).
\]
In what follows we will always assume that there are some $\omega>0$ and $\ell\in(0,1)$ with
\begin{equation}
	\label{eq-lpa}
\ell < \omega p < \frac{1}{\ell}
\end{equation} 
and $C\ge 1$ such that for every $(n,k)$ there holds
		\begin{equation}
			\label{eq-ccc}
		\frac{1}{C} \ell^n \le  \ell_{n,k} \le C \ell^n \quad \text{ and } \quad \frac{1}{C} \omega^n \le  \omega_{n,k} \le C \omega^n.
		\end{equation}
The above assumption on the edge lengths guarantees, in particular, that the height of the tree is finite (which means that the distance to the root is bounded). On the other hand, the assumption on the weights combined with the upper bound in \eqref{eq-lpa} is a necessary and sufficient condition for constant functions to belong to $L^2(\cT)$, cf. \cite[proof of Theorem 3.10]{jks}. The role of the remaining assumptions will be discussed further in the paper. 

Moreover, if the stronger condition
\[
\ell_{n,k}=L_0 \ell^n,\quad
\omega_{n,k}=\omega_0 \omega^n
\text{ for all $(n,k)$}
\]		
is fulfilled (with some fixed $L_0>0$ and $\omega_0>0$), then the tree will be called \emph{geometric}	and denoted as
\begin{equation}
	\label{tgeom}
\TT^p\big(L_0,\ell,\omega_0,\omega\big).
\end{equation}
The following two results will show that the spaces $H^1(\cT)$, $H^1_0(\cT)$, $L^2(\cT)$ behave similarly to their counterparts on finite intervals of $\mathbb{R}$.  First of all, due to the assumption \eqref{eq-ccc} on $\ell$ and $\omega$, the following important result holds true: 
\begin{lem}\label{lemcomp}
The embedding $H^1(\T)\hookrightarrow L^2(\T)$ is compact, and
there is a constant $C_0>0$ such that
\begin{equation}
	\label{poincare}
	\|f\|_{L^2(\cT)} \leq C_0 \|f'\|_{L^2(\cT)} \qquad \text{ for all } f \in \widetilde{H}^1(\cT),
\end{equation}
and 
\begin{equation}
	\label{skal1}
	\langle f,g\rangle_{\Tilde H^1(\T)}:=\langle f',g'\rangle_{L^2(\T)}\equiv\int_\T f'\overline{g'}\dd \mu
\end{equation}
is a scalar product on $\Tilde H^1(\T)$ which is equivalent to the induced scalar product inherited from $H^1(\T)$.
\end{lem}
\begin{proof}
For the case $\cT=\TT^p(1,\ell,1,\omega)=:\mathbb{T}$ the compactness of the embedding is shown in \cite[Sec.~3.5]{jks}
and the assertions on the ineqality  \eqref{poincare} and the scalar product are shown in \cite[Sec.~2.3]{Embedded Trace}. 
Now we consider the dilation operator
\begin{gather*}
\varphi:\ \TT\to\cT,\qquad
\varphi(n,k,t)=\Big(n,k,L_{n,k}-\ell_{n,k}+\dfrac{t-t_{n-1}}{\ell^n}\ell_{n,k}\Big),\\
t_{-1}:=0,\quad t_n:=\sum_{k=0}^n \ell^k \text{ for }n\in\N_0,
\end{gather*}
and note that due to the assumptions \eqref{eq-ccc} the map $f\mapsto f\circ\varphi$ defines isomorphisms $L^2(\cT)\to L^2(\TT)$, $H^1(\cT)\to H^1(\TT)$ and $\Tilde H^1(\T)\to \Tilde H^1(\TT)$, see \cite[Sec.~4.3]{Embedded Trace}, which extends the both results to $\cT$.
\end{proof}
The next result will be elaborated later, cf. Theorem \ref{thm-trace}, however, we state it here to facilitate the understanding of the function spaces.
	\begin{lem}
		\label{lem:func_spaces}
$H^1_0(\mathcal{T})\subsetneq H^1(\mathcal{T})$ and $\widetilde{H}^1_0(\mathcal{T})\subsetneq \widetilde{H}^1(\mathcal{T})$.	
	\end{lem}


\subsection{Laplacian}\label{sec22}
We will use the dual space
\[
H^{-1}(\T):=\big(\widetilde{H}^1_0(\T)\big)'.
\]

\begin{defn}\label{defn-laplacian}
For $f\in H^1(\T)$ define the Laplacian $\Delta_\T f \in H^{-1}(\cT)$ of $f$ by
\begin{equation}
	\label{eq-deltat}
	\big(\Delta_\T f, g \big)_{H^{-1}(\T),\widetilde{H}^{1}_0(\T)} := - \int_\T f' g' \dd\mu\equiv - \langle f, \overline{g} \rangle_{\widetilde{H}^1(\T)} \text{ for all } g\in \widetilde{H}^1_0(\T).
\end{equation}
We also define 
\[
H^1_\Delta(\T) :=\Big\{ f \in H^1(\T):\ \Delta_\T f \in L^2(\T) \Big\},
\]
which will be equipped with the scalar product
\[
\langle f,g\rangle_{H^1_\Delta(\T)}:=\langle f,g\rangle_{H^1(\T)}+\langle \Delta_\cT f,\Delta_\cT g\rangle_{L^2(\T)}.
\]
\end{defn}

	Remark that Definition \ref{defn-laplacian} defines a weighted Laplace operator, i.e.\, it is a counterpart of an operator $\mu^{-1}\partial_x(\mu\partial_x.)$ on the real line, rather than $\partial_x^2$.
	This is explained in the following coordinate reformulation:
\begin{prop}\label{prop23}
For any $f=(f_{n,k})\in H^1(\T)$ and $h\in L^2(\cT)$ the following two con\-ditions are equivalent:
\begin{enumerate}
	\item[(a)] $\Delta_\cT f=h$,
	\item[(b)] $f''\in L^2(\T)$, and $f$ satisfies the Kirchhoff transmissition conditions
	\begin{equation} \label{kirchhoff}
		f'_{n,k}(L_{n,k}^-)\omega_{n,k} = \sum_{j=0}^{p-1} f'_{n+1,pk+j}(L_{n,k}^+)\omega_{n+1,pk+j}
	\end{equation}
	at each node $X_{n,k}$, and $h=f''$.
\end{enumerate}	
\end{prop}


\begin{proof}
Let $f\in H^1_\Delta(\cT)$. Let $g\in \Tilde H^1_c(\cT)$ with $\supp g\subset e_{n,k}$, then 
\begin{align*}
\big( \Delta_\T f, g \big)_{H^{-1}(\T),\widetilde{H}^{1}_0(\T)}=\int_{\cT}  (\Delta_\cT f)_{n,k}g_{n,k}\dd\mu&\equiv
\int_{L_{n,k}-\ell_{n,k}}^{L_{n,k}} (\Delta_\cT f)_{n,k}(t)g_{n,k}(t)\omega_{n,k}\,\dd t \\
&=  -\int_{L_{n,k}-\ell_{n,k}}^{L_{n,k}} f'(t)g'(t) \omega_{n,k}\,\dd t.
\end{align*}
Due to $g_{n,k}\in H^1_0(e_{n,k})$ this implies $(\Delta_\T f )|_{{n,k}} = f''_{n,k}$ and, hence, $\Delta_\cT f=f''$.
Now let $g\in \Tilde H^1_c(\cT)$ be only supported on the edges incident to $X_{n,k}$, then the integration by parts
yields
\begin{align*}
	\big( \Delta_\T f, &g \big)_{H^{-1}(\T),\widetilde{H}^{1}_0(\T)}\equiv
	\int_{L_{n,k}-\ell_{n,k}}^{L_{n,k}}f''_{n,k}(t)g_{n,k}(t)\omega_{n,k}\dd t\\
	&\quad+ \sum_{j=0}^{p-1} \int_{L_{n+1,pk+j}-\ell_{n+1,pk+j}}^{L_{n+1,pk+j}} f''_{n+1,pk+j}(t) g_{n+1,pk+j}(t)\omega_{n+1,pk+j}\dd t\\
	&=-\int_{L_{n,k}-\ell_{n,k}}^{L_{n,k}}f'_{n,k}(t)g'_{n,k}(t)\omega_{n,k}\dd t\\
	&\quad- \sum_{j=0}^{p-1} \int_{L_{n+1,pk+j}-\ell_{n+1,pk+j}}^{L_{n+1,pk+j}} f'_{n+1,pk+j}(t) g'_{n+1,pk+j}(t)\omega_{n+1,pk+j}\dd t\\
	&\quad +\Big(f'_{n,k}(L_{n,k}^-)\omega_{n,k} - \sum_{j=0}^{p-1} f'_{n+1,pk+j}(L_{n,k}^+)\omega_{n+1,pk+j}\Big)g(X_{n,k})\\
	&=-\int_\cT f' g'\dd\mu +\Big(f'_{n,k}(L_{n,k}^-)\omega_{n,k} - \sum_{j=0}^{p-1} f'_{n+1,pk+j}(L_{n,k}^+)\omega_{n+1,pk+j}\Big)g(X_{n,k}),
\end{align*}
and due to the arbitrariness of $g(X_{n,k})$ we arrive at the condition \eqref{kirchhoff}. This shows that (a) implies (b), and the reciprocate implication follows directly using the integration by parts.
\end{proof}


Using the scalar product $\langle\cdot,\cdot\rangle_{\widetilde{H}^1(\T)}$ from \eqref{skal1} 
we arrive at the orthogonal direct sum decomposition
\begin{equation}
	\label{h1decomp}
\widetilde{H}^1(\T) = \widetilde{H}^1_0(\T) \oplus \big( \Tilde H^1(\cT)\cap \ker\Delta_\cT\big).
\end{equation}
By Lemma \ref{lem:func_spaces}, this decomposition is non-trivial. 
Furthermore, one has the following result:
\begin{lem}\label{lem24}
	For any $h\in L^2(\cT)$ there is a unique $u\in \Tilde H^1_0(\cT)$ with $\Delta_\cT u=h$,
	and
	\[
	L^2(\cT)\ni h\mapsto u\in \Tilde H^1_0(\cT)
	\]
	is a bounded linear map.
\end{lem}

\begin{proof}
By definition, a function $u\in \Tilde H^1_0(\cT)$ satisfies $\Delta_\cT u=h$
if and only if
\begin{align}
\label{eq:hg}
\langle h,g\rangle_{L^2(\cT)}\equiv
\big(h, \overline{g} \big)_{H^{-1}(\T),\widetilde{H}^{1}_0(\T)} = - \langle u, g\rangle_{\widetilde{H}^1(\T)} \text{ for all } g\in \widetilde{H}^1_0(\T).
\end{align}
Due to Lemma \ref{lemcomp} the left-hand side defines a continuous anti-linear functional on $\Tilde H^1(\cT)$ with respect to $g$,
and the existence and the uniqueness of $u$ follow by the Riesz representation theorem.
Choosing in \eqref{eq:hg} $g=u$ yields the upper bound
\begin{align*}
	\|u\|_{\Tilde H^1(\cT)}^2=-\langle h, u\rangle_{L^2(\cT)}\leq \|h\|_{L^2(\cT)}\|u\|_{L^2(\cT)}\leq C_0\|h\|_{L^2(\cT)}\|u\|_{\Tilde H^1(\cT)},
\end{align*} 
where the constant $C_0$ is from  \eqref{poincare}. This implies the boundedness of the map $h\mapsto u$. 
\end{proof}





\subsection{Multi-scale boundary decomposition and trace map}\label{sec23}
This section is devoted to the introduction of the notion of a trace on functions from $\mathcal{T}$. As discussed in the introduction, we will define a trace operator with values in $L^2(\Gamma)$, and provide tools necessary to analyze its properties. 
It will be convenient to denote
	\[
	d:=m-1
	\]
	then $\Gamma$ is a compact $d$-dimensional Riemannian manifold (see the introduction).
	We will need a special decomposition of $\Gamma$. To define it, we start with its counterpart in the Euclidean case; for a Lebesgue-measurable set $U\subset \mathbb{R}^d$ we denote by $|U|$ its $d-$dimensional Lebesgue measure. 

	\begin{defn}[Multiscale decomposition, Euclidean case]
		Let $U\subset\R^d$ be a bounded open set. A \emph{regular strongly balanced $p$-multiscale decomposition} of $U$ is a collection
		\[
		(U_{n,k})_{n\in\N_0,\, k\in\{0,\dots,p^n-1\}}
		\]
		of non-empty subsets $U_{n,k}$ of $U$ such that
		\begin{enumerate}
			\item $U_{0,0}=U$:
			\item For any $n\in\N_0$ the sets $U_{n,0}, \dots, U_{n,p^{n}-1}$ are disjoint-
			\item For any $n\in \N_0$ and $k\in\{0,\dots,p^n-1\}$ one has
			\begin{gather*}
				U_{n+1,pk+j}\subset U_{n,k} \text{ for any $j\in\{0,\dots,p-1\}$,}\quad
				\Big| U_{n,k}\setminus \bigcup\limits_{j=0}^{p-1} U_{n+1,pk+j}\Big|=0.
			\end{gather*}
			\item $|U_{n,k}|=\dfrac{|U|}{p^n}$ for all $n\in \N_0$ and $k\in\{0,\dots,p^n-1\}$.
			\item  There is $c_1>0$ such that for all $n\in\N_0$ and $k\in\{0,\dots,p^n-1\}$ one has
			\[
			\diam U_{n,k} \leq c_1 p^{-\frac{n}{d}}.
			\]
			\item There is $c_2>0$ such that for all $h\in \R^d$, $n\in\N_0$, $k\in\{0,\dots,p^n-1\}$ one has
			\[
			\big|U_{n,k}\setminus(U_{n,k}+h)\big| \leq c_2 |h|p^{-\frac{n(d-1)}{d}}.
			\]
		\end{enumerate}
	\end{defn}

The above conditions can be viewed as an hierarchical decomposition procedure: One sets $U_{0,0}:=U$, and if for some $n$ all $U_{n,k}$ are already constructed, then
one decomposes each $U_{n,k}$ (up to zero measure sets) into $p$ disjoint pieces $U_{n+1,pk+j}$, $j\in\{0,\dots,p-1\}$. The last three conditions control, in a sense, the size and the shape of $U_{n,k}$.

By using a cover of $\Gamma$ by local charts, we can define a multiscale decomposition on $\Gamma$. Here, given a subset $\Gamma'\subset \Gamma$, we denote by $|\Gamma'|$ its hypersurface measure. 
\begin{defn}[Multiscale decomposition, manifold case]\label{defn2}
A collection
\[
(\Gamma_{n,k})_{n\in\N_0,\,k=0,\dots,p^n-1}
\]
of subsets $\Gamma_{n,k}\subset\Gamma$
is called a \emph{regular strongly balanced regular $p$-multiscale decomposition} of $\Gamma$,
if the following conditions hold:
	\begin{enumerate}
		\item $\Gamma_{0,0}=\Gamma$.
		\item For any $n\in\N_0$ the sets $\Gamma_{n,0}, \dots, \Gamma_{n,p^{n}-1}$ are mutually disjoint.
		\item For any $n\in \N_0$ and $k\in\{0,\dots,p^n-1\}$ one has
		\begin{gather*}
			\Gamma_{n+1,pk+j}\subset \Gamma_{n,k} \text{ for any $j\in\{0,\dots,p-1\}$,}\quad
			\Big| \Gamma_{n,k}\setminus \bigcup\limits_{j=0}^{p-1}\Gamma_{n+1,pk+j}\Big|=0.
		\end{gather*}
		\item There is $N_0\in\N_0$ such that for all $K_0\in\{0,\dots,p^{N_0}-1\}$ the following conditions are satisfied:
		\begin{enumerate}
		\item $|\Gamma_{N_0,K_0}|=p^{-N_0} |\Gamma|$.
		\item The closure $\overline{\Gamma_{N_0,K}}$ is covered by a local chart
		$\Phi_{N_0,K_0}$ on $\Gamma$ such that the sets
		\[
		\Tilde\Gamma_{N_0,K_0}:=\Phi_{N_0,K_0}^{-1}(\Gamma_{N_0,K_0})
		\]
		are bounded open sets with Lipschitz boundaries in $\R^d$.
		\item The sets
		\[
		\Tilde \Gamma^{N_0,K_0}_{n,k}:=\Tilde \Gamma_{N_0+n,p^n K_0+k}:=\Phi_{N_0,K_0}( \Gamma_{N_0+n,p^n K_0+k}), \ n\in\N_0, \ k\in\{0,\dots,p^n-1\},
		\]
		form a regular strongly balanced $p$-multiscale decomposition of $\Tilde\Gamma_{N_0,K_0}$.
		\end{enumerate}
	\end{enumerate}
\end{defn}

For the rest of the paper we pick a collection $(\Gamma_{n,k})$ as in Definition~\ref{defn2}. Note the existence of such collections is proved in \cite[Example 5.4]{Embedded Trace}.

Let us define the parameter
\begin{equation}
	\label{eq-sigma}
	\sigma \equiv \sigma(\cT):= \frac{1}{2}\left(1- \frac{\log(\ell)-\log(\omega)}{\log(p)}\right),
\end{equation}
which is strictly positive due to \eqref{eq-lpa}. For what follows we additionally assume
\begin{equation}
	\label{eq-sigma2}
	\sigma d < \frac{1}{2}.
\end{equation}	

The following theorem was the main result of the paper~\cite{Embedded Trace}:

\begin{thm}[Dirichlet trace map on $\cT$]\label{thm-trace} The linear map
	\begin{align*}
		\gamma_0^\T: H^1(\T) &\longrightarrow H^{\sigma d}(\Gamma), \\
		f &\mapsto \lim_{N \rightarrow \infty} \sum_{K=0}^{p^N-1}f(X_{N,K}) \one_{\Gamma_{N,K}},
	\end{align*}
	with the limit being taken in $H^{\sigma d}(\Gamma)$, is a well-defined bounded surjective linear operator,
	and
	\[
	\ker \gamma_0^\T = H^1_0(\T).
	\]
\end{thm}
As a corollary one easily obtains
\begin{equation}
	\label{eq-hhh}
	\Tilde H^1(\cT)\cap \ker \gamma_0^\T =\Tilde H^1_0(\cT).
\end{equation}


For what follows it will be useful to have an explicit right inverse of $\gamma^\cT_0$ and to revise some constructions related to fractional Sobolev spaces. To do so, let us introduce some preliminary notation. First of all, given $N\in\N_0$ denote 
\begin{equation}
\begin{aligned}
	\label{pvn}
V_N(\Gamma)&:=\mathop{\mathrm{span}}\big\{\one_{\Gamma_{N,K}}:\ K\in\{0,\dots,p^N-1\}\big\},\\
P_N&:=\,\text{the orthogonal projector }L^2(\Gamma)\to V_N(\Gamma).
\end{aligned}
\end{equation}
As $V_N(\Gamma)\subset V_{N+1}(\Gamma)$ for any $N$, it follows that
\begin{align}
\label{eq:commutativity}
P_N P_n=P_{\min\{N,n\}} \text{ for any }N,n\in\N_0,\text{ which implies that }P_NP_n=P_nP_N.
\end{align}
Recall that for any $r\in(0,\frac{1}{2})$ one has the equality
\[
H^r(\Gamma) = \Big\{ f\in L^2(\Gamma):\  (p^{\frac{nr}{d}}\|f-P_nf\|_{L^2(\Gamma)}) \in \ell^2  \Big\}
\]
with an equivalent norm given by
\begin{equation}
	\label{norm-ar}
\|f\|^2_{A^r(\Gamma)}:=\|P_0 f\|^2_{L^2(\Gamma)}+\sum_{n=0}^\infty p^{\frac{2nr}{d}}\|f-P_n f\|^2_{L^2(\Gamma)},
\end{equation}
see \cite[Sec.~3]{Embedded Trace}. 
In particular, for any $N\to\infty$ one has
$P_N \big( H^r(\Gamma)\big)\subset H^r(\Gamma)$, and
we also recall that
\begin{equation}
	\label{l2conv}
\|f-P_N f\|_{L^2(\Gamma)}\xrightarrow{N\to\infty}0 \text{ for any } f\in L^2(\Gamma).
\end{equation}
Let us now argue that the above holds true with $L^2(\Gamma)$ replaced by $H^r(\Gamma)$. Indeed, provided $f\in H^r(\Gamma)$, by \eqref{norm-ar} it holds that 
\[
\|f-P_N f\|^2_{A^r(\Gamma)}=
\|P_0 (f-P_N f)\|^2_{L^2(\Gamma)}+\sum_{n=0}^\infty p^{\frac{2nr}{d}}\big\|(I-P_n)(f-P_Nf)\big\|^2_{L^2(\Gamma)}.
\]
Remark that each summand on the right-hand side converges to $0$ for $N\to\infty$, as the operators $P_0$ and $I-P_n$ are bounded and \eqref{l2conv} holds. Moreover, for each $n$ one has, with \eqref{eq:commutativity}, 
\[
\big\|(I-P_n)(I-P_N)f \big\|^2_{L^2(\Gamma)}=\big\|(I-P_N)(I-P_n)f \big\|^2_{L^2(\Gamma)}\le \|f-P_n f\|^2_{L^2(\Gamma)}.
\]
Hence, the dominated convergence theorem shows
\begin{equation}
	\label{pnf}
	P_N f\xrightarrow{N\to\infty}f \text{ in $H^r(\Gamma)$ for any }f\in H^r(\Gamma).
\end{equation}
Now we have all the necessary prerequisites to state the following result, which constructs an explicit $\Tilde H^1(\cT)$ lifting of an element of  $H^{\sigma d}(\Gamma)$. 
\begin{lem}\label{lem-vg}
Let $g\in H^{\sigma d}(\Gamma)$ and denote
	\[
	g_{n,k}:=\dfrac{1}{|\Gamma_{n,k}|}\int_{\Gamma_{n,k}}g\,\dd x.
	\]
Let $v:\cT\to\C$ be linear	on each edge $e_{n,k}$ with
\[
v(o)=0,\quad v(X_{n,k})=g_{n,k} \text{ for all }(n,k),
\]
then $v\in \Tilde H^1(\cT)$ with $\gamma^\cT_0 v=g$. Moreover, the linear mapping $H^{\sigma d}(\Gamma)\ni g\mapsto v\in \widetilde{H}^1(\mathcal{T})$ is bounded.  
\end{lem}	
\begin{proof}
To prove the above lemma, we need to verify that $v$ as defined in the statement of the lemma belongs to the space $\widetilde{H}^1(\mathcal{T})$, and that its trace is given by $g$.


Step 1: Estimating  $\|v'\|_{L^2(\T)}$. We have
\begin{equation}
	\label{vvv}
	\begin{aligned}
		v_{0,0}(t)&=g_{0,0}\dfrac{t}{\ell_{0,0}}, \quad v'_{0,0}(\cdot)=\dfrac{g_{0,0}}{\ell_{0,0}},\\
		v_{n+1,pk+j}(t)&=g_{n,k}+(g_{n+1,pk+j}-g_{n,k})\dfrac{t-L_{n,k}}{\ell_{n+1,pk+j}},\\
		v'_{n+1,pk+j}(\cdot)&=\dfrac{g_{n+1,pk+j}-g_{n,k}}{\ell_{n+1,pk+j}},
	\end{aligned}
\end{equation}
hence,
\begin{align*}
	\|v'\|^2_{L^2(\cT)}&=\dfrac{\omega_{0,0}}{\ell_{0,0}}|g_{0,0}|^2+\sum_{n=0}^\infty \sum_{k=0}^{p^n-1}\sum_{j=0}^{p-1}\dfrac{\omega_{n+1,pk+j}}{\ell_{n+1,pk+j}}|g_{n+1,pk+j}-g_{n,k}|^2.
\end{align*}
Using the assumption \eqref{eq-ccc} we have
\[
\dfrac{\omega_{n,k}}{\ell_{n,k}}\le C^2 \Big(\dfrac{\omega}{\ell}\Big)^n \text{ for all }(n,k),
\]
which results in
\begin{align}
	\label{eq:boundV}
\|v'\|^2_{L^2(\cT)}\le C^2\bigg[|g_{0,0}|^2+\sum_{n=0}^\infty \sum_{k=0}^{p^n-1}\sum_{j=0}^{p-1}\Big(\dfrac{\omega}{\ell}\Big)^{n+1}|g_{n+1,pk+j}-g_{n,k}|^2\bigg].
%\le\dfrac{C^2}{c^0}\|g\|^2_*<\infty.
\end{align}
To estimate the left-hand side via $g$, we use an equivalent norm $\|\cdot\|_*$ in $H^{\sigma d}(\Gamma)$:
\begin{align}
	\label{eq:equiv}
\|h\|^2_*:=\|P_0 h\|^2_{L^2(\Gamma)}+\sum_{n=0}^\infty p^{2 (n+1)\sigma}\|P_n g-P_{n+1} g\|^2_{L^2(\Gamma)},
\end{align}
see \cite[Sec.~3.2 and 3.4]{Embedded Trace}. Also, due to the choice of $\sigma$ in \eqref{eq-sigma} we have
\[
p^{2\sigma}=\dfrac{\omega p}{\ell}.
\]
For the function $g$ we have, using properties of the multiscale decomposition of $\Gamma$: 
\begin{align}
	\nonumber
	P_n g&=\sum_{k=0}^{p^n-1} g_{n,k}\one_{\Gamma_{n,k}},\\
	\label{eq:P0g}
	\|P_n g\|^2_{L^2(\Gamma)}&=\sum_{k=0}^{p^n-1} |g_{n,k}|^2 |\Gamma_{n,k}|,\\
	\nonumber
	P_n g-P_{n+1}g&=\sum_{k=0}^{p^n-1} g_{n,k}\one_{\Gamma_{n,k}} - \sum_{k=0}^{p^n-1}
	\sum_{j=0}^{p-1} g_{n+1,pk+j}\one_{\Gamma_{n+1,pk+1}},\\
	\nonumber
	&=\sum_{k=0}^{p^n-1}\sum_{j=0}^{p-1} (g_{n,k}-g_{n+1,pk+j})\one_{\Gamma_{n+1,pk+j}},\\
	\label{eq:Png}
	\|P_n g-P_{n+1}g\|^2_{L^2(\Gamma)}&=\sum_{k=0}^{p^n-1}\sum_{j=0}^{p-1}
	|g_{n,k}-g_{n+1,pk+j}|^2|\Gamma_{n+1,pk+1}|.
\end{align}
Due to the assumptions on $(\Gamma_{n,k})$ we can  find a constant $c_0>0$ such that $|\Gamma_{n,k}|\ge c_0p^{-n}$ for all $(n,k)$. 
From \eqref{eq:P0g} and \eqref{eq:Png} it follows that
\begin{align}
	\label{eq:firstg}
 \sum\limits_{k=0}^{p^n-1}|g_{n,k}|^2&\leq c_0^{-1}p^{n}\|P_ng\|_{L^2(\Gamma)}^2,\\
	\label{eq:secondg}
\sum_{k=0}^{p^n-1}\sum_{j=0}^{p-1}
	|g_{n,k}-g_{n+1,pk+j}|^2&\leq c_0^{-1}p^{n+1}\|P_n g-P_{n+1}g\|^2_{L^2(\Gamma)}.
\end{align}
Plugging in the above two bounds into \eqref{eq:boundV} yields 
\begin{align*}
	\|v'\|^2_{L^2(\mathcal{T})}\leq C^2c_0^{-1}\left(\|P_0g\|^2+\sum\limits_{n=0}^{\infty}\left(\frac{\omega p}{\ell}\right)^{n+1}\|P_{n}g-P_{n+1}g\|^2_{L^2(\Gamma)}\right)\leq C^2 c_0^{-1}\|g\|_*^2,
\end{align*}
by definition \eqref{eq:equiv}. 

Step 2: Estimating  $\|v\|_{L^2(\T)}$. From the explicit expressions \eqref{vvv} for $v$ we see that 
\begin{align*}
	\|v_{0,0}\|^2_{L^2(0,\ell_{0,0})}&\le |g_{0,0}|^2\ell_{0,0},\\
	\|v_{n+1,pk+j}\|^2_{L^2(L_{n,k},L_{n+1,pk+j})}&\le 2\big(|g_{n,k}|^2+|g_{n+1,pk+j}-g_{n,k}|^2\big)\ell_{n+1,pk+j}.
\end{align*}
Hence 
\begin{multline*}
	\|v\|^2_{L^2(\T)}\le |g_{0,0}|^2\ell_{0,0}\omega_{0,0}\\
	+2\sum_{n=0}^\infty\sum_{k=0}^{p^n-1}\sum_{j=0}^{p-1}\big(|g_{n,k}|^2+|g_{n+1,pk+j}-g_{n,k}|^2\big)\ell_{n+1,pk+j}\omega_{n+1,pk+j}.
\end{multline*}
With the help of \eqref{eq-lpa} and \eqref{eq-ccc} we estimate $\ell_{n,k}\omega_{n,k}\le C^2 (\ell\omega)^{n}$ for all $(n,k)$, and the above further rewrites 
\begin{multline*}
	\|v\|^2_{L^2(\T)} 
	\le C^2\big( |g_{0,0}|^2+2p\sum_{n=0}^\infty\sum_{k=0}^{p^n-1}(\ell\omega)^{n+1}|g_{n,k}|^2\\
	+2\sum_{n=0}^\infty(\ell\omega)^{n+1}\sum_{k=0}^{p^n-1}\sum_{j=0}^{p-1}|g_{n+1,pk+j}-g_{n,k}|^2\big).
\end{multline*}
We combine \eqref{eq:firstg} and \eqref{eq:secondg} to obtain 
\begin{multline*}
\|v\|^2_{L^2(\T)} 
	\le C^2c_0^{-1}\big( \|P_0g\|^2+2\sum_{n=0}^\infty (\ell\omega p)^{n+1}\|P_ng\|^2_{L^2(\Gamma)}\\+2\sum_{n=0}^\infty(\ell\omega p)^{n+1}\|P_ng-P_{n+1}g\|^2_{L^2(\Gamma)}\big).
\end{multline*}
The assumption \eqref{eq-lpa} $\ell \omega p <1$ and the inequality $\|P_n g\|_{L^2(\Gamma)}\leq \|g\|_{L^2(\Gamma)}$ allow to bound the first sum in the right-hand side by $\|g\|_{L^2(\Gamma)}$. As for the second sum, since $\ell\omega p<p^{2\sigma}$, we bound it by the norm \eqref{eq:equiv}. This yields the desired bound:
\begin{align*}
	\|v\|^2_{L^2(\T)}\leq C^2c_0^{-1}(2\|g\|_{L^2(\Gamma)}^2+2\|g\|_{*}^2).
\end{align*}

The results of the steps 1 and 2 show that $\|v\|_{H^1(\T)}\leq \widetilde{C}\|g\|_{H^{\sigma d}(\Gamma)}$ with some  $\widetilde{C}>0$ independent of $g$. 

Step 3: Computing the trace of $v$. 
By construction for each $n\in\N$ it holds that
\[
\sum_{k=0}^{p^n-1} v(X_{n,k})\one_{\Gamma_{n,k}}=\sum_{k=0}^{p^n-1} g_{n,k}\one_{\Gamma_{n,k}}=P_n g.
\]
For $n\to\infty$ the left-hand side converges in $H^{\sigma d}(\Gamma)$ to $\gamma^\cT_0 v$ (see Theorem \ref{thm-trace}), while the right-hand side converges to $g$ as shown in \eqref{pnf}, which gives the sought property $\gamma^\cT_0 v=g$.
\end{proof}






