\subsection{Normal derivative and Dirichlet-to-Neumann map}\label{sec24}


We will start with a simple boundary value problem for the Laplacian $\Delta_\cT$.
\begin{lem} \label{DPLEwell}
For any $g\in H^{\sigma d}(\Gamma)$ there is a unique solution $u=u_g$
of the Dirichlet problem
\begin{equation}
	 \label{eq-dirichlet}
\begin{aligned}
	\Delta_\T u &= 0, &
	\gamma^\T_0 u &= g, & u\in \Tilde H^1(\cT),
\end{aligned}
\end{equation}
and the map
\begin{equation}
	\label{eq-pt}
P_\cT: H^{\sigma d}(\Gamma)\ni g\mapsto u_g\in \Tilde H^1(\cT)
\end{equation}
is a bounded linear operator with $\Delta_\cT P_\cT=0$ and $\gamma^\cT_0 P_\cT=\Id$.
\end{lem}

\begin{proof}
In view of the decomposition \eqref{h1decomp} and the identity \eqref{eq-hhh} the map
\[
\gamma_0^\cT:\ \Tilde H^1(\cT)\cap \ker\Delta_\cT\to H^{\sigma d}(\Gamma)
\]
is a bounded bijective linear operator, hence, an isomorpshism by the closed graph theorem,
and its inverse is exactly the map $P_\cT$.
\end{proof}


\begin{defn}
For $u\in H^1_{\Delta}(\T)$, its normal derivative $\gamma^\cT_1 u\in H^{-\sigma d}(\Gamma)$ on $\Gamma$
is defined by the duality product:
	\begin{equation}
		\label{deriv}
	\big(\gamma^{\T}_1 u, \gamma^\cT_0 v\big)_{H^{-\sigma d}(\Gamma), H^{\sigma d}(\Gamma)}:=\int_\cT (\Delta_\T u) v\,\dd\mu+\int_\cT u'v'\,\dd\mu \text{ for all } v \in \Tilde H^1(\cT).
	\end{equation} 
\end{defn}

Remark that with the above choice of the duality product, for $g\in H^{-\sigma d}(\Gamma)$, $H^{\sigma d}(\Gamma)\ni\varphi\mapsto (g, \varphi)_{H^{-\sigma d}(\Gamma), H^{\sigma d}(\Gamma)}$ is a linear, rather than antilinear, form.

\begin{lem}\label{lem18}
	The map
	\[
	H^1_\Delta(\cT)\ni u\mapsto \gamma^\cT_1 u \in H^{-\sigma d}(\Gamma)
	\]
	is a well-defined bounded linear operator.
\end{lem}

\begin{proof}
	For $\gamma_0^\cT v=0$ in \eqref{deriv} one has $v\in\Tilde H^1_0(\cT)$, and the right-hand side is zero due to the definition of $\Delta_\cT$, so $\gamma^\cT_1 u$ is well-defined, and its linearity is clear.	It remains to show the continuity properties of $\gamma_1^{\T}$. 
	 With the help of the map $P_\cT$ from \eqref{eq-pt}, for any $g\in H^{\sigma d}(\cT)$ one has
	\begin{align*}
	\Big| \big(\gamma^{\T}_1 u, g\big)_{H^{-\sigma d}(\Gamma), H^{\sigma d}(\Gamma)}\Big|&\equiv 
	\Big|\big(\gamma^{\T}_1 u, \gamma^\cT_0 P_\cT g\big)_{H^{-\sigma d}(\Gamma), H^{\sigma d}(\Gamma)}\Big|\\
	&=\Big| \int_\cT (\Delta_\T u) P_\cT g\,\dd\mu+\int_\cT u' (P_\cT g)'\,\dd\mu\Big|\\
	&\le \|\Delta_\cT u\|_{L^2(\cT)}\|P_\cT g\|_{L^2(\cT)}+\|u'\|_{L^2(\cT)}\|(P_\cT g)'\|_{L^2(\cT)}\\
	&\le 2 \|u\|_{H^1_\Delta(\cT)} \|P_\cT g\|_{H^1(\cT)}\\
	&\le 2 \|u\|_{H^1_\Delta(\cT)} \|P_\cT\|_{H^{\sigma d}(\Gamma)\to H^1(\cT)} \|g\|_{H^{\sigma d}(\Gamma)},
	\end{align*}
	and by taking the supremum over all $g$ with $\|g\|_{H^{\sigma d}(\Gamma)}\le 1$ we arrive at the conclusion.
\end{proof}






\begin{defn}
The Dirichlet-to-Neumann operator $\D$ for $\cT$ is defined by
	\[
	\D:=\gamma^\cT_1 P_\cT:\ H^{\sigma d}(\Gamma)\to H^{-\sigma d}(\Gamma).
	\]
By Lemmas \ref{DPLEwell} and \ref{lem18} it is a bounded linear operator.
\end{defn}

For the following we make the trivial observation that the maps $\gamma^\cT_0$, $\gamma^\cT_1$, $\Delta_\cT$ and $P_\cT$ are real, e.g. commute with the pointwise complex conjugation. The following property of the Dirichlet-to-Neumann map will be important:

\begin{thm} \label{DTNtree}
The operator $\D$ is positive and coercive, i.e. for some $c>0$ one has,
	\[
	\big( \D g, \overline{g} \big)_{H^{-\sigma d}(\Gamma), H^{\sigma d}(\Gamma)} \ge c\|g\|^2_{H^{\sigma d}(\Gamma)} \text{ for any $g\in H^{\sigma d}(\Gamma)$.}
	\] 
\end{thm}

\begin{proof}
Let $g\in H^{\sigma d}(\Gamma)$. The substitution
$u:=P_\cT g$ and $v:=P_\cT \overline{g}$ in \eqref{deriv} yields
\begin{align*}
\big( \D g, \overline{g} \big)_{H^{-\sigma d}(\Gamma), H^{\sigma d}(\Gamma)}&=\int_\cT \big|(P_\cT g)'\big|^2\dd\mu=\|P_\cT g\|^2_{\Tilde H^1(\cT)},
\end{align*}
and with $\|g\|_{H^{\sigma d}(\Gamma)}=\|\gamma^\cT_0 P_\cT g\|_{H^{\sigma d}(\Gamma)}\le \|\gamma^\cT_0\|_{\Tilde H^1(\cT)\to H^{\sigma d}(\Gamma)}\|P_\cT g\|_{\Tilde H^1(\cT)}$
we arrive at
\[
\big( \D g, \overline{g} \big)_{H^{-\sigma d}(\Gamma), H^{\sigma d}(\Gamma)}\ge\dfrac{\|g\|^2_{H^{\sigma d}(\Gamma)}}{\|\gamma^\cT_0\|_{\Tilde H^1(\cT)\to H^{\sigma d}(\Gamma)}^2}.\qedhere
\]
\end{proof}


\subsection{Boundary values on finite sections}\label{sec-fin}
The question that we study in two next sections is the following. Assume that the infinite tree $\mathcal{T}$ is replaced by a tree $\widetilde{\T}_N$ which only contains a finite number of generations, and instead of solving the boundary-value problem for the Laplace equation with the Cauchy data $\gamma_0^{\mathcal{T}}u=g$, we solve the boundary-value problem on $\widetilde{\T}_N$, by imposing on its truncated boundary $\gamma_0^{\widetilde{\T_N}}u_N=P_Ng$. Is it possible to choose $\widetilde{\mathcal{T}}_N$ so that the associated Dirichlet-to-Neumann map is suitably close to $\D P_N$? In these two sections we give a positive answer to this question (Theorem \ref{thm221}), provided some auxiliary assumptions on $\mathcal{T}$. We start by formalizing the problem.

For $N\in\N$ denote by $\cT_N\equiv\cT^p_N\big((\ell_{n,k}),(\omega_{n,k})\big)$ the finite portion of the tree $\cT$ obtained by keeping the edges $e_{n,k}$ with $n\le N$ only, with the same edge lengths $\ell_{n,k}$ and edge weights $\omega_{n,k}$, i.e.
\[
\cT_N:=\big\{(n,k,t)\in\cT:\ n\le N\big\},
\]
and for $f:\cT_N\to\C$ one defines
\[
\int_{\cT_N} f\dd\mu:=\sum_{n=0}^N\sum_{k=0}^{p^n-1} \int_{L_{n,k}-\ell_{n,k}}^{L_{n,k}}f_{n,k}(t) \omega_{n,k}\dd t,
\qquad
f_{n,k}:=f(n,k,\cdot).
\]
This induces the spaces
\begin{gather*}
	L^2(\cT_N):=\big\{f:\cT_{N}\to\C:\ \|f\|^2_{L^2(\cT_N)}:=\int_{\cT_N} |f|^2\dd\mu<\infty\big\},\\
	\langle f,g\rangle_{L^2(\cT_N)}:=\int_{\cT_N} f\overline{g}\,\dd\mu,
\end{gather*}
and
\begin{gather*}
	H^1(\cT_N):=\big\{f\in L^2(\cT_N): f \text{ is continuous with } f'\in  L^2(\cT_N)\big\},\\
	\langle f,g\rangle_{H^1(\cT_N)}:=\langle f,g\rangle_{L^2(\cT_N)}+\langle f',g'\rangle_{L^2(\cT_N)}
\end{gather*}
as well as
\[
\Tilde H^1(\cT_N):=\big\{f\in H^1(\cT_N):\ f(o)=0\big\}.
\]
As the embedding $\Tilde H^1(\cT)\hookrightarrow L^2(\cT)$ is compact, there is $f_N\in \Tilde H^1(\cT)$ with $f_N\not\equiv 0$ such that for all $f\in \Tilde H^1(\cT_N)$ with $f\not\equiv 0$ it holds
\[
a_N:=\dfrac{\|f'_N\|^2_{L^2(\cT_N)}}{\|f_N\|^2_{L^2(\cT_N)}}\le \dfrac{\|f'\|^2_{L^2(\cT_N)}}{\|f\|^2_{L^2(\cT_N)}},
\]
and $a_N>0$ as $f_N$ cannot be constant. Hence, we have the Poincar\'e inequality
\[
\|f'\|^2_{L^2(\cT_N)}\ge a_N \|f\|^2_{L^2(\cT_N)} \text{ for all } f\in \Tilde H^1(\cT_N),
\]
which shows that
\[
\langle f,g\rangle_{\Tilde H^1(\cT_N)}:=\langle f',g'\rangle_{L^2(\cT_N)}
\]
is a scalar product on $\Tilde H^1(\cT_N)$ which is equivalent to the scalar product inherited from $H^1(\cT_N)$.

Recall that the subspaces $V_N(\Gamma)\subset L^2(\Gamma)$ were defined in \eqref{pvn}.
The set of the pending nodes $X_{N,K}$ with $K\in\{0,\dots,p^N-1\big\}$ represents the natural boundary of $\cT_N$, and by using the same multiscale decomposition $(\Gamma_{n,k})$ of $\Gamma$ one defines the bounded surjective Dirichlet trace operator
\[
	\gamma^{\T_N}_0:\  \widetilde{H}^1(\T_N) \ni f\mapsto \sum_{K=0}^{p^N-1} f(X_{N,K}) \one_{\Gamma_{N,K}}\in V_N(\Gamma)
\]
and the spaces
\[
H^1_0(\cT_N):=\big\{f\in H^1(\cT_N):\ \gamma^{\cT_N}_0f=0\big\},
\qquad
\Tilde H^1_0(\cT_N):=\big\{f\in \Tilde H^1(\cT_N):\ \gamma^{\cT_N}_0f=0\big\}.
\]
Any function in $H^1_0(\cT_N)$, respectively $\Tilde H^1_0(\cT_N)$, can be extended by zero to a function in $H^1_0(\cT)$, respectively $\Tilde H^1_0(\cT)$, and this extension preserves the respective norms.


\begin{defn}
	For $f\in H^1(\T_N)$ define its Laplacian
	\[
	\Delta_{\T_N} f \in H^{-1}(\cT_N):= \big(\Tilde H^1_0(\cT_N)\big)'
	\]
	by
	\begin{equation}
		\label{eq-deltatn}
		\big(\Delta_{\cT_N} f, g \big)_{H^{-1}(\cT_N),\widetilde{H}^{1}_0(\T_N)} := - \int_{\T_N} f' g' \dd\mu\equiv - \langle f, \overline{g} \rangle_{\widetilde{H}^1(\T_N)} \text{ for all } g\in \widetilde{H}^1_0(\T_N).
	\end{equation}

	We also define 
	\[
	H^1_\Delta(\T_N) :=\Big\{ f \in H^1(\T_N):\ \Delta_{\T_N} f \in L^2(\T_N) \Big\},
	\]
	which will be equipped with the scalar product
	\[
	\langle f,g\rangle_{H^1_\Delta(\T_N)}:=\langle f,g\rangle_{H^1(\T_N)}+\langle \Delta_{\cT_N}f,\Delta_{\cT_N} g\rangle_{L^2(\T_N)}.
	\]
\end{defn}
Remark that for any $f\in H^1_\Delta(\cT)$ one also has $f\in H^1_\Delta(\cT_N)$ with $\Delta_{\cT_N} f=\Delta_\cT f$ on $\cT_N$. Similarly to Proposition~\ref{prop23} one shows:


\begin{lem}\label{prop23-tn}
	For any $f=(f_{n,k})\in H^1(\T_N)$ and $h\in L^2(\T_N)$ the following two conditions are equivalent:
	\begin{enumerate}
		\item[(a)] $\Delta_{\T_N}f=h$,
		\item[(b)] $f''\in L^2(\T_N)$, and $f$ satisfies the Kirchhoff transmission conditions
		\begin{equation} \label{kirchhoff-tn}
			f'_{n,k}(L_{n,k}^-)\omega_{n,k} = \sum_{j=0}^{p-1} f'_{n+1,pk+j}(L_{n,k}^+)\omega_{n+1,pk+j}
		\end{equation}
		at each node $X_{n,k}\in T_N$ with $n\le N-1$, and $f''=h$.
	\end{enumerate}	
\end{lem}
