Remark that $\gamma^{\cT_N}_0 u\xrightarrow{N\to\infty}\gamma^{\cT} u$ in $H^{\sigma d}(\Gamma)$ for any $u\in H^1(\cT)$, see Theorem~\ref{thm-trace}. Let us establish a related approximation result for $\gamma^\cT_1 u$.

\begin{lem}\label{lem-weak}
	For any $u\in H^1_\Delta(\cT)$ one has $\gamma^{\cT_N}_1 u\xrightarrow{N\to\infty}\gamma^\cT_1 u$
	weakly in $H^{-\sigma d}(\Gamma)$.
\end{lem}
\begin{proof}
	Let $u\in H^1_\Delta(\cT)$ and $g\in H^{\sigma d}(\Gamma)$. In virtue of Lemma \ref{lem-vg} there is a function $v\in \Tilde H^1(\cT)$ such that
	\[
	\gamma^\cT_0 v=g,\quad v(X_{n,k})=\dfrac{1}{|\Gamma_{n,k}|}\int_{\Gamma_{n,k}} g\,\dd s \text{ for all }(n,k).
	\]
	Then
	\begin{align*}
		(\gamma^{\cT}_1 &u,g)_{H^{-\sigma d}(\Gamma),H^{\sigma d}(\Gamma)}=
		\int_{\cT}(\Delta_\T u)v\,\dd\mu+\int_{\cT}u'v'\,\dd\mu\\
		&=\lim_{N\to\infty}\Big( \int_{\cT_N}(\Delta_{\T_N} u)v\,\dd\mu+\int_{\cT_N}u'v'\,\dd\mu\Big)
		=\lim_{N\to\infty}\int_\Gamma (\gamma^{\cT_N}_1 u)(\gamma^{\cT_N}_0 v)\,\dd s\\
		&=\lim_{N\to\infty}\int_\Gamma \bigg( \sum_{K=0}^{p^N-1} \frac{\omega_{N,K}}{|\Gamma_{N,K}|} u_{N,K}'(L_{N,K}^-) \one_{\Gamma_{N,K}}\bigg)\bigg( \sum_{K=0}^{p^N-1} \dfrac{1}{|\Gamma_{N,K}|}\int_{\Gamma_{N,K}} g\,\dd s \,\one_{\Gamma_{N,K}}\bigg)\,\dd s\\
		&= \lim_{N\to\infty}\sum_{K=0}^{p^N-1} \frac{\omega_{N,K}}{|\Gamma_{N,K}|} u_{N,K}'(L_{N,K}^-) \int_{\Gamma_{N,K}} g\,\dd s \\
		&= \lim_{N\to\infty}\int_\Gamma\bigg(\sum_{K=0}^{p^N-1} \frac{\omega_{N,K}}{|\Gamma_{N,K}|} u_{N,K}'(L_{N,K}^-) \one_{\Gamma_{N,K}} \bigg)g\,\dd s\\
		&=\lim_{N\to\infty}(\gamma^{\cT_N}_1 u,g)_{H^{-\sigma d}(\Gamma),H^{\sigma d}(\Gamma)}. \qedhere
	\end{align*}	
\end{proof}


Using the scalar product $\langle\cdot,\cdot\rangle_{\widetilde{H}^1(\T_N)}$ we obtain the orthogonal direct sum decomposition
\begin{equation}
	\label{h1decomptn}
	\widetilde{H}^1(\T_N) = \widetilde{H}^1_0(\T_N) \oplus \big( \Tilde H^1(\cT_N)\cap \ker\Delta_{\cT_N}\big).
\end{equation}
As $\widetilde{H}^1_0(\T_N)$ is exactly the kernel of the map
\[
\gamma^{\cT_N}_0:\ \Tilde H^1(\cT_N)\to V_N(\Gamma),
\]
it follows that for any $g\in V_N(\Gamma)$ there is a unique solution $u=u_g$
of the Dirichlet problem
\begin{equation}
	\label{eq-dirichlet-tn}
	\begin{aligned}
		\Delta_{\T_N} u &= 0, &
		\gamma^{\T_N}_0 u&= g, &  u\in \Tilde H^1(\cT_N),
	\end{aligned}
\end{equation}
and the Dirichlet-to-Neumann map $\D^{\cT_N}$ for $\cT_N$ is defined by
\[
\D^{\cT_N}:\ V_N(\Gamma)\ni g\mapsto \gamma^{\cT_N}_1 u_g \in V_N(\Gamma).
\]


\subsection{Approximations of the Dirichlet-to-Neumann map}\label{sec-dtn}

The purpose of this subsection is to construct a good approximation for the Dirichlet-to-Neumann map $\D$ using finite-dimensional operators. These constructions are mainly adaptations of the ideas used in~\cite{msv} for discrete dyadic trees to the case of metric trees.


In Subsection \ref{sec23} we have seen that $P_N g\xrightarrow{N\to\infty}g$ in $H^{\sigma d}(\Gamma)$
for any $g\in H^{\sigma d}(\Gamma)$. Let us show that the convergence rate can be estimated under additional regularity assumptions. Recall that the norms $\|\cdot\|_{A^r(\Gamma)}$ are defined in \eqref{norm-ar}.

\begin{lem}\label{lem-pngg}
	Let $\sigma'$ be such that
	\[
	0<\sigma d<\sigma' d<\frac{1}{2},
	\]
	then for any $N\in\N_0$ and any $g\in H^{\sigma' d}(\Gamma)$ one has
	\begin{equation}
		\label{pngg}
	\|P_Ng-g\|_{A^{\sigma d}(\Gamma)} \le \dfrac{p^{2\sigma}}{p^{2\sigma}-1}p^{-N(\sigma'- \sigma )}\|g\|_{A^{\sigma'd}(\Gamma)}.
	\end{equation}
\end{lem}

\begin{proof}
With the definition of the norm $\|\cdot\|_{A^{\sigma' d}(\Gamma)}$, the right-hand side of 
 \eqref{pngg} rewrites as
\begin{align*}
	p^{-2N(\sigma'- \sigma )} \|g\|^2_{A^{\sigma'd}(\Gamma)} &= p^{-2N(\sigma'-\sigma)}\|P_0g\|^2_{L^2(\Gamma)}+ \sum_{n=0}^\infty p^{2n\sigma' - 2N\sigma'+2N\sigma } \|g-P_ng\|^2_{L^2(\Gamma)} \\
	&\ge p^{2N\sigma} \|g-P_Ng\|^2_{L^2(\Gamma)}  +p^{2N\sigma} \sum_{n=1}^\infty p^{2n\sigma'}\|g-P_{n+N}g\|^2_{L^2(\Gamma)}=:I. 
\end{align*}

To study the left-hand side of \eqref{pngg} we note first that
	\begin{align*}
	P_0(P_N g-g)&=P_0P_N g- P_0g\\
	&=P_{\min\{N,0\}}-P_0 g=P_0 g-P_0 g=0,\\[\smallskipamount]
	(P_Ng-g) - P_n(P_Ng -g) &= P_Ng - g - P_nP_Ng + P_n g\\
	&=P_Ng - g - P_{\min\{n,N\}} + P_n g =P_{\max\{N,n\}}g-g,
	\end{align*}
which yields	
	\begin{align*}
		\|P_Ng-g\|^2_{A^{\sigma d}(\Gamma)} &= \sum_{n=0}^{N} p^{2n\sigma } \|P_Ng-g\|^2 + \sum_{n=N+1}^\infty p^{2n\sigma } \|P_ng-g\|^2_{L^2(\Gamma)} \\
		&= \frac{p^{2\sigma (N+1)}-1}{p^{2\sigma}-1} \|P_Ng-g\|^2_{L^2(\Gamma)} + p^{2N\sigma}\sum_{n=1}^{\infty} p^{2n\sigma} \|P_{n+N}g-g\|^2_{L^2(\Gamma)}.
	\end{align*}
By estimating
\[
\dfrac{p^{2\sigma (N+1)}-1}{p^{2\sigma}-1}=
\dfrac{p^{2\sigma}-\dfrac{1}{p^{2\sigma N}}}{p^{2\sigma}-1} p^{2N \sigma }
\le \dfrac{p^{2\sigma}}{p^{2\sigma}-1}p^{2N \sigma },
\qquad
p^{2n\sigma}\le \dfrac{p^{2\sigma}}{p^{2\sigma}-1}p^{2n\sigma'}
\]
we arrive at
\begin{align*}
	\|P_Ng-g\|^2_{A^{\sigma d}(\Gamma)} &\le \dfrac{p^{2\sigma}}{p^{2\sigma}-1} p^{2N\sigma} \|P_Ng-g\|^2_{L^2(\Gamma)} + \dfrac{p^{2\sigma}}{p^{2\sigma}-1}p^{2N\sigma}\sum_{n=1}^{\infty} p^{2n\sigma'} \|P_{n+N}g-g\|^2_{L^2(\Gamma)}\\
	&\le \dfrac{p^{2\sigma}}{p^{2\sigma}-1}I\le \dfrac{p^{2\sigma}}{p^{2\sigma}-1}p^{-2N(\sigma'- \sigma )} \|g\|^2_{A^{\sigma'd}(\Gamma)}.\qedhere
\end{align*}
\end{proof}

As a corollary we obtain:
\begin{cor}\label{cor219}
Let $\sigma'$ be such that
\[
\sigma d <\sigma'd<\frac{1}{2},
\]
then there is a constant $c>0$ such that for any $N\in\N_0$ it holds
	\begin{equation*}
		\| \D\circ P_N  - \D  \|_{H^{\sigma' d}(\Gamma) \to H^{-\sigma d}(\Gamma)} \le c p^{-N(\sigma'-\sigma)}.
	\end{equation*}
\end{cor}
\begin{proof}
Let us use the norm $\|\cdot\|_{H^r}:=\|\cdot\|_{A^r}$, then
Lemma \ref{lem-pngg} yields for any $g\in H^{\sigma'd}(\Gamma)$:
	\begin{align*}
		\|\D\circ P_N g-\D g \|_{H^{-\sigma d}}&=\|\D (P_N g-g)\|_{H^{-\sigma d}}
		 \leq \|\D\|_{H^{\sigma d} \to H^{-\sigma d}} \|P_N g - g \|_{H^{\sigma d}}\\ &\leq \dfrac{p^{2\sigma}}{p^{2\sigma}-1}\|\D\|_{H^{\sigma d} \to H^{-\sigma d}} p^{-N(\sigma'-\sigma)}\|g\|_{H^{\sigma'd}}. \qedhere
	\end{align*}
\end{proof}

In order to work efficiently with the ``truncated map'' $\D\circ P_N$ we have to make an additional assumption on the structure of the tree $\cT$. Recall that the subtrees $\T^j_{N,k}$ and trees $\mathbb{T}^p$ were defined in Subsection \ref{sec21}.


\begin{defn} \label{regularity}
The metric tree $\T$ is called \emph{geometric from the generation $N_1$} (with some $N_1\in\N_0$) if for any
	$k\in\{0,\dots,p^{N_1}-1\}$ and any $j\in\{0,\dots,p-1\}$ it holds
	\[
	\T_{N_1,k}^j = \TT^p( \ell_{N_1+1,pk+j}, \ell,\omega_{N_1+1,pk+j}, \omega).  
	\]
In this case for any $N\ge N_1$ we denote by $\Tilde \cT_{N+1}$ the finite metric tree which is obtained from the truncated tree $\cT_{N+1}$ in the following way:
\begin{itemize}
	\item the combinatorial structure remains unchanged,
	\item the lengths of the pending (leaf) edges $e_{N+1,pk+j}$ becomes 
	\[
	{\Tilde \ell}_{N+1,pk+j}:=\dfrac{\ell_{N+1,pk+j}}{1-\dfrac{\ell}{\omega p}},
	\]
	and these new edges will be denoted by $\Tilde e_{N+1,pk+j}$,
	\item the lengths of all other edges and the weights of all edges remain unchanged.
\end{itemize}
The tree $\Tilde\cT_{N+1}$ will be called the $(N+1)$-condensation of $\cT$.	
\end{defn} 

Recall that Definition~\ref{defn2} contains a parameter $N_0\in \N_0$ related to the chosen decom\-position $(\Gamma_{n,k})$  of $\Gamma$, as well as associated local charts $\Phi_{N_0,K_0}$ covering $\overline{\Gamma_{N_0,K_0}}$ and the induced open sets $\Tilde \Gamma_{N_0,K_0}:=\Phi^{-1}_{N_0,K_0}(\Gamma_{N_0,K_0})\subset \R^d$ for $K_0\in\{0,\dots,p^{N_0}-1\}$.
We consider the respective Jacobians
\[
J_{N_0,K_0}:\ \Tilde\Gamma_{N_0,K_0}\to\R, \quad
J_{N_0,K_0}(y):=\sqrt{\det \big(\big(D\Phi_{N_0,K_0}(y)\big)^TD\Phi_{N_0,K_0}(y)\big)},
\]
which are smooth functions, bounded and separated from zero due to the above assumptions,
and their push-forwards
\[
H_{N_0,K_0}:=J_{N_0,K_0}\circ \Phi_{N_0,K_0}^{-1}:\  \Gamma_{N_0,K_0}\to\R.
\]
\begin{thm}\label{thm221}
Let the metric tree $\cT$ be geometric from some generation $N_1$, and for any $N\ge N_1$
let
\[
\Tilde \D_{N+1}:\ V_{N+1}(\Gamma)\to V_{N+1}(\Gamma)
\]
be the Dirichlet-to-Neumann map	for its $(N+1)$-condensation $\Tilde\cT_{N+1}$ constructed as in Definition~\ref{regularity}. Then
\begin{gather}
\D  P_{N+1}=H_{N_0}\Tilde \D_{N+1} P_{N+1} \text{ for any $N\ge\max\{N_0,N_1\}$}\nonumber\\
\text{with }H_{N_0}:=\dfrac{1}{p^{N_0-N-1}}\sum_{K_0=0}^{p^{N_0}-1} \dfrac{\one_{\Gamma_{N_0,K_0}}}{|\Tilde\Gamma_{N_0,K_0}|H_{N_0,K_0}}.\label{hn0}
\end{gather}
\end{thm}	

\begin{rmk}
Before delving into the proof of the above result, let us discuss why we work with condensed trees rather than truncated trees. This is particularly easy to understand for the case when $\T$ is a geometric tree for $p=1$, $\omega=1$, $L_0=\omega_0=1$. In that case the tree $\T$ can be seen as the interval $(0, L)$ with $L=(1-\ell)^{-1}$. The traces and normal derivatives reduce to scalars, and the Dirichlet-to-Neumann map is the simple multiplication operator: $\D=L^{-1}$. The truncated tree $\T_N$ is then identified with the interval $\big(0, (1-\ell^N)L\big)$, and the associated Dirichlet-to-Neumann map is then $\D_N=(1-\ell^N)^{-1}L^{-1}$. However, the condensed tree $\widetilde{\mathcal{T}}_{N+1}$ again becomes the interval $(0, L)$, and this ensures whose Dirichlet-to-Neumann map $\Tilde D_N$
coincides with $\D$. It is a generalization of this observation that allows to express $\D P_{N+1}$ via $\widetilde{\mathcal{D}}_{N+1}$ exactly as stated in the above result. 
\end{rmk}

\begin{proof}[\bf Proof of Theorem \ref{thm221}]
We first derive an explicit expression of $\Tilde{\mathcal{D}}_{N+1}$, and next compute explicitly $\mathcal{D}P_{N+1}$.  

Step 1: Computing $\Tilde{\mathcal{D}}_{N+1}$. 
Let $f\in V_{N+1}(\Gamma)$, then it is given by
\[
f=\sum_{K=0}^{p^{N+1}-1} f_{N+1,K} \one_{\Gamma_{N+1,K}},
\quad
f_{N+1,K}=\dfrac{1}{|\Gamma_{N+1,K}|}\int_{\Gamma_{N+1,K}}f_{N+1}\,\dd x.
\]	
Denote by $u\in \Tilde H^1(\Tilde \cT_{N+1})$ the uniquely defined solution of
\[
\Delta_{\Tilde \cT_{N+1}}u=0,\qquad 
\gamma^{\Tilde \cT_{N+1}}_0u=f.
\]
For $K\in\{0,\dots,p^N-1\}$ and $j\in\{0,\dots,p-1\}$ denote
\begin{align*}
b_{N,K}&:=u(X_{N,K}),&
c_{N+1,pK+j}&:=u'_{N+1,pK+j}(L_{N,K}^{+}).
\end{align*}
The harmonicity of $u$ on the modified edges $\Tilde e_{N+1,pK+j}$ implies its linearity,
\begin{align*}
u_{N+1,pK+j}(t)&=u_{N+1,pK+j}(L_{N,k})+c_{N+1,pK+j}(t-L_{N,K})\\
&\equiv b_{N,K}+c_{N+1,pK+j}(t-L_{N,K}) \text{ for all } t\in(L_{N,K},L_{N,K}+\Tilde \ell_{N+1,pK+j}),
\end{align*}
hence,
\begin{align}
	\nonumber
\gamma^{\Tilde\cT_{N+1}}_0u&=\sum_{K=0}^{p^N-1}\sum_{j=0}^{p-1} u_{N+1,pK+j}(L_{N,K}+\Tilde \ell_{N+1,pK+j})\one_{\Gamma_{N+1,pK+j}}\\
\label{eq:trace_u}
&=\sum_{K=0}^{p^N-1} \sum_{j=0}^{p-1} \Big( b_{N,K}+c_{N+1,pK+j} \Tilde \ell_{N+1,pK+j}\Big)\one_{\Gamma_{N+1,pK+j}}.
\end{align}
The boundary condition for $u$ shows that
\begin{equation}
	\label{bcf}
b_{N,K}+\sum_{j=0}^{p-1} c_{N+1,pK+j} \Tilde\ell_{N+1,pK+j}=f_{N+1,pK+j},\ K\in\{0,\dots,p^N-1\},\ j\in\{0,\dots,p-1\},
\end{equation}
and in addition we have, with the use of the explicit expression \eqref{fnderiv} for $\gamma_1^{\mathcal{T}_N}$,
\begin{equation}
	\label{tildedn}
\Tilde\D_{N+1}f\equiv
\gamma^{\Tilde \cT_{N+1}}_1 u=\sum_{K=0}^{p^N-1}\sum_{j=0}^{p-1} \dfrac{\omega_{N+1,pK+j} c_{N+1,pK+j}}{|\Gamma_{N+1,pK+j}|}\one_{\Gamma_{N+1,pK+j}}. 
\end{equation}





Step 2: Computing $\mathcal{D}P_{N+1}$. To compute the desired expression, we will construct an appropriate ansatz to the solution of the Dirichlet boundary problem on $\T$.

Step 2.1: Ansatz for the solution.
Let $v:\cT\to\C$ be defined as follows: we set $v:=u$ on $\cT_N$. Next, on $e_{N+1,pK+j}$, we define 
\[
v_{N+1,pK+j}(t):=b_{N,K}+c_{N+1,pK+j}(t-L_{N,K}) \text{ for all } j\in\{0,\dots,p-1\},
\]
which ensures that the transmission condition \eqref{kirchhoff} is fulfilled at each $X_{N,K}$,
and then extend it to a continuous function on the whole of $\cT$ such that $v$ is radial along each subtree $\cT^j_{N,K}$ (which means that for all $x\in\cT^j_{N,K}$ the value of $v(x)$ only depends on the distance between $X_{N,K}$ and $x$), linear on each edge $e_{n,k}\in \cT^j_{N,K}$ and the transmission conditions \eqref{kirchhoff} are satisfied at all nodes $X_{n,k}\in \cT^j_{N,K}$. Note that such an extension is unique and is given by the following expressions:
\begin{align*}
v=u^0+u^f,\quad \text{ where } u^0_{n,k}&=b_{N,K}r^{n-N-1}\Big(1+(r-1)\frac{t-L_{n,k}+\ell_{n,k}}{\ell_{n,k}}\Big), \\
\text{and }
u^f_{n,k}&=\alpha_{N,K,j}\left(\sum\limits_{s=0}^{n-N-2}r^s+r^{n-N-1}\frac{t-L_{n,k}+\ell_{n,k}}{\ell_{n,k}}\right), \\ \text{ with }\quad r&=\frac{\ell}{p\omega},\quad \alpha_{N,K,j}= c_{N+1,pK+j}\ell_{N+1,pK+j}-b_{N,K}(r-1).
\end{align*}
By \cite[Theorem 4.4]{jks}, it follows that $u^0$ is a harmonic function with $\gamma^{\T}_0u^0=0$ which equals to $b_{N,K}$ in $X_{N,K}$. At the same time, $u^f$ is a harmonic function with $\gamma^{\T}_0u^f=f$ that vanishes in $X_{N,K}$ (and hence the notation). Let us prove that indeed this decomposition defines a function in ${H}^1(\cT_{N,K}^j)$.  

Step 2.2: Let us show that $v\in \widetilde{H}^1(\cT)$.
As $r=\frac{\ell}{p\omega}<1$ by assumption \eqref{eq-lpa}, we conclude that 
\begin{align}
	\label{eq:boundedness}
	\begin{split}
	&\|u^0_{n,k}\|_{L^{\infty}(\mathcal{T}^j_{N,K})}\leq |b_{N,K}|(1+(r-1)), \\ 	&\|u^f_{n,k}\|_{L^{\infty}(\mathcal{T}^j_{N,K})}\leq |\alpha_{N,K,j}|\left((1-r)^{-1}+1\right).
	\end{split}
\end{align}
Using the assumptions \eqref{eq-lpa} and \eqref{eq-ccc} we see that constant functions are in $L^2(\mathcal{T})$: 
\begin{align*}
	\int_{\cT}\dd{\mu}=\sum\limits_{n=0}^{\infty}\sum\limits_{k=0}^{p^n-1}\ell_{n,k}\omega_{n,k}\leq C^2\sum\limits_{n=0}^{\infty}\sum\limits_{k=0}^{p^n-1}\ell^{n}\omega_{n}\leq  \sum\limits_{n=0}^{\infty}C^2(\ell\omega p)^n<\infty.
\end{align*}
Therefore, the above together with \eqref{eq:boundedness} yields that $v\in L^2(\cT)$. Next, let us remark that for $e_{n,k}\in \cT^{j}_{N,k}$,  
\begin{align}
	\nonumber
	v'_{n,k}&=(b_{N,K}(r-1)+\alpha_{N,K,j})r^{n-N-1}\ell_{n,k}^{-1}\\
	\nonumber
	&=(b_{N,K}(r-1)+\alpha_{N,K,j})\ell_{N+1,pK+j}^{-1}r^{n-N-1}\ell^{N-n+1}\\
	\label{eq:vprime_nk}
	&=c_{N+1,pk+j}r^{n-N-1}\ell^{N-n+1}=c_{N+1,pk+j}(p\omega)^{-n+N+1}.
\end{align} 
A direct computation yields
\begin{align*}
	\int_{\cT^j_{N,K}}|v'|^2\dd\mu&=|c_{N+1,pk+j}|^2\sum\limits_{n=N+1}^{\infty}\sum\limits_{k=0}^{p^n-1}\ell_{n,k}\omega_{n,k}(p\omega)^{2(N+1-n)}\\
	&=|c_{N+1,pk+j}|^2\ell_{N+1,pK+j}\omega_{N+1,pK+j}\sum\limits_{n=N+1}^{\infty}p^n\ell^{n-N-1}\omega^{n-N-1}(p\omega)^{2(N+1-n)}\\
	&\leq C_{N,K,j}\sum\limits_{n=N+1}^{\infty}\ell^n(p\omega)^{-n}=C_{N,K,j}\sum\limits_{n=N+1}^{\infty}r^n<\infty \text{ (due to $|r|<1$).} 
\end{align*}
Recall that $\Delta_{\mathcal{T}}v=0$ by construction, and it follows that $v\in \widetilde{H}^1_\Delta(\cT)$. 

Step 2.3: Let us show that $\gamma_0^{\T}v=f$. First of all, we remark that for all $n\geq N+1$
with $e_{n,k}\in \mathcal{T}_{N,K}^j$ we have
\begin{align}
	\label{eq:vval}
	\begin{split}
	v(X_{n,k})&=v_{n,k}(L_{n,k})=b_{N,K}r^{n-N-1}+\alpha_{N,K,j}\sum\limits_{s=0}^{n-N-2}r^s\\
	&=r^n\Big(b_{N,K}r^{-N-1}-r^{-N-1}(1-r)^{-1}\alpha_{N,K,j}\Big)+\alpha_{N,K,j}(1-r)^{-1},
	\end{split}
\end{align}
and the right-hand part does not depend on $k$ due to the radiality of $v$ on $\cT^j_{N,K}$.
Therefore, for $n\geq N+1$,
\begin{align*}
	\gamma_0^{\mathcal{T}_n}v&=\sum\limits_{k=0}^{p^n-1}v(X_{n,k}){\one}_{\Gamma_{n,k}}=\sum\limits_{k=0}^{p^n-1}\varphi_{n,N,K,j}{\one}_{\Gamma_{n,k}}
	=\sum\limits_{K=0}^{p^N-1}\sum\limits_{j=0}^{p-1}\varphi_{n,N,K,j}{\one}_{\Gamma_{N+1,pK+j}}.
\end{align*}
Next, we take $\lim\limits_{n\rightarrow +\infty}$ of the above; with \eqref{eq:vval} and $r<1$, as well as using the definition of $\alpha_{N,K,j}$ we conclude that 
\begin{align*}
	\gamma_0^{\mathcal{T}}v&=\sum\limits_{K=0}^{p^N-1}\sum\limits_{j=0}^{p-1}\left(b_{N,K}+c_{N+1,pK+j}\frac{\ell_{N+1,pK+j}}{1-r}\right){\one}_{\Gamma_{N+1,pK+j}}\\
	&=\sum\limits_{K=0}^{p^N-1}\sum\limits_{j=0}^{p-1}\left(b_{N,K}+c_{N+1,pK+j}\Tilde\ell_{N+1,pK+j}\right){\one}_{\Gamma_{N+1,pK+j}}=\gamma_0^{\Tilde{\cT}_{N+1}}u=f. 
\end{align*}
as per \eqref{eq:trace_u} and \eqref{bcf}.

Step 2.4: Relating $\gamma_1^{\T}v$ to $\gamma_1^{\widetilde{\T}_{N+1}}v$. 
We will compute $\gamma^\cT_1 v$ using Lemma \ref{lem-weak} and an explicit expression of the co-normal derivative \eqref{fnderiv}. Let $g\in H^{\sigma d}(\Gamma)$, then
\begin{align}
	(\gamma^{\cT}_1 v,g)_{H^{-\sigma d}(\Gamma),H^{\sigma d}(\Gamma)}&=\lim_{n\to\infty}
	\int_{\Gamma} \sum_{k=0}^{p^n-1} \dfrac{\omega_{n,k}}{|\Gamma_{n,k}|}v'_{n,k}(L_{n,k}^-)\one_{\Gamma_{n,k}} g\,\dd s\nonumber\\
	&=\lim_{n\to\infty}\sum_{K=0}^{p^N-1}\sum_{j=0}^{p-1} \int_\Gamma F_n(N,K,j) g\,\dd s,\label{sumfn}\\
	F_n(K,j)&:=\sum_{k:\, \cT_{n,k}\subset\cT^j_{N,K}} \dfrac{\omega_{n,k}}{|\Gamma_{n,k}|}v'_{n,k}(L_{n,k}^-)\one_{\Gamma_{n,k}} \text{ for }n\ge N+1.\nonumber
\end{align}
By \eqref{eq:vprime_nk} and the assumption on $\cT^j_{N,K}$ we have
\begin{align*}
	F_n(K,j)&=\sum_{k:\, \cT_{n,k}\subset\cT^j_{N,K}} \dfrac{\omega_{N+1,pK+j}\omega^{n-N-1}}{|\Gamma_{n,k}|}\dfrac{c_{N+1,pK+j}}{(p\omega)^{n-N-1}}\one_{\Gamma_{n,k}}\\
	&=\omega_{N+1,pK+j}c_{N+1,pK+j}\sum_{k:\, \cT_{n,k}\subset\cT^j_{N,K}} \dfrac{1}{p^{n-N-1}|\Gamma_{n,k}|}\one_{\Gamma_{n,k}},
\end{align*}
and the substitution into \eqref{sumfn} gives
\begin{equation}
	\label{ggtt11}
	\begin{aligned}
		(\gamma^{\cT}_1 v,g)_{H^{-\sigma d}(\Gamma),H^{\sigma d}(\Gamma)}&=
		\sum_{K=0}^{p^N-1}\sum_{j=0}^{p-1} \omega_{N+1,pK+j}c_{N+1,pK+j}\lim_{n\to\infty}G_n(K,j),\\
		G_n(K,j):&=\sum_{k:\, \cT_{n,k}\subset\cT^j_{N,K}} \int_\Gamma\dfrac{1}{p^{n-N-1}|\Gamma_{n,k}|}\one_{\Gamma_{n,k}} g\,\dd s.
	\end{aligned}
\end{equation}

For the computation of the limits we are going to use the local charts $\Phi_{N_0,K_0}$.
Let $K_0\in\{0,\dots,p^{N_0}-1\}$ be such that $\cT^j_{N,K}\subset \cT_{N_0,K_0}$, then for 
$\cT_{n,k}\subset\cT^j_{N,K}$ one has
\begin{equation}
	\begin{aligned}
		\int_\Gamma\dfrac{1}{p^{n-N-1}|\Gamma_{n,k}|}\one_{\Gamma_{n,k}} g\,\dd s&=\int_{\Gamma_{n,k}} \dfrac{1}{p^{n-N-1}|\Gamma_{n,k}|} g\,\dd s\\
		&=\int_{\Tilde\Gamma_{n,k}}\dfrac{1}{p^{n-N-1}|\Gamma_{n,k}|}g\big(\Phi_{N_0,K_0}(y)\big) J_{N_0,K_0}(y)\,\dd y.
	\end{aligned}
	\label{jnk1}
\end{equation}
Choose arbitrary points $a_{n,k}\in \Tilde \Gamma_{n,k}$ and denote $j_{n,k}:=J_{N_0,K_0}(a_{n,k})$. As $J_{N_0,K_0}$ is smooth, one has $|J_{N_0,K_0}(y)-j_{n,k}|\le b|y-a_{n,k}|$ with some fixed $b>0$ uniformly in $(y,n,k)$. Remark that by assumption the diameter of $\Tilde \Gamma_{n,k}$ is $O(p^{-\frac{n}{d}})$ for large $n$, which shows that $J_{N_0,K_0}(y)=j_{n,k}+O(p^{-\frac{n}{d}})$ uniformly for $y\in \Tilde \Gamma_{n,k}$ as $n$ becomes large. Similarly, 
\begin{align*}
	|\Gamma_{n,k}|&=\int_{\Tilde \Gamma_{n,k}} J_{N_0,K_0}(y)\,\dd y
	=\int_{\Tilde \Gamma_{n,k}} j_{n,k}\,\dd y+\int_{\Tilde \Gamma_{n,k}} \big(J_{N_0,K_0}(y)-j_{n,k}\big)\,\dd y\\
	&=\Big(j_{n,k}+O(p^{-\frac{n}{d}})\Big)|\Tilde \Gamma_{n,k}|
	=\dfrac{j_{n,k}|\Tilde \Gamma_{n,k}|}{1+O(p^{-\frac{n}{d}})}.
\end{align*}
The substitution of these asymptotic estimates into \eqref{jnk1} yields
\begin{align*}
	\int_\Gamma\dfrac{1}{p^{n-N-1}|\Gamma_{n,k}|}\one_{\Gamma_{n,k}} g\,\dd s&=
	\int_{\Tilde\Gamma_{n,k}}\dfrac{1}{p^{n-N-1}|\Tilde\Gamma_{n,k}|}g\big(\Phi_{N_0,K_0}(y)\big) \,
	\big(1+O(p^{-\frac{n}{d}}\big)\big)
	\dd y\\
	&=\dfrac{1}{p^{N_0-N-1}|\Tilde \Gamma_{N_0,K_0}|}\int_{\Tilde\Gamma_{n,k}}g\big(\Phi_{N_0,K_0}(y)\big) \,
	\big(1+O(p^{-\frac{n}{d}}\big)\big)
	\dd y
\end{align*}
where the $O$-term is uniform in $y\in \Gamma_{N_0,K_0}$ and we have used  $|\Tilde\Gamma_{n,k}|=p^{N_0-n}|\Tilde \Gamma_{N_0,K_0}|$. One has then
\begin{align*}
	\lim_{n\to\infty} G_n(K,j)&=\lim_{n\to\infty}\sum_{k:\, \cT_{n,k}\subset\cT^j_{N,K}}
	\dfrac{1}{p^{N_0-N-1}|\Tilde \Gamma_{N_0,K_0}|}\int_{\Tilde\Gamma_{n,k}}g\big(\Phi_{N_0,K_0}(y)\big) \,
	\big(1+O(p^{-\frac{n}{d}}\big)\big)
	\dd y\\
	&=\lim_{n\to\infty}\dfrac{1}{p^{N_0-N-1}|\Tilde \Gamma_{N_0,K_0}|}\int_{\Tilde \Gamma_{N+1,pK+j}}g\big(\Phi_{N_0,K_0}(y)\big) \,
	\big(1+O(p^{-\frac{n}{d}}\big)\big)
	\dd y\\
	&=\dfrac{1}{p^{N_0-N-1}|\Tilde \Gamma_{N_0,K_0}|}\int_{\Tilde \Gamma_{N+1,pK+j}}g\big(\Phi_{N_0,K_0}(y)\big) \, \dd y\\
	&=\dfrac{1}{p^{N_0-N-1}|\Tilde \Gamma_{N_0,K_0}|} \int_{\Gamma_{N+1,pK+j}} \dfrac{g}{H_{N_0,K_0}}\,\dd s.
\end{align*}
Recall that this result was obtained under the assumption $\cT_{N,K}\subset\cT_{N_0,K_0}$.

We now regroup the summands in \eqref{ggtt11}:
\begin{align*}
	(\gamma^{\cT}_1 v,&g)_{H^{-\sigma d}(\Gamma),H^{\sigma d}(\Gamma)}=
	\sum_{K_0=0}^{p^{N_0}-1} \sum_{(K,j):\,\cT^j_{N,K}\subset\cT_{N_0,K_0}}
	\omega_{N+1,pk+j}c_{N+1,pK+j}\lim_{n\to\infty}G_n(K,j)\\
	&=\sum_{K_0=0}^{p^{N_0}-1} \sum_{(K,j):\,\cT^j_{N,K}\subset\cT_{N_0,K_0}}
	\dfrac{\omega_{N+1,pk+j}c_{N+1,pK+j}}{p^{N_0-N-1}|\Tilde \Gamma_{N_0,K_0}|} \int_{\Gamma_{N+1,pK+j}} \dfrac{g}{H_{N_0,K_0}}\,\dd s\\
	&=\int_\Gamma \bigg(\dfrac{1}{p^{N_0-N-1}}\sum_{K_0=0}^{p^{N_0}-1} \dfrac{\one_{\Gamma_{N_0,K_0}}}{|\Tilde\Gamma_{N_0,K_0}|H_{N_0,K_0}}\bigg)	\\
	&\qquad\times
	\bigg(\sum_{K=0}^{p^N-1}\sum_{j=0}^{p-1} \dfrac{\omega_{N+1,pK+j} c_{N+1,pK+j}}{|\Gamma_{N+1,pK+j}|}\one_{\Gamma_{N+1,pK+j}}\bigg)\, g\,\dd s\\
	&=\int_{\Gamma} H_{N_0} \gamma^{\Tilde \cT_{N+1}}_1 u\, g\,\dd s,
\end{align*}
where \eqref{hn0} and \eqref{tildedn} were used in the last step,
and we arrive at
\[
\D f=\gamma^\cT_1 v=H_{N_0} \gamma^{\Tilde \cT_{N+1}}_1 u=H_{N_0}\Tilde \D_{N+1} f. \qedhere
\]
\end{proof}


\section{Boundary value problems on the exterior domain}\label{sec3-bvp}
Recall that in the context of boundary value problems for an open set $U\subset\R^m$ one usually denotes by $H^1_\loc(U)$ the set of the functions $f$ on $U$ such that $\varphi f\in H^1(\Omega)$ for any cut-off function $\varphi\in C^\infty_c(\R^m)$. In particular, $H^1_\loc(U)=H^1(U)$ for all bounded $U$.



For the rest of the section it will be convenient to denote
\[
\Omega_+:=\Omega,\qquad \Omega_-:=\R^m\setminus\overline{\Omega},
\]
and let $\nu$ be the unit normal on $\Gamma$ pointing to $\Omega_+$.
We then have the respective Dirichlet trace maps
\[
\gamma^+_0\equiv \gamma^\Omega_0: \ H^1_\loc(\Omega_+)\to H^\half(\Gamma),
\qquad
\gamma^-_0: \ H^1(\Omega_-)\to H^\half(\Gamma),
\]
so that for the functions $u$ smooth up to a boundary one has $\gamma^\pm_0 u:=u|_{\Gamma}$,
and the Neumann trace maps
\begin{align*}
	\gamma^+_1\equiv\gamma^\Omega_1:& \ \big\{u\in H^1_{\loc}(\Omega_+):\ \Delta u \in L^2_\loc(\Omega_+)\big\}\to H^{-\half}(\Gamma),\\
	\qquad
	\gamma^-_1:& \ \big\{u\in H^1(\Omega_-):\ \Delta u\in L^2(\Omega_-)\big\} \to H^{-\half}(\Gamma),
\end{align*}
such that for the functions $u$ smooth up to the boundary one has
\[
\gamma^\pm_1 u:=\partial_\nu u|_\Gamma,
\]
where $\nu$ is the unit normal on $\Gamma$ pointing to $\Omega\equiv \Omega_+$. Remark that with this sign convention, one has $u\in H^1(\R^m)$ if and only if $u\in H^1(\R^m\setminus\Gamma)$ with $(\gamma_0^+-\gamma_0^-)u=0$. In addition, $u\in H^1(\R^m)$ with $\Delta u\in L^2(\R^m)$
if and only if $u\in H^1(\R^m\setminus\Gamma)$ with $\Delta u\in L^2(\R^m\setminus\Gamma)$ (in the sense of distributions on $\R^m\setminus\Gamma$) with $(\gamma_0^+-\gamma_0^-)u=0$ and $(\gamma_1^+ -\gamma_1^-)u=0$.

The aim of the present section is to give detailed proofs of the following results:
\begin{thm}[Exterior Dirichlet problem]\label{thm21}
	For any $f\in L^2_\comp(\Omega)$ and $g\in H^\half(\Gamma)$ there is a unique solution $u\in H^1_\loc(\Omega)$
	of
	\begin{equation}
		\label{dir-ext}
		\left\{\begin{aligned}
			- \Delta u &=f  \text{ in }\Omega,\\
			\gamma^\Omega_0 u &=g  \text{ on }\Gamma,\\
			u(x)&= 	O(|x|^{2-m}) \text{ for } |x|\to \infty,
		\end{aligned}\right.
	\end{equation}
and the solution $u$ depends continuously on the right-hand sides $f$ and $g$ in the following sense: for any $\varphi\in C^\infty_c(\R^m)$ there is a constant $c>0$ such that for any $(f,g)$ one has
\[
\|\varphi u\|_{H^1(\Omega)}\le c\big(\|f\|_{L^2(\Omega)}+\|g\|_{H^\half(\Gamma)}\big).
\]


\end{thm}

\begin{thm}[Dirichlet-to-Neumann map for the exterior domain]\label{thm22}
	For $g\in H^\half(\Gamma)$ let $u_g$ denote the solution of \eqref{dir-ext} with $f=0$.	 Define the Dirichlet-to-Neumann operator 
	\[
	\dtn: \ H^{\half}(\Gamma)\ni g\mapsto \gamma^\Omega_1 u_g\in H^{-\half}(\Gamma),
	\]
	then $\dtn$ is bounded, Fredholm of index zero, and non-positive, i.e. 
	\[
	-\big(\dtn g, \overline{g}\big)_{H^{-\half}(\Gamma), H^\half(\Gamma)} \ge 0 \text{ for any } g\in H^{\half}(\Gamma).
	\]  	
	Moreover,	
	\begin{itemize}
		\item[(i)] if $m\ge 3$, then $\dtn$ is coercive, i.e. one can find a constant $c>0$ such that
		\begin{equation}
			\label{dtngg}
			-\big(\dtn g, \overline{g}\big)_{H^{-\half}(\Gamma), H^\half(\Gamma)} \ge c\|g\|_{H^\half(\Gamma)}^2
		\end{equation}
		holds for all $g\in H^\half(\Gamma)$, in particular, $\dtn$ is bijective,
		\item[(iii)] if $m=2$, then $\ker \dtn=\C \one_\Gamma$, and $\dtn$ is coercive on
		\[
		H^\half_0(\Gamma):=\big\{ g\in H^\half(\Gamma):\, (\one_\Gamma,g)_{H^{-\half}(\Gamma),H^\half(\Gamma)}=0\big\},
		\]
		i.e. there is a constant $c>0$ such that \eqref{dtngg} is fulfilled for all $ g\in H^{\half}_0(\Gamma)$.
	\end{itemize}
\end{thm}	

While both results are indeed folkloric, we did not manage to find a suitable reference containing all necessary details for the required $H^1$-setting. McLean's book \cite{McLean} provides all important tools but lacks a precise formulation of final results for the problems in exterior domains, so we decided to complete the respective part of the argument.


In the next subsection we recall some constructions related to boundary integral operators.
These machineries are then used to prove Theorems \ref{thm21} and \ref{thm22}, first for $m\ge 3$ in Subsection \ref{sec-m3} and then for $m=2$ in Subsection~\ref{sec-m2}.


\subsection{Surface potentials}

We begin by citing some of the important statements from~\cite{McLean}. Let $G$ be the standard fundamental solution for the Laplace equation in $\R^m$,

\begin{equation}\label{fundameltalsolution}
	G(x) =\begin{cases} \dfrac{1}{2 \pi} \log \dfrac{r}{|x|},& m=2,\\[\bigskipamount]
		\dfrac{1}{(m-2)\Upsilon_m} \dfrac{1}{|x|^{m-2}}, & m\ge 3,
		\end{cases}
\end{equation}
where $\Upsilon_m$ is the hypersurface area of the unit sphere in $\R^m$ and $r>0$ is arbitrary (to be chosen later), and consider the convolution operator
\[
\cG: \ \cE'(\R^m)\ni f\mapsto G\star f \in \cS'(\R^m),
\]
which satisfies $-\Delta \circ \cG = -\cG \circ \Delta=\Id$. For $g\in H^{-\half}(\Gamma)$ define  $\gamma^*_0 g\in \cS'(\R^m)$ by
\[
(\gamma^*_0 g, \phi) = (g, \gamma^+_0 \phi)_{H^{-\half}(\Gamma), H^{\half}(\Gamma)}  \text{ for all } \phi\in\cS(\R^m).
\]
Analogously, for $g\in H^\half(\Gamma)$ we define the distribution $\gamma^*_1 g\in \cS'(\R^m)$ by
\[
(\gamma^*_1 g, \phi) = (g, \gamma^+_1 \phi)_{H^{\half}(\Gamma), H^{-\half}(\Gamma)} \text{ for all } \phi\in\cS(\R^m).
\]
By construction both $\gamma^*_0 g$ and $\gamma^*_1 g$ are supported by $\Gamma$ for all admissible $g$, and in fact,
\[
\gamma_0^*:\ H^{-\half}(\Gamma)\to H^{-1}_\comp(\R^m),
\qquad
\gamma_1^*:\ H^{\half}(\Gamma)\to H^{-2}_\comp(\R^m).
\]
%where $H^{-1}_\comp( \R^m)$ is a subspace of compactly supported distributions of $\big(H^1(\Delta;\R^m)\big)'$.}
The single-layer potential $\SL$ and the double-layer potential $\DL$ associated with $\Gamma$ are defined by
\begin{align*}
\SL:= \cG\circ \gamma^*_0,
\qquad
\DL:= \cG \circ \gamma^*_1.
\end{align*} 
By construction, the functions $\SL g$ and $\DL g$ are harmonic in $\Omega_\pm$ for all admissible $g$.
For every cutoff function $\chi \in C^\infty_c(\R^m)$, the operators
\[
H^{-\half}(\Gamma)\ni g\mapsto \chi \SL g\in H^1(\Omega_\pm),
\qquad
H^{\half}(\Gamma)\ni g\mapsto \chi \DL g\in H^1(\Omega_\pm)
\]
are bounded, and the jump relations
\begin{equation}
	\label{jump}
\begin{aligned}
	(\gamma^+_0-\gamma^-_0) \SL g&=0,& (\gamma^+_1-\gamma^-_1)\SL g &= -g & \text{for all }& g\in H^{-\half}(\Gamma), \\
	(\gamma^+_0-\gamma^-_0)\DL g&=g,& (\gamma^+_1-\gamma^-_1) \DL g &= 0 &\text{ for all } &g\in H^{\half}(\Gamma),
\end{aligned}
\end{equation}
are fulfilled. We will frequently use the identity 
\begin{equation}
	 \label{sl-dl}
\begin{aligned}(\gamma^\pm_1\SL \phi,\psi)_{H^{-\half}(\Gamma),H^\half(\Gamma)}&=(\phi,\gamma^\mp_0\DL\psi)_{H^{-\half}(\Gamma),H^\half(\Gamma)}\\
\text{ for any }& \phi\in H^{-\half}(\Gamma),\ \psi \in H^\half(\Gamma),
\end{aligned}
\end{equation}
see \cite[Thm. 6.17 and Sec.~7]{McLean}.

The above considerations give rise to four important boundary operators:
\begin{align*}
	S:=&&\gamma^+_0\SL: \ & H^{-\half}(\Gamma) \to H^{\half}(\Gamma),\\
	R:=&&-\gamma^+_1 \DL:\  &H^{\half}(\Gamma) \to H^{-\half}(\Gamma),\\
	T:=&&(\gamma^+_0 + \gamma^-_0)\DL:\ & H^{\half}(\Gamma) \to H^{\half}(\Gamma),
\intertext{and remark that the adjoint of $T$ is given by}	
	T^*:=&&(\gamma^+_1+\gamma^-_1)\SL:\ &  H^{-\half}(\Gamma) \to H^{-\half}(\Gamma).
\end{align*}
By \cite[Theorem 6.11]{McLean} these operators are bounded in respective spaces, and the jump relation \eqref{jump} yield the identities
\begin{equation}
	\label{tracesl}
\gamma^\pm_1 \SL g = \frac{1}{2} (\mp g + T^* g),
\qquad
\gamma^{\pm}_0 \DL g = \frac{1}{2}(\pm g + Tg)
\end{equation}
valid for all $g$ in respective domains.  By general results for elliptic problems of \cite[Thm. 7.6, 7.8]{McLean} and their refinement for the Laplacian (namely, \cite[Theorem 8.16]{McLean} for the single-layer boundary integral operator in $m=2$, \cite[Corollary 8.13]{McLean} for the single-layer boundary integral operator in $m=3$ and \cite[Theorem 8.21]{McLean} for the hypersingular integral operator), we have: 
\begin{lem}\label{lemma-RS}
The operator $S$ is a self-adjoint Fredholm operator of index $0$, and for a suitable choice of $r>0$ in \eqref{fundameltalsolution} one has
 $\ker S = \{0\}$, in particular, $S$ has a bounded inverse.
Furthermore, the operator $R$ is self-adjoint Fredholm of index $0$ with
$\ker R = \C \one_\Gamma$.
\end{lem}
From now we assume that $r$ in \eqref{fundameltalsolution} is chosen in such a way that the assertions of Lemma~\ref{lemma-RS} hold.

Remark that for any $g\in H^\half(\Gamma)$ and $x\in\R^m\setminus\Gamma$ one has
	\begin{align*}
	\DL g(x)&=\int_{\Gamma} \partial_{\nu_y} G(x-y) g(y)\,\dd s(y)=\dfrac{1}{\Upsilon_m}\int_\Gamma \dfrac{\langle \nu_y,x-y\rangle_{\R^{m}}}{|x-y|^m}g(y)\dd s(y).
\end{align*}		
Using a standard computation with an integration by parts 
we arrive at the following identities:
\begin{equation}
	\DL \one_\Gamma=0 \text{ in } \Omega_+, \quad
	\DL \one_\Gamma=-1 \text{ in } \Omega_-,
	\quad
	\gamma^+_0 \DL \one_\Gamma=0,
	\quad
	\gamma^-_0 \DL \one_\Gamma= -\one_\Gamma.
	\label{DLone}
\end{equation}


