 The following two theorems are crucial for the subsequent considerations. First, \cite[Thm 7.15 + 8.9]{McLean} yield:
\begin{thm} \label{boundequ}
Let $f\in L^2_\comp(\Omega_+)$. 

(A) Let $g\in H^\half(\Gamma)$. If $u \in H^1_\loc(\Omega_+)$ solves the exterior Dirichlet problem
		\begin{equation}\label{dirpro}
			\left\{\begin{aligned}
				- \Delta u &= f  \text{ in }\Omega_+,\\
				\gamma^+_0 u &= g  \text{ on }\Gamma,\\
				u(x)&= \begin{cases}
					O(|x|^{2-m})  \text{ for } m\ge 3,\\
					b \log |x| + O(|x|^{-1}) \text{ with some $b\in\C$ for  } m=2,
				\end{cases} \text{ as } |x|\to \infty,
			\end{aligned}\right.
		\end{equation}
		then the function
		\[
		h:=\gamma^+_1 u \in H^{-\half}(\Gamma)
		\]
		satisfies the equation
		\begin{align}\label{shboundaryequ}
			Sh = \gamma^+_0 \cG f - \frac{1}{2}(g-Tg),
		\end{align}
		and $u$ can be represented as
		\begin{align}\label{solutionrepr}
			u= \cG f + \DL g - \SL h.
		\end{align}
		Conversely, if $h\in H^{-\frac{1}{2}}(\Gamma)$ is a solution of \eqref{shboundaryequ}, then the equation \eqref{solutionrepr} defines a solution of \eqref{dirpro}. 

(B) Let $h\in H^{-\frac{1}{2}}(\Gamma)$. If $u \in H^1_\loc(\Omega_+)$ is a solution of the exterior Neumann problem
	\begin{equation}\label{neupro}
	\left\{\begin{aligned}
		- \Delta u &= f  \text{ in }\Omega_+,\\
		\gamma^+_1 u &= h  \text{ on }\Gamma,\\
		u(x)&= \begin{cases}
			O(|x|^{2-m})  \text{ for } m\ge 3,\\
			b \log |x| + O(|x|^{-1}) \text{ with some $b\in\C$ for  } m=2,
		\end{cases} \text{ as } |x|\to \infty,
	\end{aligned}\right.
\end{equation}
then the function $g:= \gamma^+_0 u \in H^{\half}(\Gamma)$ is a solution of the equation 
		\begin{align}\label{rgboundaryequ}
			Rg = \gamma^+_1\cG f - \frac{1}{2}(h+T^*h)
		\end{align}
		and $u$ is of the form \eqref{solutionrepr}. 		Conversely, if $g\in H^{\half}(\Gamma)$ is a solution of \eqref{rgboundaryequ}, then the function $u$ defined by~\eqref{solutionrepr} defines a solution of \eqref{neupro}. 
\end{thm}

\begin{rmk}
	The required behavior of $u$ at infinity in Theorem \ref{boundequ} is termed as $\mathcal{M}u=0$
	in most assertions in the book \cite{McLean}, see \cite[Thm. 8.9]{McLean} for more detail.
\end{rmk}

	The above result states an equivalence between the solutions to the exterior boundary-value problems and the representation (Kirchhoff) formula \eqref{solutionrepr}, coupled with associated boundary integral equations for unknown traces. However, at this point it is unclear whether the exterior boundary-value problems are well-posed. This will be clarified in Theorem \ref{DTNdge2}.


The following theorem combines the claims of \cite[Thm. 8.10 and 8.18]{McLean}:
\begin{lem} \label{uniq} 
	Let $u\in H^1_\loc(\Omega_+)$ with $\Delta u = 0$ on $\Omega_+$ satisfy the radiation condition
	\[
	u(x)=O\big(|x|^{2-m}\big)  \text{ for }|x| \to \infty,
	\]
	then:
	\begin{enumerate}

		\item[(a)] $\gamma^+_0u = 0$ if and only if $u=0$ on $\Omega_+$,

		\item[(b)] $\gamma^+_1 u = 0$ if and only if
		\begin{itemize}
			\item[(i)] $u=0$ in $\Omega_+$ for $m\ge 3$,
			\item[(ii)]  $u$ is constant on $\Omega_+$ for $m=2$.
		\end{itemize}

	\end{enumerate}
\end{lem}

The following computation will also be used at several places:

\begin{lem} \label{uvskal} 
	Let $u,v\in H^1_\loc(\Omega_+)$ with $\Delta u = \Delta v=0$ on $\Omega_+$ satisfy the radiation condition
\[
u(x)=O\big(|x|^{2-m}\big), \quad v(x)=O\big(|x|^{2-m}\big)\quad \text{for }|x| \to \infty,
\]
then
\[
\big(\gamma^+_1 u,\overline{\gamma^+_0v}\,\big)_{H^{-\half}(\Gamma),H^\half(\Gamma)}=-\int_{\Omega_+} \langle \nabla u,\nabla v\rangle_{\C^m}\dd x.
\]
\end{lem}

\begin{proof}
Remark first that by \cite[Prop.~2.75]{Folland} the radial derivative $\partial_ r u$ of $u$ satisfies
	\[
	\partial_r u(x)=\begin{cases} O\big(|x|^{1-m}\big), & m\ge 3,\\
		O\big(|x|^{-2}\big), & m=2,
		\end{cases} \text{ for } |x|\to\infty
	\]
Let $R>0$ such that $\overline{\Omega_-}\subset B_R(0)$ and denote $\Omega^+_R = B_R(0) \cap \Omega_+$.
We have then
\begin{align*}	0&= \int_{\Omega^+_R} (\Delta u) \overline{v} \,\dd x=(\Delta u,v)_{H^{-1}_\comp(\Omega_+),H^1_\loc(\Omega_+)}\\
&= -\big(\gamma^+_1  u, \overline{\gamma^+_0 v} \big)_{H^{-\half}(\Gamma), H^{\half}(\Gamma)} +  \int_{|x|=R} (\partial_r u) \overline{v}\,\dd s-\int_{\Omega^+_R}\langle \nabla u,\nabla v\rangle_{\C^m}\dd x,
\end{align*}
with $\dd s$ being the hypersurface measure, which yields
\begin{equation}
	\label{lok22}
	\big(\gamma^+_1  u, \overline{\gamma^+_0 v} \big)_{H^{-\half}(\Gamma), H^{\half}(\Gamma)}=-\int_{\Omega^+_R}\langle \nabla u,\nabla v\rangle_{\C^m}\dd x+\int_{|x|=R} (\partial_r u) \overline{v}\,\dd s.	
\end{equation}
Using the above bounds for $\partial_r u$ and $v$, for large $R$ we have (with some fixed $C>0$)
\[
\Big|
\int_{|x|=R} (\partial_r u) \overline{v}\,\dd s\Big|
\le
\begin{cases}
 C \cdot R^{m-1} \cdot R^{1-m}\cdot R^{2-m}=O(R^{2-m})=o(1), & m\ge 3,\\
 C \cdot R \cdot R^{-2}\cdot  1=O(R^{-1})=o(1), & m=2,
\end{cases} 
\]
and sending $R$ to $\infty$ in \eqref{lok22} gives
\begin{equation}
	\label{lok23}
	\big(\gamma^+_1  u, \overline{\gamma^+_0 v} \big)_{H^{-\half}(\Gamma), H^{\half}(\Gamma)}=-\lim_{R\to\infty}\int_{\Omega^+_R}\langle \nabla u,\nabla v\rangle_{\C^m}\dd x.	
\end{equation}
Using the last identity for $u=v$ we conclude that $|\nabla u|^2$ and $|\nabla v|^2$ are integrable on $\Omega_+$,
so the limit on the right-hand side of \eqref{lok23} is exactly the Lebesgue integral over $\Omega_+$.
\end{proof}



\subsection{Dirichlet-to-Neumann map for $m\ge 3$}\label{sec-m3}


\begin{thm} \label{DTNdge2}
	Let $m\geq 3$ and $f\in L^2_\comp(\Omega_+)$. Then 
	\begin{enumerate}
		\item[(a)] For every $g\in H^\half (\Gamma)$ there is a unique solution $u\in H^1_\loc(\Omega_+)$
		to the Dirichlet problem with radiation condition
		\[
			\left\{\begin{aligned}
			- \Delta u &= f  \text{ in }\Omega_+,\\
			\gamma^+_0 u &= g  \text{ on }\Gamma,\\
			u(x)&= 	O(|x|^{2-m}) \text{ for } |x|\to \infty,
		\end{aligned}\right.
		\]
	and for any cut-off function $\varphi\in C^\infty_c(\R^m)$ one can find a constant $c>0$ such that for any $(f,g)$ as above and the respective solution $u$ one has
	\begin{equation}
		 \label{uc1}
	\|\varphi u\|_{H^1(\Omega_+)}\le c\big( \|f\|_{L^2(\Omega)}+\|g\|_{H^\half(\Gamma)}\big).
	\end{equation}
	\item[(b)] For every $h\in H^{-\half}(\Gamma)$ there is a unique $u\in H^1_\loc(\Omega_+)$ fulfilling the Neumann problem with radiation condition
	\[
				\left\{\begin{aligned}
		- \Delta u &= f  \text{ in }\Omega_+,\\
		\gamma^+_1 u &= h  \text{ on }\Gamma,\\
		u(x)&= 	O(|x|^{2-m}) \text{ for } |x|\to \infty.
	\end{aligned}\right.
	\]
	\item[(c)]
	For $g\in H^\half(\Gamma)$ let $u_g$ be the solution of (a) for $f=0$.	 Define the Dirichlet-to-Neumann operator 
	\[
		\dtn: \ H^{\half}(\Gamma)\ni g\mapsto \gamma^+_1 u_g\in H^{-\half}(\Gamma),
	\]
	then $\dtn$ is bounded, invertible and coercive, i.e. there is a constant $c>0$ such that for every $g\in H^{\half}(\Gamma)$ one has
	\[
	-\big(\dtn g, \overline{g}\big)_{H^{-\half}(\Gamma), H^\half(\Gamma)} \geq c \|g\|^2_{H^\half(\Gamma)}.
	\]  
	\end{enumerate}
\end{thm}
\begin{proof}
The uniqueness in (a) and (b) follows directly by Lemma~\eqref{uniq}(a,b-i). For the existence
	we note first that by Theorem \ref{boundequ} the solvability in (a) resp. (b)  is equivalent to the  solvability of the boundary equations \eqref{shboundaryequ} resp. \eqref{rgboundaryequ}. Since $S$ is a bijective isomorphism, the problem \ref{shboundaryequ} has a unique solution $h\in H^{-\half}(\Gamma)$ for any choice of $g$, and this solution continuously depends on $g$, which proves the existence in (a). The stability estimate \eqref{uc1} follows from the representation \eqref{solutionrepr} and the continuity properties of $\cG$, $\SL$ and $\DL$.

To complete the argument for (b) slightly more work is needed. 
First, by using \eqref{tracesl} we rewrite the condition \eqref{rgboundaryequ} as $Rg=\gamma_1^+\cG f - \gamma^-_1 \SL h$.
As $R$ is Fredholm and self-adjoint with $\ker R=\C \one_\Gamma$, this last equation is solvable with respect to $g$
if and only if the right-hand side satisfies
\begin{align} \label{solutioncondition}
	I:=( \one_{\Gamma}, \gamma^+_1 \cG f - \gamma^-_1 \SL h )_{H^\half (\Gamma), H^{-\half}(\Gamma)} = 0.
\end{align}
Using the definition of $\DL$ we obtain
\begin{align*}
( \one_{\Gamma}, \gamma^+_1 \cG f)_{H^\half (\Gamma), H^{-\half}(\Gamma)}&=\big(\DL \one_\Gamma, f\big)_{H^1_{\loc}(\Omega_+),H^{-1}_{\comp}(\Omega_+)}\stackrel{\eqref{DLone}}{=}
\big(0, f\big)_{H^1_{\loc}(\Omega_+),H^{-1}_{\comp}(\Omega_+)}=0,\\
( \one_{\Gamma}, \gamma^-_1 \SL h )_{H^\half (\Gamma), H^{-\half}(\Gamma)}&=
( \gamma^+_0 \DL \one_{\Gamma}, h )_{H^\half (\Gamma), H^{-\half}(\Gamma)}
\stackrel{\eqref{sl-dl}}{=}( 0, h )_{H^\half (\Gamma), H^{-\half}(\Gamma)}=0,
\end{align*}
therefore, $I=0$ and the solvability condition \eqref{solutioncondition} is fulfilled, which proves (b).


It remains to prove (c). Let $g\in H^\half(\Gamma)$ with  $\dtn g=0$, then $u_g$ is a solution of (b) for $f=0$ and $h=0$, i.e. $u_g=0$ in $\Omega_+$, and $g=\gamma^+_0 u_g=0$. This proves the injectivity of $\dtn$. Let $h\in H^{\half}(\Gamma)$ and let $u$ be a solution of (b) for $f=0$ and the chosen $h$, then $h=\dtn g$ for $g:=\gamma^+_0 u$, which shows the surjectivity of $\dtn$.



We further remark that for any $g\in H^\half(\Gamma)$, as shown by \eqref{shboundaryequ} with $f=0$, 
\begin{align*}
\dtn g= -\frac{1}{2}S^{-1} (g-Tg),
\end{align*}
which yields the boundedness of $\dtn$, and the open mapping theorem implies that $\dtn^{-1}$ is bounded as well. 


It remains to show the coercivity. For $h\in H^{-\half}(\Gamma)$ let $v_h$ be the solution of (b) with $f=0$.
For any $g\in H^\half(\Gamma)$ and any $h\in H^{-\half}(\Gamma)$ we have then, due to Lemma \ref{uvskal}:
	\[
	-(h,\overline{g})_{H^{-\half}(\Gamma), H^{\half}(\Gamma)}=\int_{\Omega_+}\langle \nabla v_h,\nabla u_g\rangle_{\C^N}\dd x.
\]
In particular, noting that $v_h=u_g$ for $h=\dtn g$ one arrives at
\begin{equation}
	\label{dtn1}
	-(\dtn g,\overline{g})_{H^{-\half}(\Gamma), H^{\half}(\Gamma)}=\int_{\Omega_+} |\nabla u_g|^2\dd x
\end{equation}
and, similarly,
\[
\int_{\Omega_+}	|\nabla v_h|^2\dd x =-\big(h, \overline{\dtn^{-1} h} \big)_{H^{-\half}(\Gamma), H^{\half}(\Gamma)}\leq  \|\dtn^{-1}\|_{H^{-\half}(\Gamma) \to H^{\half}(\Gamma)} \|h\|^2_{H^{-\half}(\Gamma)}. 
\]
Then for any $g \in H^{\frac{1}{2}}(\Gamma)$ we have
	\begin{align*}
		\|g\|_{H^{\frac{1}{2}}(\Gamma)}^2 &= \sup\limits_{h\in H^{-\frac{1}{2}}(\Gamma),\, h\ne 0} \dfrac{\big|(h,\Bar g )_{H^{-\half }(\Gamma), H^{\half }(\Gamma)}\big|^2}{\|h\|_{H^{-\half}(\Gamma)}^2}\\
		& = \sup\limits_{h\in H^{-\half}(\Gamma),\, h\ne 0} \dfrac{\bigg|\displaystyle \int_{\Omega_+}\langle \nabla v_h,\nabla u_g\rangle_{\C^m}\dd x	\bigg|^2	
		}{\|h\|_{H^{-\half}(\Gamma)}^2}\\
		& \leq \sup\limits_{h\in H^{-\half}(\Gamma),\,h\ne 0} \dfrac{\displaystyle \int_{\Omega_+}|\nabla v_h|^2\dd x \int_{\Omega_+} |\nabla u_g|^2\dd x}{\|h\|_{H^{-\half }(\Gamma)}^{2}}\\
		&\leq \sup\limits_{h\in H^{-\half}(\Gamma),\,h\ne 0} \dfrac{\displaystyle \|\dtn^{-1}\|_{H^{-\half}(\Gamma) \to H^{\half}(\Gamma)} \|h\|^2_{H^{-\half}(\Gamma)} \int_{\Omega_+} |\nabla u_g|^2\dd x}{\|h\|_{H^{-\half }(\Gamma)}^{2}}\\
		&\le  \|\dtn^{-1}\|_{H^{-\half}(\Gamma) \to H^{\half}(\Gamma)}  \int_{\Omega_+} |\nabla u_g|^2\dd x,
	\end{align*}
	i.e.
	\[
	\int_{\Omega_+} |\nabla u_g|^2\dd x\ge \|\dtn^{-1}\|_{H^{-\half}(\Gamma) \to H^{\half}(\Gamma)}^{-1} \|g\|_{H^{\frac{1}{2}}(\Gamma)}^2,
	\]
	and the substitution into \eqref{dtn1} gives the required result.
\end{proof}



\subsection{Dirichlet-to-Neumann map for $m=2$}\label{sec-m2}
Compared to the case $m\geq 3$ considered in the statement of Theorem \ref{DTNdge2}, the two-dimensional case presents additional difficulties. Recall the lemma from \cite[Sec.~8.14]{McLean}:
\begin{lem} \label{Sh+c=G}
	Let $m=2$, then for any $(g,b)\in H^{\half}(\Gamma)\times \C$ there is a unique solution $(h,c)\in H^{-\half}(\Gamma) \times \C$ to the system
	\[
	\left\{\begin{aligned}
	Sh + c &= g,\\
	\langle h,\one_{\Gamma} \rangle_{H^{-\half}(\Gamma), H^{\half}(\Gamma)} &= b.
	\end{aligned}\right.
	\] 
	In addition, the solution $(h,c)$ is continuously dependent on the right-hand side $(g,b)$, i.e. there is $c_0>0$ such that
	\[
	\|h\|^2_{H^{-\half}(\Gamma)} + |c|^2 \le c_0\big(\|g\|^2_{H^\half(\Gamma)}+|b|^2\big)
	\]
	for all $(g,b)$.
\end{lem}

\begin{thm} \label{Dirchletd1}
	Let $m=2$ and $f\in L^2_\comp(\Omega_+)$, then for any $g\in H^{\half}(\Gamma)$ there is a unique $u\in H^1_\loc(\Omega_+)$ solving the Dirichlet problem with the radiation condition
	\[
	\left\{
	\begin{aligned}
		-\Delta u &= f & \text{ in }&\Omega_+,\\
		\gamma^+_0u &= g & \text{ on }& \Gamma,\\
		u(x) &= O(1) & \text{ for }|x| &\to \infty.
	\end{aligned}\right.
	\]
	This solution has the form
	\begin{equation}
	\label{u-ansatz}
	u = \cG f + \SL h + c, 
\end{equation}
with $h\in H^{-\half} (\Gamma)$ and $c\in\C$ satisfying
\begin{equation}
	\label{eq-shc}
Sh+c=g-\gamma^+_0\cG f,\qquad ( h,\one_\Gamma)_{H^{-\half}(\Gamma),H^\half(\Gamma)}=-\int_{\supp f} f\,\dd x.
\end{equation}
In addition, for any cut-off function $\varphi\in C^\infty_c(\R^2)$ there is a constant $c>0$ 
such that for all $(f,g)$ as above and the respective solution $u$ it  holds that
	\begin{equation}
		\label{unorm00}
	\|\varphi u\|_{H^1(\Omega_+)} \le c \big(\|f\|_{L^2(\Omega_+)} + \|g\|_{H^\half(\Gamma)}\big).
	\end{equation}
\end{thm}
Remark that the radiation condition at infinity in the above theorem differs from the condition at infinity stated in Theorem \ref{boundequ}. This explains appearance of an extra constant term in the representation formula \eqref{u-ansatz}.
\begin{proof}
The uniqueness of $u$ follows by Lemma~\ref{uniq}(a). For the existence we will use the ansatz \eqref{u-ansatz}
with $(h,c) \in H^{-\half}(\Gamma) \times \C$ to be determined. Remark that $-\Delta u = f$ for any choice of $(h,c)$. For any $x\in \Omega_+$ one has by construction
	\begin{align*}
		(\cG f)(x)&=\int_{\supp f} G(x-y)f(y)\dd y=-\frac{1}{2\pi}\int_{\supp f} \log\dfrac{|x-y|}{r} f(y)\dd y,\\[\medskipamount]
	\big(\SL h\big)(x)&=\big( h,G(x-\cdot)\big)_{H^{-\half}(\Gamma),H^\half(\Gamma)}
	=-\frac{1}{2\pi} \Big( h,\gamma^+_0 \log \dfrac{|x-\cdot|}{r}\Big)_{H^{-\half}(\Gamma),H^\half(\Gamma)}.
	\end{align*}
	Representing
	\[
	-\frac{1}{2\pi}\log\dfrac{|x-y|}{r}=-\frac{1}{2\pi}\log\dfrac{|x|}{r}+F_x(y)
	\]
	with 
	\[
	F_x(y):=-\dfrac{1}{2\pi}\log\Big|\dfrac{x}{|x|}-\dfrac{y}{|x|}\Big|\equiv -\dfrac{1}{4\pi}
	%\dfrac{1}{2}
	\log\Big( 1-2\dfrac{\langle x,y\rangle_{\R^2}}{|x|^2}+\dfrac{|y|^2}{|x|^2}\Big)
	\]
	we obtain
	\begin{align*}
	(\cG f)(x)&=-\dfrac{1}{2\pi}\log \dfrac{|x|}{r}\int_{\supp f} f\,\dd x+\int_{\supp f} F_x(y)f(y)\dd y,\\
	\big(\SL h\big)(x)&=-\dfrac{1}{2\pi}\log \dfrac{|x|}{r}( h,1)_{H^{-\half}(\Gamma),H^\half(\Gamma)}
	+( h,\gamma^+_0 F_x)_{H^{-\half}(\Gamma),H^\half(\Gamma)}.
	\end{align*}
Using Taylor expansion of $\log(1+\cdot)$ we immediately obtain
\[
\|F_x\|_{L^\infty(B)}=O\Big(\dfrac{1}{|x|}\Big) \text{ for }|x|\to\infty,
\]
for any bounded $B\subset\R^2$, and for $B:=\supp f$ this results in
\begin{equation}
	\label{g-asymp}
(\cG f)(x)=-\dfrac{1}{2\pi}\log \dfrac{|x|}{r}\int_{\supp f} f\,\dd x+O\Big(\dfrac{1}{|x|}\Big) \text{ for }|x|\to\infty.
\end{equation}
Now let $B\subset\R^2$ be a bounded open set containing $\Gamma$, then for each $j\in\{1,2\}$ we have additionally
\[
\|\partial_{y_j} F_x\|_{L^\infty(B)}=O\Big(\dfrac{1}{|x|}\Big) \text{ for }|x|\to\infty,
\]
showing
\[
\|F_x\|_{H^1(B)}=O\Big(\dfrac{1}{|x|}\Big) \text{ for }|x|\to\infty,
\]
and the boundedness of the trace map implies
\[
\|\gamma^+_0 F_x\|_{H^\half(\Gamma)}=O\Big(\dfrac{1}{|x|}\Big) \text{ for }|x|\to\infty,
\]
and then
\begin{equation}
	\label{slhx}
\big(\SL h\big)(x)=-\dfrac{1}{2\pi}\log \dfrac{|x|}{r}( h,1)_{H^{-\half}(\Gamma),H^\half(\Gamma)}
+O\Big(\dfrac{1}{|x|}\Big) \text{ for }|x|\to\infty.
\end{equation}
We conclude that the function $u$ given by \eqref{u-ansatz} behaves
as
\[
u(x)=-\dfrac{1}{2\pi}\Bigg[\int_{\supp f} f\,\dd x+ ( h,1)_{H^{-\half}(\Gamma),H^\half(\Gamma)}\Bigg]
\log \dfrac{|x|}{r}+c +O\Big(\dfrac{1}{|x|}\Big) \text{ for }|x|\to\infty,
\]
and it satisfies the radiation condition $u(x)=O(1)$ for large $|x|$ if and only if the coefficient in the square brackets vanishes. Furthermore,
\[
\gamma_0^+u=\gamma^+_0\cG f +S h+c.
\]
Using Lemma \ref{Sh+c=G} we can choose $(h,c)$ such that \eqref{eq-shc} holds,
then
\[
u(x)=c+O\Big(\dfrac{1}{|x|}\Big)=O(1) \text{ for }|x|\to\infty,
\qquad \gamma^+_0 u= g,
\]
i.e. all requirements are satisfied. The norm control \eqref{unorm00} follows from the continuity of the map $(g,f)\mapsto (h,c)$ and the mapping properties of $\cG$ and $\SL$.
\end{proof}
Again, unlike in the case $m\geq 3$, the exterior Neumann problem for the Laplacian is no longer well-posed for arbitrary initial data, but rather requires a certain compatibility relation that ensures the existence of the solution.
\begin{thm} \label{Neumannd1}
Let $m=2$, then for any $f\in L^2_\comp(\Omega_+)$ and $h \in H^{-\half}(\Gamma)$ with
\[
\int_{\Omega_+} f\dd x+\big( h, \one_{\Gamma}\big)_{H^{-\half}(\Gamma), H^{\half}(\Gamma)}=0
\]
 there is a unique solution $u \in H^1_{\loc}(\Omega_+)$ for the Neumann problem 	
	\[
	\left\{
	\begin{aligned}
	-\Delta u &= f  \text{ in }\Omega_+,\\
		\gamma^+_1 u &= h  \text{ on }\Gamma, \\
		u(x) &= o(1) \text{ for } |x| \to \infty.
	\end{aligned}\right.
	\]
\end{thm}
\begin{proof}
The uniqueness follows by Lemma \ref{uniq}(b-ii). Indeed, assume that $u$ solves the Neumann problem with $f=0$ and $h=0$. From the radiation condition $u(x)=o(1)$ for $|x|\rightarrow +\infty$ it follows that $u(x)=O(1)$ for $|x|\rightarrow +\infty$  and by Lemma \ref{uniq}, $u=\operatorname{const}$. However, since $u(x)=o(1)$ for $|x|\rightarrow +\infty$, necessarily, $u=0$. 
To show the existence we use the ansatz
	\[
	u= \cG f-\DL g + \SL h 
	\]
	with $g\in H^{\half}(\Gamma)$ to be determined. Note that $-\Delta u = f$ for any choice of $g$.

	Let us show that $u$ satisfies the required bound at infinity.	By using the above assumptions on $f$ and $h$
	in the previously obtained estimates \eqref{g-asymp} and \eqref{slhx} we conclude that
	\[
	\cG f(x)+\SL h(x)=o(1) \text{ for }|x|\to\infty,
	\]
	and it remains to study $\DL g(x)$ for large $x$. For $x\in \Omega_+$ one has
	\begin{align*}
		\big|\DL g(x)\big|&=\bigg|\int_{\Gamma} \partial_{\nu_y} G(x-y) g(y)\,\dd s(y)\bigg|=\frac{1}{2\pi}\bigg|\int_\Gamma \dfrac{\langle \nu_y,x-y\rangle_{\R^2}}{|x-y|^2}g(y)\dd s(y)\bigg|\\
		&\le \dfrac{1}{2\pi}\int_\Gamma \bigg|\dfrac{\langle \nu_y,x-y\rangle_{\R^2}}{|x-y|^2}\bigg|\cdot \big|g(y)\big|\dd s(y)\le \int_\Gamma \dfrac{\big|g(y)\big|}{|x-y|}\dd s(y).
	\end{align*}		
	Let $R>0$ with $\Gamma\subset B_R(0)$, then for $|x|>R$ and $y\in\Gamma$ one has $|x-R|\ge |x|-R$, which yields
	\begin{equation}
		\label{dlg}
	\big|\DL g(x)\big|\le \dfrac{1}{2\pi}\cdot\dfrac{1}{|x|-R}\|g\|_{L^1(\Gamma)}=o(1) \text{ for } |x|\to\infty.
	\end{equation}
	This shows $u(x)=o(1)$ for $|x|\to\infty$ for any choice of $g$.

	It remains to check that $g$ can be chosen such that $u$ satisfies the required boundary condition. Note that
	$\gamma^+_1 u=\gamma^+_1\cG f+Rg+\gamma^+_1 \SL h$, and the boundary condition $\gamma^+_1 u=h$ is satisfied if and only if
	\[
	h=\gamma^+_1\cG f+Rg+\gamma^+_1 \SL h \quad \text{ i.e. } \quad Rg=h-\gamma^+_1\cG f-\gamma^+_1 \SL h.
	\]
	As $R$ is Fredholm and self-adjoint with $\ker R=\C \one_\Gamma$ (see Lemma \ref{lemma-RS}), this last equation is solvable with respect to $g$ if any only if
	\begin{equation}
		\label{hsl}
	I:=(\one_\Gamma,h-\gamma^+_1\cG f -\gamma^+_1 \SL h)_{H^\half(\Gamma),H^{-\half}(\Gamma)}=0.
	\end{equation}
	We have $I=I_1-(I_2+I_3)$, where
	\begin{align*}
		I_1&:=(\one_\Gamma,\gamma^+_1\cG f)_{H^\half(\Gamma),H^{-\half}(\Gamma)},\\
		I_2&:=(\one_\Gamma,h)_{H^\half(\Gamma),H^{-\half}(\Gamma)},\\
		I_3&:=(\one_\Gamma,\gamma^+_1 \SL h)_{H^\half(\Gamma),H^{-\half}(\Gamma)},
	\end{align*} 
	For $I_1$ we have, due to the definition of $\DL$,
	\[
	I_1=(\DL \one, f)_{H^1_\loc(\Omega_+),H^{-1}_\comp(\Omega_+)}=0,
	\]
	as $\DL\one_\Gamma=0$ in $\Omega_+$, see \eqref{DLone}. With the help of \eqref{sl-dl} we obtain
\[
I_3=(\gamma^-_0 \DL \one_\Gamma,h)_{H^{\half}(\Gamma),H^{-\half}(\Gamma)}.
\]
By \eqref{DLone} one has $\gamma^-_0 \DL \one_\Gamma= -\one_\Gamma$, hence,
	\[
	I_3=-(\one_\Gamma,h)_{H^{-\half}(\Gamma),H^\half(\Gamma)}=-I_2.
	\]
This shows $I=0$, i.e. the solvability condition \eqref{hsl} is satisfied, which gives a harmonic function $u$ of the above form with $\gamma^+_1 u=h$. 
\end{proof}

To prove the result that follows, it will be convenient to introduce the following decomposition of the space $H^{\half}(\Gamma)$:
		\begin{align}
			\label{eq:decomp_direct_sum}
			H^{ \half}(\Gamma)&=\mathbb{C}\one_{\Gamma}\overset{.}{+}H^{ \half}_0(\Gamma),\\
			%\label{eq:h012}
			\nonumber
			H^\half_0(\Gamma)&:=\Big\{ g\in H^\half(\Gamma):\, (\one_\Gamma,g)_{H^{-\half}(\Gamma),H^\half(\Gamma)}=0\Big\}. 
		\end{align}
This decomposition can be obtained by introducing the $L^2-$orthogonal projector $\Pi_1$ onto the space $\C\one_{\Gamma}$: 
\begin{align*}
	\Pi_1: \, H^{\half}(\Gamma)\ni g\mapsto g:=\frac{(g, \one_{\Gamma})_{L^2(\Gamma)}}{\|\one_{\Gamma}\|_{L^2(\Gamma)}^2}\one_{\Gamma}=\frac{1}{|\Gamma|}\bigg(\int_{\Gamma}g\dd x\bigg)\one_{\Gamma}\in H^{\half}(\Gamma).
\end{align*} 
The projector on the subspace $H^{\half}_0(\Gamma)$ with respect to the direct sum \eqref{eq:decomp_direct_sum} is
given by $\Pi_{0}=\operatorname{Id}-\Pi_1$, and thus the corresponding direct sum becomes orthogonal with respect to the $L^2(\Gamma)$-scalar product. Remark that $\Pi_1$ and $\Pi_0$ are continuous in $H^{\half}(\Gamma)$ and consider their
adjoints (which are also projectors):
\[
			\Pi_1^*, \, \Pi_0^*: \, H^{-\half}(\Gamma)\rightarrow H^{-\half}(\Gamma).
\]
The usual computation for the adjoints, see e.g. \cite[Theorem 2.13]{McLean}, gives
\begin{equation}
				\label{eq:h0m12}
\begin{aligned}
			\ran \Pi^*_0&=	\Big\{ h\in H^{-\half}(\Gamma):\ 
			\big( h, \one_{\Gamma}\big)_{H^{-\half}(\Gamma), H^{\half}(\Gamma)}=0\Big\}=:H^{-\half}_0(\Gamma),\\
			\ran \Pi_1^*&=\C\one_{\Gamma},
\end{aligned} 
\end{equation}
which gives the direct sum decomposition
\[
	H^{- \half}(\Gamma)=\C\one_{\Gamma}\overset{.}{+}H^{-\half}_0(\Gamma)
\]
with $\Pi_1^*$, respectively, $\Pi_0^*$ being the projector on the first, respectively, the second component,
and one obtains the following assertion:
		\begin{lem} The map
			\label{lem:equiv_norm}
		\begin{align*}
			\varphi\mapsto |\varphi|_{H^{-\half}(\Gamma)}:= \|\Pi_0^*\varphi\|_{H^{-\half}(\Gamma)}+\|\Pi_1^*\varphi\|_{H^{-\half}(\Gamma)}
		\end{align*}
		defines an equivalent norm on $H^{-\half}(\Gamma)$. 
	\end{lem}
\begin{proof}
Both projectors $\Pi_0^*$ and $\Pi_1^*$ are continuous, thus $|\varphi|_{H^{-\half}(\Gamma)}\leq C\|\varphi\|_{H^{-\half}(\Gamma)}$. On the other hand,
		\begin{align*}
			\|\varphi\|_{H^{-\half}(\Gamma)}&=\sup_{g\in H^{\half}(\Gamma): \, g\neq 0}\frac{( \varphi, g)_{H^{-\half}(\Gamma), H^{\half}(\Gamma)}}{\|g\|_{H^{\half}(\Gamma)}}
			=\sup_{g\in H^{\half}(\Gamma): \, g\neq 0}\frac{( \Pi_1^*\varphi+\Pi_0^*\varphi, g)_{H^{-\half}(\Gamma), H^{\half}(\Gamma)}}{\|g\|_{H^{\half}(\Gamma)}}\\
			&\leq \sup_{g\in H^{\half}(\Gamma): \, g\neq 0}\frac{\left(\|\Pi_1^*\varphi\|_{H^{-\half}(\Gamma)}+\|\Pi_0^*\varphi\|_{H^{-\half}(\Gamma)}\right)\|g\|_{H^{\half}(\Gamma)}}{\|g\|_{H^{\half}(\Gamma)}}=|\varphi|_{H^{-\half}(\Gamma)}.\qedhere
		\end{align*}
\end{proof}

\begin{cor} \label{DTNd=1}
Let $m=2$. The Dirichlet-to-Neumann operator $\dtn:H^\half(\Gamma)\to H^{-\half}(\Gamma)$
defined by 
\[
\dtn:\  g \mapsto \gamma^+_1 u_g,
\]
where $u_g\in H^1_\loc(\Omega_+)$ is the unique solution of the Dirichlet problem
\[
\left\{
\begin{aligned}
	-\Delta u &= 0  \text{ in }\Omega_+,\\
	\gamma^+_0u &= g  \text{ on } \Gamma,\\
	u(x) &= O(1) \text{ for }|x| \to \infty,
\end{aligned}\right.
\]
is bounded, non-positive and Fredholm of index $0$, with $\ker\dtn =\C \one_\Gamma$ and $\ran \dtn = H^{-\half}_0(\Gamma)$. 
In addition, it is coercive on $H^{\half}_0(\Gamma)$, 
i.e. there is a constant $c>0$ such that for any  $g\in H^{\half}(\Gamma)$ 
it holds that
\[
 - (\dtn g, \overline{g})_{H^{-\half}(\Gamma), H^{\half}(\Gamma)} \ge c \|\Pi_0 g\|^2_{H^\half (\Gamma)}. 
\]	
\end{cor}

\begin{proof}
Step 1. The boundedness of $\dtn$ follows directly from Theorem \ref{Dirchletd1}. 

Step 2: Let us show $\ker \dtn=\C\one_{\Gamma}$.
For $g:=\one_\Gamma$ one clearly has $u_g=\one_{\Omega_+}$
and $\dtn g=\gamma^+_1 u_g=0$, i.e. $\one_\Gamma\subset\ker \dtn$. On the other hand, let $g \in \ker \dtn$, then  $u_g$ satisfies
\[
	\Delta u_g = 0, \quad \gamma^+_1 u_g=0,\quad u(x)=O(1) \text{ for } |x|\to\infty,
\]
so $u$ is constant in $\Omega_+$ by Lemma \ref{uniq}(c-ii), and then $g$ is a multiple of $\one_\Gamma$. 


Step 3: We show that $\dtn$ is a self-adjoint operator.  Let $g, h\in H^{\half}(\Gamma)$, and let $u_g, u_h$ resp. be the solutions of the Dirichlet problem of Theorem \ref{Dirchletd1} with $f=0$. Then, by Lemma \ref{uvskal}, 
\begin{align*}
	(\mathcal{C}g, \overline{h})_{H^{-\half}(\Gamma), H^{\half}(\Gamma)}&=-\int_{\Omega_+}\langle \nabla u_g, \nabla u_h\rangle_{\mathbb{C}^m}\dd x=-\overline{\int_{\Omega_+}\langle \nabla u_h, \nabla u_g\rangle_{\mathbb{C}^m}}\dd x\\
	&=\overline{(\mathcal{C}h, \overline{g})}_{H^{-\half}(\Gamma), H^{\half}(\Gamma)},
\end{align*}
which gives the sought conclusion.

Step 4: We show that $\ran \dtn=H^{-\half}_0(\Gamma)$. Due to the self-adjointness of $\dtn$ the subspace $\ran \dtn$
is contained in the annihilator of $\ker \dtn$, see e.g. \cite[Lemma 2.10  and p.~23]{McLean}.
The annihilator of $\ker\dtn\equiv\C\one_\Gamma$ is exactly $H^{-\half}_0(\Gamma)$, which gives the inclusion
$\ran \dtn\subset H^{-\half}_0(\Gamma)$. 
On the other hand, by Theorem \ref{Neumannd1} for any $h\in H^{-\half}_0(\Gamma)$ there is a function $v\in H^1_\loc(\Omega_+)$ with
\[
\Delta v=0,\quad \gamma^+_1 v=h,\quad  v(x)=o(1)=O(1) \text{ for } |x|\to\infty,
\]
so $v=u_g$ for $g:=\gamma^+_0 v$, and $h=\dtn g$. This shows $H^{-\half}_0(\Gamma)\subset \ran\dtn$.
Finally we obtain the sought equality, which then implies $\operatorname{codim}\ran\dtn=1$.

Step 5: Fredholm index. The above discussion shows that $\dtn$ is Fredholm with  $\operatorname{codim}\ran\dtn=1=\dim\ker\dtn$, thus $\dtn$ has zero index. 


Step 6: Coercivity on the space $H^{\half}_0(\Gamma)$. 
For any $g\in H^\half(\Gamma)$ one has, due to Lemma \ref{uvskal},
\begin{equation}
	\label{nonpos00}
	-(\dtn g,\overline{g}\,)_{H^{-\half}(\Gamma),H^\half(\Gamma)}=-(\gamma^+_1 u_g,\overline{\gamma^+_0 u_g}\,)_{H^{-\half}(\Gamma),H^\half(\Gamma)}=\int_{\Omega_+}|\nabla u_g|^2\dd x\ge 0,
\end{equation}
which shows the non-positivity of $\dtn$. 
Further remark that by the above consideration the restricted operator
\[
\dtn_0:\ H^\half_0(\Gamma)\ni g_0\mapsto \dtn g_0\in H^{-\half}_0(\Gamma)
\]
is bounded and bijective, therefore, it has a bounded inverse. In particular, for any $h_0\in H^{-\half}_0(\Gamma)$
we have
\begin{equation}
	\label{ch00}
\begin{aligned}	
\int_{\Omega_+}	|\nabla u_{\dtn_0^{-1}h_0}|^2\dd x &=-\big(h, \overline{\dtn^{-1}_0 h_0} \big)_{H^{-\half}(\Gamma), H^{\half}(\Gamma)}\\
&\leq  \|\dtn^{-1}_0\|_{H^{-\half}_0(\Gamma) \to H^{\half}_0(\Gamma)} \|h_0\|^2_{H^{-\half}(\Gamma)}. 
\end{aligned}
\end{equation}
By Lemma  \ref{lem:equiv_norm} we can find some $B>0$ such that $|h|_{H^{-\half}(\Gamma)}\le B\|h\|_{H^{-\half}(\Gamma)}$
for all $h\in H^{-\half}(\Gamma)$.

Let $g_0 \in H^{\frac{1}{2}}_0(\Gamma)$, then
\begin{align*}
\|g_0\|_{H^{\frac{1}{2}}(\Gamma)}&=\sup\limits_{h\in H^{-\frac{1}{2}}(\Gamma),\, h\ne 0} \dfrac{\big| (h,\Bar g_0 )_{H^{-\half }(\Gamma), H^{\half }(\Gamma)}\big|}{\|h\|_{H^{-\half}(\Gamma)}}\leq B\sup\limits_{h\in H^{-\frac{1}{2}}(\Gamma),\, h\ne 0} \dfrac{\big| (h,\Bar g )_{H^{-\half }(\Gamma), H^{\half }(\Gamma)}\big|}{|h|_{H^{-\half}(\Gamma)}}\\
&= B\sup\limits_{h\in H^{-\frac{1}{2}}(\Gamma),\, h\ne 0} \dfrac{\big| (\Pi_{0}^*h+\Pi_1^* h,\Bar g_0)_{H^{-\half }(\Gamma), H^{\half }(\Gamma)}\big|}{\|\Pi_0^*h\|_{H^{-\half}(\Gamma)}+\|\Pi_1^*h\|_{H^{-\half}(\Gamma)}}=I
\end{align*}
Remark that for any $h\in H^{-\half}(\Gamma)$, 
\begin{align*}
	(\Pi_1^*h, \Bar g_0)_{H^{-\half }(\Gamma), H^{\half }(\Gamma)}=(h, \overline{\Pi_1 g_0})_{H^{-\half }(\Gamma), H^{\half }(\Gamma)}=0,
\end{align*}
since $g_0\in H^{-\half}_0(\Gamma)=\operatorname{Ker}\Pi_1$, 
and the preceding computation can be continued as:
\begin{align*}
I&=B\sup\limits_{h\in H^{-\frac{1}{2}}(\Gamma),\, h\ne 0} \dfrac{\big| (\Pi_{0}^*h,\Bar g_0)_{H^{-\half }(\Gamma), H^{\half }(\Gamma)}\big|}{\|\Pi_0^*h\|_{H^{-\half}(\Gamma)}+\|\Pi_1^*h\|_{H^{-\half}(\Gamma)}}\\
&=B\sup\limits_{h\in H^{-\frac{1}{2}}(\Gamma),\, \Pi_0^*h\ne 0} \dfrac{\big| (\Pi_0^*h,\Bar g )_{H^{-\half }(\Gamma), H^{\half }(\Gamma)}\big|}{\|\Pi_0^*h\|_{H^{-\half}(\Gamma)}+\|\Pi_1^*h\|_{H^{-\half}(\Gamma)}}\\
&\leq B\sup\limits_{h\in H^{-\frac{1}{2}}(\Gamma),\, \Pi_0^*h\ne 0} \dfrac{\big| (\Pi_0^*h,\Bar g )_{H^{-\half }(\Gamma), H^{\half }(\Gamma)}\big|}{\|\Pi_0^*h\|_{H^{-\half}(\Gamma)}}.
\end{align*}
Since $\ran \Pi_0^*=H^{-\half}_0(\Gamma)$, the reparametrization $h_0:=\Pi_0^* h$ yields
\begin{align*}
	\|g_0\|_{H^{\frac{1}{2}}(\Gamma)}&\leq B\sup\limits_{h_0\in H^{-\half}_0(\Gamma),\, h_0\ne 0} \dfrac{\big| (h_0,\Bar g_0)_{H^{-\half }(\Gamma), H^{\half }(\Gamma)}\big|}{\|h_0\|_{H^{-\half}(\Gamma)}}.
\end{align*}
By applying Lemma \ref{uvskal} on the right-hand side we arrive at
\begin{align*}
	\|g_0\|_{H^{\frac{1}{2}}(\Gamma)}^2 &\leq B \sup\limits_{h_0\in H^{-\half}_0(\Gamma),\, h_0\ne 0} \dfrac{\bigg|\displaystyle \int_{\Omega_+}\langle \nabla u_{\dtn_0^{-1}h_0},\nabla u_{g_0}\rangle_{\C^m}\dd x	\bigg|^2	
	}{\|h\|_{H^{-\half}(\Gamma)}^2}\\
	& \leq B \sup\limits_{h_0\in H^{-\half}_0(\Gamma),\,h_0\ne 0} \dfrac{\displaystyle \int_{\Omega_+}|\nabla u_{\dtn_0^{-1}h_0}|^2\dd x \int_{\Omega_+} |\nabla u_{g_0}|^2\dd x}{\|h\|_{H^{-\half }(\Gamma)}^2}\\
\text{use \eqref{ch00}: }	&\leq B \sup\limits_{h_0\in H^{-\half}_0(\Gamma),\,h_0\ne 0} \dfrac{\displaystyle \|\dtn^{-1}_0\|_{H^{-\half}_0(\Gamma) \to H^{\half}_0(\Gamma)} \|h_0\|^2_{H^{-\half}(\Gamma)} \int_{\Omega_+} |\nabla u_{g_0}|^2\dd x}{\|h\|_{H^{-\half }(\Gamma)}^{2}}\\
	&\le  B\|\dtn^{-1}_0\|_{H^{-\half}_0(\Gamma) \to H^{\half}_0(\Gamma)}  \int_{\Omega_+} |\nabla u_{g_0}|^2\dd x,
\end{align*}
i.e.
\[
\int_{\Omega_+} |\nabla u_{g_0}|^2\dd x\ge c \|g_0\|_{H^{\half}(\Gamma)}^2,
\quad
c:=\dfrac{1}{B\|\dtn^{-1}_0\|_{H^{-\half}_0(\Gamma) \to H^{\half}_0(\Gamma)}}.
\]
The substitution into \eqref{nonpos00} gives
\begin{equation}
	\label{cg0}
-(\dtn g_0,\overline{g_0}\,)_{H^{-\half}(\Gamma),H^\half(\Gamma)}\ge c \|g_0\|^2_{H^\half(\Gamma)}
\text{ for all } g_0\in H^\half_0(\Gamma).
\end{equation}

Using the self-adjointness of $\dtn$ and the identity $\dtn \Pi_1=0$, for any $g\in H^\half(\Gamma)$
we obtain:
\begin{align*}
- (\dtn g, \overline{g})_{H^{-\half}(\Gamma), H^{\half}(\Gamma)}&= - (\dtn (\Pi_0g+\Pi_1 g), \overline{\Pi_0g+\Pi_1 g})_{H^{-\half}(\Gamma), H^{\half}(\Gamma)}\\
&=-(\dtn \Pi_0g, \overline{\Pi_0 g})\stackrel{\eqref{cg0}}{\ge}
c \|\Pi_0 g\|^2_{H^\half(\Gamma)}.\qedhere
\end{align*}

\end{proof}

 \section{Hybrid transmission problem}
\label{sec:4}
\subsection{Well-posedness}
\label{sec:41}
Now we give a rigorous formulation of the transmission problem described in the introduction.

\begin{prob}\label{prob41}
Let $\alpha_1\in \C\setminus\{0\}$ and $\alpha_0\in L^\infty(\Gamma)$ be given.	
For $f_\cT\in L^2(\cT)$,  $f_\Omega\in L^2_\comp(\Omega)$ and $c\in\C$, find 
the solutions $(u_\cT,u_\Omega)\in H^1(\cT)\times H^1_\loc(\Omega)$ of the transmission problem
	\begin{equation}
	\label{transm00}
	\left\{\begin{aligned}
		\Delta_\cT u_\cT&=f_\cT \text{ on } \cT,\\
		\Delta u_\Omega&=f_\Omega \text{ on } \Omega,\\
		\gamma^\Omega_0 u_\Omega&=\gamma^\cT_0 u_\cT \text{ on } \Gamma,\\
		\gamma^\Omega_1 u_\Omega-\alpha_1\gamma^\cT_1 u_\cT&=\alpha_0 \gamma^\Omega_0 u_\Omega \text{ on }\Gamma,\\
		u_\Omega(x)&=O(|x|^{2-m}) \text{ for } |x|\to\infty,\\
		u_\cT(o)&=c.	
	\end{aligned}
	\right.	
\end{equation}
\end{prob}

Let us start with preliminary remarks on the associated homogeneous problem.


\begin{lem}\label{lem42}
Let $\alpha_1\in \C\setminus\{0\}$ and $\alpha_0\in L^\infty(\Gamma)$. Define the operator
\begin{equation}
	\label{moper}
	M:\ H^{\half}(\Gamma)\ni g\ \mapsto\   -\dtn g+\alpha_1\D g +\alpha_0 g \in H^{-\half}(\Gamma),
\end{equation}
then $\dim\ker M$ coincides with the dimension of the solution space of the homogeneous problem
	\begin{equation}
		\label{transm00hh}
		\left\{\begin{aligned}
			\Delta_\cT w_\cT&=0 \text{ on } \cT,\\
			\Delta w_\Omega&=0 \text{ on } \Omega,\\
			\gamma^\Omega_0 w_\Omega&=\gamma^\cT_0 w_\cT \text{ on } \Gamma,\\
			\gamma^\Omega_1 w_\Omega-\alpha_1\gamma^\cT_1 w_\cT&=\alpha_0 \gamma^\Omega_0 w_\Omega \text{ on }\Gamma,\\
			w_\Omega(x)&=O(|x|^{2-m}) \text{ for } |x|\to\infty,\\
			w_\cT(o)&=0.
		\end{aligned}
		\right.	
	\end{equation}
\end{lem}	
\begin{proof}
	Let $(w_\T,w_\Omega)$ be a solution of \eqref{transm00hh} and $g:=\gamma^\cT_0 w_\T\equiv \gamma^\Omega_0 w_\Omega$,
	then $w_\cT$ and $w_\Omega$ are solutions of
	\begin{equation}
				\left\{\begin{aligned}
			\Delta_\cT w_\cT&=0 \text{ on } \cT,\\
			\gamma^\cT_0 w_\cT&=g \text{ on } \Gamma,\\
			w_\cT(o)&=0,
		\end{aligned}
		\right.	
		\qquad
		\left\{\begin{aligned}
			\Delta w_\Omega&=0 \text{ on } \Omega,\\
			\gamma^\Omega_0 w_\Omega&=g \text{ on } \Gamma,\\
			w_\Omega(x)&=O(|x|^{2-m}) \text{ for } |x|\to\infty,
		\end{aligned}
		\right.	
		\label{w-homog}
	\end{equation}
	therefore, $\gamma^\Omega_1 w_\Omega=\dtn g$ and $\gamma^\cT_1 w_\cT=\D g$.
	The fourth condition in \eqref{transm00hh} is satisfied if and only if
$\dtn g-\alpha_1\D g=\alpha_0 g$, i.e. $g\in\ker M$. To arrive at the desired conclusion, it remains to note that by Lemma~\ref{DPLEwell} and Theorem~\ref{thm21}
	the map $g\mapsto (w_\cT,w_\Omega)$ is one-to-one.  
\end{proof}
Our principal result is as follows:
\begin{thm}\label{thm31}
Let $\alpha_1\in \C\setminus\{0\}$ and $\alpha_0\in L^\infty(\Gamma)$ be such that the homogeneous problem \eqref{transm00hh}
has the unique solution	$(w_\T,w_\Omega)=(0,0)$. 


Then the operator $M$ in \eqref{moper}
is an isomorphism. Moreover, the non-homogeneous problem \eqref{transm00}
has a unique solution $(u_\cT,u_\Omega)\in H^1(\cT)\times H^1_\loc(\Omega)$ 
for any choice of $f_\cT\in L^2(\cT)$,  $f_\Omega\in L^2_\comp(\Omega)$ and $c\in\C$,  and the solution depends continuously on $(f_\cT,f_\Omega,c)$ as follows: for any cut-off function $\varphi\in C^\infty_c(\R^m)$ there is a constant $B>0$ such that
\[
\|u_\cT\|_{H^1(\cT)}+\|\varphi u_\Omega\|_{H^1(\Omega)}\le B\big(\|f_\cT\|_{L^2(\cT)}+\|f_\Omega\|_{L^2(\Omega)} + |c|\big).
\]
\end{thm}	

\begin{proof}
Step 1: We are going to show that the operator $M$ defined by \eqref{moper} is surjective.
The embeddings $\iota_1:\ H^{\half}(\Gamma) \hookrightarrow H^{\sigma d}(\Gamma)$ and $\iota_2:\ H^{-\sigma d}(\Gamma) \hookrightarrow H^{-\half}(\Gamma)$,
are compact, which yields the compactness of
$\iota_2\D\iota_1: H^{\frac{1}{2}}(\Gamma) \to H^{-\half}(\Gamma)$. Similarly, the compactness of
the embeddings
$\iota_3:\ H^{\half}(\Gamma) \hookrightarrow L^2(\Gamma)$, $\iota_4:\ L^2(\Gamma) \hookrightarrow H^{-\half}(\Gamma)$,
and the boundedness of the multiplication operator
\[
T_{\alpha_0}:\,L^2(\Gamma)\ni g\mapsto\alpha_0 g\in L^2(\Gamma)
\]
imply that
$\iota_4 T_{\alpha_0} \iota_3:\ H^\half(\Gamma)\to H^{-\half}(\Gamma)$
is compact. For the above operator $M$ we have the representation
$M=-\dtn+\alpha_1\iota_2\D\iota_1+\iota_4 T_{\alpha_0} \iota_3$,
so $M$ is a compact perturbation of the zero-index Fredholm operator $-\dtn$ (see Theorem \ref{thm22}), and it follows that $M$ is a zero-index Fredholm operator too. The assumption (unique solvability of the homogeneous problem)
and Lemma \ref{lem42} show that  $M$ is injective, so it is also surjective.


Step 2: Uniqueness of solutions. Let $(u_\cT,u_\Omega)$ and $(\Tilde u_\cT,\Tilde u_\Omega)$ be two solutions of the non-homogeneous problem \eqref{transm00}, then the functions  $w_\cT:=\Tilde u_\cT-u_\cT$ and $w_\Omega:=\Tilde u_\Omega-u_\Omega$ solve the homogeneous problem \eqref{transm00hh}. By assumption $(w_\cT,w_\Omega)=(0,0)$, which yields $(u_\cT,u_\Omega)=(\Tilde u_\cT,\Tilde u_\Omega)$.


Step 3: Existence of solutions. Use the ansatz $u_\cT=u+c u_1+u_f$, $u_\Omega=v+v_f$,
where
\begin{itemize}
	\item $u_1\in H^1_0(\cT)$ is an arbitrary function with $u_1(o)=1$ and $\Delta_\cT u_1\in L^2(\cT)$,
	\item $u_f\in \Tilde H^1_0(\cT)$ satisfies $\Delta_\cT u_f=f_\cT-c\Delta_\cT u_1$, which exists by~Lemma \ref{lem24},
	\item $u\in \Tilde H^1(\cT)$ is to be determined,
	\item $v_f\in H^1_\loc(\Omega)$ is the solution of
	\[
	\left\{\begin{aligned}
		- \Delta v_f &=f_\Omega  \text{ in }\Omega_+,\\
		\gamma^\Omega_0 v_f &=0  \text{ on }\Gamma,\\
		v_f(x)&= 	O(|x|^{2-m}) \text{ for } |x|\to \infty,
	\end{aligned}\right.
	\]	 
	which exists by Theorem \ref{thm21},
	\item $v\in H^1_\loc(\Omega)$ is to be determined.
\end{itemize}
Then $(u_{\cT}, u_{\Omega})$ satisfy \eqref{transm00} if and only if the new unknown functions $(u,v)$ satisfy
	\begin{equation}
		\label{transm11}
		\left\{\begin{aligned}
			\Delta_\cT u&=0 \text{ on } \cT,\\
			\Delta v&=0 \text{ on } \Omega,\\
			\gamma^\Omega_0 v&=\gamma^\cT_0 u \text{ on } \Gamma,\\
			\gamma^\Omega_1 v-\alpha_1\gamma^\cT_1 u&=\alpha_0 \gamma^\Omega_0 v +h \text{ on }\Gamma,\\
			v(x)&=O(|x|^{2-m}) \text{ for } |x|\to\infty,\\
			u(o)&=0,		
		\end{aligned}
		\right.	
	\end{equation}
with $h:=- \gamma^\Omega_1 v_f+\alpha_1 \gamma^\cT_1 \big(cu_1 +u_f\big)\in H^{-\half}(\Gamma)$.
Note that for any $g\in H^\half(\Gamma)$ the solutions $(u,v)$ to 
\begin{equation}
	\left\{\begin{aligned}
		\Delta_\cT u &=0 \text{ on } \cT,\\
		\gamma^\cT_0 u&=g \text{ on } \Gamma,\\
		u(o)&=0,
	\end{aligned}
	\right.	
	\qquad
		\left\{\begin{aligned}
		\Delta v&=0 \text{ on } \Omega,\\
		\gamma^\Omega_0 v&=g \text{ on } \Gamma,\\
		v(x)&=O(|x|^{2-m}) \text{ for } |x|\to\infty,
	\end{aligned}
	\right.	
	\label{uv-homog}
\end{equation}
satisfy all conditions in \eqref{transm11} expect the fourth one for the normal derivatives.
In order to fulfill this remaining condition we note that for $(u,v)$ in \eqref{uv-homog}
we have
\[
\gamma^\Omega_1 v= \dtn g,\qquad
\gamma^\cT_1 u=\D g,
\]
and the fourth condition in \eqref{transm11} holds if and only if 
\begin{align}
\label{eq:alphag}
\dtn g-\alpha_1 \D g-\alpha_0 g=h,	
\end{align}
which can be rewritten as $M g=-h$. As $M$ is surjective (as shown in Step 1), this equation
has a solution $g\in H^\half(\Gamma)$. By solving \eqref{uv-homog} for this $g$ we obtain a required solution for \eqref{transm11}.

Step 4: Dependence on the initial data. The continuity of the solution on the initial data easily follows by noting that the transitions
\[
(f_\cT,c)\mapsto u_f,\quad
f_\Omega\mapsto v_f,
\quad
(f_\cT,f_\Omega,c)\mapsto h,
\quad h\mapsto g,
\quad g\mapsto v,
\quad g\mapsto u
\]
are continuous in respective norms (with an additional cut-off on $\Omega$).	
\end{proof}
Specific cases for which Theorem \ref{thm31} is applicable are easily obtained using the sign-definiteness and {coercivity} of $\dtn$ and $\D$:
\begin{cor} \label{cor44}
The assumptions of Theorem \ref{thm31} are satisfied in the following cases:

\begin{itemize}
	\item[(i)] $\Re \alpha_1, \, \Re \alpha_0\geq 0$ with $\Re \alpha_1+\Re \alpha_0>0$ a.e. 
	\item [(ii)] $\Im \alpha_1,\Im \alpha_0\geq 0$, with $\Im \alpha_1+\Im \alpha_0>0$ a.e. 
\end{itemize}
Hence, for each of these cases 	Problem \ref{prob41} is uniquely solvable.
\end{cor}
\begin{proof}
Let $\alpha_1\in \C\setminus\{0\}$ and $\alpha_0\in L^\infty(\Gamma)$.
Let $g\in H^\half(\Gamma)$ with $Mg=0$, then
\begin{align}
\nonumber
0&=(Mg,\Bar g)_{H^{-\half}(\Gamma),H^\half(\Gamma)}\\
\label{eq:dtnid}
&=-(\dtn g,\Bar g)_{H^{-\half}(\Gamma),H^\half(\Gamma)}
+\alpha_1 (\D g,\Bar g)_{H^{-\sigma d}(\Gamma),H^{\sigma d}(\Gamma)}+\int_\Gamma \alpha_0 |g|^2\,\dd s.
\end{align}
We start by arguing that $(i)$ is sufficient. Taking the real part and using the coercivity of $\D$ (Theorem \ref{DTNtree}) and the non-positivity of $\dtn$ (Corollary \ref{DTNd=1} for $m=2$, Theorem \ref{DTNdge2} for $m\geq 3$), we obtain, with some $c>0$,
\begin{align*}
0&=	-(\dtn g,\Bar g)_{H^{-\half}(\Gamma),H^\half(\Gamma)}
+(\Re \alpha_1) (\D g,\Bar g)_{H^{-\sigma d}(\Gamma),H^{\sigma d}(\Gamma)}+\int_\Gamma (\Re \alpha_0) |g|^2\,\dd s\\
&\ge (\Re \alpha_1) (\D g,\Bar g)_{H^{-\sigma d}(\Gamma),H^{\sigma d}(\Gamma)}+\int_\Gamma (\Re \alpha_0) |g|^2\,\dd s,\\
&\ge (\Re \alpha_1)c\|g\|^2_{H^{\sigma d}(\Gamma)}+\int_\Gamma (\Re \alpha_0) |g|^2\,\dd s\\
&\ge (\Re \alpha_1)c\|g\|^2_{L^2(\Gamma)}+\int_\Gamma (\Re \alpha_0) |g|^2\,\dd s\\
&\ge \min\{1,c\} \int_\Gamma (\Re \alpha_1+\Re \alpha_0) |g|^2\,\dd s,
\end{align*}
and the assumptions $(i)$ yields $g=0$ a.e.

To argue that $(ii)$ is sufficient, we take the imaginary part of \eqref{eq:dtnid} and use the coercivity of $\D$. This yields
	\begin{align*}
0&= (\Im \alpha_1) (\D g,\Bar g)_{H^{-\sigma d}(\Gamma),H^{\sigma d}(\Gamma)}+ \int_\Gamma (\Im \alpha_0) |g|^2\,\dd s,
\end{align*}
and we conclude by proceeding almost verbatim like in the previous case. 
\end{proof}




\subsection{Approximations by finite truncations}\label{sec42}

In this subsection we illustrate how the finite-dimensional approximations of $\D$ constructed in Subsection~\ref{sec-dtn} can be employed to approximate the solutions of the transmission problem \eqref{transm00}. For that we assume that the metric tree $\cT$ is geometric from some generation $N_1$ (see Definition \ref{regularity}) and denote
\[
\D_N:=\D P_N,\quad N\in\N.
\]
The result of Corollary~\ref{cor219} and the boundedness of the embeddings
\[
H^\half(\Gamma)\hookrightarrow H^{\sigma' d}(\Gamma),\quad H^{-\sigma d}(\Gamma)\hookrightarrow H^{-\half}(\Gamma)
\]
imply that for large $N$ one has
\begin{equation}
	\label{error01}
\|\D_N-\D\|_{H^{\half}(\Gamma)\to H^{-\half}(\Gamma)}=O(p^{-\rho N}) \text{ with any } \rho\in\Big(0,\frac{1-2\sigma}{2d}\Big).
\end{equation}
Further recall that Theorem~\ref{thm221} provides an efficient way of computing $\D_N$ for large $N$ using $N$-condensations of $\cT$.

In virtue of Theorem \ref{thm31} and Corollary \ref{cor44}, for suitably chosen $\alpha_1\in \C$ and $\alpha_0\in L^{\infty}(\Gamma)$
and any $f\in L^2_\comp(\Omega)$  there is a unique solution $(u_\cT,u_\Omega)\in H^1(\cT)\times H^1_\loc(\Omega)$  of the transmission problem
\begin{equation}
	\label{transm33}
	\left\{\begin{aligned}
		\Delta_\cT u_\cT&=0\text{ on } \cT,\\
		\Delta u_\Omega&=f_\Omega \text{ on } \Omega,\\
\gamma^\Omega_0 u_\Omega&=\gamma^\cT_0 u_\cT \text{ on } \Gamma,\\
		\gamma^\Omega_1 u_\Omega-\alpha_1\gamma^\cT_1 u_\cT&=\alpha_0 \gamma^\Omega_0 u_\Omega \text{ on }\Gamma,\\
		u_\Omega(x)&=O(|x|^{2-m}) \text{ for } |x|\to\infty,\\
		u_\cT(o)&=0.		
	\end{aligned}
	\right.	
\end{equation}
To construct this solution, we proceed like in the proof of Theorem~\ref{thm221} (Step 3). Repeating the corresponding argument and using the same notation we conclude that 
\begin{align*}
	u_{\Omega}=v+v_f, \quad u_{\mathcal{T}}=u,
\end{align*}
where $u, v$ solve \eqref{uv-homog} with $g$ being the unique solution to  \eqref{eq:alphag}, i.e. 
\begin{align*}
	\dtn g-\alpha_1\D g-\alpha_0 g=-\gamma_1^{\Omega}v_f.
\end{align*}
A natural approximation to the above problem consists in replacing $\D$ by $\D_N$ (all the related quantities will be marked by index $N$). 

By combining \eqref{error01} with Theorem \ref{thm31} we conclude that for large $N$ the operator
\begin{align*}
	q&\mapsto -\dtn q+\alpha_1\D_N q+\alpha_0 q\equiv \big(-\dtn q+\alpha_1\D q+\alpha_0  q) +\alpha_1(\D_N-\D)q
\end{align*}
is an isomorphism $H^\half(\Gamma)\to H^{-\half}(\Gamma)$, and applying the Neumann series for its inverse yields that 
there is a unique solution $g_N\in H^\half(\Gamma)$ of
\[
-\dtn g_N+\alpha_1\D_N g_N+\alpha_0 g_N=h,
\]
and one has $\|g_N-g\|_{H^\half(\Gamma)}=O(p^{-\rho N})$. 

By using the continuous dependence of the solutions of \eqref{uv-homog} on $g$ we conclude that
the solutions $v^N$ and $u^N$ of
\begin{equation}
	\left\{\begin{aligned}
		\Delta_\cT u^N &=0 \text{ on } \cT,\\
		\gamma^\cT_0 u^N&=g_N \text{ on } \Gamma,\\
		u^N_\cT(o)&=0,
	\end{aligned}
	\right.	
	\qquad 
		\left\{\begin{aligned}
		\Delta v^N&=0 \text{ on } \Omega,\\
		\gamma^\Omega_0 v^N&=g_N \text{ on } \Gamma,\\
		v^N(x)&=O(|x|^{2-m}) \text{ for } |x|\to\infty,
	\end{aligned}
	\right.	
\end{equation}
satisfy
\[
\|u - u^N\|_{H^1(\cT)}=O(p^{-\rho N}),
\quad 
\|\varphi(v-v^N)\|_{H^1(\Omega)}=O(p^{-\rho N}),
\]
for any cut-off function $\varphi\in C^\infty_c(\R^m)$. Hence, the functions $u^N_{\mathcal{T}}:=u^N$ and $u^N_\Omega:=v_f+v^N$ with large $N$ provide a good approximation to the solution $(u_\cT,u_\Omega)$ in the sense that
\[
\|u^N_\cT - u^N\|_{H^1(\cT)}=O(p^{-\rho N}),
\quad 
\|\varphi(u^N_\Omega-u_\Omega)\|_{H^1(\Omega)}=O(p^{-\rho N})
\]
for any cut-off function $\varphi\in C^\infty_c(\R^m)$.






\begin{rmk}
Consider in greater details the case $\alpha_0\equiv 0$. Then the unique solvability of Problem \ref{prob41} fails if and only if
the homogeneous problem
	\begin{equation}
	\label{transm00hh-mod}
	\left\{\begin{aligned}
		\Delta_\cT w_\cT&=0 \text{ on } \cT,\\
		\Delta w_\Omega&=0 \text{ on } \Omega,\\
		\gamma^\Omega_0 w_\Omega&=\gamma^\cT_0 w_\cT \text{ on } \Gamma,\\
		\gamma^\Omega_1 w_\Omega&=\alpha_1\gamma^\cT_1 w_\cT \text{ on }\Gamma,\\
		w_\Omega(x)&=O(|x|^{2-m}) \text{ for } |x|\to\infty,\\
		w_\cT(o)&=0.
	\end{aligned}
	\right.	
\end{equation}
has non-trivial solutions. Lemma \ref{lem42} implies that the values $\alpha_1$ for which it happens are exactly those
with
\begin{equation}
	\label{kcd0}
\ker(-\dtn+\alpha_1\D)\ne\{0\}.
\end{equation}
Using the non-positivity of $\dtn$ one concludes
that $\Id-\dtn:\,H^\half(\Gamma)\to H^{-\half}(\Gamma)$ is an isomorphism.
Then the factorization
\[
-\dtn+\alpha_1\D=\Big(\Id +(\alpha_1\D-\Id)(\Id-\dtn)^{-1}\Big)(\Id-\dtn)
\]
shows that~\eqref{kcd0} rewrites as
\[\ker \Big(\Id +(\alpha_1\D-\Id)(\Id-\dtn)^{-1}\Big)\ne\{0\}.
\]
Noting that $(\Id-\dtn)^{-1}$ and $\D(\Id-\dtn)^{-1}$ can be viewed as compact operators in $H^{-\half}(\Gamma)$
we conclude (using the analytic Fredholm theorem) that the values of $\alpha_1$ for which
\eqref{transm00hh-mod} has non-trivial solutions form a discrete subset of $\C$ (i.e. without finite accumulation points).
In fact, in view of Corollary \ref{cor44} and using the complex conjugation one easily sees that all these values belong to $(-\infty,0)$.

The problem \eqref{transm00hh-mod} and the respective critical values of $\alpha_1$ represent a natural mixed-dimensional counterpart
of the so-called plasmonic eigenvalue problem in $\R^m$, see e.g. the discussion in \cite{grieser, grieser2}, and it is known that
the plasmonic eigenvalues in the Euclidean case have a finite accumulation point, contrary to what was just observed
for our problem.
\end{rmk}


