	\caption{Comparison of CAM and MCA}
	\label{table1}
	\begin{tabular}{p{5cm}p{4cm}p{4cm}}
		\hline
		& CAM & MCA\\
		\hline
		computational efficiency & high     & low    \\
		attribute                & complex  & explicit  \\
		algorithms               & less     & more    \\
