\section{Notation and preliminaires} \label{sec:notation}
\subsection{Sets and topological spaces.} If $X$ is a finite set, we write $\#X$ for the cardinality of $X$. 
All the topological spaces in this paper are assumed to be locally compact and Hausdorff.  If $X$ is a topological space such that $\dim \rm H^\ast(X,\ZZ/2)$ is finite, we define $h^\ast(X) = \dim \rm H^\ast(X,\ZZ/2)$. 

A \emph{circle} is a topological space homeomorphic to $\mathbb S^1 \coloneqq \set{z \in \CC \mid \va{z} =1}$. An \emph{interval} is a topological space homeomorphic to one of intervals $(0,1)$, $[0,1)$ or $[0,1]$ inside $\mathbb R$. If the topological space is homeomorphic to $(0,1)$ we call it \emph{open interval}. 
\subsection{Groups.} Throughout the paper, $G$ will be the finite group
$
G = \Gal(\CC/\RR) \cong \ZZ/2,
$ and $\sigma \in G$ denotes a generator. Let $\Gamma$ be a group on which $G$-acts. Recall (see e.g. \cite[Chapitre I, \S 5]{serre-galoisienne}) that the non-abelian Galois cohomology group 
$\rm  H^1(G, \Gamma)$ can be canonically identified with $\rm Z^1(G,\Gamma)/\sim $ where $\rm Z^1(G,\Gamma)\subset \Gamma$ is the set of $\gamma\in \Gamma$ such that $\gamma\sigma(\gamma)=e$ and $\sim$ is the equivalence relation $\gamma \sim \beta \gamma \sigma(\beta)^{-1}$ for $\beta \in \Gamma(\CC)$. 

If $X$ is a set on which a group $H$ acts, we write $X/H$ for the set of orbits. Unless stated otherwise, we consider $H$ acting on itself by conjugation, so that $H/H$ is the set of conjugacy classes of $H$. 

\subsection{Real varieties.} A \emph{variety} over $\RR$ (resp.\ $\CC$) will be a reduced and separated scheme of finite type over $\RR$ (resp.\ $\CC$).  A variety over $\RR$ will also be called a \emph{real variety}.  If $X$ is a real variety, we denote by  $\sigma_X\colon X(\mathbb C)\rightarrow X(\mathbb C)$  the induced anti-holomorphic involution, which we also view as an action of $G$ on $X(\CC)$. 


A \emph{curve} over $\RR$ (resp.\ $\CC$) is a variety of dimension one over $\RR$ (resp.\ $\CC$). Note that we do not assume that $X$ is proper. For a smooth curve $X$ over $\RR$, any connected component $C \subset X(\RR)$ is homeomorphic to either the circle or the open interval. 

    For $n \in \ZZ_{\geq 1}$, we let $\mu_n$ be the $\RR$-group scheme with $\mu_n(S) = \set{x \in \OO_S(S) \mid x^n = 1}$ for a scheme $S$ over $\RR$. 

\subsection{Algebraic stacks.}\label{sec:notationstack}
We indicate an algebraic stack by a calligraphic letter, such as $\ca X, \ca Y, \ca Z$. Schemes are usually indicated by roman capitals, such as $X,Y,Z$. For an algebraic stack $\ca X$, we let $\ca I_{\ca X}\to \ca X$ denote the inertia stack over $\ca X$. % and $\ca X \to M$ the coarse moduli space.

%We let $I_{\ca X} \coloneqq M_{\ca I_{\ca X}}$ denote the coarse moduli space of the inertia stack. The morphism $\ca I_{\ca X}\to \ca X$ induces a morphism $I_{\ca X} \to M$. Not needed I think

When $\ca X$ is an algebraic stack over a scheme $S$, we let $\va{\ca X(S)}$ denote the set of isomorphism classes of the groupoid $\ca X(S)$. %For an object $x \in \ca X(S)$, we let $[x] \in \va{\ca X(S)}$ denote its isomorphism class. 
For an algebraic stack $\ca X$ over $\RR$, and an object $x \in \ca X(\RR)$, let $x_\CC \in \ca X(\CC)$ denote the pull-back of $x$ along $\Spec(\CC) \to \Spec(\RR)$. 

Let $\mathcal X$ be a Deligne-Mumford stack over $\mathbb R$. Recall that the sets $\vert \mathcal X(\mathbb R)\vert$ and $\vert \mathcal X(\mathbb C)\vert$ are endowed with a natural topology. To define it, one chooses a scheme $U$ and an \'etale morphism $U\rightarrow \mathcal X$ such that 
$U(\mathbb R)\rightarrow \vert \mathcal X(\mathbb R)\vert$ and $U(\mathbb C)\rightarrow \vert \mathcal X(\mathbb C)\vert $ are surjective. Then the topologies on $\vert \mathcal X(\mathbb R)\vert $ and $\vert \mathcal X(\mathbb C)\vert $ are the induced quotient topologies. See \cite[Section 2.3]{thesis-degaayfortman} for more details. 
\subsection{Preliminaries from \cite{AdGF-grup}.} For the convenience of the reader, we recall the following results from \cite{AdGF-grup}, that will be used several times in the sequel. 
\begin{proposition} \label{prop:fiber-H1}\cite[Proposition 5.5]{AdGF-grup}. Let $\ca X$ be a separated Deligne--Mumford stack of finite type over $\RR$, with coarse moduli space $p \colon \ca X \to M$.
    \begin{enumerate}
        \item Let $f \colon \vXR \to M(\RR)$ denote the map induced by $p$. Let $x \in \ca X(\RR)$ with isomorphism class $[x] \in \va{\ca X(\RR)}$. There is a canonical bijection $f^{-1}(f([x])) = \rm  H^1(G, \Aut(x_\CC))$. 
        \item We have $\# \rm  H^1(G, \Aut(x_\CC)) = \# \rm  H^1(G, \Aut(x'_\CC))$ for each pair of objects $x, x' \in \ca X(\RR)$ whose induced objects $x_\CC, x'_\CC \in \ca X(\CC)$ are isomorphic in $\ca X(\CC)$. 
    \end{enumerate}    

\end{proposition}
\begin{proposition}\label{prop:inertia-description}\cite[Proposition 5.4]{AdGF-grup}. Let $S$ be a complex variety. Let $f\colon X \to S$ be a scheme of finite type over $S$. Let $H \to S$ be a finite group scheme over $S$, acting  on $X$ over $S$. Then
    \begin{align} 
\va{\ca I_{[X/H]}(\CC)}= \set{(x,\gamma) \in X(\CC) \times H(\CC) \mid \gamma \in \Stab_{H_{f(x)}(\CC)}(x)} /_{\sim}
\end{align}
where $(x,\gamma) \sim (gx, g\gamma g^{-1})$ for $g \in H_{f(x)}(\CC)$. 
\end{proposition}

\section{Topology of a real quotient stack}\label{sec:topologyofarealquotientstack}
In this section, we describe the topology of the real locus of the quotient stack $[X/\Gamma]$ of a real variety $X$ on which a finite $\mathbb R$-group scheme $\Gamma$ acts, and prove Theorem \ref{thm:introlemme-prefere}. We then use this description to verify the Smith--Thom inequality \eqref{align:inequality-ST-stacks} in many examples. Finally, we use Theorem \ref{thm:introlemme-prefere} to study the topology of the coarse moduli space map $\ca X \to M$ of a separated Deligne--Mumford stack $\ca X$ over $\RR$, see Corollary \ref{cor:coarse-map-closed}. 

\subsection{The real locus of a quotient stack.}\label{sec:real-locus-quotient} The goal of Section \ref{sec:real-locus-quotient} is to prove Theorem \ref{thm:introlemme-prefere}. 
\subsubsection{Group schemes over the reals and torsors.}\label{}Let $\Gamma$ be a finite group scheme over $\RR$ and let $\sigma_{\Gamma} \colon \Gamma(\CC)\rightarrow \Gamma(\CC)$
be the action of $G$ on $\Gamma(\CC)$ corresponding to $\Gamma$. 

Choose a complete set of representative $H\subset \rm Z^1(G, \Gamma) $ for $H^1(G,\Gamma)$, so that the composition $H \subset \rm Z^1(G,\Gamma) \to \rm  H^1(G,\Gamma)$ is a bijection; we choose $H$ such that $e \in H$. For each $\gamma\in H$, we define an involution
\[
\varphi^{\gamma} \colon \Gamma(\CC)\rightarrow \Gamma(\CC) \quad \quad \text{as} \quad \quad \varphi^{\gamma}(g)= \sigma(g) \cdot \gamma^{-1}.
\]
We consider the resulting $G$-set $(\Gamma(\CC), \varphi^\gamma)$. Note that left multiplication defines an action of the $G$-group $(\Gamma(\CC), \sigma_\Gamma)$ on the $G$-set $(\Gamma(\CC), \varphi^\gamma)$. In particular, if $P_\gamma$ is the $\RR$-scheme associated to $(\Gamma(\CC), \varphi^\gamma)$, 
we get an action of the $\RR$-group scheme $\Gamma$ on the $\RR$-scheme $P_\gamma$ that turns the latter into a $\Gamma$-torsor. 
Recall the following classical result. 
\begin{lemma}\label{lem:bijectiontorsor}
The following map is bijective:
	\begin{align*} \rm  H^1(G, \Gamma) = H &\rightarrow \{\text{isomorphism classes of } \Gamma \text{-torsors over } \Spec(\mathbb R)\}, \\
    \gamma&\mapsto P_\gamma.
    \end{align*}
\end{lemma}
\begin{proof}
See e.g.~\cite[Example 2, page 13]{MR1845760}. 
\end{proof}
\subsubsection{The topology of the real locus of a quotient stack.} \label{sec : twistingdefinition}
We continue with the above notation. For $\gamma \in H$, define an involution
\[
\sigma^{\gamma}_{\Gamma}\colon \Gamma(\CC)\rightarrow \Gamma(\CC) \quad \quad \text{as} \quad \quad \sigma^{\gamma}_{\Gamma}(g) \coloneqq \gamma\sigma_{\Gamma}(g)\gamma^{-1}.
\]
The pair $(\Gamma(\CC), \sigma_\Gamma^\gamma)$ corresponds to a finite group scheme $\Gamma_\gamma$ over $\RR$.
Let $X$ be a quasi-projective scheme over $\RR$ with real structure $\sigma_X \colon X(\CC) \to X(\CC)$, acted upon from the left by the finite group scheme $\Gamma$ over $\RR$. 
    For $\gamma \in H$, 
    define an involution $\sigma^\gamma_X \colon X(\CC) \to X(\CC)$ as  $\sigma^\gamma_X(x) = \gamma \cdot \sigma_X(x)$. 
    The pair $(X(\CC), \sigma_X^\gamma)$ corresponds to a quasi-projective scheme $X_\gamma$ over $\RR$. 
     Note that 
    \[
    X_\gamma(\RR) = X(\CC)^{\sigma_X^\gamma} \quad \text{and} \quad \Gamma_\gamma(\RR) = \Gamma(\CC)^{\sigma_\Gamma^\gamma} \quad \text{for each} \quad \gamma \in H.
    \]
\begin{proof}[Proof of Theorem \ref{thm:introlemme-prefere}]
Recall that, by definition, one has
$$ \va{[X/\Gamma](\RR)}=\set{\text{pairs } (P, f) \mid P \text{ a $\Gamma$-torsor and } f \text{ a $\Gamma$-equivariant morphism } P \to X }/_{\cong}$$
where $(P_1,f_1)\cong (P_2,f_2)$ if there exists an isomorphism of torsors $h\colon P_1\xrightarrow{\simeq} P_2$ such that $f_2\circ h=f_1$. 

We need to prove that there exists a canonical homeomorphism
    \[
    \va{[X/\Gamma](\RR)} \xrightarrow{\sim} \coprod_{\gamma \in H} X_\gamma(\RR)/\Gamma_\gamma(\RR).
    \]
To prove this, we first observe that the action of $\Gamma(\CC)$ on $X(\mathbb C)$ is compatible with the involutions $\sigma^{\gamma}_{X}$ and $\sigma^{\gamma}_{\Gamma}$. Indeed, for $x \in X(\CC)$ and $g \in \Gamma(\CC)$, we have:
\[
\sigma^\gamma_X(g \cdot x) = \gamma \cdot \sigma_X(g \cdot x) = \gamma\cdot \sigma_\Gamma(g) \cdot \sigma_X(x) = \gamma \cdot \sigma_\Gamma(g) \cdot \gamma^{-1} \cdot \gamma \cdot \sigma_X(x) = \sigma_\Gamma^\gamma(g) \cdot \sigma_X^\gamma(x).
\]
Therefore, we obtain an action of the $G$-group $(\Gamma(\CC), {\sigma_\Gamma^\gamma})$ on the $G$-space $(X(\CC), \sigma_X^\gamma)$. In particular, the subgroup 
\[
\Gamma_\gamma(\RR) = \Gamma(\CC)^{\sigma^\gamma_\Gamma} \subset \Gamma(\CC)
\]
of elements fixed under $\sigma^\gamma_\Gamma$ acts on the fixed space $X_\gamma(\RR) = X(\CC)^{\sigma_X^\gamma} \subset X(\CC)$. 

Fix $\gamma\in H$ and take any $x\in X_\gamma(\RR)/\Gamma_\gamma(\RR)$. Choose a $y\in X_\gamma(\mathbb R)$ that lifts $x$ and consider the $\Gamma(\CC)$-equivariant morphism
$$f_y \colon \Gamma(\CC)\rightarrow X(\mathbb C), \quad \quad g \mapsto g \cdot y.$$ This morphism is compatible with the $G$-action $\varphi^{\gamma}$ on $\Gamma(\CC)$ and with the $G$-action $\sigma_{X}$ on $X(\CC)$, hence it gives rise to a $\Gamma$-equivariant morphism 
$f_y \colon P_\gamma\rightarrow X$
of schemes over $\RR$. Define 
$$\alpha(x) \coloneqq (P_\gamma,f_y)\in \va{[X/\Gamma](\mathbb R)}.$$ 
We first show that $\alpha$ is well-defined, i.e., that $\alpha$ does not depend on the choice of the lift $y$ of $x$. If $z\in X_\gamma(\RR)$ is another lift of $x$, then there exists a $g\in  \Gamma_\gamma$ such that $y=g \cdot z$. Since $g\in \Gamma_\gamma(\RR) = \Gamma(\CC)^{\sigma_\Gamma^\gamma}$, the morphism $g\colon P_\gamma\rightarrow P_\gamma$ sending $h$ to $hg$ is  an isomorphism of torsors over $\mathbb R$, fitting into the commutative diagram
\begin{center}
	\begin{tikzcd}
P_\gamma\arrow{r}{f_y}\arrow{d}{g} & X\arrow[equal]{d}\\
	P_\gamma\arrow{r}{f_z} & X. 
			\end{tikzcd}
	\end{center} 
In particular, we have an equality of isomorphism classes $[(P_\gamma,f_y)]=[(P_\gamma,f_z)] \in \va{[X/\Gamma](\mathbb R)}$. We conclude that we get a canonical map
\begin{align}\label{align:alpha-bijection}
\alpha \colon   \va{[X/\Gamma](\RR)} \to \coprod_{\gamma \in H} X_\gamma(\RR)/ \Gamma_\gamma(\RR).
\end{align}
We observe that, by construction and Lemma \ref{lem:bijectiontorsor}, the map $\alpha$ is surjective. It is also injective since $\Aut_{\Gamma}(P_{\gamma})=\Gamma_{\gamma}(\mathbb R)$. Thus, it remains to prove that $\alpha$ is a homeomorphism. 

To see this, note that for each $\gamma \in H$, we have a natural morphism 
\begin{align}\label{align:nat-mor}
X_\gamma \to [X/\Gamma].
\end{align}
Namely, to give such a map is to give:
\begin{enumerate}
    \item[(1)] a $\Gamma \times_\RR {X_{\gamma}}$-torsor $P \to X_\gamma$ over $X_\gamma$, and
    \item[(2)] a $\Gamma \times_\RR {X_{\gamma}}$ equivariant morphism $P \to X \times_\RR X_\gamma$ of schemes over $X_\gamma$.
\end{enumerate}
As for (1), we put $P = P_\gamma \times_\RR X_\gamma$, which is a $\Gamma \times_\RR X_\gamma$-torsor by base-changing the $\Gamma$-torsor structure of $P_\gamma \to \Spec(\RR)$ along $X_\gamma \to \Spec(\RR)$. As for (2), we consider the morphism 
\begin{align} \label{align:mor-Pgamma}
P_\gamma \times_\RR X_\gamma \to X \times_\RR X_\gamma 
\end{align}
defined via Galois descent by the map
\[
\Gamma(\CC) \times X(\CC) \to X(\CC) \times X(\CC), \quad \quad (g,x) \mapsto (gx,x),
\]
which is indeed compatible with the anti-holomorphic involution $(g,x) \mapsto (\varphi^\gamma(g), \sigma_X^\gamma(x))$ on the left hand side and the anti-holomorphic involution $(x,y) \mapsto (\sigma_X(x), \sigma_X^\gamma(y))$ on the right hand side. Since the map \eqref{align:mor-Pgamma} is $\Gamma \times_\RR X_\gamma$-equivariant, it yields the desired morphism \eqref{align:nat-mor}. 

We obtain a morphism
\[
U \coloneqq \coprod_{\gamma \in H} X_\gamma \to [X/\Gamma],
\]
and, by the fact that the map $\alpha$ in \eqref{align:alpha-bijection} is a bijection (which has already been shown), the induced map
\begin{align} \label{align:induced-surjective}
U(\RR) = \coprod_{\gamma \in H} X_\gamma(\RR) \to \va{[X/\Gamma](\RR)}
\end{align}
is surjective. By definition of the real analytic topology on $\va{[X/\Gamma](\RR)}$, see Section \ref{sec:notationstack}, it follows that the topology on $\va{[X/\Gamma](\RR)}$ is the quotient topology coming from the surjection \eqref{align:induced-surjective} and the real analytic topology on $U(\RR) = \coprod_{\gamma} X_\gamma(\RR)$. As the diagram
\[
\xymatrix{
\coprod_{\gamma \in H} X_\gamma(\RR)\ar@{=}[r] \ar[d] &\coprod_{\gamma \in H} X_\gamma(\RR) \ar[d] \\
\va{[X/\Gamma](\RR)} \ar[r]^-{\alpha} & \coprod_{\gamma \in H} X_\gamma(\RR)/\Gamma_\gamma 
}
\]
commutes, and as each quotient $X_\gamma(\RR)/\Gamma_\gamma $ carries the quotient topology coming from  $X_\gamma(\RR) \to X_\gamma(\RR)/\Gamma_\gamma $, this proves that $\alpha$ is a homeomorphism as wanted.
\end{proof}

\subsection{Smith--Thom for various quotient stacks.} In this section we apply Theorem \ref{thm:introlemme-prefere} to prove the Smith--Thom inequality (\ref{align:inequality-ST-stacks}) in a number of examples.
\begin{example}
Let $\Gamma$ be any finite $\mathbb R$-group scheme. 
Take $X=\Spec(\mathbb R)$ with the trivial action of $\Gamma$. Then Theorem \ref{thm:introlemme-prefere} just says that
$\va{[X/\Gamma](\mathbb R)}$ is the disjoint union of  $\# \rm H^1(G,\Gamma)$ points, which also follows directly from the definitions and Lemma \ref{lem:bijectiontorsor}. (Note that we already verified the Smith--Thom inequality (\ref{align:inequality-ST-stacks}) for $[X/\Gamma]$ in \cite[Proposition 1.8]{AdGF-grup}.) 
\end{example}

\begin{example}\label{ex:A1modZ2}
Let $X \coloneqq \mathbb A^1_{\mathbb R}$. Let $\Gamma \coloneqq \ZZ/2$ endowed with the trivial $G$-action. We let $\Gamma$ act on $X$ via the map sending $x$ to $-x$. To compute $\mathcal X \coloneqq [\mathbb A^1_{\mathbb R}/\Gamma]$, we start by observing that $\rm  H^1(G,\Gamma)$ has two elements, $e$ (the trivial element) and $\gamma$. One computes that $X(\mathbb R)/\Gamma = \RR/\pm 1 \simeq \mathbb R_{\geq 0}$ and also $X_{\gamma}(\mathbb R)/\Gamma = i\RR/\pm 1 \simeq i\mathbb R_{\geq 0}$. Hence, by Theorem \ref{thm:introlemme-prefere}, we have
$$\vert \mathcal X(\mathbb R)\vert = \RR_{\geq 0} \coprod i\RR_{\geq 0}.$$
In conclusion, we find that $h^*(\vert \mathcal X(\mathbb R)\vert )=2$. On the other hand, by Proposition \ref{prop:inertia-description}, one has  $I_{[X/\Gamma]}(\mathbb C)\simeq \mathbb C\coprod \{0\}.$
    In particular $h^*(I_{[X/\Gamma]}(\mathbb C))=2$, we see that the Smith--Thom inequality (\ref{align:inequality-ST-stacks}) holds and it is an actual equality. 
For completeness, we also describe the natural map $f\colon \vert [\mathbb A^1_{\mathbb R}/\Gamma](\mathbb R)\vert \rightarrow (X/\Gamma)(\mathbb R)$ (see Figure \ref{fig: A1:Z2}). Identifying  $(X/\Gamma)(\mathbb C)$ with $\mathbb C$ via the map $z\mapsto z^2$, one sees that  $(X/\Gamma) (\mathbb R)=\mathbb R\subset \mathbb C$. Under this identification, $f$ induces homeomorphisms $X(\mathbb R)/\Gamma = \RR_{\geq 0} \xrightarrow{z \mapsto z^2} \mathbb R_{\geq 0}$ and $X(\mathbb R)_{\gamma}/\Gamma = i\RR_{\geq 0} \xrightarrow{z \mapsto z^2}\mathbb R_{\leq 0}$. Hence $\# f^{-1}(x)=1$ for every $x\neq 0$ and $\# f^{-1}(0)=2$, as predicted by Proposition \ref{prop:fiber-H1}.
