\begin{example}\label{ex:exampleabelianvarieties}
    Let $A$ be a real abelian variety of dimension $g$, so that $A(\mathbb R)\simeq (\mathbb S^1)^{g}\times (\ZZ/2)^k$ for some $0\leq k\leq g$ compatibly with the group structure. Consider the inversion $[-1]:A\rightarrow A$. Let $\mathcal X \coloneqq [A/(\ZZ/2)]$ where $\ZZ/2$ acts via $[-1]$, and let $\gamma$ be the unique non trivial element of $\rm  H^1(G,\Gamma)$. By Theorem \ref{thm:introlemme-prefere}, we have
    $\vert \mathcal X(\mathbb R)\vert  = A(\mathbb R)/[-1]\coprod A_{\gamma}(\mathbb R)/[-1].$
    By construction, $A_{\gamma}$ is the quadratic twist of $A$, hence $A(\mathbb R)\cong A_{\gamma}(\mathbb R)$ as topological spaces. In particular, we get
    $$\vert \mathcal X(\mathbb R)\vert \simeq (\mathbb S^1)^{g}\times (\ZZ/2)^k\coprod (\mathbb S^1)^{g}\times (\ZZ/2)^k,$$
    hence $h^*(\vert \mathcal X(\mathbb R)\vert )=2^{g+k+1}.$
    On the other hand, by Proposition \ref{prop:inertia-description}, we have $$\ca I_{\ca X}(\mathbb C)\simeq A(\mathbb C)/[-1]\coprod \coprod_{x\in A(\mathbb C)[2]}\{x\}.$$
    Since $A(\mathbb C)/[-1]\simeq A(\mathbb C)$ and $\# A(\mathbb C)[2]=2^{2g}$, we get
   $h^*(\ca I_{\ca X}(\mathbb C))=2^{2g}+2^{2g}=2^{2g+1}$. Since $k\leq g$, the inequality (\ref{align:inequality-ST-stacks})
 is verified; it is an equality if and only if $A$ is maximal. 
\end{example}
\begin{example}\label{ex:symmetricproduct}
    Let $Y$ be a real algebraic variety, let $\Gamma \coloneqq \ZZ/2$ act on $Y\times Y$ by exchanging the coordinates and let $\mathcal X \coloneqq [(Y\times Y)/\Gamma]$. If $\gamma$ is the non trivial element of $\rm  H^1(G,\Gamma)$, by Theorem \ref{thm:introlemme-prefere}, one has
    $$\vert \mathcal X(\mathbb R)\vert \simeq (Y(\mathbb R)\times Y(\mathbb R))/\Gamma \coprod (Y\times Y)_{\gamma}(\mathbb R)/\Gamma\simeq (Y(\mathbb R)\times Y(\mathbb R))/\Gamma \coprod Y(\mathbb C)/G.$$
    Observe that 
    $$\va{\mathcal X(\mathbb C)}^{G}\simeq (Y(\mathbb R)\times Y(\mathbb R))/\Gamma \coprod_{Y(\mathbb R)} Y(\mathbb C)/G,$$
    where $i:Y(\mathbb R)\hookrightarrow \va{\mathcal X(\mathbb C)}^{G}$ embeds diagonally in $Y(\mathbb R)\times Y(\mathbb R)$ and naturally in $Y(\mathbb C)/G$. 
 If $f\colon\vert \mathcal X(\mathbb R)\vert \rightarrow (Y\times Y/\Gamma)(\mathbb C)^{G}$ is the natural morphism, the exact sequence of sheaves
 $0\rightarrow \ZZ/2\rightarrow f_*\ZZ/2\rightarrow i_*\ZZ/2\rightarrow 0$  shows that 
 \begin{equation}\label{eq:STsymmetric}
          h^*(\vert \mathcal X(\mathbb R)\vert )\leq h^*(\va{\mathcal X(\mathbb C)}^G)+h^*(Y(\mathbb R)).
 \end{equation}
  On the other hand, by Proposition \ref{prop:inertia-description}, we have
  $\va{\ca I_{\ca X}(\mathbb C)}\simeq \va{\mathcal X(\mathbb C)}\coprod Y(\mathbb C),$
   so that by the classical Smith--Thom inequality for $\va{\mathcal X(\mathbb C)}\coprod Y(\mathbb C)$, we get 
        $$h^*(\va{\mathcal X(\mathbb C)}^G)+h^*(Y(\mathbb R))\leq h^*(\va{\mathcal X(\mathbb C)})+h^*(Y(\mathbb C))=h^*(\va{\ca I_{\ca X}(\mathbb C)}).$$
        Combining this with (\ref{eq:STsymmetric}), we get that the Smith--Thom inequality (\ref{align:inequality-ST-stacks}) is satisfied. 
\end{example}

\subsection{The topology of the coarse moduli space map.} The goal of this section is to use Theorem \ref{thm:introlemme-prefere} to prove the following corollary.
\begin{corollary} \label{cor:coarse-map-closed}
    Let $\ca X$ be a separated Deligne--Mumford stack of finite type over $\RR$, with coarse moduli space $\ca X \to M$. The morphism on real loci $\va{\ca X(\RR)} \to M(\RR)$ is closed. 
\end{corollary}
For this, we need the following lemma, which seems interesting in its own right, whose proof follows roughly from \cite[Lemma 2.2.3]{abramvistoli-2002} and Galois descent. 
\begin{lemma}\label{lemma:local-structure}
Let $\ca X$ be a separated Deligne--Mumford stack of finite type over $\RR$, with coarse moduli space $\ca X \to M$. Let $x \in M(\RR)$. Then there is a scheme $N$ over $\RR$ with a real point $y \in N(\RR)$, an \'etale morphism $g \colon N \to M$ with $g(y) = x$, an affine scheme $Y$ of finite type over $\RR$, and a finite group scheme $H$ over $\RR$ that acts on $Y$ over $\RR$, such that $\ca X \times_M N \cong [Y/H]$. 
\end{lemma}
\begin{proof}
Let $M^{h}$ (resp.\ $M^{sh}$) be the spectrum of the henselization (resp.\ strict henselization) of $M$ at the point $x \in M$. Let $V \to \ca X$ be a finite type \'etale morphism over $\RR$, such that $V(\CC) \to \va{\ca X(\CC)} \to M(\CC)$ has $x$ in its image, and lift $x$ to a point $z \in V(\CC)$. Let $p \in M^h$ be the closed point of $M^h$, let $u  = (z,p) \in (V \times_M M^h)(\CC)$, and let $U$ be the connected component of $V \times_M M^{h}$ that contains $u$. 

Our first goal is show that there exists a finite $\RR$-group scheme $H$ acting on $U$ over $\RR$, such that $\ca X^h = [U/H]$. Our second goal is to show that this implies that there exists an étale neighbourhood $M_i \to M$ of $x \in M$, with $M_i$ affine and of finite type over $\RR$ and equipped with a point $y \in M_i(\RR)$ mapping to $x$, as well as an affine $\RR$-scheme $U_i$ which is finite over $M_i$ and acted upon by $H$ over $\RR$, such that $\ca X \times_M M_i = [U_i/H]$. By taking $N = M_i$ and $Y = U_i$, this will prove the lemma. 

Consider the natural morphism $\pi \colon U \to M^h$. Since $U$ is connected, $M^h$ the spectrum of a henselian local ring, $\pi(u) = p$, and $\pi$ quasi-finite, it follows that $\pi$ is finite (cf.\ \cite[EGA IV, Théorème (18.5.11)]{EGA}). Define $\ca X^{sh} = \ca X \times_M M^{sh}$, $U' = U \times_{M^h}M^{sh}$ and $R' = U' \times_{\ca X^{sh}} U'$. Then $R' \to U'$ is finite étale and $U'$ is the spectrum of a strictly henselian local ring, so we have a canonical isomorphism $R' = U' \times \Gamma$, where $\Gamma$ is the set of connected components of $R'$. Moreover, as in the proof of \cite[Lemma 2.2.3]{abramvistoli-2002}, the groupoid scheme structure $[R'\rightrightarrows U']$ yield a group structure on $\Gamma$ and an action of $\Gamma$ on $U'$ such that $\ca X^{sh} = [U'/\Gamma']$. 

