\section{Smith--Thom for real stacky curves}\label{sec:STforcurves}
The goal of this section is to prove Theorem \ref{thm:introST-curves}. As previously noted, the proof is somewhat indirect: rather than comparing the topology of \( \lvert [X/\Gamma](\mathbb{R}) \rvert \) directly with that of \( I_{[X/\Gamma]}(\mathbb{C}) \), we compute \( h^*(I_{[X/\Gamma]}(\mathbb{C})) \) in Section \ref{sec:inertiacurve}, and \( h^*(\lvert [X/\Gamma](\mathbb{R}) \rvert) \) in Section \ref{sec:realpointscurve}. We then combine these computations in Section \ref{sec:proofsmiththomcurve} to establish Theorem \ref{thm:introST-curves}.


\subsection{Inertia of complex stacky curves.}\label{sec:inertiacurve}
Let $X$ be a smooth curve over $\CC$, and let $\Gamma$ be a finite abelian group which acts on $X$ over $\CC$. We let $K \subset \Gamma$ be the kernel of the homomorphism $\Gamma \to \Aut_\CC(X)$ associated to the $\Gamma$-action, and define $Q \coloneqq \Gamma/K$. This gives a short exact sequence of finite abelian groups
\[
0 \to K \to \Gamma \to Q \to 0.
\]
The restriction of the action on $X$ of $\Gamma$ to $K$ yields the trivial action of $K$ on $X$, and the induced action of $Q$ on $X$ is faithful. Let $$M \coloneqq X/Q=X/\Gamma,$$
which is the coarse moduli space of both $[X/Q]$ and $[X/\Gamma]$.
\begin{proposition} \label{prop:inertia-curves-description}
In the above notation, assume that the subgroup $K \subset \Gamma$ is contained in the center of $\Gamma$, so that for every $x\in X(\mathbb C)$ there is a natural inclusion $K\subset \Gamma_{x}/\Gamma_{x}$. Let $\Delta \subset M(\CC)$ be the branch locus of the quotient map $q \colon X(\CC) \to M$, and choose a lift $y_x \in X(\CC)$ of each $x \in \Delta$. Then there is a canonical homeomorphism
    \[
    \vert \mathcal I_{[X/\Gamma]}(\CC) \vert \simeq \left(K \times M(\CC) \right) \coprod \coprod_{x \in \Delta} \left( \Gamma_{y_x}/\Gamma_{y_x} - K \right) 
    \]
    that commutes with the natural projections onto $M(\mathbb C)$. 
\end{proposition}
\begin{proof}
We may assume that $X$ is connected. Let $I_{[X/\Gamma]}$ be the coarse moduli space of the inertia stack $\mathcal I_{[X/\Gamma]}$ of $[X/\Gamma]$. It suffices to show that the map $I_{[X/\Gamma]} \to M$ has $\# K$ disjoint sections. Indeed, $I_{[X/\Gamma]} \to M$ is finite by \cite[Lemma 5.2]{AdGF-grup}, hence for each irreducible component $Z \subset I_{[X/\Gamma]}$ of dimension one, the restriction $Z \to M$ is a finite morphism of curves, hence an isomorphism if it admits a section; moreover, over the open subset of $M$ where the stabilizer group is exactly $K$, the fibers of $I_{[X/\Gamma]} \to M$ have cardinality exactly $\# K$ by Proposition \ref{prop:inertia-description}.  


Let $S \subset X \times_\CC \Gamma$ be the stabilizer group scheme associated to the action of $\Gamma$ on $X$ over $\CC$, so that $S$ can be described pointwise as
$S = \set{(x, g) \in X \times_\CC \Gamma \mid g \cdot x = x}$. Then $\Gamma$ acts on $S$ by $\gamma \cdot (x,g) = (\gamma \cdot x, \gamma g \gamma^{-1})$ for $\gamma \in \Gamma$ and $(x,g) \in S$. Moreover, we have a canonical isomorphism
$\ca I_{[X/\Gamma]} = [S/\Gamma]$ (see e.g. \cite[Exercise 3.2.12]{notesstack}), so that, in particular, $I_{[X/\Gamma]} = S/\Gamma$.

Since $K$ is contained in the center of $\Gamma$, to any $k \in K$ one can associate the following well defined section $s_k$ of the canonical map $ I_{[X/\Gamma]} \to M$: 
\begin{align}\label{align:sec-k}
s_k \colon  M \to  I_{[X/\Gamma]} = S/\Gamma, \quad \quad [x] \mapsto [(x, k)].
\end{align}
The sections $s_k$ and $s_{k'}$ are disjoint for $k \neq k' \in K$, and so the proposition follows. 
\end{proof}


\begin{proposition} \label{prop:betti-nr-inertia-abelian}
Assume that $K \subset \Gamma$ is contained in the center of $\Gamma$.  
Then
    \begin{align} \label{eq:FXGam:1}
    \begin{split}
    h^\ast(\vert \mathcal I_{[X/\Gamma]}(\mathbb C)\vert) = \# K \cdot h^\ast(M(\CC))   + \left(\sum_{x \in \Delta}\# (\Gamma_{y_x}/\Gamma_{y_x})\right) - \# \Delta\cdot \# K.
    \end{split}
    \end{align}
    If, in addition, $\Gamma_{y_x}$ is abelian for each $x \in \Delta$, then
    %(which holds for instance when $\Gamma_{y_x}$ is abelian for each $x \in \Delta$), then 
    \begin{align}
    \label{eq:FXGam:2}
     h^\ast(\vert \mathcal I_{[X/\Gamma]}(\mathbb C)\vert) = \# K  \cdot h^\ast(\vert \mathcal I_{[X/Q]}(\mathbb C)\vert). % - \# \Delta \cdot \# K.  
    \end{align}
\end{proposition}
\begin{proof}
