\begin{example}
Consider the moduli stack $\ca A_1$ of elliptic curves over $\CC$, with coarse moduli space $\ca A_1 \to \mathsf A_1 = \bb A^1_\CC$. 
Then $h^\ast(\vert \mathcal I_{\mathcal A_1}(\CC)\vert ) = 8$. Indeed, we let $\ell \geq 3$ be a prime number and let $\ca A_1[\ell]$ be the moduli space of elliptic curves with level $\ell$ structure; it is equipped with a $\SL_2(\bb F_\ell)$-action such that $\ca A_1 = [\SL_2(\bb F_\ell) \sm \ca A_1[\ell]]$. In this case, we have $K = \langle -1 \cdot \Id \rangle \subset \SL_2(\bb F_\ell) = \Gamma$, and $\Gamma/K = \PSL_2(\bb F_\ell)$. The locus $\Delta \subset \mathsf A_1(\CC)$ of isomorphism classes of elliptic curves with automorphism group larger than $\set{\pm 1}$ consists of two points, with respective automorphism groups $\ZZ/4$ and $\ZZ/6$. Thus, Proposition \ref{prop:betti-nr-inertia-abelian} implies that $h^\ast(\vert \mathcal I_{\mathcal A_1}(\CC)\vert ) = 2 + 4 + 6 - 2 \cdot 2 = 8$. 
\end{example}
\subsection{Topology of real stacky curves.}\label{sec:realpointscurve}
In this section, we study the topology of $\va{\ca X(\RR)}$ when $\ca X$ is a stacky quotient curve over $\RR$. 
\subsubsection{Local geometry.} 
Let $\ca X$ be a separated Deligne--Mumford stack of finite type over $\RR$. Let $f \colon \va{\ca X(\RR)} \to M(\RR)$ be the map induced by the coarse moduli space $\ca X \to M$. 
%Let $X$ be a smooth curve over $\RR$. Let $H$ be a finite $\RR$-group scheme that acts on $X$ over $\RR$. Let $x\in (X/H)(\RR)$ be in the image of $f\colon [X/H](\mathbb R)\rightarrow X/H(\mathbb R)$. 
\begin{definition}\label{def:h1G}For $x \in M(\RR)$, define $h^1(G,x) = \# \rm H^1(G, \Aut(z_\CC))$ where $z \in \ca X(\RR)$ is an object whose isomorphism class $[z] \in \va{\ca X(\RR)}$ lies in the inverse image $f^{-1}(x)$ of $x$. By Proposition \ref{prop:fiber-H1}, we have $h^1(G,x) = \# f^{-1}(x)$. 
\end{definition}

For example, when $\ca X$ is the quotient $\ca X = [X/H]$ of a real variety $X$ by finite group scheme $H$ over $\RR$, and when $x \in (X/H)(\RR)$ is the image of a point $y \in X(\RR)$ under the map $X(\RR) \to (X/H)(\RR)$, then $h^1(G,x) = \#\rm H^1(G, H_y(\CC))$. This definition allows us to study the local topology of a stacky curve around a point with non-trivial stabilizer.
    \begin{lemma} \label{lem:local-groupstructure-curves}
   Let $X$ be a smooth curve over $\RR$. Let $H$ be a finite $\RR$-group scheme that acts faithfully on $X$ over $\RR$. %Assume that $H$ acts faithfully on $X$ over $\RR$.       
   \begin{enumerate}\item For each $x \in X(\RR)$, there exists an integer $n \geq 1$ such that the stabilizer group scheme $H_x$ is isomorphic to $\mu_n$. 
        \item For $x \in (X/H)(\RR)$, the number $ h^1(G,x)$ is equal to $1$ (resp.\ $2$) if $n$ is odd (resp.\ even).
        \end{enumerate}
    \end{lemma}
\begin{proof}
Let $\Gamma = H(\CC)$. Since the action of $\Gamma$ is faithful, there are only finitely many points $x \in X(\RR)$ 
 with non trivial stabilizer $\Gamma_x$. Since the statement is trivial for points with trivial stabilizer, we focus on the points $x$ with  $\Gamma_x\neq 0$. Choose an open neighbourhood $U$ of $x$, stable under the actions of $G$ and $\Gamma$, not containing any other point with non-trivial stabilizer, and $G$-equivariantly biholomorphic to an open disk centered in $x$ endowed with the $G$-action given by complex conjugation. Since the group of biholomorphisms of the disk with one fixed point is isomorphic to $\mathbb S^1$, we see that $\Gamma_x$ is isomorphic to $\ZZ/n$ for some positive integer $n$. Moreover, a generator $\gamma \in \Gamma_x$ acts as $\gamma(z)=e^{i\theta}z$ if $z$ is a local coordinate around $x$. Since the $G$-action is compatible with the action of $\Gamma$, this forces a $G$-equivariant isomorphism $\Gamma_x\simeq \mu_n$, proving the first item of the lemma. By the fact that $\# \rm H^1(G,\mu_n)$ equals $1$ if $n$ is odd and $2$ if $n$ is even, the second item follows from the first. 
\end{proof}
\subsubsection{Global geometry.} \label{subsec:fin-quot-real-curves}
We now study the possible shapes of the connected components of the real locus of a real stacky quotient curve. 
\begin{proposition} \label{prop:top-reallocus-stcurve}
    Let $X$ be a smooth curve over $\RR$. Let $H$ be a finite \'etale group scheme over $\RR$ which acts on $X$ over $\RR$. Let $C$ be a connected component of $\va{[X/H](\RR)}$. Then $C$ is homeomorphic to either an interval in $\RR$ of the form $(0,1), (0,1]$ or $[0,1]$, or to the circle $\mathbb S^1$. If $X$ is proper then only the possilibities $[0,1]$ and $\mathbb S^1$ can occur. 
\end{proposition}
We actually prove something slighlty more general in the following Lemma \ref{lem:isometries-circle}. Observe that  Proposition \ref{prop:top-reallocus-stcurve} follows from Theorem \ref{thm:introlemme-prefere} and Lemma \ref{lem:isometries-circle}. 


\begin{lemma}\label{lem:isometries-circle}
 Let $X$ be a smooth curve over $\RR$. Let $H$ be a finite \'etale group scheme over $\RR$ acting on $X$ over $\RR$. Each connected component of $X(\RR)/H(\RR)$ is homeomorphic to the interval $[0,1] \subset \RR$, the interval $(0,1]$, the interval $(0,1)$, or the circle $\mathbb S^1 \subset \RR^2$. 
 %If $X$ is proper then only the possibilities $[0,1]$ and $\mathbb S^1$ occur.
\end{lemma}
\begin{proof}
We may and do assume that $H$ acts faithfully on $X$. 

First, assume that $X$ is proper, so that $X(\mathbb R)$ is compact, and let $C$ be a connected component of $X(\RR)$ with stabilizer $\Stab_{H(\RR)}(C)$ in $H(\RR)$. 
We start by proving that 
\begin{equation}\label{eq:connectedcomponent}
C/\Stab_{H(\RR)}(C)\simeq \mathbb S^1 \quad\text{or} \quad C/\Stab_{H(\RR)}(C)\simeq [0,1].
\end{equation}
Recall that every connected Riemann surface $S$ admits a unique complete Riemann metric $g$ with constant curvature being negative (genus $\geq 2$), zero (genus zero) or positive (genus one). 
Moreover, for genus $\geq 2$ the group $\rm{Bihol}(S)$ coincides with the group $\Isom(S,g)^+$ of orientation preserving isometries of the Riemannian manifold $(S,g)$. In genus zero we have, for the subgroup $\PGL_2(\RR) \subset \PGL_2(\CC) = \rm{Bihol}(\PP^1(\CC))$, that $\PGL_2(\RR) = \rm{SO}_3(\RR)$ acts as isometries on $\PP^1(\CC) \cong S^2$. The automorphism group of any complex elliptic curve preserves its Riemannian metric. 

In particular, as $H$ acts faithfully on $X$, there are natural inclusions
$$\Stab_{H(\RR)}(C)\subset H(\mathbb R)\subset \Isom(X(\CC)) \subset \Homeo(X(\CC)),$$ 
where $\Isom(X(\CC))$ is the group of isometries with respect to the Riemannian metric of $X(\CC)$. 
We endow $C$ with the Riemannian metric induced by the embedding $C \subset X(\CC)$. Then $C$ is a compact one-dimensional Riemannian manifold, and hence isometric to a circle of some length $L$: we have $C \cong \RR/L\ZZ$ with the standard Riemannian metric. In particular, $\rm{Isom}(C) \cong \rm{O}(2)$. By the above, $\Stab_{H(\RR)}(C) \subset \rm{Isom}(X(\CC))$, and hence $\Stab_{H(\RR)}(C)  \subset \rm{Isom}(C) \cong \rm{O}(2)$. So, $\Stab_{H(\RR)}(C)$ is a finite subgroup of $\rm{O}(2) = \rm{Isom}(\mathbb S^1)$ with $\mathbb S^1 = \set{z \in \CC \mid \va{z} = 1}$, hence it is generated by multiplication by some root of unity and, possibly, the standard complex conjugation on $\mathbb S^1$. This yields \eqref{eq:connectedcomponent}. 


Let $C_1, \dotsc, C_n$ be the connected components of $X(\RR)$; each $C_i$ is homeomorphic to $\mathbb S^1$. Then $I \coloneqq \set{1, \dotsc, n}$ admits a partition $I = I_1 \sqcup I_2 \sqcup \cdots \sqcup I_k$ with $k \leq n$ such that the $I_j$ are the orbits for the induced action of $H(\RR)$ on $I$. For each $j \in \set{1, \dotsc, k}$, choose an element $i_j \in I_j$. 
%We let $I' \subset I$ be a subset with $\# (I' \cap I_j) = 1$ for each $j$. 
Let $H(\RR)_j = \rm{\Stab}_{H(\RR)}(C_{i_j})$ be the stabilizer of $C_{i_j}$ in the group $H(\RR)$. 
Then
\begin{align*}
X(\RR)/H(\RR) = \left(\coprod_{i = 1}^n C_i \right)/H(\RR) = \coprod_{j = 1}^k\left(\left(\coprod_{i \in I_j} C_i \right)/H(\RR) \right)  \cong \coprod_{j = 1}^k C_{i_j}/H(\RR)_j. 
\end{align*}
Thus, the lemma in the case where $X$ is proper follows from \eqref{eq:connectedcomponent}.

In the general case, consider the smooth projective compactification $X \hookrightarrow Y$ of $X$. The action of $H$ on $X$ extends to an action of $H$ on $Y$, and the natural map $X(\RR)/H(\RR) \to Y(\RR)/H(\RR)$ is an open embedding whose complement is a finite set (possibly empty). By what has already been proved, each connected component of $Y(\RR)/H(\RR)$ is homeomorphic to $[0,1]$ or $\mathbb S^1$. By removing the points in $\Delta(\RR) \subset Y(\RR)$, where $\Delta = Y - X$, we see that each connected component of $X(\RR)/H(\RR)$ is homeomorphic to $[0,1]$, $(0,1]$, $(0,1)$ or $\mathbb S^1$, and we are done. 
\end{proof}
\subsubsection{Map to the coarse moduli space.}\label{sec:maptocoarsmodulispace}
Finally, we study the map from a real stacky curve to its coarse moduli space. 

   Let $X$ be a smooth curve over $\RR$. Let $H$ be a finite $\RR$-group scheme that acts on $X$ over $\RR$, with associated real structure $\sigma \colon H(\CC) \to H(\CC)$. %Define $R_Q \subset \rm Z^1(G,Q)$ and 
   Let $p \colon [X/H] \to X/H = M$ be the coarse moduli space map, with induced map $f \colon \va{[X/H](\RR)} \to (X/H)(\RR) = M(\RR)$.
    \begin{lemma} \label{lem:topXR-faithful}
    Let $C \subset M(\RR)$ be a connected component. The following holds.
    \begin{enumerate}
