\subsection{Smith--Thom for real stacky curves.}\label{sec:proofsmiththomcurve} We are now ready to proceed with the:
\begin{proof}[Proof of Theorem \ref{thm:introST-curves}]
The action of $H$ on $X$ corresponds to a homomorphism
\begin{align}\label{align:action-hom}
H \to \underline{\Aut}_\RR(X),
\end{align}
where the latter denotes the automorphism group scheme of $X$ over $\RR$. Let $K \subset H$ be the kernel of \eqref{align:action-hom}, and let $Q = H/K$ be the quotient of $H$ by $K$. The canonical map $Q \to \underline{\Aut}_\RR(X)$ is a closed immersion. In particular, the group $Q(\CC)$ acts faithfully on $X(\CC)$. %Define $$\Gamma = H(\CC).$$ 
Let $[X/H] \to M$ be the coarse moduli space; we have $M(\CC) = X(\CC)/H(\CC) = X(\CC)/Q(\CC)$. 
\\
\\
\textbf{Step 1:} \emph{If $H$ is abelian, and if the Smith--Thom inequality \eqref{align:inequality-ST-stacks} holds for the quotient stack $[X/Q]$, then it also holds for $[X/H]$.}
\begin{proof}
Assume the Smith--Thom inequality \eqref{align:inequality-ST-stacks} for $[X/Q]$, and 
consider the canonical map 
\begin{align}\label{align:themapg}
g \colon \va{[X/H](\RR)} \to \va{[X/Q](\RR)}.
\end{align}
We claim that \begin{align} \label{align:we have}\# g^{-1}(p)\leq \#K(\mathbb C) \quad \quad \text{ for any 
$p \in \va{[X/Q](\RR)}$.
}
\end{align} To prove this, choose a complete set of representatives $\rm R_H \subset \rm Z^1(G,H)$ for $\rm H^1(G,H)$. Let $\rm I_Q = m(\rm{R}_H) \subset \rm Z^1(G,Q)$ be the image of $\rm R_H$ in $\rm Z^1(G,Q)$ under the natural map $m \colon \rm Z^1(G,H) \to \rm Z^1(G,Q)$, and extend $\rm I_Q$ to a complete set of representatives $\rm I_Q \subset \rm R_Q \subset \rm Z^1(G,Q)$  for $\rm H^1(G,Q)$. By construction, the map $m \colon \rm Z^1(G,H) \to \rm Z^1(G,Q)$ restricts to a map $m\colon \rm R_H \to \rm  R_Q$. By Theorem \ref{thm:introlemme-prefere}, of which we retain the notation,  we have a commutative diagram 
\[
\xymatrix{
\va{[X/H](\RR)} \ar[d]^{\wr}  \ar[r]^-g & \va{[X/Q](\RR)} \ar[d]^{\wr}\\
\coprod_{\gamma \in \rm  R_H} X_{\gamma}(\RR)/H_{\gamma}(\RR) \ar[r] & \coprod_{\mu \in \rm  R_Q} X_{\mu}(\RR)/Q_{\mu}(\RR)
}
\]
in which the vertical arrows are homeomorphisms and where the map on the bottom is induced by the map $m\colon\rm R_H \to \rm  R_Q$ and the quotient morphisms
$X_{\gamma}(\RR)/H_{\gamma}(\RR)\rightarrow X_{m(\gamma)}(\RR)/Q_{m(\gamma)}(\RR).$
To prove the claim, we may assume that $p = g(q)$ for some $q \in \va{[X/H](\RR)}$. Let $\gamma \in \rm R_H$ such that $q \in X_\gamma(\RR)/H_\gamma(\RR)$. 
The exact sequence of abelian groups
\[
0 \to K_{\gamma}(\RR) \to H_{\gamma}(\RR) \to Q_{m(\gamma)}(\RR) \to \rm  H^1(G,K_{\gamma}) \to \rm  H^1(G,H_{\gamma}) \to \rm  H^1(G,Q_{m(\gamma)}),
\]
where $K_{\gamma}\coloneqq \Ker(H_{\gamma}\rightarrow Q_{m(\gamma)})$, 
shows that $\#g^{-1}(p)\leq \#\rm  H^1(G, K_{\gamma}(\mathbb C))\leq \#K(\mathbb C)$. This proves \eqref{align:we have}.

By Proposition \ref{prop:top-reallocus-stcurve}, each connected component of $\va{[X/H](\RR)}$ or $\va{[X/Q](\RR)}$ is homeomorphic to a circle or an interval. Let $C$ be a connected component of $\va{[X/Q](\RR)}$. If $C$ is a circle, then, by \eqref{align:we have}, the inverse image $g^{-1}(C)$ consists of at most $\# K$ connected components which are circles or intervals. This implies that 
\begin{align} \label{align:CIRCLE}
h^\ast(g^{-1}(C)) \leq 2 \cdot \# K(\mathbb C) \quad \quad \text{ if $C$ is a circle.}
\end{align}
Note that every surjective continuous map from a circle to an interval has the property that the fiber above any point in the interior of the interval has cardinality at least two. To prove this, take a point $p$ not on boundary of the interval. If $p$ had only one pre-image, then, eliminating the point, we would get a surjective morphism from a connected space, a circle minus one point, to a non-connected one, an interval minus one point not on the boundary. This is not possible, so that $p$ has at least two pre-images.

Thus, by \eqref{align:we have}, if the connected component $C$ of $\va{[X/Q](\RR)}$ is an interval, then $g^{-1}(C)$ is an union of $a$ intervals and $b$ circles with $a+2b\leq \#K$. Hence, we have: 
\begin{align} \label{align:INTERVAL}
h^\ast(g^{-1}(C)) \leq \# K(\mathbb C) \quad \quad \text{ if $C$ is an interval.}
\end{align}
Therefore, we have: 
\begin{align*}
h^\ast(\va{[X/H](\RR)}) &= \sum_{C \in \pi_0(\va{[X/Q](\RR)})}h^\ast\left( g^{-1}(C) \right)\\
& = 
\sum_{C \text{ circle}}h^\ast\left( g^{-1}(C) \right)
+
\sum_{C \text{ interval}}h^\ast\left( g^{-1}(C) \right) \\
& 
\stackrel{\text{(a)}}{\leq}  
\sum_{C \text{ circle}} 2 \cdot \# K(\CC)
+
\sum_{C \text{ interval}} \# \rm   K(\CC) \\
& = 
\# K(\CC) \cdot h^\ast(\va{[X/Q](\RR)}) \\
& \stackrel{\text{(b)}}{\leq}  \# K(\CC) \cdot h^\ast(\vert \mathcal I_{[X/Q]}(\mathbb C)\vert) \\
& \stackrel{\text{(c)}}{=} h^\ast(\vert \mathcal I_{[X/H]}(\mathbb C)\vert),
\end{align*}
where (a) holds by \eqref{align:CIRCLE} and \eqref{align:INTERVAL}, (b) by the assumption that the Smith--Thom inequality \eqref{align:inequality-ST-stacks} holds for $[X/Q]$, while $(c)$ holds by Proposition \ref{prop:betti-nr-inertia-abelian}, which we can apply since $H$ is abelian. This proves Step 1.
\end{proof}

Let $\Delta \subset X(\CC)/Q$ be the branch locus of the quotient map $q \colon X(\CC) \to X(\CC)/Q$. For each $x \in \Delta$ choose an element $y_x \in X(\CC)$ such that $q(y_x) = x$. Define
\[
\Delta' \coloneqq \set{x \in \Delta \cap (X/Q)(\RR) \mid h^1(G,x) > 1},
\]
where $h^1(G,x) = \# \rm  H^1(G, H_y(\CC))$ for some $y \in q^{-1}(x)$.\\
\\
\textbf{Step 2:} \emph{The Smith--Thom inequality \eqref{align:inequality-ST-stacks} holds when the action of $H$ on $X$ over $\RR$ is faithful.}
\begin{proof}
Assume that $H$ acts faithfully on $X$. By Lemma \ref{lem:topXR-faithful}, the natural map $f \colon \va{\ca X(\RR)} \to M(\RR)$ is surjective. Let $C \subset (X/Q)(\RR)$ be a connected component which is homeomorphic to a circle.   Since the action of $H$ is faithful, by Proposition \ref{prop:topXR-faithful}, $f^{-1}(C)$ is homeomorphic to a circle if $h^1(G,x) = 1$ for each $x \in C$, and $f^{-1}(C)$ is homeomorphic to the union of $\#(C \cap \Delta')$ intervals if $\Delta' \cap C \neq \emptyset$.   
    In particular, we have:
    \[
    h^\ast\left( f^{-1}(C) \right) =\begin{cases}
2 & \text{ if } \quad C \cap \Delta'= \emptyset, 
\\
    \# ( C \cap \Delta') & \text{ if } \quad  C \cap \Delta' \neq \emptyset.  
\end{cases}
    \]
 Let $I \subset (X/Q)(\RR)$ be a connected component which is homeomorphic to the open interval $(0,1)$. 
    Since the action of $H$ is faithful, by Proposition \ref{prop:topXR-faithful}, $f^{-1}(I)$ is homeomorphic to the union of  $\# ( I \cap \Delta') + 1$ intervals. In particular, we have $h^\ast( f^{-1}(I))=\# ( I \cap \Delta') + 1$. Therefore, we have:
\begin{align*}
h^\ast(\va{\ca X(\RR)}) &= \sum_{C \in \pi_0(M(\RR)) \text{ circle}} h^\ast(f^{-1}(C)) + \sum_{I \in \pi_0(M(\RR)) \text{ interval}} h^\ast(f^{-1}(C))  \\
& \stackrel{\text{(a)}}{=}  
\sum_{C \cap \Delta' = \emptyset} 2 + \sum_{C \cap \Delta' \neq \emptyset} \#(C \cap \Delta') + \sum_{I} \left( \#(C \cap \Delta') + 1 \right) \\
& = 
\left(\sum_{C \cap \Delta' = \emptyset} 2 + \sum_{I} 1\right) +
\left(\sum_{C \cap \Delta' \neq \emptyset} \#(C \cap \Delta')  +
\sum_{I \cap \Delta' \neq \emptyset} \#(C \cap \Delta') \right)
\\
& \leq h^\ast((X/Q)(\RR)) + \sum_{x \in \Delta} 1
 \\
 & \stackrel{\text{(b)}}{\leq}  h^\ast((X/Q)(\RR)) + \sum_{x \in \Delta} \left(\# (H_{y_x}(\CC)/H_{y_x}(\CC))- 1\right) \\
 & \stackrel{\text{(c)}}{\leq} h^\ast((X/Q)(\CC)) + \sum_{x \in \Delta} \left(\# (H_{y_x}(\CC)/H_{y_x}(\CC)) - 1\right)\\
 & \stackrel{\text{(d)}}{=} h^\ast(\vert \mathcal I_{\mathcal X}(\CC)\vert).
\end{align*}
Here, (a) follows from the previous discussion, (b) from the fact that we have $2 \leq \# (H_{y_x}(\CC)/H_{y_x}(\CC))$, (c) from the classical Smith--Thom inequality (\ref{align:inequality-ST}) for $X/Q$, and, finally, (d) from Proposition \ref{prop:betti-nr-inertia-abelian}. This proves Step 2. 
\end{proof}
By combining Steps 1 and 2, Theorem \ref{thm:introST-curves} follows.  
\end{proof}



