\section{Topology of split gerbes over a real variety}\label{sec:classifyingstack}

Let \( U \) be a geometrically connected real variety with \( U(\mathbb{R}) \neq \emptyset \), and let \( H \to U \) be a finite étale group scheme, equipped with the trivial action on \( U \) over $U$. In this section, we describe how to compute the topology of \( \lvert [U/H](\mathbb{R}) \rvert \) by comparing it with \( U(\mathbb{R}) \). This analysis leads to the proof of Theorem \ref{thm:topcovering[U/H]} as well as Corollaries \ref{cor:gerbesovercurves} and \ref{cor:gerbesovercurvesconcrete}.

In Section \ref{sec:notation U/H}, we introduce notation that will be used throughout Section \ref{sec:classifyingstack}. The main work toward proving Theorem \ref{thm:topcovering[U/H]} is carried out in Section \ref{sec:topalgU/H}. In Section \ref{sec:proofU/H}, we assemble all the ingredients and prove Theorem \ref{thm:topcovering[U/H]} along with Corollaries \ref{cor:gerbesovercurves} and \ref{cor:gerbesovercurvesconcrete}.


\subsection{Notation and description of the complex inertia.}\label{sec:notation U/H}
Let \( U \) be a geometrically connected real variety with \( U(\mathbb{R}) \neq \emptyset \), and let \( H \to U \) be a finite étale group scheme, equipped with the trivial action on \( U \) over $U$. 
For $x\in U(\mathbb R)$, we let $H_x$ denote the fiber of $H \to U$ over $x$; thus $H_x$ is a finite \'etale group scheme over $\RR$. We let $\overline x \colon \Spec(\CC) \to U$ be the geometric point associated to $x$, and define $H_{\overline x} = H \times_{U}\overline x$. Thus, $H_{\overline x}$ is the constant group scheme over $\CC$ associated to the finite group $H_{x}(\mathbb C)$ which, by abuse of notation, we will also denote by $H_{\overline x}$. The finite group $H_{\overline x}$ is endowed with an action of $G$ whose associated involution we denote by  
\begin{align}\label{align:involution-G-Hx}
    \sigma_x \colon H_{\overline x}\rightarrow H_{\overline x}.
\end{align}
The natural map $U\rightarrow \mathcal X$ is a section of the coarse moduli space map $[U/H]\rightarrow U/H = U$, so that the map  $f\colon \vert [U/H](\mathbb R)\vert \rightarrow U(\mathbb R)$ is surjective. Proposition \ref{prop:inertia-description} implies the following description of the complex locus of the inertia stack $\ca I_{[U/H]}$ of $[U/H]$. 
\begin{lemma}\label{lemma:inertia:H/U}
%Let $U$ be a connected scheme of finite type over $\mathbb C$, and let $H\rightarrow U$ be a finite \'etale group scheme over $U$. Let $H$ act trivially on $U$ and consider the stack $[U/H]$. 
In the above notation, we have
$$\vert \mathcal I_{[U/H]}(\mathbb C)\vert \simeq H(\mathbb C)/H(\mathbb C) \coloneqq  \{(p,h)\in U(\mathbb C)\times H(\mathbb C) \mid h \in H_p(\CC)\}/_\sim $$
where $\sim$ denotes the equivalence relation $(p,h)\sim (p',h')$  if $p=p'$ and $h$ is conjugate to $h'$ in $H_p(\mathbb C)$.
In particular, when $H$ is abelian, one has
$\vert \mathcal I_{[U/H]}(\mathbb C)\vert \simeq H(\mathbb C).$ \hfill \qed
\end{lemma}
\subsection{Topological and algebraic fundamental groups}\label{sec:topalgU/H}
\subsubsection{Action of fundamental groups.} Fix $p\in U(\mathbb R)$, and write $C$ for the connected component of $U(\mathbb R)$ containing $p$.
The finite \'etale group scheme $H \to U$ corresponds to an action $\pi^{\et}_1(U,\overline p)$ on $H_{\overline p}$, 
$$\rho_p \colon \pi^{\et}_1(U,\overline p)\rightarrow \Aut(H_{\overline p}),$$ 
which compatible with the group structure of $H_{\overline p}$. Here, $\pi^{\et}_1(U,\overline p)$ is the \'etale fundamental group of $U$ at the geometric point $\overline p$. 

Since $U$ is geometrically connected and $G = \pi_1^{\et}(\Spec(\RR))$, the natural morphisms $U_{\mathbb C}\rightarrow U\rightarrow \Spec(\mathbb R)$ induce a short exact sequence of groups
\begin{equation}\label{eq:homotopy exact sequence}
	1\rightarrow \pi^{\et}_1(U_{\mathbb C},\overline p)\rightarrow \pi^{\et}_1(U,\overline p)\rightarrow G\rightarrow 1.
\end{equation}
Restricting $\rho_p$ to $\pi^{\et}_1(U_{\mathbb C},\overline p)$, we get an action of $\pi^{\et}_1(U_{\mathbb C},\overline p)$ on $H_{\overline p}$,
$$\rho^{\mathbb C}_{p}\colon \pi^{\et}_1(U_{\mathbb C},\overline p)\rightarrow \Aut(H_{\overline p}),$$
which corresponds to the \'etale $U_{\mathbb C}$-group scheme $H_{\mathbb C}\rightarrow U_{\mathbb C}$. 
Recall that $\pi^{\et}_1(U_{\mathbb C},\overline p)$ identifies with the profinite completion of usual fundamental group $\pi_1(U(\mathbb C),p)$ so that, in particular, there is a natural map
$\pi_1(U(\mathbb C),p)\rightarrow \pi^{\et}_1(U_{\mathbb C},\overline p)$. We denote again by $$\rho^{\mathbb C}_{p} \colon \pi_1(U(\mathbb C), p) \to \Aut(H_{\overline p})$$ the restriction of  $\rho^{\mathbb C}_{p}\colon \pi^{\et}_1(U_{\mathbb C},\overline p)\rightarrow \Aut(H_{\overline p})$ along the map $\pi_1(U(\mathbb C), p) \to \pi_1^\et(U_\CC, \overline p)$; this representation of $\pi_1(U(\mathbb C), p)$ corresponds to the topological covering  $H(\mathbb C)\rightarrow U(\mathbb C)$. 

Viewing $p$ as a morphism of schemes $p \colon \Spec(\mathbb R)\rightarrow U$, we get a morphism  $\pi_1(p)\colon  G=\pi_1^\et(\Spec(\mathbb R))\rightarrow \pi^{\et}_1(U,\overline p)$
which splits (\ref{eq:homotopy exact sequence}), and hence yields an isomorphism
\begin{equation}\label{eq:semidirect}
\pi^{\et}_1(U,\overline p)\simeq \pi^{\et}_1(U_{\mathbb C},\overline p)\rtimes G. 
\end{equation}
Hence, viewing $G$ as a subgroup $G \subset \pi_1^\et(U,\overline p)$ via the isomorphism \eqref{eq:semidirect}, this induces an action of $G = \langle \sigma \rangle $ on $\pi^{\et}_1(U_{\mathbb C},\overline p)$ by the usual formula $\sigma \cdot \alpha = \sigma \alpha \sigma^{-1}$ for $\alpha \in \pi^{\et}_1(U_{\mathbb C},\overline p)$. This action is compatible with the natural action of $G$ on $\pi_1(U(\CC), p)$ defined as follows: for $\alpha\in \pi_1(U(\mathbb C),p)$, we have $\sigma \cdot \alpha = \sigma_{U\ast}(\alpha)$.

Restricting $\rho_p$ to $G$ via $\pi_1(p)$, we get an action of $G$ on $H_{\overline p}$ which corresponds to the natural involution $\sigma_p$ on $H_{\overline p}$, see \eqref{align:involution-G-Hx}. Consider the morphism $\pi_1(C,p)\rightarrow \pi_1(U(\mathbb C),p)$ induced by the embedding $C \subset U(\CC)$, and define \begin{align}\label{align:rhop-action}\rho_p^{C} \colon \pi_1(C,p) \to \Aut(H_{\overline p})\end{align} 
as the composition of $\rho_p^{\mathbb C}$ with $\pi_1(C,p) \to \pi_1(U(\CC),p)$. 

\begin{lemma}\label{lem:actionrestriction}
The above action \eqref{align:rhop-action} of $\pi_1(C,p)$ on $H_{\overline p}$ commutes with $\sigma_p$, in the sense that $\sigma_p(\gamma \cdot x) = \gamma \cdot \sigma_p(x)$ for $\gamma \in \pi_1(C,p)$ and $x \in H_{\overline p}$. In particular, it preserves the subset $\rm Z^1(G, H_{\overline p}) = \set{x \in H_{\overline p} \mid x \cdot \sigma_p(x) = e} \subset H_{\overline p}$ and the induced action of $\pi_1(C,p)$ on $\rm Z^1(G, H_{\overline p})$ descends to an action of $\pi_1(C,p)$ on $\rm H^1(G, H_{\overline p})$. 
%to an action $\rho_p^{H^1}$ of $\pi_1(C,p)$ on $\rm  H^1(G,H_{\overline p})$. 
\end{lemma}


\proof
We need to show that for every $\alpha\in \pi_1(C,p)$, one has   
\begin{align}\label{align:equation:needtoprove}\rho_p^{C}(\alpha) \circ \sigma_p=\sigma_p\circ \rho_p^{C}(\alpha) \quad \quad \text{as maps} \quad \quad H_{\overline p} \to H_{\overline p}.\end{align}
Via the isomorphism (\ref{eq:semidirect}), we write each element $\beta \in \pi_1^{\et}(U, \overline p)$ as a pair $\beta = (\beta_1, \beta_2)$ with $\beta_1 \in \pi_1^\et(U_\CC, \overline p)$ and $\beta_2 \in G$. Denoting again by $\alpha$ the image of $\alpha$ in $\pi^{\etale}_1(U_{\mathbb C},\overline p)$, equation \eqref{align:equation:needtoprove} can be rewritten as
\begin{align} \label{align:rewrite}\rho_p(\alpha, e)^{-1} \circ \rho_p(e, \sigma) \circ  \rho_p(\alpha, e)=\rho_p(e, \sigma),\end{align}
where $e$ is the neutral element of $\pi^{\etale}_1(U_{\mathbb C},\overline p)$. 
Since $\rho_p$ is a group homomorphism, we have
$$\rho_p(\alpha, e)^{-1}\circ \rho_p(e, \sigma)\circ  \rho_p(\alpha, e)=\rho_p((\alpha^{-1},e)\cdot(e, \sigma)\cdot (\alpha, e)).
$$
The semi-direct product group structure gives 
$(\alpha^{-1},e)\cdot (e, \sigma)\cdot (\alpha, e)=(\alpha^{-1}\sigma^{-1}\alpha \sigma,\sigma).$ The image $\alpha \in \pi_1(U(\CC),p)$ of $\alpha \in \pi_1(C,p)$ satisfies $\sigma_{U\ast}(\alpha) = \sigma_U \circ \alpha = \alpha$. 
%is fixed by $\sigma_U$, in the sense that $(\sigma_U)$
For the image $\alpha \in \pi_1^\et(U_\CC, \overline p)$, one therefore has $\sigma \cdot \alpha = \sigma^{-1} \alpha \sigma = \alpha$.  
%Hence, one has $\sigma_U\alpha \sigma_U=\sigma_U(\alpha)=\alpha$.
Hence, we get 
$\rho_p(\alpha, e)^{-1}\circ \rho_p(e, \sigma)\circ \rho_p(\alpha, e)=\rho_p((\alpha^{-1},e)(e, \sigma)(\alpha, e))=\rho_p(e,\sigma),$ so that \eqref{align:rewrite} follows.
\endproof
\subsubsection{Change of base point.}\label{sec:changeofbasepoint}
In the previous section, we fixed a point \( p \in U(\mathbb{R}) \) to study the fiber \( H_p \). For concrete calculations, it will be important to understand how \( H_p \) varies when the point $p$ varies in $U(\RR)$. This is the content of the following proposition. 
\begin{proposition}\label{prop:changeofbasepoint}
Let $U$ be a geometrically connected scheme of finite type over $\RR$ with $U(\RR) \neq \emptyset$. Let $Y\rightarrow U$ be a finite \'etale cover. 
Let $p,q\in U(\mathbb R)$ and choose a topological path $\gamma_{q,p}$ from $q$ to $p$ in $U(\mathbb C)$. Define $\omega_{q,p} \coloneqq (\sigma_U \circ \gamma_{q,p}) \ast \gamma^{-1}_{q,p}\in \pi_1(U(\mathbb C),p)$ (where $\ast$ denotes the composition of paths). Then the following diagram commutes:
\[
\xymatrixcolsep{3pc}
\xymatrix{
Y_{\overline q} \ar[d]^-{(\gamma_{q,p})_\ast}\ar[r]^-{\sigma_q} & Y_{\overline q} \ar@{=}[r] & Y_{\overline q}\ar[d]^-{(\gamma_{q,p})_\ast} \\
Y_{\overline p} \ar[r]^{\sigma_p}& Y_{\overline p} \ar[r]^-{\omega_{q,p}} & Y_{\overline p}.
}
%\xymatrix{
%Y_{\overline q}\ar[d]^{\sigma_q} \ar[r]^-{(\gamma_{q,p})_\ast}& %Y_{\overline p}\ar[d]^-{\sigma_p} \\
%Y_{\overline q}\ar@{=}[d]&Y_{\overline p} \ar[d]^-{\omega_{q,p}} \\
%Y_{\overline q} \ar[r]^-%{(\gamma_{q,p})_\ast}& Y_{\overline p}.
%}
\]
Here, $\omega_{q,p}$ acts on $Y_{\overline p}$ as an element of $\pi_1(U(\mathbb C),p)$, and $(\gamma_{q,p})_\ast \colon Y_{\overline q} \xrightarrow{\sim} Y_{\overline p}$ is the canonical isomorphism induced by the path $\gamma_{q,p}$. 
\end{proposition}
\proof
For any path $\gamma_{q,p} \colon [0,1] \to U(\CC)$ from $q$ to $p$, and any point $y \in Y_{\overline q}$, we let $\widetilde{\gamma}^{y}_{q,p}$ be the unique path in $Y(\mathbb C)$ that lifts $\gamma_{q,p}$ and that satisfies $\widetilde \gamma_{q,p}^y(0) = y$. %We start by recalling how $\gamma_{q,p}$ induces an isomorphism $Y_{\overline q}\rightarrow Y_{\overline p}$. 
This yields an isomorphism
\[
(\gamma_{q,p})_\ast  \colon Y_{\overline q} \xrightarrow{\sim} Y_{\overline p}, \quad \quad y \mapsto \widetilde \gamma_{q,p}^y(1). 
\]
By construction, we have:
$$\sigma_Y((\gamma_{q,p})_\ast (y))=\sigma_Y(\widetilde{\gamma}_{q,p}^y(1))\quad \text{and} \quad \omega_{q,p} \cdot  (\gamma_{q,p})_\ast (\sigma_Y(y))=\omega_{q,p}\cdot  \widetilde{\gamma}^{\sigma_Y(y)}_{q,p}.$$ 
Observe that
$$\sigma_Y(\widetilde{\gamma}_{q,p}^y(1))=\left(\sigma_{U\ast}(\widetilde{\gamma}_{p,q}^y)\right)(1)$$
and that $\sigma_{U\ast}(\widetilde{\gamma}_{p,q}^y)$ is a path in $Y(\mathbb C)$ that lifts $\sigma_{U\ast}(\gamma_{q,p})$ and that starts at $\sigma_Y(y)$.
In other words, 
$$\sigma_Y\left((\gamma_{q,p})_\ast (y)\right)=\widetilde{\sigma_{U\ast}(\gamma_{q,p})}^{\sigma_Y(y)}(1).$$
On the other hand, by construction of the action of $\pi_1(U(\mathbb C),p)$ on $Y_{\overline p}$, one has 
$$\omega_{q,p} \cdot\left(  \widetilde{\gamma_{q,p}}^{\sigma_Y(y)}(1)\right)=\widetilde{\omega_{q,p} \ast \gamma_{q,p}}^{\sigma_Y(y)}(1).$$
But $\omega_{q,p}\ast \gamma_{q,p}=\sigma_{U\ast}(\gamma_{q,p})$ by definition of $\omega_{q,p}$, hence the proof is concluded. \endproof
