\subsection{Proof of Theorem \ref{thm:topcovering[U/H]} and its corollaries.}\label{sec:proofU/H} We are ready to proceed with the:
\begin{proof}[Proof of Theorem \ref{thm:topcovering[U/H]}]
Item \ref{itemthm:UH:2} is the content of Lemma \ref{lem:actionrestriction}, while item \ref{item:3:theoremUH} is a particular case of Proposition \ref{prop:changeofbasepoint}. 
Hence we are left to prove item \ref{itemthm:UH:1}. By \cite[Theorem 1.5]{AdGF-grup}, the morphism $f^{-1}(C)\rightarrow C$ is a topological covering. Moreover, it has fiber over $p$ isomorphic to $H^1(G,H_p(\mathbb C))$ by Proposition \ref{prop:fiber-H1}.
We are left to prove that the action of $\pi_1(C,c)$ on $f^{-1}(p)$ corresponds, under the isomorphism $f^{-1}(p)\simeq H^1(G,H_p(\mathbb C))$, to the action defined in item \ref{itemthm:UH:2}. 

For this, set 
$$Z^1_C\coloneqq\set{(u, g) \in C \times H(\mathbb C) \mid  g \in H_u(\mathbb C)\text{ and } g \sigma(g) = e}\subseteq C\times H(\mathbb C),$$
and recall from \cite[Theorem 5.9]{AdGF-grup} that one has a canonical homeomorphism $f^{-1}(C)\simeq Z^1_C/_\sim $ where $(u, g) \sim (u',g')$ if $u = u'$ and there exists $h \in H_u(\mathbb C)$ such that $g' = h g \sigma(h)^{-1}$. 
Hence, one has the following commutative diagram in which the vertical arrows are covering maps and the square on the right is cartesian:
\begin{center}
	\begin{tikzcd}
f^{-1}(C)\arrow{d}\ar[d]& Z^1_C\arrow{d}\arrow[two heads]{l}\arrow[hook]{r} & H(\mathbb C)_{\vert C}\arrow{d}\arrow[hook]{r}\arrow[phantom]{rd}{\Box} & H(\mathbb C)\arrow{d}\\
C\arrow[equal]{r}& C\arrow[equal]{r} & C\arrow[hook]{r} & U(\mathbb C).
			\end{tikzcd}
	\end{center} 
Since the upper left horizontal arrow is surjective, this concludes the proof of item \ref{itemthm:UH:1}, and thereby of Theorem \ref{thm:topcovering[U/H]}. 
\end{proof}
\begin{proof}[Proof of Corollary \ref{cor:gerbesovercurves}]
By Lemma \ref{lemma:inertia:H/U},  $\vert \mathcal I_{\mathcal X}(\mathbb C)\vert $ is homeomorphic to $H(\mathbb C)$, so we need to prove that 
\[
h^\ast(\va{[U/H](\RR)}) \leq h^\ast(H(\CC)),
\]
Consider the diagram of finite \'etale covers
\[
\xymatrix{
& H(\RR) \ar[d]^-g \\
\va{[U/H](\RR)} \ar[r]^-f &U(\RR)
}
\]
We claim that there exists a canonical embedding of sheaves \begin{align} \label{align:label-embeddingofsheaves}f_\ast\ZZ/2 \hookrightarrow g_\ast\ZZ/2. \end{align} To prove this, we may fix a connected component $C \subset U(\RR)$, and define the embedding after restricting both sheaves to $C$. Fix $p \in C$. By assumption, we have an isomorphism of $G$-groups $H_{\overline p} = A$ for a finite $G$-module $A$ with underlying abelian group $(\ZZ/2)^n$. Let $\sigma \colon A \to A$ be the involution corresponding to the $G$-module structure of $A$. 

On the one hand, the \'etale cover $g \colon H(\RR)|_C \to C$ has fiber $g^{-1}(p)= A^\sigma$ and corresponds to the action of $\pi_1(C,p)$ on $A^\sigma$ induced by the map $\pi_1(C,p) \to \pi_1(U(\CC), p)$ and the action of $\pi_1(U(\CC),p)$ on $A$ (which is, in turn, induced by the \'etale cover $H \to U$). On the other hand, the \'etale cover $f^{-1}(C) \to C$ corresponds by Theorem \ref{thm:topcovering[U/H]} to the action of $\pi_1(C,p)$ on $f^{-1}(p) = \rm H^1(G, A)$ induced by the morphism $\pi_1(C,p) \to \pi_1(U(\CC),p)$ and the action of $\pi_1(U(\CC),p)$ on $A$. 

Note that, since $A$ is an $\mathbb F_2$-vector space, one has 
$\rm H^1(G,A) = A^\sigma/(1+\sigma)A$. 
Moreover, by the above, the quotient map 
\begin{align} \label{align:map-quot}
A^\sigma \to A^\sigma/(1+\sigma)A = \rm H^1(G,A)
\end{align}
is $\pi_1(C,p)$-equivariant. Applying the contravariant functor $(\ZZ/2)^{(-)}$ to \eqref{align:map-quot} gives a $\pi_1(C,p)$-equivariant embedding
\[
(f_*\ZZ/2)_p = (\ZZ/2)^{\rm H^1(G,A)} \hookrightarrow (\ZZ/2)^{A^\sigma} = (g_*\ZZ/2)_p.
\]
Since $f_*\ZZ/2$ and $g_*\ZZ/2$ are locally constant sheaves, this yields the desired embedding of sheaves \eqref{align:label-embeddingofsheaves}. 

By taking global sections of the embedding of sheaves \eqref{align:label-embeddingofsheaves}, we obtain the inequality
\begin{equation}\label{eq:inequalitycurvesgerbes1}
\dim \rm H^0(\va{[U/H](\RR)}, \ZZ/2) \leq \dim \rm H^0(H(\RR),\ZZ/2). 
\end{equation}
Since $f$ and $g$ are finite maps, we have $f_*=f_{!}$ and $g_*=g_{!}$. Hence, we can take global sections with compact support, to get 
\begin{equation}\label{eq:inequalitycurvesgerbes2}
\dim \rm H^0_c(\va{[U/H](\RR)}, \ZZ/2) \leq \dim \rm H_c^0(H(\RR),\ZZ/2).
\end{equation}
All the connected components of $U(\mathbb R)$ are open intervals or circles; as $f\colon\vert [U/H](\mathbb R)\vert \rightarrow U(\mathbb R)$ is a finite topological covering by Theorem \ref{thm:topcovering[U/H]}, this also holds for $\vert [U/H](\mathbb R)\vert$. Hence, one has:
\begin{align*}h^\ast(\va{[U/H](\RR)})&=\dim \rm H^0(\va{[U/H](\RR)}, \ZZ/2)+\dim \rm H_c^0(\va{[U/H](\RR)}, \ZZ/2)\\
&\leq \dim \rm H^0(H(\RR), \ZZ/2)+\dim \rm H_c^0(H(\RR), \ZZ/2)=h^\ast(H(\RR)),
\end{align*}
where the inequality follows from (\ref{eq:inequalitycurvesgerbes1}) and (\ref{eq:inequalitycurvesgerbes2}). The classical Smith--Thom inequality \eqref{align:inequality-ST}
implies that $h^\ast( H(\RR)) \leq h^\ast(H(\CC))$, so that
\[
h^\ast(\va{[U/H](\RR)}) \leq h^\ast( H(\RR))) \leq h^\ast(H(\CC)),
\]
and this concludes the proof.  
\end{proof}

%\subsection{.}\label{sec:gerbecurveconcrete}
\begin{proof}[Proof of Corollary \ref{cor:gerbesovercurvesconcrete}]
Since $U$ is a smooth proper curve, by Theorem \ref{thm:topcovering[U/H]}, $\vert [U/H](\mathbb R)\vert $ is a disjoint union of circles, so that
$$h^{*}(\vert [U/H](\mathbb R)\vert )=2\cdot\#\pi_0(\va{[U/H](\mathbb R)}).$$
By Theorem \ref{thm:topcovering[U/H]}, for every connected component $C_i\in \pi_0( \vert [U/H](\mathbb R)\vert )$, the map
$f^{-1}(C_i)\rightarrow C_i$ is the \'etale cover corresponding to the action of $\pi_1(C_i,p_i)$ on $\rm H^1(G,H_{\overline p_i})$. Hence, $f^{-1}(C_i)$ has $\# \big(\rm H^1(G,H_{\overline p_i})/\pi_1(C_i,p_i)\big) $ connected components. Consequently, we get 
\begin{align}\label{align:descr-UH-R}h^{*}(\vert [U/H](\mathbb R)\vert)=\sum_{i = 1}^m 2\cdot\# \left(\frac{\rm H^1\left(G,H_{\overline p_i}\right)}{\pi_1(C_i,p_i)}\right).\end{align}
Assuming Conjecture \ref{conj:ST}, we have \begin{align} \label{align:proof-ST-UH}h^{\ast}(\vert [U/H](\mathbb R)\vert) \leq h^{*}(\vert I_{[U/H]}(\mathbb C)\vert ).
\end{align}
Therefore, to finish the proof, it suffices to show that
\begin{align}\label{eq : concretesmiththom}
\begin{split}
	h^{*}(\vert I_{[U/H]}(\mathbb C)\vert )&= 2\cdot\#\left(
    \frac{H_{\overline p}}{\pi_1(U(\mathbb C), p)}
    \right)\\&+\sum_{D\in (H_{\overline p}/\pi_1(U(\mathbb C), p))} 2\cdot\big (\# D \cdot(g-1) +1\big ),
    \end{split}
\end{align}
for indeed, by the fact that $\sum_D \# D = \# H_{\overline p}$, where the sum ranges over the orbits $D\in (H_{\overline p}/\pi_1(U(\mathbb C), p))$, equations \eqref{align:descr-UH-R}, \eqref{align:proof-ST-UH} and \eqref{eq : concretesmiththom} together imply equation \eqref{align:inequality:H/U}. 

By Lemma \ref{lemma:inertia:H/U}, the map $\vert I_{[U/H]}(\mathbb C)\vert = H(\CC) \rightarrow \vert \mathcal [U/H](\mathbb C)\vert=U(\mathbb C) $ is the \'etale cover corresponding to the action of $\pi_1(U(\mathbb C),p)$ on $H_p(\CC)$. Hence, $\vert I_{[U/H]}(\mathbb C)\vert $ has $\#(H_{\overline p}/\pi_1(U(\mathbb C),p))$ connected components, and each of these is a connected \'etale cover whose degree equals the cardinality of the orbit. Thus, (\ref{eq : concretesmiththom}) follows from the Riemann--Hurwitz formula, and the proof is finished.
\end{proof}

\section{Gerbes and the homotopy exact sequence} \label{sec:splitting}

In this section, we refine the results of Section \ref{sec:classifyingstack}, in order to be able to apply them in explicit examples. A key step is the reinterpretation of Proposition \ref{prop:changeofbasepoint} in terms of splittings of the homotopy exact sequence \eqref{eq:homotopy exact sequence}. This reinterpretation is developed in Section \ref{sec:topopathsplitting} and subsequently applied in Section \ref{sec:exenriques} to the study of certain gerbes over an Enriques surface.

We retain the notation introduced in Section \ref{sec:classifyingstack}. In particular, \( U \) denotes a geometrically connected scheme locally of finite type over \( \mathbb{R} \) with \( U(\mathbb{R}) \neq \emptyset \), and \( H \to U \) is a finite étale group scheme over \( U \).


\subsection{Topological paths and splitting of the homotopy exact sequence}\label{sec:topopathsplitting}
\subsubsection{Galois formalism.}
Write $\mathrm{Fset}$ for the category of finite sets and, for a scheme $Z$, $\rm{F}\etale(Z)$ for the category of finite \'etale covers of $Z$.
 Recall that for every $q\in U(\mathbb R)$, the group 
$\pi^{\etale}_1(U,\overline q)$ (resp.\ $\pi^{\etale}_1(U_{\mathbb C},\overline q)$) is  the automorphism of the functor
$$(-)_{\overline q}:\rm{F}\etale(U)\rightarrow \mathrm{Fset}\quad (\text{resp.\ } (-)^{\mathbb C}_{\overline q}:\rm{F}\etale(U_{\mathbb C})\rightarrow \mathrm{Fset})$$
sending $Y\rightarrow U$ (resp.\ $Y\rightarrow U_{\mathbb C}$) to the geometric fiber $Y_{\overline q}$. 
By the general formalism of Galois categories,  every isomorphism of functors
$\phi \colon (-)_{\overline q}\xrightarrow{\simeq} (-)_{\overline p}$ induces an isomorphism, well defined up to conjugation, 
$\varphi\colon \pi_1^\et(U,\overline q)\xrightarrow{\simeq} \pi_1^\et(U,\overline p),$
in such a way that the action of $G$ on $H_{\overline q}$
is induced by the action of $\pi_1^\et(U,\overline p)$ on $H_{\overline p}$ and the composition
$$G=\pi_1^\et(\Spec(\mathbb R))\xrightarrow{\pi_1(q)}\pi_1^\et(U,\overline q)\xrightarrow{\varphi}\pi_1^\et(U,\overline p).$$
\begin{remark}\label{rmk:nonuniques}
    Let us emphatize that, in general, the isomorphism $\varphi \colon \pi_1^\et(U,\overline q)\xrightarrow{\simeq}\pi_1^\et(U,\overline p)$ induced by an isomorphism of functors $\phi \colon (-)_{\overline q}\xrightarrow{\simeq} (-)_{\overline p}$ is not unique. It is only unique up to conjugation.
\end{remark}
Since both $\pi_1(p)$ and $\varphi\circ\pi_1(q)$ are splittings of the exact sequence 
$$0\rightarrow \pi_1^\et(U_{\mathbb C},\overline p)\rightarrow \pi_1^\et(U,\overline p)\rightarrow G\rightarrow 0,$$
to understand the action of $G$ on $H_{\overline q}$, one has to understand how the different splittings of this sequence are related. This is the main result of the section. 

\subsubsection{Splittings of the homotopy exact sequence.} Let $p,q \in U(\RR)$. Let $\gamma_{q,p} \colon [0,1] \to U(\CC)$ be a path from $q$ to $p$. 
The isomorphisms $(\gamma_{q,p})_\ast \colon Y_{\overline q}\simeq Y_{\overline p}$ induced by $\gamma_{q,p}$ fit together to give an isomorphism 
$\varphi^{\mathbb C}_{q,p}\colon (-)^{\mathbb C}_{\overline q}\xrightarrow{\simeq}(-)^{\mathbb C}_{\overline p}$ of fiber functors. In turn, this induces an isomorphism $\varphi^{\mathbb C}_{q,p}\colon \pi^{\et}_1(U_{\mathbb C},\overline q)\xrightarrow{\simeq }\pi^{\et}_1(U_{\mathbb C},\overline p),$ well defined up to conjugation, extending the usual isomorphism $\pi_1(U(\mathbb C),q)\rightarrow \pi_1(U(\mathbb C),p)$ defined by $\alpha\mapsto \gamma_{q,p}\alpha \gamma_{q,p}^{-1}$. Write $$\omega \coloneqq \sigma_{U\ast}(\gamma_{q,p})\ast \gamma_{q,p}^{-1} \in \pi_1(U(\CC), p),$$ 
where $\ast$ is the concatenation of paths. By abuse of notation, let $\omega \in \pi_1^\et(U_\CC, \overline p)$ be the image of $\omega$ under the natural morphism $\pi_1(U(\CC), p) \to \pi_1^\et(U_\CC, \overline p)$. 
\begin{proposition}\label{prop:splitting}
In the above notation, consider the map $f \colon G \to \pi_1^\et(U_\CC, \overline p) \rtimes G$ defined as the 
composition 
$$
f \colon G \xlongrightarrow{\pi_1(q)}
\pi_1^\et(U,\overline q) \xlongrightarrow{\varphi_{q,p}} \pi^{\et}_1(U,\overline p)\simeq \pi^{\et}_1(U_{\mathbb C},\overline p)\rtimes G,$$	
	where the isomorphism on the right is defined by the splitting of the homotopy exact sequence (\ref{eq:homotopy exact sequence}) induced by the section $\pi_1(p) \colon G \to \pi_1^\et(U,\overline p)$. Then $f(\sigma)$ is conjugate to $(\omega, \sigma)$. 
\end{proposition}
\begin{proof}
Let $Y\rightarrow U$ be a finite connected \'etale cover. 
By Proposition \ref{prop:changeofbasepoint}, 
the action of $G=\pi_1^\et(\Spec(\mathbb R))$ on 
$Y_{\overline p}$ %coincides with the action of $G$ 
induced by the action of $\pi_1^\et(U,\overline p)$ on $Y_{\overline p}$, and up to multiplying by $\omega$, the composition
$$G\xrightarrow{\pi_1(q)}\pi_1^{\etale}(U,\overline q)\xrightarrow{\varphi_{q,p}} \pi_1^{\etale}(U,\overline p)$$
identifies with the natural action of $G$ on $Y_{\overline p}$. To be precise, after identifying 
$Y_{\overline p}$ and $Y_{\overline q}$ using $\gamma_{q,p}$, one has $\sigma_q=\omega\cdot  \sigma_p$. 
The proposition follows from this. 
\end{proof}
%Hence, if we consider an isomorphism, well defined up to conjugation, 
%$$\pi_1^\et(U,\overline p)\simeq \pi_1^\et(U_{\CC}, \overline p)\rtimes G$$ induced by $\pi_1(p)$, 
%the image of section corresponding to $\pi_1(q)$ is  $(\omega,\sigma)$. 

\begin{examples}
    Let \( U = \mathbb{G}_m \) and take \( p = 1 \in \mathbb{G}_m(\mathbb{R}) \). In this case, the étale fundamental group is given by $\pi_1^{\etale}(U, \overline p) \simeq \hat{\mathbb{Z}} \rtimes G,
    $ where \( G \) acts on \( \hat{\mathbb{Z}} \) by inversion.

    \begin{enumerate}
        \item Take \( q = 2 \) and choose \( \gamma_{q,p} \) as the natural path contained in the real part connecting \( q \) to \( p \). In this case, \(\omega\) is the trivial loop, so the image of the section corresponding to \( \pi_1(q) \) is identified with \( (0,e) \).

        \item Again, take \( q = 2 \), but this time let \( \gamma_{q,p} \) be the path shown on the left in Figure \ref{fig: paths}, so that \(\omega\) is nontrivial. By construction, the class of \(\omega\) in \(\pi_1(U(\mathbb{C}), p) \simeq \mathbb{Z}\) is \( 2 \), so under this choice of \( \gamma \), the image of the section \( \pi_1(q) \) is \( (2,e) \). Although different from the previous case, we note that \( (2,e) \) is conjugate to \( (0,e) \) in \( \mathbb{Z} \rtimes G \), meaning that the conjugacy class of the section remains unchanged (see Remark \ref{rmk:nonuniques}). 

        \item Take \( q = -1 \) and choose \( \gamma_{q,p} \) as the "half-circle path" from \( -1 \) to \( 1 \), as depicted on the right in Figure \ref{fig: paths}. In this case, \( \gamma \) corresponds to the class of \( 1 \) in \( \mathbb{Z} \), so the image of the section \( \pi_1(q) \) is \( (1,e) \). Since \( (1,e) \) is not conjugate to \( (0,e) \), this section is genuinely different from the previous ones, even up to conjugation.
    \end{enumerate}
