The equations of geodesics on the manifold $M$ are
\bea
\ddot y +\omega'e^{-2\omega}|\dot {\hat x}|^2
&=& 0,
\label{214iga}\\
\frac{D^2 \hat x^i}{ds^2}
&=&2\omega'\dot y \dot {\hat x}^i,
\label{215iga}\eea
where the dot denotes the derivative with respect to the
natural parameter $s$,
%$\omega'{}=\partial_y\omega$,
\be
|\dot {\hat x}|^2=h_{ij}\dot {\hat x}^i\dot {\hat x}^j,
\ee
and
\be
\frac{D^2 \hat x^i}{ds^2}
=\ddot {\hat x}^i
+\gamma^i{}_{jk}\dot {\hat x}^j\dot {\hat x}^k,
\ee
with $\gamma^i{}_{jk}$ being the Christoffel symbols of the metric $h$.
Obviously, the curves
\be
y(s)=s, \qquad \hat x^i(s)=\hat x'^i,
\ee
are geodesics.
More generally,
these equations have the integral
\be
\dot y^2+e^{-2\omega}|\dot {\hat x}|^2
=1.
\ee
Therefore, the first equation
(\ref{214iga}) takes the form
\be
\ddot y =\omega'(\dot y^2-1),
\ee
which can be integrated to get
\be
\dot y^2=1-c^2_1 e^{2\omega}.
\ee
with an integration constant $c_1$, that is,
\be
|\dot {\hat x}|^2=c^2_1e^{4\omega}.
\ee
This gives $y(s)$
implicitly,
\be
s=\int\limits_{y'}^{y(s)}\frac{dy''}{\sqrt{1-c^2_1 e^{2\omega(y'')}}}.
\ee
In particular, in the case of cusps,
when $\omega(y)=y/a$ (for $y>0$), we get
\bea
y(s)=-a\log\left\{
c_1\cosh\left[\frac{s}{a}
+\cosh^{-1}\left(\frac{1}{c_1}e^{-y'/a}\right)
\right]
\right\}
\eea

The second equation (\ref{215iga}) becomes
\be
\frac{D^2 \hat x^i}{ds^2}
=2\omega'\sqrt{1-c^2_1 e^{2\omega}}\; \dot {\hat x}^i.
\ee
As a consequence,  eq. (\ref{215iga}) gives
\be
h_{ij}\dot{\hat x}^j\frac{D^2 \hat x^i}{ds^2}
=2c^2_1e^{4\omega}\omega'\sqrt{1-c^2_1 e^{2\omega}}.
\ee




Let $d(\hat x,\hat x')$ be the geodesic distance
between the points $\hat x$ and $\hat x'$
on the manifold $N$
and $\sigma(\hat x,\hat x')$
be the Ruse-Synge function
equal to one half of the square of
the geodesic distance,
\be
\sigma(\hat x,\hat x')=\frac{1}{2}
\left[d(\hat x,\hat x')\right]^2.
\ee
It is determined by the equation
\cite{avramidi15}
\be
\sigma=\frac{1}{2}h^{ij}
\hat\partial_i\sigma\hat\partial_j\sigma
\ee
with the conditions
\be
\sigma(\hat x,\hat x)=0,
\qquad
\hat\partial_i\sigma(\hat x,\hat x')\Big|_{\hat x=\hat x'}=0;
\ee
Here $\hat\partial_i$ denote the partial derivatives with respect to
the coordinates $\hat x^i$.
Let
$d(y,\hat x,y',\hat x')$
be the the geodesic distance on the manifold $M$
between the points $(y,\hat x)$ and $(y',\hat x')$
and
\be
\rho(y,\hat x,y',\hat x')=\frac{1}{2}[d(y,\hat x,y',\hat x')]^2,
\ee
 be the corresponding Ruse-Synge function
in the manifold $M$.
It is determined by the equation
\be
\rho=\frac{1}{2}\left\{(\partial_y\rho)^2
+e^{2\omega}h^{ij}
\hat\partial_i\rho\hat\partial_j\rho
\right\}
\ee
with the conditions
\be
\rho(y,\hat x,y,\hat x)=0,
\qquad
\partial_y\rho(y,\hat x,y',\hat x)\Big|_{y=y'}=0,
\qquad
\hat\partial_i\rho(y,\hat x,y,\hat x')\Big|_{\hat x=\hat x'}=0;
\ee
also
\be
\partial^2_y\rho(y,\hat x,y',\hat x)\Big|_{y=y'}=1,
\qquad
\hat\partial_i\partial_y
\rho(y,\hat x,y,\hat x')\Big|_{\hat x=\hat x'}=0,
\ee
\be
\hat\partial_i\hat\partial_j
\rho(y,\hat x,y,\hat x')\Big|_{\hat x=\hat x'}=
e^{-2\omega}h_{ij}.
\ee
It is easy to see that
if $\hat x=\hat x'$, then
\be
\rho(y,\hat x,y',\hat x)=\frac{1}{2}(y-y')^2,
\ee
%and if $y=y'$ then it is determined by the geodesic distance
%on the manifold $N$
%\be
%\rho(y,\hat x,y,\hat x')
%=e^{-2\omega(y)}\sigma(\hat x,\hat x').
%\ee
If the function $\omega$ is constant, then the solution
of this equation is
\be
\rho=\frac{1}{2}(y-y')^2+e^{-2\omega}\sigma(\hat x,\hat x').
\ee
In general, we parameterize the function $\rho$ by
\be
\rho=\frac{a^2}{2}\left(
\cosh^{-1}\chi\right)^2;
\ee
then the function $\chi$ satisfies the equation
\be
(\partial_y\chi)^2+e^{2\omega}h^{ij}
\hat\partial_i\chi\hat\partial_j\chi
=\frac{1}{a^2}\left(\chi^2-1\right).
\ee
Further, we let
\be
\chi=
\cosh\left(\frac{y-y'}{a}\right)
+\frac{1}{a^2}\eta(y,\hat x,y',\hat x')
\sigma(\hat x,\hat x'),
\ee
with some function
$\eta(y,\hat x,y',\hat x')$.
In the case of cusps, when
\be
\omega(y)=\frac{y}{a},
\qquad (\mbox{for } y>0),
\ee
this function can be found exactly
\be
\eta=\exp\left(-\frac{y+y'}{a}\right),
\ee
that is, the geodesic distance
on the manifold $M$ is
\be
d(y,\hat x,y',\hat x')=a
\cosh^{-1}\left[
\cosh\left(\frac{y-y'}{a}\right)
+\frac{1}{a^2}
\exp\left(-\frac{y+y'}{a}\right)
\sigma(\hat x,\hat x')
\right].
\label{267iga}
\ee



\section{Heat Kernel}
\setcounter{equation}{0}

%\ed

Let $\nabla$ be the Levi-Civita connection and
$\nabla^*$ be the formal adjoint to $\nabla$ defined using the Riemannian
metric. The scalar Laplacian
$\Delta_M: C^\infty(M)\to C^\infty(M)$ is a partial differential operator of
the form
\be
\Delta_M=-\nabla^*\nabla=g^{\mu\nu}\nabla_\mu\nabla_\nu,
\label{1ms}
\ee
which in local coordinates takes the form
\be
\Delta_M=
|g|^{-1/2}\partial_\mu |g|^{1/2}g^{\mu\nu}
\partial_\nu.
\ee
The Laplacian on the warped product manifold $M=\Sigma\times_f N$ is
\bea
\Delta_M &=&
\partial_y^2-2\alpha\omega'{}\partial_y+e^{2\omega}\Delta_N,
\eea
where $\Delta_N=h^{ij}\nabla_i\nabla_j$ is the Laplacian
on the manifold $N$.
It is easy to see that the Laplacian can be written in the form
\be
\Delta_M = -e^{\alpha\omega}Le^{-\alpha\omega },
\label{38iga}
\ee
where
\be
L=
D_0-e^{2\omega}\Delta_N,
\label{35iga}
\ee
and $D_0$ is the ordinary differential operator
on $L^2(\Sigma, dy)$
defined by
\bea
D_0 &=&
 -(\partial_y-\alpha\omega'{})
(\partial_y+\alpha\omega'{})
\nn\\
&=&-\partial^2_y{}+Q_0,
\label{39iga}
\eea
where
\be
Q_0=\alpha^2\omega'^2{}
-\alpha\omega''{}.
\label{37iga}
\ee

%\ed

The heat kernel
$U_M(t;x,x')=\exp(t\Delta_M)\delta_M(x,x')$
of the Laplacian is defined by
requiring it to
satisfy the equation
\be
\left(\partial_t-\Delta_M\right)U_M(t;x,x')=0,
\ee
with the initial condition
\be
U_M(0;x,x')=\delta_M(x,x'),
\ee
where
\bea
\delta_M(x,x') &=& |g|^{-1/4}(x)|g|^{-1/4}(x')\delta(x-x')
\nn\\
 &=&
\exp\left\{\alpha\left[\omega(y)+\omega(y')\right]\right\}
\delta(y{}-y{}')
\delta_N(\hat x,\hat x'),
\label{43iga}
\eea
is the covariant delta function on the manifold $M$.


%\ed

%=====================================

By using the intertwining property (\ref{38iga})
the heat semigroup of the Laplacian,
$\exp(t\Delta_M): C^\infty(M)\to C^\infty(M)$,
takes the form
\be
\exp(t\Delta_M) = e^{\alpha\omega}
\exp\left(-tL\right)
e^{-\alpha\omega}.
\label{47iga}
\ee
Therefore, by acting on the delta function (\ref{43iga})
we obtain the heat kernel on the manifold $M$
in terms of the heat kernel of the operator $L$
\be
U_M(t;y,\hat x,y',\hat x')
=
\exp\left\{\alpha\left[\omega(y{})+\omega(y{}')\right]\right\}
U(t;y,\hat x,y',\hat x'),
\ee
where the heat kernel $U(t;y,\hat x,y',\hat x')$
of the operator $L$ is defined by the equation
\be
\left(\partial_t+L\right)U(t;y,\hat x,y',\hat x')=0,
\ee
with the initial condition
\be
U(0;y,\hat x,y',\hat x')=\delta(y-y')\delta_N(\hat x,\hat x').
\ee

%===========================================================

Let $\{\mu_k\}_{k=0}^\infty$ be the spectrum
of the negative Laplacian $-\Delta_N$
on the manifold $N$ and $T_k$ be the corresponding
orthogonal spectral projections.
The multiplicities of the eigenvalues $\mu_k$ are
\be
d_k=\dim\Ker(\Delta_N+\mu_k).
\ee
Since
the manifold $N$ is closed,
the first eigenvalue (which is simple with
multiplicity $d_0=1$) is zero,
\be
\mu_0=0,
\ee
with the constant eigenfunction
\be
\varphi_0(\hat x)=[\vol(N)]^{-1/2}.
\ee

For example, in the case of the sphere $S^{n-1}$ the spectrum
of the negative Laplacian is \cite{avramidi23}
\be
\mu_k(S^{n-1})=\frac{1}{a^2}k(k+n-2),
\qquad
k=0,1,2,\dots,
\ee
with the multiplicities $d_0=1$ and
\be
d_k=(2k+n-2)\frac{(k+n-3)!}{(n-2)!k!},
\qquad
k=1,2,\dots.
\ee
In the case of the torus $T^{n-1}$ the eigenvalues are
\be
\mu_{k_1\dots k_{n-1}}(T^{n-1})=\sum_{j=1}^{n-1}\frac{k_j^2}{a_j^2},
\ee
where $a_j$ are the radii of the circles and $k_j\in\ZZ$.


%=====================================================
%\section{Heat Kernel}
%\setcounter{equation}{0}

%\ed

Let $U_N(t;\hat x,\hat x')=\exp(t\Delta_N)\delta_N(\hat x,\hat x')$
be the heat kernel of the
Laplacian on the manifold $N$
satisfying the equation
\be
\left(\partial_t-\Delta_N\right)U_N(t;\hat x,\hat x')=0,
\ee
with the initial condition
\be
U_N(0;\hat x,\hat x')=\delta_N(\hat x,\hat x'),
\ee
where
\be
\delta_N(\hat x,\hat x')=|h|^{-1/4}(\hat x)|h|^{-1/4}(\hat x')\delta(\hat x-\hat x')
\ee
is the covariant delta function on the
manifold $N$.

Let $P_N$ be the projection onto the orthogonal complement
of the kernel of the Laplacian and $\tilde\Delta_N$ be the reduced
Laplacian defined by
\be
\tilde\Delta_N=P_N\Delta_N P_N.
\ee
The spectral resolution of the heat kernel on the manifold $N$
is
\be
U_N(t;\hat x,\hat x')
=\frac{1}{\vol(N)}
+\tilde U_N(t;\hat x,\hat x'),
\ee
where
\be
\tilde U_N(t;\hat x,\hat x')
=\sum_{k=1}^\infty
 e^{-t\mu_k}
T_k(\hat x,\hat x')
\ee
is the heat kernel of the positive operator
$
-\tilde\Delta_N.
$
%(recall that $P_N$ is the orthogonal projection
%on the orthogonal complement of the kernel of the
%operator $\Delta_N$).

%======================================
%===================================

%\ed

We use the spectral resolution of the Laplacian on the manifold $N$
to separate variables and to get the heat kernel of the operator $L$
\be
U(t;y,\hat x,y',\hat x')=\sum_{k=0}^\infty
U_k(t;y,y')T_k(\hat x,\hat x'),
\ee
where the functions $U_k(t;y,y')=
\exp(-tD_k)\delta(y-y')$ are the heat kernels
of the
ordinary differential operators
\be
D_k=D_0+\mu_ke^{2\omega},
\label{426iga}
\ee
satisfying the equations
\be
\left(\partial_t+D_k\right)U_k(t;y,y')=0
\ee
with the initial conditions
\be
U_k(0;y,y')=\delta(y-y').
\ee

We will find it useful to
separate the zero mode of the operator $\Delta_N$.
By using the projection $T_0(\hat x,\hat x')=[\vol(N)]^{-1}$
to the kernel of the operator $\Delta_N$ we get
\be
U(t;y,\hat x,y',\hat x')=\frac{1}{\vol(N)}U_0(t;y,y')
+\tilde U(t;y,\hat x,y',\hat x'),
\label{329iga}
\ee
where the function $U_0(t;y,y')=\exp(-tD_0)$
is the heat kernel of the operator $D_0$ and
\bea
\tilde U(t;y,\hat x,y',\hat x')
&=&\sum_{k=1}^\infty
U_k(t;y,y')T_k(\hat x,\hat x').
\eea
Notice that
\be
\tilde U(t;y,\hat x,y',\hat x')
=\exp(-t\tilde L)\delta(y-y')\delta_N(\hat x,\hat x')
\label{331iga}
\ee
is the heat kernel of the operator
\be
\tilde L = D_0 -e^{2\omega}\tilde\Delta_N.
\label{332iga}
\ee




%============================================================

Let
\be
\Phi(t,\lambda{};y,y'{})
=\exp\left[-t\left(D_0+\lambda e^{2\omega}\right)\right]
\delta(y{}-y')
\label{418iga}
\ee
be the analytic continuation of the heat kernel of the
operator $\left(D_0+\lambda e^{2\omega}\right)$
defined for $\Real \lambda\ge 0$ by
\be
\left(\partial_t
+D_0+\lambda e^{2\omega}\right)\Phi(t,\lambda;y,y')=0,
\ee
with the initial condition
\be
\Phi(0,\lambda{};y,y')
=\delta(y-y').
\ee
This function is analytic function of $\lambda$ with a cut along
the negative real axis.
Then, of course,
\be
U_k(t;y,y')=\Phi(t,\mu_k;y,y').
\label{336iga}
\ee
Therefore,
we can use the Cauchy formula to represent the heat kernel
in terms of the resolvent $\tilde G_N(\lambda)=(-\tilde\Delta_N-\lambda)^{-1}$
of the positive operator $\tilde\Delta_N$,
\be
\tilde U(t;y,\hat x,y',\hat x')
=\int\limits_{c-i\infty}^{c+i\infty}
\frac{d\lambda}{2\pi i}\; \tilde G_N(\lambda;\hat x,\hat x')
\Phi(t,\lambda;y,y'),
\label{337iga}
\ee
where $c$ is a non-negative constant less than $\mu_1$, that is,
$
0\le c<\mu_1.
$
Further, we can represent this resolvent in terms of the heat kernel
of the operator $\tilde\Delta_N$, for $0\le \Real \lambda<\mu_1$,
\be
\tilde G_N(\lambda;\hat x,\hat x')
=\int\limits_0^\infty d\tau\; e^{\tau\lambda{}}
\tilde U_N(\tau;\hat x,\hat x').
\ee
Thus, we obtain the heat kernel
\be
\tilde U(t;y,\hat x,y',\hat x')
=
\int\limits_0^\infty d\tau\;
\tilde U_N(\tau;\hat x,\hat x')
\int\limits_{c-i\infty}^{c+i\infty}
\frac{d\lambda}{2\pi i}\;
e^{\tau\lambda{}}
\Phi(t,\lambda;y,y').
\label{339iga}
\ee
This enables one to compute the
heat trace
\be
\Tr\exp(-t\tilde L)
=
\int\limits_0^\infty d\tau\;
V(t,\tau)\Tr\exp(\tau\tilde\Delta_N),
\ee
where
\be
V(t,\tau)=
\int\limits_{c-i\infty}^{c+i\infty}
\frac{d\lambda}{2\pi i}\;
e^{\tau\lambda}
\Tr\exp\left[-t\left(
D_0+\lambda e^{2\omega}\right)\right].
\label{339igax}
\ee


%================================

An alternative method consists of employing the
wave kernel of the operator $\tilde\Delta_N$,
\be
W(p;\hat x,\hat x')
=\exp\left(ip\sqrt{-\tilde \Delta_N}\right)
\delta_N(\hat x,\hat x').
\ee
We use the Fourier transform
\bea
f(A) &=&
\int\limits_{-\infty}^\infty
dp\;
\exp\left(ip\sqrt{A}\right)
f(-\partial_p^2)
\delta(p),
\eea
to obtain the heat semigroup of the operator
$\tilde L=D_0-e^{2\omega}\tilde\Delta_N$,
\bea
\exp(-t\tilde L)
%&=&
%\int_{-\infty}^\infty dp \delta(p)\;
%\exp(-tK)
%\exp\left(ip\sqrt{-\Delta_N}\right)
%\nonumber
%\\
&=&
\int\limits_{-\infty}^\infty dp
\exp\left(ip\sqrt{-\tilde\Delta_N}\right)
\exp\left[-t\left(D_0-e^{2\omega}\partial_p^2\right)
\right]
\delta(p).
\eea
This gives
the heat kernel of the operator $\tilde L$
in the form
\bea
\tilde U(t;y,\hat x,y',\hat x') &=&
\int\limits_{-\infty}^\infty dp\;
W(p;\hat x,\hat x')
K(t;y,p,y',0),
\eea
where
\be
K(t; y,p, y', p')=
\exp\left[-t\left(D_0-e^{2\omega}\partial_p^2\right)
\right]
\delta(y-y')
\delta(p-p').
\ee



In the case of cusps,
for large $y>0$, when the function $\omega$ is given by
$\omega(y)\sim y/a$,
the operator $-D_0+e^{2\omega}\partial_p^2$
approaches the
Laplacian on the hyperbolic plane
$H^2$ (with a constant potential)
with a well known
heat kernel \cite{avramidi15},
\bea
K(t; y,p, y', p')
&=&\frac{a}{2(2\pi t)^{3/2}}
\exp\left[-\left(\frac{1}{4}+\alpha^2\right)
\frac{t}{a^2}
%-\frac{(y-y')}{2a}
\right]
\nn\\
&&\hspace{-2cm}\times
\int\limits_{d/a}^\infty
ds\frac{s}{\sqrt{\cosh s-\cosh(d/a)}}
\exp\left(-\frac{s^2a^2}{4t}\right),
\eea
where $d$ is the geodesic distance given by
a formula similar to (\ref{267iga}),
\be
d(y,p,y',p')=a
\cosh^{-1}\left[
\cosh\left(\frac{y-y'}{a}\right)
+\frac{1}{a^2}
\exp\left(-\frac{y+y'}{a}\right)
(p-p')^2
\right].
\label{267igax}
\ee
The asymptotics of this heat kernel as
$t\to 0$ is
\be
K(t; y, p, y', p')
\sim \frac{1}{4\pi t}
\left(\frac{d}{a\sinh (d/a)}\right)^{1/2}
\exp\left(-\frac{d^2}{4t}\right).
\ee
Note that
\be
d(y,p,y,0)=
\cosh^{-1}\left[
1+\exp\left(-2\frac{y}{a}\right)
\frac{p^2}{a^2}
\right].
\label{267igay}
\ee

To compute the trace we need to regularize the wave
kernel as follows,
\bea
\Tr\exp(-t\tilde L) &=&
\int\limits_{0}^\infty dp\;
\int\limits_\RR dy
K(t;y,p,y,0)
\\
&&\times
\left\{
\Tr\exp\left(ie^{i\varepsilon}p\sqrt{-\tilde\Delta_N}
\right)
+\Tr\exp\left(-ie^{-i\varepsilon}p\sqrt{-\tilde\Delta_N}
\right)
\right\}.
\nn\eea

