\section{Heat Trace on Compact Manifolds}
\setcounter{equation}{0}


The Laplacian $\Delta_N$ on the manifold $N$
has a discrete non-negative real spectrum
with finite multiplicities bounded from below
\cite{gilkey95}.
The spectrum is analyzed by
studying the heat trace
%\cite{gilkey95}
%(here each eigenvalue is counted with its multiplicity)
\be
\Tr\exp(t\Delta_N)=\dim\Ker\Delta_N
+\Tr\exp(t\tilde\Delta_N).
\ee
It is well known that it has the
asymptotic expansion as $t\to 0$,
\cite{gilkey95},
\be
\Tr\exp(t\Delta_N)
%\sum_{\lambda_k>0}^\infty e^{-\lambda_k(N) t}
\sim (4\pi )^{-\alpha}\sum_{k=0}^\infty \frac{t^{k-\alpha}}{k!}A_k(N),
\label{11iga}
\ee
where
$A_k(N)$ are the spectral invariants called the global
heat kernel coefficients.
These coefficients play an important role in spectral geometry and
quantum field theory. They have been computed explicitly
up to $A_4$ \cite{gilkey95,avramidi91,avramidi00}.
Let $\varkappa$ be the largest positive integer
smaller than $\alpha=\frac{n-1}{2}$,
\be
\varkappa=\left[\frac{n}{2}\right]-1;
\ee
that is, if $n$ is odd then $\varkappa=\frac{n-3}{2}=\alpha-1$, and if $n$ is even
then $\varkappa=\frac{n-2}{2}=\alpha-\frac{1}{2}$.
Then
\be
\Tr\exp(t\Delta_N) = \Theta_{N,-}(t)
%+\dim\Ker\Delta_N
+\Theta_{N,+}(t),
\label{16igaxx}
\ee
where the function
\be
\Theta_{N,-}(t) = (4\pi)^{-\alpha}\sum_{k=0}^{\varkappa}
 \frac{1}{k!}A_k(N)t^{k-\alpha},
\label{122iga}
\ee
contains
only negative powers of $t$ and the function
\be
\Theta_{N,+}(t) \sim
(4\pi)^{-\alpha}\sum_{k=\varkappa+1}^{\infty}
\frac{1}{k!}A_k(N)t^{k-\alpha{}},
\ee
contains only non-negative powers of $t$.

The zeta function is defined by a modified
Mellin transform of the heat trace,
\bea
\zeta_N(s)
=\Tr(-\tilde\Delta_N)^{-s}
%=\sum_{\lambda_k>0} \left[\lambda_k(N)\right]^{-s}
%\nn\\
&=&\frac{1}{\Gamma(s)}\int\limits_0^\infty dt\;
t^{s-1}\Tr\exp(t\tilde\Delta_N).
\label{12iga}
\eea
This function is analytic for
$\Real s>\alpha{}$ and has a meromorphic analytic continuation.
The analytic structure of the zeta function is exhibited by
the representation \cite{avramidi91,avramidi00,avramidi10},
\be
\zeta_N(s)=\frac{\Gamma(s-\alpha{})}{\Gamma(s)}Z_N(s),
\label{18iga}
\ee
where $Z_N(s)$ is an entire function.
%\section{Heat Trace $\Tr\exp(t\Delta_N)$}
%\setcounter{equation}{0}
The entire function  $Z_N(s)$ is expressed in terms of the heat trace by
\be
Z_N(s)=\frac{1}{\Gamma\left(s-\alpha{}+k\right)}
\int\limits_0^\infty dt\; t^{s-1-\alpha{}+k}
(-\partial_t)^k\left[t^{\alpha{}}\Tr\exp(t\tilde\Delta_N)\right],
\ee
where $k$ is a sufficiently large positive integer, $k>\alpha{}$.

It is easy to see that  the values at the
points $s=\alpha{}-k$, $k=0,1,2,\dots$, are
\be
Z_N\left(\alpha{}-k\right)=(-1)^{k}(4\pi)^{-\alpha{}}A_{k}(N),
\label{110iga}
\ee
where $A_k(N)$ are the heat trace coefficients of the manifold $N$
defined by (\ref{11iga}).
Therefore, if $n$ is even (that is, $\alpha$ is half-integer) then the zeta function
has an infinite number of
simple poles at the half-integer points
$s_k=\alpha{}-k$, $k=0,1,2,\dots,$ with the residues
\be
\Res\zeta_N\left(\alpha{}-k\right)
=\frac{1}{k!\Gamma\left(\alpha{}-k\right)}
(4\pi)^{-\alpha{}}A_{k}(N).
\ee
If $n$ is odd (that is, $\alpha$ is an integer),
then the zeta function has only a finite number
of these poles at the integer points
$1,2, \dots, \alpha-1,
\alpha{}$.

In any case, the zeta function is analytic at $s=0$.
The value at $s=0$ gives the regularized number of modes;
it is easy to see that
\be
\zeta_N(0)=
\left\{
\begin{array}{ll}
0, & \mbox{ for even } n,
\\[10pt]
\displaystyle
\frac{(4\pi)^{-\alpha{}}}{\Gamma\left(\alpha{}+1\right)}A_{\alpha{}}(N),
& \mbox{ for odd } n.
\end{array}
\right.
\ee

The value of the derivative at $s=0$ defines the regularized
determinant of the operator
\be
\Det(-\Delta_N)=\exp\left\{-\zeta'_N(0)\right\}.
\ee
It is given by the integral:
for even $n=2j$,
\be
\zeta'_N(0)=\frac{\sqrt{\pi}}{\Gamma(j+\frac{1}{2})}
\int\limits_0^\infty dt\; t^{-\frac{1}{2}}
(-\partial_t)^{j}\left[t^{j-\frac{1}{2}}\Tr\exp(t\tilde\Delta_N)\right],
\ee
and
for odd $n=2j-1$,
\bea
\zeta'_N(0) &=& \frac{(-1)^{j-1}}{(j-1)!}\int\limits_0^\infty dt\;
\left\{
\log t
+\psi(j)
\right\}
(-\partial_t)^j\left[t^{j-1}\Tr\exp(t\tilde\Delta_N)\right],
\eea
where $\psi(z)=\Gamma'(z)/\Gamma(z)$ is the logarithmic derivative
of the gamma function.

The heat trace can be obtained from the zeta function by the inverse Mellin
transform
\be
\Tr\exp(t\tilde\Delta_N)=
%\dim\Ker\Delta_N+
\int\limits_{\sigma-i\infty}^{\sigma+i\infty}
\frac{ds}{2\pi i}\;t^{-s}\;
\Gamma\left(s-\alpha\right)Z_N\left(s\right),
\label{16iga}
\ee
where $\sigma$ is a positive constant,
$\sigma> \alpha$.
More generally,
\bea
(-\partial_t)^k\left[
t^\alpha\Tr\exp(t\tilde\Delta_N)
\right]
=
\int\limits_{\tilde\sigma-i\infty}^{\tilde\sigma+i\infty}
\frac{ds}{2\pi i}\;t^{-s+\alpha-k}\;
\Gamma\left(s-\alpha+k\right)
Z_N\left(s\right),
\eea
where $\tilde\sigma>\alpha-k$.


Notice that this formula can also be used for a complex
variable $t$ with a cut along the negative real axis.
By moving the contour of integration to the left and
using eq. (\ref{110iga}) we obtain a
more general formula
\be
\Tr\exp(t\tilde\Delta_N) = \Theta_{N,-}(t)
%+\dim\Ker\Delta_N
+\Theta_{N,+}(t),
\label{16igaxy}
\ee
where the function $\Theta_{N,-}(t)$ is defined in (\ref{122iga})
and
\bea
\Theta_{N,+}(t) &=&
\int\limits_{\sigma_\varkappa-i\infty}^{\sigma_\varkappa+i\infty}
\frac{ds}{2\pi i}\;t^{-s}\;
\Gamma\left(s-\alpha\right)Z_N\left(s\right),
\eea
with  $\alpha-\varkappa-1<\sigma_\varkappa<\alpha-\varkappa$.
%(recall that $m=[n/2]-1$).
Similarly, we have
\bea
(-\partial_t)^k\left[
t^\alpha\Theta_{N,+}(t)
\right]
=
\int\limits_{\tilde\sigma-i\infty}^{\tilde\sigma+i\infty}
\frac{ds}{2\pi i}\;t^{-s+\alpha-k}\;
\Gamma\left(s-\alpha+k\right)
Z_N\left(s\right),
\eea
where $\tilde\sigma>\alpha-k$.


By taking the derivative, this equation also gives the traces
for any positive integer $j>0$,
\bea
\Tr\left\{(-\Delta_N)^j\exp(t\Delta_N)\right\}
& =&
(4\pi)^{-\alpha{}}\sum_{k=0}^{\varkappa} \frac{1}{k!}
\frac{\Gamma\left(\alpha{}+j-k\right)}
{\Gamma\left(\alpha{}-k\right)}
A_k(N)t^{k-j-\alpha{}}
\nn
%\label{16igax}
\\
&&
\hspace{-3cm}
+\int\limits_{\sigma_\varkappa-i\infty}^{\sigma_\varkappa+i\infty}
\frac{ds}{2\pi i}\;t^{-s-j}\;
\frac{\Gamma\left(s+j\right)}
{\Gamma\left(s\right)}
\Gamma\left(s-\alpha\right)Z_N\left(s\right),
%\nn
\label{16igax}
\eea







%===============================

Note that we can also define the trace
\be
\Tr(-z\tilde\Delta_N)^{-s}
=z^{-s}\zeta_N(s)
\ee
for a complex variable $z$ with a cut along the negative real axis.
In particular,
\be
\Tr(i\tilde\Delta_N)^{-s}=e^{-is\pi/2}\zeta_N(s).
\ee
More generally, for $\Real \lambda<0$ and $\Real s> \alpha{} $
we can define the trace
\bea
\Tr(-z\Delta_N-\lambda)^{-s}
&=&
(-\lambda)^{-s}\dim\Ker\Delta_N
%\nn
\\
&&
+\frac{(-\lambda)^{-s}}{\Gamma(s)}\int\limits_{\sigma-i\infty}^{\sigma+i\infty}
\frac{dw}{2\pi i}
\left(\frac{-\lambda}{z}\right)^{w}
\Gamma(w-\alpha)\Gamma(s-w)Z_N\left(w\right),
\nn\eea
where $\alpha<\sigma<\Real s$.


\section{One Dimensional Heat Kernel}
\setcounter{equation}{0}

Let $D$ be a Schr\"odinger operator acting on smooth functions
on $\RR$ of the form
\be
D=-\partial_y^2+Q(y),
\ee
where the potential $Q(y)$ is an even function.
Let $U(t;y,y')$ be the heat kernel of the operator $D$
 satisfying
the equation
\be
\left(\partial_t-\partial_y^2
+Q(y)\right)
 U(t;y,y')=0
\ee
with the initial condition
\be
U(0;y,y')=\delta(y-y').
\ee

The asymptotics of the heat kernel diagonal
$U(t;y,y)$ as $t\to 0$
has the following form
\cite{avramidi00b}
\be
U(t;y,y)\sim
(4\pi)^{-1/2}\sum_{k=0}^\infty
\frac{t^{k-1/2}}{k!}c_k(y),
\label{56iga}\ee
where the coefficients $c_k$
are differential polynomials of the potential $Q$
of degree $k$,
\be
c_k=\sum_{j=1}^k\sum_{|{\bf m}|=2k-2j}
(-1)^j
c({\bf m})Q^{(m_j)}\cdots Q^{(m_1)},
\ee
where ${\bf m}=(m_1,\dots m_j)$ is a multiindex,
$|{\bf m}|=m_1+\cdots+m_j$, and the coefficients
$c({\bf m})$ are computed explicitly
in \cite{avramidi00b}.
In particular,
\bea
c_0 &=& 1,
\\
c_1 &=& -Q,
\\
c_2 &=& Q^2-\frac{1}{3}Q''.
\eea

%We need to
%compute the asymptotics of the heat kernel diagonal
%$U(t;y,y)$ as $t\to 0$.
One can show that the heat kernel diagonal $U(t;y,y)$
satisfies the equation
\cite{avramidi14,avramidi95,avramidi15}
\be
\left(\partial_t\partial_y-\frac{E}{4}\right)U(t;y,y)
=0,
\ee
where $E$ is a third-order differential operator
\bea
E &=& \partial_y^3-2Q\partial_y-2\partial_y Q.
%\nn\\
%&=&
%\partial_y^3+4\partial_y u-2u'.
\eea
Therefore, the coefficients $c_k$
satisfy
the recurrence relations
\be
\partial_y c_k=\frac{k}{2(2k-1)}Ec_{k-1},
\qquad
k\ge 1,
\ee
with the initial condition
\be
c_0=1.
\ee
The formal
solution of this recurrence is, for $k\ge 1$,
\be
c_k=\frac{(k!)^2}{(2k)!}B^{k}\cdot 1,
\label{59iga}\ee
where
\be
B=\partial_y^{-1}E.
%=\partial_y^2-2Q-2\partial_y^{-1}Q\partial_y.
\ee
One can sum the asymptotic series formally to get
\bea
U(t;y,y)
&\sim&
(4\pi t)^{-1/2}\varphi\left(tB\right)\cdot 1
=(4\pi t)^{-1/2}\left[1-tf(tB)Q\right],
\eea
where
\bea
f(t) &=&
\sum_{k=0}^\infty
\frac{k!}{(2k+1)!}t^{k}
\nn\\
&=&\int\limits_0^1 ds\exp\left[
\frac{1}{4}(1-s^2)t
\right]
\eea
and
\bea
\varphi(t)&=&\sum_{k=0}^\infty
\frac{k!}{(2k)!}t^{k}
\nn\\
&=&
\left(1+2t\partial_t\right)
f(t).
\eea


By using this solution one can get the linear and quadratic terms
in all coefficients $c_k$; they have the form
\cite{avramidi14,avramidi15}
\be
c_k=\frac{k!(k-1)!}{(2k-1)!}
\left\{-\partial_y^{2(k-1)}Q
+(2k-1)Q\partial_y^{k-2}Q
\right\}
+O(\partial_y(QQ))+O(Q^3),
\label{518iga}\ee
where the neglected terms are of order higher than
or equal to three and the total derivatives.
Thus, it has the asymptotic expansion
\be
U(t;y,y)=(4\pi t)^{-1/2}
\left\{1-tf(t\partial_y^2)Q
+\frac{t^2}{2}Qf(t\partial_y^2)Q
+O(\partial_y(QQ))
+O(Q^3)\right\}.
\label{519iga}
\ee


On another hand one can separate the terms without
the derivatives of the potential
\be
c_k=(-1)^kQ^k+O(\partial Q).
\ee
These terms can also be summed up to get a restructured
asymptotic expansion
\be
U(t;y,y)\sim
(4\pi )^{-1/2}\exp(-tQ)\sum_{k=0}^\infty \frac{t^{k-1/2}}{k!}\tilde c_k,
\label{521iga}
\ee
where the coefficients $\tilde c_k$ are differential polynomials
in the potential $u$,
\be
\tilde c_k=\sum_{j=0}^k {k\choose j}Q^j c_{k-j}.
\ee





