%================================
%\section{Heat Kernel on a Manifold with Cusps}
%\setcounter{equation}{0}

In the case of cusps, the potential
has the form
(so called P\"oschl-Teller potential)
\bea
Q_0 &=&
\frac{1}{b^2}\left\{\nu^2
-\frac{\nu(\nu+1)}{\cosh^2(y/b)}\right\}.
\label{525iga}
\eea
Such potentials enable the exact solution
\cite{derezinski11}.
This potential behaves like a harmonic oscillator as $y\to 0$
\be
Q_0=-\frac{\nu}{b^2}{}{}
+\frac{\nu{}(\nu{}+1)}{b^4}
{} y^2
+O(y^4)
\ee
and approaches a constant at infinity as $|y|\to\infty$,
\be
Q_0=\frac{\nu^2}{b^2}
+O\left(e^{-2{} |y|/b}\right).
\label{77iga}\ee

The operator $D_0$ has a more complicated
spectrum.
Of course, it still has the simple zero eigenvalue
$\lambda_{0,0}=0$.
In the interval
$[0, \nu^2)$ it might
have some discrete eigenvalues
$
\lambda_{0,j}
$
with $j=1,\dots, N$, depending on the value of the parameter
$\nu$.
The rest of the spectrum, $[\nu^2,\infty)$, is continuous.

%===========================
To study the structure of the spectrum we compute the resolvent.
We cut the complex plane $\lambda$ along the real axis
from $\nu^2$ to infinity and
define
\be
\mu=\sqrt{-\lambda b^2+\nu^2},
\ee
with $\Real\mu\ge 0$.
We also define another commonly used spectral parameter
$s$ such that
\be
\lambda=\frac{1}{b^2}(\nu^2-\mu^2)
=\frac{1}{b^2}s\left(2\nu-s\right)
\ee
by
\be
s=\nu+\mu,
%\qquad
%2\nu-s=\nu-\mu,
\ee
so that $\Real s\ge \nu$.
This maps works as follows:
the whole comnplex plane of $\lambda$ with a cut along
the real axis from $\nu^2/b^2$ to infinity is mapped to the
right half-plane of $\mu$. The region $\Real \lambda>\nu^2/b^2$
is mapped to the region
\be
|\Imag\mu|>\Real\mu>0;
\ee
The left half-plane, $\Real \lambda<0$,
is mapped to the interior of the hyperbola
\be
\Real \mu >\sqrt{(\Imag\mu)^2+\nu^2-b^2\Real\lambda};
\ee
and the vertical strip $0<\Real\lambda<\nu^2/b^2$ is mapped
to the region
\be
|\Imag\mu|<\Real \mu <\sqrt{(\Imag\mu)^2+\nu^2-b^2\Real\lambda}.
\ee
Then the interval
$(-\infty,\nu^2/b^2]$ on the real axis in the complex plane
$\lambda$ is mapped to the positive real axis $[0,\infty)$
in the complex plane $\mu$.
The upper bank of the cut,
that is, $\lambda=(\nu^2+p^2)/b^2+i\varepsilon$, with positive $p>0$
is mapped to the negative imaginary half-axis of the
complex plane $\mu$,
$\mu=-ip$,
and the lower bank of the cut,
that is, $\lambda=(\nu^2+p^2)/b^2-i\varepsilon$,
is mapped to the positive imaginary half-axis of the,
$\mu=ip$.

The resolvent is determined by (\ref{519iga})
where the function $\tilde G_0(\lambda;y,y')$
satisfies the equation
\be
\left\{\partial_y^2
+\frac{\nu(\nu+1)}{b^2\cosh^2(y/b)}
-\frac{\mu^2}{b^2}\right\}\tilde G_0(\lambda;y,y')=0.
\ee
For  $y, y'\to \infty$
or $y,y'\to -\infty$ the resolvent has the well-known
form
\be
G_0(\lambda;y,y')\sim \frac{b}{2\mu{}}
\exp\left(-\mu{}|y-y'|/b\right).
\label{77igaxy}
\ee


In terms of the new variable
$
z=\tanh({} y/b)
$
we obtain the Legendre equation
\be
\left\{-(1-z^2)\partial_z^2+2z\partial_z
-\left[\nu{}(\nu{}+1)
-\frac{\mu^2}{(1-z^2)}
\right]\right\}\tilde G_0(\lambda;y,y')
=0.
\ee
The two linearly independent solutions of this equation are
given by the associated Legendre functions
$P^{\pm\mu}_\nu(\pm z)$
and $Q^{\pm \mu}_\nu(\pm z)$
\cite{erdelyi53}.
Any two linearly independent
solutions can be expressed in terms of the other two solutions.
We choose for the two solutions the functions
\bea
E_+(\mu,y)&=&
\frac{\Gamma(1+\mu+\nu)\Gamma(\mu-\nu)}{\Gamma(\mu)}
P^{-\mu}_\nu(-z),
\\
E_-(\mu,y)&=&
\frac{\Gamma(1+\mu+\nu)\Gamma(\mu-\nu)}{\Gamma(\mu)}
P^{-\mu}_\nu(z),
\eea
where
\bea
P^{-\mu}_{\nu{}}(z) &=& \frac{1}{\Gamma(1+\mu)}
\left(\frac{1-z}{1+z}\right)^{\mu/2}
F\left(-\nu{},\nu{}+1;1+\mu;\frac{1-z}{2}\right),
\\
P^{-\mu}_{\nu{}}(-z)
&=&\frac{1}{\Gamma(1+\mu)}
\left(\frac{1+z}{1-z}\right)^{\mu/2}
F\left(-\nu{},\nu{}+1;1+\mu;\frac{1+z}{2}\right),
\eea
are associated Legendre functions and
$F(a,b;c;z)$ denotes the hypergeometric function
\cite{erdelyi53}.
For integer values of $\nu$ the  functions
$F\left(-\nu{},\nu{}+1;1\pm\mu;\frac{1\pm z}{2}\right)$
are polynomials.
Notice that
\be
E_-(\mu,y)=E_+(\mu,-y).
\label{726igax}
\ee

These function can be analytically continued to meromorphic functions
of $\mu$.
They satisfy the equations
\be
\left(D_0+\frac{\mu^2}{b^2}\right)E_\pm(\mu,y)=0,
\ee
in fact, they satisfy the equations on the whole manifold $M$
\be
\left(\Delta_M-\frac{\mu^2}{b^2}\right)E_\pm(\mu,y)=0.
\ee

By using the relations
\cite{erdelyi53}
\bea
{}F{}(a,b;c;z)&=&(1-z)^{c-a-b}{}F{}(c-a,c-b;c;z)
\\[10pt]
F(a,b;c;1-z)&=&
\frac{\Gamma(c)\Gamma(c-a-b)}{\Gamma(c-a)\Gamma(c-b)}F(a,b;a+b-c+1;z)
%\nonumber
\\
&&
+z^{c-a-b}\frac{\Gamma(c)\Gamma(a+b-c)}{\Gamma(a)\Gamma(b)}F(c-a,c-b;c-a-b+1;z)
\nonumber
\eea
we get
\bea
&&
-\frac{\pi}{\Gamma(1-\mu+\nu)\Gamma(-\mu-\nu)}
\frac{1}{\Gamma(1+\mu)}
F(-\nu,\nu+1;1+\mu;z)
\nn\\
&&
=\sin(\pi\mu)\frac{1}{\Gamma(1-\mu)}F(-\nu,\nu+1;1-\mu;1-z)
\nn\\
&&
+z^{-\mu}(1-z)^{\mu}
\sin(\pi\nu)\frac{1}{\Gamma(1-\mu)}
F(-\nu,\nu+1;1-\mu;z)
\label{726iga}
\eea
and, therefore,
\bea
&&
-\frac{\pi}{\Gamma(1-\mu+\nu)\Gamma(-\mu-\nu)}
P^{-\mu}_\nu(z)
=\sin(\pi\mu)
P^{\mu}_\nu(-z)
+\sin(\pi\nu)
P^{\mu}_\nu(z).
\label{725iga}
\eea



%================================

We study the behavior of these solutions at infinity
$y\to +\infty$, ($z\to 1$), and $y\to -\infty$, ($z\to -1$).
Notice that
\be
\frac{1+z}{1-z}=e^{2y/b}.
\ee
%Also, recall that we have $\Real \mu>0$.
By using the hypergeometric series and the eq. (\ref{725iga})
in the form
\bea
&&
P^{-\mu}_\nu(z)
=
\frac{\Gamma(\mu)\Gamma(1-\mu)}{\Gamma(1+\mu+\nu)\Gamma(\mu-\nu)}
P^{\mu}_\nu(-z)
+
\frac{\sin(\pi\nu)}{\sin(\pi\mu)}P^{-\mu}_\nu(-z),
\label{730iga}
\eea
we obtain the asymptotics
\be
E_+(\mu,y)
\sim
\left\{
\begin{array}{ll}
e^{\mu y/b}
+R(\mu)
e^{-\mu y/b},
\qquad
 &y\to \infty,
\\[5pt]
T(\mu)
e^{\mu y/b},
\qquad
& y\to -\infty,
\end{array}
\right.
\label{734iga}
\ee
\be
E_-(\mu,y)
\sim
\left\{
\begin{array}{ll}
T(\mu)
e^{-\mu y/b},
\qquad
& y\to \infty,
\\[5pt]
e^{-\mu y/b}
+R(\mu)
e^{\mu y/b},
\qquad
 &y\to -\infty,
\end{array}
\right.
\label{735iga}
\ee
%=========
where
\bea
T(\mu) &=&
\frac{\Gamma(\mu+\nu+1)\Gamma(\mu-\nu)}{\Gamma(\mu+1)\Gamma(\mu)},
\\[5pt]
R(\mu) &=&
\frac{\sin(\pi\nu)}{\sin(\pi\mu)}
\frac{\Gamma(\mu+\nu+1)\Gamma(\mu-\nu)}{\Gamma(\mu+1)\Gamma(\mu)}.
\eea
This enables one to easily compute the
Wronskian of these solutions
\be
E_+(\mu,y)\partial_y E_-(\mu,y)
-\partial_y E_+(\mu,y) E_-(\mu,y)
=-\frac{2\mu}{b} T(\mu).
\ee

Therefore, for $\Real\mu>0$ the function $E_-(\mu,y)$
is bounded as $y\to \infty$ and the function $E_+(\mu,y)$
is bounded as $y\to -\infty$.
For imaginary $\mu=\pm ip$
these solutions behave like incoming and outgoing waves.


By using the relations (\ref{725iga}) it is easy to see that
these functions are related by
\bea
E_+(\mu,y)
&=&
R(\mu)E_+(-\mu,y)
+T(\mu)E_-(-\mu,y),
\\
E_-(\mu,y)
&=&
T(\mu)E_+(-\mu,y)
+R(\mu)E_-(-\mu,y),
\eea
or in the matrix form
\be
\begin{pmatrix}
E_+(\mu)\\
E_-(\mu)
\end{pmatrix}
=C(\mu)\begin{pmatrix}
E_+(-\mu)\\
E_-(-\mu)
\end{pmatrix},
\ee
where $C(\mu)$ is a symmetric matrix defined by
\be
C(\mu)=
\begin{pmatrix}
R(\mu) & T(\mu)
\\
T(\mu) & R(\mu)
\end{pmatrix}.
\ee
Therefore, the matrix $C(\mu)$ satisfies the
functional equation
\be
C(\mu)C(-\mu)=I.
\ee
In particular, this means
\bea
R(\mu)T(-\mu)+T(\mu)R(-\mu) &=& 0,
\label{744iga}\\
R(\mu)R(-\mu)+T(\mu)T(-\mu) &=& 1.
\label{745iga}
\eea
Obviously, it is symmetric and satisfies
\be
\overline{C(\mu)}=C(\bar\mu),
\qquad
C^T(\mu)=C(\mu);
\ee
therefore, for the imaginary $\mu$, with $\Real\mu=0$,
the matrix $C(\mu)$ is unitary,
\be
C(\mu)C^*(\mu)=I.
\ee
In particular, this means that
the matrix $C(\mu)$ does not have poles on the
imaginary axis.

We summarize the properties of the matrix $C(\mu)$.
Let $\nu$ be a positive real parameter.
Then:
\benum
\item
The matrix $C(\mu)$ is a meromorphic function of $\mu$.
\item
It is analytic for $\Real \mu >\nu$;
all poles are located in the half-plane
$\Real\mu\le \nu$.
\item
All poles are on the real axis.
\item
The poles on the interval $(0,\nu]$ are simple and have the form
\be
a_j=\nu -j, \qquad
j=0,1,\dots, [\nu].
\ee

\item
If $2\nu$ is not an integer, then there are two series of
simple poles in the
left half-plane $\Real\mu<0$,
\be
b_m=-\nu-1-m,
\qquad
m=0,1,2,\dots
\ee
and
\be
a_j=\nu -j, \qquad
j\ge [\nu]+1.
\ee

\item
If $2\nu$ is a positive integer then the poles
\be
a_j=\nu -j,
\qquad
[\nu]+1\le  j\le 2\nu,
\ee
are single
and the poles
\be
b_m=-\nu-1-m,
\qquad
m=0,1,2,\dots
\ee
are double.

\item
The matrix $C(\mu)$ satisfies the functional equation
\be
C(\mu)C(-\mu)=I
\ee
and is unitary on the imaginary axis, for $\Real\mu=0$.

\eenum

Therefore, the function $\tilde G_0(\lambda;y,y')$ is
given by
\bea
\tilde G_0(\lambda;y,y')
&=&
\frac{b}{2\mu T(\mu)}
E_+(\mu,y)E_-(\mu,y');
\eea
by using (\ref{726igax}) we see that
\be
\tilde G_0(\lambda;y,y')=\tilde G_0(\lambda;-y',-y).
\ee
The resolvent is
\be
G_0(\lambda;y,y')
=\theta(y'-y)\tilde G_0(\lambda;y,y')
+\theta(y-y')\tilde G_0(\lambda;y',y).
\ee
which is obviously symmetric and
has the correct asymptotics at infinity
(\ref{77iga}).
The asymptotics of the resolvent at infinity,
as $y,y'\to \infty$ or $y,y'\to-\infty$ is
\be
\tilde G_0(\lambda;y,y')
\sim
\frac{b}{2\mu}\left\{e^{\mu(y-y')/b}
+R(\mu)e^{-\mu|y+y'|/b}
\right\}.
\ee
The diagonal value of the resolvent is
\bea
G_0(\lambda;y,y)
&=&
\frac{b}{2\mu T(\mu)}
E_+(\mu,y)E_-(\mu,y).
\eea
which is an even function
\be
G_0(\lambda;y,y)=G_0(\lambda;-y,-y)
\ee
with the asymptotics as $|y|\to\infty$,
\be
G_0(\lambda;y,y)
\sim
\frac{b}{2\mu}\left\{1
+R(\mu)e^{-2\mu|y|/b}
\right\}.
\ee
Note that for $\Real\mu>0$ the resolvent diagonal approaches a constant at
infinity $|y|\to \infty$,
\be
G_0(\lambda;y,y)\sim \frac{b}{2\mu}
\ee
and, therefore, is not integrable.

%===================


The spectrum is determined by the singularities
of the resolvent.
The resolvent is a meromorphic function $\mu$.
It has a finite number of simple poles
on the positive real line at
\be
a_j=\nu-j,
\qquad
j=0,1,2\dots, N,
\ee
that is,
\be
\lambda_{0,j}=\frac{1}{b^2}\left[\nu^2-(\nu-j)^2\right]
=\frac{1}{b^2}j(2\nu-j),
\ee
where
$
N=\lceil \nu\rceil-1
$
is the greatest integer less than $\nu$.
The corresponding eigenfunctions are
\be
\psi_{0,j}(y)
=c_{0,j}P^{j-\nu}_\nu(z)
\ee
with some normalization constants.
These eigenfunctions decrease at infinity
exponentially as $y\to \pm\infty$,
\be
\psi_{0,j}(y)\sim \exp[-(\nu-j)|y|/b],
\ee
for any $j<\nu$.

By using the integral
\cite{erdelyi53}
\be
\int\limits_{-1}^1 \frac{dz}{1-z^2}
[P^{j-\nu}_\nu(z)]^2
=\frac{1}{2(\nu-j)}\frac{j!}{\Gamma(2\nu-j+1)}
\ee
we find
\be
c_{0,j}=\frac{1}{\sqrt{b}}
\left(2(\nu-j)\frac{\Gamma(2\nu-j+1)}{j!}\right)^{1/2}.
\ee
%If $\nu$ is an integer, then $N=\nu$ and
%$\lambda_N=N^2$ is an embedded eigenvalue.

The corresponding eigenfunctions of the Laplacian
on the manifold $M$ are
\be
\Psi_{0,j}(y,\hat x)=\frac{c_{0,j}}{\sqrt{\vol(N)}}P^{j-\nu}_\nu(z).
\ee

It is obvious that, as a function of $\lambda$,
the resolvent has a branch cut singularity
along the positive real axis from $\nu^2$ to infinity,
which determines the continuous spectrum $[\nu^2/b^2,\infty)$.

%===========================
%====================================

Now, we obtain the heat kernel of the operator $D_0$
by the inverse Laplace transform (\ref{617iga}).
%\be
%U_0(t;y,y')=\frac{1}{2\pi i}
%\int\limits_{c-i\infty}^{c+i\infty}d\lambda\; e^{-t\lambda}
%\frac{1}{2\mu T(\mu)}E_+(\mu,y)E_-(\mu,y').
%\ee
We deform the contour of integration to a contour
 in the complex plane of $\lambda$ which goes from
$-i\varepsilon+\infty$ around the positive real half-axis
to $i\varepsilon+i\infty$. Recall that the upper bank of the
branch cut corresponds to $\mu=-ip$ and the lower
bank of the cut corresponds to $\mu=ip$ with $p>0$.
This leads to the sum of the poles of the resolvent
and the integral over the branch cut of the jump of the resolvent
across the cut,
\bea
U_0(t;y,y') &=&
\sum_{j=0}^{N}\exp\left\{-[\nu^2-(\nu-j)^2]\frac{t}{b^2}\right\}
\psi_{0,j}(y)\psi_{0,j}(y')
\nn\\
&&
+\frac{1}{b}\int\limits_{0}^{\infty}\frac{dp}{2\pi}\;
\exp\left\{-(\nu^2+p^2)\frac{t}{b^2}\right\}
W(p;y,y'),
\label{565iga}
\eea
where
\bea
W(p;y,y')
%&=&
%\frac{2ip}{b}
%\left\{\tilde G_0(ip;y,y')-\tilde G_0(-ip;y,y')
%\right\}
%\nn\\
&=& E_+(ip,y)E_+(-ip,y')
+E_-(ip,y)E_-(-ip,y').
\label{567iga}
\eea
This function has the properties
\be
W(p;y,y')=W(p;-y,-y')=W(-p,y,y'),
\ee
%We compute the asymptotics of this function.
By using (\ref{734iga}), (\ref{735iga}),
and (\ref{744iga}), (\ref{745iga}), we get
as $y,y'\to \infty$ or $y,y'\to -\infty$,
\be
W(p;y,y')
\sim
2\cos[p(y-y')/b]
+R(ip)e^{-ip|y+y'|/b}+R(-ip)e^{ip |y+y'|/b}.
\ee
The diagonal value of this function
is a real even function
of both $y$ and $p$.
By using the definition of the functions
$E_\pm(\mu,y)$ and the properties of the gamma function
we compute
\bea
W(p;y,y)
&=&
\frac{\sinh^2(\pi p)}{\sinh[\pi(p-i\nu)]\sinh[\pi(p+i\nu)]}
\left\{
\Psi(p,y)+\Psi(p,-y)
\right\}
\label{570iga}
\eea
where
\be
\Psi(p,y)
=F\left(-\nu{},\nu{}+1;1+ip;\frac{1+z}{2}\right)
F\left(-\nu{},\nu{}+1;1-ip;\frac{1+z}{2}\right)
\ee
We will also need the asymptotics of this function as $p\to\infty$.
By using the properties of the hypergeometric function we get
\be
\Psi(p,y)= 1-\frac{\nu(\nu+1)}{p^2}
\left\{1
-(\nu-1)(\nu+2)\frac{(1+z)}{2}
\right\}\frac{(1+z)}{2}
+O(p^{-3})
\ee
Therefore, as $p\to \infty$,
\be
W(p;y,y)
\sim
 2-\frac{\nu(\nu+1)}{p^2}
\left\{1
-\frac{(\nu-1)(\nu+2)}{2}
(1+z^2)
\right\}
+O(p^{-3})
\ee

Note that as $p \to 0$,
\be
W(p;y,y) \sim \frac{\pi^2p^2}{\sin^2(\pi\nu)}
\left\{
\Psi(0,y)+\Psi(0,-y)
\right\},
\ee
and as $|y|\to \infty$,
\be
W(p;y,y)\sim
2+R(ip)e^{-2ip |y|/b}
+R(-ip)e^{2ip |y|/b}.
\ee
where
\be
R(ip) =
\sin(\pi\nu)\frac{p}{\sinh(\pi p)}
\frac{\Gamma(ip+\nu+1)\Gamma(ip-\nu)}{\left[\Gamma(ip+1)\right]^2
}.
\ee
%\be
%R(ip) =
%\frac{\sin(\pi\nu)}{\sin[\pi(ip-\nu)]}
%\frac{\Gamma(1+\nu+ip)\Gamma(1-ip)}{\Gamma(1+ip)\Gamma(1+\nu-ip)}.
%\ee
Notice that as $p\to 0$
\be
R(ip)= -1-cip+O(p^2)
\ee
where
\be
c=\left[\psi(\nu+1)+\psi(-\nu)
-2\psi(1)\right],
\ee
where $\psi(z)=\Gamma'(z)/\Gamma(z)$ is the logarithmic derivative
of the gamma function.

Next, by using the asymptotics of the gamma function
%Use as $z\to \infty$
\be
\Gamma(z) \sim (2\pi)^{1/2}z^{-1/2}\exp\left\{
z\log z -z
\right\}
\ee
we get
\be
\frac{\Gamma(z+a)}{\Gamma(z)} \sim z^a
\ee
and, therefore,
as $p\to \infty$
\be
R(ip) \sim
-i\frac{\sin(\pi\nu)}{\sinh(\pi p)}.
%\sim
%-2i\sign({}p)\sin(\pi\nu)e^{-\pi|{}p|}
\ee

