\section{Turaev--Viro invariants}\label{Sec:TV}
This section provides a new proof of \refconj{TVconj} for flat octahedral fully augmented links.

We utilise a formula of Detcherry, Kalfagianni and Yang \cite[Theorem~1.1]{DKYRTTV}, to relate the Turaev--Viro invariants of an octahedral fully augmented link complement to its coloured Jones polynomial:

\begin{theorem} [Theorem~1.1 of \cite{DKYRTTV}]\label{Thm:TVfromColJones}
Let $L$ be a link in $S^3$ with $n$ components.
Let $r=2m+1\ge3$ be an odd integer and $A$ a primitive $2r^{th}$ root of unity, with $q=A^2$. Then 
\begin{equation} \label{Eqn:TVasSumofJones}
TV_r(S^3\setminus L,q)=2^{n-1}(\eta_r')^2\sum_{1\leq\pmb{i}\leq m}|J_{L,\pmb{i}}(A)|^2.
\end{equation}
Here $\eta_r' = (A^2-A^{-2})/\sqrt{-r}$ and $\pmb{i}=(i_1,\dots,i_n)$ and $1\leq\pmb{i}\leq m$ means $1\leq i_k\leq m$ for each $k$.
\end{theorem}

\begin{remark}
Note that \cite{DKYRTTV} uses a different normalisation of the coloured Jones polynomial than we used in the previous section, following \cite{KauffLins,LickorishTextbook}. Our definition takes into account a correction factor for the framing of the links, and differs from that of \cite{DKYRTTV} by a power of $A$. However, since $A$ is a root of unity and we are only interested in the modulus of $|J_{L,\pmb{i}}|$ in \refthm{TVfromColJones}, our formula will suffice.
\end{remark}


We will use \refthm{TVfromColJones}  with \refprop{ColJonesforOctFAL} and \refeqn{colJones} to evaluate limits of $TV_r$. By \refprop{ColJonesforOctFAL}, we will have terms involving $\Delta_j$, $\lambda_{j,a}$, $\gamma_j^{i,k}$, and quantum 6j-symbols. We will need further information on these terms to find and apply bounds.


We first consider $\Delta_j$ and $\lambda_{j,a}$. Recall $\Delta_j$ is the closure of the Jones--Wenzl idempotent in the plane evaluated in the Kauffman bracket, and $\lambda_{j,a}$ is defined in \reflem{remove-circle}. 

\begin{lemma}[Lemma~4 of \cite{KauffLins}]\label{Lem:jbounded}
The term $\Delta_{j} = (-1)^{j} [j+1]$, where $[n]$ is the quantum integer of \refdef{QuantumInt}. It is the $j^{th}$ Chebyshev polynomial of second kind in variable $(-A^2-A^{-2})$:
\[ \Delta_j=\frac{(-1)^j(A^{2(j+1)}-A^{-2(j+1)})}{A^2-A^{-2}} \]
If $q=A^2$ is a primitive $r$-th root of unity, where $r\ge3$ is odd, then $\Delta_{r-1}=0$ and for all $0\leq j\leq r-2,$ 
\begin{equation}\label{Eqn:Delta_n}
\Delta_j = (-1)^j \frac{\sin ( 2\pi (j+1)/r)}{\sin(2\pi/r)}\neq 0.
\end{equation}
\end{lemma}

A quantum $6j$ symbol is associated with an admissible 6-tuple $(i,j,k,l,m,n)$, as follows.

\begin{definition} \label{Def:r-admis}
A triple $(i,j,k)$ of elements of $I_r$ is called \emph{$r$-admissible} (or \emph{admissible}), if
\begin{enumerate}
\item $i+j+k$ is even,
\item $i\leq j+k$, $j\leq k+i$, $k\leq i+j$, and
\item $i+j+k\leq 2r-4$.
\end{enumerate}
A 6-tuple $(i,j,k,l,m,n)$ of elements of $I_r$ is \textit{admissible} if each of the triples $(i,j,k)$, $(j,l,n)$, $(i,m,n)$, $(k,l,m)$ are $r$-admissible.
\end{definition}

Throughout, let $n_r=\frac{r-1}{2}$ if $r\equiv1\mod4$ and $n_r=\frac{r-3}{2}$ if $r\equiv3\mod4$. 
Note that for $j\in I_r$, if $(n_r,n_r,j)$ is admissible, then the admissibility conditions imply that $j\in\{0,2,4,\dots,r-3\}$.


\begin{lemma} \label{Lem:DeltaLambdaSigns}
Let $n_r=(r-1)/2$ if $r\equiv 1\mod 4$ and $n_r=(r-3)/2$ if $r\equiv 3\mod 4$.
For $j,j_1,j_2\in I_r$ such that $(n_r,n_r,j),(n_r,n_r,j_1),(n_r,n_r,j_2)$ are $r$-admissible, the following hold.
\begin{enumerate}
\item The sign of $\Delta_j$ is positive if $0\leq j\leq (r-3)/2$ and negative if $(r-1)/2\leq j\leq r-2$.

\item The sign of $\lambda_{j,n_r}$, defined as in \refeqn{LambdaFormula}, is
  \[ \sgn(\lambda_{j,n_r})=\begin{cases}
  \sgn(\Delta_j), & r\equiv3\mod4, \\
  -\sgn(\Delta_j), & r\equiv1\mod4.
  \end{cases}\]
\end{enumerate} 
\end{lemma}

\begin{proof}
For (1), by \reflem{jbounded},
\[ \Delta_j = (-1)^j \, \frac{\sin(2\pi(j+1)/r)}{\sin(2\pi/r)} \in \RR \]
By admissibility conditions on $(n_r, n_r, j)$, the integer $j$ must be even. The denominator $\sin(2\pi/r)$ is positive for all $r\ge3$.
The term $(2\pi(j+1))/r$ lies in $(0,\pi)$ for $0\leq j\leq (r-3)/2$, and lies in $(\pi,2\pi)$ for $(r-1)/2\leq j\leq r-2$. The statement of (1) follows. 

For (2), by \refeqn{LambdaFormula}, we have
\[ \lambda_{j,n_r} = \frac{\sin(2\pi(j+1)(n_r+1)/r)}{\sin(2\pi(j+1)/r)}\in\RR
\]
Now,
\[\frac{2\pi}{r}(j+1)(n_r+1) = \begin{cases}
  \pi(j+1)-\frac{\pi}{r}(j+1), & r\equiv 3\mod4, \\
  \pi(j+1)+\frac{\pi}{r}(j+1), & r\equiv 1\mod4.
\end{cases}\]
By the argument of (1), $\frac{\pi}{r}(j+1) \in (0,\frac{\pi}{2})$ for $0\leq j\leq (r-3)/2$ and $\frac{\pi}{r}(j+1) \in (\frac{\pi}{2},\pi)$ for $(r-1)/2\leq j\leq r-2$.
Note also that $j+1$ is odd since $j$ is even by admissibility. Hence, if $r\equiv 3\mod4$, then 
$\frac{2\pi}{r}(j+1)(n_r+1) \in  (j \pi , \pi (j+1)-\frac{\pi}{2}) \cup (\pi (j+1)-\frac{\pi}{2}, \pi (j+1))$, which is in the first and second quadrant of the unit circle. Therefore, $\sin\left(\frac{2\pi}{r}(j+1)(n_r+1)\right)>0$, so the sign of $\lambda_{j,n_r}$ is given by $\sgn \left(\sin\left(2\pi(j+1)/r\right)\right) = \sgn(\Delta_j)$. If $r\equiv 1\mod4$, then $\frac{2\pi}{r}(j+1)(n_r+1)$ is in the third and fourth quadrant and the result follows analogously.
\end{proof}


We need to determine the signs of the quantum $6j$ symbols as well. To do so, we need more information on these symbols. We now recall their full definition, and related results.

\begin{definition} \label{Def:6j-defn}
The \emph{quantum $6j$-symbol} associated with an admissible 6-tuple $(i,j,k,l,m,n)$ is the complex number
\begin{equation}
  \begin{vmatrix}
    i & j & k \\
    l & m & n
  \end{vmatrix} =(-1)^{(i+j+k+l+m+n)/2}\Delta(ijk)\Delta(imn)\Delta(ljn)\Delta(lmk)  \sum_{z=\max\{T_1,T_2,T_3,T_4\}}^{\min\{Q_1,Q_2,Q_3\}}S_z
\end{equation}
Here $\Delta(ijk)$ is given by
\begin{equation}\label{Eqn:DeltaEqn}
  \Delta(ijk)  = \left(\frac{[\frac{i+j-k}{2}]![\frac{i-j+k}{2}]![\frac{j+k-i}{2}]!}{[\frac{i+j+k}{2}+1]!} \right)^{1/2}
\end{equation}
The term $S_z$ is defined as
\begin{equation}\label{Eqn:sz}
S_z = \frac{(-1)^z[z+1]!}{[z-T_1]![z-T_2]![z-T_3]![z-T_4]![Q_1-z]![Q_2-z]![Q_3-z]!} \end{equation}
where the values $T_p$ correspond to faces of the tetrahedron as in \reffig{6jtetra}:
\begin{equation}\label{Eqn:Tdefn}
  T_1=\frac{i+j+k}{2}, \quad T_2=\frac{j+l+n}{2}, \quad T_3=\frac{i+m+n}{2}, \quad T_4=\frac{k+l+m}{2},
\end{equation}
The values $Q_q$ correspond to quadrilaterals separating two pairs of vertices as in \reffig{6jtetra}:
\begin{equation}\label{Eqn:Qdefn}
  Q_1=\frac{i+j+l+m}{2}, \quad Q_2=\frac{i+k+l+n}{2}, \quad Q_3=\frac{j+k+m+n}{2}
\end{equation}
\end{definition}

