In~\cite[Theorem~A.1]{MainPaper}, the authors prove the following result of Costantino~\cite{Cost6jSymb} for the root of unity $\qroot$. The form of the theorem that we need appears in~\cite{KumarMelbyTVadditivity}.

\begin{theorem}[Theorem~3.4~(1) of \cite{KumarMelbyTVadditivity}]\label{Thm:6TuplesandHypIdealTetra} 
If $(n_1^{(r)},n_2^{(r)},n_3^{(r)},n_4^{(r)},n_5^{(r)},n_6^{(r)})$ is a sequence of admissible 6-tuples with
\begin{enumerate}[label=(\roman*)]
\item $0\leq Q_j-T_i\leq (r-2)/2$ for $1\leq i\leq 4$, $1\leq j\leq3$, and
\item $(r-2)/2\leq T_i\leq r-2$ for $1\leq i\leq4$,
\end{enumerate}
then
for each $r$, the sign of $S_z$ is independent of the choice of $z$, for $\max\{T_i\}\leq z\leq\min\{Q_j\}$.
\end{theorem}


\begin{lemma}\label{Lem:6jSign}
Let $n_r=(r-1)/2$ if $r\equiv 1\mod 4$, and $n_r=(r-3)/2$ if $r\equiv 3\mod 4$. Then the quantum $6j$-symbol
\[\begin{vmatrix}
  n_r & n_r & j_1 \\
  n_r & n_r & j_2
\end{vmatrix}\]
is real-valued. Its sign is positive if $r\equiv3\mod4$ and negative if $r\equiv1\mod4$.
\end{lemma}

\begin{proof}
The given quantum $6j$-symbol is real-valued due to \cite[Lemma~4.7]{KumarMelbyTVadditivity}. The rest of the proof considers its sign, appealing to \refdef{6j-defn}. 

For the admissible 6-tuple $(n_r, n_r, j_1, n_r, n_r, j_2)$, the values of $T_i$ and $Q_j$ are as follows:
\[ T_1=T_4 = n_r+ \frac{j_1}{2}, \quad T_2=T_3=n_r+\frac{j_2}{2}, \quad Q_1=2n_r, \quad Q_2=Q_3=n_r + \frac{j_1+j_2}{2}
\]
Thus $Q_j-T_i$ is one of $n_r-(j_1/2)$, $n_r-(j_2/2)$, $j_1/2$, or $j_2/2$. Note also that by admissibility, $j_1, j_2\in \{0, 2, 4, \dots, r-3\}$. 
Then by \refdef{6j-defn}, 
\begin{equation}\label{Eqn:6jForSign}
\begin{vmatrix}
n_r & n_r & j_1 \\
n_r & n_r & j_2
\end{vmatrix}
=(-1)^{(j_1 + j_2)/2} \Delta(n_r,n_r,j_1)^2 \Delta(n_r,n_r,j_2)^2
\sum_{z=n_r+\frac12 \max\{j_1,j_2\}}^{\min\{2n_r,n_r+\frac12(j_1+j_2)\}} S_z^{j_1,j_2}
\end{equation}
where
\begin{equation} \label{Eqn:nr6j}
S_z^{j_1,j_2}=\frac{(-1)^z[z+1]!}{([z-n_r-\frac{j_1}{2}]!)^2([z-n_r-\frac{j_2}{2}]!)^2[2n_r-z]!([n_r-\frac{j_1}{2}-\frac{j_2}{2}-z]!)^2}
\end{equation}

Consider the case where $j_1,j_2\neq0$. We show that the assumptions of \refthm{6TuplesandHypIdealTetra} hold if $j_1,j_2\neq0$. 
By admissibility, for $l\in\{1,2\}$, we have $j_l/2 \geq 0$ and $j_l/2 \leq n_r$, hence $n_r-(j_l/2)\geq 0$. This gives the lower inequality for assumption~(i).  For the upper, $j_l\leq r-3$ so $(j_l/2)\leq (r-3)/2< (r-2)/2$. Also, $n_r-(j_l/2)\leq n_r=(r-3)/2$ if $r\equiv3\mod4$. If $r\equiv 1\mod 4$, since $j_l\neq 0$, we have $n_r-(j_l/2)\leq (r-1)/2 - 1/2$. This gives the upper bound of~(i).

For assumption~(ii) of \refthm{6TuplesandHypIdealTetra}, suppose first $r\equiv1\mod4$. Then $(r-2)/2<n_r$ so $(r-2)/2\leq n_r + (j_l/2)$.
Also, $n_r+(j_l/2) \leq n_r + (r-3)/2 = r-2$. So~(ii) holds when $r\equiv1\mod4$.
Now suppose $r \equiv 3\mod 4$. Then $n_r + (j_l/2) \leq n_r + (r-3)/2 = 2n_r < r-2$, and $n_r + (j_l/2) \ge (r-2)/2$ if $j_l>0$. So~(ii) holds provided $j_l\neq0$.
Then \refthm{6TuplesandHypIdealTetra} holds when $j_l\neq 0$. 

By \refthm{6TuplesandHypIdealTetra}, the sign of $S_z^{j_1,j_2}$ is independent of $z$. For this case, we show the sign of $S_z^{j_1,j_2}$ is also independent of $j_1,j_2$. Possible contributions to the sign in \refeqn{nr6j} come from terms $(-1)^z$, $[z+1]!$, and $[2n_r-z]!$, since the other terms are squares of real numbers (see \reflem{jbounded}) hence always positive. Since the sign is independent of $z$, to compute the sign it suffices to find the signs of terms $[z+1]!$ and $[2n_r-z]!$ for any value of $z$ in the range of the sum of \refeqn{6jForSign}. In particular, let $j_m := \max\{j_1,j_2\}$, and consider the minimum value $z = n_r + j_m/2$. Then $[z+1]!=[n_r+(j_m/2)+1]!$ and $[2n_r-z]=[n_r-(j_m/2)]!$.

By our work checking~(i) of \refthm{6TuplesandHypIdealTetra}, we have
$0 \leq n_r - (j_m/2) \leq (r-2)/2$. 
For any $k\in \ZZ$ satisfying $0 \leq k \leq (r-2)/2$, the value $2\pi k/r$ must lie in Quadrants~I or~II. Then
\begin{equation}\label{Eqn:NR}
[n_r-(j_m/2)]! = \prod_{k=1}^{n_r-(j_m/2)} \frac{\sin(2\pi k/r)}{\sin(2\pi/r)} >0
\end{equation}

By our work checking~(ii), $r/2 < n_r + (j_m/2)+1 \leq r-1$ (note the strict inequality since $j\neq0$ so $j\geq2$ by admissibility). Any $k\in\ZZ$ in this range satisfies $\pi < (2\pi k)/r \leq 2\pi(r-1)/r$, hence it lies in Quadrants~III or~IV and the value of $\sin(2\pi k/r)$ is negative. Then
\begin{equation}\label{Eqn:NRP}
[n_r + (j_m/2)+1]! = \prod_{k=1}^{(r-1)/2} \frac{\sin(2\pi k/r)}{\sin(2\pi/r)} \prod_{(r+1)/2}^{n_r+(j_m/2)+1} \frac{\sin(2\pi k/r)}{\sin(2\pi/r)}
\end{equation}
The first product consists of all positive terms, the second all negative, hence its sign is given by $(-1)^{n_r+(j_m/2)+1-(r-1)/2}$. It follows that the sign of $S_z^{j_1,j_2}$ is given by the product of this sign and $(-1)^{n_r+ (j_m/2)}$, which is $(-1)^{-(r-3)/2}$ since $j_m$ is even. Thus the sign is independent of $z$, $j_1$, $j_2$. It is $1$ if $r\equiv 3\mod4$ and $-1$ if $r\equiv 1\mod 4$. 

Now, for $l\in\{1,2\}$, by \refeqn{DeltaEqn}, 
\[
\Delta(n_r,n_r,j_l)^2=\frac{[n_r-\frac{j_l}{2}]!([\frac{j_l}{2}]!)^2}{[n_r+\frac{j_l}{2}+1]!}
\]
Since $([\frac{j_l}{2}]!)^2$ is positive by \reflem{jbounded}, and $[n_r-j_\ell/2]!$ is positive by \refeqn{NR}, the sign is that of \refeqn{NRP}, or
\[\sgn \left(\Delta(n_r,n_r,j_l)^2 \right) = (-1)^{n_r+(j_l/2)-(r-3)/2}\]
It follows that
\[
\sgn\left((-1)^{(j_1+j_2)/2}\Delta(n_r,n_r,j_1)^2\Delta(n_r,n_r,j_2)^2 \right)=1\]
This concludes the proof in the case $j_1,j_2\neq0$.

Now, suppose one of $j_1$ or $j_2$ is zero.
In this case, consider
$\Tet\begin{bmatrix}n_r & n_r & j_1 \\n_r & n_r & j_2 \end{bmatrix}$
in \reffig{theta-net}~(3). If one of $j_1$, $j_2$ is zero, without loss of generality say $j_1=0$, then there are two 3-vertices in that figure labeled $(n_r, n_r, 0)$. By \refdef{3vertDef}, it follows that labels for $j$, $k$, $c$ in \reffig{theta-net}~(1) are all zero, and labels $a$, $b$, $i$ are all $n_r$. This describes a single edge decorated by the Jones--Wenzl idempotent labeled $n_r$. Thus, we may remove the edge of the tetrahedral network labeled $0$ and replace the adjacent two edges labeled $n_r$ by single edges labeled $n_r$. The result is a theta net labeled $n_r$, $n_r$, $j_2$. Noting the trihedron coefficient is symmetric in its arguments, we conclude
\[\Tet\begin{bmatrix}
n_r & n_r & 0 \\
n_r & n_r & j_2
\end{bmatrix}=\theta(n_r,n_r,j_2)\]
Moreover, a similar argument as above shows that the theta net labeled $(n_r, n_r, 0)$ is just the closure of the Jones--Wenzl idempotent in the plane, so $\theta(n_r,n_r,0)=\Delta_{n_r}$.
Hence, by \refeqn{Tetrato6j},
\[\begin{vmatrix}
n_r & n_r & 0 \\
n_r & n_r & j_2
\end{vmatrix} = \frac{1}{\Delta_{n_r}\theta(n_r,n_r,j_2)}
\Tet\begin{bmatrix}
n_r & n_r & 0 \\
n_r & n_r & j_2
\end{bmatrix} = \Delta_{n_r}^{-1} \]

Applying \reflem{DeltaLambdaSigns}~(1), 
\[ \sgn\left(\begin{vmatrix}
  n_r & n_r & 0 \\
  n_r & n_r & j_2
\end{vmatrix}\right)= \sgn(\Delta_{n_r}) = 
\begin{cases}
  1, & r\equiv3\mod4, \\
  -1, & r\equiv1\mod4.
\end{cases} \]

Finally, suppose $j_1=j_2=0$. Then by \refeqn{Tetrato6j},
\[\begin{vmatrix}
n_r & n_r & 0 \\
n_r & n_r & 0
\end{vmatrix} = \Delta_{n_r}^{-2} \Tet\begin{bmatrix}
n_r & n_r & 0 \\
n_r & n_r & 0
\end{bmatrix} = \Delta_{n_r}^{-2}\Delta_{n_r}=\Delta_{n_r}^{-1} \]
and the result follows as in the previous case.
\end{proof}

\begin{corollary} \label{Cor:SignofN}
Let $L$ be a flat octahedral fully augmented link with $c$ crossing circles, and let $N_{\pmb{i},j_1,j_2,\dots,j_c}$ be as in \refprop{ColJonesforOctFAL}. Let $\pmb{n}_r=(n_r,\dots,n_r)$. Then $N_{\pmb{n}_r,j_1,j_2,\dots,j_c}$ is real-valued, with sign given by
\[\sgn(N_{\pmb{n}_r,j_1,j_2,\dots,j_c})=
\begin{cases}
  1, & r\equiv3\mod4, \\
  -1, & r\equiv1\mod4.
\end{cases}\]
In particular, the sign of $N_{\pmb{n}_r,j_1,j_2,\dots,j_n}$ is independent of $j_1,j_2,\dots,j_c$.
\end{corollary}

\begin{proof}
The fact that $N_{\pmb{n}_r,j_1,\dots,j_n}$ is real-valued follows from the fact that it is a product of real-valued terms by \reflem{DeltaLambdaSigns} and \reflem{6jSign}. Moreover, if $r\equiv3\mod4$ then $\sgn(N_{\pmb{n}_r,j_1,\dots,j_n})=1$ and if $r\equiv1\mod4$ then $\sgn(N_{\pmb{n}_r,j_1,j_2,\dots,j_n})=(-1)^{c}(-1)^{c-1}=-1$, where the term $(-1)^c$ is the sign of the product of the $c$ terms $\Delta_{j_l}\lambda_{j_l,n_r}$ by \reflem{DeltaLambdaSigns}, and the $(-1)^{c-1}$ comes from the $c-1$ quantum 6j-symbols, by \reflem{6jSign}.
\end{proof}



\subsection{Bounds}
Belletti, Detcherry, Kalfagianni and Yang~\cite{MainPaper} give the following upper bound on the growth of rate of the quantum $6j$-symbol. Related results on these growth rates are also due to Costantino~\cite{Cost6jSymb}. 

\begin{theorem}[Theorem~1.2 of \cite{MainPaper}] \label{Thm:6jBound}
For any $r$ and any $r$-admissible 6-tuple $(i,j,k,l,m,n)$, the following bound holds:
\[\frac{2\pi}{r}\log\left|\begin{vmatrix}
i & j & k \\
l & m & n
\end{vmatrix}_{q=\qroot}\right|\leq v_8+\mathcal{O}\left(\frac{\log(r)}{r}\right)\]
\end{theorem}

For a specific choice of colours, the following result is given by Kumar and Melby~\cite{KumarMelbyTVadditivity}; compare also to \cite[Lemma~3.13]{MainPaper}.

\begin{theorem}[Lemma~3.6 of \cite{KumarMelbyTVadditivity}] \label{Thm:lowerBoundChoice}
If the sign is chosen such that $\frac{r-2\pm1}{2}$ is even, then the following holds:
\[\frac{2\pi}{r}\log\Bigg|\begin{vmatrix}
\frac{r-2\pm1}{2} & \frac{r-2\pm1}{2} & \frac{r-2\pm1}{2} \\[2pt]
\frac{r-2\pm1}{2} & \frac{r-2\pm1}{2} & \frac{r-2\pm1}{2}
\end{vmatrix}_{q=\qroot}\Bigg|=v_8+\mathcal{O}\left(\frac{\log(r)}{r}\right)\]
\end{theorem}


\begin{lemma} \label{Lem:DeltaLambdaBound}
For any fixed integers $j$ and $a$ with $0\leq j,a<r-1$,
\[|\Delta_j\lambda_{j,a}|_{q=\qroot}=\mathcal{O}\left(r\right)\]
\end{lemma}

\begin{proof}
For $q=A^2=\qroot$, by \refeqn{LambdaFormula} and \refeqn{Delta_n} we have
\[
\Delta_j\lambda_{j,a}=(-1)^{a+j} \, \frac{\sin(2(j+1)(a+1)\pi/r)}{\sin(2\pi/r)}
\]
Thus, $|\Delta_j\lambda_{j,a}|\leq|\sin(2\pi/r)|^{-1}\leq r/(2 \pi)$ for sufficiently large $r$.
\end{proof}

\begin{proposition}\label{Prop:UpperBound}
Let $L$ be an octahedral fully augmented link with $c$ crossing circles. Then
\[
\frac{2\pi}{r}\log\left|TV_r(S^3\setminus L,q)\right|\leq2(c-1)v_8+\mathcal{O}\left(\frac{\log(r)}{r}\right)
\]
\end{proposition}

\begin{proof}
Let $s$ denote the number of knot strands of $L$. 
By \refthm{TVfromColJones} and \refdef{CJP}
\[
TV_r(S^3\setminus L,q) =
2^{c+s-1} (\eta_r')^2 \sum_{1\leq\pmb{i}\leq m} |J_{L,\pmb{i}}(A)|^2 =
  2^{c+s-1}(\eta_r')^2\sum_{1\leq\pmb{i}\leq m} \left| \sum_{j_1,j_2,\dots,j_c} N_{\pmb{i},j_1,j_2,\dots,j_c} \right|^2
\]
where $N_{\pmb{i},j_1,j_2,\dots,j_c}$ is as in \refprop{ColJonesforOctFAL}.

Let $C_r$ be the number of possible colours $\pmb{i}$ such that $1\leq\pmb{i}\leq m  =(r-1)/2$. Then $C_r\leq m^{c+s}$ grows at most polynomially in $r$. The term $\eta_r' = (q-q^{-1})/\sqrt{-r}$ also grows at most polynomially in $r$.
Observe that $|J_{L,\pmb{i}}(A)|$ consists of $c$ nested sums. By admissibility, each summation variable $j_k$ is such that $0\leq j_k\leq r-2$ for $1\leq k\leq c$. Hence, $|J_{L,\pmb{i}}(A)|$ consists of at most $(r-1)^c$ terms.

Let $\pmb{I}_r$ denote the index realising $\max_{1\leq\pmb{i}\leq m}|J_{L,\pmb{i}}(A)|$, so $|J_{L,\pmb{I}_r}(A)|$ is this maximum value. 
Let $J = \{j_1, \dots, j_n\}$ be the choice of summation variables that realise the maximum of $|N_{\pmb{I}_r,j_1, \dots, j_n}|$. So $|N_{\pmb{I}_r,J}|$ is this maximum. 
Then we obtain the following bounds.
\[
\frac{2\pi}{r}\log\left|TV_r(S^3\setminus L,q)\right| \leq \frac{2\pi}{r}\log|J_{L,\pmb{I}_r}(A)|^2 + \mathcal{O}\left( \frac{\log(r)}{r}\right) \leq \frac{2\pi}{r} \cdot 2\log|N_{\pmb{I}_r,J}|+\mathcal{O}\left(\frac{\log(r)}{r}\right)
\]

Now, $N_{\pmb{I}_r, J}$ is a product of terms including $c-1$ quantum $6j$-symbols.
Thus applying \reflem{DeltaLambdaBound} and \refthm{6jBound} we obtain 
\[
\frac{2\pi}{r}\cdot 2\log|N_{\pmb{I}_r,J}|
\leq 2(c-1)v_8 + \mathcal{O}\left(\frac{\log(r)}{r}\right)  \qedhere\]
\end{proof}


\begin{lemma}\label{Lem:LowerBound}
Let $L$ be an octahedral fully augmented link with $c$ crossing circles, and assume that $L$ has no half-twists. Then for odd $r$, 
\[ \lim_{r\to\infty}\frac{2\pi}{r}\log\left|TV_r(S^3\setminus L,q)\right| \geq  2(c-1)v_8\]
\end{lemma}

\begin{proof}
Let $s$ denote the number of knot strands of $L$, so its total number of components is $c+s$. Consider the colouring $\pmb{n}_r=(n_r,\dots,n_r)$. Using \refthm{TVfromColJones} and the fact that $\eta_r'$ grows at most polynomially in $r$, 
\begin{align*}
  \lim_{r\to\infty}\frac{2\pi}{r}\log\left|TV_r(S^3\setminus L,q)\right| &\ge \lim_{r\to\infty}\frac{2\pi}{r}\log|2^{c+s-1}(\eta_r')^2J_{L,\pmb{n}_r}(A)|^2 \\
& = 2\lim_{r\to\infty}\frac{2\pi}{r}\log|J_{L,\pmb{n}_r}(A)| = 2\lim_{r\to\infty}\frac{2\pi}{r}\log\left|\sum_{j_1,\dots,j_c}N_{\pmb{n}_r,j_1,\dots,j_c}\right|
\end{align*}

Since $L$ has no half-twists, by \refcor{SignofN}, all summands in $|J_{L,\pmb{n}_r}(A)|$ have the same sign, so we can bound the sum below by an individual summand. In particular, we can bound $\left| \sum_{j_1, \dots, j_c} N_{\pmb{n}_r,j_1, \dots, j_c} \right|$
from below by the term $|N_{\pmb{n}_r, n_r, \dots, n_r}|$. That is, take the term with $j_1 = j_2 = \dots = j_c = n_r$, noting that this is one of the terms in the sum, since the sum runs over all $j_k$ with $(n_r, n_r, j_k)$ admissible and $0 \leq j_k \leq r-3$, for $1 \leq k \leq c$. The triple $(n_r,n_r,n_r)$ is such an admissible triple. Hence,
\[
\lim_{r\to\infty}\frac{2\pi}{r}\log\left|TV_r(S^3\setminus L,q)\right| \geq \lim_{r\to\infty}\frac{2\pi}{r}\log|N_{\pmb{n}_r,n_r,\dots,n_r}| = 2(c-1)v_8
\]
where the final equality follows from \reflem{DeltaLambdaBound} and \refthm{lowerBoundChoice}.
\end{proof}


We are now ready to conclude our new proof of the TV volume conjecture for octahedral fully augmented links, a result which is originally due to \cite{WongYang,MainPaper}. 

\begin{theorem} \label{Thm:TVconjforOctFAL}
Let $L$ be an octahedral fully augmented link with $c$ crossing circles and no half-twists. Then for odd $r$,
\begin{equation}\label{Eqn:TVConj}
\lim_{r \to \infty}\frac{2\pi}{r}\log|TV_r(S^3\setminus L,q=\qroot)| = \vol(S^3\setminus L)
\end{equation}
\end{theorem}

\begin{proof}
By \refprop{UpperBound}, the limit on the left hand side of \refeqn{TVConj} is bounded above by $2(c-1)v_8$. 

By \reflem{LowerBound}, the left hand side of \refeqn{TVConj} is also bounded below by $2(c-1)v_8$.

Thus the limit equals $2(c-1)v_8$, which is the volume of $S^3\setminus L$ by \refprop{octaLinksCharac}.
\end{proof}

In \cite{DKYRTTV}, Detcherry, Kalfagianni, and Yang proposed a question about the asymptotic behaviour of the coloured Jones polynomial. They asked whether $J_{L, m}(t)$ for $q^2= t = e^{(2 \pi i)/(m+ \frac{1}{2})}$ grows exponentially in $m$ with growth rate equal to the hyperbolic volume. We answer their question in the positive for flat fully augmented links when $m$ varies over the even integers.  

\begin{theorem}\label{Thm:coloredJonesQuestion}
Let $L$ be an octahedral fully augmented link with $c$ crossing circles and no half-twists. Then as $m$ varies over th even integers, 
\[
\lim_{m \to \infty} \frac{4 \pi}{2m+1} \log \left|J_{L, (m,m\dots,m)} \left(t=e^{\frac{4 \pi \sqrt{-1}}{2m+1}} \right) \right|=2(c-1)v_8 = \vol(S^3 \backslash L),
\]
\end{theorem}

\begin{proof}
Let  $r = 2m+1$ and $n_r = (r-1)/2$. Then as $m$ varies over the even integers
\begin{align*} 
\lim_{m \to \infty} \frac{4 \pi}{2m+1} \log 
\left|J_{L, (m,\dots,m)} \left(t=e^{\frac{4 \pi \sqrt{-1}}{2m+1}} \right) \right| &= 2 \lim_{r \to \infty } \frac{2 \pi}{r} \log \left|J_{L, \pmb{n}_r} \left(q=e^{\frac{2 \pi \sqrt{-1}}{r}} \right) \right| \\
&= 2\lim_{r \to \infty}\frac{2\pi}{r}\log\left|\sum_{j_1,j_2,\dots,j_c}N_{\pmb{n}_r,j_1,j_2,\dots,j_c}\right|
\end{align*}
as $r$ varies over the odd integers.
The result follows as in the proof of \reflem{LowerBound}.
\end{proof}

\begin{remark}
We believe that \refthm{coloredJonesQuestion} can be extended to all $m$ by minor modifications to \reflem{DeltaLambdaSigns} and \reflem{6jSign}, and by using Theorem~A.1 of \cite{MainPaper} to show that
\[ \lim_{r \to \infty} \frac{2 \pi}{r} \log \begin{vmatrix}
\frac{r - 1}{2} & \frac{r - 1}{2} & \frac{r-2\pm 1}{2} \\
\frac{r - 1}{2} & \frac{r - 1}{2} & \frac{r-2\pm 1}{2}
\end{vmatrix} = v_8.\]
\end{remark}

We now give a brief discussion of the issues which we encounter when we attempt to extend \refthm{TVconjforOctFAL} to octahedral fully augmented links with half-twists. First note the following lemma.

\begin{lemma} \label{Lem:gammaBound}
For a $r$-admissible triple $(a,b,c)$,
    \[\lim_{r\to\infty}\frac{2\pi}{r}\log(|\gamma_c^{ab}|\Big|_{q=\qroot})=0.\]
\end{lemma}

\begin{proof} 
    The formula for $\gamma_c^{ab}$ is given in \reflem{removeHalfTwist}. But $A\in\CC$ with $|A|=1$, so it follows that $|\gamma_c^{ab}|=1$.  
\end{proof}



By applying \reflem{gammaBound}, we can prove an upper bound of $2(n-1)v_8$ for octahedral fully augmented links with $c$ crossing circles and allowing for half-twists, as in \refthm{TVconjforOctFAL}. The difficulty is in proving the lower bound. By \refprop{ColJonesforOctFAL}, each half-twist contributes a term $\gamma^{i,k}_j$, where $i,k$ are colours of knot strands and $j$ is a summation variable. For the colouring $\pmb{n}_{r}$, we have $j\in\{0,2,4,\dots,r-3\}$, so $\gamma^{n_r,n_r}_j$ changes sign. Hence, the product of all $\gamma^{n_r,n_r}_j$'s from the half-twists changes sign depending on the summation variables. Moreover, $\gamma^{i,k}_j$ can be complex valued. It is not clear to us how to show that the term $N_{\pmb{n}_r,n_r,\dots,n_r}$ does not cancel with other terms, or to show that this term is a lower bound of the sum in \refeqn{colJonesFormula}. One may, however, be able to use methods from analysis as in \cite{Ohtsuki52knot} to prove a lower bound.

Note that such issues of sign do not arise in Belletti, Detcherry, Kalfagianni and Yang's proof~\cite{MainPaper} of \refconj{TVconj} for fundamental shadow links, as they extend a result of~\cite{DKYRTTV} to prove a result relating the Turaev--Viro invariants to relative Reshetikhin-Turaev invariants \cite{BHMVtqft, LickorishSkein}. The difference in the way these invariants are computed as opposed to the coloured Jones polynomials means that the only contributions from half-twists are products of the modulus $|\gamma^{i,k}_j|$. Since $|\gamma^{i,k}_j|=1$, these contributions do not need to be considered.




\bibliographystyle{amsplain}
\bibliography{ref1}

\end{document}

